/**
 * SetupGuideButton — header bar button that opens the setup guide drawer.
 * Shows remaining task count badge. Pulses for new users (first 3 days).
 */

import { useState, useEffect, useCallback } from 'react';
import { CheckSquare } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { cn } from '@/utils/cn';
import { SetupGuideDrawer } from './SetupGuideDrawer';
import { SETUP_CATEGORIES, TOTAL_TASK_COUNT } from './setupGuideConfig';

// ─── Preference key constants ─────────────────────────────────────────────────

const PREF_MANUAL_KEY = 'setup-guide-manual-done';
const PREF_CREATED_AT_KEY = 'setup-guide-first-seen';
const NEW_USER_PULSE_DAYS = 3;

// ─── Types ────────────────────────────────────────────────────────────────────

interface SetupGuideApiResponse {
  completedTasks: string[];
}

interface PreferencesApiResponse {
  [key: string]: string;
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseManualDone(raw: string | undefined): Set<string> {
  if (!raw) return new Set();
  try {
    const parsed: unknown = JSON.parse(raw);
    if (Array.isArray(parsed)) return new Set(parsed as string[]);
  } catch {
    // malformed — ignore
  }
  return new Set();
}

function isNewUser(firstSeenRaw: string | undefined): boolean {
  if (!firstSeenRaw) return true;
  const firstSeen = new Date(firstSeenRaw);
  if (isNaN(firstSeen.getTime())) return true;
  const daysSince = (Date.now() - firstSeen.getTime()) / (1000 * 60 * 60 * 24);
  return daysSince <= NEW_USER_PULSE_DAYS;
}

// ─── Component ────────────────────────────────────────────────────────────────

export function SetupGuideButton() {
  const [drawerOpen, setDrawerOpen] = useState(false);
  const [autoCompleted, setAutoCompleted] = useState<Set<string>>(new Set());
  const [manualDone, setManualDone] = useState<Set<string>>(new Set());
  const [pulse, setPulse] = useState(false);
  const [loaded, setLoaded] = useState(false);

  // Load both auto-detected status and manual completions
  useEffect(() => {
    let cancelled = false;

    async function load() {
      try {
        const [guideRes, prefRes] = await Promise.all([
          apiFetch('/api/accounting/setup-guide'),
          apiFetch('/api/auth/preferences'),
        ]);

        if (cancelled) return;

        if (guideRes.ok) {
          const guideJson = (await guideRes.json()) as { data: SetupGuideApiResponse };
          setAutoCompleted(new Set(guideJson.data.completedTasks));
        }

        if (prefRes.ok) {
          const prefJson = (await prefRes.json()) as { data: PreferencesApiResponse };
          const prefs = prefJson.data;
          setManualDone(parseManualDone(prefs[PREF_MANUAL_KEY]));
          setPulse(isNewUser(prefs[PREF_CREATED_AT_KEY]));

          // Record first-seen timestamp if not already set
          if (!prefs[PREF_CREATED_AT_KEY]) {
            void apiFetch('/api/auth/preferences', {
              method: 'PUT',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                preferences: { [PREF_CREATED_AT_KEY]: new Date().toISOString() },
              }),
            });
          }
        }
      } catch {
        // Non-critical — guide still works without auto-detection
      } finally {
        if (!cancelled) setLoaded(true);
      }
    }

    void load();
    return () => { cancelled = true; };
  }, []);

  const completedTasks = new Set([...autoCompleted, ...manualDone]);
  const remainingCount = TOTAL_TASK_COUNT - completedTasks.size;

  const handleMarkDone = useCallback((taskId: string) => {
    setManualDone(prev => {
      const next = new Set(prev);
      next.add(taskId);

      // Persist to preferences
      const allManual = [...autoCompleted].filter(id => {
        // Only store manually-marked ones not auto-detected
        const cat = SETUP_CATEGORIES.find(c => c.tasks.some(t => t.id === id));
        const task = cat?.tasks.find(t => t.id === id);
        return !task?.autoDetectKey;
      });
      const toStore = [...next];

      void apiFetch('/api/auth/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          preferences: { [PREF_MANUAL_KEY]: JSON.stringify(toStore) },
        }),
      });

      return next;
    });
  }, [autoCompleted]);

  if (!loaded) return null;

  return (
    <>
      <button
        onClick={() => setDrawerOpen(true)}
        className={cn(
          'relative p-2 rounded-lg transition-colors',
          'text-gray-400 hover:text-gray-900 dark:hover:text-white',
          'hover:bg-gray-100 dark:hover:bg-gray-700/50',
          pulse && remainingCount > 0 && 'animate-pulse',
        )}
        title="Setup guide"
        aria-label={`Setup guide — ${remainingCount} tasks remaining`}
      >
        <CheckSquare className="w-4 h-4" />

        {/* Remaining count badge */}
        {remainingCount > 0 && (
          <span
            aria-hidden="true"
            className={cn(
              'absolute -top-0.5 -right-0.5',
              'min-w-[16px] h-4 px-1',
              'bg-teal-500 text-white text-[10px] font-bold rounded-full',
              'flex items-center justify-center leading-none',
            )}
          >
            {remainingCount > 99 ? '99+' : remainingCount}
          </span>
        )}
      </button>

      <SetupGuideDrawer
        open={drawerOpen}
        onClose={() => setDrawerOpen(false)}
        completedTasks={completedTasks}
        onMarkDone={handleMarkDone}
      />
    </>
  );
}

/**
 * GET /api/accounting/setup-guide
 * Returns auto-detected completed task IDs based on company data.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

interface CompanyRow {
  logo_data: string | null;
  registration_number: string | null;
  vat_number: string | null;
}

interface CountRow {
  count: string;
}

interface FiscalRow {
  count: string;
}

interface OpeningRow {
  count: string;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const [
      companyRows,
      bankAccountRows,
      bankTxRows,
      invoiceRows,
      customerRows,
      supplierRows,
      fiscalRows,
      openingRows,
    ] = await Promise.all([
      sql`
        SELECT logo_data, registration_number, vat_number
        FROM companies
        WHERE id = ${companyId}
        LIMIT 1
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM bank_accounts
        WHERE company_id = ${companyId}
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM bank_transactions
        WHERE company_id = ${companyId}
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM customers
        WHERE company_id = ${companyId}
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM suppliers
        WHERE company_id = ${companyId}
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM fiscal_periods
        WHERE company_id = ${companyId}
      `,
      sql`
        SELECT COUNT(*) AS count
        FROM gl_journal_entries
        WHERE company_id = ${companyId}
          AND source = 'opening_balance'
      `,
    ]);

    const company = (companyRows as CompanyRow[])[0];
    const bankAccountCount = Number((bankAccountRows as CountRow[])[0]?.count ?? 0);
    const bankTxCount = Number((bankTxRows as CountRow[])[0]?.count ?? 0);
    const invoiceCount = Number((invoiceRows as CountRow[])[0]?.count ?? 0);
    const customerCount = Number((customerRows as CountRow[])[0]?.count ?? 0);
    const supplierCount = Number((supplierRows as CountRow[])[0]?.count ?? 0);
    const fiscalCount = Number((fiscalRows as FiscalRow[])[0]?.count ?? 0);
    const openingCount = Number((openingRows as OpeningRow[])[0]?.count ?? 0);

    const completedTasks: string[] = [];

    if (company?.logo_data) completedTasks.push('company-logo');
    if (company?.registration_number) completedTasks.push('company-legal');
    if (company?.vat_number) completedTasks.push('vat-number');
    if (fiscalCount > 0) completedTasks.push('fiscal-year');
    if (openingCount > 0) completedTasks.push('opening-balances');
    if (bankAccountCount > 0) completedTasks.push('bank-account');
    if (bankTxCount > 0) completedTasks.push('bank-transactions');
    if (invoiceCount > 0) completedTasks.push('customer-invoices');
    if (customerCount > 0) completedTasks.push('customers');
    if (supplierCount > 0) completedTasks.push('suppliers');

    log.info('Setup guide status fetched', { companyId, completed: completedTasks.length }, 'setup-guide');

    return apiResponse.success(res, { completedTasks });
  } catch (err) {
    log.error('Failed to fetch setup guide status', { error: err }, 'setup-guide');
    return apiResponse.badRequest(res, 'Failed to fetch setup guide status');
  }
}

