/**
 * VatSummaryWidget — Current VAT period status.
 * Uses /api/accounting/reports-vat-return for the current month period.
 * // WORKING: Shows output VAT, input VAT, net payable.
 */

import { useEffect, useState } from 'react';
import { Percent, Calendar } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface VatData {
  outputVat: number;
  inputVat: number;
  netVat: number;
  periodStart: string;
  periodEnd: string;
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

function fmtDate(s: string): string {
  return new Date(s).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
}

function currentPeriod(): { start: string; end: string } {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth() + 1;
  const start = `${y}-${String(m).padStart(2, '0')}-01`;
  const lastDay = new Date(y, m, 0).getDate();
  const end = `${y}-${String(m).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
  return { start, end };
}

export function VatSummaryWidget() {
  const [data, setData] = useState<VatData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      const { start, end } = currentPeriod();
      try {
        const res = await apiFetch(
          `/api/accounting/reports-vat-return?period_start=${start}&period_end=${end}`
        );
        const json = (await res.json()) as { data?: {
          output_vat?: number; outputVat?: number;
          input_vat?: number; inputVat?: number;
          net_vat?: number; netVat?: number;
        } };
        const d = json.data ?? {};
        setData({
          outputVat: d.output_vat ?? d.outputVat ?? 0,
          inputVat: d.input_vat ?? d.inputVat ?? 0,
          netVat: d.net_vat ?? d.netVat ?? 0,
          periodStart: start,
          periodEnd: end,
        });
      } catch (err) {
        log.error('VatSummaryWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load VAT data');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const isPayable = (data?.netVat ?? 0) > 0;

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
          <Percent className="h-4 w-4 text-teal-500" />
          <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">VAT Summary</span>
        </div>
      }
    >
      {loading ? (
        <div className="space-y-3">
          <Skeleton variant="text" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
        <p className="text-sm text-red-500">{error}</p>
      ) : data ? (
        <div className="space-y-4">
          {/* Period */}
          <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400">
            <Calendar className="h-3.5 w-3.5" />
            {fmtDate(data.periodStart)} &ndash; {fmtDate(data.periodEnd)}
          </div>
          {/* Breakdown */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Output VAT (collected)</span>
              <span className="text-xs font-medium text-gray-900 dark:text-gray-100">
                {fmtCurrency(data.outputVat)}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Input VAT (claimable)</span>
              <span className="text-xs font-medium text-green-600 dark:text-green-400">
                {fmtCurrency(data.inputVat)}
              </span>
            </div>
            <div className="h-px bg-gray-200 dark:bg-gray-700" />
            <div className="flex justify-between">
              <span className="text-xs font-semibold text-gray-900 dark:text-gray-100">
                {isPayable ? 'Net VAT Payable' : 'VAT Refund Due'}
              </span>
              <span className={`text-xs font-bold ${isPayable ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
                {fmtCurrency(Math.abs(data.netVat))}
              </span>
            </div>
          </div>
        </div>
      ) : null}
    </Card>
  );
}

/**
 * Widget Layout API
 * GET  /api/accounting/widget-layout  — Returns saved widget layout (or adaptive default)
 * POST /api/accounting/widget-layout  — Saves widget layout to user_preferences
 */

import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { WidgetConfig } from '@/components/dashboard/widgetTypes';
import { DEFAULT_WIDGET_LAYOUT } from '@/components/dashboard/widgetTypes';

const PREF_KEY = 'dashboard_widget_layout';

async function buildAdaptiveDefault(companyId: string): Promise<WidgetConfig[]> {
  const layout: WidgetConfig[] = [
    { id: 'quick-actions-1', type: 'quick-actions', title: 'Quick Actions', size: 'md' },
  ];

  const [bankRows, invoiceRows, supplierRows] = await Promise.all([
    sql`SELECT id FROM gl_accounts WHERE company_id = ${companyId} AND account_subtype = 'bank' AND is_active = true LIMIT 1`,
    sql`SELECT id FROM customer_invoices WHERE company_id = ${companyId} LIMIT 1`,
    sql`SELECT id FROM supplier_invoices WHERE company_id = ${companyId} LIMIT 1`,
  ]);

  if ((bankRows as unknown[]).length > 0) {
    layout.push({ id: 'bank-summary-1', type: 'bank-summary', title: 'Bank Accounts', size: 'md' });
  }
  if ((invoiceRows as unknown[]).length > 0) {
    layout.push({ id: 'invoices-owed-1', type: 'invoices-owed', title: 'Invoices Owed', size: 'sm' });
  }
  if ((supplierRows as unknown[]).length > 0) {
    layout.push({ id: 'bills-to-pay-1', type: 'bills-to-pay', title: 'Bills to Pay', size: 'sm' });
  }

  layout.push(
    { id: 'pnl-snapshot-1', type: 'pnl-snapshot', title: 'P&L Snapshot', size: 'md' },
    { id: 'recent-activity-1', type: 'recent-activity', title: 'Recent Activity', size: 'sm' },
  );

  return layout;
}

async function handler(req: CompanyApiRequest, res: NextApiResponse) {
  const { companyId } = req;
  const userId = req.user.id;

  // ── GET ──────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    try {
      const rows = await sql`
        SELECT value FROM user_preferences
        WHERE user_id = ${userId} AND key = ${PREF_KEY}
        LIMIT 1
      `;

      const existing = (rows as { value: string }[]);
      const firstRow = existing[0];
      if (firstRow?.value) {
        const saved = JSON.parse(firstRow.value) as WidgetConfig[];
        return apiResponse.success(res, { layout: saved, isDefault: false });
      }

      // Build adaptive default based on company data
      const layout = await buildAdaptiveDefault(companyId);
      return apiResponse.success(res, { layout, isDefault: true });
    } catch (err) {
      log.error('Failed to load widget layout', { error: err, companyId }, 'widget-layout');
      // Fall back to static default on error
      return apiResponse.success(res, { layout: DEFAULT_WIDGET_LAYOUT, isDefault: true });
    }
  }

  // ── POST ─────────────────────────────────────────────────────────────────
  if (req.method === 'POST') {
    try {
      const body = req.body as { layout?: unknown };
      if (!body.layout || !Array.isArray(body.layout)) {
        return apiResponse.badRequest(res, 'layout array is required');
      }

      const layout = body.layout as WidgetConfig[];
      const value = JSON.stringify(layout);

      await sql`
        INSERT INTO user_preferences (user_id, key, value, updated_at)
        VALUES (${userId}, ${PREF_KEY}, ${value}, NOW())
        ON CONFLICT (user_id, key)
        DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
      `;

      log.info('Widget layout saved', { userId, widgetCount: layout.length }, 'widget-layout');
      return apiResponse.success(res, { saved: true, widgetCount: layout.length });
    } catch (err) {
      log.error('Failed to save widget layout', { error: err, companyId }, 'widget-layout');
      return apiResponse.badRequest(res, 'Failed to save widget layout');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET', 'POST']);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler as any));

/**
 * CreateNewMenu — Quick-create "+" button for the app header.
 *
 * Opens a dropdown of common create actions. Supports:
 *   - "N" key to open the menu (when not in a text field)
 *   - Letter keys to jump to items when the menu is open
 *   - Arrow keys for navigation, Enter to activate, Escape to close
 *   - Click-outside to close
 *   - Portal rendering to avoid z-index clipping
 */

import {
  useState,
  useEffect,
  useRef,
  useCallback,
  KeyboardEvent as ReactKeyboardEvent,
} from 'react';
import { createPortal } from 'react-dom';
import { useRouter } from 'next/router';
import {
  Plus,
  FileText,
  Receipt,
  FileCheck,
  CreditCard,
  BookOpen,
  UserPlus,
  ArrowLeftRight,
  LucideIcon,
} from 'lucide-react';
import { Tooltip } from '@/components/ui/Tooltip';
import { cn } from '@/utils/cn';

// ─── Menu item definition ────────────────────────────────────────────────────

interface MenuItem {
  label: string;
  icon: LucideIcon;
  route: string;
  /** Single uppercase letter shown as shortcut hint when menu is open. */
  shortcutLetter: string;
}

const MENU_ITEMS: MenuItem[] = [
  { label: 'New Invoice',       icon: FileText,        route: '/accounting/customer-invoices?action=new', shortcutLetter: 'I' },
  { label: 'New Bill',          icon: Receipt,         route: '/accounting/supplier-invoices?action=new', shortcutLetter: 'B' },
  { label: 'New Quote',         icon: FileCheck,       route: '/accounting/customer-quotes?action=new',   shortcutLetter: 'Q' },
  { label: 'Record Payment',    icon: CreditCard,      route: '/accounting/customer-payments/new',        shortcutLetter: 'P' },
  { label: 'New Journal Entry', icon: BookOpen,        route: '/accounting/journal-entries/new',          shortcutLetter: 'J' },
  { label: 'New Contact',       icon: UserPlus,        route: '/accounting/customers/new',                shortcutLetter: 'C' },
  { label: 'Bank Transfer',     icon: ArrowLeftRight,  route: '/accounting/bank-transfers?action=new',    shortcutLetter: 'T' },
];

// Map shortcut letter → index for quick lookup
const LETTER_MAP: Record<string, number> = Object.fromEntries(
  MENU_ITEMS.map((item, i) => [item.shortcutLetter.toLowerCase(), i])
);

// ─── Helpers ─────────────────────────────────────────────────────────────────

function isTextTarget(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  const tag = target.tagName.toLowerCase();
  if (tag === 'input' || tag === 'textarea' || tag === 'select') return true;
  if (target.isContentEditable) return true;
  return false;
}

// ─── Dropdown portal ─────────────────────────────────────────────────────────

interface DropdownProps {
  anchorRect: DOMRect;
  focusedIndex: number;
  onSelect: (route: string) => void;
  onFocusChange: (index: number) => void;
}

function Dropdown({ anchorRect, focusedIndex, onSelect, onFocusChange }: DropdownProps) {
  const itemRefs = useRef<(HTMLButtonElement | null)[]>([]);

  useEffect(() => {
    itemRefs.current[focusedIndex]?.focus();
  }, [focusedIndex]);

  const top = anchorRect.bottom + window.scrollY + 8;
  const left = anchorRect.right + window.scrollX;

  return createPortal(
    <div
      role="menu"
      aria-label="Create new"
      style={{ position: 'absolute', top, left, transform: 'translateX(-100%)' }}
      className={cn(
        'z-[9999] w-64 py-1.5 rounded-xl',
        'bg-white dark:bg-gray-900',
        'border border-gray-200 dark:border-gray-700',
        'shadow-xl shadow-black/10 dark:shadow-black/40',
      )}
    >
      <p className="px-3 pb-1 pt-0.5 text-[10px] font-semibold uppercase tracking-wider text-gray-400 dark:text-gray-500 select-none">
        Create New
      </p>
      {MENU_ITEMS.map((item, i) => {
        const Icon = item.icon;
        const isFocused = focusedIndex === i;
        return (
          <button
            key={item.route}
            ref={el => { itemRefs.current[i] = el; }}
            role="menuitem"
            tabIndex={isFocused ? 0 : -1}
            onClick={() => onSelect(item.route)}
            onMouseEnter={() => onFocusChange(i)}
            onFocus={() => onFocusChange(i)}
            className={cn(
              'w-full flex items-center gap-3 px-3 py-2 text-sm transition-colors',
              'text-gray-700 dark:text-gray-200',
              isFocused
                ? 'bg-teal-50 dark:bg-teal-900/30 text-teal-700 dark:text-teal-300'
                : 'hover:bg-gray-50 dark:hover:bg-gray-800',
            )}
          >
            <Icon className="w-4 h-4 flex-shrink-0 text-gray-400 dark:text-gray-500" />
            <span className="flex-1 text-left">{item.label}</span>
            <span className="text-[10px] text-gray-400 dark:text-gray-500 font-mono tabular-nums">
              N {item.shortcutLetter}
            </span>
          </button>
        );
      })}
    </div>,
    document.body
  );
}

// ─── Main component ──────────────────────────────────────────────────────────

export function CreateNewMenu() {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [focusedIndex, setFocusedIndex] = useState(0);
  const [anchorRect, setAnchorRect] = useState<DOMRect | null>(null);
  const buttonRef = useRef<HTMLButtonElement>(null);

  const openMenu = useCallback(() => {
    if (buttonRef.current) {
      setAnchorRect(buttonRef.current.getBoundingClientRect());
    }
    setFocusedIndex(0);
    setOpen(true);
  }, []);

  const closeMenu = useCallback(() => {
    setOpen(false);
    buttonRef.current?.focus();
  }, []);

  const navigate = useCallback((route: string) => {
    setOpen(false);
    void router.push(route);
  }, [router]);

  // Global "N" key opens the menu
  useEffect(() => {
    const handler = (e: globalThis.KeyboardEvent) => {
      if (isTextTarget(e.target)) return;
      if (e.ctrlKey || e.metaKey || e.altKey) return;

      if (!open && e.key.toLowerCase() === 'n') {
        e.preventDefault();
        openMenu();
        return;
      }

      if (open) {
        if (e.key === 'Escape') {
          e.preventDefault();
          closeMenu();
          return;
        }
        if (e.key === 'ArrowDown') {
          e.preventDefault();
          setFocusedIndex(i => (i + 1) % MENU_ITEMS.length);
          return;
        }
        if (e.key === 'ArrowUp') {
          e.preventDefault();
          setFocusedIndex(i => (i - 1 + MENU_ITEMS.length) % MENU_ITEMS.length);
          return;
        }
        if (e.key === 'Enter') {
          e.preventDefault();
          const focused = MENU_ITEMS[focusedIndex];
          if (focused) navigate(focused.route);
          return;
        }
        // Letter shortcut
        const idx = LETTER_MAP[e.key.toLowerCase()];
        if (idx !== undefined) {
          e.preventDefault();
          const target = MENU_ITEMS[idx];
          if (target) navigate(target.route);
        }
      }
    };

    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open, focusedIndex, openMenu, closeMenu, navigate]);

  // Click outside to close
  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (buttonRef.current?.contains(e.target as Node)) return;
      setOpen(false);
    };
    // Delay one tick so the button click that opened the menu doesn't immediately close it
    const id = setTimeout(() => document.addEventListener('mousedown', handler), 0);
    return () => {
      clearTimeout(id);
      document.removeEventListener('mousedown', handler);
    };
  }, [open]);

  // Recalculate anchor on scroll/resize while open
  useEffect(() => {
    if (!open) return;
    const update = () => {
      if (buttonRef.current) setAnchorRect(buttonRef.current.getBoundingClientRect());
    };
    window.addEventListener('resize', update, { passive: true });
    window.addEventListener('scroll', update, { passive: true, capture: true });
    return () => {
      window.removeEventListener('resize', update);
      window.removeEventListener('scroll', update, { capture: true });
    };
  }, [open]);

  const handleButtonKeyDown = (e: ReactKeyboardEvent<HTMLButtonElement>) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      open ? closeMenu() : openMenu();
    }
    if (e.key === 'Escape' && open) {
      e.preventDefault();
      closeMenu();
    }
  };

  return (
    <>
      <Tooltip content="Create new (N)" position="bottom">
        <button
          ref={buttonRef}
          aria-haspopup="menu"
          aria-expanded={open}
          aria-label="Create new"
          onClick={() => open ? closeMenu() : openMenu()}
          onKeyDown={handleButtonKeyDown}
          className={cn(
            'w-8 h-8 rounded-full flex items-center justify-center flex-shrink-0 transition-colors',
            open
              ? 'bg-teal-700 text-white'
              : 'bg-teal-600 hover:bg-teal-700 text-white',
          )}
        >
          <Plus className="w-4 h-4" />
        </button>
      </Tooltip>

      {open && anchorRect && (
        <Dropdown
          anchorRect={anchorRect}
          focusedIndex={focusedIndex}
          onSelect={navigate}
          onFocusChange={setFocusedIndex}
        />
      )}
    </>
  );
}

