export function getActiveTabId(
  pathname: string,
  query: Record<string, string | string[] | undefined>,
): string {
  if (pathname === '/accounting') return 'dashboard';
  if (pathname.startsWith('/accounting/migration')) return 'import';
  if (pathname.startsWith('/accounting/sage-migration')) return 'import';

  // Customers
  if (
    pathname.startsWith('/accounting/customers') ||
    pathname.startsWith('/accounting/customer-') ||
    pathname.startsWith('/accounting/recurring-invoices') ||
    pathname.startsWith('/accounting/credit-notes') ||
    pathname.startsWith('/accounting/write-offs') ||
    pathname.startsWith('/accounting/debtors-manager') ||
    pathname.startsWith('/accounting/ar-aging') ||
    pathname.startsWith('/accounting/statement-run') ||
    pathname.startsWith('/accounting/dunning') ||
    pathname === '/accounting/reports/sales-by-customer' ||
    pathname === '/accounting/reports/unallocated-receipts' ||
    (pathname.startsWith('/accounting/adjustments') && query.type === 'customer')
  ) {
    return 'customers';
  }

  // Suppliers
  if (
    pathname.startsWith('/accounting/suppliers') ||
    pathname.startsWith('/accounting/supplier-') ||
    pathname.startsWith('/accounting/purchase-orders') ||
    pathname.startsWith('/accounting/batch-payments') ||
    pathname.startsWith('/accounting/ap-aging') ||
    pathname === '/accounting/reports/purchases-by-supplier' ||
    pathname === '/accounting/reports/unallocated-payments' ||
    (pathname.startsWith('/accounting/adjustments') && query.type === 'supplier')
  ) {
    return 'suppliers';
  }

  // Items
  if (
    pathname.startsWith('/accounting/items') ||
    pathname.startsWith('/accounting/item-') ||
    pathname === '/accounting/reports/item-listing' ||
    pathname === '/accounting/reports/sales-by-item' ||
    pathname === '/accounting/reports/purchases-by-item' ||
    pathname === '/accounting/reports/item-movement' ||
    pathname === '/accounting/reports/item-valuation' ||
    pathname === '/accounting/reports/item-quantities'
  ) {
    return 'items';
  }

  // Banking
  if (pathname.startsWith('/accounting/bank-')) return 'banking';

  // Accounts
  if (
    pathname.startsWith('/accounting/chart-of-accounts') ||
    pathname.startsWith('/accounting/journal-entries') ||
    pathname.startsWith('/accounting/recurring-journals') ||
    pathname.startsWith('/accounting/fiscal-periods') ||
    pathname.startsWith('/accounting/default-accounts') ||
    pathname.startsWith('/accounting/currencies') ||
    pathname.startsWith('/accounting/exchange-rates')
  ) {
    return 'accounts';
  }

  // VAT
  if (
    pathname.startsWith('/accounting/vat-') ||
    pathname.startsWith('/accounting/drc-vat') ||
    pathname === '/accounting/reports/vat-return'
  ) {
    return 'vat';
  }

  // Accountant's Area
  if (
    pathname.startsWith('/accounting/trial-balance') ||
    pathname.startsWith('/accounting/opening-balances') ||
    pathname.startsWith('/accounting/assets') ||
    pathname.startsWith('/accounting/depreciation') ||
    pathname.startsWith('/accounting/year-end') ||
    pathname.startsWith('/accounting/cost-centres') ||
    pathname.startsWith('/accounting/business-units') ||
    pathname.startsWith('/accounting/budgets')
  ) {
    return 'accountants';
  }

  // Group
  if (pathname.startsWith('/accounting/group')) return 'group';

  // SARS
  if (pathname.startsWith('/accounting/sars')) return 'sars';

  // Tools
  if (
    pathname.startsWith('/accounting/document-capture') ||
    pathname.startsWith('/accounting/approvals') ||
    pathname.startsWith('/accounting/company-settings') ||
    pathname.startsWith('/accounting/my-account') ||
    pathname.startsWith('/accounting/cash-flow-forecast') ||
    pathname.startsWith('/accounting/time-tracking') ||
    pathname.startsWith('/accounting/user-access') ||
    pathname.startsWith('/accounting/audit-log') ||
    pathname.startsWith('/accounting/gl-import') ||
    pathname.startsWith('/accounting/duplicates') ||
    pathname.startsWith('/accounting/data-archiving') ||
    pathname.startsWith('/accounting/webhooks') ||
    pathname.startsWith('/accounting/recurring-transactions')
  ) {
    return 'tools';
  }

  if (pathname.startsWith('/accounting/reports')) return 'reports';

  // Payroll
  if (pathname.startsWith('/payroll')) return 'payroll';

  return 'dashboard';
}

export function isLinkActive(href: string, asPath: string): boolean {
  const parts = href.split('?');
  const itemPath = parts[0] as string;
  const qs = parts[1];
  return asPath.startsWith(itemPath) && (!qs || asPath.includes(qs));
}

/**
 * Button — primary interactive element with variants, sizes, icons, and loading state.
 * WORKING: CVA-based variants, Radix Slot asChild support, forward ref.
 */

import * as React from 'react';
import { Slot } from '@radix-ui/react-slot';
import { cva, type VariantProps } from 'class-variance-authority';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/utils/cn';
import { LoadingSpinner } from './LoadingSpinner';

const buttonVariants = cva(
  [
    'inline-flex items-center justify-center gap-2 rounded-md font-medium',
    'transition-colors duration-150 focus-visible:outline-none',
    'focus-visible:ring-2 focus-visible:ring-offset-2',
    'disabled:pointer-events-none disabled:opacity-50',
    'select-none whitespace-nowrap',
  ],
  {
    variants: {
      variant: {
        primary: [
          'bg-teal-600 text-white',
          'hover:bg-teal-700',
          'focus-visible:ring-teal-500',
          'dark:bg-teal-500 dark:hover:bg-teal-600',
        ],
        secondary: [
          'border border-gray-300 bg-white text-gray-700',
          'hover:bg-gray-50 hover:border-gray-400',
          'focus-visible:ring-teal-500',
          'dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200',
          'dark:hover:bg-gray-700 dark:hover:border-gray-500',
        ],
        ghost: [
          'bg-transparent text-gray-700',
          'hover:bg-gray-100 hover:text-gray-900',
          'focus-visible:ring-teal-500',
          'dark:text-gray-300 dark:hover:bg-gray-800 dark:hover:text-gray-100',
        ],
        danger: [
          'bg-red-600 text-white',
          'hover:bg-red-700',
          'focus-visible:ring-red-500',
          'dark:bg-red-700 dark:hover:bg-red-800',
        ],
      },
      size: {
        sm: 'h-8 px-3 text-xs',
        md: 'h-9 px-4 text-sm',
        lg: 'h-11 px-6 text-base',
      },
    },
    defaultVariants: {
      variant: 'primary',
      size: 'md',
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  asChild?: boolean;
  loading?: boolean;
  leftIcon?: LucideIcon;
  rightIcon?: LucideIcon;
}

// WORKING: Forward ref with asChild (Radix Slot) support
const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  (
    {
      className,
      variant,
      size,
      asChild = false,
      loading = false,
      leftIcon: LeftIcon,
      rightIcon: RightIcon,
      disabled,
      children,
      ...props
    },
    ref
  ) => {
    const Comp = asChild ? Slot : 'button';
    const isDisabled = disabled || loading;

    const spinnerSize = size === 'lg' ? 'md' : 'sm';

    return (
      <Comp
        ref={ref}
        disabled={isDisabled}
        aria-disabled={isDisabled}
        aria-busy={loading}
        className={cn(buttonVariants({ variant, size }), className)}
        {...props}
      >
        {loading ? (
          <LoadingSpinner size={spinnerSize} />
        ) : (
          LeftIcon && <LeftIcon size={size === 'lg' ? 18 : 16} />
        )}
        {children}
        {!loading && RightIcon && <RightIcon size={size === 'lg' ? 18 : 16} />}
      </Comp>
    );
  }
);

Button.displayName = 'Button';

export { Button, buttonVariants };

/**
 * Generic Sage-style horizontal navigation bar for module pages.
 * Tabs with dropdown menus; supports up to three-level flyout nesting.
 *
 * Usage:
 *   <ModuleNav tabs={TABS} getActiveTabId={getActiveTabId} accentColor="teal" />
 *
 * Accent classes are pre-written in full so Tailwind's purge pass retains them.
 */

import { useState, useRef, useEffect } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { ChevronDown, ChevronRight } from 'lucide-react';
import {
  isFlyout, isLinkActive,
  type Tab, type DropdownItem, type NavItem,
} from '../accounting/accountingNavConfig';

// 🟢 WORKING: Full class strings — never use template literals with Tailwind.
export type AccentColor = 'teal' | 'blue' | 'amber' | 'emerald' | 'violet' | 'slate' | 'rose' | 'cyan';

interface AccentTokens {
  activeBorder: string;
  activeText: string;
  activeLinkBg: string;
  activeSectionText: string;
}

export const ACCENT_CLASSES: Record<AccentColor, AccentTokens> = {
  teal: {
    activeBorder: 'border-teal-500',
    activeText: 'text-teal-400',
    activeLinkBg: 'text-teal-400 bg-teal-500/10',
    activeSectionText: 'text-teal-400',
  },
  blue: {
    activeBorder: 'border-blue-500',
    activeText: 'text-blue-400',
    activeLinkBg: 'text-blue-400 bg-blue-500/10',
    activeSectionText: 'text-blue-400',
  },
  amber: {
    activeBorder: 'border-amber-500',
    activeText: 'text-amber-400',
    activeLinkBg: 'text-amber-400 bg-amber-500/10',
    activeSectionText: 'text-amber-400',
  },
  emerald: {
    activeBorder: 'border-emerald-500',
    activeText: 'text-emerald-400',
    activeLinkBg: 'text-emerald-400 bg-emerald-500/10',
    activeSectionText: 'text-emerald-400',
  },
  violet: {
    activeBorder: 'border-violet-500',
    activeText: 'text-violet-400',
    activeLinkBg: 'text-violet-400 bg-violet-500/10',
    activeSectionText: 'text-violet-400',
  },
  slate: {
    activeBorder: 'border-slate-500',
    activeText: 'text-slate-400',
    activeLinkBg: 'text-slate-400 bg-slate-500/10',
    activeSectionText: 'text-slate-400',
  },
  rose: {
    activeBorder: 'border-rose-500',
    activeText: 'text-rose-400',
    activeLinkBg: 'text-rose-400 bg-rose-500/10',
    activeSectionText: 'text-rose-400',
  },
  cyan: {
    activeBorder: 'border-cyan-500',
    activeText: 'text-cyan-400',
    activeLinkBg: 'text-cyan-400 bg-cyan-500/10',
    activeSectionText: 'text-cyan-400',
  },
};

export interface ModuleNavProps {
  tabs?: Tab[];
  getActiveTabId: (pathname: string, query: Record<string, string | string[] | undefined>) => string;
  accentColor: AccentColor;
}

// ─── Shared static classes ────────────────────────────────────────────────────

const panelCls =
  'absolute left-full top-0 bg-gray-800 border border-gray-700 rounded-r-lg shadow-xl min-w-[210px] py-1';

const inactiveLinkCls =
  'text-gray-300 hover:text-white hover:bg-gray-700/50';

// ─── Internal helpers that need accent tokens ─────────────────────────────────

function makeLinkCls(active: boolean, accent: AccentTokens): string {
  return `block px-4 py-2 text-sm whitespace-nowrap transition-colors ${
    active ? accent.activeLinkBg : inactiveLinkCls
  }`;
}

function makeSectionCls(hovered: boolean, active: boolean, accent: AccentTokens): string {
  return `flex items-center justify-between px-4 py-2.5 text-sm cursor-default transition-colors ${
    hovered
      ? 'bg-gray-700 text-white'
      : active
        ? accent.activeSectionText
        : 'text-gray-300'
  }`;
}

// ─── Sub-components ───────────────────────────────────────────────────────────

interface SubMenuItemsProps {
  items: NavItem[];
  asPath: string;
  onClose: () => void;
  accent: AccentTokens;
}

function SubMenuItems({ items, asPath, onClose, accent }: SubMenuItemsProps) {
  const [hovered, setHovered] = useState<string | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clear = () => { if (timerRef.current) clearTimeout(timerRef.current); };
  const delayed = () => { timerRef.current = setTimeout(() => setHovered(null), 150); };
  useEffect(() => () => clear(), []);

  return (
    <>
      {items.map(item => {
        if (!isFlyout(item)) {
          return (
            <Link
              key={item.href}
              href={item.href}
              onClick={onClose}
              className={makeLinkCls(isLinkActive(item.href, asPath), accent)}
            >
              {item.label}
            </Link>
          );
        }
        const isHov = hovered === item.section;
        return (
          <div
            key={item.section}
            className="relative"
            onMouseEnter={() => { clear(); setHovered(item.section); }}
            onMouseLeave={delayed}
          >
            <div className={makeSectionCls(isHov, false, accent)}>
              <span className="font-medium">{item.section}</span>
              <ChevronRight className="h-3.5 w-3.5 ml-6 flex-shrink-0" />
            </div>
            {isHov && (
              <div onMouseEnter={clear} onMouseLeave={delayed} className={panelCls}>
                <SubMenuItems items={item.items} asPath={asPath} onClose={onClose} accent={accent} />
              </div>
            )}
          </div>
        );
      })}
    </>
  );
}

interface FlatDropdownProps {
  items: DropdownItem[];
  asPath: string;
  onClose: () => void;
  accent: AccentTokens;
}

function FlatDropdown({ items, asPath, onClose, accent }: FlatDropdownProps) {
  return (
    <div className="absolute top-full left-0 bg-gray-800 border border-gray-700 rounded-b-lg shadow-xl min-w-[220px] py-1 z-40">
      {items.map(item => (
        <Link
          key={item.href}
          href={item.href}
          onClick={onClose}
          className={makeLinkCls(isLinkActive(item.href, asPath), accent)}
        >
          {item.label}
        </Link>
      ))}
    </div>
  );
}

interface FlyoutDropdownProps {
  tab: Tab;
  asPath: string;
  onClose: () => void;
  accent: AccentTokens;
}

function FlyoutDropdown({ tab, asPath, onClose, accent }: FlyoutDropdownProps) {
  const [hoveredSection, setHoveredSection] = useState<string | null>(null);
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const clearTimer = () => { if (timeoutRef.current) clearTimeout(timeoutRef.current); };
  const delayedClose = () => { timeoutRef.current = setTimeout(() => setHoveredSection(null), 150); };
  useEffect(() => () => clearTimer(), []);

  const sections = (tab.items ?? []).filter(isFlyout);

  return (
    <div className="absolute top-full left-0 z-40">
      <div className="bg-gray-800 border border-gray-700 rounded-b-lg shadow-xl min-w-[200px] py-1">
        {tab.topItems?.map(item => (
          <Link
            key={item.href}
            href={item.href}
            onClick={onClose}
            className="block px-4 py-2 text-sm text-gray-300 hover:text-white hover:bg-gray-700/50 transition-colors"
          >
            {item.label}
          </Link>
        ))}
        {tab.topItems && tab.topItems.length > 0 && (
          <div className="border-t border-gray-700 my-1" />
        )}

        {sections.map(section => {
          const isHovered = hoveredSection === section.section;
          return (
            <div
              key={section.section}
              className="relative"
              onMouseEnter={() => { clearTimer(); setHoveredSection(section.section); }}
              onMouseLeave={delayedClose}
            >
              <div className={makeSectionCls(isHovered, false, accent)}>
                <span className="font-medium">{section.section}</span>
                <ChevronRight className="h-3.5 w-3.5 ml-6 flex-shrink-0" />
              </div>
              {isHovered && (
                <div onMouseEnter={clearTimer} onMouseLeave={delayedClose} className={panelCls}>
                  <SubMenuItems items={section.items} asPath={asPath} onClose={onClose} accent={accent} />
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Public component ─────────────────────────────────────────────────────────

/**
 * Generic Sage-style module nav bar.
 *
 * @param tabs            Array of top-level tabs (with optional nested items)
 * @param getActiveTabId  Route-to-tab resolver for the owning module
 * @param accentColor     Tailwind color token used for active-state highlights
 */
export function ModuleNav({ tabs, getActiveTabId, accentColor }: ModuleNavProps) {
  const router = useRouter();
  const [openTab, setOpenTab] = useState<string | null>(null);
  const navRef = useRef<HTMLDivElement>(null);
  const activeTab = typeof getActiveTabId === 'function'
    ? getActiveTabId(router.pathname, router.query)
    : 'dashboard';
  const accent = ACCENT_CLASSES[accentColor];

  useEffect(() => {
    const handler = (e: MouseEvent) => {
      if (navRef.current && !navRef.current.contains(e.target as Node)) setOpenTab(null);
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, []);

  useEffect(() => { setOpenTab(null); }, [router.pathname]);

  const hasFlyout = (t: Tab) => t.items?.some(isFlyout) ?? false;

  return (
    <nav ref={navRef} className="bg-gray-900 border-b border-gray-700 relative z-30">
      <div className="flex items-center gap-0 px-2">
        {(tabs ?? []).map(t => (
          <div key={t.id} className="relative" data-tour={`nav-${t.id}`}>
            {t.href ? (
              <Link
                href={t.href}
                className={`block px-4 py-2.5 text-sm font-medium whitespace-nowrap border-b-2 transition-colors ${
                  activeTab === t.id
                    ? `${accent.activeBorder} ${accent.activeText}`
                    : 'border-transparent text-gray-400 hover:text-white'
                }`}
              >
                {t.label}
              </Link>
            ) : (
              <button
                onClick={() => setOpenTab(openTab === t.id ? null : t.id)}
                className={`px-4 py-2.5 text-sm font-medium whitespace-nowrap border-b-2 transition-colors inline-flex items-center gap-1 ${
                  activeTab === t.id
                    ? `${accent.activeBorder} ${accent.activeText}`
                    : 'border-transparent text-gray-400 hover:text-white'
                }`}
              >
                {t.label}
                <ChevronDown className={`h-3 w-3 transition-transform ${openTab === t.id ? 'rotate-180' : ''}`} />
              </button>
            )}

            {t.items && openTab === t.id && (
              hasFlyout(t)
                ? <FlyoutDropdown tab={t} asPath={router.asPath} onClose={() => setOpenTab(null)} accent={accent} />
                : <FlatDropdown items={t.items as DropdownItem[]} asPath={router.asPath} onClose={() => setOpenTab(null)} accent={accent} />
            )}
          </div>
        ))}
      </div>
    </nav>
  );
}

/**
 * Tooltip — CSS-only hover tooltip with position variants.
 * WORKING: No external dependencies, delay via CSS transition, aria-label fallback.
 *
 * Usage:
 *   <Tooltip content="Export to CSV" position="top">
 *     <button>Export</button>
 *   </Tooltip>
 */

import * as React from 'react';
import { cn } from '@/utils/cn';

export type TooltipPosition = 'top' | 'bottom' | 'left' | 'right';

export interface TooltipProps {
  content: string;
  position?: TooltipPosition;
  children: React.ReactElement;
  className?: string;
}

// Positioning styles for the bubble and its arrow
const positionClasses: Record<TooltipPosition, string> = {
  top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
  bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
  left: 'right-full top-1/2 -translate-y-1/2 mr-2',
  right: 'left-full top-1/2 -translate-y-1/2 ml-2',
};

const arrowClasses: Record<TooltipPosition, string> = {
  top: 'top-full left-1/2 -translate-x-1/2 border-t-gray-800 border-x-transparent border-b-transparent dark:border-t-gray-200',
  bottom: 'bottom-full left-1/2 -translate-x-1/2 border-b-gray-800 border-x-transparent border-t-transparent dark:border-b-gray-200',
  left: 'left-full top-1/2 -translate-y-1/2 border-l-gray-800 border-y-transparent border-r-transparent dark:border-l-gray-200',
  right: 'right-full top-1/2 -translate-y-1/2 border-r-gray-800 border-y-transparent border-l-transparent dark:border-r-gray-200',
};

// WORKING: Pure CSS approach — tooltip visibility controlled by group-hover
function Tooltip({
  content,
  position = 'top',
  children,
  className,
}: TooltipProps) {
  return (
    <span className={cn('group relative inline-flex', className)}>
      {children}

      {/* Tooltip bubble — hidden by default, revealed on group hover with delay */}
      <span
        role="tooltip"
        aria-hidden="true"
        className={cn(
          'pointer-events-none absolute z-50 whitespace-nowrap rounded-md px-2 py-1',
          'text-xs font-medium text-white bg-gray-800',
          'dark:bg-gray-100 dark:text-gray-900',
          'opacity-0 transition-opacity duration-150 delay-300',
          'group-hover:opacity-100',
          positionClasses[position]
        )}
      >
        {content}
        {/* Arrow */}
        <span
          aria-hidden="true"
          className={cn(
            'absolute border-4',
            arrowClasses[position]
          )}
        />
      </span>
    </span>
  );
}

Tooltip.displayName = 'Tooltip';

export { Tooltip };

