/**
 * GET /api/auth/preferences  — returns all preferences as { key: value } map
 * PUT /api/auth/preferences  — upserts { preferences: { key: value, ... } }
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  const authReq = req as AuthenticatedNextApiRequest;
  const userId = authReq.user.id;

  // ── GET ──────────────────────────────────────────────────────────────────
  if (req.method === 'GET') {
    const rows = (await sql`
      SELECT key, value FROM user_preferences WHERE user_id = ${userId}
    `) as Row[];

    const prefs: Record<string, string> = {};
    for (const row of rows) {
      prefs[row.key as string] = row.value as string;
    }

    return apiResponse.success(res, prefs);
  }

  // ── PUT ──────────────────────────────────────────────────────────────────
  if (req.method === 'PUT') {
    const { preferences } = req.body as { preferences?: Record<string, string> };

    if (!preferences || typeof preferences !== 'object') {
      return apiResponse.badRequest(res, 'preferences object is required');
    }

    const entries = Object.entries(preferences);
    if (entries.length === 0) {
      return apiResponse.success(res, {}, 'No preferences to update');
    }

    // Upsert each preference individually using tagged sql template
    for (const [key, value] of entries) {
      await sql`
        INSERT INTO user_preferences (user_id, key, value, updated_at)
        VALUES (${userId}, ${key}, ${String(value)}, NOW())
        ON CONFLICT (user_id, key)
        DO UPDATE SET value = EXCLUDED.value, updated_at = NOW()
      `;
    }

    log.info('Preferences updated', { userId, keys: Object.keys(preferences) }, 'auth/preferences');

    return apiResponse.success(res, preferences, 'Preferences saved');
  }

  return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET', 'PUT']);
}

export default withAuth(withErrorHandler(handler) as any);

/**
 * Tooltip — CSS-only hover tooltip with position variants.
 * WORKING: No external dependencies, delay via CSS transition, aria-label fallback.
 *
 * Usage:
 *   <Tooltip content="Export to CSV" position="top">
 *     <button>Export</button>
 *   </Tooltip>
 */

import * as React from 'react';
import { cn } from '@/utils/cn';

export type TooltipPosition = 'top' | 'bottom' | 'left' | 'right';

export interface TooltipProps {
  content: string;
  position?: TooltipPosition;
  children: React.ReactElement;
  className?: string;
}

// Positioning styles for the bubble and its arrow
const positionClasses: Record<TooltipPosition, string> = {
  top: 'bottom-full left-1/2 -translate-x-1/2 mb-2',
  bottom: 'top-full left-1/2 -translate-x-1/2 mt-2',
  left: 'right-full top-1/2 -translate-y-1/2 mr-2',
  right: 'left-full top-1/2 -translate-y-1/2 ml-2',
};

const arrowClasses: Record<TooltipPosition, string> = {
  top: 'top-full left-1/2 -translate-x-1/2 border-t-gray-800 border-x-transparent border-b-transparent dark:border-t-gray-200',
  bottom: 'bottom-full left-1/2 -translate-x-1/2 border-b-gray-800 border-x-transparent border-t-transparent dark:border-b-gray-200',
  left: 'left-full top-1/2 -translate-y-1/2 border-l-gray-800 border-y-transparent border-r-transparent dark:border-l-gray-200',
  right: 'right-full top-1/2 -translate-y-1/2 border-r-gray-800 border-y-transparent border-l-transparent dark:border-r-gray-200',
};

// WORKING: Pure CSS approach — tooltip visibility controlled by group-hover
function Tooltip({
  content,
  position = 'top',
  children,
  className,
}: TooltipProps) {
  return (
    <span className={cn('group relative inline-flex', className)}>
      {children}

      {/* Tooltip bubble — hidden by default, revealed on group hover with delay */}
      <span
        role="tooltip"
        aria-hidden="true"
        className={cn(
          'pointer-events-none absolute z-50 whitespace-nowrap rounded-md px-2 py-1',
          'text-xs font-medium text-white bg-gray-800',
          'dark:bg-gray-100 dark:text-gray-900',
          'opacity-0 transition-opacity duration-150 delay-300',
          'group-hover:opacity-100',
          positionClasses[position]
        )}
      >
        {content}
        {/* Arrow */}
        <span
          aria-hidden="true"
          className={cn(
            'absolute border-4',
            arrowClasses[position]
          )}
        />
      </span>
    </span>
  );
}

Tooltip.displayName = 'Tooltip';

export { Tooltip };

/**
 * Fetch wrapper that automatically injects the active company ID header.
 * Use this instead of raw fetch() for all accounting API calls.
 */

const COMPANY_STORAGE_KEY = 'isaflow_active_company';

export async function apiFetch(url: string, options?: RequestInit): Promise<Response> {
  const headers = new Headers(options?.headers);

  if (typeof window !== 'undefined') {
    const stored = localStorage.getItem(COMPANY_STORAGE_KEY);
    if (stored) {
      try {
        const { id } = JSON.parse(stored);
        if (id) headers.set('X-Company-Id', id);
      } catch {
        // Invalid JSON — ignore
      }
    }
  }

  return fetch(url, {
    ...options,
    headers,
    credentials: 'include',
  });
}

