/**
 * SplitButton — Primary action with a dropdown of secondary actions.
 * WORKING: Portal-based dropdown, keyboard navigation, dark mode, ESC/click-outside close.
 *
 * Usage:
 *   <SplitButton
 *     label="Approve"
 *     onClick={handleApprove}
 *     options={[
 *       { label: 'Approve & Email', onClick: handleApproveEmail, icon: Mail },
 *       { label: 'Approve & Print', onClick: handleApprovePrint, icon: Printer },
 *     ]}
 *   />
 */

import * as React from 'react';
import { createPortal } from 'react-dom';
import { ChevronDown } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import { cn } from '@/utils/cn';
import { LoadingSpinner } from './LoadingSpinner';

// ─── Types ─────────────────────────────────────────────────────────────────────

export interface SplitButtonOption {
  label: string;
  onClick: () => void;
  icon?: LucideIcon;
  disabled?: boolean;
}

export interface SplitButtonProps {
  label: string;
  onClick: () => void;
  variant?: 'primary' | 'secondary' | 'danger';
  size?: 'sm' | 'md' | 'lg';
  disabled?: boolean;
  loading?: boolean;
  options: SplitButtonOption[];
  className?: string;
}

// ─── Variant/size maps ────────────────────────────────────────────────────────

const variantMain: Record<NonNullable<SplitButtonProps['variant']>, string> = {
  primary: [
    'bg-teal-600 text-white hover:bg-teal-700 focus-visible:ring-teal-500',
    'dark:bg-teal-500 dark:hover:bg-teal-600',
  ].join(' '),
  secondary: [
    'border border-gray-300 bg-white text-gray-700 hover:bg-gray-50',
    'focus-visible:ring-teal-500',
    'dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-gray-700',
  ].join(' '),
  danger: [
    'bg-red-600 text-white hover:bg-red-700 focus-visible:ring-red-500',
    'dark:bg-red-700 dark:hover:bg-red-800',
  ].join(' '),
};

const variantChevron: Record<NonNullable<SplitButtonProps['variant']>, string> = {
  primary: [
    'bg-teal-700 text-white hover:bg-teal-800 border-l border-teal-500',
    'focus-visible:ring-teal-500',
    'dark:bg-teal-600 dark:hover:bg-teal-700 dark:border-teal-400',
  ].join(' '),
  secondary: [
    'border border-l-0 border-gray-300 bg-white text-gray-700 hover:bg-gray-50',
    'focus-visible:ring-teal-500',
    'dark:border-gray-600 dark:bg-gray-800 dark:text-gray-200 dark:hover:bg-gray-700',
  ].join(' '),
  danger: [
    'bg-red-700 text-white hover:bg-red-800 border-l border-red-500',
    'focus-visible:ring-red-500',
    'dark:bg-red-800 dark:hover:bg-red-900 dark:border-red-600',
  ].join(' '),
};

const sizeMain: Record<NonNullable<SplitButtonProps['size']>, string> = {
  sm: 'h-8 px-3 text-xs',
  md: 'h-9 px-4 text-sm',
  lg: 'h-11 px-6 text-base',
};

const sizeChevron: Record<NonNullable<SplitButtonProps['size']>, string> = {
  sm: 'h-8 w-7',
  md: 'h-9 w-8',
  lg: 'h-11 w-10',
};

const iconSize: Record<NonNullable<SplitButtonProps['size']>, number> = {
  sm: 14,
  md: 16,
  lg: 18,
};

// ─── Portal dropdown ──────────────────────────────────────────────────────────

interface DropdownPortalProps {
  anchorRect: DOMRect;
  options: SplitButtonOption[];
  focusedIndex: number;
  onSelect: (option: SplitButtonOption) => void;
  onFocusChange: (index: number) => void;
}

function DropdownPortal({
  anchorRect,
  options,
  focusedIndex,
  onSelect,
  onFocusChange,
}: DropdownPortalProps) {
  const top = anchorRect.bottom + window.scrollY + 4;
  const left = anchorRect.left + window.scrollX;

  return createPortal(
    <div
      role="menu"
      aria-orientation="vertical"
      style={{ position: 'absolute', top, left, minWidth: anchorRect.width, zIndex: 9999 }}
      className={cn(
        'rounded-md shadow-xl border py-1',
        'bg-white border-gray-200',
        'dark:bg-gray-800 dark:border-gray-700',
      )}
    >
      {options.map((opt, idx) => {
        const Icon = opt.icon;
        const isFocused = idx === focusedIndex;
        return (
          <button
            key={opt.label}
            role="menuitem"
            disabled={opt.disabled}
            tabIndex={-1}
            onMouseEnter={() => onFocusChange(idx)}
            onClick={() => onSelect(opt)}
            className={cn(
              'w-full flex items-center gap-2 px-4 py-2 text-sm text-left',
              'transition-colors disabled:opacity-50 disabled:pointer-events-none',
              isFocused
                ? 'bg-teal-50 text-teal-700 dark:bg-teal-900/40 dark:text-teal-300'
                : 'text-gray-700 hover:bg-gray-50 dark:text-gray-200 dark:hover:bg-gray-700',
            )}
          >
            {Icon && <Icon size={14} className="flex-shrink-0" />}
            {opt.label}
          </button>
        );
      })}
    </div>,
    document.body,
  );
}

// ─── SplitButton ──────────────────────────────────────────────────────────────

function SplitButton({
  label,
  onClick,
  variant = 'primary',
  size = 'md',
  disabled = false,
  loading = false,
  options,
  className,
}: SplitButtonProps) {
  const [open, setOpen] = React.useState(false);
  const [focusedIndex, setFocusedIndex] = React.useState(-1);
  const [anchorRect, setAnchorRect] = React.useState<DOMRect | null>(null);
  const wrapperRef = React.useRef<HTMLDivElement>(null);
  const chevronRef = React.useRef<HTMLButtonElement>(null);

  const isDisabled = disabled || loading;
  const iSize = iconSize[size];

  // Close on outside click
  React.useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target as Node)) {
        setOpen(false);
        setFocusedIndex(-1);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  // Keyboard: ESC and arrow keys
  React.useEffect(() => {
    if (!open) return;
    const handler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        setOpen(false);
        setFocusedIndex(-1);
        chevronRef.current?.focus();
        return;
      }
      if (e.key === 'ArrowDown') {
        e.preventDefault();
        setFocusedIndex(i => Math.min(i + 1, options.length - 1));
        return;
      }
      if (e.key === 'ArrowUp') {
        e.preventDefault();
        setFocusedIndex(i => Math.max(i - 1, 0));
        return;
      }
      if (e.key === 'Enter' && focusedIndex >= 0) {
        const opt = options[focusedIndex];
        if (opt && !opt.disabled) {
          opt.onClick();
          setOpen(false);
          setFocusedIndex(-1);
        }
      }
    };
    document.addEventListener('keydown', handler);
