        label="Bank Name"
        value={state.bankName}
        onChange={e => setState(s => ({ ...s, bankName: e.target.value }))}
        placeholder="e.g. First National Bank"
      />
      <div className="grid grid-cols-2 gap-3">
        <Input
          label="Account Number"
          value={state.accountNumber}
          onChange={e => setState(s => ({ ...s, accountNumber: e.target.value }))}
          placeholder="62xxxxxxxx"
        />
        <Input
          label="Branch Code"
          value={state.branchCode}
          onChange={e => setState(s => ({ ...s, branchCode: e.target.value }))}
          placeholder="250655"
        />
      </div>
      <div>
        <label className="text-sm font-medium text-gray-700 dark:text-gray-300 block mb-1.5">
          Payment Terms
        </label>
        <textarea
          value={state.paymentTerms}
          onChange={e => setState(s => ({ ...s, paymentTerms: e.target.value }))}
          rows={3}
          className="w-full rounded-md border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500 dark:focus:ring-teal-400 placeholder-gray-400 dark:placeholder-gray-500 transition-colors"
          placeholder="Payment due within 30 days."
        />
      </div>
    </div>
  );
}

// ── Step 3: Invoice Numbering ────────────────────────────────────────────────

function Step3({ state, setState }: { state: WizardState; setState: React.Dispatch<React.SetStateAction<WizardState>> }) {
  const preview = `${state.invoicePrefix || 'INV-'}${state.nextNumber || '0001'}`;
  return (
    <div className="space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <Input
          label="Prefix"
          value={state.invoicePrefix}
          onChange={e => setState(s => ({ ...s, invoicePrefix: e.target.value }))}
          placeholder="INV-"
        />
        <Input
          label="Next Number"
          value={state.nextNumber}
          onChange={e => setState(s => ({ ...s, nextNumber: e.target.value }))}
          placeholder="0001"
        />
      </div>
      <div className="bg-gray-100 dark:bg-gray-700/50 rounded-lg p-4 text-center">
        <p className="text-xs text-gray-500 dark:text-gray-400 mb-1">Your next invoice number will be</p>
        <p className="text-2xl font-bold text-teal-600 dark:text-teal-400 tracking-wide">{preview}</p>
      </div>
      <p className="text-xs text-gray-400 dark:text-gray-500">
        The number increments automatically with each new invoice.
      </p>
    </div>
  );
}

// ── Main Wizard ──────────────────────────────────────────────────────────────

export function FirstInvoiceWizard() {
  const { shouldShow, dismiss, loading } = useFirstUseWizard('first_invoice_wizard');
  const [step, setStep] = useState(0);
  const [state, setState] = useState<WizardState>(INITIAL);

  if (loading || !shouldShow) return null;

  const isLast = step === STEPS.length - 1;

  const handleNext = () => {
    if (isLast) { dismiss(); return; }
    setStep(s => s + 1);
  };

  const stepTitles = ['Branding', 'Payment Details', 'Numbering'];

  return (
    <Modal open title={`Set Up Your Invoices — ${stepTitles[step]}`} onClose={dismiss} size="md" disableBackdropClose>
      <Modal.Body>
        <StepDots current={step} total={STEPS.length} />
        {step === 0 && <Step1 state={state} setState={setState} />}
        {step === 1 && <Step2 state={state} setState={setState} />}
        {step === 2 && <Step3 state={state} setState={setState} />}
      </Modal.Body>
      <Modal.Footer className="justify-between">
        <button
          type="button"
          onClick={dismiss}
          className="text-sm text-gray-400 hover:text-gray-300 dark:hover:text-gray-200 transition-colors"
        >
          Skip for now
        </button>
        <div className="flex gap-2">
          {step > 0 && (
            <Button variant="secondary" size="sm" onClick={() => setStep(s => s - 1)}>
              Back
            </Button>
          )}
          <Button size="sm" onClick={handleNext}>
            {isLast ? 'Finish' : 'Next'}
          </Button>
        </div>
      </Modal.Footer>
    </Modal>
  );
}

