          value={state.invoicePrefix}
          onChange={e => setState(s => ({ ...s, invoicePrefix: e.target.value }))}
          placeholder="INV-"
        />
        <Input
          label="Next Number"
          value={state.nextNumber}
          onChange={e => setState(s => ({ ...s, nextNumber: e.target.value }))}
