}

// ── Main Wizard ──────────────────────────────────────────────────────────────

export function FirstInvoiceWizard() {
  const { shouldShow, dismiss, loading } = useFirstUseWizard('first_invoice_wizard');
  const [step, setStep] = useState(0);
  const [state, setState] = useState<WizardState>(INITIAL);

  if (loading || !shouldShow) return null;

  const isLast = step === STEPS.length - 1;

  const handleNext = () => {
    if (isLast) { dismiss(); return; }
    setStep(s => s + 1);
  };

  const stepTitles = ['Branding', 'Payment Details', 'Numbering'];

  return (
    <Modal open title={`Set Up Your Invoices — ${stepTitles[step]}`} onClose={dismiss} size="md" disableBackdropClose>
      <Modal.Body>
        <StepDots current={step} total={STEPS.length} />
        {step === 0 && <Step1 state={state} setState={setState} />}
        {step === 1 && <Step2 state={state} setState={setState} />}
        {step === 2 && <Step3 state={state} setState={setState} />}
      </Modal.Body>
      <Modal.Footer className="justify-between">
        <button
          type="button"
          onClick={dismiss}
          className="text-sm text-gray-400 hover:text-gray-300 dark:hover:text-gray-200 transition-colors"
        >
          Skip for now
        </button>
        <div className="flex gap-2">
          {step > 0 && (
            <Button variant="secondary" size="sm" onClick={() => setStep(s => s - 1)}>
              Back
            </Button>
          )}
          <Button size="sm" onClick={handleNext}>
            {isLast ? 'Finish' : 'Next'}
          </Button>
        </div>
      </Modal.Footer>
    </Modal>
  );
}

