/**
 * useFirstUseWizard — checks user_preferences for a wizard dismissal key.
 * Returns shouldShow, dismiss(), and loading state.
 * Caches the result in a module-level map so repeated renders don't re-fetch.
 */

import { useCallback, useEffect, useRef, useState } from 'react';
import { apiFetch } from '@/lib/apiFetch';

// Module-level cache: wizardKey → dismissed boolean
const cache = new Map<string, boolean>();
// Track in-flight fetches to avoid duplicate requests
const inFlight = new Map<string, Promise<boolean>>();

async function fetchDismissed(wizardKey: string): Promise<boolean> {
  if (inFlight.has(wizardKey)) {
    return inFlight.get(wizardKey)!;
  }

  const promise = apiFetch('/api/auth/preferences')
    .then(async (res) => {
      if (!res.ok) return false;
      const body = await res.json() as { data?: Record<string, string> };
      const prefs = body.data ?? {};
      return prefs[`${wizardKey}_dismissed`] === 'true';
    })
    .catch(() => false)
    .finally(() => {
      inFlight.delete(wizardKey);
    });

  inFlight.set(wizardKey, promise);
  return promise;
}

async function saveDismissed(wizardKey: string): Promise<void> {
  await apiFetch('/api/auth/preferences', {
    method: 'PUT',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      preferences: { [`${wizardKey}_dismissed`]: 'true' },
    }),
  });
}

interface UseFirstUseWizardResult {
  shouldShow: boolean;
  dismiss: () => void;
  loading: boolean;
}

export function useFirstUseWizard(wizardKey: string): UseFirstUseWizardResult {
  const [dismissed, setDismissed] = useState<boolean | null>(
    cache.has(wizardKey) ? (cache.get(wizardKey) ?? false) : null
  );
  const [loading, setLoading] = useState(!cache.has(wizardKey));
  const mounted = useRef(true);

  useEffect(() => {
    mounted.current = true;
    return () => { mounted.current = false; };
  }, []);

  useEffect(() => {
    if (cache.has(wizardKey)) {
      setDismissed(cache.get(wizardKey) ?? false);
      setLoading(false);
      return;
    }

    setLoading(true);
    void fetchDismissed(wizardKey).then((isDismissed) => {
      cache.set(wizardKey, isDismissed);
      if (mounted.current) {
        setDismissed(isDismissed);
        setLoading(false);
      }
    });
  }, [wizardKey]);

  const dismiss = useCallback(() => {
    cache.set(wizardKey, true);
    setDismissed(true);
    void saveDismissed(wizardKey);
  }, [wizardKey]);

  return {
    shouldShow: dismissed === false,
    dismiss,
    loading,
  };
}

/**
 * useReportFavourites — manages starred reports per user via user_preferences.
 * Optimistic updates: toggle immediately, revert on API error.
 * WORKING: Loads once on mount, caches in state for the lifetime of the hook.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

const PREF_KEY = 'report_favourites';

export interface UseReportFavouritesResult {
  favourites: string[];
  isFavourite: (id: string) => boolean;
  toggleFavourite: (id: string) => void;
  loading: boolean;
}

export function useReportFavourites(): UseReportFavouritesResult {
  const [favourites, setFavourites] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  // Track whether we have loaded at all to prevent double-fetch in StrictMode
  const loaded = useRef(false);

  useEffect(() => {
    if (loaded.current) return;
    loaded.current = true;

    void (async () => {
      try {
        const res = await apiFetch('/api/auth/preferences');
        if (!res.ok) {
          log.warn('Failed to load preferences', { status: res.status }, 'useReportFavourites');
          return;
        }
        const json = (await res.json()) as { data?: Record<string, string> };
        const raw = json.data?.[PREF_KEY];
        if (raw) {
          try {
            const parsed = JSON.parse(raw) as unknown;
            if (Array.isArray(parsed)) {
              setFavourites(parsed as string[]);
            }
          } catch {
            log.warn('Could not parse report_favourites pref', {}, 'useReportFavourites');
          }
        }
      } catch (err) {
        log.error('Error loading report favourites', { err }, 'useReportFavourites');
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  const save = useCallback(async (next: string[]) => {
    try {
      const res = await apiFetch('/api/auth/preferences', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ preferences: { [PREF_KEY]: JSON.stringify(next) } }),
      });
      if (!res.ok) {
        log.warn('Failed to save report favourites', { status: res.status }, 'useReportFavourites');
        return false;
      }
      return true;
    } catch (err) {
      log.error('Error saving report favourites', { err }, 'useReportFavourites');
      return false;
    }
  }, []);

  const toggleFavourite = useCallback((id: string) => {
    setFavourites(prev => {
      const exists = prev.includes(id);
      const next = exists ? prev.filter(f => f !== id) : [...prev, id];

      // Optimistic: save in background, revert on failure
      void save(next).then(ok => {
        if (!ok) {
          setFavourites(prev2 => {
            // Revert: if we added, remove it; if we removed, add it back
            if (!exists) return prev2.filter(f => f !== id);
            if (!prev2.includes(id)) return [...prev2, id];
            return prev2;
          });
        }
      });

      return next;
    });
  }, [save]);

  const isFavourite = useCallback((id: string) => favourites.includes(id), [favourites]);

  return { favourites, isFavourite, toggleFavourite, loading };
}

