    } catch (err) {
      log.error('Failed to get dashboard stats', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to get dashboard stats');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
}

