/**
 * Admin Dashboard Service
 * Aggregates platform-wide KPIs for the ISAFlow Admin Platform.
 * Queries: company counts, user counts, MRR/ARR, recent activity.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { DashboardStats, ActivityEvent } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toISOString(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

/**
 * Fetch platform-wide dashboard statistics.
 * Runs aggregate queries in parallel for performance.
 */
export async function getDashboardStats(): Promise<DashboardStats> {
  const [companyStats, userStats, mrrStats, signupCount, recentActivity] =
    await Promise.all([
      getCompanyStats(),
      getUserStats(),
      getMrrStats(),
      getNewSignupCount(),
      getRecentActivity(),
    ]);

  const stats: DashboardStats = {
    total_companies: companyStats.total,
    active_companies: companyStats.active,
    total_users: userStats.total,
    active_users_30d: userStats.active_30d,
    mrr_cents: mrrStats.mrr_cents,
    arr_cents: mrrStats.arr_cents,
    new_signups_30d: signupCount,
    recent_activity: recentActivity,
  };

  log.info('Admin dashboard stats fetched', {
    total_companies: stats.total_companies,
    active_companies: stats.active_companies,
    total_users: stats.total_users,
    mrr_cents: stats.mrr_cents,
  }, 'AdminDashboardService');

  return stats;
}

async function getCompanyStats(): Promise<{ total: number; active: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'active') AS active
    FROM companies
    WHERE status IS DISTINCT FROM 'deleted'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10),
    active: parseInt(row.active as string, 10),
  };
}

async function getUserStats(): Promise<{ total: number; active_30d: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS active_30d
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10),
    active_30d: parseInt(row.active_30d as string, 10),
  };
}

async function getMrrStats(): Promise<{ mrr_cents: number; arr_cents: number }> {
  // Monthly: sum monthly_price_cents
  // Annual: normalise to monthly (divide by 12)
  const rows = await sql`
    SELECT
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM subscriptions s
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.status IN ('active', 'trial')
  `;
  const mrr = parseInt((rows[0] as Row).mrr_cents as string, 10);
  return { mrr_cents: mrr, arr_cents: mrr * 12 };
}

async function getNewSignupCount(): Promise<number> {
  const rows = await sql`
    SELECT COUNT(*) AS count
    FROM companies
    WHERE created_at >= NOW() - INTERVAL '30 days'
      AND status IS DISTINCT FROM 'deleted'
  `;
  return parseInt((rows[0] as Row).count as string, 10);
}

/**
 * Most recent 50 events from admin_audit_log + recent user_sessions.
 */
async function getRecentActivity(): Promise<ActivityEvent[]> {
  const rows = await sql`
    SELECT
      a.id::text                                                     AS id,
      'admin_action'                                                 AS type,
      a.action || ' ' || a.target_type                              AS description,
      COALESCE(u.first_name || ' ' || u.last_name, u.email)          AS user_name,
      NULL::text                                                     AS company_name,
      a.created_at
    FROM admin_audit_log a
    LEFT JOIN users u ON u.id = a.admin_user_id

    UNION ALL

    SELECT
      s.id::text                                                     AS id,
      'user_login'                                                   AS type,
      'User login'                                                   AS description,
      COALESCE(u.first_name || ' ' || u.last_name, u.email)          AS user_name,
      NULL::text                                                     AS company_name,
      s.created_at
    FROM user_sessions s
    INNER JOIN users u ON u.id = s.user_id
    WHERE s.created_at >= NOW() - INTERVAL '7 days'

    ORDER BY created_at DESC
    LIMIT 50
  `;

  return (rows as Row[]).map((row) => ({
    id: row.id as string,
    type: row.type as string,
    description: row.description as string,
    user_name: row.user_name as string | null,
    company_name: row.company_name as string | null,
    created_at: toISOString(row.created_at),
  }));
}

/**
 * Admin — Feature Flags
 * View and edit all platform feature flags. Features are seeded via migration,
 * so create/delete is not exposed here — only name, description, and is_global.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2, Pencil, Globe, Lock, X, Check } from 'lucide-react';

interface FeatureFlag {
  id: string;
  code: string;
  name: string;
  description: string | null;
  is_global: boolean;
  created_at: string;
}

interface EditState {
  name: string;
  description: string;
  is_global: boolean;
}

function fmtDate(d: string) {
  return new Date(d).toLocaleDateString('en-ZA');
}

export default function AdminFeaturesPage() {
  const [flags, setFlags]         = useState<FeatureFlag[]>([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [editing, setEditing]     = useState<string | null>(null);
  const [editState, setEditState] = useState<EditState>({ name: '', description: '', is_global: false });
  const [saving, setSaving]       = useState(false);
  const [saveError, setSaveError] = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res  = await apiFetch('/api/admin/features');
      const json = await res.json() as { data?: FeatureFlag[]; message?: string };
      if (!res.ok) throw new Error(json.message || 'Failed to load features');
      setFlags(json.data ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load features');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  function openEdit(flag: FeatureFlag) {
    setEditing(flag.id);
    setEditState({
      name: flag.name,
      description: flag.description ?? '',
      is_global: flag.is_global,
    });
    setSaveError('');
  }

  function cancelEdit() {
    setEditing(null);
    setSaveError('');
  }

  async function saveEdit(id: string) {
    setSaving(true);
    setSaveError('');
    try {
      const res = await apiFetch(`/api/admin/features/${id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: editState.name.trim() || undefined,
          description: editState.description.trim() || undefined,
          is_global: editState.is_global,
        }),
      });
      const json = await res.json() as { data?: FeatureFlag; message?: string };
      if (!res.ok) throw new Error(json.message || 'Failed to save');

      setFlags((prev) =>
        prev.map((f) => (f.id === id && json.data ? json.data : f))
      );
      setEditing(null);
    } catch (err) {
      setSaveError(err instanceof Error ? err.message : 'Failed to save');
    } finally {
      setSaving(false);
    }
  }

  return (
    <AdminLayout title="Feature Flags">
      <div className="mb-5 flex items-center justify-between">
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Feature flags control access to platform capabilities.
          Flags are seeded via migration — edit names, descriptions, and global availability here.
        </p>
        <span className="text-sm text-gray-500 dark:text-gray-400">{flags.length} flags</span>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <th className="px-4 py-3 font-medium">Code</th>
                <th className="px-4 py-3 font-medium">Name</th>
                <th className="px-4 py-3 font-medium">Description</th>
                <th className="px-4 py-3 font-medium">Global</th>
                <th className="px-4 py-3 font-medium">Created</th>
                <th className="px-4 py-3 font-medium w-16"></th>
              </tr>
            </thead>
            <tbody>
              {loading && flags.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center">
                    <Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" />
                  </td>
                </tr>
              )}
              {!loading && flags.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center text-gray-400">
                    No feature flags found
                  </td>
                </tr>
              )}

              {flags.map((flag) =>
                editing === flag.id ? (
                  // Edit row
                  <tr
                    key={flag.id}
                    className="border-b border-gray-100 dark:border-gray-800 last:border-0 bg-teal-50/40 dark:bg-teal-900/10"
                  >
                    <td className="px-4 py-3">
                      <code className="text-xs font-mono text-gray-500 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded">
                        {flag.code}
                      </code>
                    </td>
                    <td className="px-4 py-3">
                      <input
                        type="text"
                        value={editState.name}
                        onChange={(e) => setEditState((s) => ({ ...s, name: e.target.value }))}
                        className="w-full px-2 py-1 text-sm rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                        placeholder="Feature name"
                      />
                    </td>
                    <td className="px-4 py-3">
                      <input
                        type="text"
                        value={editState.description}
                        onChange={(e) => setEditState((s) => ({ ...s, description: e.target.value }))}
                        className="w-full px-2 py-1 text-sm rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
                        placeholder="Description"
                      />
                    </td>
                    <td className="px-4 py-3">
                      <button
                        type="button"
                        onClick={() => setEditState((s) => ({ ...s, is_global: !s.is_global }))}
                        className={`flex items-center gap-1.5 px-2 py-1 rounded text-xs font-medium transition-colors ${
                          editState.is_global
                            ? 'bg-teal-100 text-teal-700 dark:bg-teal-900/40 dark:text-teal-300'
                            : 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400'
                        }`}
                      >
                        {editState.is_global
                          ? <><Globe className="w-3 h-3" /> Global</>
                          : <><Lock className="w-3 h-3" /> Plan only</>
                        }
                      </button>
                    </td>
                    <td className="px-4 py-3 text-gray-400 text-xs">{fmtDate(flag.created_at)}</td>
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-1">
                        {saveError && (
                          <span className="text-xs text-red-500 mr-1">{saveError}</span>
                        )}
                        <button
                          onClick={() => void saveEdit(flag.id)}
                          disabled={saving}
                          className="p-1.5 rounded text-teal-600 hover:bg-teal-50 dark:hover:bg-teal-900/20 disabled:opacity-40 transition-colors"
                          title="Save"
                        >
                          {saving
                            ? <Loader2 className="w-4 h-4 animate-spin" />
                            : <Check className="w-4 h-4" />
                          }
                        </button>
                        <button
                          onClick={cancelEdit}
                          disabled={saving}
                          className="p-1.5 rounded text-gray-500 hover:bg-gray-100 dark:hover:bg-gray-800 disabled:opacity-40 transition-colors"
                          title="Cancel"
                        >
                          <X className="w-4 h-4" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ) : (
                  // Read-only row
                  <tr
                    key={flag.id}
                    className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 transition-colors"
                  >
                    <td className="px-4 py-3">
                      <code className="text-xs font-mono text-gray-600 dark:text-gray-400 bg-gray-100 dark:bg-gray-800 px-2 py-0.5 rounded">
                        {flag.code}
                      </code>
                    </td>
                    <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">
                      {flag.name}
                    </td>
                    <td className="px-4 py-3 text-gray-500 dark:text-gray-400 max-w-xs truncate">
                      {flag.description || <span className="italic text-gray-300 dark:text-gray-600">No description</span>}
                    </td>
                    <td className="px-4 py-3">
                      {flag.is_global ? (
                        <span className="flex items-center gap-1 text-xs text-teal-600 dark:text-teal-400">
                          <Globe className="w-3.5 h-3.5" /> Global
                        </span>
                      ) : (
                        <span className="flex items-center gap-1 text-xs text-gray-400">
                          <Lock className="w-3.5 h-3.5" /> Plan only
                        </span>
                      )}
                    </td>
                    <td className="px-4 py-3 text-gray-400 text-xs whitespace-nowrap">
                      {fmtDate(flag.created_at)}
                    </td>
                    <td className="px-4 py-3">
                      <button
                        onClick={() => openEdit(flag)}
                        className="p-1.5 rounded text-gray-400 hover:text-gray-700 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
                        title="Edit feature flag"
                      >
                        <Pencil className="w-4 h-4" />
                      </button>
                    </td>
                  </tr>
                )
              )}
            </tbody>
          </table>
        </div>
      </div>
    </AdminLayout>
  );
}

