        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_cache_bypass $http_upgrade;
    }
}

/**
 * Admin Dashboard — KPI stats + recent activity feed.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { StatsCard } from '@/components/admin/StatsCard';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Building2, Users, ArrowRight, Loader2, Activity } from 'lucide-react';

interface DashboardStats {
  totalCompanies: number;
  activeCompanies30d: number;
  totalUsers: number;
  activeUsers30d: number;
  mrrCents: number;
  newSignups30d: number;
}

interface ActivityRow {
  type: string;
  description: string;
  user: string;
  company: string;
  createdAt: string;
}

interface DashboardData {
  stats: DashboardStats;
  recentActivity: ActivityRow[];
}

interface PlatformHealth {
  active_users_24h: number;
  active_users_7d: number;
  active_users_30d: number;
  db_size_mb: number;
  error_rate_percent: number;
}

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtRelative(dateStr: string) {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60_000);
  if (mins < 60)  return `${mins}m ago`;

/**
 * AdminLayout — wraps AppLayout with admin sidebar nav.
 * Enforces super_admin role; redirects non-admins to /login.
 */

import { useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import { AdminNav } from './AdminNav';
import { useAuth } from '@/contexts/AuthContext';
import { Loader2 } from 'lucide-react';

interface AdminLayoutProps {
  children: React.ReactNode;
  title: string;
}

export function AdminLayout({ children, title }: AdminLayoutProps) {
  const { user, loading } = useAuth();
  const router = useRouter();

  useEffect(() => {
    if (!loading && (!user || user.role !== 'super_admin')) {
      void router.replace('/login');
    }
  }, [user, loading, router]);

  if (loading || !user || user.role !== 'super_admin') {
    return (
      <AppLayout>
        <div className="flex items-center justify-center h-64">
          <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
        </div>
      </AppLayout>
    );
  }

  return (
    <AppLayout>
      <div className="flex min-h-[calc(100vh-4rem)] -m-4 lg:-m-6">
        <AdminNav />
        <main className="flex-1 p-6 overflow-y-auto bg-white dark:bg-gray-950 min-w-0">
          <h1 className="text-2xl font-bold mb-6 text-gray-900 dark:text-white">{title}</h1>
          {children}
        </main>
      </div>
    </AppLayout>
  );
}

