/**
 * Admin Tools Landing Page
 * Overview of available platform tools with navigation cards.
 */

import Link from 'next/link';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { Megaphone, Download, UserCog, Zap, ExternalLink } from 'lucide-react';

interface ToolCard {
  icon: React.ComponentType<{ className?: string }>;
  title: string;
  description: string;
  action: { label: string; href: string; external?: boolean } | null;
  note?: string;
}

const TOOLS: ToolCard[] = [
  {
    icon: Megaphone,
    title: 'Announcements',
    description:
      'Create and manage platform-wide announcements. Target all users, specific plans, or individual companies. Schedule start/end times and mark messages as dismissible.',
    action: { label: 'Manage Announcements', href: '/admin/tools/announcements' },
  },
  {
    icon: Download,
    title: 'Data Export',
    description:
      'Export all accounting data for any company as a structured JSON file. Includes chart of accounts, customers, suppliers, invoices, journal entries, and bank transactions.',
    action: null,
    note: 'Navigate to Company Detail → click "Export Data" button to download.',
  },
  {
    icon: UserCog,
    title: 'Impersonation',
    description:
      'View the application as a specific company for debugging and support. Generates a 30-minute impersonation token that switches company context in the customer app.',
    action: null,
    note: 'Navigate to Company Detail → click "Impersonate" button to generate a session.',
  },
  {
    icon: Zap,
    title: 'Sage Auto-Import',
    description:
      'Trigger a full Sage Accounting data import for any company. Pulls chart of accounts, customers, suppliers, invoices, and journal entries via the internal REST API.',
    action: {
      label: 'Open Sage Import',
      href: '/accounting/migration/sage-auto',
      external: true,
    },
    note: 'Opens in the customer app — you must be logged in to a company.',
  },
];

export default function AdminToolsPage() {
  return (
    <AdminLayout title="Admin Tools">
      <div className="max-w-4xl mx-auto space-y-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Admin Tools</h1>
          <p className="mt-1 text-sm text-gray-500 dark:text-gray-400">
            Platform management tools for super_admin use only.
          </p>
        </div>

        <div className="grid gap-4 sm:grid-cols-2">
          {TOOLS.map((tool) => {
            const Icon = tool.icon;
            return (
              <div
                key={tool.title}
                className="bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-xl p-5 flex flex-col gap-3"
              >
                <div className="flex items-center gap-3">
                  <div className="p-2 bg-teal-500/10 rounded-lg">
                    <Icon className="w-5 h-5 text-teal-600 dark:text-teal-400" />
                  </div>
                  <h2 className="text-base font-semibold text-gray-900 dark:text-white">
                    {tool.title}
                  </h2>
                </div>

                <p className="text-sm text-gray-600 dark:text-gray-400 flex-1">
                  {tool.description}
                </p>

                {tool.note && (
                  <p className="text-xs text-amber-600 dark:text-amber-400 bg-amber-50 dark:bg-amber-900/20 rounded-lg px-3 py-2">
                    {tool.note}
                  </p>
                )}

                {tool.action && (
                  tool.action.external ? (
                    <a
                      href={tool.action.href}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1.5 text-sm font-medium text-teal-600 dark:text-teal-400 hover:underline"
                    >
                      {tool.action.label}
                      <ExternalLink className="w-3.5 h-3.5" />
                    </a>
                  ) : (
                    <Link
                      href={tool.action.href}
                      className="inline-flex items-center gap-1.5 text-sm font-medium text-teal-600 dark:text-teal-400 hover:underline"
                    >
                      {tool.action.label}
                    </Link>
                  )
                )}
              </div>
            );
          })}
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminPrefix } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
} from 'lucide-react';

interface NavItem {
  label: string;
  href: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; href: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Paths relative to the admin root — prefix is applied dynamically */
const NAV_DEFS: { label: string; path: string; icon: React.ComponentType<{ className?: string }>; disabled?: boolean; children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[] }[] = [
  { label: 'Dashboard',   path: '',           icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies', icon: Building2 },
  { label: 'Users',       path: '/users',     icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
    ],
  },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',  path: '/analytics',  icon: BarChart2 },
  { label: 'Components', path: '/components', icon: Palette },
  { label: 'Settings',   path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const prefix = useAdminPrefix();

  /** Build nav items with the correct prefix applied */
  const navItems = NAV_DEFS.map(def => ({
    ...def,
    href: prefix + def.path || '/',
    children: def.children?.map(c => ({ ...c, href: prefix + c.path })),
  }));

  /** Use asPath for active state — it reflects the browser URL (clean on subdomain) */
  const currentPath = router.asPath.split('?')[0];

  const isActive = (href: string) => {
    const root = prefix || '/';
    if (href === root) return currentPath === root;
    return currentPath.startsWith(href);
  };

  const isSectionOpen = (href: string) => currentPath.startsWith(href);

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {navItems.map(item => {
          const Icon = item.icon;

          if (item.disabled) {
            return (
              <div
                key={item.href}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.href);
            return (
              <div key={item.href}>
                <Link
                  href={item.href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.href) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.href) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childActive = currentPath === child.href;
                      return (
                        <Link
                          key={child.href}
                          href={child.href}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.href);
          return (
            <Link
              key={item.href}
              href={item.href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

