/**
 * Admin Dashboard — KPI stats + recent activity feed.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { StatsCard } from '@/components/admin/StatsCard';
import { apiFetch } from '@/lib/apiFetch';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { AlertCircle, Building2, Users, ArrowRight, Loader2, Activity } from 'lucide-react';

interface DashboardStats {
  totalCompanies: number;
  activeCompanies30d: number;
  totalUsers: number;
  activeUsers30d: number;
  mrrCents: number;
  newSignups30d: number;
}

interface ActivityRow {
  type: string;
  description: string;
  user: string;
  company: string;
  createdAt: string;
}

interface DashboardData {
  stats: DashboardStats;
  recentActivity: ActivityRow[];
}

interface PlatformHealth {
  active_users_24h: number;
  active_users_7d: number;
  active_users_30d: number;
  db_size_mb: number;
  error_rate_percent: number;
}

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtRelative(dateStr: string) {
  const diff = Date.now() - new Date(dateStr).getTime();
  const mins = Math.floor(diff / 60_000);
  if (mins < 60)  return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24)   return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

export default function AdminDashboard() {
  const router = useRouter();
  const adminHref = useAdminHref();
  const [data, setData]           = useState<DashboardData | null>(null);
  const [health, setHealth]       = useState<PlatformHealth | null>(null);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [statsRes, healthRes] = await Promise.all([
        apiFetch('/api/admin/dashboard-stats'),
        apiFetch('/api/admin/analytics/health'),
      ]);
      const statsJson  = await statsRes.json();
      const healthJson = await healthRes.json();
      if (!statsRes.ok) throw new Error(statsJson.message || 'Failed to load dashboard');
      setData(statsJson.data as DashboardData);
      if (healthRes.ok) setHealth(healthJson.data as PlatformHealth);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load dashboard');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  const stats = data?.stats;

  return (
    <AdminLayout title="Admin Dashboard">
      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-6">
          <AlertCircle className="w-4 h-4 flex-shrink-0" />
          {error}
        </div>
      )}

      {loading && !data && (
        <div className="flex items-center justify-center py-24">
          <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
        </div>
      )}

      {stats && (
        <>
          {/* KPI Grid */}
          <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4 mb-8">
            <StatsCard title="Total Companies"       value={stats.totalCompanies} />
            <StatsCard title="Active (30d)"          value={stats.activeCompanies30d} subtitle="companies" />
            <StatsCard title="Total Users"           value={stats.totalUsers} />
            <StatsCard title="Active Users (30d)"    value={stats.activeUsers30d} />
            <StatsCard title="MRR"                   value={fmtZAR(stats.mrrCents)} />
            <StatsCard title="New Signups (30d)"     value={stats.newSignups30d} />
          </div>

          {/* Platform Health */}
          {health && (
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm mb-6">
              <div className="px-5 py-4 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Activity className="w-4 h-4 text-teal-500" />
                  <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Platform Health</h2>
                </div>
                <Link href={adminHref('/admin/analytics')} className="text-xs text-teal-500 hover:text-teal-400 font-medium">
                  View Full Analytics →
                </Link>
              </div>
              <div className="grid grid-cols-2 lg:grid-cols-5 gap-px bg-gray-200 dark:bg-gray-700">
                {[
                  { label: 'Active (24h)',  value: health.active_users_24h },
                  { label: 'Active (7d)',   value: health.active_users_7d },
                  { label: 'Active (30d)',  value: health.active_users_30d },
                  { label: 'DB Size',       value: `${health.db_size_mb} MB` },
                  { label: 'Error Rate',    value: `${health.error_rate_percent}%` },
                ].map((item) => (
                  <div key={item.label} className="bg-white dark:bg-gray-900 px-5 py-4">
                    <p className="text-xs text-gray-500 dark:text-gray-400 font-medium uppercase tracking-wider mb-1">{item.label}</p>
                    <p className="text-xl font-bold text-gray-900 dark:text-white">{item.value}</p>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Recent Activity */}
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm mb-8">
            <div className="px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Recent Activity</h2>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700">
                    <th className="px-5 py-3 font-medium">Type</th>
                    <th className="px-5 py-3 font-medium">Description</th>
                    <th className="px-5 py-3 font-medium">User</th>
                    <th className="px-5 py-3 font-medium">Company</th>
                    <th className="px-5 py-3 font-medium">Time</th>
                  </tr>
                </thead>
                <tbody>
                  {(data?.recentActivity ?? []).length === 0 && (
                    <tr>
                      <td colSpan={5} className="px-5 py-8 text-center text-gray-400 text-sm">
                        No recent activity
                      </td>
                    </tr>
                  )}
                  {(data?.recentActivity ?? []).map((row, i) => (
                    <tr key={i} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40">
                      <td className="px-5 py-3">
                        <span className="px-2 py-0.5 rounded text-xs font-medium bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300">
                          {row.type}
                        </span>
                      </td>
                      <td className="px-5 py-3 text-gray-700 dark:text-gray-200 max-w-xs truncate">{row.description}</td>
                      <td className="px-5 py-3 text-gray-600 dark:text-gray-300">{row.user}</td>
                      <td className="px-5 py-3 text-gray-600 dark:text-gray-300">{row.company}</td>
                      <td className="px-5 py-3 text-gray-400 whitespace-nowrap">{fmtRelative(row.createdAt)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}

      {/* Quick Actions */}
      <div className="flex gap-3 flex-wrap">
        <button
          onClick={() => void router.push(adminHref('/admin/companies'))}
          className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors"
        >
          <Building2 className="w-4 h-4" /> Manage Companies <ArrowRight className="w-4 h-4" />
        </button>
        <button
          onClick={() => void router.push(adminHref('/admin/users'))}
          className="inline-flex items-center gap-2 px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white text-sm font-medium rounded-lg transition-colors"
        >
          <Users className="w-4 h-4" /> Manage Users <ArrowRight className="w-4 h-4" />
        </button>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin — Company List
 * Search, filter, sort, paginate companies.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter } from 'next/router';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { Search, AlertCircle, Loader2, ChevronLeft, ChevronRight, ChevronsUpDown } from 'lucide-react';

interface Company {
  id: string;
  name: string;
  plan: string;
  status: 'trial' | 'active' | 'suspended' | 'cancelled';
  userCount: number;
  mrrCents: number;
  createdAt: string;
  lastActiveAt: string | null;
}

interface PagedResponse {
  items: Company[];
  total: number;
  page: number;
  limit: number;
}

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  suspended: 'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
};

type SortField = 'name' | 'plan' | 'status' | 'userCount' | 'mrrCents' | 'createdAt' | 'lastActiveAt';

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtDate(d: string | null) {
  if (!d) return '—';
  return new Date(d).toLocaleDateString('en-ZA');
}

export default function AdminCompaniesPage() {
  const router = useRouter();
  const adminHref = useAdminHref();

  const [rows, setRows]         = useState<Company[]>([]);
  const [total, setTotal]       = useState(0);
  const [page, setPage]         = useState(1);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState('');
  const [search, setSearch]     = useState('');
  const [status, setStatus]     = useState('');
  const [sortBy, setSortBy]     = useState<SortField>('createdAt');
  const [sortDir, setSortDir]   = useState<'asc' | 'desc'>('desc');

  const LIMIT = 25;
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const load = useCallback(async (q: string, st: string, pg: number, sb: SortField, sd: string) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({
        page:    String(pg),
        limit:   String(LIMIT),
        sortBy:  sb,
        sortDir: sd,
      });
      if (q)  params.set('search', q);
      if (st) params.set('status', st);
      const res  = await apiFetch(`/api/admin/companies?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load companies');
      const d = json.data as PagedResponse;
      setRows(d.items);
      setTotal(d.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, []);

  // Debounce search
  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      void load(search, status, 1, sortBy, sortDir);
    }, 300);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [search, status, sortBy, sortDir, load]);

  useEffect(() => {
    void load(search, status, page, sortBy, sortDir);
  }, [page]); // eslint-disable-line react-hooks/exhaustive-deps

  function toggleSort(field: SortField) {
    if (sortBy === field) {
      setSortDir(d => d === 'asc' ? 'desc' : 'asc');
    } else {
      setSortBy(field);
      setSortDir('asc');
    }
  }

  const totalPages = Math.max(1, Math.ceil(total / LIMIT));

  function SortIcon({ field }: { field: SortField }) {
    if (sortBy !== field) return <ChevronsUpDown className="w-3.5 h-3.5 opacity-30" />;
    return <ChevronsUpDown className="w-3.5 h-3.5 text-teal-500" />;
  }

  return (
    <AdminLayout title="Companies">
      {/* Filters */}
      <div className="flex gap-3 flex-wrap mb-5">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search companies…"
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500"
          />
        </div>
        <select
          value={status}
          onChange={e => { setStatus(e.target.value); setPage(1); }}
          className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
        >
          <option value="">All statuses</option>
          <option value="trial">Trial</option>
          <option value="active">Active</option>
          <option value="suspended">Suspended</option>
          <option value="cancelled">Cancelled</option>
        </select>
        <span className="ml-auto text-sm text-gray-500 dark:text-gray-400 self-center">
          {total} total
        </span>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                {([
                  ['name',         'Name'],
                  ['plan',         'Plan'],
                  ['status',       'Status'],
                  ['userCount',    'Users'],
                  ['mrrCents',     'MRR'],
                  ['createdAt',    'Created'],
                  ['lastActiveAt', 'Last Active'],
                ] as [SortField, string][]).map(([field, label]) => (
                  <th
                    key={field}
                    className="px-4 py-3 font-medium cursor-pointer select-none hover:text-gray-900 dark:hover:text-white"
                    onClick={() => toggleSort(field)}
                  >
                    <div className="flex items-center gap-1">
                      {label} <SortIcon field={field} />
                    </div>
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading && rows.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-12 text-center">
                    <Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" />
                  </td>
                </tr>
              )}
              {!loading && rows.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-12 text-center text-gray-400">No companies found</td>
                </tr>
              )}
              {rows.map(c => (
                <tr
                  key={c.id}
                  className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 cursor-pointer transition-colors"
                  onClick={() => void router.push(adminHref(`/admin/companies/${c.id}`))}
                >
                  <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{c.name}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{c.plan}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[c.status] ?? ''}`}>
                      {c.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{c.userCount}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(c.mrrCents)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(c.createdAt)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(c.lastActiveAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700 text-sm">
          <span className="text-gray-500 dark:text-gray-400">
            Page {page} of {totalPages}
          </span>
          <div className="flex gap-2">
            <button
              disabled={page <= 1}
              onClick={() => setPage(p => p - 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button
              disabled={page >= totalPages}
              onClick={() => setPage(p => p + 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin — Company Detail
 * Company info, subscription, users tab, and admin actions.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { ConfirmModal } from '@/components/admin/ConfirmModal';
import { apiFetch } from '@/lib/apiFetch';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { ArrowLeft, AlertCircle, Loader2, Building2, ShieldOff, ShieldCheck, Trash2 } from 'lucide-react';

interface CompanyDetail {
  id: string; name: string;
  registrationNumber: string | null; vatNumber: string | null;
  email: string | null; phone: string | null; address: string | null;
  plan: string; billingCycle: string; status: string;
  createdAt: string; lastActiveAt: string | null;
}

interface CompanyUser {
  id: string; name: string; email: string; role: string; lastLoginAt: string | null;
}

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  suspended: 'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
};

const fmtDate = (d: string | null) => d ? new Date(d).toLocaleDateString('en-ZA') : '—';

function Field({ label, value }: { label: string; value: string | null | undefined }) {
  return (
    <div>
      <p className="text-xs text-gray-500 dark:text-gray-400 mb-0.5">{label}</p>
      <p className="text-sm text-gray-900 dark:text-white">{value || '—'}</p>
    </div>
  );
}

export default function AdminCompanyDetailPage() {
  const router = useRouter();
  const adminHref = useAdminHref();
  const { id } = router.query;

  const [company, setCompany]   = useState<CompanyDetail | null>(null);
  const [users, setUsers]       = useState<CompanyUser[]>([]);
  const [loading, setLoading]   = useState(true);
  const [usersLoading, setUsersLoading] = useState(false);
  const [error, setError]       = useState('');
  const [activeTab, setActiveTab] = useState<'info' | 'users'>('info');
  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError]     = useState('');
  const [suspendOpen, setSuspendOpen] = useState(false);
  const [suspendReason, setSuspendReason] = useState('');
  const [deleteOpen, setDeleteOpen]   = useState(false);

  const load = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setLoading(true); setError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load company');
      setCompany(json.data as CompanyDetail);
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setLoading(false); }
  }, [id]);

  const loadUsers = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setUsersLoading(true);
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/users`);
      const json = await res.json();
      if (res.ok) setUsers((json.data as CompanyUser[]) || []);
    } catch { /* non-critical */ }
    finally { setUsersLoading(false); }
  }, [id]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (activeTab === 'users') void loadUsers(); }, [activeTab, loadUsers]);

  async function handleSuspend() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/suspend`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: suspendReason }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setSuspendOpen(false); setSuspendReason(''); void load();
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); }
    finally { setActionLoading(false); }
  }

  async function handleActivate() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}/activate`, { method: 'POST' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      void load();
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); }
    finally { setActionLoading(false); }
  }

  async function handleDelete() {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/companies/${id}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      void router.push(adminHref('/admin/companies'));
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); setActionLoading(false); }
  }

  return (
    <AdminLayout title="Company Detail">
      <button onClick={() => void router.push(adminHref('/admin/companies'))}
        className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-900 dark:hover:text-white mb-5 transition-colors">
        <ArrowLeft className="w-4 h-4" /> Back to Companies
      </button>

      {[error, actionError].filter(Boolean).map((msg, i) => (
        <div key={i} className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {msg}
        </div>
      ))}

      {loading && <div className="flex items-center justify-center py-24"><Loader2 className="w-6 h-6 animate-spin text-teal-500" /></div>}

      {company && (
        <>
          <div className="flex items-start justify-between gap-4 mb-6 flex-wrap">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-teal-500/10 rounded-lg"><Building2 className="w-6 h-6 text-teal-500" /></div>
              <div>
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">{company.name}</h2>
                <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[company.status] ?? ''}`}>{company.status}</span>
              </div>
            </div>
            <div className="flex gap-2 flex-wrap">
              {company.status !== 'suspended'
                ? <button onClick={() => setSuspendOpen(true)} disabled={actionLoading}
                    className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-yellow-400 text-yellow-600 hover:bg-yellow-50 dark:hover:bg-yellow-500/10 transition-colors disabled:opacity-50">
                    <ShieldOff className="w-4 h-4" /> Suspend
                  </button>
                : <button onClick={() => void handleActivate()} disabled={actionLoading}
                    className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-teal-400 text-teal-600 hover:bg-teal-50 dark:hover:bg-teal-500/10 transition-colors disabled:opacity-50">
                    <ShieldCheck className="w-4 h-4" /> Activate
                  </button>
              }
              <button onClick={() => setDeleteOpen(true)} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-red-400 text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-colors disabled:opacity-50">
                <Trash2 className="w-4 h-4" /> Delete
              </button>
            </div>
          </div>

          <div className="flex gap-1 mb-5 border-b border-gray-200 dark:border-gray-700">
            {(['info', 'users'] as const).map(tab => (
              <button key={tab} onClick={() => setActiveTab(tab)}
                className={`px-4 py-2 text-sm font-medium capitalize border-b-2 -mb-px transition-colors ${
                  activeTab === tab ? 'border-teal-500 text-teal-600 dark:text-teal-400' : 'border-transparent text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>
                {tab}
              </button>
            ))}
          </div>

          {activeTab === 'info' && (
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-5">
              <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl p-5 shadow-sm">
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-4">Company Information</h3>
                <div className="grid grid-cols-2 gap-4">
                  <Field label="Registration #" value={company.registrationNumber} />
                  <Field label="VAT Number"      value={company.vatNumber} />
                  <Field label="Email"           value={company.email} />
                  <Field label="Phone"           value={company.phone} />
                  <Field label="Created"         value={fmtDate(company.createdAt)} />
                  <Field label="Last Active"     value={fmtDate(company.lastActiveAt)} />
                  <div className="col-span-2"><Field label="Address" value={company.address} /></div>
                </div>
              </div>
              <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl p-5 shadow-sm">
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white mb-4">Subscription</h3>
                <div className="grid grid-cols-2 gap-4">
                  <Field label="Plan"          value={company.plan} />
                  <Field label="Billing Cycle" value={company.billingCycle} />
                  <Field label="Status"        value={company.status} />
                </div>
              </div>
            </div>
          )}

          {activeTab === 'users' && (
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
              {usersLoading
                ? <div className="flex items-center justify-center py-12"><Loader2 className="w-5 h-5 animate-spin text-teal-500" /></div>
                : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                          <th className="px-4 py-3 font-medium">Name</th>
                          <th className="px-4 py-3 font-medium">Email</th>
                          <th className="px-4 py-3 font-medium">Role</th>
                          <th className="px-4 py-3 font-medium">Last Login</th>
                        </tr>
                      </thead>
                      <tbody>
                        {users.length === 0 && <tr><td colSpan={4} className="px-4 py-8 text-center text-gray-400">No users</td></tr>}
                        {users.map(u => (
                          <tr key={u.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0">
                            <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{u.name}</td>
                            <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{u.email}</td>
                            <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{u.role}</td>
                            <td className="px-4 py-3 text-gray-500 dark:text-gray-400">{fmtDate(u.lastLoginAt)}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )
              }
            </div>
          )}
        </>
      )}

      <ConfirmModal
        open={suspendOpen}
        title="Suspend Company"
        message="This will immediately prevent all users from accessing the company. Provide a reason below."
        confirmLabel="Suspend"
        confirmClass="bg-yellow-500 hover:bg-yellow-600"
        loading={actionLoading}
        onConfirm={() => void handleSuspend()}
        onCancel={() => setSuspendOpen(false)}
      >
        <textarea rows={3} value={suspendReason} onChange={e => setSuspendReason(e.target.value)}
          placeholder="Reason for suspension…"
          className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-yellow-500 resize-none"
        />
      </ConfirmModal>

      <ConfirmModal
        open={deleteOpen}
        title="Delete Company"
        message={<>This action is <strong>permanent</strong>. All data for <strong>{company?.name}</strong> will be deleted and cannot be recovered.</>}
        confirmLabel="Delete Permanently"
        loading={actionLoading}
        onConfirm={() => void handleDelete()}
        onCancel={() => setDeleteOpen(false)}
      />
    </AdminLayout>
  );
}

/**
 * Admin — User List
 * Search, filter by role and status, paginate.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { useRouter } from 'next/router';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { Search, AlertCircle, Loader2, ChevronLeft, ChevronRight } from 'lucide-react';

interface AdminUser {
  id: string;
  name: string;
  email: string;
  role: string;
  companyCount: number;
  lastLoginAt: string | null;
  status: 'active' | 'suspended' | 'inactive';
  createdAt: string;
}

interface PagedResponse {
  items: AdminUser[];
  total: number;
  page: number;
  limit: number;
}

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  suspended: 'bg-red-500/10 text-red-500',
  inactive:  'bg-gray-500/10 text-gray-500',
};

const ROLES = ['super_admin', 'admin', 'manager', 'storeman', 'technician', 'viewer'];

function fmtDate(d: string | null) {
  if (!d) return '—';
  return new Date(d).toLocaleDateString('en-ZA');
}

const LIMIT = 25;

export default function AdminUsersPage() {
  const router = useRouter();
  const adminHref = useAdminHref();

  const [rows, setRows]       = useState<AdminUser[]>([]);
  const [total, setTotal]     = useState(0);
  const [page, setPage]       = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError]     = useState('');
  const [search, setSearch]   = useState('');
  const [role, setRole]       = useState('');
  const [status, setStatus]   = useState('');

  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const load = useCallback(async (q: string, r: string, st: string, pg: number) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ page: String(pg), limit: String(LIMIT) });
      if (q)  params.set('search', q);
      if (r)  params.set('role', r);
      if (st) params.set('status', st);
      const res  = await apiFetch(`/api/admin/users?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load users');
      const d = json.data as PagedResponse;
      setRows(d.items);
      setTotal(d.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      void load(search, role, status, 1);
    }, 300);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [search, role, status, load]);

  useEffect(() => {
    void load(search, role, status, page);
  }, [page]); // eslint-disable-line react-hooks/exhaustive-deps

  const totalPages = Math.max(1, Math.ceil(total / LIMIT));

  return (
    <AdminLayout title="Users">
      {/* Filters */}
      <div className="flex gap-3 flex-wrap mb-5">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input
            type="text"
            placeholder="Search name or email…"
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500"
          />
        </div>
        <select
          value={role}
          onChange={e => { setRole(e.target.value); setPage(1); }}
          className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
        >
          <option value="">All roles</option>
          {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
        </select>
        <select
          value={status}
          onChange={e => { setStatus(e.target.value); setPage(1); }}
          className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
        >
          <option value="">All statuses</option>
          <option value="active">Active</option>
          <option value="suspended">Suspended</option>
          <option value="inactive">Inactive</option>
        </select>
        <span className="ml-auto text-sm text-gray-500 dark:text-gray-400 self-center">{total} total</span>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <th className="px-4 py-3 font-medium">Name</th>
                <th className="px-4 py-3 font-medium">Email</th>
                <th className="px-4 py-3 font-medium">Role</th>
                <th className="px-4 py-3 font-medium">Companies</th>
                <th className="px-4 py-3 font-medium">Last Login</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium">Created</th>
              </tr>
            </thead>
            <tbody>
              {loading && rows.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-12 text-center">
                    <Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" />
                  </td>
                </tr>
              )}
              {!loading && rows.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-12 text-center text-gray-400">No users found</td>
                </tr>
              )}
              {rows.map(u => (
                <tr
                  key={u.id}
                  className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 cursor-pointer transition-colors"
                  onClick={() => void router.push(adminHref(`/admin/users/${u.id}`))}
                >
                  <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{u.name}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{u.email}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{u.role}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{u.companyCount}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(u.lastLoginAt)}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[u.status] ?? ''}`}>
                      {u.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(u.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700 text-sm">
          <span className="text-gray-500 dark:text-gray-400">Page {page} of {totalPages}</span>
          <div className="flex gap-2">
            <button
              disabled={page <= 1}
              onClick={() => setPage(p => p - 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button
              disabled={page >= totalPages}
              onClick={() => setPage(p => p + 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin — User Detail
 * Profile, company memberships, and admin actions.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import {
  ArrowLeft, AlertCircle, Loader2, User,
  ShieldOff, ShieldCheck, KeyRound, LogOut, Pencil, Check, X,
} from 'lucide-react';

interface UserDetail {
  id: string; firstName: string; lastName: string;
  email: string; phone: string | null; role: string;
  status: 'active' | 'suspended' | 'inactive';
  lastLoginAt: string | null; loginCount: number; createdAt: string;
}

interface UserCompany { id: string; name: string; role: string; status: string; }

const ROLES = ['super_admin', 'admin', 'manager', 'storeman', 'technician', 'viewer'];

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  suspended: 'bg-red-500/10 text-red-500',
  inactive:  'bg-gray-500/10 text-gray-500',
};

const fmtDate = (d: string | null) => d ? new Date(d).toLocaleDateString('en-ZA') : '—';

function Field({ label, value }: { label: string; value: string | null | undefined }) {
  return (
    <div>
      <p className="text-xs text-gray-500 dark:text-gray-400 mb-0.5">{label}</p>
      <p className="text-sm text-gray-900 dark:text-white">{value || '—'}</p>
    </div>
  );
}

export default function AdminUserDetailPage() {
  const router = useRouter();
  const adminHref = useAdminHref();
  const { id } = router.query;

  const [user, setUser]           = useState<UserDetail | null>(null);
  const [companies, setCompanies] = useState<UserCompany[]>([]);
  const [loading, setLoading]     = useState(true);
  const [companiesLoading, setCompaniesLoading] = useState(false);
  const [error, setError]         = useState('');
  const [activeTab, setActiveTab] = useState<'profile' | 'companies'>('profile');
  const [actionLoading, setActionLoading] = useState(false);
  const [actionError, setActionError]     = useState('');
  const [editing, setEditing]     = useState(false);
  const [editFirstName, setEditFirstName] = useState('');
  const [editLastName, setEditLastName]   = useState('');
  const [editPhone, setEditPhone]         = useState('');
  const [editRole, setEditRole]           = useState('');

  const load = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setLoading(true); setError('');
    try {
      const res  = await apiFetch(`/api/admin/users/${id}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load user');
      const u = json.data as UserDetail;
      setUser(u);
      setEditFirstName(u.firstName); setEditLastName(u.lastName);
      setEditPhone(u.phone ?? '');   setEditRole(u.role);
    } catch (err) { setError(err instanceof Error ? err.message : 'Failed'); }
    finally { setLoading(false); }
  }, [id]);

  const loadCompanies = useCallback(async () => {
    if (!id || typeof id !== 'string') return;
    setCompaniesLoading(true);
    try {
      const res  = await apiFetch(`/api/admin/users/${id}/companies`);
      const json = await res.json();
      if (res.ok) setCompanies((json.data as UserCompany[]) || []);
    } catch { /* non-critical */ }
    finally { setCompaniesLoading(false); }
  }, [id]);

  useEffect(() => { void load(); }, [load]);
  useEffect(() => { if (activeTab === 'companies') void loadCompanies(); }, [activeTab, loadCompanies]);

  async function doAction(endpoint: string, method = 'POST', body?: object) {
    if (!id || typeof id !== 'string') return;
    setActionLoading(true); setActionError('');
    try {
      const res  = await apiFetch(`/api/admin/users/${id}/${endpoint}`, {
        method,
        ...(body ? { headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) } : {}),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      return true;
    } catch (err) { setActionError(err instanceof Error ? err.message : 'Failed'); return false; }
    finally { setActionLoading(false); }
  }

  async function handleSaveEdit() {
    const ok = await doAction('', 'PATCH', {
      firstName: editFirstName, lastName: editLastName,
      phone: editPhone, role: editRole,
    });
    if (ok) { setEditing(false); void load(); }
  }

  async function handleResetPassword() {
    if (!confirm('Send password reset email to this user?')) return;
    await doAction('reset-password');
  }

  async function handleToggleSuspend() {
    const action = user?.status === 'suspended' ? 'activate' : 'suspend';
    if (!confirm(`${action === 'activate' ? 'Activate' : 'Suspend'} this user?`)) return;
    const ok = await doAction(action);
    if (ok) void load();
  }

  async function handleForceLogout() {
    if (!confirm('Force logout this user from all sessions?')) return;
    await doAction('force-logout');
  }

  return (
    <AdminLayout title="User Detail">
      <button onClick={() => void router.push(adminHref('/admin/users'))}
        className="inline-flex items-center gap-1 text-sm text-gray-500 hover:text-gray-900 dark:hover:text-white mb-5 transition-colors">
        <ArrowLeft className="w-4 h-4" /> Back to Users
      </button>

      {[error, actionError].filter(Boolean).map((msg, i) => (
        <div key={i} className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {msg}
        </div>
      ))}

      {loading && <div className="flex items-center justify-center py-24"><Loader2 className="w-6 h-6 animate-spin text-teal-500" /></div>}

      {user && (
        <>
          <div className="flex items-start justify-between gap-4 mb-6 flex-wrap">
            <div className="flex items-center gap-3">
              <div className="w-12 h-12 rounded-full bg-teal-600 flex items-center justify-center flex-shrink-0">
                <User className="w-6 h-6 text-white" />
              </div>
              <div>
                <h2 className="text-xl font-bold text-gray-900 dark:text-white">{user.firstName} {user.lastName}</h2>
                <p className="text-sm text-gray-500 dark:text-gray-400">{user.email}</p>
                <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[user.status] ?? ''}`}>{user.status}</span>
              </div>
            </div>
            <div className="flex gap-2 flex-wrap">
              <button onClick={() => setEditing(e => !e)} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-gray-300 dark:border-gray-600 text-gray-600 dark:text-gray-300 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors disabled:opacity-50">
                <Pencil className="w-4 h-4" /> Edit
              </button>
              <button onClick={() => void handleResetPassword()} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-blue-400 text-blue-500 hover:bg-blue-50 dark:hover:bg-blue-500/10 transition-colors disabled:opacity-50">
                <KeyRound className="w-4 h-4" /> Reset Password
              </button>
              <button onClick={() => void handleToggleSuspend()} disabled={actionLoading}
                className={`inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border transition-colors disabled:opacity-50 ${
                  user.status === 'suspended'
                    ? 'border-teal-400 text-teal-600 hover:bg-teal-50 dark:hover:bg-teal-500/10'
                    : 'border-yellow-400 text-yellow-600 hover:bg-yellow-50 dark:hover:bg-yellow-500/10'}`}>
                {user.status === 'suspended' ? <><ShieldCheck className="w-4 h-4" /> Activate</> : <><ShieldOff className="w-4 h-4" /> Suspend</>}
              </button>
              <button onClick={() => void handleForceLogout()} disabled={actionLoading}
                className="inline-flex items-center gap-2 px-3 py-2 text-sm font-medium rounded-lg border border-red-400 text-red-500 hover:bg-red-50 dark:hover:bg-red-500/10 transition-colors disabled:opacity-50">
                <LogOut className="w-4 h-4" /> Force Logout
              </button>
            </div>
          </div>

          <div className="flex gap-1 mb-5 border-b border-gray-200 dark:border-gray-700">
            {(['profile', 'companies'] as const).map(tab => (
              <button key={tab} onClick={() => setActiveTab(tab)}
                className={`px-4 py-2 text-sm font-medium capitalize border-b-2 -mb-px transition-colors ${
                  activeTab === tab ? 'border-teal-500 text-teal-600 dark:text-teal-400' : 'border-transparent text-gray-500 hover:text-gray-900 dark:hover:text-white'}`}>
                {tab}
              </button>
            ))}
          </div>

          {activeTab === 'profile' && (
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl p-5 shadow-sm">
              <div className="flex items-center justify-between mb-4">
                <h3 className="text-sm font-semibold text-gray-900 dark:text-white">Profile Information</h3>
                {editing && (
                  <div className="flex gap-2">
                    <button onClick={() => void handleSaveEdit()} disabled={actionLoading}
                      className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium bg-teal-600 hover:bg-teal-700 text-white rounded-lg disabled:opacity-50 transition-colors">
                      {actionLoading ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Check className="w-3.5 h-3.5" />} Save
                    </button>
                    <button onClick={() => setEditing(false)}
                      className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium text-gray-600 dark:text-gray-300 border border-gray-200 dark:border-gray-700 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                      <X className="w-3.5 h-3.5" /> Cancel
                    </button>
                  </div>
                )}
              </div>
              {editing ? (
                <div className="grid grid-cols-2 gap-4">
                  {[
                    ['First Name', editFirstName, setEditFirstName],
                    ['Last Name',  editLastName,  setEditLastName],
                    ['Phone',      editPhone,     setEditPhone],
                  ].map(([label, value, setter]) => (
                    <div key={label as string}>
                      <label className="text-xs text-gray-500 dark:text-gray-400 block mb-1">{label as string}</label>
                      <input value={value as string} onChange={e => (setter as (v: string) => void)(e.target.value)}
                        className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
                    </div>
                  ))}
                  <div>
                    <label className="text-xs text-gray-500 dark:text-gray-400 block mb-1">Role</label>
                    <select value={editRole} onChange={e => setEditRole(e.target.value)}
                      className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
                      {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                    </select>
                  </div>
                </div>
              ) : (
                <div className="grid grid-cols-2 lg:grid-cols-3 gap-4">
                  <Field label="First Name"  value={user.firstName} />
                  <Field label="Last Name"   value={user.lastName} />
                  <Field label="Email"       value={user.email} />
                  <Field label="Phone"       value={user.phone} />
                  <Field label="Role"        value={user.role} />
                  <Field label="Status"      value={user.status} />
                  <Field label="Last Login"  value={fmtDate(user.lastLoginAt)} />
                  <Field label="Login Count" value={String(user.loginCount)} />
                  <Field label="Created"     value={fmtDate(user.createdAt)} />
                </div>
              )}
            </div>
          )}

          {activeTab === 'companies' && (
            <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
              {companiesLoading
                ? <div className="flex items-center justify-center py-12"><Loader2 className="w-5 h-5 animate-spin text-teal-500" /></div>
                : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                          <th className="px-4 py-3 font-medium">Company</th>
                          <th className="px-4 py-3 font-medium">Role</th>
                          <th className="px-4 py-3 font-medium">Status</th>
                        </tr>
                      </thead>
                      <tbody>
                        {companies.length === 0 && <tr><td colSpan={3} className="px-4 py-8 text-center text-gray-400">No companies</td></tr>}
                        {companies.map(c => (
                          <tr key={c.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0">
                            <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{c.name}</td>
                            <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{c.role}</td>
                            <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{c.status}</td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )
              }
            </div>
          )}
        </>
      )}
    </AdminLayout>
  );
}

/**
 * Admin — Billing Overview
 * MRR, ARR, subscription KPIs + recent subscriptions table.
 */

import { useState, useEffect, useCallback } from 'react';
import { useRouter } from 'next/router';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { StatsCard } from '@/components/admin/StatsCard';
import { apiFetch } from '@/lib/apiFetch';
import { useAdminHref } from '@/hooks/useAdminPrefix';
import { AlertCircle, Loader2, ArrowRight, CreditCard, List, FileText } from 'lucide-react';

interface BillingOverview {
  mrrCents: number;
  arrCents: number;
  activeSubscriptions: number;
  pastDueSubscriptions: number;
  trialSubscriptions: number;
  churnRatePct: number;
  arpuCents: number;
  totalRevenueCents: number;
  outstandingCents: number;
}

interface RecentSubscription {
  id: string;
  companyName: string;
  planName: string;
  status: string;
  billingCycle: string;
  amountCents: number;
  createdAt: string;
}

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtDate(d: string) {
  return new Date(d).toLocaleDateString('en-ZA');
}

const SUB_STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  past_due:  'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
  paused:    'bg-blue-500/10 text-blue-400',
};

export default function BillingOverviewPage() {
  const router = useRouter();
  const adminHref = useAdminHref();
  const [overview, setOverview]   = useState<BillingOverview | null>(null);
  const [recent, setRecent]       = useState<RecentSubscription[]>([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const [ovRes, subRes] = await Promise.all([
        apiFetch('/api/admin/billing/overview'),
        apiFetch('/api/admin/billing/subscriptions?limit=10'),
      ]);
      const [ovJson, subJson] = await Promise.all([ovRes.json(), subRes.json()]);
      if (!ovRes.ok)  throw new Error(ovJson.message  || 'Failed to load billing overview');
      if (!subRes.ok) throw new Error(subJson.message || 'Failed to load subscriptions');
      setOverview(ovJson.data as BillingOverview);
      setRecent((subJson.data?.items ?? subJson.data ?? []) as RecentSubscription[]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load billing data');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  return (
    <AdminLayout title="Billing Overview">
      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-6">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {loading && !overview && (
        <div className="flex items-center justify-center py-24">
          <Loader2 className="w-6 h-6 animate-spin text-teal-500" />
        </div>
      )}

      {overview && (
        <>
          {/* KPI Grid */}
          <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 mb-8">
            <StatsCard title="MRR"                   value={fmtZAR(overview.mrrCents)} />
            <StatsCard title="ARR"                   value={fmtZAR(overview.arrCents)} />
            <StatsCard title="Active Subscriptions"  value={overview.activeSubscriptions} />
            <StatsCard title="Past Due"              value={overview.pastDueSubscriptions} />
            <StatsCard title="Trials"                value={overview.trialSubscriptions} />
            <StatsCard title="Churn Rate"            value={`${overview.churnRatePct.toFixed(1)}%`} />
            <StatsCard title="ARPU"                  value={fmtZAR(overview.arpuCents)} />
            <StatsCard title="Total Revenue"         value={fmtZAR(overview.totalRevenueCents)} />
            <StatsCard title="Outstanding"           value={fmtZAR(overview.outstandingCents)} />
          </div>

          {/* Quick Links */}
          <div className="flex gap-3 flex-wrap mb-8">
            <button
              onClick={() => void router.push(adminHref('/admin/billing/plans'))}
              className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors"
            >
              <CreditCard className="w-4 h-4" /> Manage Plans <ArrowRight className="w-4 h-4" />
            </button>
            <button
              onClick={() => void router.push(adminHref('/admin/billing/subscriptions'))}
              className="inline-flex items-center gap-2 px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white text-sm font-medium rounded-lg transition-colors"
            >
              <List className="w-4 h-4" /> View Subscriptions <ArrowRight className="w-4 h-4" />
            </button>
            <button
              onClick={() => void router.push(adminHref('/admin/billing/invoices'))}
              className="inline-flex items-center gap-2 px-4 py-2 bg-gray-700 hover:bg-gray-600 text-white text-sm font-medium rounded-lg transition-colors"
            >
              <FileText className="w-4 h-4" /> View Invoices <ArrowRight className="w-4 h-4" />
            </button>
          </div>

          {/* Recent Subscriptions */}
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
            <div className="px-5 py-4 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
              <h2 className="text-sm font-semibold text-gray-900 dark:text-white">Recent Subscriptions</h2>
              <button
                onClick={() => void router.push(adminHref('/admin/billing/subscriptions'))}
                className="text-xs text-teal-500 hover:text-teal-400 transition-colors"
              >
                View all
              </button>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                    <th className="px-5 py-3 font-medium">Company</th>
                    <th className="px-5 py-3 font-medium">Plan</th>
                    <th className="px-5 py-3 font-medium">Status</th>
                    <th className="px-5 py-3 font-medium">Billing Cycle</th>
                    <th className="px-5 py-3 font-medium">Amount</th>
                    <th className="px-5 py-3 font-medium">Created</th>
                  </tr>
                </thead>
                <tbody>
                  {recent.length === 0 && (
                    <tr>
                      <td colSpan={6} className="px-5 py-8 text-center text-gray-400">No subscriptions found</td>
                    </tr>
                  )}
                  {recent.map(sub => (
                    <tr key={sub.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 transition-colors">
                      <td className="px-5 py-3 font-medium text-gray-900 dark:text-white">{sub.companyName}</td>
                      <td className="px-5 py-3 text-gray-600 dark:text-gray-300">{sub.planName}</td>
                      <td className="px-5 py-3">
                        <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${SUB_STATUS_BADGE[sub.status] ?? 'bg-gray-500/10 text-gray-500'}`}>
                          {sub.status.replace('_', ' ')}
                        </span>
                      </td>
                      <td className="px-5 py-3 text-gray-600 dark:text-gray-300 capitalize">{sub.billingCycle}</td>
                      <td className="px-5 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(sub.amountCents)}</td>
                      <td className="px-5 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(sub.createdAt)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      )}
    </AdminLayout>
  );
}

/**
 * Admin — Plan Management
 * Create, edit, and archive billing plans.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2, Plus, Pencil, Archive, X, Check } from 'lucide-react';

interface Plan {
  id: string;
  code: string;
  name: string;
  description: string;
  monthlyPriceCents: number;
  annualPriceCents: number;
  usersLimit: number | null;
  isArchived: boolean;
  features: Record<string, unknown>;
  limits: Record<string, unknown>;
}

interface PlanForm {
  code: string;
  name: string;
  description: string;
  monthly_price: string;
  annual_price: string;
  users_limit: string;
  features: string;
  limits: string;
}

const EMPTY_FORM: PlanForm = {
  code: '', name: '', description: '',
  monthly_price: '', annual_price: '',
  users_limit: '', features: '{}', limits: '{}',
};

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

export default function PlansPage() {
  const [plans, setPlans]         = useState<Plan[]>([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [formError, setFormError] = useState('');
  const [saving, setSaving]       = useState(false);
  const [showForm, setShowForm]   = useState(false);
  const [editId, setEditId]       = useState<string | null>(null);
  const [form, setForm]           = useState<PlanForm>(EMPTY_FORM);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res  = await apiFetch('/api/admin/billing/plans?include_archived=true');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load plans');
      setPlans((json.data ?? []) as Plan[]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load plans');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { void load(); }, [load]);

  function openAdd() {
    setEditId(null);
    setForm(EMPTY_FORM);
    setFormError('');
    setShowForm(true);
  }

  function openEdit(plan: Plan) {
    setEditId(plan.id);
    setForm({
      code:          plan.code,
      name:          plan.name,
      description:   plan.description,
      monthly_price: String(plan.monthlyPriceCents / 100),
      annual_price:  String(plan.annualPriceCents / 100),
      users_limit:   plan.usersLimit != null ? String(plan.usersLimit) : '',
      features:      JSON.stringify(plan.features, null, 2),
      limits:        JSON.stringify(plan.limits, null, 2),
    });
    setFormError('');
    setShowForm(true);
  }

  async function handleSave() {
    setFormError('');
    let features: unknown, limits: unknown;
    try { features = JSON.parse(form.features); } catch { setFormError('Features must be valid JSON'); return; }
    try { limits   = JSON.parse(form.limits);   } catch { setFormError('Limits must be valid JSON'); return; }

    const body = {
      code:               form.code,
      name:               form.name,
      description:        form.description,
      monthly_price_cents: Math.round(parseFloat(form.monthly_price) * 100),
      annual_price_cents:  Math.round(parseFloat(form.annual_price)  * 100),
      users_limit:        form.users_limit ? parseInt(form.users_limit) : null,
      features,
      limits,
    };

    setSaving(true);
    try {
      const res  = editId
        ? await apiFetch(`/api/admin/billing/plans/${editId}`, { method: 'PUT',  body: JSON.stringify(body) })
        : await apiFetch('/api/admin/billing/plans',            { method: 'POST', body: JSON.stringify(body) });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Save failed');
      setShowForm(false);
      void load();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Save failed');
    } finally {
      setSaving(false);
    }
  }

  async function handleArchive(id: string) {
    if (!confirm('Archive this plan? Existing subscriptions will not be affected.')) return;
    try {
      const res  = await apiFetch(`/api/admin/billing/plans/${id}/archive`, { method: 'POST' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Archive failed');
      void load();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Archive failed');
    }
  }

  function field(key: keyof PlanForm, label: string, opts?: { type?: string; rows?: number }) {
    const isTextarea = !!opts?.rows;
    const cls = 'w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500';
    return (
      <div>
        <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">{label}</label>
        {isTextarea
          ? <textarea rows={opts!.rows} value={form[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))} className={cls} />
          : <input type={opts?.type ?? 'text'} value={form[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))} className={cls} />
        }
      </div>
    );
  }

  return (
    <AdminLayout title="Billing Plans">
      <div className="flex items-center justify-between mb-5">
        <span className="text-sm text-gray-500 dark:text-gray-400">{plans.length} plan{plans.length !== 1 ? 's' : ''}</span>
        <button
          onClick={openAdd}
          className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors"
        >
          <Plus className="w-4 h-4" /> Add Plan
        </button>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Plan Form Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl w-full max-w-lg max-h-[90vh] overflow-y-auto">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white">{editId ? 'Edit Plan' : 'Add Plan'}</h3>
              <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><X className="w-4 h-4" /></button>
            </div>
            <div className="p-5 space-y-4">
              {formError && (
                <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-xs">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" /> {formError}
                </div>
              )}
              <div className="grid grid-cols-2 gap-4">
                {field('code', 'Code (e.g. starter)')}
                {field('name', 'Name')}
              </div>
              {field('description', 'Description')}
              <div className="grid grid-cols-3 gap-4">
                {field('monthly_price', 'Monthly Price (R)', { type: 'number' })}
                {field('annual_price',  'Annual Price (R)',  { type: 'number' })}
                {field('users_limit',   'Users Limit',       { type: 'number' })}
              </div>
              {field('features', 'Features (JSON)', { rows: 4 })}
              {field('limits',   'Limits (JSON)',   { rows: 4 })}
            </div>
            <div className="px-5 py-4 border-t border-gray-200 dark:border-gray-700 flex justify-end gap-3">
              <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors">Cancel</button>
              <button
                onClick={() => void handleSave()}
                disabled={saving}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50"
              >
                {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />}
                {editId ? 'Save Changes' : 'Create Plan'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <th className="px-4 py-3 font-medium">Name</th>
                <th className="px-4 py-3 font-medium">Code</th>
                <th className="px-4 py-3 font-medium">Monthly</th>
                <th className="px-4 py-3 font-medium">Annual</th>
                <th className="px-4 py-3 font-medium">Users</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium">Actions</th>
              </tr>
            </thead>
            <tbody>
              {loading && plans.length === 0 && (
                <tr><td colSpan={7} className="px-4 py-12 text-center"><Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" /></td></tr>
              )}
              {!loading && plans.length === 0 && (
                <tr><td colSpan={7} className="px-4 py-12 text-center text-gray-400">No plans found</td></tr>
              )}
              {plans.map(p => (
                <tr key={p.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 transition-colors">
                  <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{p.name}</td>
                  <td className="px-4 py-3 font-mono text-xs text-gray-500 dark:text-gray-400">{p.code}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(p.monthlyPriceCents)}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(p.annualPriceCents)}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{p.usersLimit ?? 'Unlimited'}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded text-xs font-medium ${p.isArchived ? 'bg-gray-500/10 text-gray-500' : 'bg-teal-500/10 text-teal-600 dark:text-teal-400'}`}>
                      {p.isArchived ? 'Archived' : 'Active'}
                    </span>
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-2">
                      <button onClick={() => openEdit(p)} className="p-1.5 rounded text-gray-400 hover:text-teal-500 hover:bg-teal-500/10 transition-colors" title="Edit">
                        <Pencil className="w-3.5 h-3.5" />
                      </button>
                      {!p.isArchived && (
                        <button onClick={() => void handleArchive(p.id)} className="p-1.5 rounded text-gray-400 hover:text-red-400 hover:bg-red-500/10 transition-colors" title="Archive">
                          <Archive className="w-3.5 h-3.5" />
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin — Subscription List
 * Filter, search, paginate subscriptions; add new subscription.
 */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2, Search, ChevronLeft, ChevronRight, Plus, X, Check } from 'lucide-react';

interface Subscription {
  id: string;
  companyId: string;
  companyName: string;
  planName: string;
  status: 'trial' | 'active' | 'past_due' | 'cancelled' | 'paused';
  billingCycle: string;
  discountPct: number;
  amountCents: number;
  periodEnd: string | null;
  createdAt: string;
}

interface Plan {
  id: string;
  name: string;
  code: string;
}

interface PagedResponse {
  items: Subscription[];
  total: number;
  page: number;
  limit: number;
}

interface SubForm {
  company_id: string;
  plan_id: string;
  billing_cycle: string;
  discount_pct: string;
}

const EMPTY_FORM: SubForm = { company_id: '', plan_id: '', billing_cycle: 'monthly', discount_pct: '0' };

const STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  past_due:  'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
  paused:    'bg-blue-500/10 text-blue-400',
};

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtDate(d: string | null) {
  if (!d) return '—';
  return new Date(d).toLocaleDateString('en-ZA');
}

export default function SubscriptionsPage() {
  const [rows, setRows]         = useState<Subscription[]>([]);
  const [total, setTotal]       = useState(0);
  const [page, setPage]         = useState(1);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState('');
  const [search, setSearch]     = useState('');
  const [status, setStatus]     = useState('');
  const [plans, setPlans]       = useState<Plan[]>([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm]         = useState<SubForm>(EMPTY_FORM);
  const [formError, setFormError] = useState('');
  const [saving, setSaving]     = useState(false);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const LIMIT = 25;

  const load = useCallback(async (q: string, st: string, pg: number) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ page: String(pg), limit: String(LIMIT) });
      if (q)  params.set('search', q);
      if (st) params.set('status', st);
      const res  = await apiFetch(`/api/admin/billing/subscriptions?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load subscriptions');
      const d = json.data as PagedResponse;
      setRows(d.items);
      setTotal(d.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, []);

  const loadPlans = useCallback(async () => {
    try {
      const res  = await apiFetch('/api/admin/billing/plans');
      const json = await res.json();
      if (res.ok) setPlans((json.data ?? []) as Plan[]);
    } catch { /* non-critical */ }
  }, []);

  useEffect(() => { void loadPlans(); }, [loadPlans]);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      void load(search, status, 1);
    }, 300);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [search, status, load]);

  useEffect(() => { void load(search, status, page); }, [page]); // eslint-disable-line react-hooks/exhaustive-deps

  const totalPages = Math.max(1, Math.ceil(total / LIMIT));

  async function handleAdd() {
    setFormError('');
    if (!form.company_id.trim()) { setFormError('Company ID is required'); return; }
    if (!form.plan_id)           { setFormError('Plan is required'); return; }
    setSaving(true);
    try {
      const res  = await apiFetch('/api/admin/billing/subscriptions', {
        method: 'POST',
        body: JSON.stringify({
          company_id:    form.company_id,
          plan_id:       form.plan_id,
          billing_cycle: form.billing_cycle,
          discount_pct:  parseFloat(form.discount_pct) || 0,
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to create subscription');
      setShowForm(false);
      setForm(EMPTY_FORM);
      void load(search, status, 1);
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setSaving(false);
    }
  }

  return (
    <AdminLayout title="Subscriptions">
      {/* Toolbar */}
      <div className="flex gap-3 flex-wrap mb-5">
        <div className="relative flex-1 min-w-[200px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Search company…" value={search} onChange={e => setSearch(e.target.value)}
            className="w-full pl-9 pr-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500" />
        </div>
        <select value={status} onChange={e => { setStatus(e.target.value); setPage(1); }}
          className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
          <option value="">All statuses</option>
          <option value="trial">Trial</option>
          <option value="active">Active</option>
          <option value="past_due">Past Due</option>
          <option value="cancelled">Cancelled</option>
          <option value="paused">Paused</option>
        </select>
        <span className="text-sm text-gray-500 dark:text-gray-400 self-center ml-auto">{total} total</span>
        <button onClick={() => { setShowForm(true); setFormError(''); setForm(EMPTY_FORM); }}
          className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors">
          <Plus className="w-4 h-4" /> Add Subscription
        </button>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Add Subscription Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl w-full max-w-md">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white">Add Subscription</h3>
              <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><X className="w-4 h-4" /></button>
            </div>
            <div className="p-5 space-y-4">
              {formError && (
                <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-xs">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" /> {formError}
                </div>
              )}
              <div>
                <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Company ID</label>
                <input type="text" value={form.company_id} onChange={e => setForm(f => ({ ...f, company_id: e.target.value }))}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500" />
              </div>
              <div>
                <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Plan</label>
                <select value={form.plan_id} onChange={e => setForm(f => ({ ...f, plan_id: e.target.value }))}
                  className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
                  <option value="">Select a plan…</option>
                  {plans.map(p => <option key={p.id} value={p.id}>{p.name} ({p.code})</option>)}
                </select>
              </div>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Billing Cycle</label>
                  <select value={form.billing_cycle} onChange={e => setForm(f => ({ ...f, billing_cycle: e.target.value }))}
                    className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500">
                    <option value="monthly">Monthly</option>
                    <option value="annual">Annual</option>
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Discount %</label>
                  <input type="number" min="0" max="100" value={form.discount_pct} onChange={e => setForm(f => ({ ...f, discount_pct: e.target.value }))}
                    className="w-full px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500" />
                </div>
              </div>
            </div>
            <div className="px-5 py-4 border-t border-gray-200 dark:border-gray-700 flex justify-end gap-3">
              <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors">Cancel</button>
              <button onClick={() => void handleAdd()} disabled={saving}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50">
                {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />} Create
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <th className="px-4 py-3 font-medium">Company</th>
                <th className="px-4 py-3 font-medium">Plan</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3 font-medium">Cycle</th>
                <th className="px-4 py-3 font-medium">Discount</th>
                <th className="px-4 py-3 font-medium">Amount</th>
                <th className="px-4 py-3 font-medium">Period End</th>
                <th className="px-4 py-3 font-medium">Created</th>
              </tr>
            </thead>
            <tbody>
              {loading && rows.length === 0 && (
                <tr><td colSpan={8} className="px-4 py-12 text-center"><Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" /></td></tr>
              )}
              {!loading && rows.length === 0 && (
                <tr><td colSpan={8} className="px-4 py-12 text-center text-gray-400">No subscriptions found</td></tr>
              )}
              {rows.map(s => (
                <tr key={s.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 transition-colors">
                  <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{s.companyName}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{s.planName}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[s.status] ?? 'bg-gray-500/10 text-gray-500'}`}>
                      {s.status.replace('_', ' ')}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">{s.billingCycle}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300">{s.discountPct > 0 ? `${s.discountPct}%` : '—'}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(s.amountCents)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(s.periodEnd)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(s.createdAt)}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700 text-sm">
          <span className="text-gray-500 dark:text-gray-400">Page {page} of {totalPages}</span>
          <div className="flex gap-2">
            <button disabled={page <= 1} onClick={() => setPage(p => p - 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

/** Admin — Invoice List: filter by status/date, paginate, send drafts, mark paid, create invoices. */

import { useState, useEffect, useCallback, useRef } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2, Search, ChevronLeft, ChevronRight, Plus, X, Check, Send, CreditCard } from 'lucide-react';

interface Invoice {
  id: string; invoiceNumber: string; companyId: string; companyName: string;
  status: 'draft' | 'sent' | 'paid' | 'overdue' | 'cancelled' | 'credited';
  subtotalCents: number; taxCents: number; totalCents: number;
  dueDate: string | null; paidAt: string | null; createdAt: string;
}

interface PagedResponse {
  items: Invoice[];
  total: number;
  page: number;
  limit: number;
}

interface InvForm {
  company_id: string;
  subtotal: string;
  tax: string;
  total: string;
  due_date: string;
  notes: string;
}

const EMPTY_FORM: InvForm = { company_id: '', subtotal: '', tax: '0', total: '', due_date: '', notes: '' };

const STATUS_BADGE: Record<string, string> = {
  draft:      'bg-gray-500/10 text-gray-500',
  sent:       'bg-blue-500/10 text-blue-400',
  paid:       'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  overdue:    'bg-red-500/10 text-red-500',
  cancelled:  'bg-gray-500/10 text-gray-500',
  credited:   'bg-purple-500/10 text-purple-400',
};

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtDate(d: string | null) {
  if (!d) return '—';
  return new Date(d).toLocaleDateString('en-ZA');
}

export default function InvoicesPage() {
  const [rows, setRows]           = useState<Invoice[]>([]);
  const [total, setTotal]         = useState(0);
  const [page, setPage]           = useState(1);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [search, setSearch]       = useState('');
  const [status, setStatus]       = useState('');
  const [dateFrom, setDateFrom]   = useState('');
  const [dateTo, setDateTo]       = useState('');
  const [showForm, setShowForm]   = useState(false);
  const [form, setForm]           = useState<InvForm>(EMPTY_FORM);
  const [formError, setFormError] = useState('');
  const [saving, setSaving]       = useState(false);
  const [actionId, setActionId]   = useState<string | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const LIMIT = 25;

  const load = useCallback(async (q: string, st: string, from: string, to: string, pg: number) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ page: String(pg), limit: String(LIMIT) });
      if (q)    params.set('search',    q);
      if (st)   params.set('status',    st);
      if (from) params.set('date_from', from);
      if (to)   params.set('date_to',   to);
      const res  = await apiFetch(`/api/admin/billing/invoices?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load invoices');
      const d = json.data as PagedResponse;
      setRows(d.items);
      setTotal(d.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = setTimeout(() => {
      setPage(1);
      void load(search, status, dateFrom, dateTo, 1);
    }, 300);
    return () => { if (debounceRef.current) clearTimeout(debounceRef.current); };
  }, [search, status, dateFrom, dateTo, load]);

  useEffect(() => { void load(search, status, dateFrom, dateTo, page); }, [page]); // eslint-disable-line react-hooks/exhaustive-deps

  const totalPages = Math.max(1, Math.ceil(total / LIMIT));

  async function handleAction(id: string, action: 'send' | 'mark_paid') {
    setActionId(id);
    try {
      const res  = await apiFetch(`/api/admin/billing/invoices/${id}/${action}`, { method: 'POST' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Action failed');
      void load(search, status, dateFrom, dateTo, page);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Action failed');
    } finally {
      setActionId(null);
    }
  }

  async function handleCreate() {
    setFormError('');
    if (!form.company_id.trim()) { setFormError('Company ID is required'); return; }
    if (!form.subtotal)          { setFormError('Subtotal is required'); return; }
    if (!form.total)             { setFormError('Total is required'); return; }
    setSaving(true);
    try {
      const res  = await apiFetch('/api/admin/billing/invoices', {
        method: 'POST',
        body: JSON.stringify({
          company_id:     form.company_id,
          subtotal_cents: Math.round(parseFloat(form.subtotal) * 100),
          tax_cents:      Math.round(parseFloat(form.tax || '0') * 100),
          total_cents:    Math.round(parseFloat(form.total) * 100),
          due_date:       form.due_date || null,
          notes:          form.notes || null,
        }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to create invoice');
      setShowForm(false);
      setForm(EMPTY_FORM);
      void load(search, status, dateFrom, dateTo, 1);
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setSaving(false);
    }
  }

  const inputCls = 'px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-teal-500';

  return (
    <AdminLayout title="Invoices">
      {/* Toolbar */}
      <div className="flex gap-3 flex-wrap mb-5">
        <div className="relative flex-1 min-w-[180px] max-w-xs">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
          <input type="text" placeholder="Search company or invoice #…" value={search} onChange={e => setSearch(e.target.value)}
            className={`w-full pl-9 pr-3 ${inputCls}`} />
        </div>
        <select value={status} onChange={e => { setStatus(e.target.value); setPage(1); }} className={inputCls}>
          <option value="">All statuses</option>
          <option value="draft">Draft</option>
          <option value="sent">Sent</option>
          <option value="paid">Paid</option>
          <option value="overdue">Overdue</option>
          <option value="cancelled">Cancelled</option>
          <option value="credited">Credited</option>
        </select>
        <input type="date" value={dateFrom} onChange={e => { setDateFrom(e.target.value); setPage(1); }} className={inputCls} title="From date" />
        <input type="date" value={dateTo}   onChange={e => { setDateTo(e.target.value);   setPage(1); }} className={inputCls} title="To date" />
        <span className="text-sm text-gray-500 dark:text-gray-400 self-center ml-auto">{total} total</span>
        <button onClick={() => { setShowForm(true); setFormError(''); setForm(EMPTY_FORM); }}
          className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors">
          <Plus className="w-4 h-4" /> Create Invoice
        </button>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Create Invoice Modal */}
      {showForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm p-4">
          <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-xl w-full max-w-md">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-200 dark:border-gray-700">
              <h3 className="text-sm font-semibold text-gray-900 dark:text-white">Create Invoice</h3>
              <button onClick={() => setShowForm(false)} className="text-gray-400 hover:text-gray-600 dark:hover:text-gray-200"><X className="w-4 h-4" /></button>
            </div>
            <div className="p-5 space-y-4">
              {formError && (
                <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-xs">
                  <AlertCircle className="w-4 h-4 flex-shrink-0" /> {formError}
                </div>
              )}
              {(['company_id', 'subtotal', 'tax', 'total', 'due_date'] as const).map((key, i) => {
                const labels = ['Company ID', 'Subtotal (R)', 'Tax (R)', 'Total (R)', 'Due Date'];
                const types  = ['text', 'number', 'number', 'number', 'date'];
                return (
                  <div key={key}>
                    <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">{labels[i]}</label>
                    <input type={types[i]} value={form[key]} onChange={e => setForm(f => ({ ...f, [key]: e.target.value }))} className={`w-full ${inputCls}`} />
                  </div>
                );
              })}
              <div>
                <label className="block text-xs font-medium text-gray-500 dark:text-gray-400 mb-1">Notes</label>
                <textarea rows={3} value={form.notes} onChange={e => setForm(f => ({ ...f, notes: e.target.value }))}
                  className={`w-full ${inputCls}`} />
              </div>
            </div>
            <div className="px-5 py-4 border-t border-gray-200 dark:border-gray-700 flex justify-end gap-3">
              <button onClick={() => setShowForm(false)} className="px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white transition-colors">Cancel</button>
              <button onClick={() => void handleCreate()} disabled={saving}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white text-sm font-medium rounded-lg transition-colors disabled:opacity-50">
                {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Check className="w-4 h-4" />} Create
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                {['Invoice #','Company','Status','Subtotal','Tax','Total','Due Date','Paid At','Created','Actions'].map(h => (
                  <th key={h} className="px-4 py-3 font-medium">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {loading && rows.length === 0 && (
                <tr><td colSpan={10} className="px-4 py-12 text-center"><Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" /></td></tr>
              )}
              {!loading && rows.length === 0 && (
                <tr><td colSpan={10} className="px-4 py-12 text-center text-gray-400">No invoices found</td></tr>
              )}
              {rows.map(inv => (
                <tr key={inv.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40 transition-colors">
                  <td className="px-4 py-3 font-mono text-xs text-gray-600 dark:text-gray-300">{inv.invoiceNumber}</td>
                  <td className="px-4 py-3 font-medium text-gray-900 dark:text-white">{inv.companyName}</td>
                  <td className="px-4 py-3">
                    <span className={`px-2 py-0.5 rounded text-xs font-medium capitalize ${STATUS_BADGE[inv.status] ?? 'bg-gray-500/10 text-gray-500'}`}>{inv.status}</span>
                  </td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(inv.subtotalCents)}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs">{fmtZAR(inv.taxCents)}</td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 font-mono text-xs font-semibold">{fmtZAR(inv.totalCents)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(inv.dueDate)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(inv.paidAt)}</td>
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap">{fmtDate(inv.createdAt)}</td>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-1.5">
                      {inv.status === 'draft' && (
                        <button onClick={() => void handleAction(inv.id, 'send')} disabled={actionId === inv.id}
                          className="p-1.5 rounded text-gray-400 hover:text-blue-400 hover:bg-blue-500/10 transition-colors disabled:opacity-40" title="Send">
                          {actionId === inv.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <Send className="w-3.5 h-3.5" />}
                        </button>
                      )}
                      {(inv.status === 'sent' || inv.status === 'overdue') && (
                        <button onClick={() => void handleAction(inv.id, 'mark_paid')} disabled={actionId === inv.id}
                          className="p-1.5 rounded text-gray-400 hover:text-teal-400 hover:bg-teal-500/10 transition-colors disabled:opacity-40" title="Mark Paid">
                          {actionId === inv.id ? <Loader2 className="w-3.5 h-3.5 animate-spin" /> : <CreditCard className="w-3.5 h-3.5" />}
                        </button>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700 text-sm">
          <span className="text-gray-500 dark:text-gray-400">Page {page} of {totalPages}</span>
          <div className="flex gap-2">
            <button disabled={page <= 1} onClick={() => setPage(p => p - 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button disabled={page >= totalPages} onClick={() => setPage(p => p + 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors">
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * Admin Usage Analytics — DAU/WAU/MAU, feature adoption, revenue by plan, churn signals.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { StatsCard } from '@/components/admin/StatsCard';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2 } from 'lucide-react';

interface UsageAnalytics {
  dau: number;
  wau: number;
  mau: number;
  stickiness_percent: number;
  top_pages: Array<{ path: string; views: number }>;
  feature_adoption: Array<{ feature: string; adoption_percent: number; user_count: number }>;
  revenue_by_plan: Array<{ plan_name: string; mrr_cents: number; company_count: number }>;
