      log.error('Failed to create invoice', { error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to create invoice');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET', 'POST']);
}

