  target_ids: '', starts_at: '', ends_at: '', is_dismissible: true,
} as const;

export type AnnouncementFormState = {
  title: string;
  message: string;
  type: string;
  target: string;
  target_ids: string;
  starts_at: string;
  ends_at: string;
  is_dismissible: boolean;
};

interface Props {
  initial: AnnouncementFormState;
  onClose: () => void;
  onSave: (data: AnnouncementFormState) => Promise<void>;
  saving: boolean;
}

const INPUT_CLS =
  'w-full rounded-lg border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-700 text-sm px-3 py-2 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500';

export function AnnouncementModal({ initial, onClose, onSave, saving }: Props) {
  const [form, setForm] = useState<AnnouncementFormState>(initial);
  const set = <K extends keyof AnnouncementFormState>(k: K, v: AnnouncementFormState[K]) =>
    setForm((f) => ({ ...f, [k]: v }));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-lg mx-4 p-6 space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
            {initial.title ? 'Edit Announcement' : 'New Announcement'}
          </h2>
          <button onClick={onClose} className="text-gray-400 hover:text-gray-600">
            <X className="w-5 h-5" />
          </button>
        </div>

        <div className="space-y-3">
          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Title</label>
            <input value={form.title} onChange={e => set('title', e.target.value)} className={INPUT_CLS} />
          </div>

          <div>
            <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Message</label>
            <textarea rows={3} value={form.message} onChange={e => set('message', e.target.value)}
              className={`${INPUT_CLS} resize-none`} />
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Type</label>
              <select value={form.type} onChange={e => set('type', e.target.value)} className={INPUT_CLS}>
                <option value="info">Info</option>
                <option value="warning">Warning</option>
                <option value="maintenance">Maintenance</option>
                <option value="feature">Feature</option>
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Target</label>
              <select value={form.target} onChange={e => set('target', e.target.value)} className={INPUT_CLS}>
                <option value="all">All</option>
                <option value="plan">Plan</option>
                <option value="company">Company</option>
              </select>
            </div>
          </div>

          {form.target !== 'all' && (
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Target IDs (comma-separated UUIDs)
              </label>
              <input value={form.target_ids} onChange={e => set('target_ids', e.target.value)}
                placeholder="uuid1, uuid2, ..." className={INPUT_CLS} />
            </div>
          )}

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">Starts At</label>
              <input type="datetime-local" value={form.starts_at}
                onChange={e => set('starts_at', e.target.value)} className={INPUT_CLS} />
            </div>
            <div>
              <label className="block text-xs font-medium text-gray-600 dark:text-gray-400 mb-1">
                Ends At (optional)
              </label>
              <input type="datetime-local" value={form.ends_at}
                onChange={e => set('ends_at', e.target.value)} className={INPUT_CLS} />
            </div>
          </div>

          <label className="flex items-center gap-2 text-sm text-gray-700 dark:text-gray-300 cursor-pointer">
            <input type="checkbox" checked={form.is_dismissible}
              onChange={e => set('is_dismissible', e.target.checked)}
              className="rounded border-gray-300 text-teal-600 focus:ring-teal-500" />
            Dismissible by users
          </label>
        </div>

        <div className="flex justify-end gap-2 pt-2">
          <button onClick={onClose}
            className="px-4 py-2 text-sm text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white">
            Cancel
          </button>
          <button
            onClick={() => onSave(form)}
            disabled={saving || !form.title || !form.message || !form.starts_at}
            className="px-4 py-2 text-sm font-medium bg-teal-600 text-white rounded-lg hover:bg-teal-700 disabled:opacity-50 flex items-center gap-2"
          >
            {saving && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
            Save
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Admin Dashboard Service
 * Aggregates platform-wide KPIs for the ISAFlow Admin Platform.
 * Queries: company counts, user counts, MRR/ARR, recent activity.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { DashboardStats, ActivityEvent } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toISOString(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

/**
 * Fetch platform-wide dashboard statistics.
 * Runs aggregate queries in parallel for performance.
 */
export async function getDashboardStats(): Promise<DashboardStats> {
  const [companyStats, userStats, mrrStats, signupCount, recentActivity] =
    await Promise.all([
      getCompanyStats(),
      getUserStats(),
      getMrrStats(),
      getNewSignupCount(),
      getRecentActivity(),
    ]);

  const stats: DashboardStats = {
    total_companies: companyStats.total,
    active_companies: companyStats.active,
    total_users: userStats.total,
    active_users_30d: userStats.active_30d,
    mrr_cents: mrrStats.mrr_cents,
    arr_cents: mrrStats.arr_cents,
    new_signups_30d: signupCount,
    recent_activity: recentActivity,
  };

  log.info('Admin dashboard stats fetched', {
    total_companies: stats.total_companies,
    active_companies: stats.active_companies,
    total_users: stats.total_users,
    mrr_cents: stats.mrr_cents,
  }, 'AdminDashboardService');

  return stats;
}

async function getCompanyStats(): Promise<{ total: number; active: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'active') AS active
    FROM companies
    WHERE status IS DISTINCT FROM 'deleted'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10),
    active: parseInt(row.active as string, 10),
  };
}

async function getUserStats(): Promise<{ total: number; active_30d: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS active_30d
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10),
    active_30d: parseInt(row.active_30d as string, 10),
  };
}

async function getMrrStats(): Promise<{ mrr_cents: number; arr_cents: number }> {
  // Monthly: sum monthly_price_cents
  // Annual: normalise to monthly (divide by 12)
  const rows = await sql`
    SELECT
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM subscriptions s
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.status IN ('active', 'trial')
  `;
  const mrr = parseInt((rows[0] as Row).mrr_cents as string, 10);
  return { mrr_cents: mrr, arr_cents: mrr * 12 };
}

async function getNewSignupCount(): Promise<number> {
  const rows = await sql`
    SELECT COUNT(*) AS count
    FROM companies
    WHERE created_at >= NOW() - INTERVAL '30 days'
      AND status IS DISTINCT FROM 'deleted'
  `;
  return parseInt((rows[0] as Row).count as string, 10);
}

/**
 * Most recent 50 events from admin_audit_log + recent user_sessions.
 */
async function getRecentActivity(): Promise<ActivityEvent[]> {
  const rows = await sql`
    SELECT
      a.id::text                                                     AS id,
      'admin_action'                                                 AS type,
      a.action || ' ' || a.target_type                              AS description,
      COALESCE(u.first_name || ' ' || u.last_name, u.email)          AS user_name,
      NULL::text                                                     AS company_name,
      a.created_at
    FROM admin_audit_log a
    LEFT JOIN users u ON u.id = a.admin_user_id

    UNION ALL

    SELECT
      s.id::text                                                     AS id,
      'user_login'                                                   AS type,
      'User login'                                                   AS description,
      COALESCE(u.first_name || ' ' || u.last_name, u.email)          AS user_name,
      NULL::text                                                     AS company_name,
      s.created_at
    FROM user_sessions s
    INNER JOIN users u ON u.id = s.user_id
    WHERE s.created_at >= NOW() - INTERVAL '7 days'

    ORDER BY created_at DESC
    LIMIT 50
  `;

  return (rows as Row[]).map((row) => ({
    id: row.id as string,
    type: row.type as string,
    description: row.description as string,
    user_name: row.user_name as string | null,
    company_name: row.company_name as string | null,
    created_at: toISOString(row.created_at),
  }));
}

/**
 * Audit Service
 * Admin action logging for ISAFlow Admin Platform
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { AuditLogEntry, PaginatedResult } from '../types/admin.types';

export interface AuditLogFilters {
  admin_user_id?: string;
  target_type?: string;
  target_id?: string;
  action?: string;
  from_date?: string;
  to_date?: string;
  page?: number;
  limit?: number;
}

export async function logAdminAction(
  adminUserId: string,
  action: string,
  targetType: string,
  targetId: string | null,
  details: Record<string, unknown> | null,
  ipAddress: string | null
): Promise<void> {
  try {
    await sql`
      INSERT INTO admin_audit_log (
        admin_user_id,
        action,
        target_type,
        target_id,
        details,
        ip_address,
        created_at
      ) VALUES (
        ${adminUserId},
        ${action},
        ${targetType},
        ${targetId},
        ${details ? JSON.stringify(details) : null},
        ${ipAddress},
        NOW()
      )
    `;
  } catch (err) {
    // Audit logging must not break the calling flow — log and swallow
    log.error('logAdminAction failed', { adminUserId, action, error: err }, 'auditService');
  }
}

export async function getAuditLog(
  filters: AuditLogFilters = {}
): Promise<PaginatedResult<AuditLogEntry>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT
        al.id,
        al.admin_user_id,
        COALESCE(u.first_name || ' ' || u.last_name, u.email, 'Unknown') AS admin_name,
        al.action,
        al.target_type,
        al.target_id,
        al.details,
        al.ip_address,
        al.created_at
      FROM admin_audit_log al
      LEFT JOIN users u ON u.id = al.admin_user_id
      WHERE (
        ${filters.admin_user_id ? sql`al.admin_user_id = ${filters.admin_user_id}` : sql`TRUE`}
      )
      AND (${filters.target_type ? sql`al.target_type = ${filters.target_type}` : sql`TRUE`})
      AND (${filters.target_id ? sql`al.target_id = ${filters.target_id}` : sql`TRUE`})
      AND (${filters.action ? sql`al.action ILIKE ${'%' + filters.action + '%'}` : sql`TRUE`})
      AND (${filters.from_date ? sql`al.created_at >= ${filters.from_date}::timestamptz` : sql`TRUE`})
      AND (${filters.to_date ? sql`al.created_at <= ${filters.to_date}::timestamptz` : sql`TRUE`})
      ORDER BY al.created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(*)::int AS total
      FROM admin_audit_log al
      WHERE (
        ${filters.admin_user_id ? sql`al.admin_user_id = ${filters.admin_user_id}` : sql`TRUE`}
      )
      AND (${filters.target_type ? sql`al.target_type = ${filters.target_type}` : sql`TRUE`})
      AND (${filters.target_id ? sql`al.target_id = ${filters.target_id}` : sql`TRUE`})
      AND (${filters.action ? sql`al.action ILIKE ${'%' + filters.action + '%'}` : sql`TRUE`})
      AND (${filters.from_date ? sql`al.created_at >= ${filters.from_date}::timestamptz` : sql`TRUE`})
      AND (${filters.to_date ? sql`al.created_at <= ${filters.to_date}::timestamptz` : sql`TRUE`})
    `;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const toIso = (v: unknown) =>
      v instanceof Date ? v.toISOString() : (v as string);

    const total = countRow?.total ?? 0;

    return {
      items: rows.map((r) => ({
        id: r.id as string,
        admin_user_id: r.admin_user_id as string,
        admin_name: r.admin_name as string,
        action: r.action as string,
        target_type: r.target_type as string,
        target_id: r.target_id as string | null,
        details: (r.details ?? {}) as Record<string, unknown>,
        ip_address: r.ip_address as string | null,
        created_at: toIso(r.created_at),
      })),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit),
    };
  } catch (err) {
    log.error('getAuditLog failed', { error: err }, 'auditService');
    throw err;
  }
}

/**
 * Admin Company Service
 * Cross-company management operations for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  AdminCompanyListItem,
  AdminCompanyDetail,
  AdminListFilters,
  AdminUserCompany,
  PaginatedResult,
} from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  name: 'c.name',
  created_at: 'c.created_at',
  status: 'c.status',
  user_count: 'user_count',
  mrr_cents: 'mrr_cents',
};

export async function listCompanies(
  filters: AdminListFilters & { plan?: string } = {}
): Promise<PaginatedResult<AdminCompanyListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'c.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT c.id) AS total
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
  `;

  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')                                    AS status,
      p.name                                                          AS plan_name,
      p.code                                                          AS plan_code,
      (SELECT COUNT(*) FROM company_users cu WHERE cu.company_id = c.id)::int
                                                                      AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int                                                          AS mrr_cents,
      c.created_at,
      c.updated_at                                                    AS last_active
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.status IS DISTINCT FROM 'deleted'
      AND (${searchPattern}::text IS NULL
           OR c.name ILIKE ${searchPattern}
           OR c.registration_number ILIKE ${searchPattern})
      AND (${filters.status ?? null}::text IS NULL OR COALESCE(c.status,'active') = ${filters.status ?? null})
      AND (${filters.plan ?? null}::text IS NULL OR p.code = ${filters.plan ?? null})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listCompanies: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminCompanyService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      name: r.name as string,
      trading_name: r.trading_name as string | null,
      status: r.status as string,
      plan_name: r.plan_name as string | null,
      plan_code: r.plan_code as string | null,
      user_count: r.user_count as number,
      mrr_cents: r.mrr_cents as number,
      created_at: toIso(r.created_at) ?? '',
      last_active: toIso(r.last_active),
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getCompanyDetail(
  companyId: string
): Promise<AdminCompanyDetail | null> {
  const rows = await sql`
    SELECT
      c.id,
      c.name,
      c.trading_name,
      COALESCE(c.status, 'active')    AS status,
      p.name                          AS plan_name,
      p.code                          AS plan_code,
      c.registration_number,
      c.vat_number,
      c.tax_number,
      c.address_line1,
      c.city,
      c.province,
      c.postal_code,
      c.phone,
      c.email,
      c.website,
      c.billing_email,
      c.billing_contact,
      c.stripe_customer_id,
      c.trial_ends_at,
      c.suspended_at,
      c.suspended_reason,
      c.metadata,
      c.created_at,
      c.updated_at                    AS last_active,
      (SELECT COUNT(*)
         FROM company_users cu
        WHERE cu.company_id = c.id)::int AS user_count,
      COALESCE(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END, 0
      )::int AS mrr_cents
    FROM companies c
    LEFT JOIN subscriptions s ON s.company_id = c.id AND s.status IN ('active','trial')
    LEFT JOIN plans p ON p.id = s.plan_id
    WHERE c.id = ${companyId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    name: r.name as string,
    trading_name: r.trading_name as string | null,
    status: r.status as string,
    plan_name: r.plan_name as string | null,
    plan_code: r.plan_code as string | null,
    user_count: r.user_count as number,
    mrr_cents: r.mrr_cents as number,
    created_at: toIso(r.created_at) ?? '',
    last_active: toIso(r.last_active),
    registration_number: r.registration_number as string | null,
    vat_number: r.vat_number as string | null,
    tax_number: r.tax_number as string | null,
    address_line1: r.address_line1 as string | null,
    city: r.city as string | null,
    province: r.province as string | null,
    postal_code: r.postal_code as string | null,
    phone: r.phone as string | null,
    email: r.email as string | null,
    website: r.website as string | null,
    billing_email: r.billing_email as string | null,
    billing_contact: r.billing_contact as string | null,
    stripe_customer_id: r.stripe_customer_id as string | null,
    trial_ends_at: toIso(r.trial_ends_at),
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    metadata: (r.metadata ?? {}) as Record<string, unknown>,
  };
}

export async function updateCompany(
  companyId: string,
  data: Partial<AdminCompanyDetail>
): Promise<void> {
  // Only update safe, explicitly listed fields
  const {
    name, trading_name, phone, email, website,
    billing_email, billing_contact,
    address_line1, city, province, postal_code,
  } = data;

  await sql`
    UPDATE companies SET
      name             = COALESCE(${name ?? null}, name),
      trading_name     = COALESCE(${trading_name ?? null}, trading_name),
      phone            = COALESCE(${phone ?? null}, phone),
      email            = COALESCE(${email ?? null}, email),
      website          = COALESCE(${website ?? null}, website),
      billing_email    = COALESCE(${billing_email ?? null}, billing_email),
      billing_contact  = COALESCE(${billing_contact ?? null}, billing_contact),
      address_line1    = COALESCE(${address_line1 ?? null}, address_line1),
      city             = COALESCE(${city ?? null}, city),
      province         = COALESCE(${province ?? null}, province),
      postal_code      = COALESCE(${postal_code ?? null}, postal_code),
      updated_at       = NOW()
    WHERE id = ${companyId}
  `;

  log.info('updateCompany', { companyId }, 'AdminCompanyService');
}

export async function suspendCompany(
  companyId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'suspended',
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('suspendCompany', { companyId, reason }, 'AdminCompanyService');
}

export async function activateCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status           = 'active',
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${companyId}
  `;
  log.info('activateCompany', { companyId }, 'AdminCompanyService');
}

/** Soft delete — sets status='deleted', preserves data for audit trail. */
export async function deleteCompany(companyId: string): Promise<void> {
  await sql`
    UPDATE companies
    SET status     = 'deleted',
        updated_at = NOW()
    WHERE id = ${companyId}
  `;
  log.info('deleteCompany (soft)', { companyId }, 'AdminCompanyService');
}

export async function getCompanyUsers(
  companyId: string
): Promise<AdminUserCompany[]> {
  const rows = await sql`
    SELECT
      cu.company_id,
      c.name    AS company_name,
      cu.role,
      COALESCE(cu.is_default, false) AS is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.company_id = ${companyId}
    ORDER BY cu.role, c.name
  `;

  return (rows as Row[]).map((r) => ({
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    role: r.role as string,
    is_default: r.is_default as boolean,
  }));
}

/**
 * Admin User Service
 * Cross-company user management for the ISAFlow Admin Platform.
 * All mutations should be followed by logAdminAction from auditService.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { generateRandomPassword, hashPassword } from '@/lib/auth';
import type {
  AdminUserListItem,
  AdminUserDetail,
  AdminUserCompany,
  AdminListFilters,
  PaginatedResult,
} from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT_COLUMNS: Record<string, string> = {
  email: 'u.email',
  first_name: 'u.first_name',
  last_name: 'u.last_name',
  created_at: 'u.created_at',
  last_login: 'u.last_login',
  role: 'u.role',
};

export async function listUsers(
  filters: AdminListFilters & { role?: string; company_id?: string } = {}
): Promise<PaginatedResult<AdminUserListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT_COLUMNS[filters.sort_by ?? ''] ?? 'u.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;

  const searchPattern = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(DISTINCT u.id) AS total
    FROM users u
    LEFT JOIN company_users cu ON cu.user_id = u.id
    WHERE (${searchPattern}::text IS NULL
           OR u.email ILIKE ${searchPattern}
           OR u.first_name ILIKE ${searchPattern}
           OR u.last_name ILIKE ${searchPattern})
      AND (${filters.role ?? null}::text IS NULL OR u.role = ${filters.role ?? null})
      AND (${filters.company_id ?? null}::uuid IS NULL OR cu.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR (${filters.status ?? null} = 'active'    AND u.is_active = true)
           OR (${filters.status ?? null} = 'suspended' AND u.is_active = false))
  `;

  const rows = await sql`
    SELECT
      u.id,
      u.email,
      u.first_name,
      u.last_name,
      u.role,
      CASE WHEN u.is_active THEN 'active' ELSE 'suspended' END        AS status,
      (SELECT COUNT(*)
         FROM company_users cu2
        WHERE cu2.user_id = u.id)::int                                AS company_count,
      ARRAY(
        SELECT c.name
          FROM company_users cu3
          JOIN companies c ON c.id = cu3.company_id
         WHERE cu3.user_id = u.id
         ORDER BY c.name
         LIMIT 10
      )                                                               AS company_names,
      u.last_login,
      COALESCE(
        (SELECT COUNT(*) FROM user_sessions s WHERE s.user_id = u.id)::int,
        0
      )                                                               AS login_count,
      u.created_at
    FROM users u
    LEFT JOIN company_users cu ON cu.user_id = u.id
    WHERE (${searchPattern}::text IS NULL
           OR u.email ILIKE ${searchPattern}
           OR u.first_name ILIKE ${searchPattern}
           OR u.last_name ILIKE ${searchPattern})
      AND (${filters.role ?? null}::text IS NULL OR u.role = ${filters.role ?? null})
      AND (${filters.company_id ?? null}::uuid IS NULL OR cu.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR (${filters.status ?? null} = 'active'    AND u.is_active = true)
           OR (${filters.status ?? null} = 'suspended' AND u.is_active = false))
    GROUP BY u.id, u.email, u.first_name, u.last_name, u.role, u.is_active,
             u.last_login, u.created_at
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);

  log.info(`listUsers: ${rows.length} rows (page ${page}, total ${total})`, {}, 'AdminUserService');

  return {
    items: (rows as Row[]).map((r) => ({
      id: r.id as string,
      email: r.email as string,
      first_name: r.first_name as string | null,
      last_name: r.last_name as string | null,
      role: r.role as string,
      status: r.status as string,
      company_count: r.company_count as number,
      company_names: (r.company_names as string[]) ?? [],
      last_login: toIso(r.last_login),
      login_count: r.login_count as number,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getUserDetail(
  userId: string
): Promise<AdminUserDetail | null> {
  const rows = await sql`
    SELECT
      u.id,
      u.email,
      u.first_name,
      u.last_name,
      u.role,
      CASE WHEN u.is_active THEN 'active' ELSE 'suspended' END AS status,
      u.phone,
      u.department,
      u.last_login,
      u.last_login_ip,
      u.suspended_at,
      u.suspended_reason,
      COALESCE(
        (SELECT COUNT(*) FROM user_sessions s WHERE s.user_id = u.id)::int,
        0
      ) AS login_count,
      u.created_at
    FROM users u
    WHERE u.id = ${userId}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  const companyRows = await sql`
    SELECT
      cu.company_id,
      c.name AS company_name,
      cu.role,
      COALESCE(cu.is_default, false) AS is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId}
    ORDER BY c.name
  `;

  const companies: AdminUserCompany[] = (companyRows as Row[]).map((c) => ({
    company_id: c.company_id as string,
    company_name: c.company_name as string,
    role: c.role as string,
    is_default: c.is_default as boolean,
  }));

  return {
    id: r.id as string,
    email: r.email as string,
    first_name: r.first_name as string | null,
    last_name: r.last_name as string | null,
    role: r.role as string,
    status: r.status as string,
    company_count: companies.length,
    company_names: companies.map((c) => c.company_name),
    last_login: toIso(r.last_login),
    login_count: r.login_count as number,
    created_at: toIso(r.created_at) ?? '',
    phone: r.phone as string | null,
    department: r.department as string | null,
    last_login_ip: r.last_login_ip as string | null,
    suspended_at: toIso(r.suspended_at),
    suspended_reason: r.suspended_reason as string | null,
    companies,
  };
}

export async function updateUser(
  userId: string,
  data: { first_name?: string; last_name?: string; role?: string; phone?: string }
): Promise<void> {
  await sql`
    UPDATE users SET
      first_name = COALESCE(${data.first_name ?? null}, first_name),
      last_name  = COALESCE(${data.last_name ?? null}, last_name),
      role       = COALESCE(${data.role ?? null}, role),
      phone      = COALESCE(${data.phone ?? null}, phone),
      updated_at = NOW()
    WHERE id = ${userId}
  `;
  log.info('updateUser', { userId }, 'AdminUserService');
}

export async function suspendUser(
  userId: string,
  reason: string
): Promise<void> {
  await sql`
    UPDATE users
    SET is_active        = false,
        suspended_reason = ${reason},
        suspended_at     = NOW(),
        updated_at       = NOW()
    WHERE id = ${userId}
  `;
  // Invalidate all active sessions immediately
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('suspendUser', { userId, reason }, 'AdminUserService');
}

export async function activateUser(userId: string): Promise<void> {
  await sql`
    UPDATE users
    SET is_active        = true,
        suspended_reason = NULL,
        suspended_at     = NULL,
        updated_at       = NOW()
    WHERE id = ${userId}
  `;
  log.info('activateUser', { userId }, 'AdminUserService');
}

/**
 * Generate a temporary password, hash and store it, return plain text.
 * Caller is responsible for emailing the reset token/password.
 */
export async function resetPassword(userId: string): Promise<string> {
  const temporaryPassword = generateRandomPassword();
  const hashed = await hashPassword(temporaryPassword);

  await sql`
    UPDATE users
    SET password_hash        = ${hashed},
        must_change_password = true,
        updated_at           = NOW()
    WHERE id = ${userId}
  `;

  log.info('resetPassword — temporary password issued', { userId }, 'AdminUserService');
  return temporaryPassword;
}

/**
 * Force logout by deleting all active sessions for a user.
 * A no-op placeholder message is logged if no sessions exist.
 */
export async function forceLogout(userId: string): Promise<void> {
  await sql`DELETE FROM user_sessions WHERE user_id = ${userId}`;
  log.info('forceLogout — sessions cleared', { userId }, 'AdminUserService');
}

export async function addUserToCompany(
  userId: string,
  companyId: string,
  role: string
): Promise<void> {
  await sql`
    INSERT INTO company_users (user_id, company_id, role, created_at)
    VALUES (${userId}, ${companyId}, ${role}, NOW())
    ON CONFLICT (user_id, company_id) DO UPDATE
      SET role       = EXCLUDED.role,
          updated_at = NOW()
  `;
  log.info('addUserToCompany', { userId, companyId, role }, 'AdminUserService');
}

export async function removeUserFromCompany(
  userId: string,
  companyId: string
): Promise<void> {
  await sql`
    DELETE FROM company_users
    WHERE user_id = ${userId} AND company_id = ${companyId}
  `;
  log.info('removeUserFromCompany', { userId, companyId }, 'AdminUserService');
}

/**
 * Billing Service — Overview & Subscriptions
 * Aggregate KPIs and subscription lifecycle for the ISAFlow Admin Platform.
 * Invoice operations are in invoiceService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  BillingOverview,
  SubscriptionListItem,
  PaginatedResult,
} from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

// ---------------------------------------------------------------------------
// Overview
// ---------------------------------------------------------------------------

export async function getBillingOverview(): Promise<BillingOverview> {
  const [[subRow], [churnRow], [revRow]] = await Promise.all([
    sql`
      SELECT COUNT(*) AS total,
        COUNT(*) FILTER (WHERE s.status = 'active')   AS active,
        COUNT(*) FILTER (WHERE s.status = 'past_due') AS past_due,
        COUNT(*) FILTER (WHERE s.status = 'trial')    AS trial,
        COALESCE(SUM(CASE
          WHEN s.status NOT IN ('active','trial') THEN 0
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0 END), 0) AS mrr_cents
      FROM subscriptions s INNER JOIN plans p ON p.id = s.plan_id
    `,
    sql`
      SELECT
        COUNT(*) FILTER (WHERE status = 'cancelled'
          AND cancelled_at >= NOW() - INTERVAL '30 days')::float AS cancelled_30d,
        GREATEST(COUNT(*) FILTER (WHERE status IN ('active','trial','past_due')
          OR (status = 'cancelled' AND cancelled_at >= NOW() - INTERVAL '30 days')), 1)::float AS base
      FROM subscriptions
    `,
    sql`
      SELECT
        COALESCE(SUM(total_cents) FILTER (WHERE status = 'paid'), 0)              AS total_revenue_cents,
        COALESCE(SUM(total_cents) FILTER (WHERE status IN ('sent','overdue')), 0)  AS outstanding_cents
      FROM admin_invoices
    `,
  ]);

  const s = subRow as Row;
  const c = churnRow as Row;
  const rv = revRow as Row;
  const mrr = parseInt(s.mrr_cents as string, 10);
  const active = parseInt(s.active as string, 10);
  const churnRate = Math.round(((c.cancelled_30d as number) / (c.base as number)) * 10000) / 100;

  const overview: BillingOverview = {
    mrr_cents: mrr,
    arr_cents: mrr * 12,
    total_subscriptions: parseInt(s.total as string, 10),
    active_subscriptions: active,
    past_due_count: parseInt(s.past_due as string, 10),
    trial_count: parseInt(s.trial as string, 10),
    churn_rate_percent: churnRate,
    arpu_cents: active > 0 ? Math.round(mrr / active) : 0,
    total_revenue_cents: parseInt(rv.total_revenue_cents as string, 10),
    outstanding_cents: parseInt(rv.outstanding_cents as string, 10),
  };

  log.info('getBillingOverview', { mrr_cents: mrr, active }, 'BillingService');
  return overview;
}

// ---------------------------------------------------------------------------
// Subscriptions
// ---------------------------------------------------------------------------

const ALLOWED_SUB_SORT: Record<string, string> = {
  created_at: 's.created_at',
  status: 's.status',
  company_name: 'c.name',
  plan_name: 'p.name',
};

function rowToSubscription(r: Row): SubscriptionListItem {
  return {
    id: r.id as string,
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    plan_id: r.plan_id as string,
    plan_name: r.plan_name as string,
    plan_code: r.plan_code as string,
    status: r.status as string,
    billing_cycle: r.billing_cycle as string,
    current_period_start: toIso(r.current_period_start),
    current_period_end: toIso(r.current_period_end),
    cancel_at_period_end: r.cancel_at_period_end as boolean,
    discount_percent: r.discount_percent as number,
    monthly_amount_cents: parseInt(r.monthly_amount_cents as string, 10),
    created_at: toIso(r.created_at) ?? '',
  };
}

export async function listSubscriptions(filters: {
  status?: string;
  plan_id?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<SubscriptionListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SUB_SORT[filters.sort_by ?? ''] ?? 's.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
  `;

  const rows = await sql`
    SELECT s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle, s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
           WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
           ELSE 0 END AS monthly_amount_cents, s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listSubscriptions: ${rows.length} rows (page ${page})`, {}, 'BillingService');

  return {
    items: (rows as Row[]).map(rowToSubscription),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getSubscription(
  subscriptionId: string
): Promise<SubscriptionListItem | null> {
  const rows = await sql`
    SELECT s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle, s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
           WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
           ELSE 0 END AS monthly_amount_cents, s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.id = ${subscriptionId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToSubscription(rows[0] as Row);
}

export async function createSubscription(data: {
  company_id: string;
  plan_id: string;
  billing_cycle: string;
  discount_percent?: number;
  notes?: string;
}): Promise<string> {
  const { company_id, plan_id, billing_cycle, discount_percent = 0, notes = null } = data;
  const periodDays = billing_cycle === 'annual' ? 365 : 30;

  const rows = await sql`
    INSERT INTO subscriptions (
      company_id, plan_id, status, billing_cycle,
      current_period_start, current_period_end,
      cancel_at_period_end, discount_percent, notes,
      created_at, updated_at
    ) VALUES (
      ${company_id}::uuid, ${plan_id}::uuid,
      'active', ${billing_cycle},
      NOW(), NOW() + INTERVAL '1 day' * ${periodDays},
      false, ${discount_percent}, ${notes},
      NOW(), NOW()
    )
    RETURNING id
  `;

  const id = (rows[0] as Row).id as string;
  log.info('createSubscription', { id, company_id, plan_id, billing_cycle }, 'BillingService');
  return id;
}

export async function updateSubscription(
  subscriptionId: string,
  data: {
    plan_id?: string;
    billing_cycle?: string;
    discount_percent?: number;
    status?: string;
    notes?: string;
  }
): Promise<void> {
  const { plan_id, billing_cycle, discount_percent, status, notes } = data;

  await sql`
    UPDATE subscriptions SET
      plan_id          = COALESCE(${plan_id ?? null}::uuid, plan_id),
      billing_cycle    = COALESCE(${billing_cycle ?? null}, billing_cycle),
      discount_percent = COALESCE(${discount_percent ?? null}, discount_percent),
      status           = COALESCE(${status ?? null}, status),
      notes            = COALESCE(${notes ?? null}, notes),
      updated_at       = NOW()
    WHERE id = ${subscriptionId}
  `;

  log.info('updateSubscription', { subscriptionId }, 'BillingService');
}

export async function cancelSubscription(
  subscriptionId: string,
  atPeriodEnd: boolean
): Promise<void> {
  if (atPeriodEnd) {
    await sql`
      UPDATE subscriptions
      SET cancel_at_period_end = true,
          updated_at           = NOW()
      WHERE id = ${subscriptionId}
    `;
  } else {
    await sql`
      UPDATE subscriptions
      SET status       = 'cancelled',
          cancelled_at = NOW(),
          updated_at   = NOW()
      WHERE id = ${subscriptionId}
    `;
  }
  log.info('cancelSubscription', { subscriptionId, atPeriodEnd }, 'BillingService');
}

/**
 * Plan Service
 * CRUD operations for billing plans in the ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { Plan } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

function rowToPlan(r: Row): Plan {
  return {
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    monthly_price_cents: r.monthly_price_cents as number,
    annual_price_cents: r.annual_price_cents as number,
    currency: r.currency as string,
    features: (r.features ?? {}) as Record<string, unknown>,
    limits: (r.limits ?? {}) as Record<string, unknown>,
    is_active: r.is_active as boolean,
    display_order: r.display_order as number,
    created_at: toIso(r.created_at),
    updated_at: toIso(r.updated_at),
  };
}

export async function listPlans(includeArchived = false): Promise<Plan[]> {
  const rows = includeArchived
    ? await sql`
        SELECT * FROM plans
        ORDER BY display_order ASC, name ASC
      `
    : await sql`
        SELECT * FROM plans
        WHERE is_active = true
        ORDER BY display_order ASC, name ASC
      `;

  log.info(`listPlans: ${rows.length} plans (includeArchived=${includeArchived})`, {}, 'PlanService');
  return (rows as Row[]).map(rowToPlan);
}

export async function getPlan(planId: string): Promise<Plan | null> {
  const rows = await sql`
    SELECT * FROM plans
    WHERE id = ${planId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToPlan(rows[0] as Row);
}

export interface CreatePlanData {
  code: string;
  name: string;
  description?: string;
  monthly_price_cents: number;
  annual_price_cents: number;
  currency?: string;
  features?: Record<string, unknown>;
  limits?: Record<string, unknown>;
  display_order?: number;
}

export async function createPlan(data: CreatePlanData): Promise<Plan> {
  const {
    code,
    name,
    description = null,
    monthly_price_cents,
    annual_price_cents,
    currency = 'ZAR',
    features = {},
    limits = {},
    display_order = 0,
  } = data;

  const rows = await sql`
    INSERT INTO plans (
      code, name, description,
      monthly_price_cents, annual_price_cents, currency,
      features, limits, is_active, display_order,
      created_at, updated_at
    ) VALUES (
      ${code}, ${name}, ${description},
      ${monthly_price_cents}, ${annual_price_cents}, ${currency},
      ${JSON.stringify(features)}::jsonb, ${JSON.stringify(limits)}::jsonb,
      true, ${display_order},
      NOW(), NOW()
    )
    RETURNING *
  `;

  const plan = rowToPlan(rows[0] as Row);
  log.info('createPlan', { planId: plan.id, code }, 'PlanService');
  return plan;
}

export async function updatePlan(
  planId: string,
  data: Partial<Plan>
): Promise<void> {
  const {
    name, description, monthly_price_cents, annual_price_cents,
    currency, features, limits, is_active, display_order,
  } = data;

  await sql`
    UPDATE plans SET
      name                 = COALESCE(${name ?? null}, name),
      description          = COALESCE(${description ?? null}, description),
      monthly_price_cents  = COALESCE(${monthly_price_cents ?? null}, monthly_price_cents),
      annual_price_cents   = COALESCE(${annual_price_cents ?? null}, annual_price_cents),
      currency             = COALESCE(${currency ?? null}, currency),
      features             = COALESCE(${features != null ? JSON.stringify(features) : null}::jsonb, features),
      limits               = COALESCE(${limits != null ? JSON.stringify(limits) : null}::jsonb, limits),
      is_active            = COALESCE(${is_active ?? null}, is_active),
