    WHERE id = ${id}
  `;

  log.info('updateFeatureFlag', { id, data }, 'FeatureFlagService');
}

export async function getCompanyEffectiveFeatures(
  companyId: string
): Promise<CompanyEffectiveFeature[]> {
  // Fetch all flags, plan memberships and overrides in parallel
  const [flagRows, planRows, overrideRows] = await Promise.all([
    sql`
      SELECT id, code, name, is_global
      FROM feature_flags
      ORDER BY code ASC
    `,
    sql`
      SELECT pf.feature_id
      FROM plan_features pf
      JOIN companies c ON c.plan_id = pf.plan_id
      WHERE c.id = ${companyId}
    `,
    sql`
      SELECT feature_id, enabled
      FROM company_feature_overrides
      WHERE company_id = ${companyId}
    `,
  ]);

  const planFeatureIds = new Set(
    (planRows as Row[]).map((r) => r.feature_id as string)
  );

  const overrideMap = new Map<string, boolean>(
    (overrideRows as Row[]).map((r) => [r.feature_id as string, r.enabled as boolean])
  );

  return (flagRows as Row[]).map((r) => {
    const id = r.id as string;
    const isGlobal = r.is_global as boolean;
    const inPlan = planFeatureIds.has(id);
    const override = overrideMap.get(id);

    let enabled: boolean;
    let source: 'global' | 'plan' | 'override';

    if (override !== undefined) {
      // Override always wins
      enabled = override;
      source = 'override';
    } else if (isGlobal) {
      enabled = true;
      source = 'global';
    } else if (inPlan) {
      enabled = true;
      source = 'plan';
    } else {
      enabled = false;
      source = 'plan';
    }

    return {
      code: r.code as string,
      name: r.name as string,
      enabled,
      source,
    };
  });
}

export async function setCompanyFeatureOverride(
  companyId: string,
  featureId: string,
  enabled: boolean,
  reason: string,
  setBy: string
): Promise<void> {
  await sql`
    INSERT INTO company_feature_overrides
      (company_id, feature_id, enabled, reason, set_by, created_at)
    VALUES
      (${companyId}, ${featureId}, ${enabled}, ${reason}, ${setBy}, NOW())
    ON CONFLICT (company_id, feature_id)
    DO UPDATE SET
      enabled    = EXCLUDED.enabled,
      reason     = EXCLUDED.reason,
      set_by     = EXCLUDED.set_by,
      created_at = NOW()
  `;

  log.info('setCompanyFeatureOverride', { companyId, featureId, enabled }, 'FeatureFlagService');
}

export async function removeCompanyFeatureOverride(
  companyId: string,
  featureId: string
): Promise<void> {
  await sql`
    DELETE FROM company_feature_overrides
    WHERE company_id = ${companyId}
      AND feature_id = ${featureId}
  `;

  log.info('removeCompanyFeatureOverride', { companyId, featureId }, 'FeatureFlagService');
}

export async function hasFeature(
  companyId: string,
  featureCode: string
): Promise<boolean> {
  const rows = await sql`
    SELECT
      ff.is_global,
      EXISTS (
        SELECT 1
        FROM plan_features pf
        JOIN companies c ON c.plan_id = pf.plan_id
        WHERE c.id = ${companyId}
          AND pf.feature_id = ff.id
      ) AS in_plan,
      cfo.enabled AS override_enabled
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo
      ON cfo.feature_id = ff.id
      AND cfo.company_id = ${companyId}
    WHERE ff.code = ${featureCode}
    LIMIT 1
  `;

  if (rows.length === 0) return false;

  const r = rows[0] as Row;
  const overrideEnabled = r.override_enabled as boolean | null;

  // Override takes precedence
  if (overrideEnabled !== null) return overrideEnabled;
  // Then global flag
  if (r.is_global as boolean) return true;
  // Then plan membership
  return r.in_plan as boolean;
}

/**
 * Impersonation Service
 * Short-lived JWT tokens allowing super_admin to view the app as a specific company.
 * Uses the same jose library and JWT_SECRET as the main auth layer.
 */

import { SignJWT, jwtVerify } from 'jose';
import { log } from '@/lib/logger';

const IMPERSONATION_EXPIRY_MINUTES = 30;

function getSecret(): Uint8Array {
  const secret = process.env.JWT_SECRET;
  if (!secret) throw new Error('JWT_SECRET environment variable is not set');
  return new TextEncoder().encode(secret);
}

export interface ImpersonationTokenPayload {
  admin_user_id: string;
  company_id: string;
}

/**
 * Create a short-lived impersonation JWT.
 * Returns the token string and an ISO expiry timestamp.
 */
export async function createImpersonationToken(
  adminUserId: string,
  companyId: string
): Promise<{ token: string; expires_at: string }> {
  const secret = getSecret();
  const expiresAt = new Date(
    Date.now() + IMPERSONATION_EXPIRY_MINUTES * 60 * 1000
  );

  try {
    const token = await new SignJWT({
      impersonating: true,
      company_id: companyId,
    })
      .setProtectedHeader({ alg: 'HS256' })
      .setSubject(adminUserId)
      .setIssuedAt()
      .setExpirationTime(`${IMPERSONATION_EXPIRY_MINUTES}m`)
      .sign(secret);

    return { token, expires_at: expiresAt.toISOString() };
  } catch (err) {
    log.error(
      'createImpersonationToken failed',
      { adminUserId, companyId, error: err },
      'impersonationService'
    );
    throw err;
  }
}

/**
 * Verify an impersonation JWT.
 * Returns the decoded payload or null if invalid / expired.
 */
export async function validateImpersonationToken(
  token: string
): Promise<ImpersonationTokenPayload | null> {
  try {
    const secret = getSecret();
    const { payload } = await jwtVerify(token, secret);

    if (
      !payload.sub ||
      payload.impersonating !== true ||
      typeof payload.company_id !== 'string'
    ) {
      return null;
    }

    return {
      admin_user_id: payload.sub,
      company_id: payload.company_id,
    };
  } catch (err) {
    // Expired or tampered tokens are expected — only log unexpected errors
    const msg = err instanceof Error ? err.message : String(err);
    if (!msg.includes('expired') && !msg.includes('JWTExpired')) {
      log.error('validateImpersonationToken error', { error: err }, 'impersonationService');
    }
    return null;
  }
}

/**
 * Data Export Service
 * Exports all major accounting data for a company as structured JSON.
 * Future enhancement: ZIP/CSV generation.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface CompanyExportResult {
  filename: string;
  data: Record<string, unknown[]>;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(v: unknown): string | null {
  if (v == null) return null;
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

function normalizeRows(rows: Row[]): Record<string, unknown>[] {
  return rows.map((r) => {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(r)) {
      out[k] = v instanceof Date ? toIso(v) : v;
    }
    return out;
  });
}

export async function exportCompanyData(
  companyId: string
): Promise<CompanyExportResult> {
  try {
    const [companyRows, accountRows, customerRows, supplierRows, invoiceRows, journalRows, bankRows] =
      await Promise.all([
        sql`SELECT * FROM companies WHERE id = ${companyId}`,

        sql`SELECT * FROM gl_accounts
            WHERE company_id = ${companyId}
            ORDER BY code`,

        sql`SELECT * FROM customers
            WHERE company_id = ${companyId}
            ORDER BY name`,

        sql`SELECT * FROM suppliers
            WHERE company_id = ${companyId}
            ORDER BY name`,

        sql`SELECT * FROM invoices
            WHERE company_id = ${companyId}
            ORDER BY invoice_date DESC`,

        sql`SELECT * FROM gl_journal_entries
            WHERE company_id = ${companyId}
            ORDER BY entry_date DESC`,

        sql`SELECT * FROM bank_transactions
            WHERE company_id = ${companyId}
            ORDER BY transaction_date DESC`,
      ]);

    const companyName =
      (companyRows[0]?.name as string | undefined) ?? companyId;

    const dateStr = new Date().toISOString().split('T')[0];
    const safeName = companyName.replace(/[^a-zA-Z0-9-_]/g, '-').toLowerCase();
    const filename = `export-${safeName}-${dateStr}.json`;

    return {
      filename,
      data: {
        company:         normalizeRows(companyRows),
        accounts:        normalizeRows(accountRows),
        customers:       normalizeRows(customerRows),
        suppliers:       normalizeRows(supplierRows),
        invoices:        normalizeRows(invoiceRows),
        journal_entries: normalizeRows(journalRows),
        bank_transactions: normalizeRows(bankRows),
      },
    };
  } catch (err) {
    log.error('exportCompanyData failed', { companyId, error: err }, 'dataExportService');
    throw err;
  }
}

/**
 * Announcement Service
 * CRUD for system_announcements table — admin-managed platform messages.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { Announcement, PaginatedResult } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(v: unknown): string | null {
  if (v == null) return null;
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

function rowToAnnouncement(r: Row): Announcement {
  return {
    id: r.id as string,
    title: r.title as string,
    message: r.message as string,
    type: r.type as string,
    target: r.target as string,
    target_ids: (r.target_ids ?? []) as string[],
    starts_at: toIso(r.starts_at) as string,
    ends_at: toIso(r.ends_at),
    is_dismissible: r.is_dismissible as boolean,
    created_by: r.created_by as string,
    created_at: toIso(r.created_at) as string,
  };
}

interface ListFilters {
  active_only?: boolean;
  page?: number;
  limit?: number;
}

export async function listAnnouncements(
  filters: ListFilters = {}
): Promise<PaginatedResult<Announcement>> {
  const page  = Math.max(1, filters.page  ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT *
      FROM system_announcements
      WHERE (
        ${filters.active_only
          ? sql`starts_at <= NOW() AND (ends_at IS NULL OR ends_at >= NOW())`
          : sql`TRUE`}
      )
      ORDER BY created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(*)::int AS total
      FROM system_announcements
      WHERE (
        ${filters.active_only
          ? sql`starts_at <= NOW() AND (ends_at IS NULL OR ends_at >= NOW())`
          : sql`TRUE`}
      )
    `;

    const total = countRow?.total ?? 0;

    return {
      items: rows.map(rowToAnnouncement),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit),
    };
  } catch (err) {
    log.error('listAnnouncements failed', { error: err }, 'announcementService');
    throw err;
  }
}

export async function getAnnouncement(id: string): Promise<Announcement | null> {
  try {
    const [row] = await sql`
      SELECT * FROM system_announcements WHERE id = ${id}
    `;
    if (!row) return null;
    return rowToAnnouncement(row);
  } catch (err) {
    log.error('getAnnouncement failed', { id, error: err }, 'announcementService');
    throw err;
  }
}

export interface CreateAnnouncementData {
  title: string;
  message: string;
  type?: string;
  target?: string;
  target_ids?: string[];
  starts_at: string;
  ends_at?: string;
  is_dismissible?: boolean;
  created_by: string;
}

export async function createAnnouncement(data: CreateAnnouncementData): Promise<string> {
  const type         = data.type         ?? 'info';
  const target       = data.target       ?? 'all';
  const target_ids   = data.target_ids   ?? [];
  const is_dismissible = data.is_dismissible ?? true;

  try {
    const rows = await sql`
      INSERT INTO system_announcements (
        title, message, type, target, target_ids,
        starts_at, ends_at, is_dismissible, created_by, created_at
      ) VALUES (
        ${data.title},
        ${data.message},
        ${type},
        ${target},
        ${target_ids},
        ${data.starts_at}::timestamptz,
        ${data.ends_at ?? null}::timestamptz,
        ${is_dismissible},
        ${data.created_by},
        NOW()
      )
      RETURNING id
    `;
    if (!rows[0]) throw new Error('Insert returned no row');
    return rows[0].id as string;
  } catch (err) {
    log.error('createAnnouncement failed', { error: err }, 'announcementService');
    throw err;
  }
}

export async function updateAnnouncement(
  id: string,
  data: Partial<Omit<Announcement, 'id' | 'created_at' | 'created_by'>>
): Promise<void> {
  try {
    const startsAt = data.starts_at ?? null;
    const endsAt   = data.ends_at   ?? null;

    await sql`
      UPDATE system_announcements SET
        title          = COALESCE(${data.title          ?? null}, title),
        message        = COALESCE(${data.message        ?? null}, message),
        type           = COALESCE(${data.type           ?? null}, type),
        target         = COALESCE(${data.target         ?? null}, target),
        target_ids     = COALESCE(${data.target_ids     ?? null}, target_ids),
        starts_at      = CASE WHEN ${startsAt}::text IS NOT NULL
                              THEN ${startsAt}::timestamptz
                              ELSE starts_at END,
        ends_at        = CASE WHEN ${endsAt}::text IS NOT NULL
                              THEN ${endsAt}::timestamptz
                              ELSE ends_at END,
        is_dismissible = COALESCE(${data.is_dismissible ?? null}, is_dismissible)
      WHERE id = ${id}
    `;
  } catch (err) {
    log.error('updateAnnouncement failed', { id, error: err }, 'announcementService');
    throw err;
  }
}

export async function deleteAnnouncement(id: string): Promise<void> {
  try {
    await sql`DELETE FROM system_announcements WHERE id = ${id}`;
  } catch (err) {
    log.error('deleteAnnouncement failed', { id, error: err }, 'announcementService');
    throw err;
  }
}

/**
 * Admin Company Suspend API
 * POST /api/admin/companies/[id]/suspend — Suspend a company
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { suspendCompany } from '@/modules/admin/services/adminCompanyService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = req.query.id as string;

  if (req.method === 'POST') {
    try {
      const { reason } = req.body as { reason?: string };

      if (!reason || reason.trim().length === 0) {
        return apiResponse.badRequest(res, 'A suspension reason is required');
      }

      await suspendCompany(companyId, reason.trim());

      await logAdminAction(
        req.user.id,
        'company.suspend',
        'company',
        companyId,
        { reason },
        getIp(req)
      );

      return apiResponse.success(res, { suspended: true });
    } catch (err) {
      log.error('Failed to suspend company', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to suspend company');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

export default withAdmin(handler);

/**
 * Admin Analytics Service
 * Platform health, usage analytics, and settings for ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { PlatformHealth, UsageAnalytics, PlatformSettings } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toISOString(value: unknown): string | null {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

export async function getPlatformHealth(): Promise<PlatformHealth> {
  const [activeUsers, apiCalls, dbSize, topCompanies] = await Promise.all([
    getActiveUserCounts(),
    getApiCallCount(),
    getDbSizeMb(),
    getTopCompaniesBySize(),
  ]);

  const health: PlatformHealth = {
    active_users_24h: activeUsers.h24,
    active_users_7d: activeUsers.d7,
    active_users_30d: activeUsers.d30,
    total_api_calls_24h: apiCalls.total,
    error_count_24h: apiCalls.errors,
    error_rate_percent: apiCalls.total > 0
      ? Math.round((apiCalls.errors / apiCalls.total) * 10000) / 100
      : 0,
    db_size_mb: dbSize,
    top_companies_by_size: topCompanies,
  };

  log.info('Platform health fetched', {
    active_users_24h: health.active_users_24h,
    db_size_mb: health.db_size_mb,
  }, 'analyticsService');

  return health;
}

async function getActiveUserCounts(): Promise<{ h24: number; d7: number; d30: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '24 hours') AS h24,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')   AS d7,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days')  AS d30
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    h24: parseInt(row.h24 as string, 10) || 0,
    d7: parseInt(row.d7 as string, 10) || 0,
    d30: parseInt(row.d30 as string, 10) || 0,
  };
}

async function getApiCallCount(): Promise<{ total: number; errors: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE action ILIKE 'error%') AS errors
    FROM admin_audit_log
    WHERE created_at >= NOW() - INTERVAL '24 hours'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10) || 0,
    errors: parseInt(row.errors as string, 10) || 0,
  };
}

async function getDbSizeMb(): Promise<number> {
  const rows = await sql`
    SELECT ROUND(pg_database_size(current_database()) / 1048576.0, 2) AS size_mb
  `;
  const val = (rows[0] as Row).size_mb;
  return parseFloat(val as string) || 0;
}

async function getTopCompaniesBySize(): Promise<PlatformHealth['top_companies_by_size']> {
  // Proxy company "size" by counting rows in major tables grouped by company_id
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name AS company_name,
      (
        COALESCE((SELECT COUNT(*) FROM gl_journal_entries je WHERE je.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM customer_invoices ci WHERE COALESCE(ci.client_id, ci.customer_id) IS NOT NULL AND ci.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM bank_transactions bt WHERE bt.company_id = c.id), 0)
      )::float / 1000.0 AS size_mb
    FROM companies c
    WHERE c.status IS DISTINCT FROM 'deleted'
    ORDER BY size_mb DESC
    LIMIT 10
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    size_mb: parseFloat(row.size_mb as string) || 0,
  }));
}

export async function getUsageAnalytics(): Promise<UsageAnalytics> {
  const [engagement, featureAdoption, revenueByPlan, churnSignals] = await Promise.all([
    getEngagementCounts(),
    getFeatureAdoption(),
    getRevenueByPlan(),
    getChurnSignals(),
  ]);

  const stickiness = engagement.mau > 0
    ? Math.round((engagement.dau / engagement.mau) * 10000) / 100
    : 0;

  const analytics: UsageAnalytics = {
    dau: engagement.dau,
    wau: engagement.wau,
    mau: engagement.mau,
    stickiness_percent: stickiness,
    // top_pages requires a page_views tracking table — not yet implemented
    top_pages: [],
    feature_adoption: featureAdoption,
    revenue_by_plan: revenueByPlan,
    churn_signals: churnSignals,
  };

  log.info('Usage analytics fetched', {
    dau: analytics.dau,
    mau: analytics.mau,
    churn_signals: analytics.churn_signals.length,
  }, 'analyticsService');

  return analytics;
}

async function getEngagementCounts(): Promise<{ dau: number; wau: number; mau: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '1 day')   AS dau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')  AS wau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS mau
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    dau: parseInt(row.dau as string, 10) || 0,
    wau: parseInt(row.wau as string, 10) || 0,
    mau: parseInt(row.mau as string, 10) || 0,
  };
}

async function getFeatureAdoption(): Promise<UsageAnalytics['feature_adoption']> {
  const totalRow = await sql`SELECT COUNT(*) AS total FROM companies WHERE status IS DISTINCT FROM 'deleted'`;
  const total = parseInt((totalRow[0] as Row).total as string, 10) || 1;

  const rows = await sql`
    SELECT
      ff.name AS feature,
      COUNT(DISTINCT cfo.company_id) AS user_count
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo ON cfo.feature_id = ff.id AND cfo.enabled = true
    GROUP BY ff.id, ff.name
    ORDER BY user_count DESC
  `;

  return (rows as Row[]).map((row) => ({
    feature: row.feature as string,
    user_count: parseInt(row.user_count as string, 10) || 0,
    adoption_percent: Math.round(((parseInt(row.user_count as string, 10) || 0) / total) * 10000) / 100,
  }));
}

async function getRevenueByPlan(): Promise<UsageAnalytics['revenue_by_plan']> {
  const rows = await sql`
    SELECT
      p.name AS plan_name,
      COUNT(s.id) AS company_count,
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM plans p
    LEFT JOIN subscriptions s ON s.plan_id = p.id AND s.status IN ('active', 'trial')
    GROUP BY p.id, p.name
    ORDER BY mrr_cents DESC
  `;
  return (rows as Row[]).map((row) => ({
    plan_name: row.plan_name as string,
    mrr_cents: parseInt(row.mrr_cents as string, 10) || 0,
    company_count: parseInt(row.company_count as string, 10) || 0,
  }));
}

async function getChurnSignals(): Promise<UsageAnalytics['churn_signals']> {
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name     AS company_name,
      EXTRACT(DAY FROM NOW() - MAX(u.last_login))::int AS days_inactive,
      MAX(u.last_login) AS last_login
    FROM companies c
    INNER JOIN company_users cu ON cu.company_id = c.id
    INNER JOIN users u ON u.id = cu.user_id AND u.is_active = true
    WHERE c.status IS DISTINCT FROM 'deleted'
    GROUP BY c.id, c.name
    HAVING MAX(u.last_login) < NOW() - INTERVAL '14 days'
        OR MAX(u.last_login) IS NULL
    ORDER BY days_inactive DESC NULLS LAST
    LIMIT 20
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    days_inactive: parseInt(row.days_inactive as string, 10) || 0,
    last_login: toISOString(row.last_login),
  }));
}

