        `Page renders with relevant content [${pageTest.checks.slice(0, 2).join(', ')}]`,
        `Title: "${title}" | Content keywords found: ${hasExpectedContent} | 404: ${is404} | 500: ${is500}`,
        pass,
        notes
      );
    } catch (e) {
