function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

function fmtDate(d: string) {
  return new Date(d).toLocaleDateString('en-ZA');
}

const SUB_STATUS_BADGE: Record<string, string> = {
  active:    'bg-teal-500/10 text-teal-600 dark:text-teal-400',
  trial:     'bg-yellow-500/10 text-yellow-600 dark:text-yellow-400',
  past_due:  'bg-red-500/10 text-red-500',
  cancelled: 'bg-gray-500/10 text-gray-500',
  paused:    'bg-blue-500/10 text-blue-400',
};

export default function BillingOverviewPage() {
  const router = useRouter();
  const adminHref = useAdminHref();
  const [overview, setOverview]   = useState<BillingOverview | null>(null);
  const [recent, setRecent]       = useState<RecentSubscription[]>([]);
  const [loading, setLoading]     = useState(true);

  code: string;
  name: string;
  description: string;
  monthlyPriceCents: number;
  annualPriceCents: number;
  usersLimit: number | null;
  isArchived: boolean;
  features: Record<string, unknown>;
  limits: Record<string, unknown>;
}

interface PlanForm {
  code: string;
  name: string;
  description: string;
  monthly_price: string;
  annual_price: string;
  users_limit: string;
  features: string;
  limits: string;
}

const EMPTY_FORM: PlanForm = {
  code: '', name: '', description: '',
  monthly_price: '', annual_price: '',
  users_limit: '', features: '{}', limits: '{}',
};

function fmtZAR(cents: number) {
  return (cents / 100).toLocaleString('en-ZA', { style: 'currency', currency: 'ZAR' });
}

export default function PlansPage() {
  const [plans, setPlans]         = useState<Plan[]>([]);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [formError, setFormError] = useState('');
  const [saving, setSaving]       = useState(false);
  const [showForm, setShowForm]   = useState(false);
  const [editId, setEditId]       = useState<string | null>(null);
  const [form, setForm]           = useState<PlanForm>(EMPTY_FORM);

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const res  = await apiFetch('/api/admin/billing/plans?include_archived=true');
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load plans');
      setPlans((json.data ?? []) as Plan[]);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load plans');
    } finally {
      setLoading(false);
    }

  const s = subRow as Row;
  const c = churnRow as Row;
  const rv = revRow as Row;
  const mrr = parseInt(s.mrr_cents as string, 10);
  const active = parseInt(s.active as string, 10);
  const churnRate = Math.round(((c.cancelled_30d as number) / (c.base as number)) * 10000) / 100;

  const overview: BillingOverview = {
    mrr_cents: mrr,
    arr_cents: mrr * 12,
    total_subscriptions: parseInt(s.total as string, 10),
    active_subscriptions: active,
    past_due_count: parseInt(s.past_due as string, 10),
    trial_count: parseInt(s.trial as string, 10),
    churn_rate_percent: churnRate,
    arpu_cents: active > 0 ? Math.round(mrr / active) : 0,
    total_revenue_cents: parseInt(rv.total_revenue_cents as string, 10),
    outstanding_cents: parseInt(rv.outstanding_cents as string, 10),
  };

  log.info('getBillingOverview', { mrr_cents: mrr, active }, 'BillingService');
  return overview;
}

