/**
 * Portal Chatbot API
 * POST: client asks a question, gets AI-powered response
 */
import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { classifyClientQuery, buildClientChatPrompt, parseClientChatResponse, sanitizeClientResponse, type ClientContext } from '@/modules/accounting/services/portalChatbotService';
import { jwtVerify } from 'jose';
import cookie from 'cookie';

const PORTAL_SECRET = new TextEncoder().encode(
  (() => { if (!process.env.JWT_SECRET) throw new Error('JWT_SECRET is required'); return process.env.JWT_SECRET + '-portal'; })()
);

type Row = Record<string, unknown>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  // Authenticate portal session
  const cookies = cookie.parse(req.headers.cookie || '');
  const token = cookies.portal_session;
  if (!token) return res.status(401).json({ success: false, error: { message: 'Not authenticated' } });
  let sessionClientId: string;
  try {
    const { payload } = await jwtVerify(token, PORTAL_SECRET);
    sessionClientId = payload.clientId as string;
  } catch {
    return res.status(401).json({ success: false, error: { message: 'Invalid session' } });
  }

  const { question, clientId } = req.body;
  if (!question) return apiResponse.badRequest(res, 'question is required');
  if (!clientId || clientId !== sessionClientId) return apiResponse.badRequest(res, 'clientId mismatch or missing');
  if (question.length > 500) return apiResponse.badRequest(res, 'question too long (max 500 chars)');

  const queryType = classifyClientQuery(question);

  // Build client context from DB
  const clients = await sql`SELECT name FROM customers WHERE id = ${clientId} LIMIT 1` as Row[];
  const clientName = String(clients[0]?.name || 'Client');

  const balanceRows = await sql`SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) as outstanding FROM customer_invoices WHERE customer_id = ${clientId} AND status NOT IN ('cancelled', 'draft', 'paid')` as Row[];
  const overdueRows = await sql`SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) as overdue FROM customer_invoices WHERE customer_id = ${clientId} AND status NOT IN ('cancelled', 'draft', 'paid') AND due_date < CURRENT_DATE` as Row[];
  const invoiceCount = await sql`SELECT COUNT(*) as cnt FROM customer_invoices WHERE customer_id = ${clientId} AND status NOT IN ('cancelled', 'draft', 'paid')` as Row[];
  const lastPay = await sql`SELECT amount, payment_date FROM customer_payments WHERE customer_id = ${clientId} ORDER BY payment_date DESC LIMIT 1` as Row[];

  const ctx: ClientContext = {
    clientName,
    outstandingBalance: Number(balanceRows[0]?.outstanding ?? 0),
    overdueAmount: Number(overdueRows[0]?.overdue ?? 0),
    lastPaymentDate: lastPay[0] ? String(lastPay[0].payment_date) : '',
    lastPaymentAmount: Number(lastPay[0]?.amount ?? 0),
    openInvoices: Number(invoiceCount[0]?.cnt ?? 0),
    companyName: 'IsaFlow',
  };

/**
 * Natural Language Financial Query API
 * POST: ask a question in plain English, get data back
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  buildTextToSQLPrompt, parseSQLResponse, validateGeneratedSQL,
  formatQueryResult, buildSchemaDescription, classifyQueryIntent,
  type SchemaTable,
} from '@/modules/accounting/services/nlQueryService';

type Row = Record<string, unknown>;

const SCHEMA_TABLES: SchemaTable[] = [
  { name: 'customer_invoices', columns: ['id', 'customer_id', 'invoice_number', 'invoice_date', 'due_date', 'total_amount', 'amount_paid', 'status', 'company_id'], description: 'Customer/sales invoices' },
  { name: 'customers', columns: ['id', 'name', 'email', 'payment_terms', 'is_active', 'company_id'], description: 'Customer master data' },
  { name: 'supplier_invoices', columns: ['id', 'supplier_id', 'invoice_number', 'invoice_date', 'total_amount', 'amount_paid', 'status', 'company_id'], description: 'Supplier/purchase invoices' },
  { name: 'suppliers', columns: ['id', 'name', 'email', 'is_active', 'company_id'], description: 'Supplier master data' },
  { name: 'gl_accounts', columns: ['id', 'account_code', 'account_name', 'account_type', 'is_active', 'company_id'], description: 'Chart of accounts (GL)' },
  { name: 'gl_journal_entries', columns: ['id', 'entry_number', 'entry_date', 'description', 'status', 'source'], description: 'Journal entries' },
  { name: 'gl_journal_lines', columns: ['id', 'journal_entry_id', 'gl_account_id', 'debit', 'credit', 'description'], description: 'Journal entry lines (debits/credits)' },
  { name: 'bank_transactions', columns: ['id', 'bank_account_id', 'date', 'description', 'amount', 'category', 'is_reconciled'], description: 'Imported bank transactions' },
  { name: 'products', columns: ['id', 'code', 'name', 'cost_price', 'selling_price', 'current_stock', 'company_id'], description: 'Products/inventory items' },
  { name: 'employees', columns: ['id', 'first_name', 'last_name', 'email', 'basic_salary', 'employment_type', 'company_id'], description: 'Employee master data' },
  { name: 'payslips', columns: ['id', 'employee_id', 'payroll_run_id', 'gross_pay', 'net_pay', 'paye', 'uif_employee'], description: 'Payslips per payroll run' },
  { name: 'projects', columns: ['id', 'project_number', 'name', 'client_id', 'status', 'budget_amount', 'total_revenue', 'total_cost'], description: 'Projects/jobs' },
];

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { question } = req.body;
  if (!question || typeof question !== 'string' || question.trim().length < 3) {
    return apiResponse.badRequest(res, 'Please ask a question (minimum 3 characters)');
  }
  if (question.length > 500) {
    return apiResponse.badRequest(res, 'Question is too long (maximum 500 characters)');
  }

  const companyId = (req as any).companyId as string;
  const intent = classifyQueryIntent(question);
  const schemaDesc = buildSchemaDescription(SCHEMA_TABLES);
  const prompt = buildTextToSQLPrompt(question, schemaDesc, companyId);

  // Call Claude
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return apiResponse.success(res, {
      intent,
      message: 'Natural language queries require ANTHROPIC_API_KEY to be configured.',
      rows: [], columns: [], summary: 'AI not configured',
    });
  }

  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 512,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (!response.ok) {
      return apiResponse.success(res, { intent, message: 'AI service unavailable', rows: [], columns: [], summary: 'Service error' });
    }

    const data = await response.json() as any;
    const text = data.content?.[0]?.text || '';
    const parsed = parseSQLResponse(text);

    if (!parsed) {
      return apiResponse.success(res, { intent, message: 'Could not generate a query for that question.', explanation: text, rows: [], columns: [], summary: 'Unable to parse' });
    }

    // Validate SQL
    const validation = validateGeneratedSQL(parsed.sql);
    if (!validation.valid) {
      return apiResponse.success(res, { intent, message: `Generated SQL was rejected: ${validation.error}`, rows: [], columns: [], summary: 'Query rejected' });
    }

    // Verify company_id appears in an actual "company_id = '<uuid>'" predicate,
    // not just anywhere in the string (e.g. a comment, alias, or lucky substring).
    const scopeRegex = new RegExp(`company_id\\s*=\\s*'${companyId}'`, 'i');
    if (!scopeRegex.test(validation.sanitizedSQL)) {
      log.warn('NL query missing company_id scope — rejected', { question, companyId }, 'ai');
      return apiResponse.success(res, { intent, message: 'Could not generate a properly scoped query. Please try again.', rows: [], columns: [], summary: 'Scope error' });
    }

    // Execute inside a transaction so SET LOCAL applies to the same connection.
    // Neon HTTP driver is stateless — each top-level sql`` call is a separate
    // HTTP request, so a bare SET statement_timeout would have no effect on the
    // next call.  sql.transaction() batches both statements into a single HTTP
    // request, guaranteeing SET LOCAL is honoured for the query that follows it.
    const [, rows] = await sql.transaction(
      (txn) => [
        txn`SET LOCAL statement_timeout = '5000'`,
        txn.unsafe(validation.sanitizedSQL) as any,
      ]
    ) as [unknown, Row[]];
    const formatted = formatQueryResult(rows as Record<string, unknown>[], question);

    log.info('NL query executed', { question, intent, rowCount: formatted.rowCount }, 'ai');

    return apiResponse.success(res, {
      intent,
      question,
      sql: validation.sanitizedSQL,
      explanation: parsed.explanation,
      ...formatted,
    });
  } catch (err) {
    log.error('NL query failed', { error: err }, 'ai');
    return apiResponse.success(res, { intent, message: 'Query execution failed', rows: [], columns: [], summary: 'Error' });
  }
}

export default withCompany(withErrorHandler(handler));

/**
 * GET /api/auth/me
 * Returns the currently authenticated user from the JWT cookie.
 * Uses a single JOIN query for performance (session + user in one round-trip).
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';
import { apiResponse } from '@/lib/apiResponse';
import { verifyToken } from '@/lib/auth/jwt';
import { getUserAndValidateSession, AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import { createHash } from 'crypto';
import { withErrorHandler } from '@/lib/api-error-handler';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['GET']);
  }

  // Extract token from cookie or Authorization header
  const cookieToken = req.cookies[AUTH_COOKIE_NAME];
  const authHeader = req.headers.authorization;
  const bearerToken = authHeader?.startsWith('Bearer ') ? authHeader.substring(7) : null;
  const token = cookieToken ?? bearerToken;

  if (!token) {
    return res.status(401).json({
      success: false,
      error: { code: 'UNAUTHORIZED', message: 'Not authenticated' },
    });
  }

  try {
    const payload = await verifyToken(token);
    if (!payload) {
      return res.status(401).json({
        success: false,
        error: { code: 'INVALID_TOKEN', message: 'Invalid or expired token' },
      });
    }

    const tokenHash = createHash('sha256').update(token).digest('hex');
    const user = await getUserAndValidateSession(payload.sub, payload.sessionId, tokenHash);

    if (!user) {
      return res.status(401).json({
        success: false,
        error: { code: 'SESSION_INVALID', message: 'Session expired or invalid' },
      });
    }

    return apiResponse.success(res, { user });
  } catch (err) {
    log.error('Failed to get current user', err instanceof Error ? { message: err.message } : { err }, 'auth/me');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

/**
 * Admin Company Activate API
 * POST /api/admin/companies/[id]/activate — Reinstate a suspended company
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { activateCompany } from '@/modules/admin/services/adminCompanyService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = req.query.id as string;

  if (req.method === 'POST') {
    try {
      await activateCompany(companyId);

      await logAdminAction(
        req.user.id,
        'company.activate',
        'company',
        companyId,
        null,
        getIp(req)
      );

      return apiResponse.success(res, { activated: true });
    } catch (err) {
      log.error('Failed to activate company', { companyId, error: err }, 'admin-api');
      return apiResponse.badRequest(res, 'Failed to activate company');
    }
  }

  return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
}

export default withAdmin(handler);

/**
 * Admin Company Data Export API
 * GET /api/admin/companies/[id]/export-data
 * Returns all company accounting data as a downloadable JSON file.
 */

import type { NextApiResponse } from 'next';
import { type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withAdmin } from '@/modules/admin/middleware/withAdmin';
import { apiResponse } from '@/lib/apiResponse';
import { log } from '@/lib/logger';
import { exportCompanyData } from '@/modules/admin/services/dataExportService';
import { logAdminAction } from '@/modules/admin/services/auditService';

function getIp(req: AuthenticatedNextApiRequest): string | null {
  return (
    (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim() ||
    req.socket?.remoteAddress ||
    null
  );
}

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['GET']);
  }

  const companyId = req.query.id as string;

  try {
    const { filename, data } = await exportCompanyData(companyId);

    await logAdminAction(
      req.user.id,
      'company.export_data',
      'company',
      companyId,
      { filename },
      getIp(req)
    );

    res.setHeader('Content-Type', 'application/json');
    res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
    res.status(200).json({ filename, data });
  } catch (err) {
    log.error('Failed to export company data', { companyId, error: err }, 'admin-api');
    return apiResponse.badRequest(res, 'Failed to export company data');
  }
}

