/**
 * Auto-create supplier invoice from captured document extraction
 * POST: match supplier + create invoice from extracted data
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { fuzzyMatchSupplier, buildAutoInvoiceFromExtraction, calculateFieldConfidence } from '@/modules/accounting/services/docExtractionEnhancedService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { documentId } = req.body;
  if (!documentId) return apiResponse.badRequest(res, 'documentId is required');

  const companyId = (req as any).companyId as string;

  // Get captured document
  const docs = await sql`SELECT * FROM captured_documents WHERE id = ${documentId} AND company_id = ${companyId}` as Row[];
  if (!docs[0]) return apiResponse.notFound(res, 'Document', documentId);

  const doc = docs[0] as any;
  const extracted = doc.extracted_data;
  if (!extracted) return apiResponse.badRequest(res, 'Document has no extracted data');

  // Calculate field confidence
  const fieldConfidence = calculateFieldConfidence({
    vendorName: extracted.vendorName || extracted.vendor?.name || '',
    documentDate: extracted.documentDate || '',
    referenceNumber: extracted.referenceNumber || '',
    subtotal: Number(extracted.subtotal || 0),
    vatAmount: Number(extracted.vatAmount || 0),
    totalAmount: Number(extracted.totalAmount || 0),
    lineItems: extracted.lineItems || [],
  });

  // Fuzzy match supplier
  const suppliers = await sql`SELECT id, name FROM suppliers WHERE company_id = ${companyId}::UUID AND is_active = true` as Row[];
  const vendorName = extracted.vendorName || extracted.vendor?.name || '';
  const supplierMatch = fuzzyMatchSupplier(vendorName, suppliers.map((s: any) => ({ id: String(s.id), name: String(s.name) })));

  if (!supplierMatch) {
    return apiResponse.success(res, {
      matched: false,
      message: `No supplier match found for "${vendorName}"`,
      fieldConfidence,
      extractedData: extracted,
    });
  }

  // Build auto-invoice data
  const invoiceData = buildAutoInvoiceFromExtraction({
    vendorName,
    documentDate: extracted.documentDate || '',
    referenceNumber: extracted.referenceNumber || '',
    subtotal: Number(extracted.subtotal || 0),
    vatAmount: Number(extracted.vatAmount || 0),
    totalAmount: Number(extracted.totalAmount || 0),
    lineItems: extracted.lineItems || [],
  }, supplierMatch.supplierId);

  log.info('Auto-invoice prepared from document', {
    documentId, supplierId: supplierMatch.supplierId, total: invoiceData.totalAmount,
  }, 'ai');

  return apiResponse.success(res, {
    matched: true,
    supplierMatch,
    invoiceData,
    fieldConfidence,
  });
}

export default withCompany(withErrorHandler(handler));

/**
 * Projects API — CRUD
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateProject } from '@/modules/accounting/services/projectAccountingService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  const companyId = (req as any).companyId as string;

  if (req.method === 'GET') {
    const { status, clientId } = req.query;
    let rows: Row[];
    if (status) {
      rows = await sql`SELECT p.*, c.name as client_name FROM projects p LEFT JOIN customers c ON p.client_id = c.id WHERE p.company_id = ${companyId}::UUID AND p.status = ${String(status)} ORDER BY p.created_at DESC` as Row[];
    } else {
      rows = await sql`SELECT p.*, c.name as client_name FROM projects p LEFT JOIN customers c ON p.client_id = c.id WHERE p.company_id = ${companyId}::UUID ORDER BY p.created_at DESC LIMIT 200` as Row[];
    }
    return apiResponse.success(res, rows);
  }

  if (req.method === 'POST') {
    const body = req.body;
    const validation = validateProject(body);
    if (!validation.success) return apiResponse.validationError(res, Object.fromEntries((validation.errors || []).map(e => [e.field, e.message])));

    const countRes = await sql`SELECT COUNT(*) as cnt FROM projects WHERE company_id = ${companyId}::UUID` as Row[];
    const projNum = `PROJ-${String(Number((countRes[0] as any)?.cnt || 0) + 1).padStart(4, '0')}`;

    const inserted = await sql`
      INSERT INTO projects (company_id, project_number, name, description, client_id, billing_method, start_date, end_date, budget_amount, created_by)
      VALUES (${companyId}::UUID, ${projNum}, ${body.name}, ${body.description || null}, ${body.clientId || null}, ${body.billingMethod || 'time_and_materials'}, ${body.startDate || null}, ${body.endDate || null}, ${body.budgetAmount || 0}, ${String(req.user.id)})
      RETURNING *
    ` as Row[];

    log.info('Project created', { projNum, name: body.name }, 'accounting');
    return apiResponse.created(res, inserted[0]);
  }

  return apiResponse.methodNotAllowed(res, req.method!, ['GET', 'POST']);
}
export default withCompany(withErrorHandler(handler));

/**
 * Anomaly Detection Scan API
 * POST: run anomaly detection on recent transactions
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  benfordsLawAnalysis, detectStatisticalOutliers, detectDuplicatePayments,
  detectUnusualPostingPatterns, buildAlertMessage, type Transaction,
} from '@/modules/accounting/services/anomalyDetectionService';

type Row = Record<string, unknown>;

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const companyId = (req as any).companyId as string;
  const { period } = req.body;
  const fromDate = period || new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

  // Get recent transactions
  const txRows = await sql`
    SELECT id, description, amount, transaction_date as date FROM bank_transactions
    WHERE transaction_date >= ${fromDate} ORDER BY transaction_date DESC LIMIT 1000
  ` as Row[];
  const transactions: Transaction[] = txRows.map((r: any) => ({ id: String(r.id), amount: Number(r.amount), description: String(r.description), date: String(r.date) }));

  // Get recent payments for duplicate detection
  const payRows = await sql`
    SELECT sp.id, sp.supplier_id, sp.total_amount as amount, sp.payment_date as date, sp.reference
    FROM supplier_payments sp WHERE sp.payment_date >= ${fromDate}
    ORDER BY sp.payment_date DESC LIMIT 500
  ` as Row[];
  const payments = payRows.map((r: any) => ({ id: String(r.id), supplierId: String(r.supplier_id), amount: Number(r.amount), date: String(r.date), reference: String(r.reference || '') }));

  // Get journal entries for posting pattern analysis
  const jeRows = await sql`
    SELECT je.id, je.entry_date as date, jl.debit + jl.credit as amount, je.created_by as user_id, je.description
    FROM gl_journal_entries je JOIN gl_journal_lines jl ON je.id = jl.journal_entry_id
    WHERE je.entry_date >= ${fromDate} AND je.source = 'manual'
    LIMIT 500
  ` as Row[];
  const entries = jeRows.map((r: any) => ({ id: String(r.id), date: String(r.date), amount: Number(r.amount), userId: String(r.user_id), description: String(r.description || '') }));

  // Run all detections
  const benfords = benfordsLawAnalysis(transactions.map(t => Math.abs(t.amount)));
  const outliers = detectStatisticalOutliers(transactions);
  const duplicates = detectDuplicatePayments(payments);
  const patterns = detectUnusualPostingPatterns(entries);

  // Build alerts
  const alerts = [];
  if (!benfords.conforming && benfords.sampleSize > 20) {
    alerts.push(buildAlertMessage('benfords_violation', 'warning', { chiSquare: benfords.chiSquare }));
  }
  for (const o of outliers.outliers.slice(0, 5)) {
    alerts.push(buildAlertMessage('unusual_amount', 'warning', { amount: o.amount, description: o.description }));
  }
  for (const d of duplicates) {
    alerts.push(buildAlertMessage('duplicate_payment', d.confidence >= 0.9 ? 'critical' : 'warning', { amount: d.amount, supplier: d.supplierId }));
  }
  for (const p of patterns) {
    alerts.push(buildAlertMessage(p.type, 'info', { count: p.entryIds.length }));
  }

  log.info('Anomaly scan completed', { alerts: alerts.length, transactions: transactions.length }, 'ai');

  return apiResponse.success(res, {
    benfords, outliers: { count: outliers.outliers.length, items: outliers.outliers.slice(0, 10) },
    duplicates, patterns, alerts, scannedTransactions: transactions.length,
  });
}
export default withCompany(withErrorHandler(handler));

/**
 * Natural Language Financial Query API
 * POST: ask a question in plain English, get data back
 */
import type { NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  buildTextToSQLPrompt, parseSQLResponse, validateGeneratedSQL,
  formatQueryResult, buildSchemaDescription, classifyQueryIntent,
  type SchemaTable,
} from '@/modules/accounting/services/nlQueryService';

type Row = Record<string, unknown>;

const SCHEMA_TABLES: SchemaTable[] = [
  { name: 'customer_invoices', columns: ['id', 'customer_id', 'invoice_number', 'invoice_date', 'due_date', 'total_amount', 'amount_paid', 'status', 'company_id'], description: 'Customer/sales invoices' },
  { name: 'customers', columns: ['id', 'name', 'email', 'payment_terms', 'is_active', 'company_id'], description: 'Customer master data' },
  { name: 'supplier_invoices', columns: ['id', 'supplier_id', 'invoice_number', 'invoice_date', 'total_amount', 'amount_paid', 'status', 'company_id'], description: 'Supplier/purchase invoices' },
  { name: 'suppliers', columns: ['id', 'name', 'email', 'is_active', 'company_id'], description: 'Supplier master data' },
  { name: 'gl_accounts', columns: ['id', 'account_code', 'account_name', 'account_type', 'is_active', 'company_id'], description: 'Chart of accounts (GL)' },
  { name: 'gl_journal_entries', columns: ['id', 'entry_number', 'entry_date', 'description', 'status', 'source'], description: 'Journal entries' },
  { name: 'gl_journal_lines', columns: ['id', 'journal_entry_id', 'gl_account_id', 'debit', 'credit', 'description'], description: 'Journal entry lines (debits/credits)' },
  { name: 'bank_transactions', columns: ['id', 'bank_account_id', 'date', 'description', 'amount', 'category', 'is_reconciled'], description: 'Imported bank transactions' },
  { name: 'products', columns: ['id', 'code', 'name', 'cost_price', 'selling_price', 'current_stock', 'company_id'], description: 'Products/inventory items' },
  { name: 'employees', columns: ['id', 'first_name', 'last_name', 'email', 'basic_salary', 'employment_type', 'company_id'], description: 'Employee master data' },
  { name: 'payslips', columns: ['id', 'employee_id', 'payroll_run_id', 'gross_pay', 'net_pay', 'paye', 'uif_employee'], description: 'Payslips per payroll run' },
  { name: 'projects', columns: ['id', 'project_number', 'name', 'client_id', 'status', 'budget_amount', 'total_revenue', 'total_cost'], description: 'Projects/jobs' },
];

async function handler(req: AuthenticatedNextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return apiResponse.methodNotAllowed(res, req.method!, ['POST']);

  const { question } = req.body;
  if (!question || typeof question !== 'string' || question.trim().length < 3) {
    return apiResponse.badRequest(res, 'Please ask a question (minimum 3 characters)');
  }
  if (question.length > 500) {
    return apiResponse.badRequest(res, 'Question is too long (maximum 500 characters)');
  }

  const companyId = (req as any).companyId as string;
  const intent = classifyQueryIntent(question);
  const schemaDesc = buildSchemaDescription(SCHEMA_TABLES);
  const prompt = buildTextToSQLPrompt(question, schemaDesc, companyId);

  // Call Claude
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) {
    return apiResponse.success(res, {
      intent,
      message: 'Natural language queries require ANTHROPIC_API_KEY to be configured.',
      rows: [], columns: [], summary: 'AI not configured',
    });
  }

  try {
    const response = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': apiKey,
        'anthropic-version': '2023-06-01',
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 512,
        messages: [{ role: 'user', content: prompt }],
      }),
    });

    if (!response.ok) {
      return apiResponse.success(res, { intent, message: 'AI service unavailable', rows: [], columns: [], summary: 'Service error' });
    }

    const data = await response.json() as any;
    const text = data.content?.[0]?.text || '';
    const parsed = parseSQLResponse(text);

    if (!parsed) {
      return apiResponse.success(res, { intent, message: 'Could not generate a query for that question.', explanation: text, rows: [], columns: [], summary: 'Unable to parse' });
    }

    // Validate SQL
    const validation = validateGeneratedSQL(parsed.sql);
    if (!validation.valid) {
      return apiResponse.success(res, { intent, message: `Generated SQL was rejected: ${validation.error}`, rows: [], columns: [], summary: 'Query rejected' });
    }

    // Verify company_id appears in an actual "company_id = '<uuid>'" predicate,
    // not just anywhere in the string (e.g. a comment, alias, or lucky substring).
    const scopeRegex = new RegExp(`company_id\\s*=\\s*'${companyId}'`, 'i');
    if (!scopeRegex.test(validation.sanitizedSQL)) {
      log.warn('NL query missing company_id scope — rejected', { question, companyId }, 'ai');
      return apiResponse.success(res, { intent, message: 'Could not generate a properly scoped query. Please try again.', rows: [], columns: [], summary: 'Scope error' });
    }

    // Execute inside a transaction so SET LOCAL applies to the same connection.
    // Neon HTTP driver is stateless — each top-level sql`` call is a separate
    // HTTP request, so a bare SET statement_timeout would have no effect on the
    // next call.  sql.transaction() batches both statements into a single HTTP
    // request, guaranteeing SET LOCAL is honoured for the query that follows it.
    const [, rows] = await sql.transaction(
      (txn) => [
        txn`SET LOCAL statement_timeout = '5000'`,
        txn.unsafe(validation.sanitizedSQL) as any,
      ]
    ) as [unknown, Row[]];
    const formatted = formatQueryResult(rows as Record<string, unknown>[], question);

    log.info('NL query executed', { question, intent, rowCount: formatted.rowCount }, 'ai');

    return apiResponse.success(res, {
      intent,
      question,
      sql: validation.sanitizedSQL,
      explanation: parsed.explanation,
      ...formatted,
    });
  } catch (err) {
    log.error('NL query failed', { error: err }, 'ai');
    return apiResponse.success(res, { intent, message: 'Query execution failed', rows: [], columns: [], summary: 'Error' });
  }
}

export default withCompany(withErrorHandler(handler));

