/**
 * Sidebar navigation using the same TABS config as the top-bar.
 * Hover a tab → flyout panel pops to the right via a portal on document.body.
 * Sub-sections cascade further right, also via portals so nothing is clipped.
 */

import { useState, useRef, useEffect, useCallback } from 'react';
import { createPortal } from 'react-dom';
import { useRouter } from 'next/router';
import Link from 'next/link';
import { ChevronRight } from 'lucide-react';
import {
  TABS,
  getActiveTabId,
  isFlyout,
  isLinkActive,
  type Tab,
  type NavItem,
} from '../accounting/accountingNavConfig';

// ─── Shared styles ──────────────────────────────────────────────────────────

const panelCls = 'bg-gray-800 border border-gray-700 rounded-lg shadow-2xl min-w-[210px] py-1';

const linkCls = (active: boolean) =>
  `block px-4 py-1.5 text-sm whitespace-nowrap transition-colors ${
    active ? 'text-teal-400 bg-teal-500/10 font-medium' : 'text-gray-300 hover:text-white hover:bg-gray-700/50'
  }`;

// ─── Recursive section flyout using portals ─────────────────────────────────

function SectionFlyout({
  label,
  items,
  asPath,
  onNav,
  parentRight,
  parentTop,
}: {
  label: string;
  items: NavItem[];
  asPath: string;
  onNav: () => void;
  parentRight: number;
  parentTop: number;
}) {
  const [open, setOpen] = useState(false);
  const [subPos, setSubPos] = useState<{ top: number; left: number } | null>(null);
  const ref = useRef<HTMLDivElement>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const cl = () => { if (timer.current) clearTimeout(timer.current); };
  const dl = () => { timer.current = setTimeout(() => setOpen(false), 150); };
  useEffect(() => () => cl(), []);

  const handleEnter = () => {
    cl();
    setOpen(true);
    if (ref.current) {
      const rect = ref.current.getBoundingClientRect();
      setSubPos({ top: rect.top, left: rect.right });
    }
  };

  return (
    <div ref={ref} onMouseEnter={handleEnter} onMouseLeave={dl}>
      <div className={`flex items-center justify-between px-4 py-2 text-sm cursor-default transition-colors ${
        open ? 'bg-gray-700 text-white' : 'text-gray-300 hover:text-gray-600'
      }`}>
        <span className="font-medium">{label}</span>
        <ChevronRight className="h-3.5 w-3.5 ml-4 flex-shrink-0" />
      </div>

      {open && subPos && createPortal(
        <div
          style={{ position: 'fixed', top: subPos.top, left: subPos.left, zIndex: 99999 }}
          className={panelCls}
          onMouseEnter={cl}
          onMouseLeave={dl}
        >
          {items.map(item => {
            if (!isFlyout(item)) {
              return (
                <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>
                  {item.label}
                </Link>
              );
            }
            // Nested section → recurse
            return (
              <SectionFlyout
                key={item.section}
                label={item.section}
                items={item.items}
                asPath={asPath}
                onNav={onNav}
                parentRight={subPos.left + 210}
                parentTop={subPos.top}
              />
            );
          })}
        </div>,
        document.body
      )}
    </div>
  );
}

// ─── Tab flyout content ─────────────────────────────────────────────────────

function TabFlyoutContent({ tab, asPath, onNav }: { tab: Tab; asPath: string; onNav: () => void }) {
  const hasSections = tab.items?.some(isFlyout) ?? false;

  return (
    <>
      {/* Quick actions */}
      {tab.topItems?.map(item => (
        <Link key={item.href} href={item.href} onClick={onNav}
          className="block px-4 py-2 text-sm text-teal-400 hover:bg-gray-700/50 transition-colors whitespace-nowrap">
          + {item.label}
        </Link>
      ))}
      {tab.topItems && tab.topItems.length > 0 && <div className="border-t border-gray-700 my-1" />}

      {/* Sections with sub-flyouts */}
      {hasSections && tab.items?.map(item => {
        if (!isFlyout(item)) {
          return <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>{item.label}</Link>;
        }
        return (
          <SectionFlyout
            key={item.section}
            label={item.section}
            items={item.items}
            asPath={asPath}
            onNav={onNav}
            parentRight={0}
            parentTop={0}
          />
        );
      })}

      {/* Flat items */}
      {!hasSections && tab.items?.map(item => {
        if (isFlyout(item)) return null;
        return <Link key={item.href} href={item.href} onClick={onNav} className={linkCls(isLinkActive(item.href, asPath))}>{item.label}</Link>;
      })}
    </>
  );
}

// ─── Main sidebar nav ───────────────────────────────────────────────────────

interface SidebarNavProps {
  collapsed?: boolean;
}

export function SidebarNav({ collapsed }: SidebarNavProps) {
  const router = useRouter();
  const asPath = router.asPath;
  const activeTabId = getActiveTabId(router.pathname, router.query);

  const [flyout, setFlyout] = useState<{ tabId: string; top: number; left: number } | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cl = useCallback(() => { if (timer.current) { clearTimeout(timer.current); timer.current = null; } }, []);
  const dl = useCallback(() => { timer.current = setTimeout(() => setFlyout(null), 180); }, []);

  useEffect(() => { setFlyout(null); }, [router.pathname]);
  useEffect(() => () => cl(), [cl]);

  const openFlyout = useCallback((tabId: string, el: HTMLElement) => {
    cl();
    const rect = el.getBoundingClientRect();
    setFlyout({ tabId, top: rect.top, left: rect.right });
  }, [cl]);

  const flyoutTab = flyout ? TABS.find(t => t.id === flyout.tabId) : null;

  return (
    <>
      <nav className="flex-1 overflow-y-auto py-2">
        {TABS.map(tab => {
          const active = activeTabId === tab.id;
          const hasItems = !!(tab.items?.length);
          const isOpen = flyout?.tabId === tab.id;

          if (tab.href && !hasItems) {
            return (
              <Link key={tab.id} href={tab.href}
                className={`flex items-center px-4 py-2 text-sm font-medium transition-colors border-l-2 ${
                  active ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-teal-500'
                    : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-transparent'
                } ${collapsed ? 'justify-center px-0' : ''}`}
                title={collapsed ? tab.label : undefined}>
                {collapsed ? tab.label.slice(0, 2) : tab.label}
              </Link>
            );
          }

          return (
            <div key={tab.id}
              onMouseEnter={(e) => openFlyout(tab.id, e.currentTarget)}
              onMouseLeave={dl}
              className={`flex items-center justify-between px-4 py-2 text-sm font-medium cursor-pointer transition-colors border-l-2 ${
                active || isOpen ? 'text-teal-600 dark:text-teal-400 bg-teal-500/10 border-teal-500'
                  : 'text-gray-700 dark:text-gray-300 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 border-transparent'
              } ${collapsed ? 'justify-center px-0' : ''}`}
              title={collapsed ? tab.label : undefined}>
              <span>{collapsed ? tab.label.slice(0, 2) : tab.label}</span>
              {!collapsed && <ChevronRight className={`w-3.5 h-3.5 flex-shrink-0 ${isOpen ? 'text-teal-400' : 'text-gray-500'}`} />}
            </div>
          );
        })}
      </nav>

      {/* First-level flyout via portal */}
      {flyoutTab && flyout && createPortal(
        <div
          style={{ position: 'fixed', top: flyout.top, left: flyout.left, zIndex: 99999 }}
          className={panelCls}
          onMouseEnter={cl}
          onMouseLeave={dl}
        >
          <TabFlyoutContent tab={flyoutTab} asPath={asPath} onNav={() => setFlyout(null)} />
        </div>,
        document.body
      )}
    </>
  );
}

/**
 * Sage-style horizontal navigation bar for accounting pages.
 * Delegates to ModuleNav with teal accent colors.
 */

import { ModuleNav } from '../layout/ModuleNav';
import { TABS, getActiveTabId } from './accountingNavConfig';

export function AccountingNav() {
  return <ModuleNav tabs={TABS} getActiveTabId={getActiveTabId} accentColor="teal" />;
}

/**
 * Admin sidebar navigation component.
 * Vertically stacked links with active state highlighting.
 */

import Link from 'next/link';
import { useRouter } from 'next/router';
import { useAdminPrefix } from '@/hooks/useAdminPrefix';
import {
  LayoutDashboard,
  Building2,
  Users,
  CreditCard,
  Wrench,
  ScrollText,
  Settings,
  BarChart2,
  ChevronRight,
  List,
  FileText,
  Megaphone,
  Palette,
} from 'lucide-react';

interface NavItem {
  label: string;
  href: string;
  icon: React.ComponentType<{ className?: string }>;
  disabled?: boolean;
  children?: { label: string; href: string; icon: React.ComponentType<{ className?: string }> }[];
}

/** Paths relative to the admin root — prefix is applied dynamically */
const NAV_DEFS: { label: string; path: string; icon: React.ComponentType<{ className?: string }>; disabled?: boolean; children?: { label: string; path: string; icon: React.ComponentType<{ className?: string }> }[] }[] = [
  { label: 'Dashboard',   path: '',           icon: LayoutDashboard },
  { label: 'Companies',   path: '/companies', icon: Building2 },
  { label: 'Users',       path: '/users',     icon: Users },
  {
    label: 'Billing',
    path: '/billing',
    icon: CreditCard,
    children: [
      { label: 'Overview',      path: '/billing',               icon: CreditCard },
      { label: 'Plans',         path: '/billing/plans',         icon: CreditCard },
      { label: 'Subscriptions', path: '/billing/subscriptions', icon: List },
      { label: 'Invoices',      path: '/billing/invoices',      icon: FileText },
    ],
  },
  {
    label: 'Tools',
    path: '/tools',
    icon: Wrench,
    children: [
      { label: 'Overview',       path: '/tools',               icon: Wrench },
      { label: 'Announcements',  path: '/tools/announcements', icon: Megaphone },
    ],
  },
  { label: 'Audit Trail', path: '/audit',      icon: ScrollText },
  { label: 'Analytics',  path: '/analytics',  icon: BarChart2 },
  { label: 'Components', path: '/components', icon: Palette },
  { label: 'Settings',   path: '/settings',   icon: Settings },
];

export function AdminNav() {
  const router = useRouter();
  const prefix = useAdminPrefix();

  /** Build nav items with the correct prefix applied */
  const navItems = NAV_DEFS.map(def => ({
    ...def,
    href: prefix + def.path || '/',
    children: def.children?.map(c => ({ ...c, href: prefix + c.path })),
  }));

  /** Use asPath for active state — it reflects the browser URL (clean on subdomain) */
  const currentPath = router.asPath.split('?')[0] ?? '/';

  const isActive = (href: string) => {
    const root = prefix || '/';
    if (href === root) return currentPath === root;
    return currentPath.startsWith(href);
  };

  const isSectionOpen = (href: string) => currentPath.startsWith(href);

  return (
    <aside className="w-56 flex-shrink-0 bg-gray-900 border-r border-gray-700 flex flex-col min-h-full">
      <div className="px-4 py-4 border-b border-gray-700">
        <p className="text-xs font-semibold text-gray-400 uppercase tracking-wider">Admin Console</p>
      </div>
      <nav className="flex-1 py-3 px-2 space-y-0.5">
        {navItems.map(item => {
          const Icon = item.icon;

          if (item.disabled) {
            return (
              <div
                key={item.href}
                className="flex items-center gap-3 px-3 py-2 rounded-lg text-gray-600 cursor-not-allowed select-none"
                title="Coming Soon"
              >
                <Icon className="w-4 h-4 flex-shrink-0" />
                <span className="text-sm">{item.label}</span>
                <span className="ml-auto text-xs text-gray-700 font-medium">Soon</span>
              </div>
            );
          }

          if (item.children) {
            const parentActive = isActive(item.href);
            return (
              <div key={item.href}>
                <Link
                  href={item.href}
                  className={[
                    'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                    parentActive
                      ? 'bg-teal-600 text-white font-medium'
                      : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
                  ].join(' ')}
                >
                  <Icon className="w-4 h-4 flex-shrink-0" />
                  <span>{item.label}</span>
                  <ChevronRight className={`w-3.5 h-3.5 ml-auto transition-transform ${isSectionOpen(item.href) ? 'rotate-90' : ''}`} />
                </Link>

                {isSectionOpen(item.href) && (
                  <div className="ml-3 mt-0.5 space-y-0.5 border-l border-gray-700 pl-3">
                    {item.children.map(child => {
                      const ChildIcon = child.icon;
                      const childActive = currentPath === child.href;
                      return (
                        <Link
                          key={child.href}
                          href={child.href}
                          className={[
                            'flex items-center gap-2 px-2 py-1.5 rounded-lg text-xs transition-colors',
                            childActive
                              ? 'bg-teal-600/80 text-white font-medium'
                              : 'text-gray-400 hover:bg-gray-700/50 hover:text-white',
                          ].join(' ')}
                        >
                          <ChildIcon className="w-3.5 h-3.5 flex-shrink-0" />
                          <span>{child.label}</span>
                        </Link>
                      );
                    })}
                  </div>
                )}
              </div>
            );
          }

          const active = isActive(item.href);
          return (
            <Link
              key={item.href}
              href={item.href}
              className={[
                'flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors',
                active
                  ? 'bg-teal-600 text-white font-medium'
                  : 'text-gray-300 hover:bg-gray-700/60 hover:text-white',
              ].join(' ')}
            >
              <Icon className="w-4 h-4 flex-shrink-0" />
              <span>{item.label}</span>
            </Link>
          );
        })}
      </nav>
    </aside>
  );
}

/**
 * Standalone AppLayout for the Accounting app.
 * Supports two nav modes: top-bar (Sage-style, default) or sidebar.
 * User preference persisted in localStorage.
 */

import { useState, useEffect, useRef, ReactNode, useMemo } from 'react';
import { useRouter } from 'next/router';
import {
  BookOpen,
  ChevronLeft,
  ChevronRight,
  Menu,
  LogOut,
  User,
  Moon,
  Sun,
  PanelLeft,
  PanelTop,
  Download,
  X as XIcon,
  Search,
} from 'lucide-react';
import dynamic from 'next/dynamic';
import { useAuth } from '@/contexts/AuthContext';
import { useTheme } from '@/contexts/ThemeContext';
import { useCompany } from '@/contexts/CompanyContext';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';
import { CompanySwitcher } from '@/components/layout/CompanySwitcher';
import { CreateNewMenu } from '@/components/layout/CreateNewMenu';
import { SidebarNav } from '@/components/layout/SidebarNav';
import { CommandPalette } from '@/components/layout/CommandPalette';
import { ShortcutHelpOverlay } from '@/components/layout/ShortcutHelpOverlay';
import { useKeyboardShortcuts } from '@/hooks/useKeyboardShortcuts';
import type { ShortcutConfig } from '@/lib/keyboard-shortcuts';
import { AccountingTour } from '@/components/onboarding/AccountingTour';
import { SetupGuideButton } from '@/components/onboarding/SetupGuideButton';

const AccountingNav = dynamic(
  () => import('@/components/accounting/AccountingNav').then(mod => ({ default: mod.AccountingNav })),
);

const SIDEBAR_COLLAPSED_KEY = 'accounting-sidebar-collapsed';
const NAV_MODE_KEY = 'accounting-nav-mode';
const PWA_INSTALL_DISMISSED_KEY = 'isaflow-pwa-install-dismissed';

type NavMode = 'top' | 'side';

// ─── Props ──────────────────────────────────────────────────────────────────

interface AppLayoutProps {
  children: ReactNode;
}

// ─── Component ──────────────────────────────────────────────────────────────

export function AppLayout({ children }: AppLayoutProps) {
  const router = useRouter();
  const { user, loading, logout } = useAuth();
  const { theme, toggleTheme } = useTheme();
  const { companyRole } = useCompany();

  // On admin subdomain, hide accounting-specific UI (nav, company switcher, etc.)
  const [isAdminHost, setIsAdminHost] = useState(false);
  useEffect(() => {
    if (typeof window !== 'undefined' && window.location.hostname === 'admin.isaflow.co.za') {
      setIsAdminHost(true);
    }
  }, []);

  // Command palette
  const [commandPaletteOpen, setCommandPaletteOpen] = useState(false);

  // Shortcut help overlay
  const [shortcutHelpOpen, setShortcutHelpOpen] = useState(false);

  // Nav mode preference
  const [navMode, setNavMode] = useState<NavMode>('top');

  // Mobile sidebar open state (used in both modes for mobile)
  const [mobileOpen, setMobileOpen] = useState(false);

  // Desktop collapsed state (sidebar mode only)
  const [collapsed, setCollapsed] = useState(false);
  const [hydrated, setHydrated] = useState(false);

  // PWA install prompt
  const deferredPromptRef = useRef<Event | null>(null);
  const [showInstallBanner, setShowInstallBanner] = useState(false);

  useEffect(() => {
    const savedMode = localStorage.getItem(NAV_MODE_KEY) as NavMode | null;
    if (savedMode === 'top' || savedMode === 'side') setNavMode(savedMode);
    const savedCollapsed = localStorage.getItem(SIDEBAR_COLLAPSED_KEY);
    if (savedCollapsed !== null) setCollapsed(JSON.parse(savedCollapsed) as boolean);
    setHydrated(true);
  }, []);

  // Listen for PWA install prompt
  useEffect(() => {
    const dismissed = localStorage.getItem(PWA_INSTALL_DISMISSED_KEY);
    if (dismissed) return;

    const handler = (e: Event) => {
      e.preventDefault();
      deferredPromptRef.current = e;
      setShowInstallBanner(true);
    };
    window.addEventListener('beforeinstallprompt', handler);
    return () => window.removeEventListener('beforeinstallprompt', handler);
  }, []);

  useEffect(() => {
    if (hydrated) {
      localStorage.setItem(NAV_MODE_KEY, navMode);
      localStorage.setItem(SIDEBAR_COLLAPSED_KEY, JSON.stringify(collapsed));
    }
  }, [collapsed, navMode, hydrated]);

  // ─── Global keyboard shortcuts ────────────────────────────────────────────
  const globalShortcuts = useMemo<ShortcutConfig[]>(() => [
    {
      key: 'ctrl+k',
      label: 'Ctrl+K',
      description: 'Open command palette',
      category: 'global',
      action: () => setCommandPaletteOpen(true),
    },
    {
      key: '?',
      label: '?',
      description: 'Show keyboard shortcuts',
      category: 'global',
      action: () => setShortcutHelpOpen(true),
    },
    // Navigation sequences — press G then the second key within 1 second
    {
      key: 'g d',
      label: 'G then D',
      description: 'Go to Dashboard',
      category: 'navigation',
      action: () => { void router.push('/accounting'); },
    },
    {
      key: 'g c',
      label: 'G then C',
      description: 'Go to Customers',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=customers'); },
    },
    {
      key: 'g s',
      label: 'G then S',
      description: 'Go to Suppliers',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=suppliers'); },
    },
    {
      key: 'g b',
      label: 'G then B',
      description: 'Go to Banking',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=banking'); },
    },
    {
      key: 'g a',
      label: 'G then A',
      description: 'Go to Accounts',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=accounts'); },
    },
    {
      key: 'g r',
      label: 'G then R',
      description: 'Go to Reports',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=reports'); },
    },
    {
      key: 'g v',
      label: 'G then V',
      description: 'Go to VAT',
      category: 'navigation',
      action: () => { void router.push('/accounting?tab=vat'); },
    },
  ], [router]);

  useKeyboardShortcuts(globalShortcuts);

  // Close mobile nav on route change
  useEffect(() => {
    setMobileOpen(false);
  }, [router.pathname]);

  const toggleNavMode = () => setNavMode(m => m === 'top' ? 'side' : 'top');

  const handleInstall = async () => {
    const prompt = deferredPromptRef.current as (Event & { prompt: () => Promise<void> }) | null;
    if (!prompt) return;
    await prompt.prompt();
    deferredPromptRef.current = null;
    setShowInstallBanner(false);
  };

  const dismissInstall = () => {
    setShowInstallBanner(false);
    localStorage.setItem(PWA_INSTALL_DISMISSED_KEY, '1');
  };

  const userInitials = user
    ? (`${user.firstName?.[0] ?? ''}${user.lastName?.[0] ?? ''}`.toUpperCase() || user.email?.[0]?.toUpperCase() || 'U')
    : 'U';

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-950">
        <div className="text-center">
          <LoadingSpinner size="lg" className="mx-auto mb-4" />
          <p className="text-gray-400 text-sm">Loading...</p>
        </div>
      </div>
    );
  }

  // ─── Sidebar content (shared between mobile + desktop sidebar) ────────────

  const SidebarContent = (
    <>
      {/* Logo */}
      <div className={`flex items-center px-4 py-4 border-b border-gray-200 dark:border-gray-700 ${collapsed ? 'justify-center' : ''}`}>
        {collapsed ? (
          <div className="w-8 h-8 bg-teal-600 rounded-lg flex items-center justify-center flex-shrink-0">
            <BookOpen className="w-4 h-4 text-white" />
          </div>
        ) : (
          <img src="/logo.png" alt="ISAFlow" className="h-9 w-auto dark:brightness-0 dark:invert" />
        )}
      </div>

      {/* Nav — uses same TABS config as top nav */}
      <SidebarNav collapsed={collapsed} />

      {/* User area */}
      <div className={`border-t border-gray-200 dark:border-gray-700 p-3 ${collapsed ? 'flex flex-col items-center gap-2' : ''}`}>
        {user && !collapsed && (
          <div className="flex items-center gap-2 px-2 py-2 mb-1">
            <div className="w-7 h-7 bg-teal-700 rounded-full flex items-center justify-center flex-shrink-0">
              <span className="text-xs text-white font-semibold">{userInitials}</span>
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-xs font-medium text-gray-900 dark:text-white truncate">
                {user.firstName} {user.lastName}
              </p>
              <p className="text-xs text-gray-500 truncate capitalize">{companyRole || user.role}</p>
            </div>
          </div>
        )}
        <button
          onClick={() => void logout()}
          title={collapsed ? 'Log out' : undefined}
          className={`
            flex items-center gap-2 w-full px-3 py-2 rounded-lg text-sm text-gray-500 dark:text-gray-400
            hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors
            ${collapsed ? 'justify-center' : ''}
          `}
        >
          <LogOut className="w-4 h-4 flex-shrink-0" />
          {!collapsed && <span>Log out</span>}
        </button>
      </div>
    </>
  );

  const showSidebar = navMode === 'side';

  return (
    <div className="flex h-screen bg-white dark:bg-gray-950 overflow-hidden">

      {/* ── Desktop sidebar (only in side mode) ──────────────────────────── */}
      {showSidebar && (
        <aside
          className={`
            hidden lg:flex flex-col bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700
            transition-all duration-300 flex-shrink-0
            ${collapsed ? 'w-16' : 'w-64'}
          `}
        >
          {SidebarContent}

          {/* Collapse toggle */}
          <button
            onClick={() => setCollapsed(c => !c)}
            className="flex items-center justify-center h-10 border-t border-gray-200 dark:border-gray-700 text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={collapsed ? 'Expand sidebar' : 'Collapse sidebar'}
          >
            {collapsed
              ? <ChevronRight className="w-4 h-4" />
              : <ChevronLeft className="w-4 h-4" />
            }
          </button>
        </aside>
      )}

      {/* ── Mobile sidebar overlay (always available for mobile) ──────── */}
      {mobileOpen && (
        <div
          className="fixed inset-0 z-30 bg-black/60 lg:hidden"
          onClick={() => setMobileOpen(false)}
        />
      )}
      <aside
        className={`
          fixed inset-y-0 left-0 z-40 w-64 bg-gray-50 dark:bg-gray-900 border-r border-gray-200 dark:border-gray-700
          flex flex-col lg:hidden transition-transform duration-300
          ${mobileOpen ? 'translate-x-0' : '-translate-x-full'}
        `}
      >
        {SidebarContent}
      </aside>

      {/* ── Main area ────────────────────────────────────────────────────── */}
      <div className="flex-1 flex flex-col min-w-0">

        {/* PWA install banner */}
        {showInstallBanner && (
          <div className="bg-teal-600 text-white px-4 py-2 flex items-center justify-between text-sm flex-shrink-0">
            <div className="flex items-center gap-2">
              <Download className="w-4 h-4" />
              <span>Install IsaFlow for a faster, app-like experience</span>
            </div>
            <div className="flex items-center gap-2">
              <button onClick={handleInstall} className="px-3 py-1 bg-white/20 hover:bg-white/30 rounded text-xs font-medium transition-colors">
                Install
              </button>
              <button onClick={dismissInstall} className="p-1 hover:bg-white/20 rounded transition-colors" aria-label="Dismiss">
                <XIcon className="w-3.5 h-3.5" />
              </button>
            </div>
          </div>
        )}

        {/* Header bar */}
        <header className="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700 h-14 flex items-center px-4 gap-3 flex-shrink-0">
          {/* Mobile hamburger */}
          <button
            className="lg:hidden text-gray-400 hover:text-gray-900 dark:hover:text-white transition-colors"
            onClick={() => setMobileOpen(o => !o)}
            aria-label="Open menu"
          >
            <Menu className="w-5 h-5" />
          </button>

          {/* Logo (in top-nav mode, show logo here; in side mode it's in the sidebar) */}
          <img src="/logo.png" alt="ISAFlow" className="h-8 w-auto hidden sm:block dark:brightness-0 dark:invert" />

          {/* Company switcher (hidden on admin subdomain) */}
          {!isAdminHost && (
            <div data-tour="company-switcher">
              <CompanySwitcher />
            </div>
          )}

          <div className="flex-1" />

          {/* Quick create menu (hidden on admin subdomain) */}
          {!isAdminHost && <CreateNewMenu />}

          {/* Command palette trigger */}
          <button
            data-tour="command-palette"
            onClick={() => setCommandPaletteOpen(true)}
            className="
              hidden sm:flex items-center gap-2 px-3 py-1.5 rounded-lg text-sm
              text-[var(--ff-text-tertiary)] bg-[var(--ff-bg-secondary)]
              border border-[var(--ff-border-primary)]
              hover:border-teal-400 hover:text-[var(--ff-text-primary)]
              transition-colors
            "
            title="Search (Ctrl+K)"
          >
            <Search className="w-3.5 h-3.5" />
            <span className="text-xs">Search</span>
            <kbd className="ml-1 px-1 py-0.5 text-[10px] bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded">
              Ctrl+K
            </kbd>
          </button>

          {/* Mobile search icon */}
          <button
            onClick={() => setCommandPaletteOpen(true)}
            className="sm:hidden p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title="Search"
            aria-label="Open search"
          >
            <Search className="w-4 h-4" />
          </button>

          {/* Setup guide (hidden on admin subdomain) */}
          {!isAdminHost && <SetupGuideButton />}

          {/* Nav mode toggle */}
          <button
            onClick={toggleNavMode}
            className="p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={navMode === 'top' ? 'Switch to sidebar navigation' : 'Switch to top navigation'}
          >
            {navMode === 'top' ? <PanelLeft className="w-4 h-4" /> : <PanelTop className="w-4 h-4" />}
          </button>

          {/* Theme toggle */}
          <button
            onClick={toggleTheme}
            className="p-2 rounded-lg text-gray-400 hover:text-gray-900 dark:hover:text-white hover:bg-gray-100 dark:hover:bg-gray-700/50 transition-colors"
            title={theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'}
          >
            {theme === 'dark' ? <Sun className="w-4 h-4" /> : <Moon className="w-4 h-4" />}
          </button>

          {/* User info */}
          {user && (
            <div className="flex items-center gap-2 text-sm text-gray-500 dark:text-gray-400">
              <User className="w-4 h-4" />
              <span className="hidden sm:inline truncate max-w-[160px]">
                {user.firstName} {user.lastName}
              </span>
            </div>
          )}

          {/* Logout (visible in top-nav mode where sidebar user area is hidden) */}
          {!showSidebar && (
            <button
              onClick={() => void logout()}
              className="p-2 rounded-lg text-gray-400 hover:text-red-500 transition-colors"
              title="Log out"
            >
              <LogOut className="w-4 h-4" />
            </button>
          )}
        </header>

        {/* Horizontal nav bar (only in top mode, hidden on admin subdomain) */}
        {!showSidebar && !isAdminHost && (
          <div className="relative z-40">
            <AccountingNav />
          </div>
        )}

        {/* Page content */}
        <main className="flex-1 overflow-y-auto bg-white dark:bg-gray-950 p-4 lg:p-6 relative z-0">
          {children}
        </main>
      </div>

      {/* Command Palette */}
      <CommandPalette
        isOpen={commandPaletteOpen}
        onClose={() => setCommandPaletteOpen(false)}
      />

      {/* Shortcut Help Overlay — triggered by '?' */}
      <ShortcutHelpOverlay
        isOpen={shortcutHelpOpen}
        onClose={() => setShortcutHelpOpen(false)}
        shortcuts={globalShortcuts}
      />

      {/* Onboarding Tour */}
      <AccountingTour />
    </div>
  );
}

