/**
 * KPI Dashboard Service
 * Real-time financial KPIs from the general ledger, invoices, and bank accounts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ───────────────────────────────────────────────────────────────────

export interface DashboardKPIs {
  revenue: { total: number; priorTotal: number; changePercent: number };
  expenses: { total: number; priorTotal: number };
  grossProfit: { amount: number; margin: number };
  netProfit: { amount: number; margin: number };
  cash: { total: number; priorTotal: number; change: number };
  receivables: { total: number; overdue: number; avgDebtorDays: number };
  payables: { total: number; overdue: number; avgCreditorDays: number };
  activity: { invoicesIssued: number; paymentsReceived: number; journalsPosted: number };
}

export interface ChartPoint {
  month: string;
  revenue: number;
  expenses: number;
}

export interface CashFlowPoint {
  month: string;
  inflows: number;
  outflows: number;
}

export interface AgingBreakdownBucket {
  name: string;
  value: number;
}

export interface TopCustomer {
  name: string;
  revenue: number;
  invoiceCount: number;
}

export interface TopExpenseCategory {
  accountName: string;
  total: number;
  percentOfExpenses: number;
}

// ── Dashboard KPIs ──────────────────────────────────────────────────────────

export async function getDashboardKPIs(companyId: string,
  fromDate: string,
  toDate: string
): Promise<DashboardKPIs> {
  try {
    // Calculate prior period (same duration before fromDate)
    const from = new Date(fromDate);
    const to = new Date(toDate);
    const durationMs = to.getTime() - from.getTime();
    const priorFrom = new Date(from.getTime() - durationMs);
    const priorFromStr = priorFrom.toISOString().slice(0, 10);
    const priorToStr = new Date(from.getTime() - 86400000).toISOString().slice(0, 10);

    const [
      revenueRows,
      priorRevenueRows,
      expenseRows,
      priorExpenseRows,
      cashRows,
      priorCashRows,
      arRows,
      arOverdueRows,
      arDebtorDaysRows,
      apRows,
      apOverdueRows,
      apCreditorDaysRows,
      invoicesIssuedRows,
      paymentsReceivedRows,
      journalsPostedRows,
    ] = await Promise.all([
      // Current period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id

/**
 * KPI Dashboard API
 * GET /api/accounting/kpi-dashboard
 *   ?from=YYYY-MM-DD   - period start (defaults to start of current month)
 *   ?to=YYYY-MM-DD     - period end (defaults to today)
 *   ?months=N           - chart lookback months (default 6)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDashboardKPIs,
  getRevenueChart,
  getCashFlowChart,
  getAgingBreakdown,
  getTopCustomers,
  getTopExpenseCategories,
} from '@/modules/accounting/services/kpiService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;

    const from = req.query.from
      ? String(req.query.from)
      : `${year}-${String(month).padStart(2, '0')}-01`;
    const to = req.query.to
      ? String(req.query.to)
      : now.toISOString().slice(0, 10);
    const months = req.query.months ? Number(req.query.months) : 6;

    const [kpis, revenueChart, cashFlowChart, arAging, apAging, topCustomers, topExpenses] =
      await Promise.all([
        getDashboardKPIs(companyId, from, to),
        getRevenueChart(companyId, months),
        getCashFlowChart(companyId, months),
        getAgingBreakdown(companyId, 'ar'),
        getAgingBreakdown(companyId, 'ap'),
        getTopCustomers(companyId, 5),
        getTopExpenseCategories(companyId, 5),
      ]);

    return apiResponse.success(res, {
      kpis,
      revenueChart,
      cashFlowChart,
      arAging,
      apAging,
      topCustomers,
      topExpenses,
    });
  } catch (err) {
    log.error('Failed to load KPI dashboard', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, 'Failed to load KPI dashboard');
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

