    ['/accounting/debtors-manager', 'Debtor'],
    ['/accounting/statement-run', 'Statement'],
  ];

  const results = [];
  for (const [url, keyword] of pages) {
    try {
      const res = await fetch(url, { credentials: 'include' });
      const text = await res.text();
      const has500 = text.includes('"statusCode":500');
      const has404 = text.includes('"statusCode":404');
      const hasKeyword = text.toLowerCase().includes(keyword.toLowerCase());
      let status = 'OK';
      if (has500) status = '500-ERROR';
      else if (has404) status = '404-NOT-FOUND';
      else if (!hasKeyword) status = 'NO-CONTENT';
      results.push({ url, httpStatus: res.status, render: status });
    } catch (e) {
      results.push({ url, httpStatus: 0, render: 'FETCH-FAIL: ' + e.message });
    }
  }
  return results;
}

