/**
 * WidgetGrid — Responsive 3-column grid that renders configured widgets.
 * // WORKING: Edit mode, add/remove widgets, reset to default layout.
 */

import { useState, useCallback } from 'react';
import { Plus, RotateCcw, GripVertical, X } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  type WidgetConfig,
  type WidgetType,
  WIDGET_SIZE_CLASS,
  WIDGET_CATALOGUE,
  DEFAULT_WIDGET_LAYOUT,
} from './widgetTypes';
import { BankSummaryWidget } from './widgets/BankSummaryWidget';
import { InvoicesOwedWidget } from './widgets/InvoicesOwedWidget';
import { BillsToPayWidget } from './widgets/BillsToPayWidget';
import { QuickActionsWidget } from './widgets/QuickActionsWidget';
import { RecentActivityWidget } from './widgets/RecentActivityWidget';
import { PnlSnapshotWidget } from './widgets/PnlSnapshotWidget';
import { VatSummaryWidget } from './widgets/VatSummaryWidget';

// ---------------------------------------------------------------------------
// Widget renderer
// ---------------------------------------------------------------------------

function renderWidget(type: WidgetType): React.ReactNode {
  switch (type) {
    case 'bank-summary':     return <BankSummaryWidget />;
    case 'invoices-owed':    return <InvoicesOwedWidget />;
    case 'bills-to-pay':     return <BillsToPayWidget />;
    case 'quick-actions':    return <QuickActionsWidget />;
    case 'recent-activity':  return <RecentActivityWidget />;
    case 'pnl-snapshot':     return <PnlSnapshotWidget />;
    case 'vat-summary':      return <VatSummaryWidget />;
    default:
      return (
        <Card>
          <p className="text-sm text-gray-500 dark:text-gray-400 capitalize">
            {type.replace(/-/g, ' ')} widget coming soon.
          </p>
        </Card>
      );
  }
}

// ---------------------------------------------------------------------------
// Add Widget Modal
// ---------------------------------------------------------------------------

interface AddWidgetModalProps {
  onAdd: (type: WidgetType, size: WidgetConfig['size']) => void;
  onClose: () => void;
  existingTypes: WidgetType[];
}

function AddWidgetModal({ onAdd, onClose, existingTypes }: AddWidgetModalProps) {
  const available = WIDGET_CATALOGUE.filter(w => !existingTypes.includes(w.type));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} aria-hidden="true" />
      <div className="relative z-10 w-full max-w-md mx-4 bg-white dark:bg-gray-900 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100">Add Widget</h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-md text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {available.length === 0 ? (
          <p className="text-sm text-gray-500 dark:text-gray-400">All available widgets are already on your dashboard.</p>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {available.map(w => (
              <button
                key={w.type}
                onClick={() => { onAdd(w.type, w.size); onClose(); }}
                className="flex flex-col items-start gap-1 p-3 rounded-lg border border-gray-200 dark:border-gray-700 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/20 transition-colors text-left"
              >
                <span className="text-sm font-medium text-gray-900 dark:text-gray-100">{w.title}</span>
                <span className="text-xs text-gray-500 dark:text-gray-400 capitalize">{w.size} size</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// WidgetGrid
// ---------------------------------------------------------------------------

interface WidgetGridProps {
  widgets: WidgetConfig[];
  editMode: boolean;
  onLayoutChange: (widgets: WidgetConfig[]) => void;
}

export function WidgetGrid({ widgets, editMode, onLayoutChange }: WidgetGridProps) {
  const [showAddModal, setShowAddModal] = useState(false);

  const handleRemove = useCallback((id: string) => {
    onLayoutChange(widgets.filter(w => w.id !== id));
  }, [widgets, onLayoutChange]);

  const handleAdd = useCallback((type: WidgetType, size: WidgetConfig['size']) => {
    const newWidget: WidgetConfig = {
      id: `${type}-${Date.now()}`,
      type,
      title: WIDGET_CATALOGUE.find(w => w.type === type)?.title ?? type,
      size,
    };
    onLayoutChange([...widgets, newWidget]);
  }, [widgets, onLayoutChange]);

  const handleReset = useCallback(() => {
    onLayoutChange(DEFAULT_WIDGET_LAYOUT);
  }, [onLayoutChange]);

  const existingTypes = widgets.map(w => w.type);

  return (
    <div className="space-y-4">
      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {widgets.map(widget => (
          <div
            key={widget.id}
            className={`relative ${WIDGET_SIZE_CLASS[widget.size]}`}
          >
            {/* Drag handle (visual only) */}
            {editMode && (
              <div className="absolute top-2 left-2 z-10 p-1 rounded cursor-grab text-gray-400 dark:text-gray-500">
                <GripVertical className="h-4 w-4" />
              </div>
            )}
            {/* Remove button */}
            {editMode && (
              <button
                onClick={() => handleRemove(widget.id)}
                className="absolute top-2 right-2 z-10 p-1 rounded-full bg-red-100 dark:bg-red-900/30 text-red-500 hover:bg-red-200 dark:hover:bg-red-900/60 transition-colors"
                aria-label={`Remove ${widget.title} widget`}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
            {/* Widget content */}
            <div className={editMode ? 'opacity-80 pointer-events-none select-none' : ''}>
              {renderWidget(widget.type)}
            </div>
          </div>
        ))}

        {/* Add Widget button in edit mode */}
        {editMode && (
          <div className="col-span-1">
            <button
              onClick={() => setShowAddModal(true)}
              className="w-full h-full min-h-[120px] flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/10 transition-colors text-gray-400 dark:text-gray-500 hover:text-teal-600 dark:hover:text-teal-400"
            >
              <Plus className="h-6 w-6" />
              <span className="text-sm font-medium">Add Widget</span>
            </button>
          </div>
        )}
      </div>

      {/* Edit mode controls */}
      {editMode && (
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleReset}
            className="flex items-center gap-1.5"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Reset to Suggested
          </Button>
        </div>
      )}

      {/* Add Widget Modal */}
      {showAddModal && (
        <AddWidgetModal
          onAdd={handleAdd}
          onClose={() => setShowAddModal(false)}
          existingTypes={existingTypes}
        />
      )}
    </div>
  );
}

/**
 * Widget type definitions for the Adaptive Widget Dashboard.
 * // WORKING: Full type definitions, no any.
 */

export type WidgetType =
  | 'bank-summary'
  | 'invoices-owed'
  | 'bills-to-pay'
  | 'cash-position'
  | 'pnl-snapshot'
  | 'tasks-reminders'
  | 'recent-activity'
  | 'ai-insights'
  | 'quick-actions'
  | 'vat-summary'
  | 'kpi-cards'
  | 'setup-guide';

export type WidgetSize = 'sm' | 'md' | 'lg';

export interface WidgetConfig {
  id: string;
  type: WidgetType;
  title: string;
  size: WidgetSize;
}

/** Maps WidgetSize to CSS grid column span class */
export const WIDGET_SIZE_CLASS: Record<WidgetSize, string> = {
  sm: 'col-span-1',
  md: 'col-span-1 md:col-span-2',
  lg: 'col-span-1 md:col-span-2 xl:col-span-3',
};

/** Default adaptive widget layout */
export const DEFAULT_WIDGET_LAYOUT: WidgetConfig[] = [
  { id: 'quick-actions-1', type: 'quick-actions', title: 'Quick Actions', size: 'md' },
  { id: 'bank-summary-1', type: 'bank-summary', title: 'Bank Accounts', size: 'md' },
  { id: 'invoices-owed-1', type: 'invoices-owed', title: 'Invoices Owed', size: 'sm' },
  { id: 'bills-to-pay-1', type: 'bills-to-pay', title: 'Bills to Pay', size: 'sm' },
  { id: 'pnl-snapshot-1', type: 'pnl-snapshot', title: 'P&L Snapshot', size: 'md' },
  { id: 'recent-activity-1', type: 'recent-activity', title: 'Recent Activity', size: 'sm' },
];

/** Catalogue of all available widgets (for the Add Widget modal) */
export const WIDGET_CATALOGUE: Array<Pick<WidgetConfig, 'type' | 'title' | 'size'>> = [
  { type: 'bank-summary', title: 'Bank Accounts', size: 'md' },
  { type: 'invoices-owed', title: 'Invoices Owed', size: 'sm' },
  { type: 'bills-to-pay', title: 'Bills to Pay', size: 'sm' },
  { type: 'pnl-snapshot', title: 'P&L Snapshot', size: 'md' },
  { type: 'quick-actions', title: 'Quick Actions', size: 'md' },
  { type: 'recent-activity', title: 'Recent Activity', size: 'sm' },
  { type: 'vat-summary', title: 'VAT Summary', size: 'sm' },
  { type: 'kpi-cards', title: 'KPI Cards', size: 'lg' },
];

/**
 * BankSummaryWidget — Shows bank account balances from /api/accounting/bank-accounts.
 * // WORKING: Self-contained data fetch, skeleton loading, dark mode.
 */

import { useEffect, useState } from 'react';
import { Landmark, TrendingUp } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface BankAccount {
  id: string;
  account_name: string;
  account_code: string;
  bank_account_number: string | null;
  statement_balance: number;
  gl_balance: number;
  difference: number;
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

export function BankSummaryWidget() {
  const [accounts, setAccounts] = useState<BankAccount[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/bank-accounts');
        const json = (await res.json()) as { data?: BankAccount[] };
        const data = json.data ?? [];
        setAccounts(data);
      } catch (err) {
        log.error('BankSummaryWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load bank accounts');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const totalGL = accounts.reduce((s, a) => s + (a.gl_balance ?? 0), 0);

  return (
    <Card
      header={
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Landmark className="h-4 w-4 text-teal-500" />
            <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">Bank Accounts</span>
          </div>
          {!loading && !error && (
            <span className="text-xs font-medium text-teal-600 dark:text-teal-400">{fmtCurrency(totalGL)}</span>
          )}
        </div>
      }
      noPadding
    >
      {loading ? (
        <div className="p-4 space-y-3">
          <Skeleton variant="text" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
        <p className="p-4 text-sm text-red-500">{error}</p>
      ) : accounts.length === 0 ? (
        <p className="p-4 text-sm text-gray-500 dark:text-gray-400">No bank accounts found.</p>
      ) : (
        <div className="divide-y divide-gray-100 dark:divide-gray-700">
          {accounts.map(account => {
            const lastFour = account.bank_account_number?.slice(-4) ?? '----';
            const diff = account.difference ?? 0;
            const inBalance = Math.abs(diff) < 0.01;
            return (
              <div key={account.id} className="px-4 py-3 flex items-center justify-between gap-2">
                <div className="min-w-0">
                  <p className="text-sm font-medium text-gray-900 dark:text-gray-100 truncate">
                    {account.account_name}
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400">
                    {account.account_code} &bull; &bull;&bull;&bull;&bull; {lastFour}
                  </p>
                </div>
                <div className="text-right flex-shrink-0">
                  <p className="text-sm font-semibold text-gray-900 dark:text-gray-100">
                    {fmtCurrency(account.gl_balance ?? 0)}
                  </p>
                  {!inBalance && (
                    <p className="text-xs text-amber-500 flex items-center justify-end gap-1">
                      <TrendingUp className="h-3 w-3" />
                      {diff > 0 ? '+' : ''}{fmtCurrency(diff)}
                    </p>
                  )}
                  {inBalance && (
                    <p className="text-xs text-green-500">Reconciled</p>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </Card>
  );
}

/**
 * InvoicesOwedWidget — AR summary using /api/accounting/dashboard-stats.
 * // WORKING: Color-coded current vs overdue, skeleton loading.
 */

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { FileText, AlertCircle, CheckCircle2, ArrowRight } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface ARStats {
  arTotal: number;
  arOverdue: number;
  arCurrent: number;
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

export function InvoicesOwedWidget() {
  const [stats, setStats] = useState<ARStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { arTotal: number; arOverdue?: number } };
        const d = json.data ?? { arTotal: 0 };
        setStats({
          arTotal: d.arTotal ?? 0,
          arOverdue: d.arOverdue ?? 0,
          arCurrent: Math.max(0, (d.arTotal ?? 0) - (d.arOverdue ?? 0)),
        });
      } catch (err) {
        log.error('InvoicesOwedWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load AR data');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
          <FileText className="h-4 w-4 text-teal-500" />
          <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">Invoices Owed</span>
        </div>
      }
    >
      {loading ? (
        <div className="space-y-3">
          <Skeleton variant="heading" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
        <p className="text-sm text-red-500">{error}</p>
      ) : stats ? (
        <div className="space-y-4">
          <div>
            <p className="text-2xl font-bold text-gray-900 dark:text-gray-100">
              {fmtCurrency(stats.arTotal)}
            </p>
            <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">Total awaiting payment</p>
          </div>
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-1.5 text-xs text-green-600 dark:text-green-400">
                <CheckCircle2 className="h-3.5 w-3.5" />
                Current
              </div>
              <span className="text-xs font-medium text-gray-900 dark:text-gray-100">
                {fmtCurrency(stats.arCurrent)}
              </span>
            </div>
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-1.5 text-xs text-red-600 dark:text-red-400">
                <AlertCircle className="h-3.5 w-3.5" />
                Overdue
              </div>
              <span className="text-xs font-medium text-red-600 dark:text-red-400">
                {fmtCurrency(stats.arOverdue)}
              </span>
            </div>
          </div>
          <Link
            href="/accounting/customer-invoices"
            className="flex items-center gap-1 text-xs text-teal-600 hover:text-teal-700 dark:text-teal-400"
          >
            View all invoices <ArrowRight className="h-3 w-3" />
          </Link>
        </div>
      ) : null}
    </Card>
  );
}

/**
 * BillsToPayWidget — AP summary using /api/accounting/dashboard-stats.
 * // WORKING: Mirror of InvoicesOwedWidget but for payables.
 */

import { useEffect, useState } from 'react';
import Link from 'next/link';
import { Receipt, AlertCircle, CheckCircle2, ArrowRight } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface APStats {
  apTotal: number;
  apOverdue: number;
  apCurrent: number;
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

export function BillsToPayWidget() {
  const [stats, setStats] = useState<APStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { apTotal: number; apOverdue?: number } };
        const d = json.data ?? { apTotal: 0 };
        setStats({
          apTotal: d.apTotal ?? 0,
          apOverdue: d.apOverdue ?? 0,
          apCurrent: Math.max(0, (d.apTotal ?? 0) - (d.apOverdue ?? 0)),
        });
      } catch (err) {
        log.error('BillsToPayWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load AP data');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
