        </div>
      ) : error ? (
        <p className="p-4 text-sm text-red-500">{error}</p>
      ) : entries.length === 0 ? (
        <p className="p-4 text-sm text-gray-500 dark:text-gray-400">No recent journal entries.</p>
      ) : (
        <div className="divide-y divide-gray-100 dark:divide-gray-700">
