/**
 * RecentActivityWidget — Last 5 journal entries from /api/accounting/dashboard-stats.
 * // WORKING: Uses recentJournals from dashboard-stats, no extra endpoint needed.
 */

import { useEffect, useState } from 'react';
import { Clock, FileSpreadsheet } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { Badge } from '@/components/ui/Badge';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface JournalEntry {
  id: string;
  date: string | Date;
  description: string;
  source: string;
  status: string;
  amount: number;
}

function formatDate(val: string | Date): string {
  const d = typeof val === 'string' ? new Date(val) : val;
  return d.toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' });
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

const STATUS_VARIANT: Record<string, 'success' | 'warning' | 'default'> = {
  posted: 'success',
  draft: 'warning',
};

export function RecentActivityWidget() {
  const [entries, setEntries] = useState<JournalEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { recentJournals?: JournalEntry[] } };
        const d = json.data ?? {};
        setEntries(d.recentJournals ?? []);
      } catch (err) {
        log.error('RecentActivityWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load recent activity');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-teal-500" />
          <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">Recent Activity</span>
        </div>
      }
      noPadding
    >
      {loading ? (
        <div className="p-4 space-y-3">
          {[1, 2, 3].map(i => <Skeleton key={i} variant="table-row" />)}
        </div>
      ) : error ? (
        <p className="p-4 text-sm text-red-500">{error}</p>
      ) : entries.length === 0 ? (
        <p className="p-4 text-sm text-gray-500 dark:text-gray-400">No recent journal entries.</p>
      ) : (
        <div className="divide-y divide-gray-100 dark:divide-gray-700">
          {entries.map(entry => (
            <div key={entry.id} className="px-4 py-3 flex items-start gap-3">
              <div className="mt-0.5 flex-shrink-0 p-1.5 rounded-md bg-gray-100 dark:bg-gray-800">
                <FileSpreadsheet className="h-3.5 w-3.5 text-gray-500 dark:text-gray-400" />
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-xs font-medium text-gray-900 dark:text-gray-100 truncate">
                  {entry.description || entry.source || 'Journal Entry'}
                </p>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-xs text-gray-500 dark:text-gray-400">{formatDate(entry.date)}</span>
                  <Badge variant={STATUS_VARIANT[entry.status] ?? 'default'} size="sm">
                    {entry.status}
                  </Badge>
                </div>
              </div>
              <span className="text-xs font-medium text-gray-700 dark:text-gray-300 flex-shrink-0">
                {fmtCurrency(entry.amount)}
              </span>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

/**
 * PnlSnapshotWidget — Current month P&L summary from /api/accounting/dashboard-stats.
 * // WORKING: Revenue, expenses, net profit with trend indicators.
 */

import { useEffect, useState } from 'react';
import { TrendingUp, TrendingDown, BarChart3 } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface PnlData {
  monthRevenue: number;
  monthExpenses: number;
  netProfit: number;
}

function fmtCurrency(n: number): string {
  if (Math.abs(n) >= 1_000_000) return 'R\u00a0' + (n / 1_000_000).toFixed(1) + 'M';
  if (Math.abs(n) >= 1_000) return 'R\u00a0' + (n / 1_000).toFixed(1) + 'K';
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

function currentMonthLabel(): string {
  return new Date().toLocaleString('en-ZA', { month: 'long', year: 'numeric' });
}

export function PnlSnapshotWidget() {
  const [data, setData] = useState<PnlData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { monthRevenue: number; monthExpenses: number } };
        const d = json.data ?? { monthRevenue: 0, monthExpenses: 0 };
        const monthRevenue = d.monthRevenue ?? 0;
        const monthExpenses = d.monthExpenses ?? 0;
        setData({ monthRevenue, monthExpenses, netProfit: monthRevenue - monthExpenses });
      } catch (err) {
        log.error('PnlSnapshotWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load P&L data');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const isProfit = (data?.netProfit ?? 0) >= 0;

  return (
    <Card
      header={
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <BarChart3 className="h-4 w-4 text-teal-500" />
            <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">P&amp;L Snapshot</span>
          </div>
          <span className="text-xs text-gray-500 dark:text-gray-400">{currentMonthLabel()}</span>
        </div>
      }
    >
      {loading ? (
        <div className="space-y-3">
          <Skeleton variant="heading" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
        <p className="text-sm text-red-500">{error}</p>
      ) : data ? (
        <div className="space-y-4">
          {/* Net profit headline */}
          <div className="flex items-end justify-between">
            <div>
              <p className="text-xs text-gray-500 dark:text-gray-400">Net Profit</p>
              <p className={`text-2xl font-bold ${isProfit ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                {fmtCurrency(data.netProfit)}
              </p>
            </div>
            <div className={`p-2 rounded-full ${isProfit ? 'bg-green-50 dark:bg-green-900/20' : 'bg-red-50 dark:bg-red-900/20'}`}>
              {isProfit
                ? <TrendingUp className="h-5 w-5 text-green-600 dark:text-green-400" />
                : <TrendingDown className="h-5 w-5 text-red-600 dark:text-red-400" />
              }
            </div>
          </div>
          {/* Revenue vs Expenses breakdown */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Revenue</span>
              <span className="text-xs font-semibold text-green-600 dark:text-green-400">
                {fmtCurrency(data.monthRevenue)}
              </span>
            </div>
            {/* Progress bar */}
            <div className="h-1.5 rounded-full bg-gray-100 dark:bg-gray-700 overflow-hidden">
              <div
                className="h-full rounded-full bg-green-500"
                style={{ width: '100%' }}
              />
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Expenses</span>
              <span className="text-xs font-semibold text-orange-600 dark:text-orange-400">
                {fmtCurrency(data.monthExpenses)}
              </span>
            </div>
            {data.monthRevenue > 0 && (
              <div className="h-1.5 rounded-full bg-gray-100 dark:bg-gray-700 overflow-hidden">
                <div
                  className="h-full rounded-full bg-orange-400"
                  style={{ width: `${Math.min(100, (data.monthExpenses / data.monthRevenue) * 100).toFixed(1)}%` }}
                />
              </div>
            )}
          </div>
          {/* Margin */}
          {data.monthRevenue > 0 && (
            <p className="text-xs text-gray-500 dark:text-gray-400">
              Margin:{' '}
              <span className={`font-medium ${isProfit ? 'text-green-600' : 'text-red-600'}`}>
                {((data.netProfit / data.monthRevenue) * 100).toFixed(1)}%
              </span>
            </p>
          )}
        </div>
      ) : null}
    </Card>
  );
}

/**
 * VatSummaryWidget — Current VAT period status.
 * Uses /api/accounting/reports-vat-return for the current month period.
 * // WORKING: Shows output VAT, input VAT, net payable.
 */

import { useEffect, useState } from 'react';
import { Percent, Calendar } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface VatData {
  outputVat: number;
  inputVat: number;
  netVat: number;
  periodStart: string;
  periodEnd: string;
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

function fmtDate(s: string): string {
  return new Date(s).toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' });
}

function currentPeriod(): { start: string; end: string } {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth() + 1;
  const start = `${y}-${String(m).padStart(2, '0')}-01`;
  const lastDay = new Date(y, m, 0).getDate();
  const end = `${y}-${String(m).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
  return { start, end };
}

export function VatSummaryWidget() {
  const [data, setData] = useState<VatData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      const { start, end } = currentPeriod();
      try {
        const res = await apiFetch(
          `/api/accounting/reports-vat-return?period_start=${start}&period_end=${end}`
        );
        const json = (await res.json()) as { data?: {
          output_vat?: number; outputVat?: number;
          input_vat?: number; inputVat?: number;
          net_vat?: number; netVat?: number;
        } };
        const d = json.data ?? {};
        setData({
          outputVat: d.output_vat ?? d.outputVat ?? 0,
          inputVat: d.input_vat ?? d.inputVat ?? 0,
          netVat: d.net_vat ?? d.netVat ?? 0,
          periodStart: start,
          periodEnd: end,
        });
      } catch (err) {
        log.error('VatSummaryWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load VAT data');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const isPayable = (data?.netVat ?? 0) > 0;

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
          <Percent className="h-4 w-4 text-teal-500" />
          <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">VAT Summary</span>
        </div>
      }
    >
      {loading ? (
        <div className="space-y-3">
          <Skeleton variant="text" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
        <p className="text-sm text-red-500">{error}</p>
      ) : data ? (
        <div className="space-y-4">
          {/* Period */}
          <div className="flex items-center gap-1.5 text-xs text-gray-500 dark:text-gray-400">
            <Calendar className="h-3.5 w-3.5" />
            {fmtDate(data.periodStart)} &ndash; {fmtDate(data.periodEnd)}
          </div>
          {/* Breakdown */}
          <div className="space-y-2">
            <div className="flex justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Output VAT (collected)</span>
              <span className="text-xs font-medium text-gray-900 dark:text-gray-100">
                {fmtCurrency(data.outputVat)}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Input VAT (claimable)</span>
              <span className="text-xs font-medium text-green-600 dark:text-green-400">
                {fmtCurrency(data.inputVat)}
              </span>
            </div>
            <div className="h-px bg-gray-200 dark:bg-gray-700" />
            <div className="flex justify-between">
              <span className="text-xs font-semibold text-gray-900 dark:text-gray-100">
                {isPayable ? 'Net VAT Payable' : 'VAT Refund Due'}
              </span>
              <span className={`text-xs font-bold ${isPayable ? 'text-red-600 dark:text-red-400' : 'text-green-600 dark:text-green-400'}`}>
                {fmtCurrency(Math.abs(data.netVat))}
              </span>
            </div>
          </div>
        </div>
      ) : null}
    </Card>
  );
}

/**
 * WidgetGrid — Responsive 3-column grid that renders configured widgets.
 * // WORKING: Edit mode, add/remove widgets, reset to default layout.
 */

import { useState, useCallback } from 'react';
import { Plus, RotateCcw, GripVertical, X } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import {
  type WidgetConfig,
  type WidgetType,
  WIDGET_SIZE_CLASS,
  WIDGET_CATALOGUE,
  DEFAULT_WIDGET_LAYOUT,
} from './widgetTypes';
import { BankSummaryWidget } from './widgets/BankSummaryWidget';
import { InvoicesOwedWidget } from './widgets/InvoicesOwedWidget';
import { BillsToPayWidget } from './widgets/BillsToPayWidget';
import { QuickActionsWidget } from './widgets/QuickActionsWidget';
import { RecentActivityWidget } from './widgets/RecentActivityWidget';
import { PnlSnapshotWidget } from './widgets/PnlSnapshotWidget';
import { VatSummaryWidget } from './widgets/VatSummaryWidget';

// ---------------------------------------------------------------------------
// Widget renderer
// ---------------------------------------------------------------------------

function renderWidget(type: WidgetType): React.ReactNode {
  switch (type) {
    case 'bank-summary':     return <BankSummaryWidget />;
    case 'invoices-owed':    return <InvoicesOwedWidget />;
    case 'bills-to-pay':     return <BillsToPayWidget />;
    case 'quick-actions':    return <QuickActionsWidget />;
    case 'recent-activity':  return <RecentActivityWidget />;
    case 'pnl-snapshot':     return <PnlSnapshotWidget />;
    case 'vat-summary':      return <VatSummaryWidget />;
    default:
      return (
        <Card>
          <p className="text-sm text-gray-500 dark:text-gray-400 capitalize">
            {type.replace(/-/g, ' ')} widget coming soon.
          </p>
        </Card>
      );
  }
}

// ---------------------------------------------------------------------------
// Add Widget Modal
// ---------------------------------------------------------------------------

interface AddWidgetModalProps {
  onAdd: (type: WidgetType, size: WidgetConfig['size']) => void;
  onClose: () => void;
  existingTypes: WidgetType[];
}

function AddWidgetModal({ onAdd, onClose, existingTypes }: AddWidgetModalProps) {
  const available = WIDGET_CATALOGUE.filter(w => !existingTypes.includes(w.type));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} aria-hidden="true" />
      <div className="relative z-10 w-full max-w-md mx-4 bg-white dark:bg-gray-900 rounded-xl shadow-xl border border-gray-200 dark:border-gray-700 p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100">Add Widget</h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-md text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {available.length === 0 ? (
          <p className="text-sm text-gray-500 dark:text-gray-400">All available widgets are already on your dashboard.</p>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {available.map(w => (
              <button
                key={w.type}
                onClick={() => { onAdd(w.type, w.size); onClose(); }}
                className="flex flex-col items-start gap-1 p-3 rounded-lg border border-gray-200 dark:border-gray-700 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/20 transition-colors text-left"
              >
                <span className="text-sm font-medium text-gray-900 dark:text-gray-100">{w.title}</span>
                <span className="text-xs text-gray-500 dark:text-gray-400 capitalize">{w.size} size</span>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// WidgetGrid
// ---------------------------------------------------------------------------

interface WidgetGridProps {
  widgets: WidgetConfig[];
  editMode: boolean;
  onLayoutChange: (widgets: WidgetConfig[]) => void;
}

export function WidgetGrid({ widgets, editMode, onLayoutChange }: WidgetGridProps) {
  const [showAddModal, setShowAddModal] = useState(false);

  const handleRemove = useCallback((id: string) => {
    onLayoutChange(widgets.filter(w => w.id !== id));
  }, [widgets, onLayoutChange]);

  const handleAdd = useCallback((type: WidgetType, size: WidgetConfig['size']) => {
    const newWidget: WidgetConfig = {
      id: `${type}-${Date.now()}`,
      type,
      title: WIDGET_CATALOGUE.find(w => w.type === type)?.title ?? type,
      size,
    };
    onLayoutChange([...widgets, newWidget]);
  }, [widgets, onLayoutChange]);

  const handleReset = useCallback(() => {
    onLayoutChange(DEFAULT_WIDGET_LAYOUT);
  }, [onLayoutChange]);

  const existingTypes = widgets.map(w => w.type);

  return (
    <div className="space-y-4">
      {/* Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">
        {widgets.map(widget => (
          <div
            key={widget.id}
            className={`relative ${WIDGET_SIZE_CLASS[widget.size]}`}
          >
            {/* Drag handle (visual only) */}
            {editMode && (
              <div className="absolute top-2 left-2 z-10 p-1 rounded cursor-grab text-gray-400 dark:text-gray-500">
                <GripVertical className="h-4 w-4" />
              </div>
            )}
            {/* Remove button */}
            {editMode && (
              <button
                onClick={() => handleRemove(widget.id)}
                className="absolute top-2 right-2 z-10 p-1 rounded-full bg-red-100 dark:bg-red-900/30 text-red-500 hover:bg-red-200 dark:hover:bg-red-900/60 transition-colors"
                aria-label={`Remove ${widget.title} widget`}
              >
                <X className="h-3.5 w-3.5" />
              </button>
            )}
            {/* Widget content */}
            <div className={editMode ? 'opacity-80 pointer-events-none select-none' : ''}>
              {renderWidget(widget.type)}
            </div>
          </div>
        ))}

        {/* Add Widget button in edit mode */}
        {editMode && (
          <div className="col-span-1">
            <button
              onClick={() => setShowAddModal(true)}
              className="w-full h-full min-h-[120px] flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed border-gray-300 dark:border-gray-600 hover:border-teal-400 dark:hover:border-teal-500 hover:bg-teal-50 dark:hover:bg-teal-900/10 transition-colors text-gray-400 dark:text-gray-500 hover:text-teal-600 dark:hover:text-teal-400"
            >
              <Plus className="h-6 w-6" />
              <span className="text-sm font-medium">Add Widget</span>
            </button>
          </div>
        )}
      </div>

      {/* Edit mode controls */}
      {editMode && (
        <div className="flex items-center gap-3">
          <Button
            variant="ghost"
            size="sm"
            onClick={handleReset}
            className="flex items-center gap-1.5"
          >
            <RotateCcw className="h-3.5 w-3.5" />
            Reset to Suggested
          </Button>
        </div>
      )}

      {/* Add Widget Modal */}
      {showAddModal && (
        <AddWidgetModal
          onAdd={handleAdd}
          onClose={() => setShowAddModal(false)}
          existingTypes={existingTypes}
        />
      )}
    </div>
  );
}

