/**
 * Admin — Audit Trail
 * Date range, action type, target type filters. Paginated table.
 */

import { useState, useEffect, useCallback } from 'react';
import { AdminLayout } from '@/components/admin/AdminLayout';
import { apiFetch } from '@/lib/apiFetch';
import { AlertCircle, Loader2, ChevronLeft, ChevronRight, ScrollText } from 'lucide-react';

interface AuditEntry {
  id: string;
  createdAt: string;
  adminName: string;
  action: string;
  targetType: string;
  targetId: string;
  details: string;
  ipAddress: string | null;
}

interface PagedResponse {
  items: AuditEntry[];
  total: number;
  page: number;
  limit: number;
}

function getDefaultDates() {
  const now   = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  return {
    from: start.toISOString().split('T')[0] as string,
    to:   now.toISOString().split('T')[0] as string,
  };
}

const LIMIT = 50;

export default function AdminAuditPage() {
  const defaults = getDefaultDates();

  const [rows, setRows]           = useState<AuditEntry[]>([]);
  const [total, setTotal]         = useState(0);
  const [page, setPage]           = useState(1);
  const [loading, setLoading]     = useState(true);
  const [error, setError]         = useState('');
  const [dateFrom, setDateFrom]   = useState(defaults.from);
  const [dateTo, setDateTo]       = useState(defaults.to);
  const [actionType, setActionType] = useState('');
  const [targetType, setTargetType] = useState('');

  const load = useCallback(async (pg: number) => {
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({ page: String(pg), limit: String(LIMIT) });
      if (dateFrom)   params.set('from', dateFrom);
      if (dateTo)     params.set('to', dateTo);
      if (actionType) params.set('action', actionType);
      if (targetType) params.set('targetType', targetType);
      const res  = await apiFetch(`/api/admin/audit?${params}`);
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed to load audit trail');
      const d = json.data as PagedResponse;
      setRows(d.items);
      setTotal(d.total);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed');
    } finally {
      setLoading(false);
    }
  }, [dateFrom, dateTo, actionType, targetType]);

  useEffect(() => {
    setPage(1);
    void load(1);
  }, [load]);

  useEffect(() => {
    void load(page);
  }, [page]); // eslint-disable-line react-hooks/exhaustive-deps

  function fmtDateTime(d: string) {
    return new Date(d).toLocaleString('en-ZA', {
      day: '2-digit', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit',
    });
  }

  const totalPages = Math.max(1, Math.ceil(total / LIMIT));

  return (
    <AdminLayout title="Audit Trail">
      {/* Filters */}
      <div className="flex gap-3 flex-wrap mb-5 items-end">
        <div>
          <label className="text-xs text-gray-500 dark:text-gray-400 block mb-1">From</label>
          <input
            type="date"
            value={dateFrom}
            onChange={e => setDateFrom(e.target.value)}
            className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
          />
        </div>
        <div>
          <label className="text-xs text-gray-500 dark:text-gray-400 block mb-1">To</label>
          <input
            type="date"
            value={dateTo}
            onChange={e => setDateTo(e.target.value)}
            className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
          />
        </div>
        <div>
          <label className="text-xs text-gray-500 dark:text-gray-400 block mb-1">Action Type</label>
          <select
            value={actionType}
            onChange={e => setActionType(e.target.value)}
            className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
          >
            <option value="">All actions</option>
            <option value="create">Create</option>
            <option value="update">Update</option>
            <option value="delete">Delete</option>
            <option value="suspend">Suspend</option>
            <option value="activate">Activate</option>
            <option value="login">Login</option>
            <option value="logout">Logout</option>
            <option value="reset_password">Reset Password</option>
          </select>
        </div>
        <div>
          <label className="text-xs text-gray-500 dark:text-gray-400 block mb-1">Target Type</label>
          <select
            value={targetType}
            onChange={e => setTargetType(e.target.value)}
            className="px-3 py-2 text-sm rounded-lg border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-teal-500"
          >
            <option value="">All targets</option>
            <option value="company">Company</option>
            <option value="user">User</option>
            <option value="subscription">Subscription</option>
            <option value="settings">Settings</option>
          </select>
        </div>
        <span className="ml-auto text-sm text-gray-500 dark:text-gray-400 self-center">{total} entries</span>
      </div>

      {error && (
        <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-4">
          <AlertCircle className="w-4 h-4 flex-shrink-0" /> {error}
        </div>
      )}

      {/* Table */}
      <div className="bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-700 rounded-xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left text-xs text-gray-500 dark:text-gray-400 border-b border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <th className="px-4 py-3 font-medium whitespace-nowrap">Date / Time</th>
                <th className="px-4 py-3 font-medium">Admin</th>
                <th className="px-4 py-3 font-medium">Action</th>
                <th className="px-4 py-3 font-medium">Target</th>
                <th className="px-4 py-3 font-medium">Details</th>
                <th className="px-4 py-3 font-medium">IP</th>
              </tr>
            </thead>
            <tbody>
              {loading && rows.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center">
                    <Loader2 className="w-5 h-5 animate-spin text-teal-500 mx-auto" />
                  </td>
                </tr>
              )}
              {!loading && rows.length === 0 && (
                <tr>
                  <td colSpan={6} className="px-4 py-12 text-center">
                    <div className="flex flex-col items-center gap-2 text-gray-400">
                      <ScrollText className="w-8 h-8 opacity-30" />
                      <span className="text-sm">No audit entries for selected filters</span>
                    </div>
                  </td>
                </tr>
              )}
              {rows.map(row => (
                <tr key={row.id} className="border-b border-gray-100 dark:border-gray-800 last:border-0 hover:bg-gray-50 dark:hover:bg-gray-800/40">
                  <td className="px-4 py-3 text-gray-500 dark:text-gray-400 whitespace-nowrap font-mono text-xs">
                    {fmtDateTime(row.createdAt)}
                  </td>
                  <td className="px-4 py-3 text-gray-700 dark:text-gray-200 font-medium">{row.adminName}</td>
                  <td className="px-4 py-3">
                    <span className="px-2 py-0.5 rounded text-xs font-medium bg-gray-100 dark:bg-gray-800 text-gray-600 dark:text-gray-300 capitalize">
                      {row.action.replaceAll('_', ' ')}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 capitalize">
                    <span className="text-xs">{row.targetType}</span>
                    {row.targetId && (
                      <span className="block font-mono text-xs text-gray-400">{row.targetId.slice(0, 8)}…</span>
                    )}
                  </td>
                  <td className="px-4 py-3 text-gray-600 dark:text-gray-300 max-w-xs truncate">{row.details}</td>
                  <td className="px-4 py-3 text-gray-400 font-mono text-xs whitespace-nowrap">{row.ipAddress ?? '—'}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Pagination */}
        <div className="flex items-center justify-between px-4 py-3 border-t border-gray-200 dark:border-gray-700 text-sm">
          <span className="text-gray-500 dark:text-gray-400">Page {page} of {totalPages}</span>
          <div className="flex gap-2">
            <button
              disabled={page <= 1}
              onClick={() => setPage(p => p - 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <button
              disabled={page >= totalPages}
              onClick={() => setPage(p => p + 1)}
              className="p-1.5 rounded border border-gray-200 dark:border-gray-700 text-gray-500 hover:text-gray-900 dark:hover:text-white disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </AdminLayout>
  );
}

/**
 * RecentActivityWidget — Last 5 journal entries from /api/accounting/dashboard-stats.
 * // WORKING: Uses recentJournals from dashboard-stats, no extra endpoint needed.
 */

import { useEffect, useState } from 'react';
import { Clock, FileSpreadsheet } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { Badge } from '@/components/ui/Badge';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface JournalEntry {
  id: string;
  date: string | Date;
  description: string;
  source: string;
  status: string;
  amount: number;
}

function formatDate(val: string | Date): string {
  const d = typeof val === 'string' ? new Date(val) : val;
  return d.toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' });
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

const STATUS_VARIANT: Record<string, 'success' | 'warning' | 'default'> = {
  posted: 'success',
  draft: 'warning',
};

export function RecentActivityWidget() {
  const [entries, setEntries] = useState<JournalEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { recentJournals?: JournalEntry[] } };
        const d = json.data ?? {};
        setEntries(d.recentJournals ?? []);
      } catch (err) {
        log.error('RecentActivityWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load recent activity');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-teal-500" />
          <span className="text-sm font-semibold text-[var(--ff-text-primary)]">Recent Activity</span>
        </div>
      }
      noPadding
    >
      {loading ? (
        <div className="p-4 space-y-3">
          {[1, 2, 3].map(i => <Skeleton key={i} variant="table-row" />)}
        </div>
      ) : error ? (
        <p className="p-4 text-sm text-red-500">{error}</p>
      ) : entries.length === 0 ? (
        <p className="p-4 text-sm text-[var(--ff-text-secondary)]">No recent journal entries.</p>
      ) : (
        <div className="divide-y divide-gray-100 dark:divide-gray-700">
          {entries.map(entry => (
            <div key={entry.id} className="px-4 py-3 flex items-start gap-3">
              <div className="mt-0.5 flex-shrink-0 p-1.5 rounded-md bg-gray-100 dark:bg-gray-800">
                <FileSpreadsheet className="h-3.5 w-3.5 text-gray-500 dark:text-gray-400" />
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-xs font-medium text-gray-900 dark:text-gray-100 truncate">
                  {entry.description || entry.source || 'Journal Entry'}
                </p>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-xs text-gray-500 dark:text-gray-400">{formatDate(entry.date)}</span>
                  <Badge variant={STATUS_VARIANT[entry.status] ?? 'default'} size="sm">
                    {entry.status}
                  </Badge>
                </div>
              </div>
              <span className="text-xs font-medium text-gray-700 dark:text-gray-300 flex-shrink-0">
                {fmtCurrency(entry.amount)}
              </span>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

/**
 * PnlSnapshotWidget — Current month P&L summary from /api/accounting/dashboard-stats.
 * // WORKING: Revenue, expenses, net profit with trend indicators.
 */

import { useEffect, useState } from 'react';
import { TrendingUp, TrendingDown, BarChart3 } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface PnlData {
  monthRevenue: number;
  monthExpenses: number;
  netProfit: number;
}

function fmtCurrency(n: number): string {
  if (Math.abs(n) >= 1_000_000) return 'R\u00a0' + (n / 1_000_000).toFixed(1) + 'M';
  if (Math.abs(n) >= 1_000) return 'R\u00a0' + (n / 1_000).toFixed(1) + 'K';
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

function currentMonthLabel(): string {
  return new Date().toLocaleString('en-ZA', { month: 'long', year: 'numeric' });
}

export function PnlSnapshotWidget() {
  const [data, setData] = useState<PnlData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { monthRevenue: number; monthExpenses: number } };
        const d = json.data ?? { monthRevenue: 0, monthExpenses: 0 };
        const monthRevenue = d.monthRevenue ?? 0;
        const monthExpenses = d.monthExpenses ?? 0;
        setData({ monthRevenue, monthExpenses, netProfit: monthRevenue - monthExpenses });
      } catch (err) {
        log.error('PnlSnapshotWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load P&L data');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  const isProfit = (data?.netProfit ?? 0) >= 0;

  return (
    <Card
      header={
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <BarChart3 className="h-4 w-4 text-teal-500" />
            <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">P&amp;L Snapshot</span>
          </div>
          <span className="text-xs text-gray-500 dark:text-gray-400">{currentMonthLabel()}</span>
        </div>
      }
    >
      {loading ? (
        <div className="space-y-3">
          <Skeleton variant="heading" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
          <Skeleton variant="text" />
        </div>
      ) : error ? (
        <p className="text-sm text-red-500">{error}</p>
      ) : data ? (
        <div className="space-y-4">
          {/* Net profit headline */}
          <div className="flex items-end justify-between">
            <div>
              <p className="text-xs text-gray-500 dark:text-gray-400">Net Profit</p>
              <p className={`text-2xl font-bold ${isProfit ? 'text-green-600 dark:text-green-400' : 'text-red-600 dark:text-red-400'}`}>
                {fmtCurrency(data.netProfit)}
              </p>
            </div>
            <div className={`p-2 rounded-full ${isProfit ? 'bg-green-50 dark:bg-green-900/20' : 'bg-red-50 dark:bg-red-900/20'}`}>
              {isProfit
                ? <TrendingUp className="h-5 w-5 text-green-600 dark:text-green-400" />
                : <TrendingDown className="h-5 w-5 text-red-600 dark:text-red-400" />
              }
            </div>
          </div>
          {/* Revenue vs Expenses breakdown */}
          <div className="space-y-2">
            <div className="flex items-center justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Revenue</span>
              <span className="text-xs font-semibold text-green-600 dark:text-green-400">
                {fmtCurrency(data.monthRevenue)}
              </span>
            </div>
            {/* Progress bar */}
            <div className="h-1.5 rounded-full bg-gray-100 dark:bg-gray-700 overflow-hidden">
              <div
                className="h-full rounded-full bg-green-500"
                style={{ width: '100%' }}
              />
            </div>
            <div className="flex items-center justify-between">
              <span className="text-xs text-gray-500 dark:text-gray-400">Expenses</span>
              <span className="text-xs font-semibold text-orange-600 dark:text-orange-400">
                {fmtCurrency(data.monthExpenses)}
              </span>
            </div>
            {data.monthRevenue > 0 && (
              <div className="h-1.5 rounded-full bg-gray-100 dark:bg-gray-700 overflow-hidden">
                <div
                  className="h-full rounded-full bg-orange-400"
                  style={{ width: `${Math.min(100, (data.monthExpenses / data.monthRevenue) * 100).toFixed(1)}%` }}
                />
              </div>
            )}
          </div>
          {/* Margin */}
          {data.monthRevenue > 0 && (
            <p className="text-xs text-gray-500 dark:text-gray-400">
              Margin:{' '}
              <span className={`font-medium ${isProfit ? 'text-green-600' : 'text-red-600'}`}>
                {((data.netProfit / data.monthRevenue) * 100).toFixed(1)}%
              </span>
            </p>
          )}
        </div>
      ) : null}
    </Card>
  );
}

