import { VatSummaryWidget } from './widgets/VatSummaryWidget';

// ---------------------------------------------------------------------------
// Widget renderer
// ---------------------------------------------------------------------------

function renderWidget(type: WidgetType): React.ReactNode {
  switch (type) {
    case 'bank-summary':     return <BankSummaryWidget />;
    case 'invoices-owed':    return <InvoicesOwedWidget />;
    case 'bills-to-pay':     return <BillsToPayWidget />;
    case 'quick-actions':    return <QuickActionsWidget />;
    case 'recent-activity':  return <RecentActivityWidget />;
    case 'pnl-snapshot':     return <PnlSnapshotWidget />;
    case 'vat-summary':      return <VatSummaryWidget />;
    default:
      return (
        <Card>
          <p className="text-sm text-[var(--ff-text-secondary)] capitalize">
            {type.replace(/-/g, ' ')} widget coming soon.
          </p>
        </Card>
      );
  }
}

// ---------------------------------------------------------------------------
// Add Widget Modal
// ---------------------------------------------------------------------------

interface AddWidgetModalProps {
  onAdd: (type: WidgetType, size: WidgetConfig['size']) => void;
  onClose: () => void;
  existingTypes: WidgetType[];
}

function AddWidgetModal({ onAdd, onClose, existingTypes }: AddWidgetModalProps) {
  const available = WIDGET_CATALOGUE.filter(w => !existingTypes.includes(w.type));

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/50" onClick={onClose} aria-hidden="true" />
      <div className="relative z-10 w-full max-w-md mx-4 bg-[var(--ff-bg-secondary)] rounded-xl shadow-xl border border-[var(--ff-border-light)] p-6">
        <div className="flex items-center justify-between mb-4">
          <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">Add Widget</h2>
          <button
            onClick={onClose}
            className="p-1.5 rounded-md text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-tertiary)] transition-colors"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {available.length === 0 ? (
          <p className="text-sm text-[var(--ff-text-secondary)]">All available widgets are already on your dashboard.</p>
        ) : (
          <div className="grid grid-cols-2 gap-3">
            {available.map(w => (
              <button
                key={w.type}
                onClick={() => { onAdd(w.type, w.size); onClose(); }}
                className="flex flex-col items-start gap-1 p-3 rounded-lg border border-[var(--ff-border-light)] hover:border-teal-500/50 hover:shadow-md transition-all text-left"
              >
                <span className="text-sm font-medium text-[var(--ff-text-primary)]">{w.title}</span>
                <span className="text-xs text-[var(--ff-text-secondary)] capitalize">{w.size} size</span>
