      warn_item_qty_below_zero = COALESCE(${v('warnItemQtyBelowZero') ?? null}, warn_item_qty_below_zero),
      block_item_qty_below_zero = COALESCE(${v('blockItemQtyBelowZero') ?? null}, block_item_qty_below_zero),
      warn_item_cost_zero = COALESCE(${v('warnItemCostZero') ?? null}, warn_item_cost_zero),
      warn_item_selling_below_cost = COALESCE(${v('warnItemSellingBelowCost') ?? null}, warn_item_selling_below_cost),
      display_inactive_items_processing = COALESCE(${v('displayInactiveItemsProcessing') ?? null}, display_inactive_items_processing),
      display_inactive_items_reports = COALESCE(${v('displayInactiveItemsReports') ?? null}, display_inactive_items_reports),
      sales_orders_reserve_qty = COALESCE(${v('salesOrdersReserveQty') ?? null}, sales_orders_reserve_qty),
      display_inactive_bundles = COALESCE(${v('displayInactiveBundles') ?? null}, display_inactive_bundles),
      ageing_monthly = COALESCE(${v('ageingMonthly') ?? null}, ageing_monthly),
      ageing_based_on = COALESCE(${v('ageingBasedOn') ?? null}, ageing_based_on),
      updated_at = NOW()
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Company ${id} not found`);
  return mapCompany(rows[0]);
}

// ── User-Company ─────────────────────────────────────────────────────────────

export async function getUserCompanies(userId: string): Promise<CompanyUser[]> {
  const rows = (await sql`
    SELECT cu.company_id, c.name AS company_name, cu.role, cu.is_default
    FROM company_users cu
    JOIN companies c ON c.id = cu.company_id
    WHERE cu.user_id = ${userId} AND c.is_active = true
    ORDER BY cu.is_default DESC, c.name ASC
  `) as Row[];
  return rows.map((r: Row) => ({
    companyId: r.company_id,
    companyName: r.company_name,
    role: r.role,
    isDefault: r.is_default,
  }));
}

export async function setDefaultCompany(userId: string, companyId: string): Promise<void> {
  await sql`UPDATE company_users SET is_default = false WHERE user_id = ${userId}`;
  await sql`UPDATE company_users SET is_default = true WHERE user_id = ${userId} AND company_id = ${companyId}::UUID`;
}

export async function addUserToCompany(companyId: string, userId: string, role = 'user'): Promise<void> {
  await sql`
    INSERT INTO company_users (company_id, user_id, role)
    VALUES (${companyId}::UUID, ${userId}, ${role})
    ON CONFLICT (company_id, user_id) DO UPDATE SET role = ${role}
  `;
}

export async function removeUserFromCompany(companyId: string, userId: string): Promise<void> {
  await sql`DELETE FROM company_users WHERE company_id = ${companyId}::UUID AND user_id = ${userId}`;
}

// ── Mapper ───────────────────────────────────────────────────────────────────

function mapCompany(r: Row): Company {
  return {
    id: r.id,
    name: r.name,
    tradingName: r.trading_name,
    registrationNumber: r.registration_number,
    vatNumber: r.vat_number,
    taxNumber: r.tax_number,
    addressLine1: r.address_line1,
    addressLine2: r.address_line2,
    city: r.city,
    province: r.province,
    postalCode: r.postal_code,
    country: r.country,
    phone: r.phone,
    email: r.email,
    website: r.website,
    logoUrl: r.logo_url,
    logoData: r.logo_data || null,
    bankName: r.bank_name,
    bankAccountNumber: r.bank_account_number,
    bankBranchCode: r.bank_branch_code,
    bankAccountType: r.bank_account_type,
    financialYearStart: r.financial_year_start,
    vatPeriod: r.vat_period,
    vatPeriodAlignment: r.vat_period_alignment ?? 'odd',
    defaultCurrency: r.default_currency,
    isActive: r.is_active,
    createdAt: r.created_at,
    // Lockdown
    lockdownEnabled: r.lockdown_enabled ?? false,
    lockdownDate: r.lockdown_date ? new Date(r.lockdown_date).toISOString().split('T')[0]! : null,
    // VAT system
    vatSystemType: r.vat_system_type ?? 'invoice',
    // Entity & statutory
    entityType: r.entity_type ?? 'company',
    registeredName: r.registered_name,
    taxOffice: r.tax_office,
    contactName: r.contact_name,
    fax: r.fax,
    mobile: r.mobile,
    // Physical address
    physicalAddressLine1: r.physical_address_line1,
    physicalAddressLine2: r.physical_address_line2,
    physicalCity: r.physical_city,
    physicalProvince: r.physical_province,
    physicalPostalCode: r.physical_postal_code,
    // Tax practitioner
    taxPractitionerRegNumber: r.tax_practitioner_reg_number,
    taxPractitionerName: r.tax_practitioner_name,
    // SARS contact
    sarsContactFirstName: r.sars_contact_first_name,
    sarsContactLastName: r.sars_contact_last_name,
    sarsContactCapacity: r.sars_contact_capacity,
    sarsContactNumber: r.sars_contact_number,
    sarsContactTelephone: r.sars_contact_telephone,
    // Branding
    logoPosition: r.logo_position ?? 'top-left',
    logoOnEmails: r.logo_on_emails ?? true,
    logoOnPortal: r.logo_on_portal ?? true,
    // Regional
    roundingType: r.rounding_type ?? 'none',
    roundToNearest: parseFloat(r.round_to_nearest ?? '0'),
    qtyDecimalPlaces: r.qty_decimal_places ?? 2,
    valueDecimalPlaces: r.value_decimal_places ?? 2,
    hoursDecimalPlaces: r.hours_decimal_places ?? 2,
    costPriceDecimalPlaces: r.cost_price_decimal_places ?? 2,
    sellingPriceDecimalPlaces: r.selling_price_decimal_places ?? 2,
    currencySymbol: r.currency_symbol ?? 'R',
    dateFormat: r.date_format ?? 'dd/mm/yyyy',
    // Email toggles
    emailUseForCommunication: r.email_use_for_communication ?? true,
    emailAlwaysCc: r.email_always_cc ?? false,
    emailUseServiceFrom: r.email_use_service_from ?? false,
    // Customer & Supplier
    warnDuplicateCustomerRef: r.warn_duplicate_customer_ref ?? true,
    warnDuplicateSupplierInv: r.warn_duplicate_supplier_inv ?? true,
    displayInactiveCustomersProcessing: r.display_inactive_customers_processing ?? false,
    displayInactiveSuppliersProcessing: r.display_inactive_suppliers_processing ?? false,
    displayInactiveCustomersReports: r.display_inactive_customers_reports ?? false,
    displayInactiveSuppliersReports: r.display_inactive_suppliers_reports ?? false,
    useInclusiveProcessing: r.use_inclusive_processing ?? true,
    useAccountDefaultLineType: r.use_account_default_line_type ?? false,
    // Items
    warnItemQtyBelowZero: r.warn_item_qty_below_zero ?? true,
    blockItemQtyBelowZero: r.block_item_qty_below_zero ?? false,
    warnItemCostZero: r.warn_item_cost_zero ?? false,
    warnItemSellingBelowCost: r.warn_item_selling_below_cost ?? false,
    displayInactiveItemsProcessing: r.display_inactive_items_processing ?? false,
    displayInactiveItemsReports: r.display_inactive_items_reports ?? false,
    salesOrdersReserveQty: r.sales_orders_reserve_qty ?? false,
    displayInactiveBundles: r.display_inactive_bundles ?? false,
    // Ageing
    ageingMonthly: r.ageing_monthly ?? true,
    ageingBasedOn: r.ageing_based_on ?? 'invoice_date',
  };
}

// ── Document Numbers ──────────────────────────────────────────────────────────

export interface DocumentNumber {
  id: string;
  companyId: string;
  documentType: string;
  prefix: string;
  nextNumber: number;
  padding: number;
}

const DEFAULT_DOC_NUMBERS: { type: string; prefix: string }[] = [
  { type: 'quotation', prefix: 'QUO' },
  { type: 'sales_order', prefix: 'SO' },
  { type: 'customer_invoice', prefix: 'INV' },
  { type: 'credit_note', prefix: 'CRN' },
  { type: 'customer_receipt', prefix: 'RCP' },
  { type: 'customer_write_off', prefix: 'WRI' },
  { type: 'recurring_invoice', prefix: 'RINV' },
  { type: 'customer_adjustment', prefix: 'CADJ' },
  { type: 'purchase_order', prefix: 'PO' },
  { type: 'supplier_invoice', prefix: 'SIV' },
  { type: 'supplier_return', prefix: 'RTN' },
  { type: 'supplier_payment', prefix: 'PAY' },
  { type: 'supplier_adjustment', prefix: 'SADJ' },
  { type: 'delivery_note', prefix: 'DN' },
];

export async function getDocumentNumbers(companyId: string): Promise<DocumentNumber[]> {
  const rows = (await sql`
    SELECT * FROM company_document_numbers WHERE company_id = ${companyId}::UUID ORDER BY document_type
  `) as Row[];
  return rows.map((r: Row) => ({
    id: r.id, companyId: r.company_id, documentType: r.document_type,
    prefix: r.prefix, nextNumber: r.next_number, padding: r.padding,
  }));
}

export async function ensureDocumentNumbers(companyId: string): Promise<DocumentNumber[]> {
  for (const d of DEFAULT_DOC_NUMBERS) {
    await sql`
      INSERT INTO company_document_numbers (company_id, document_type, prefix, next_number, padding)
      VALUES (${companyId}::UUID, ${d.type}, ${d.prefix}, 1, 7)
      ON CONFLICT (company_id, document_type) DO NOTHING
    `;
  }
  return getDocumentNumbers(companyId);
}

export async function updateDocumentNumber(companyId: string, documentType: string, prefix: string, nextNumber?: number): Promise<void> {
  if (nextNumber !== undefined) {
    await sql`
      UPDATE company_document_numbers SET prefix = ${prefix}, next_number = ${nextNumber}
      WHERE company_id = ${companyId}::UUID AND document_type = ${documentType}
    `;
  } else {
    await sql`
      UPDATE company_document_numbers SET prefix = ${prefix}
      WHERE company_id = ${companyId}::UUID AND document_type = ${documentType}
    `;
  }
}

// ── Company Messages ──────────────────────────────────────────────────────────

export interface CompanyMessage {
  messageType: string;
  message: string;
}

export async function getCompanyMessages(companyId: string): Promise<CompanyMessage[]> {
  const rows = (await sql`
    SELECT message_type, message FROM company_messages WHERE company_id = ${companyId}::UUID ORDER BY message_type
  `) as Row[];
  return rows.map((r: Row) => ({ messageType: r.message_type, message: r.message ?? '' }));
}

export async function upsertCompanyMessage(companyId: string, messageType: string, message: string): Promise<void> {
  await sql`
    INSERT INTO company_messages (company_id, message_type, message)
    VALUES (${companyId}::UUID, ${messageType}, ${message})
    ON CONFLICT (company_id, message_type) DO UPDATE SET message = ${message}, updated_at = NOW()
  `;
}

export async function upsertCompanyMessages(companyId: string, messages: CompanyMessage[]): Promise<void> {
  for (const m of messages) {
    await upsertCompanyMessage(companyId, m.messageType, m.message);
  }
}

/**
 * Create Customer Invoice (standalone)
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, FileText, Plus, Trash2, Loader2, Info, SlidersHorizontal } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { ScanAndFillButton } from '@/components/accounting/ScanAndFillButton';
import { fuzzyMatchClient } from '@/modules/accounting/utils/fuzzyMatch';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Client { id: string; name: string }
interface LineItem { key: string; description: string; quantity: number; unitPrice: number; incomeType: string }

export default function NewCustomerInvoicePage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [scanBanner, setScanBanner] = useState<string | null>(null);
  const today = new Date().toISOString().split('T')[0];

  const [form, setForm] = useState({ clientId: '', invoiceDate: today, dueDate: '', billingPeriodStart: today, billingPeriodEnd: today, taxRate: 15, notes: '' });
  const [lines, setLines] = useState<LineItem[]>([{ key: '1', description: '', quantity: 1, unitPrice: 0, incomeType: 'other' }]);

  useEffect(() => {
    apiFetch('/api/accounting/customers', { credentials: 'include' }).then(r => r.json()).then(json => {
      const d = json.data || json;
      setClients(Array.isArray(d) ? d : d.clients || []);
    }).catch(() => { /* reference data load failure — non-critical, client dropdown will be empty */ });
  }, []);

  const updateLine = (key: string, field: string, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };
  const addLine = () => setLines(prev => [...prev, { key: String(Date.now()), description: '', quantity: 1, unitPrice: 0, incomeType: 'other' }]);
  const removeLine = (key: string) => setLines(prev => prev.length > 1 ? prev.filter(l => l.key !== key) : prev);

  const subtotal = lines.reduce((s, l) => s + l.quantity * l.unitPrice, 0);
  const tax = subtotal * (form.taxRate / 100);
  const total = subtotal + tax;

  function handleExtracted(data: ExtractedDocument) {
    const updates: Partial<typeof form> = {};
    if (data.date) updates.invoiceDate = data.date;
    if (data.dueDate) updates.dueDate = data.dueDate;
    if (data.vatRate !== null) updates.taxRate = data.vatRate;

    setForm(f => ({ ...f, ...updates }));

    if (data.customerName && clients.length > 0) {
      const match = fuzzyMatchClient(data.customerName, clients);
      if (match) setForm(f => ({ ...f, clientId: String(match.id) }));
    }

    if (data.lineItems.length > 0) {
      setLines(data.lineItems.map(li => ({
        key: String(Date.now() + Math.random()),
        description: li.description,
        quantity: li.quantity ?? 1,
        unitPrice: li.unitPrice ?? 0,
        incomeType: 'other',
      })));
    }

    setScanBanner(`Auto-filled (${Math.round(data.confidence * 100)}% confidence). Review all fields.`);
  }

  const handleSubmit = async () => {
    if (!form.clientId) return setError('Select a client');
    const validLines = lines.filter(l => l.description && l.unitPrice > 0);
    if (validLines.length === 0) return setError('Add at least one line item');
    setSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/customer-invoices-create', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, items: validLines }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Failed to create');
      const d = json.data || json;
      router.push(`/accounting/customer-invoices/${d.id}`);
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed'); setSubmitting(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/customer-invoices" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Invoices
          </Link>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10"><FileText className="h-6 w-6 text-blue-500" /></div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Customer Invoice</h1>
            </div>
            <ScanAndFillButton onExtracted={handleExtracted} label="Scan Invoice" />
          </div>
        </div>

        <div className="p-6 max-w-4xl space-y-6">
          {scanBanner && (
            <div className="p-3 bg-blue-500/10 rounded-lg text-blue-400 text-sm flex items-center gap-2">
              <Info className="h-4 w-4 flex-shrink-0" />{scanBanner}
              <button type="button" onClick={() => setScanBanner(null)} className="ml-auto text-blue-500 hover:text-blue-300 text-xs">Dismiss</button>
            </div>
          )}
          {error && <div className="p-3 bg-red-500/10 rounded-lg text-red-400 text-sm">{error}</div>}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Client *</label>
                <select value={form.clientId} onChange={e => setForm(p => ({ ...p, clientId: e.target.value }))} className="ff-select w-full text-sm">
                  <option value="">Select client...</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">VAT Rate %</label>
                <input type="number" value={form.taxRate} onChange={e => setForm(p => ({ ...p, taxRate: Number(e.target.value) }))} className="ff-input w-full text-sm" />
              </div>
            </div>
            <div className="grid grid-cols-4 gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Invoice Date</label>
                <input type="date" value={form.invoiceDate} onChange={e => setForm(p => ({ ...p, invoiceDate: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Due Date</label>
                <input type="date" value={form.dueDate} onChange={e => setForm(p => ({ ...p, dueDate: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Period Start</label>
                <input type="date" value={form.billingPeriodStart} onChange={e => setForm(p => ({ ...p, billingPeriodStart: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Period End</label>
                <input type="date" value={form.billingPeriodEnd} onChange={e => setForm(p => ({ ...p, billingPeriodEnd: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Notes</label>
              <textarea value={form.notes} onChange={e => setForm(p => ({ ...p, notes: e.target.value }))} rows={2} className="ff-input w-full text-sm" />
            </div>
          </div>

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <div className="px-4 py-3 border-b border-[var(--ff-border-light)] flex items-center justify-between">
              <h3 className="text-sm font-semibold text-[var(--ff-text-primary)]">Line Items</h3>
              <button onClick={addLine} className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1"><Plus className="h-3 w-3" />Add Line</button>
            </div>
            <table className="w-full">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-3 py-2 text-left text-xs text-[var(--ff-text-secondary)]">Description</th>
                  <th className="px-3 py-2 text-center text-xs text-[var(--ff-text-secondary)]">Type</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Qty</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Unit Price</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Total</th>
                  <th className="px-3 py-2 w-8"></th>
                </tr>
              </thead>
              <tbody>
                {lines.map(l => (
                  <tr key={l.key} className="border-b border-[var(--ff-border-light)]">
                    <td className="px-3 py-2"><input value={l.description} onChange={e => updateLine(l.key, 'description', e.target.value)} placeholder="Description *" className="ff-input w-full text-sm" /></td>
                    <td className="px-3 py-2"><select value={l.incomeType} onChange={e => updateLine(l.key, 'incomeType', e.target.value)} className="ff-select text-sm">
                      <option value="activation">Activation</option><option value="bonus">Bonus</option><option value="adjustment">Adjustment</option><option value="other">Other</option>
                    </select></td>
                    <td className="px-3 py-2 w-20"><input type="number" value={l.quantity} onChange={e => updateLine(l.key, 'quantity', Number(e.target.value))} className="ff-input w-full text-sm text-right" /></td>
                    <td className="px-3 py-2 w-28"><input type="number" value={l.unitPrice} onChange={e => updateLine(l.key, 'unitPrice', Number(e.target.value))} className="ff-input w-full text-sm text-right" /></td>
                    <td className="px-3 py-2 text-right font-mono text-sm">{fmt(l.quantity * l.unitPrice)}</td>
                    <td className="px-3 py-2"><button onClick={() => removeLine(l.key)} className="text-red-400 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex items-center justify-between">
            <div className="text-sm space-y-1">
              <p className="text-[var(--ff-text-secondary)]">Subtotal: <span className="font-mono">{fmt(subtotal)}</span></p>
              <p className="text-[var(--ff-text-secondary)]">VAT ({form.taxRate}%): <span className="font-mono">{fmt(tax)}</span></p>
              <p className="text-[var(--ff-text-primary)] font-bold">Total: <span className="font-mono text-blue-400">{fmt(total)}</span></p>
            </div>
            <button onClick={handleSubmit} disabled={submitting} className="px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-sm font-medium disabled:opacity-50">
              {submitting ? <><Loader2 className="h-4 w-4 animate-spin inline mr-1" />Creating...</> : 'Create Invoice'}
            </button>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

