  async function saveDimensionSetting(key: string, value: boolean) {
    try {
      await apiFetch('/api/accounting/accounting-settings', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ key, value: String(value) }),
      });
    } catch { /* ignore */ }
  }

