                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : <p className="text-sm text-[var(--ff-text-tertiary)] text-center py-6">No documents uploaded yet.</p>}
        </section>
      </>
    );
