          {favouriteReports.length > 0 && (
            <div>
              <h2 className="flex items-center gap-2 text-sm font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider mb-3">
                <Star className="h-4 w-4 fill-yellow-400 text-yellow-400" />
                Favourites
              </h2>
