  { value: 'partnership', label: 'Partnership' },
  { value: 'cc', label: 'Close Corporation (CC)' },
  { value: 'pty_ltd', label: 'Private Company (Pty Ltd)' },
  { value: 'ltd', label: 'Public Company (Ltd)' },
  { value: 'npc', label: 'Non-Profit Organisation (NPC)' },
