// ─── Main Drawer ──────────────────────────────────────────────────────────────

export function SetupGuideDrawer({ open, onClose, completedTasks, onMarkDone }: SetupGuideDrawerProps) {
  const completedCount = completedTasks.size;
  const progressPct = TOTAL_TASK_COUNT > 0 ? Math.round((completedCount / TOTAL_TASK_COUNT) * 100) : 0;

  const { companies, switchCompany } = useCompany();
  const demoCompany = companies.find(c => c.companyName.toLowerCase().includes('demo'));

  const handleMarkDone = useCallback((taskId: string) => {
    onMarkDone(taskId);
  }, [onMarkDone]);

  const handleSwitchDemo = useCallback(async () => {
    if (demoCompany) {
      await switchCompany(demoCompany.companyId);
      onClose();
    }
  }, [demoCompany, switchCompany, onClose]);

  return (
    <Drawer open={open} onClose={onClose} title="Setup Guide" width="md">
      {/* Overall progress */}
      <div className="mb-6 p-4 bg-gray-50 dark:bg-gray-800/50 rounded-xl">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
            Overall progress
          </span>
          <span className="text-sm font-semibold text-teal-600 dark:text-teal-400">
            {completedCount} of {TOTAL_TASK_COUNT} tasks
          </span>
        </div>
        <ProgressBar value={progressPct} color="teal" size="md" />
        {completedCount === TOTAL_TASK_COUNT && (
          <p className="mt-2 text-xs text-teal-600 dark:text-teal-400 font-medium">
            Setup complete — you are ready to go!
          </p>
        )}
      </div>

      {/* Category sections */}
      <div className="space-y-2">
        {SETUP_CATEGORIES.map((category, idx) => (
          <CategorySection
            key={category.id}
            categoryId={category.id}
            label={category.label}
            icon={category.icon}
            tasks={category.tasks}
            completedTasks={completedTasks}
            onMarkDone={handleMarkDone}
            defaultOpen={idx === 0}
          />
        ))}
      </div>

      {/* Demo company CTA */}
      {demoCompany && (
        <div className="mt-4 p-4 rounded-xl bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-700/40">
          <div className="flex items-start gap-3">
            <Sparkles className="w-4 h-4 text-teal-600 dark:text-teal-400 mt-0.5 flex-shrink-0" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-teal-800 dark:text-teal-200">
                Want to explore first?
              </p>
              <p className="text-xs text-teal-700 dark:text-teal-300 mt-0.5">
                Try our demo company with sample data to see ISAFlow in action.
              </p>
            </div>
          </div>
          <button
            onClick={() => void handleSwitchDemo()}
            className="mt-3 w-full py-1.5 text-xs font-medium rounded-lg bg-teal-600 hover:bg-teal-500 text-white transition-colors"
          >
            Switch to Demo
          </button>
        </div>
      )}

      {/* Footer */}
      <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700">
        <Button variant="ghost" size="sm" onClick={onClose} className="w-full">
          Close guide
        </Button>
      </div>
    </Drawer>
  );
}

