/**
 * DemoCompanyCTA — dismissable inline banner encouraging new users to explore
 * the demo company. Dismiss state is stored in localStorage only (lightweight).
 */

import { useState, useEffect } from 'react';
import { Sparkles, X } from 'lucide-react';
import { useCompany } from '@/contexts/CompanyContext';

const DISMISSED_KEY = 'isaflow_demo_cta_dismissed';

interface DemoCompanyCTAProps {
  /** Optional override text. Defaults to the standard copy. */
  message?: string;
}

export function DemoCompanyCTA({ message }: DemoCompanyCTAProps) {
  const [dismissed, setDismissed] = useState(true); // default hidden until we read localStorage
  const [demoCompanyId, setDemoCompanyId] = useState<string | null>(null);
  const { companies, switchCompany } = useCompany();

  useEffect(() => {
    const stored = localStorage.getItem(DISMISSED_KEY);
    if (!stored) setDismissed(false);
  }, []);

  useEffect(() => {
    // Find a company whose name contains "demo" (case-insensitive)
    const demo = companies.find(c =>
      c.companyName.toLowerCase().includes('demo'),
    );
    setDemoCompanyId(demo?.companyId ?? null);
  }, [companies]);

  const handleDismiss = () => {
    localStorage.setItem(DISMISSED_KEY, '1');
    setDismissed(true);
  };

  const handleTryDemo = async () => {
    if (demoCompanyId) {
      await switchCompany(demoCompanyId);
    }
    handleDismiss();
  };

  if (dismissed || !demoCompanyId) return null;

  return (
    <div className="flex items-center gap-3 px-4 py-3 rounded-lg bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-700/40 text-sm">
      <Sparkles className="w-4 h-4 flex-shrink-0 text-teal-600 dark:text-teal-400" />
      <p className="flex-1 text-teal-800 dark:text-teal-200">
        {message ?? 'New here? Explore our demo company to see ISAFlow in action.'}
      </p>
      <button
        onClick={() => void handleTryDemo()}
        className="flex-shrink-0 px-3 py-1 rounded-md bg-teal-600 hover:bg-teal-500 text-white text-xs font-medium transition-colors"
      >
        Try Demo
      </button>
      <button
        onClick={handleDismiss}
        aria-label="Dismiss"
        className="flex-shrink-0 text-teal-500 hover:text-teal-700 dark:hover:text-teal-300 transition-colors"
      >
        <X className="w-4 h-4" />
      </button>
    </div>
  );
}

/**
 * SetupGuideDrawer — right-side onboarding checklist drawer.
 * Shows 9 setup categories with collapsible task lists and completion state.
 */

import { useState, useCallback } from 'react';
import Link from 'next/link';
import { ChevronDown, ChevronRight, CheckCircle2, Circle, ExternalLink, Sparkles } from 'lucide-react';
import { Drawer } from '@/components/ui/Drawer';
import { ProgressBar } from '@/components/ui/ProgressBar';
import { Button } from '@/components/ui/Button';
import { cn } from '@/utils/cn';
import { SETUP_CATEGORIES, TOTAL_TASK_COUNT, type SetupTask } from './setupGuideConfig';
import { useCompany } from '@/contexts/CompanyContext';

// ─── Props ───────────────────────────────────────────────────────────────────

interface SetupGuideDrawerProps {
  open: boolean;
  onClose: () => void;
  completedTasks: Set<string>;
  onMarkDone: (taskId: string) => void;
}

// ─── Task Row ────────────────────────────────────────────────────────────────

interface TaskRowProps {
  task: SetupTask;
  isDone: boolean;
  onMarkDone: (id: string) => void;
}

function TaskRow({ task, isDone, onMarkDone }: TaskRowProps) {
  return (
    <div className={cn(
      'flex items-start gap-3 py-2.5 px-3 rounded-lg group',
      'hover:bg-gray-50 dark:hover:bg-gray-800/50 transition-colors',
    )}>
      {/* Status icon */}
      <div className="mt-0.5 flex-shrink-0">
        {isDone
          ? <CheckCircle2 className="w-4 h-4 text-teal-500" />
          : <Circle className="w-4 h-4 text-gray-300 dark:text-gray-600" />
        }
      </div>

      {/* Label + description */}
      <div className="flex-1 min-w-0">
        <Link
          href={task.href}
          className={cn(
            'text-sm font-medium inline-flex items-center gap-1',
            isDone
              ? 'line-through text-gray-400 dark:text-gray-500'
              : 'text-gray-800 dark:text-gray-200 hover:text-teal-600 dark:hover:text-teal-400',
          )}
        >
          {task.label}
          {!isDone && <ExternalLink className="w-3 h-3 opacity-0 group-hover:opacity-50 transition-opacity" />}
        </Link>
        <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 leading-snug">
          {task.description}
        </p>
      </div>

      {/* Mark done button */}
      {!isDone && (
        <button
          onClick={() => onMarkDone(task.id)}
          className={cn(
            'flex-shrink-0 text-xs px-2 py-1 rounded border transition-colors',
            'border-gray-200 dark:border-gray-700',
            'text-gray-500 dark:text-gray-400',
            'hover:border-teal-400 hover:text-teal-600 dark:hover:text-teal-400',
            'opacity-0 group-hover:opacity-100',
          )}
          title="Mark as done"
        >
          Done
        </button>
      )}
    </div>
  );
}

// ─── Category Section ─────────────────────────────────────────────────────────

interface CategorySectionProps {
  categoryId: string;
  label: string;
  icon: React.ElementType;
  tasks: SetupTask[];
  completedTasks: Set<string>;
  onMarkDone: (taskId: string) => void;
  defaultOpen?: boolean;
}

function CategorySection({
  categoryId,
  label,
  icon: Icon,
  tasks,
  completedTasks,
  onMarkDone,
  defaultOpen = false,
}: CategorySectionProps) {
  const [isOpen, setIsOpen] = useState(defaultOpen);
  const doneCount = tasks.filter(t => completedTasks.has(t.id)).length;
  const isComplete = doneCount === tasks.length;

  return (
    <div className="border border-gray-200 dark:border-gray-700 rounded-xl overflow-hidden">
      {/* Category header */}
      <button
        onClick={() => setIsOpen(o => !o)}
        className={cn(
          'w-full flex items-center gap-3 px-4 py-3 text-left transition-colors',
          'hover:bg-gray-50 dark:hover:bg-gray-800/50',
          isComplete && 'bg-teal-50/50 dark:bg-teal-900/10',
        )}
        aria-expanded={isOpen}
        aria-controls={`category-${categoryId}`}
      >
        {/* Icon */}
        <div className={cn(
          'w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0',
          isComplete
            ? 'bg-teal-100 dark:bg-teal-900/40 text-teal-600 dark:text-teal-400'
            : 'bg-gray-100 dark:bg-gray-800 text-gray-500 dark:text-gray-400',
        )}>
          <Icon className="w-4 h-4" />
        </div>

        {/* Label + fraction */}
        <div className="flex-1 min-w-0">
          <span className={cn(
            'text-sm font-semibold',
            isComplete
              ? 'text-teal-700 dark:text-teal-300'
              : 'text-gray-900 dark:text-gray-100',
          )}>
            {label}
          </span>
          <span className="ml-2 text-xs text-gray-400 dark:text-gray-500">
            {doneCount} of {tasks.length}
          </span>
        </div>

        {/* Chevron */}
        {isOpen
          ? <ChevronDown className="w-4 h-4 text-gray-400 flex-shrink-0" />
          : <ChevronRight className="w-4 h-4 text-gray-400 flex-shrink-0" />
        }
      </button>

      {/* Task list */}
      {isOpen && (
        <div id={`category-${categoryId}`} className="px-2 pb-2 border-t border-gray-100 dark:border-gray-700/50">
          {tasks.map(task => (
            <TaskRow
              key={task.id}
              task={task}
              isDone={completedTasks.has(task.id)}
              onMarkDone={onMarkDone}
            />
          ))}
        </div>
      )}
    </div>
  );
}

// ─── Main Drawer ──────────────────────────────────────────────────────────────

export function SetupGuideDrawer({ open, onClose, completedTasks, onMarkDone }: SetupGuideDrawerProps) {
  const completedCount = completedTasks.size;
  const progressPct = TOTAL_TASK_COUNT > 0 ? Math.round((completedCount / TOTAL_TASK_COUNT) * 100) : 0;

  const { companies, switchCompany } = useCompany();
  const demoCompany = companies.find(c => c.companyName.toLowerCase().includes('demo'));

  const handleMarkDone = useCallback((taskId: string) => {
    onMarkDone(taskId);
  }, [onMarkDone]);

  const handleSwitchDemo = useCallback(async () => {
    if (demoCompany) {
      await switchCompany(demoCompany.companyId);
      onClose();
    }
  }, [demoCompany, switchCompany, onClose]);

  return (
    <Drawer open={open} onClose={onClose} title="Setup Guide" width="md">
      {/* Overall progress */}
      <div className="mb-6 p-4 bg-gray-50 dark:bg-gray-800/50 rounded-xl">
        <div className="flex items-center justify-between mb-2">
          <span className="text-sm font-medium text-gray-700 dark:text-gray-300">
            Overall progress
          </span>
          <span className="text-sm font-semibold text-teal-600 dark:text-teal-400">
            {completedCount} of {TOTAL_TASK_COUNT} tasks
          </span>
        </div>
        <ProgressBar value={progressPct} color="teal" size="md" />
        {completedCount === TOTAL_TASK_COUNT && (
          <p className="mt-2 text-xs text-teal-600 dark:text-teal-400 font-medium">
            Setup complete — you are ready to go!
          </p>
        )}
      </div>

      {/* Category sections */}
      <div className="space-y-2">
        {SETUP_CATEGORIES.map((category, idx) => (
          <CategorySection
            key={category.id}
            categoryId={category.id}
            label={category.label}
            icon={category.icon}
            tasks={category.tasks}
            completedTasks={completedTasks}
            onMarkDone={handleMarkDone}
            defaultOpen={idx === 0}
          />
        ))}
      </div>

      {/* Demo company CTA */}
      {demoCompany && (
        <div className="mt-4 p-4 rounded-xl bg-teal-50 dark:bg-teal-900/20 border border-teal-200 dark:border-teal-700/40">
          <div className="flex items-start gap-3">
            <Sparkles className="w-4 h-4 text-teal-600 dark:text-teal-400 mt-0.5 flex-shrink-0" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium text-teal-800 dark:text-teal-200">
                Want to explore first?
              </p>
              <p className="text-xs text-teal-700 dark:text-teal-300 mt-0.5">
                Try our demo company with sample data to see ISAFlow in action.
              </p>
            </div>
          </div>
          <button
            onClick={() => void handleSwitchDemo()}
            className="mt-3 w-full py-1.5 text-xs font-medium rounded-lg bg-teal-600 hover:bg-teal-500 text-white transition-colors"
          >
            Switch to Demo
          </button>
        </div>
      )}

      {/* Footer */}
      <div className="mt-4 pt-4 border-t border-gray-200 dark:border-gray-700">
        <Button variant="ghost" size="sm" onClick={onClose} className="w-full">
          Close guide
        </Button>
      </div>
    </Drawer>
  );
}

/**
 * Create Customer Invoice (standalone)
 */

import { useState, useEffect } from 'react';
import { useRouter } from 'next/router';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import { ArrowLeft, FileText, Plus, Trash2, Loader2, Info, SlidersHorizontal } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import { ScanAndFillButton } from '@/components/accounting/ScanAndFillButton';
import { fuzzyMatchClient } from '@/modules/accounting/utils/fuzzyMatch';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

const fmt = (n: number) => new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

interface Client { id: string; name: string }
interface LineItem { key: string; description: string; quantity: number; unitPrice: number; incomeType: string; discount: number }

export default function NewCustomerInvoicePage() {
  const router = useRouter();
  const [clients, setClients] = useState<Client[]>([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [scanBanner, setScanBanner] = useState<string | null>(null);
  const today = new Date().toISOString().split('T')[0];

  const [form, setForm] = useState({ clientId: '', invoiceDate: today, dueDate: '', billingPeriodStart: today, billingPeriodEnd: today, taxRate: 15, notes: '' });
  const [lines, setLines] = useState<LineItem[]>([{ key: '1', description: '', quantity: 1, unitPrice: 0, incomeType: 'other', discount: 0 }]);
  const [showDiscount, setShowDiscount] = useState(false);

  useEffect(() => {
    apiFetch('/api/accounting/customers', { credentials: 'include' }).then(r => r.json()).then(json => {
      const d = json.data || json;
      setClients(Array.isArray(d) ? d : d.clients || []);
    }).catch(() => { /* reference data load failure — non-critical, client dropdown will be empty */ });
  }, []);

  const updateLine = (key: string, field: string, value: string | number) => {
    setLines(prev => prev.map(l => l.key === key ? { ...l, [field]: value } : l));
  };
  const addLine = () => setLines(prev => [...prev, { key: String(Date.now()), description: '', quantity: 1, unitPrice: 0, incomeType: 'other', discount: 0 }]);
  const removeLine = (key: string) => setLines(prev => prev.length > 1 ? prev.filter(l => l.key !== key) : prev);

  const lineTotal = (l: LineItem) => l.quantity * l.unitPrice * (1 - (l.discount || 0) / 100);
  const subtotal = lines.reduce((s, l) => s + lineTotal(l), 0);
  const tax = subtotal * (form.taxRate / 100);
  const total = subtotal + tax;

  function handleExtracted(data: ExtractedDocument) {
    const updates: Partial<typeof form> = {};
    if (data.date) updates.invoiceDate = data.date;
    if (data.dueDate) updates.dueDate = data.dueDate;
    if (data.vatRate !== null) updates.taxRate = data.vatRate;

    setForm(f => ({ ...f, ...updates }));

    if (data.customerName && clients.length > 0) {
      const match = fuzzyMatchClient(data.customerName, clients);
      if (match) setForm(f => ({ ...f, clientId: String(match.id) }));
    }

    if (data.lineItems.length > 0) {
      setLines(data.lineItems.map(li => ({
        key: String(Date.now() + Math.random()),
        description: li.description,
        quantity: li.quantity ?? 1,
        unitPrice: li.unitPrice ?? 0,
        incomeType: 'other',
        discount: 0,
      })));
    }

    setScanBanner(`Auto-filled (${Math.round(data.confidence * 100)}% confidence). Review all fields.`);
  }

  const handleSubmit = async () => {
    if (!form.clientId) return setError('Select a client');
    const validLines = lines.filter(l => l.description && l.unitPrice > 0);
    if (validLines.length === 0) return setError('Add at least one line item');
    setSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/customer-invoices-create', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ ...form, items: validLines }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || 'Failed to create');
      const d = json.data || json;
      router.push(`/accounting/customer-invoices/${d.id}`);
    } catch (e) { setError(e instanceof Error ? e.message : 'Failed'); setSubmitting(false); }
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <Link href="/accounting/customer-invoices" className="inline-flex items-center gap-1 text-sm text-[var(--ff-text-secondary)] hover:text-blue-400 mb-3">
            <ArrowLeft className="h-4 w-4" /> Back to Invoices
          </Link>
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-blue-500/10"><FileText className="h-6 w-6 text-blue-500" /></div>
              <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">New Customer Invoice</h1>
            </div>
            <ScanAndFillButton onExtracted={handleExtracted} label="Scan Invoice" />
          </div>
        </div>

        <div className="p-6 max-w-4xl space-y-6">
          {scanBanner && (
            <div className="p-3 bg-blue-500/10 rounded-lg text-blue-400 text-sm flex items-center gap-2">
              <Info className="h-4 w-4 flex-shrink-0" />{scanBanner}
              <button type="button" onClick={() => setScanBanner(null)} className="ml-auto text-blue-500 hover:text-blue-300 text-xs">Dismiss</button>
            </div>
          )}
          {error && <div className="p-3 bg-red-500/10 rounded-lg text-red-400 text-sm">{error}</div>}

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4 space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Client *</label>
                <select value={form.clientId} onChange={e => setForm(p => ({ ...p, clientId: e.target.value }))} className="ff-select w-full text-sm">
                  <option value="">Select client...</option>
                  {clients.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">VAT Rate %</label>
                <input type="number" value={form.taxRate} onChange={e => setForm(p => ({ ...p, taxRate: Number(e.target.value) }))} className="ff-input w-full text-sm" />
              </div>
            </div>
            <div className="grid grid-cols-4 gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Invoice Date</label>
                <input type="date" value={form.invoiceDate} onChange={e => setForm(p => ({ ...p, invoiceDate: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Due Date</label>
                <input type="date" value={form.dueDate} onChange={e => setForm(p => ({ ...p, dueDate: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Period Start</label>
                <input type="date" value={form.billingPeriodStart} onChange={e => setForm(p => ({ ...p, billingPeriodStart: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Period End</label>
                <input type="date" value={form.billingPeriodEnd} onChange={e => setForm(p => ({ ...p, billingPeriodEnd: e.target.value }))} className="ff-input w-full text-sm" />
              </div>
            </div>
            <div>
              <label className="block text-xs text-[var(--ff-text-secondary)] mb-1">Notes</label>
              <textarea value={form.notes} onChange={e => setForm(p => ({ ...p, notes: e.target.value }))} rows={2} className="ff-input w-full text-sm" />
            </div>
          </div>

          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            <div className="px-4 py-3 border-b border-[var(--ff-border-light)] flex items-center justify-between">
              <h3 className="text-sm font-semibold text-[var(--ff-text-primary)]">Line Items</h3>
              <div className="flex items-center gap-2">
                <button
                  onClick={() => setShowDiscount(v => !v)}
                  className={`inline-flex items-center gap-1 text-xs px-2 py-1 rounded border transition-colors ${showDiscount ? 'border-teal-500/60 text-teal-400 bg-teal-500/10' : 'border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:border-teal-500/40 hover:text-teal-400'}`}
                  title="Toggle discount column"
                >
                  <SlidersHorizontal className="h-3 w-3" />
                  {showDiscount ? 'Hide Disc.' : 'Disc. %'}
                </button>
                <button onClick={addLine} className="text-xs text-blue-400 hover:text-blue-300 flex items-center gap-1"><Plus className="h-3 w-3" />Add Line</button>
              </div>
            </div>
            <table className="w-full">
              <thead>
                <tr className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-tertiary)]">
                  <th className="px-3 py-2 text-left text-xs text-[var(--ff-text-secondary)]">Description</th>
                  <th className="px-3 py-2 text-center text-xs text-[var(--ff-text-secondary)]">Type</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Qty</th>
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Unit Price</th>
                  {showDiscount && (
                    <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)] w-20">Disc. %</th>
                  )}
                  <th className="px-3 py-2 text-right text-xs text-[var(--ff-text-secondary)]">Total</th>
                  <th className="px-3 py-2 w-8"></th>
                </tr>
              </thead>
              <tbody>
                {lines.map(l => (
                  <tr key={l.key} className="border-b border-[var(--ff-border-light)]">
                    <td className="px-3 py-2"><input value={l.description} onChange={e => updateLine(l.key, 'description', e.target.value)} placeholder="Description *" className="ff-input w-full text-sm" /></td>
                    <td className="px-3 py-2"><select value={l.incomeType} onChange={e => updateLine(l.key, 'incomeType', e.target.value)} className="ff-select text-sm">
                      <option value="activation">Activation</option><option value="bonus">Bonus</option><option value="adjustment">Adjustment</option><option value="other">Other</option>
                    </select></td>
                    <td className="px-3 py-2 w-20"><input type="number" value={l.quantity} onChange={e => updateLine(l.key, 'quantity', Number(e.target.value))} className="ff-input w-full text-sm text-right" /></td>
                    <td className="px-3 py-2 w-28"><input type="number" value={l.unitPrice} onChange={e => updateLine(l.key, 'unitPrice', Number(e.target.value))} className="ff-input w-full text-sm text-right" /></td>
                    {showDiscount && (
                      <td className="px-3 py-2 w-20">
                        <input
                          type="number"
                          min={0}
                          max={100}
                          step={0.1}
                          value={l.discount || ''}
                          onChange={e => updateLine(l.key, 'discount', e.target.value === '' ? 0 : Number(e.target.value))}
                          placeholder="0"
                          className="ff-input w-full text-sm text-right"
                        />
                      </td>
                    )}
                    <td className="px-3 py-2 text-right font-mono text-sm">
                      {fmt(lineTotal(l))}
                      {showDiscount && l.discount > 0 && (
                        <span className="block text-xs text-teal-500 dark:text-teal-400">
                          -{l.discount}%
                        </span>
                      )}
                    </td>
                    <td className="px-3 py-2"><button onClick={() => removeLine(l.key)} className="text-red-400 hover:text-red-300"><Trash2 className="h-3.5 w-3.5" /></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          <div className="flex items-center justify-between">
            <div className="text-sm space-y-1">
              <p className="text-[var(--ff-text-secondary)]">Subtotal: <span className="font-mono">{fmt(subtotal)}</span></p>
              <p className="text-[var(--ff-text-secondary)]">VAT ({form.taxRate}%): <span className="font-mono">{fmt(tax)}</span></p>
              <p className="text-[var(--ff-text-primary)] font-bold">Total: <span className="font-mono text-blue-400">{fmt(total)}</span></p>
            </div>
            <button onClick={handleSubmit} disabled={submitting} className="px-6 py-2.5 bg-blue-600 hover:bg-blue-500 text-white rounded-lg text-sm font-medium disabled:opacity-50">
              {submitting ? <><Loader2 className="h-4 w-4 animate-spin inline mr-1" />Creating...</> : 'Create Invoice'}
            </button>
          </div>
        </div>
      </div>
    </AppLayout>
  );
}

