/**
 * Audit Trail Service
 * Field-level change history for all accounting entities.
 * logAudit is fire-and-forget — never throws.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export type AuditAction =
  | 'create'
  | 'update'
  | 'delete'
  | 'post'
  | 'reverse'
  | 'approve'
  | 'reject'
  | 'login'
  | 'export';

export interface AuditFieldChange {
  field: string;
  old: string | null;
  new: string | null;
  label: string;
}

export interface AuditChanges {
  fields: AuditFieldChange[];
  metadata?: Record<string, string>;
}

export interface AuditLogItem {
  id: string;
  companyId: string;
  userId: string;
  userEmail: string | null;
  action: AuditAction;
  entityType: string;
  entityId: string;
  entityRef: string | null;
  changes: AuditChanges | null;
  ipAddress: string | null;
  userAgent: string | null;
  sessionId: string | null;
  createdAt: string;
}

export interface LogAuditParams {
  companyId: string;
  userId: string;
  userEmail?: string;
  action: AuditAction;
  entityType: string;
  entityId: string;
  entityRef?: string;
  changes?: AuditChanges;
  ip?: string;
  userAgent?: string;
  sessionId?: string;
}

export interface AuditLogFilters {
  entityType?: string;
  entityId?: string;
  userId?: string;
  action?: string;
  dateFrom?: string;
  dateTo?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

/**
 * Fire-and-forget audit log writer. Never throws — errors are swallowed
 * so audit failures never break the calling transaction.
 */
export async function logAudit(params: LogAuditParams): Promise<void> {
  try {
    const changesJson = params.changes ? JSON.stringify(params.changes) : null;
    await sql`
      INSERT INTO audit_log (
        company_id, user_id, user_email, action,
        entity_type, entity_id, entity_ref,
        changes, ip_address, user_agent, session_id
      ) VALUES (
        ${params.companyId}::UUID,
        ${params.userId},
        ${params.userEmail ?? null},
        ${params.action},
        ${params.entityType},
        ${params.entityId}::UUID,
        ${params.entityRef ?? null},
        ${changesJson}::JSONB,
        ${params.ip ?? null},
        ${params.userAgent ?? null},
        ${params.sessionId ? params.sessionId + '::UUID' : null}
      )
    `;
  } catch (err) {
    // Never surface audit errors to callers
    log.warn('Audit log write failed', { error: err, params }, 'audit-trail');
  }
}

export async function getAuditLog(
  companyId: string,
  filters: AuditLogFilters,
): Promise<{ items: AuditLogItem[]; total: number }> {
  try {
    const limit = filters.limit ?? 50;
    const offset = filters.offset ?? 0;

    // Build conditional clauses using separate queries per filter combination
    // to avoid dynamic SQL string concatenation
    const entityType = filters.entityType ?? null;
    const entityId = filters.entityId ?? null;
    const userId = filters.userId ?? null;
    const action = filters.action ?? null;
    const dateFrom = filters.dateFrom ?? null;
    const dateTo = filters.dateTo ?? null;
    const search = filters.search ? `%${filters.search}%` : null;

    const [rows, countRows] = await Promise.all([
      sql`
        SELECT *
        FROM audit_log
        WHERE company_id = ${companyId}::UUID
          AND (${entityType}::VARCHAR IS NULL OR entity_type = ${entityType})
          AND (${entityId}::UUID IS NULL OR entity_id = ${entityId}::UUID)
          AND (${userId}::VARCHAR IS NULL OR user_id = ${userId})
          AND (${action}::VARCHAR IS NULL OR action = ${action})
          AND (${dateFrom}::TIMESTAMPTZ IS NULL OR created_at >= ${dateFrom}::TIMESTAMPTZ)
          AND (${dateTo}::TIMESTAMPTZ IS NULL OR created_at <= ${dateTo}::TIMESTAMPTZ)
          AND (
            ${search}::VARCHAR IS NULL
            OR user_email ILIKE ${search}
            OR entity_ref ILIKE ${search}
            OR entity_type ILIKE ${search}
          )
        ORDER BY created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM audit_log
        WHERE company_id = ${companyId}::UUID
          AND (${entityType}::VARCHAR IS NULL OR entity_type = ${entityType})
          AND (${entityId}::UUID IS NULL OR entity_id = ${entityId}::UUID)
          AND (${userId}::VARCHAR IS NULL OR user_id = ${userId})
          AND (${action}::VARCHAR IS NULL OR action = ${action})
          AND (${dateFrom}::TIMESTAMPTZ IS NULL OR created_at >= ${dateFrom}::TIMESTAMPTZ)
          AND (${dateTo}::TIMESTAMPTZ IS NULL OR created_at <= ${dateTo}::TIMESTAMPTZ)
          AND (
            ${search}::VARCHAR IS NULL
            OR user_email ILIKE ${search}
            OR entity_ref ILIKE ${search}
            OR entity_type ILIKE ${search}
          )
      ` as Promise<Row[]>,
    ]);

    return {
      items: rows.map(mapAuditRow),
      total: Number(countRows[0].cnt),
    };
  } catch (err) {
    log.error('Failed to get audit log', { companyId, filters, error: err }, 'audit-trail');
    throw err;
  }
}

export async function getEntityHistory(
  companyId: string,
  entityType: string,
  entityId: string,
): Promise<AuditLogItem[]> {
  try {
    const rows = (await sql`
      SELECT *
      FROM audit_log
      WHERE company_id = ${companyId}::UUID
        AND entity_type = ${entityType}
        AND entity_id = ${entityId}::UUID
      ORDER BY created_at DESC
      LIMIT 500
    `) as Row[];
    return rows.map(mapAuditRow);
  } catch (err) {
    log.error('Failed to get entity history', { companyId, entityType, entityId, error: err }, 'audit-trail');
    throw err;
  }
}

/**
 * Diffs two objects and returns an array of field changes.
 * Only includes fields that actually changed.
 */
export function diffObjects(
  oldObj: Record<string, unknown>,
  newObj: Record<string, unknown>,
  fieldLabels: Record<string, string>,
): AuditFieldChange[] {
  const allKeys = new Set([...Object.keys(oldObj), ...Object.keys(newObj)]);
  const changes: AuditFieldChange[] = [];

  for (const key of allKeys) {
    const oldVal = oldObj[key];
    const newVal = newObj[key];
    const oldStr = oldVal == null ? null : String(oldVal);
    const newStr = newVal == null ? null : String(newVal);
    if (oldStr !== newStr) {
      changes.push({
        field: key,
        old: oldStr,
        new: newStr,
        label: fieldLabels[key] ?? key,
      });
    }
  }

  return changes;
}

function mapAuditRow(row: Row): AuditLogItem {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    userId: String(row.user_id),
    userEmail: row.user_email ? String(row.user_email) : null,
    action: String(row.action) as AuditAction,
    entityType: String(row.entity_type),
    entityId: String(row.entity_id),
    entityRef: row.entity_ref ? String(row.entity_ref) : null,
    changes: row.changes ?? null,
    ipAddress: row.ip_address ? String(row.ip_address) : null,
    userAgent: row.user_agent ? String(row.user_agent) : null,
    sessionId: row.session_id ? String(row.session_id) : null,
    createdAt: row.created_at instanceof Date
      ? row.created_at.toISOString()
      : String(row.created_at),
  };
}

/**
 * Next.js Edge Middleware
 * - admin.isaflow.co.za: admin subdomain — rewrites clean paths to /admin/*
 * - app.isaflow.co.za: redirect / to /accounting (app domain — no landing page)
 * - isaflow.co.za: show landing page at /
 * - Redirects unauthenticated /accounting/* requests to /login
 */

import { NextResponse } from 'next/server';
import type { NextRequest } from 'next/server';
import { jwtVerify } from 'jose';

const AUTH_COOKIE_NAME = 'ff_auth_token';

const getJWTSecret = (): Uint8Array =>
  new TextEncoder().encode(process.env.JWT_SECRET ?? '');

const PUBLIC_PATHS = ['/login', '/register', '/api/auth/login', '/api/auth/logout', '/api/auth/register', '/onboarding', '/api/onboarding', '/invite', '/api/invite'];

/** Hostnames that should skip the landing page and go straight to the app */
const APP_HOSTS = ['app.isaflow.co.za'];

/** Hostnames that serve the admin subdomain */
const ADMIN_HOSTS = ['admin.isaflow.co.za'];

/** Paths on the admin subdomain that should NOT be rewritten to /admin/* */
const ADMIN_PASSTHROUGH = ['/_next', '/api/', '/icons', '/login', '/register', '/landing', '/invite'];

const ADMIN_URL = process.env.NEXT_PUBLIC_ADMIN_URL ?? 'https://admin.isaflow.co.za';

async function verifyAdmin(request: NextRequest): Promise<'ok' | 'no-token' | 'invalid'> {
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;
  if (!token) return 'no-token';
  try {
    const { payload } = await jwtVerify(token, getJWTSecret());
    return payload.role === 'super_admin' ? 'ok' : 'invalid';
  } catch {
    return 'invalid';
  }
}

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;
  const host = request.headers.get('host')?.split(':')[0] ?? '';
  const isAdminHost = ADMIN_HOSTS.includes(host);

  // --- Admin subdomain routing ---
  if (isAdminHost) {
    // Let public paths, static files, and API routes pass through
    if (
      ADMIN_PASSTHROUGH.some(p => pathname.startsWith(p)) ||
      pathname === '/manifest.json' ||
      pathname === '/sw.js' ||
      pathname === '/favicon.ico'
    ) {
      return NextResponse.next();
    }

    // Rewrite clean paths → /admin/* (e.g. /companies → /admin/companies, / → /admin)
    const adminPath = pathname === '/' ? '/admin' : `/admin${pathname}`;

    // Auth check before rewrite
    const authResult = await verifyAdmin(request);
    if (authResult !== 'ok') {
      const loginUrl = new URL('/login', request.url);
      loginUrl.searchParams.set('returnTo', pathname);
      return NextResponse.redirect(loginUrl);
    }

    // Rewrite (keeps the clean URL in the browser)
    const url = request.nextUrl.clone();
    url.pathname = adminPath;
    return NextResponse.rewrite(url);
  }

  // --- App/landing domain: block /admin/* and redirect to admin subdomain ---
  if (pathname.startsWith('/admin') && !pathname.startsWith('/api/admin')) {
    const cleanPath = pathname.replace(/^\/admin/, '') || '/';
    return NextResponse.redirect(new URL(cleanPath, ADMIN_URL));
  }

  // Allow public paths, static files, and API routes
  if (
    PUBLIC_PATHS.some(p => pathname.startsWith(p)) ||
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/') ||
    pathname.startsWith('/icons') ||
    pathname.startsWith('/landing') ||
    pathname === '/manifest.json' ||
    pathname === '/sw.js' ||
    pathname === '/favicon.ico'
  ) {
    return NextResponse.next();
  }

  // app.isaflow.co.za: redirect root to /accounting
  if (pathname === '/' && APP_HOSTS.includes(host)) {
    return NextResponse.redirect(new URL('/accounting', request.url));
  }

  // Check for auth cookie on protected routes
  const token = request.cookies.get(AUTH_COOKIE_NAME)?.value;

  if (!token && (pathname.startsWith('/accounting') || pathname.startsWith('/payroll'))) {
    const loginUrl = new URL('/login', request.url);
    loginUrl.searchParams.set('returnTo', pathname);
    return NextResponse.redirect(loginUrl);
  }

  // Redirect to onboarding if user hasn't completed it
  if (token && !request.cookies.get('ff_onboarding_done')?.value) {
    if (pathname.startsWith('/accounting') || pathname.startsWith('/payroll')) {
      return NextResponse.redirect(new URL('/onboarding', request.url));
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: ['/((?!_next/static|_next/image|favicon.ico).*)'],
};

/**
 * KPI Dashboard API
 * GET /api/accounting/kpi-dashboard
 *   ?from=YYYY-MM-DD   - period start (defaults to start of current month)
 *   ?to=YYYY-MM-DD     - period end (defaults to today)
 *   ?months=N           - chart lookback months (default 6)
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import {
  getDashboardKPIs,
  getRevenueChart,
  getCashFlowChart,
  getAgingBreakdown,
  getTopCustomers,
  getTopExpenseCategories,
} from '@/modules/accounting/services/kpiService';

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['GET']);
  }

  const { companyId } = req as CompanyApiRequest;

  try {
    const now = new Date();
    const year = now.getFullYear();
    const month = now.getMonth() + 1;

    // Default to start of financial year (12 months back from current month-end)
    const fyStart = new Date(year, month - 13, 1); // ~12 months ago
    const from = req.query.from
      ? String(req.query.from)
      : fyStart.toISOString().slice(0, 10);
    const to = req.query.to
      ? String(req.query.to)
      : now.toISOString().slice(0, 10);
    const months = req.query.months ? Number(req.query.months) : 6;

