  );

  useEffect(() => {
    loadKPIData();
    loadQuickActions();
  }, []);

  const loadKPIData = async () => {
    setIsLoading(true);
    try {
      const res = await apiFetch('/api/accounting/kpi-dashboard', { credentials: 'include' });
      const json = await res.json();
      const payload = json.data || json;
