import {
  createContext,
  useContext,
  useEffect,
  useState,
  ReactNode,
  useCallback,
} from 'react';
import type { AuthRole } from '@/lib/auth/types';

/**
 * Authenticated user shape returned from /api/auth/me
 */
export interface AuthUser {
  id: string;
  email: string;
  firstName: string;
  lastName: string;
  name: string;
  role: AuthRole;
  permissions: string[];
  isActive: boolean;
  profilePicture?: string | null;
  department?: string;
  onboardingCompleted?: boolean;
}

export interface TwoFactorChallenge {
  tempToken: string;
}

interface AuthContextType {
  /** Currently authenticated user, or null if not logged in */
  user: AuthUser | null;
  /** True while the initial session check is in progress */
  loading: boolean;
  /** Last authentication error message */
  error: string | null;
  /** True when a valid user session exists */
  isAuthenticated: boolean;
  /** Set when login requires 2FA verification */
  twoFactorChallenge: TwoFactorChallenge | null;

  /** Sign in with email and password. Returns true if 2FA challenge was issued. */
  login: (email: string, password: string, deviceFingerprint?: string) => Promise<boolean>;
  /** Complete 2FA challenge during login */
  completeTwoFactor: (code: string, trustDevice?: boolean, deviceFingerprint?: string, deviceName?: string) => Promise<void>;
  /** Sign out and redirect to /sign-in */
  logout: () => Promise<void>;
  /** Re-fetch the current user from /api/auth/me */
  refreshUser: () => Promise<void>;
  /** Clear the current error state */
  clearError: () => void;

  /** Check if the user has a specific permission string */
  hasPermission: (permission: string) => boolean;
  /** Check if the user has the given role or higher */
  hasRole: (role: AuthRole) => boolean;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

/**
 * Map the raw API response into a typed AuthUser
 */
function mapApiUser(raw: Record<string, unknown>): AuthUser {
  const firstName = (raw.firstName as string) || (raw.first_name as string) || '';
  const lastName = (raw.lastName as string) || (raw.last_name as string) || '';
  const name =
    (raw.name as string) ||
    (firstName && lastName ? `${firstName} ${lastName}`.trim() : (raw.email as string));

  return {
    id: raw.id as string,
    email: raw.email as string,
    firstName,
    lastName,
    name,
    role: (raw.role as AuthRole) || 'viewer',
    permissions: (raw.permissions as string[]) || [],
    isActive: raw.isActive !== false && raw.is_active !== false,
    profilePicture: (raw.profilePicture as string) || (raw.profile_picture as string) || null,
    department: (raw.department as string) || undefined,
    onboardingCompleted: raw.onboardingCompleted === true || raw.onboarding_completed === true,
  };
}

// Role hierarchy for permission checks
const ROLE_HIERARCHY: Record<AuthRole, number> = {
  super_admin: 6,
  system: 5,
  admin: 4,
  manager: 3,
  storeman: 2,
  technician: 2,
  viewer: 1,
};

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<AuthUser | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [twoFactorChallenge, setTwoFactorChallenge] = useState<TwoFactorChallenge | null>(null);

  /**
   * Fetch current session from the API
   */
  const checkAuth = useCallback(async () => {
    try {
      const res = await fetch('/api/auth/me', { credentials: 'include' });

      if (res.ok) {
        const data = await res.json();
        // Support both { data: { user } } and { data: user } shapes
        const raw = data.data?.user ?? data.data ?? data.user;
        if (raw) {
          setUser(mapApiUser(raw));
        } else {
          setUser(null);
        }
      } else {
        setUser(null);
      }
    } catch {
      setUser(null);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    checkAuth();

    // Re-fetch user when tab regains focus (picks up RBAC changes)
    const onFocus = () => checkAuth();
    window.addEventListener('focus', onFocus);

    // Also poll every 5 minutes as a fallback
    const interval = setInterval(checkAuth, 5 * 60 * 1000);

    return () => {
      window.removeEventListener('focus', onFocus);
      clearInterval(interval);
    };
  }, [checkAuth]);

  /**
   * Sign in with email/password credentials.
   * If 2FA is enabled, sets twoFactorChallenge and does NOT set user.
   * Returns true if a 2FA challenge was issued, false if login completed.
   */
  const login = async (email: string, password: string, deviceFingerprint?: string): Promise<boolean> => {
    setLoading(true);
    setError(null);
    setTwoFactorChallenge(null);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password, deviceFingerprint }),
        credentials: 'include',
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error?.message || data.message || 'Login failed');
      }

      // 2FA required — store temp token for the challenge step
      if (data.data?.requiresTwoFactor) {
        setTwoFactorChallenge({ tempToken: data.data.tempToken as string });
        return true;
      }

      const raw = data.data?.user ?? data.data ?? data.user;
      setUser(raw ? mapApiUser(raw) : null);
      return false;
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Login failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Complete 2FA challenge — verify code and obtain full session.
   */
  const completeTwoFactor = async (
    code: string,
    trustDevice?: boolean,
    deviceFingerprint?: string,
    deviceName?: string
  ) => {
    if (!twoFactorChallenge) throw new Error('No 2FA challenge active');

    setLoading(true);
    setError(null);

    try {
      const res = await fetch('/api/auth/2fa-verify', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          tempToken: twoFactorChallenge.tempToken,
          code,
          trustDevice,
          deviceFingerprint,
          deviceName,
        }),
        credentials: 'include',
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error?.message || data.message || 'Invalid code');
      }

      setTwoFactorChallenge(null);
      const raw = data.data?.user ?? data.data ?? data.user;
      setUser(raw ? mapApiUser(raw) : null);
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Verification failed';
      setError(message);
      throw err;
    } finally {
      setLoading(false);
    }
  };

  /**
   * Sign out and clear session cookie
   */
  const logout = async () => {
    try {
      await fetch('/api/auth/logout', {
        method: 'POST',
        credentials: 'include',
      });
    } finally {
      setUser(null);
      if (typeof window !== 'undefined') {
        window.location.href = '/login';
      }
    }
  };

  const refreshUser = async () => {
    await checkAuth();
  };

  const clearError = () => {
    setError(null);
  };

  /**
   * Check if the current user holds a specific permission string.
   * Users with the 'all' permission pass all checks.
   */
  const hasPermission = (permission: string): boolean => {
    if (!user) return false;
    return user.permissions.includes('all') || user.permissions.includes(permission);
  };

  /**
   * Check if the current user's role meets or exceeds the required role level.
   */
  const hasRole = (role: AuthRole): boolean => {
    if (!user) return false;
    const userLevel = ROLE_HIERARCHY[user.role] ?? 0;
    const requiredLevel = ROLE_HIERARCHY[role] ?? 0;
    return userLevel >= requiredLevel;
  };

  const value: AuthContextType = {
    user,
    loading,
    error,
    isAuthenticated: user !== null,
    twoFactorChallenge,
    login,
    completeTwoFactor,
    logout,
    refreshUser,
    clearError,
    hasPermission,
    hasRole,
  };

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

import {
  createContext,
  useContext,
  useEffect,
  useState,
  useCallback,
  useMemo,
  ReactNode,
} from 'react';
import { useAuth } from './AuthContext';
import { apiFetch } from '@/lib/apiFetch';

const STORAGE_KEY = 'isaflow_active_company';

export interface Company {
  id: string;
  name: string;
  tradingName?: string;
  registrationNumber?: string;
  vatNumber?: string;
  taxNumber?: string;
  addressLine1?: string;
  addressLine2?: string;
  city?: string;
  province?: string;
  postalCode?: string;
  country?: string;
  phone?: string;
  email?: string;
  website?: string;
  logoUrl?: string;
  logoData?: string;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  financialYearStart?: number;
  vatPeriod?: string;
  vatSystemType?: 'invoice' | 'payment' | 'none';
  defaultCurrency?: string;
  isActive?: boolean;
}

export interface CompanyUser {
  companyId: string;
  companyName: string;
  role: string;
  isDefault: boolean;
}

interface CompanyContextType {
  activeCompany: Company | null;
  companies: CompanyUser[];
  loading: boolean;
  companyRole: string | null;
  switchCompany: (companyId: string) => Promise<void>;
}

const CompanyContext = createContext<CompanyContextType | undefined>(undefined);

export function CompanyProvider({ children }: { children: ReactNode }) {
  const { user, isAuthenticated } = useAuth();
  const [activeCompany, setActiveCompany] = useState<Company | null>(null);
  const [companies, setCompanies] = useState<CompanyUser[]>([]);
  const [loading, setLoading] = useState(true);
  const [companyRole, setCompanyRole] = useState<string | null>(null);

  const loadCompanyDetails = useCallback(async (companyId: string) => {
    try {
      const res = await apiFetch(`/api/accounting/companies?id=${companyId}`);
      if (res.ok) {
        const data = await res.json();
        const c = data.data;
        if (c) {
          const company: Company = {
            id: c.id,
            name: c.name,
            tradingName: c.trading_name || c.tradingName,
            registrationNumber: c.registration_number || c.registrationNumber,
            vatNumber: c.vat_number || c.vatNumber,
            taxNumber: c.tax_number || c.taxNumber,
            addressLine1: c.address_line1 || c.addressLine1,
            addressLine2: c.address_line2 || c.addressLine2,
            city: c.city,
            province: c.province,
            postalCode: c.postal_code || c.postalCode,
            country: c.country,
            phone: c.phone,
            email: c.email,
            website: c.website,
            logoUrl: c.logo_url || c.logoUrl,
            logoData: c.logo_data || c.logoData,
            bankName: c.bank_name || c.bankName,
            bankAccountNumber: c.bank_account_number || c.bankAccountNumber,
            bankBranchCode: c.bank_branch_code || c.bankBranchCode,
            bankAccountType: c.bank_account_type || c.bankAccountType,
            financialYearStart: c.financial_year_start || c.financialYearStart,
            vatPeriod: c.vat_period || c.vatPeriod,
            vatSystemType: c.vat_system_type || c.vatSystemType || 'none',
            defaultCurrency: c.default_currency || c.defaultCurrency,
            isActive: c.is_active ?? c.isActive ?? true,
          };
          setActiveCompany(company);
          localStorage.setItem(STORAGE_KEY, JSON.stringify({ id: company.id, name: company.name }));
          return company;
        }
      }
    } catch {
      // Failed to load company details
    }
    return null;
  }, []);

  const loadUserCompanies = useCallback(async () => {
    if (!isAuthenticated) {
      setLoading(false);
      return;
    }

    try {
      const res = await apiFetch('/api/accounting/companies?action=user-companies');

      if (!res.ok) {
        setLoading(false);
        return;
      }

      const data = await res.json();
      const raw = data.data?.items ?? data.data ?? [];
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const list: CompanyUser[] = (Array.isArray(raw) ? raw : []).map((c: any) => ({
        companyId: (c.companyId || c.company_id) as string,
        companyName: (c.companyName || c.company_name) as string,
        role: c.role as string,
        isDefault: Boolean(c.isDefault ?? c.is_default ?? false),
      }));

      setCompanies(list);

      if (list.length === 0) {
        // User has no companies — clear any stale localStorage
        localStorage.removeItem(STORAGE_KEY);
        setActiveCompany(null);
        setLoading(false);
        return;
      }

      // Determine which company to activate
      let targetId: string | null = null;

      // 1. Check localStorage
      try {
        const stored = localStorage.getItem(STORAGE_KEY);
        if (stored) {
          const { id } = JSON.parse(stored);
          if (id && list.some((c: CompanyUser) => c.companyId === id)) {
            targetId = id;
          }
        }
      } catch {
