/**
 * Document Validation API
 * POST /api/accounting/document-validation
 * Body: { entityType, entityId, documentId }
 * Validates VLM-extracted data against the entity record.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  validateInvoiceDocument,
  validatePaymentReceipt,
} from '@/modules/accounting/services/documentValidationService';
import type { ExtractedDocument } from '@/modules/accounting/types/documentCapture.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method || 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  const { entityType, entityId, documentId } = req.body as {
    entityType?: string;
    entityId?: string;
    documentId?: string;
  };

  if (!entityType || !entityId || !documentId) {
    return apiResponse.badRequest(res, 'entityType, entityId, and documentId are required');
  }

  // Fetch extracted data from document — scoped to company
  const [doc] = (await sql`
    SELECT extracted_data FROM procurement_documents
    WHERE id = ${documentId}::uuid AND company_id = ${companyId}::uuid
  `) as Row[];

  if (!doc?.extracted_data) {
    return apiResponse.badRequest(res, 'Document has no extracted data. VLM extraction may not have completed.');
  }

  const extracted = doc.extracted_data as ExtractedDocument;
  let result;

  if (entityType === 'supplier_invoice') {
    const [invoice] = (await sql`
      SELECT invoice_number, total_amount, tax_amount as vat_amount, tax_rate
      FROM supplier_invoices WHERE id = ${entityId}::uuid AND company_id = ${companyId}::uuid
    `) as Row[];
    if (!invoice) return apiResponse.notFound(res, 'Supplier invoice', entityId);

    // Get supplier name
    const [supplier] = (await sql`
      SELECT name FROM suppliers WHERE id = (
        SELECT supplier_id FROM supplier_invoices WHERE id = ${entityId}::uuid AND company_id = ${companyId}::uuid
      )
    `) as Row[];

    result = validateInvoiceDocument(extracted, {
      invoiceNumber: invoice.invoice_number,
      totalAmount: parseFloat(invoice.total_amount),
      vatAmount: invoice.vat_amount ? parseFloat(invoice.vat_amount) : undefined,
      taxRate: invoice.tax_rate ? parseFloat(invoice.tax_rate) : undefined,
      vendorName: supplier?.name,
    });
  } else if (entityType === 'customer_invoice') {
    const [invoice] = (await sql`
      SELECT invoice_number, total_amount, tax_amount, invoice_date
      FROM customer_invoices WHERE id = ${entityId}::uuid AND company_id = ${companyId}::uuid
    `) as Row[];
    if (!invoice) return apiResponse.notFound(res, 'Customer invoice', entityId);

    result = validateInvoiceDocument(extracted, {
      invoiceNumber: invoice.invoice_number,
      totalAmount: parseFloat(invoice.total_amount),
      vatAmount: invoice.tax_amount ? parseFloat(invoice.tax_amount) : undefined,
      invoiceDate: invoice.invoice_date ? new Date(invoice.invoice_date).toISOString().split('T')[0] : undefined,
    });
  } else if (entityType === 'supplier_payment' || entityType === 'customer_payment') {
    const [payment] = entityType === 'supplier_payment'
      ? (await sql`SELECT total_amount, payment_date, reference FROM supplier_payments WHERE id = ${entityId}::uuid AND company_id = ${companyId}::uuid`) as Row[]
      : (await sql`SELECT total_amount, payment_date, reference FROM customer_payments WHERE id = ${entityId}::uuid AND company_id = ${companyId}::uuid`) as Row[];
    if (!payment) return apiResponse.notFound(res, entityType, entityId);

    result = validatePaymentReceipt(extracted, {
      totalAmount: parseFloat(payment.total_amount),
      paymentDate: payment.payment_date ? new Date(payment.payment_date).toISOString().split('T')[0] : undefined,
      reference: payment.reference,
    });
  } else {
    return apiResponse.badRequest(res, `Unsupported entity type: ${entityType}`);
  }

  // Store validation result
  // @ts-expect-error — auth middleware attaches user
  const userId: string | null = req.user?.id ?? null;

  await sql`
    INSERT INTO document_validation_results (
      company_id, document_id, entity_type, entity_id,
      validation_type, result_data, discrepancy_count, validated_by
    ) VALUES (
      ${companyId}::uuid, ${documentId}::uuid, ${entityType}, ${entityId}::uuid,
      'vlm_document_match', ${JSON.stringify(result)}::jsonb,
      ${result.discrepancies.length}, ${userId}
    )
  `;

  log.info('Document validation completed', {
    entityType,
    entityId,
    documentId,
    valid: result.valid,
    discrepancies: result.discrepancies.length,
  }, 'document-validation');

  return apiResponse.success(res, result);
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Manual Bank Transaction API — Spend Money / Receive Money
 * POST /api/accounting/bank-transactions-manual
 * Equivalent to Sage "Create Transaction" in Process Bank.
 *
 * Inserts a bank_transaction record and immediately allocates it
 * via the existing allocateTransaction service.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  type AllocationType,
} from '@/modules/accounting/services/bankReconciliationService';

// ── Types ─────────────────────────────────────────────────────────────────────

interface ManualTxBody {
  type: 'spend' | 'receive';
  bankAccountId: string;
  date: string;
  amount: number | string;
  reference?: string;
  description?: string;
  allocationType: AllocationType;
  /** GL account ID (when allocationType === 'account') */
  contraAccountId?: string;
  /** Supplier or Customer ID (when allocationType is supplier/customer) */
  entityId?: string;
  vatCode?: string;
}

// ── Handler ───────────────────────────────────────────────────────────────────

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const { companyId } = req as CompanyApiRequest;
  // @ts-expect-error — auth middleware attaches user
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  const body = req.body as ManualTxBody;
  const {
    type,
    bankAccountId,
    date,
    amount: rawAmount,
    reference,
    description,
    allocationType,
    contraAccountId,
    entityId,
    vatCode,
  } = body;

  // ── Validation ─────────────────────────────────────────────────────────────

  if (!type || (type !== 'spend' && type !== 'receive')) {
    return apiResponse.badRequest(res, "type must be 'spend' or 'receive'");
  }
  if (!bankAccountId) {
    return apiResponse.badRequest(res, 'bankAccountId is required');
  }
  if (!date) {
    return apiResponse.badRequest(res, 'date is required');
  }
  const numericAmount = Number(rawAmount);
  if (!rawAmount || isNaN(numericAmount) || numericAmount <= 0) {
    return apiResponse.badRequest(res, 'amount must be a positive number');
  }
  if (!allocationType) {
    return apiResponse.badRequest(res, 'allocationType is required');
  }
  if (allocationType === 'account' && !contraAccountId) {
    return apiResponse.badRequest(res, 'contraAccountId is required when allocationType is account');
  }
  if ((allocationType === 'supplier' || allocationType === 'customer') && !entityId) {
    return apiResponse.badRequest(res, 'entityId is required when allocationType is supplier or customer');
  }

  // ── Amount sign — negative for spend, positive for receive ─────────────────

  const signedAmount = type === 'spend' ? -Math.abs(numericAmount) : Math.abs(numericAmount);

  try {
    // ── Step 1: Insert bank_transactions row ─────────────────────────────────

    const txRows = await sql`
      INSERT INTO bank_transactions (
        bank_account_id,
        transaction_date,
        amount,
        description,
        reference,
        status,
        company_id
      ) VALUES (
        ${bankAccountId}::UUID,
        ${date}::DATE,
        ${signedAmount},
        ${description ?? null},
        ${reference ?? null},
        'imported',
        ${companyId}
      )
      RETURNING id
    `;

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const txId = String((txRows as any[])[0]!.id);

    log.info('Manual bank transaction created', {
      txId, type, bankAccountId, amount: signedAmount, date,
    }, 'accounting-api');

    // ── Step 2: Immediately allocate the transaction ──────────────────────────

    const result = await allocateTransaction(
      companyId,
      txId,
      contraAccountId ?? '',
      userId,
      description,
      allocationType,
      entityId,
      vatCode,
    );

    log.info('Manual bank transaction allocated', {
      txId, journalEntryId: result.journalEntryId,
    }, 'accounting-api');

    return apiResponse.created(res, {
      bankTransactionId: txId,
      journalEntryId: result.journalEntryId,
      bankTransaction: result.bankTransaction,
    }, 'Transaction recorded and allocated successfully');
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Failed to record transaction';
    log.error('Manual bank transaction failed', { error: err }, 'accounting-api');
    return apiResponse.internalError(res, err, message);
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withCompany(withErrorHandler(handler));

/**
 * Bank Match Confirm API
 * POST /api/accounting/bank-match-confirm
 * Body: { bankTransactionId, candidateType, candidateId }
 *
 * Confirms a manual match selection from the FindMatchModal.
 * Creates proper double-entry journal entries and handles partial payments:
 *
 * Customer invoice (receipt):  DR Bank, CR Accounts Receivable
 * Supplier invoice (payment):  DR Accounts Payable, CR Bank
 * Purchase order (payment):    DR Accounts Payable, CR Bank
 * Journal line:                Direct match to existing GL entry
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { log } from '@/lib/logger';
import { sql } from '@/lib/neon';
import {
  allocateTransaction,
  matchTransaction,
} from '@/modules/accounting/services/bankReconciliationService';
import type { CandidateType } from '@/modules/accounting/types/bank-match.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'UNKNOWN', ['POST']);
  }

  const {
    bankTransactionId,
    candidateType,
    candidateId,
  } = req.body as {
    bankTransactionId?: string;
    candidateType?: CandidateType;
    candidateId?: string;
  };

  const { companyId } = req as CompanyApiRequest;
  // @ts-expect-error — auth middleware attaches user
  const userId: string = req.user?.id ?? req.user?.userId ?? 'system';

  if (!bankTransactionId) return apiResponse.badRequest(res, 'bankTransactionId is required');
  if (!candidateType) return apiResponse.badRequest(res, 'candidateType is required');
  if (!candidateId) return apiResponse.badRequest(res, 'candidateId is required');

  const validTypes: CandidateType[] = ['supplier_invoice', 'customer_invoice', 'purchase_order', 'journal_line'];
  if (!validTypes.includes(candidateType)) {
    return apiResponse.badRequest(res, `candidateType must be one of: ${validTypes.join(', ')}`);
  }

  try {
    // Get the bank transaction amount for partial payment calculations
    const txRows = (await sql`
      SELECT amount FROM bank_transactions WHERE id = ${bankTransactionId}::UUID AND company_id = ${companyId}
    `) as Row[];
    if (txRows.length === 0) {
      return apiResponse.notFound(res, 'Bank transaction', bankTransactionId);
    }
    const paymentAmount = Math.abs(Number(txRows[0]!.amount));

    if (candidateType === 'supplier_invoice') {
      const invRows = (await sql`
        SELECT id, supplier_id, total_amount, amount_paid, balance
        FROM supplier_invoices WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (invRows.length === 0) {
        return apiResponse.notFound(res, 'Supplier invoice', candidateId);
      }
      const inv = invRows[0]!;
      const supplierId = String(inv.supplier_id);
      const currentPaid = Number(inv.amount_paid || 0);
      const invoiceTotal = Number(inv.total_amount);
      const outstandingBalance = invoiceTotal - currentPaid;

      // Create GL entry: DR Accounts Payable, CR Bank
      await allocateTransaction(
        companyId, bankTransactionId, '', userId, undefined, 'supplier', supplierId,
      );

      // Update invoice payment tracking
      const newPaid = currentPaid + Math.min(paymentAmount, outstandingBalance);
      const newBalance = invoiceTotal - newPaid;
      const newStatus = newBalance <= 0.01 ? 'paid' : 'partially_paid';

      await sql`
        UPDATE supplier_invoices
        SET amount_paid = ${newPaid}::NUMERIC,
            balance = ${newBalance}::NUMERIC,
            status = ${newStatus},
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: supplier invoice', {
        bankTransactionId, candidateId,
        paymentAmount, outstandingBalance, newStatus,
      }, 'accounting-api');

    } else if (candidateType === 'customer_invoice') {
      const ciRows = (await sql`
        SELECT id, customer_id, total_amount, amount_paid
        FROM customer_invoices WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (ciRows.length === 0) {
        return apiResponse.notFound(res, 'Customer invoice', candidateId);
      }
      const ci = ciRows[0]!;
      const customerId = String(ci.customer_id);
      const currentPaid = Number(ci.amount_paid || 0);
      const invoiceTotal = Number(ci.total_amount);
      const outstandingBalance = invoiceTotal - currentPaid;

      // Create GL entry: DR Bank, CR Accounts Receivable
      await allocateTransaction(
        companyId, bankTransactionId, '', userId, undefined, 'customer', customerId,
      );

      // Update invoice payment tracking
      const newPaid = currentPaid + Math.min(paymentAmount, outstandingBalance);
      const newStatus = (newPaid >= invoiceTotal - 0.01) ? 'paid' : 'partially_paid';

      await sql`
        UPDATE customer_invoices
        SET amount_paid = ${newPaid}::NUMERIC,
            status = ${newStatus},
            paid_at = ${newStatus === 'paid' ? new Date().toISOString() : null},
            updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: customer invoice', {
        bankTransactionId, candidateId,
        paymentAmount, outstandingBalance, newStatus,
      }, 'accounting-api');

    } else if (candidateType === 'purchase_order') {
      const poRows = (await sql`
        SELECT id, supplier_id, total FROM purchase_orders WHERE id = ${candidateId}::UUID AND company_id = ${companyId}
      `) as Row[];
      if (poRows.length === 0) {
        return apiResponse.notFound(res, 'Purchase order', candidateId);
      }
      const supplierId = String(poRows[0]!.supplier_id);

      // Create GL entry: DR Accounts Payable, CR Bank
      await allocateTransaction(
        companyId, bankTransactionId, '', userId, undefined, 'supplier', supplierId,
      );

      await sql`
        UPDATE purchase_orders SET status = 'paid', updated_at = NOW()
        WHERE id = ${candidateId}::UUID
      `;

      log.info('Confirmed match: purchase order', { bankTransactionId, candidateId }, 'accounting-api');

    } else {
      // journal_line — match to existing GL entry
      await matchTransaction(companyId, bankTransactionId, candidateId);
      log.info('Confirmed match: journal line', { bankTransactionId, candidateId }, 'accounting-api');
    }

    return apiResponse.success(res, { matched: true, candidateType, candidateId });
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Match confirmation failed';
    log.error('Failed to confirm bank match', { bankTransactionId, candidateType, candidateId, error: err }, 'accounting-api');
    return apiResponse.badRequest(res, message);
  }
}

