/**
 * Admin Middleware
 * Convenience wrapper: withAuth + withRole('super_admin') + withErrorHandler
 * All admin API routes must be wrapped with this.
 */

import { withAuth, withRole, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { withErrorHandler } from '@/lib/api-error-handler';
import type { NextApiHandler, NextApiResponse } from 'next';

/**
 * Wraps a handler with:
 * 1. JWT authentication (withAuth)
 * 2. super_admin role enforcement (withRole)
 * 3. Structured error handling (withErrorHandler)
 *
 * Usage:
 *   export default withAdmin(async (req, res) => { ... });
 */
export function withAdmin(
  handler: (req: AuthenticatedNextApiRequest, res: NextApiResponse) => Promise<void>
): NextApiHandler {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const errorWrapped = withErrorHandler(handler as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const roleWrapped = withRole('super_admin')(errorWrapped as any);
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  return withAuth(roleWrapped as any) as NextApiHandler;
}

/**
 * In-memory rate limiter using LRU cache with TTL
 */

import { LRUCache } from 'lru-cache';
import type { NextApiRequest, NextApiResponse } from 'next';
import { log } from '@/lib/logger';

interface RateLimitOptions {
  windowMs?: number;    // time window in ms (default 15 min)
  maxRequests?: number; // max requests per window (default 5)
}

// Each cache entry tracks hit count within the TTL window
const caches = new Map<string, LRUCache<string, number>>();

function getCache(windowMs: number): LRUCache<string, number> {
  const key = String(windowMs);
  if (!caches.has(key)) {
    caches.set(key, new LRUCache<string, number>({
      max: 10_000,
      ttl: windowMs,
    }));
  }
  return caches.get(key)!;
}

/**
 * Returns true if the key is rate limited, false if the request is allowed.
 */
export function checkRateLimit(key: string, opts?: RateLimitOptions): boolean {
  const windowMs = opts?.windowMs ?? 15 * 60 * 1000;
  const maxRequests = opts?.maxRequests ?? 5;

  const cache = getCache(windowMs);
  const current = cache.get(key) ?? 0;

  if (current >= maxRequests) {
    return true; // rate limited
  }

  cache.set(key, current + 1);
  return false;
}

function getClientIp(req: NextApiRequest): string {
  const forwarded = req.headers['x-forwarded-for'];
  if (Array.isArray(forwarded)) return forwarded[0] ?? 'unknown';
  if (typeof forwarded === 'string') return forwarded.split(',')[0]?.trim() ?? 'unknown';
  return req.socket.remoteAddress ?? 'unknown';
}

/**
 * Middleware wrapper that applies rate limiting per IP before the handler runs.
 */
export function withRateLimit(
  handler: (req: NextApiRequest, res: NextApiResponse) => Promise<void> | void,
  opts?: RateLimitOptions
) {
  return async (req: NextApiRequest, res: NextApiResponse): Promise<void> => {
    const ip = getClientIp(req);
    const limited = checkRateLimit(ip, opts);

    if (limited) {
      log.warn('Rate limit exceeded', { ip }, 'rateLimit');
      res.status(429).json({
        success: false,
        error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
      });
      return;
    }

    return handler(req, res);
  };
}

/**
 * Trend Analysis API
 * GET /api/accounting/reports-trend-analysis?metric=revenue|expenses|netProfit|cash&months=6
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withCompany, type CompanyApiRequest } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { analyzeTrend } from '@/modules/accounting/services/trendAnalysisService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

const METRIC_QUERIES: Record<string, string> = {
  revenue: "SUM(CASE WHEN ga.account_code LIKE '4%' THEN jl.credit - jl.debit ELSE 0 END)",
  expenses: "SUM(CASE WHEN ga.account_code LIKE '5%' THEN jl.debit - jl.credit ELSE 0 END)",
  netProfit: "SUM(CASE WHEN ga.account_code LIKE '4%' THEN jl.credit - jl.debit WHEN ga.account_code LIKE '5%' THEN -(jl.debit - jl.credit) ELSE 0 END)",
};

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'GET') return apiResponse.methodNotAllowed(res, req.method || '', ['GET']);

  const { companyId } = req as CompanyApiRequest;
  const metric = (req.query.metric as string) || 'revenue';
  const months = Math.min(12, Math.max(3, parseInt(String(req.query.months || '6'), 10)));

  const now = new Date();
  const dataPoints: Array<{ period: string; value: number }> = [];

  for (let i = months - 1; i >= 0; i--) {
    const date = new Date(now.getFullYear(), now.getMonth() - i, 1);
    const from = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-01`;
    const lastDay = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    const to = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${lastDay}`;
    const label = date.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });

    let value = 0;

    if (metric === 'cash') {
      const [r] = (await sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) as val
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.company_id = ${companyId} AND je.status = 'posted'
          AND ga.account_code = '1110' AND je.entry_date <= ${to}::date
      `) as Row[];
      value = parseFloat(r?.val || '0');
    } else {
      const [r] = (await sql`
        SELECT
          COALESCE(SUM(CASE WHEN ga.account_code LIKE '4%' THEN jl.credit - jl.debit ELSE 0 END), 0) as revenue,
          COALESCE(SUM(CASE WHEN ga.account_code LIKE '5%' THEN jl.debit - jl.credit ELSE 0 END), 0) as expenses
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.company_id = ${companyId} AND je.status = 'posted'
          AND je.entry_date >= ${from}::date AND je.entry_date <= ${to}::date
      `) as Row[];

      if (metric === 'revenue') value = parseFloat(r?.revenue || '0');
      else if (metric === 'expenses') value = parseFloat(r?.expenses || '0');
      else if (metric === 'netProfit') value = parseFloat(r?.revenue || '0') - parseFloat(r?.expenses || '0');
    }

    dataPoints.push({ period: label, value: Math.round(value * 100) / 100 });
  }

  const analysis = analyzeTrend(dataPoints);

  return apiResponse.success(res, { metric, months, analysis });
}

