/**
 * RecentActivityWidget — Last 5 journal entries from /api/accounting/dashboard-stats.
 * // WORKING: Uses recentJournals from dashboard-stats, no extra endpoint needed.
 */

import { useEffect, useState } from 'react';
import { Clock, FileSpreadsheet } from 'lucide-react';
import { Card } from '@/components/ui/Card';
import { Skeleton } from '@/components/ui/Skeleton';
import { Badge } from '@/components/ui/Badge';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';

interface JournalEntry {
  id: string;
  date: string | Date;
  description: string;
  source: string;
  status: string;
  amount: number;
}

function formatDate(val: string | Date): string {
  const d = typeof val === 'string' ? new Date(val) : val;
  return d.toLocaleDateString('en-ZA', { day: '2-digit', month: 'short' });
}

function fmtCurrency(n: number): string {
  return 'R\u00a0' + new Intl.NumberFormat('en-ZA', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(n);
}

const STATUS_VARIANT: Record<string, 'success' | 'warning' | 'default'> = {
  posted: 'success',
  draft: 'warning',
};

export function RecentActivityWidget() {
  const [entries, setEntries] = useState<JournalEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    async function load() {
      try {
        const res = await apiFetch('/api/accounting/dashboard-stats');
        const json = (await res.json()) as { data?: { recentJournals?: JournalEntry[] } };
        const d = json.data ?? {};
        setEntries(d.recentJournals ?? []);
      } catch (err) {
        log.error('RecentActivityWidget fetch failed', { error: err }, 'dashboard-widget');
        setError('Unable to load recent activity');
      } finally {
        setLoading(false);
      }
    }
    void load();
  }, []);

  return (
    <Card
      header={
        <div className="flex items-center gap-2">
          <Clock className="h-4 w-4 text-teal-500" />
          <span className="text-sm font-semibold text-gray-900 dark:text-gray-100">Recent Activity</span>
        </div>
      }
      noPadding
    >
      {loading ? (
        <div className="p-4 space-y-3">
          {[1, 2, 3].map(i => <Skeleton key={i} variant="table-row" />)}
        </div>
      ) : error ? (
        <p className="p-4 text-sm text-red-500">{error}</p>
      ) : entries.length === 0 ? (
        <p className="p-4 text-sm text-gray-500 dark:text-gray-400">No recent journal entries.</p>
      ) : (
        <div className="divide-y divide-gray-100 dark:divide-gray-700">
          {entries.map(entry => (
            <div key={entry.id} className="px-4 py-3 flex items-start gap-3">
              <div className="mt-0.5 flex-shrink-0 p-1.5 rounded-md bg-gray-100 dark:bg-gray-800">
                <FileSpreadsheet className="h-3.5 w-3.5 text-gray-500 dark:text-gray-400" />
              </div>
              <div className="min-w-0 flex-1">
                <p className="text-xs font-medium text-gray-900 dark:text-gray-100 truncate">
                  {entry.description || entry.source || 'Journal Entry'}
                </p>
                <div className="flex items-center gap-2 mt-0.5">
                  <span className="text-xs text-gray-500 dark:text-gray-400">{formatDate(entry.date)}</span>
                  <Badge variant={STATUS_VARIANT[entry.status] ?? 'default'} size="sm">
                    {entry.status}
                  </Badge>
                </div>
              </div>
              <span className="text-xs font-medium text-gray-700 dark:text-gray-300 flex-shrink-0">
                {fmtCurrency(entry.amount)}
              </span>
            </div>
          ))}
        </div>
      )}
    </Card>
  );
}

/**
 * Two-Factor Authentication section for My Account > Security tab.
 * Handles: status display, setup flow (QR + verify), backup codes, trusted devices.
 */

import { useState, useEffect } from 'react';
import Image from 'next/image';
import { ShieldCheck, ShieldOff, Smartphone, Trash2, Loader2, RefreshCw, Copy, Check } from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';
import toast from 'react-hot-toast';
import { SECTION_CLS, LABEL_CLS, INPUT_CLS } from './AccountTabs';

// ── Types ─────────────────────────────────────────────────────────────────────

interface TwoFAStatus {
  enabled: boolean;
  method: string | null;
  verifiedAt: string | null;
}

interface TrustedDevice {
  id: string;
  deviceName: string | null;
  deviceFingerprint: string;
  trustedUntil: string;
  lastUsedAt: string;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

type SetupStep = 'idle' | 'qr' | 'verify' | 'backup' | 'disable';

function formatDate(iso: string | null): string {
  if (!iso) return 'Unknown';
  return new Date(iso).toLocaleDateString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
}

// ── Backup Codes Display ──────────────────────────────────────────────────────

function BackupCodesDisplay({ codes, onDone }: { codes: string[]; onDone: () => void }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    void navigator.clipboard.writeText(codes.join('\n'));
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="space-y-4">
      <div className="p-4 bg-amber-500/10 border border-amber-500/30 rounded-lg">
        <p className="text-sm font-medium text-amber-400">Save these backup codes now</p>
        <p className="text-xs text-amber-300 mt-1">
          Each code can only be used once. Store them somewhere safe — they will not be shown again.
        </p>
      </div>

      <div className="grid grid-cols-2 gap-2">
        {codes.map((code) => (
          <div key={code} className="font-mono text-sm text-center py-2 px-3 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg text-[var(--ff-text-primary)] tracking-wider">
            {code}
          </div>
        ))}
      </div>

      <div className="flex gap-2">
        <button
          onClick={handleCopy}
          className="flex items-center gap-2 px-3 py-2 text-sm border border-[var(--ff-border-primary)] rounded-lg text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
        >
          {copied ? <Check className="h-4 w-4 text-teal-500" /> : <Copy className="h-4 w-4" />}
          {copied ? 'Copied' : 'Copy All'}
        </button>
        <button
          onClick={onDone}
          className="flex-1 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors"
        >
          I have saved my backup codes
        </button>
      </div>
    </div>
  );
}

// ── Main Component ────────────────────────────────────────────────────────────

export function TwoFactorSection() {
  const [status, setStatus] = useState<TwoFAStatus | null>(null);
  const [devices, setDevices] = useState<TrustedDevice[]>([]);
  const [step, setStep] = useState<SetupStep>('idle');
  const [qrData, setQrData] = useState<{ qrCodeDataUrl: string; uri: string } | null>(null);
  const [backupCodes, setBackupCodes] = useState<string[]>([]);
  const [verifyCode, setVerifyCode] = useState('');
  const [disableCode, setDisableCode] = useState('');
  const [loading, setLoading] = useState(false);
  const [statusLoading, setStatusLoading] = useState(true);

  useEffect(() => {
    void loadStatus();
    void loadDevices();
  }, []);

  async function loadStatus() {
    setStatusLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-status');
      const json = await res.json();
      if (json.success) setStatus(json.data as TwoFAStatus);
    } catch {
      toast.error('Failed to load 2FA status');
    } finally {
      setStatusLoading(false);
    }
  }

  async function loadDevices() {
    try {
      const res = await apiFetch('/api/auth/2fa-trusted-devices');
      const json = await res.json();
      if (json.success) setDevices((json.data?.devices ?? []) as TrustedDevice[]);
    } catch {
      // Non-critical — silently ignore
    }
  }

  // ── Setup Flow ─────────────────────────────────────────────────────────────

  async function handleStartSetup() {
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-setup', { method: 'POST' });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Failed to start setup');
        return;
      }
      setQrData({ qrCodeDataUrl: json.data.qrCodeDataUrl as string, uri: json.data.uri as string });
      setVerifyCode('');
      setStep('qr');
    } catch {
      toast.error('Failed to start 2FA setup');
    } finally {
      setLoading(false);
    }
  }

  async function handleVerifySetup() {
    if (!verifyCode.trim()) return;
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-verify-setup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: verifyCode.trim() }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Invalid code');
        return;
      }
      setBackupCodes((json.data?.backupCodes as string[]) ?? []);
      setStep('backup');
      await loadStatus();
    } catch {
      toast.error('Verification failed');
    } finally {
      setLoading(false);
    }
  }

  // ── Disable Flow ───────────────────────────────────────────────────────────

  async function handleDisable() {
    if (!disableCode.trim()) return;
    setLoading(true);
    try {
      const res = await apiFetch('/api/auth/2fa-disable', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code: disableCode.trim() }),
      });
      const json = await res.json();
      if (!res.ok) {
        toast.error(json.error?.message ?? 'Invalid code');
        return;
      }
      toast.success('2FA disabled');
      setDisableCode('');
      setStep('idle');
      await loadStatus();
    } catch {
      toast.error('Failed to disable 2FA');
    } finally {
      setLoading(false);
    }
  }

  // ── Remove Device ──────────────────────────────────────────────────────────

  async function handleRemoveDevice(deviceId: string) {
    try {
      const res = await apiFetch(`/api/auth/2fa-trusted-devices?id=${deviceId}`, { method: 'DELETE' });
      if (!res.ok) {
        toast.error('Failed to remove device');
        return;
      }
      toast.success('Device removed');
      void loadDevices();
    } catch {
      toast.error('Failed to remove device');
    }
  }

  // ── Render ─────────────────────────────────────────────────────────────────

  if (statusLoading) {
    return (
      <section className={SECTION_CLS}>
        <div className="flex justify-center py-8">
          <Loader2 className="h-6 w-6 animate-spin text-teal-500" />
        </div>
      </section>
    );
  }

  const enabled = status?.enabled ?? false;

  return (
    <div className="space-y-6">

      {/* Status Card */}
      <section className={SECTION_CLS}>
        <div className="flex items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            <div className={`p-2 rounded-lg ${enabled ? 'bg-teal-500/10' : 'bg-gray-500/10'}`}>
              {enabled
                ? <ShieldCheck className="h-6 w-6 text-teal-500" />
                : <ShieldOff className="h-6 w-6 text-gray-400" />
              }
            </div>
            <div>
              <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                Two-Factor Authentication
              </h2>
              <p className="text-sm text-[var(--ff-text-secondary)] mt-0.5">
                {enabled
                  ? `Enabled via authenticator app${status?.verifiedAt ? ` since ${formatDate(status.verifiedAt)}` : ''}`
                  : 'Add an extra layer of security to your account'
                }
              </p>
            </div>
          </div>

          <div className="flex gap-2 flex-shrink-0">
            {enabled && step === 'idle' && (
              <button
                onClick={() => setStep('disable')}
                className="px-3 py-1.5 text-sm text-red-400 border border-red-400/30 rounded-lg hover:bg-red-400/10 transition-colors"
              >
                Disable
              </button>
            )}
            {!enabled && step === 'idle' && (
              <button
                onClick={() => void handleStartSetup()}
                disabled={loading}
                className="flex items-center gap-2 px-3 py-1.5 text-sm bg-teal-600 hover:bg-teal-700 text-white rounded-lg transition-colors disabled:opacity-50"
              >
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                Enable 2FA
              </button>
            )}
            {(step === 'qr' || step === 'verify') && (
              <button
                onClick={() => { setStep('idle'); setQrData(null); }}
                className="px-3 py-1.5 text-sm text-[var(--ff-text-secondary)] border border-[var(--ff-border-primary)] rounded-lg hover:text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
            )}
          </div>
        </div>

        {/* QR Code Step */}
        {step === 'qr' && qrData && (
          <div className="mt-6 space-y-4">
            <div className="p-4 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg">
              <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-3">
                1. Scan this QR code with your authenticator app
              </p>
              <div className="flex justify-center">
                <Image src={qrData.qrCodeDataUrl} alt="2FA QR Code" className="rounded-lg" width={200} height={200} unoptimized />
              </div>
              <p className="text-xs text-[var(--ff-text-secondary)] mt-3 text-center">
                Supported apps: Google Authenticator, Microsoft Authenticator, Authy
              </p>
            </div>

            <div>
              <p className="text-sm font-medium text-[var(--ff-text-primary)] mb-2">
                2. Enter the 6-digit code shown in your app
              </p>
              <div className="flex gap-2">
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={verifyCode}
                  onChange={e => setVerifyCode(e.target.value.replace(/\D/g, ''))}
                  placeholder="000000"
                  className={INPUT_CLS + ' font-mono tracking-widest text-center'}
                />
                <button
                  onClick={() => void handleVerifySetup()}
                  disabled={loading || verifyCode.length < 6}
                  className="flex items-center gap-2 px-4 py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 whitespace-nowrap"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  Verify & Enable
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Backup Codes Step */}
        {step === 'backup' && (
          <div className="mt-6">
            <BackupCodesDisplay codes={backupCodes} onDone={() => { setStep('idle'); setBackupCodes([]); }} />
          </div>
        )}

        {/* Disable Step */}
        {step === 'disable' && (
          <div className="mt-6 space-y-4">
            <div className="p-4 bg-red-500/10 border border-red-500/30 rounded-lg">
              <p className="text-sm text-red-400">
                Enter your current authenticator code to disable 2FA.
                This will remove the extra security layer from your account.
              </p>
            </div>
            <div>
              <label className={LABEL_CLS}>Authentication Code</label>
              <div className="flex gap-2">
                <input
                  type="text"
                  inputMode="numeric"
                  maxLength={6}
                  value={disableCode}
                  onChange={e => setDisableCode(e.target.value.replace(/\D/g, ''))}
                  placeholder="000000"
                  className={INPUT_CLS + ' font-mono tracking-widest text-center'}
                />
                <button
                  onClick={() => void handleDisable()}
                  disabled={loading || disableCode.length < 6}
                  className="flex items-center gap-2 px-4 py-2 bg-red-600 hover:bg-red-700 text-white rounded-lg text-sm font-medium transition-colors disabled:opacity-50 whitespace-nowrap"
                >
                  {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
                  Disable 2FA
                </button>
              </div>
            </div>
            <button
              onClick={() => { setStep('idle'); setDisableCode(''); }}
              className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
            >
              Cancel
            </button>
          </div>
        )}
      </section>

      {/* Trusted Devices */}
      {enabled && devices.length > 0 && (
        <section className={SECTION_CLS}>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-base font-semibold text-[var(--ff-text-primary)]">
              Trusted Devices
            </h2>
            <button
              onClick={() => void loadDevices()}
              className="text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
              title="Refresh"
            >
              <RefreshCw className="h-4 w-4" />
            </button>
          </div>

          <div className="space-y-2">
            {devices.map(device => (
              <div
                key={device.id}
                className="flex items-center justify-between gap-4 p-3 bg-[var(--ff-bg-primary)] border border-[var(--ff-border-primary)] rounded-lg"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <Smartphone className="h-4 w-4 text-[var(--ff-text-secondary)] flex-shrink-0" />
                  <div className="min-w-0">
                    <p className="text-sm font-medium text-[var(--ff-text-primary)] truncate">
                      {device.deviceName ?? 'Unknown Device'}
                    </p>
                    <p className="text-xs text-[var(--ff-text-secondary)]">
                      Trusted until {formatDate(device.trustedUntil)}
                      {' · '}Last used {formatDate(device.lastUsedAt)}
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => void handleRemoveDevice(device.id)}
                  className="text-red-400 hover:text-red-300 transition-colors flex-shrink-0"
                  title="Remove device"
                >
                  <Trash2 className="h-4 w-4" />
                </button>
              </div>
            ))}
          </div>
        </section>
      )}

    </div>
  );
}

/**
 * EFT File Generation Service — South African Bank Formats
 * Generates payment files for: Standard Bank, FNB, ABSA, Nedbank, Capitec
 * Pure business logic — no database dependencies.
 */

export interface EFTPayment {
  beneficiaryName: string;
  beneficiaryAccountNumber: string;
  beneficiaryBranchCode: string;
  beneficiaryAccountType: 'current' | 'savings' | 'transmission';
  amount: number;
  reference: string;
  beneficiaryBank?: string;
}

export interface EFTBatchHeader {
  companyName: string;
  bankAccountNumber: string;
  branchCode: string;
  accountType: 'current' | 'savings';
  batchReference: string;
  actionDate: string; // YYYY-MM-DD
}

export interface EFTValidationResult {
  valid: boolean;
  errors: string[];
  totalAmount: number;
  paymentCount: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// FORMATTING UTILITIES
// ═══════════════════════════════════════════════════════════════════════════

export function formatEFTAmount(amount: number): string {
  return String(Math.round(amount * 100));
}

export function padRight(str: string, length: number): string {
  return str.substring(0, length).padEnd(length, ' ');
}

export function padLeft(str: string, length: number): string {
  const s = String(str);
  return s.length > length ? s.substring(s.length - length) : s.padStart(length, '0');
}

function formatDate(dateStr: string): string {
  return dateStr.replace(/-/g, '').substring(2); // YYMMDD
}

function accountTypeCode(type: string): string {
  switch (type) {
    case 'current': return '1';
    case 'savings': return '2';
    case 'transmission': return '3';
    default: return '1';
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// VALIDATION
// ═════════════════════���═════════════════════════════════════════════════════

export function validateBankAccount(accountNumber: string, branchCode: string): { valid: boolean; error?: string } {
  if (!accountNumber || accountNumber.trim() === '') return { valid: false, error: 'Account number is required' };
  if (!branchCode || branchCode.trim() === '') return { valid: false, error: 'Branch code is required' };
  if (!/^\d+$/.test(accountNumber)) return { valid: false, error: 'Account number must contain only digits' };
  if (!/^\d{6}$/.test(branchCode)) return { valid: false, error: 'Branch code must be exactly 6 digits' };
  return { valid: true };
}

export function validateEFTBatch(header: EFTBatchHeader, payments: EFTPayment[]): EFTValidationResult {
  const errors: string[] = [];

  if (!payments || payments.length === 0) {
    errors.push('At least one payment is required');
    return { valid: false, errors, totalAmount: 0, paymentCount: 0 };
  }

  let totalAmount = 0;
  for (let i = 0; i < payments.length; i++) {
    const p = payments[i]!;
    if (!p.beneficiaryName || p.beneficiaryName.trim() === '') errors.push(`Payment ${i + 1}: Beneficiary name is required`);
    if (!p.beneficiaryAccountNumber || p.beneficiaryAccountNumber.trim() === '') errors.push(`Payment ${i + 1}: Account number is required`);
    if (!p.amount || p.amount <= 0) errors.push(`Payment ${i + 1}: Amount must be greater than zero`);
    totalAmount += p.amount || 0;
  }

  totalAmount = Math.round(totalAmount * 100) / 100;
  return { valid: errors.length === 0, errors, totalAmount, paymentCount: payments.length };
}

// ═════════════════════════════════════════════════════���═════════════════════
// STANDARD BANK ACB FORMAT
// ══════��═══════════════════════════════════════════════════════��════════════

export function generateStandardBankACB(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  // Header record
  lines.push(
    'H' +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    padRight(header.companyName, 30) +
    date +
    padRight(header.batchReference, 20) +
    padLeft(String(payments.length), 6)
  );

  // Transaction records
  for (const p of payments) {
    lines.push(
      'T' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 20)
    );
  }

  // Trailer record
  lines.push(
    'Z' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 62)
  );

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// FNB EFT FORMAT
// ═══════════════════════════════════════════════════════════���═══════════════

export function generateFNBEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  // Header
  lines.push(
    'EFT' +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    date +
    padRight(header.companyName, 30) +
    padRight(header.batchReference, 12)
  );

  // Transactions
  for (const p of payments) {
    lines.push(
      'STD' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 12)
    );
  }

  // Trailer
  lines.push(
    'END' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 50)
  );

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// ABSA EFT FORMAT
// ════════════════════════��════════════════════════════��═════════════════════

export function generateABSAEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  lines.push(
    '04' + date +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    padRight(header.companyName, 30) +
    padRight(header.batchReference, 12)
  );

  for (const p of payments) {
    lines.push(
      '50' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 12)
    );
  }

  lines.push(
    '92' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 50)
  );

  return lines.join('\n');
}

// ═══════════════════════════════���═══════════════════════════════════════════
// NEDBANK EFT FORMAT
// ══��═══════════════════════════════════════════════════════════════���════════

export function generateNedbankEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  lines.push(
    'HDR' +
    date +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    padRight(header.companyName, 30) +
    padRight(header.batchReference, 12)
  );

  for (const p of payments) {
    lines.push(
      'TXN' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 12)
    );
  }

  lines.push(
    'TRL' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 50)
  );

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════��═══════════════
// CAPITEC EFT FORMAT
// ═══════════════════��════════════════════════════════════���══════════════════

export function generateCapitecEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  lines.push(
    'H,' + date + ',' +
    header.branchCode + ',' +
    header.bankAccountNumber + ',' +
    header.companyName + ',' +
    header.batchReference
  );

  for (const p of payments) {
    lines.push(
      'T,' +
      p.beneficiaryBranchCode + ',' +
      p.beneficiaryAccountNumber + ',' +
      accountTypeCode(p.beneficiaryAccountType) + ',' +
      formatEFTAmount(p.amount) + ',' +
      p.beneficiaryName + ',' +
      p.reference
    );
  }

  lines.push(
    'Z,' + payments.length + ',' + totalCents
  );

  return lines.join('\n');
}

/**
 * BankTxAttachmentsModal
 *
 * View, upload, and delete file attachments (receipts, invoices, PDFs) for a
 * single bank transaction. Files are stored as base64 data URLs in the
 * bank_transaction_attachments table (suitable for small receipts ≤ 2 MB).
 *
 * Props:
 *   bankTransactionId     — UUID of the target bank transaction
 *   transactionDescription — Optional label shown in the modal header
 *   onClose               — Dismiss callback
 */

import { useState, useEffect, useRef, useCallback } from 'react';
import { X, Paperclip, Trash2, Upload, FileImage, FileText, AlertCircle, Loader2 } from 'lucide-react';
import { notify } from '@/utils/toast';
import { apiFetch } from '@/lib/apiFetch';

// ── Types ─────────────────────────────────────────────────────────────────────

interface Attachment {
  id: string;
  bank_transaction_id: string;
  file_url: string;
  file_name: string;
  file_size: number | null;
  uploaded_by: string | null;
  created_at: string;
}

interface Props {
  bankTransactionId: string;
  transactionDescription?: string;
  onClose: () => void;
}

// ── Constants ─────────────────────────────────────────────────────────────────

const MAX_BYTES = 2 * 1024 * 1024; // 2 MB
const ACCEPT = '.jpg,.jpeg,.png,.pdf';
const ACCEPTED_MIME = ['image/jpeg', 'image/png', 'application/pdf'];

// ── Helpers ───────────────────────────────────────────────────────────────────

function formatBytes(bytes: number | null): string {
  if (bytes === null) return '';
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatDate(iso: string): string {
  return new Date(iso).toLocaleDateString('en-ZA', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
}

function fileIcon(name: string): 'image' | 'pdf' | 'generic' {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  if (['jpg', 'jpeg', 'png'].includes(ext)) return 'image';
  if (ext === 'pdf') return 'pdf';
  return 'generic';
}

function readFileAsDataUrl(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

// ── Component ─────────────────────────────────────────────────────────────────

// 🟢 WORKING: Attachment list + upload modal for bank transactions
export function BankTxAttachmentsModal({ bankTransactionId, transactionDescription, onClose }: Props) {
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [dragOver, setDragOver] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // ── Fetch attachment list ──────────────────────────────────────────────────
  const fetchAttachments = useCallback(async () => {
    setLoading(true);
    try {
      const res = await apiFetch(
        `/api/accounting/bank-tx-attachments?bankTransactionId=${encodeURIComponent(bankTransactionId)}`,
      );
      const json = await res.json() as { success: boolean; data: Attachment[] };
      if (!res.ok || !json.success) throw new Error('Failed to load attachments');
      setAttachments(json.data);
    } catch {
      notify.error('Could not load attachments');
    } finally {
      setLoading(false);
    }
  }, [bankTransactionId]);

  useEffect(() => { void fetchAttachments(); }, [fetchAttachments]);

  // ── Upload ─────────────────────────────────────────────────────────────────
  const handleUpload = useCallback(async (file: File) => {
    if (!ACCEPTED_MIME.includes(file.type)) {
      notify.error('Only JPG, PNG and PDF files are accepted');
      return;
    }
    if (file.size > MAX_BYTES) {
      notify.error('File exceeds the 2 MB limit');
      return;
    }

    setUploading(true);
    try {
      const fileData = await readFileAsDataUrl(file);
      const res = await apiFetch('/api/accounting/bank-tx-attachments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bankTransactionId,
          fileName: file.name,
          fileData,
          fileSize: file.size,
        }),
      });
      const json = await res.json() as { success: boolean; message?: string };
      if (!res.ok || !json.success) throw new Error(json.message ?? 'Upload failed');
      notify.success(`${file.name} uploaded`);
      await fetchAttachments();
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Upload failed');
    } finally {
      setUploading(false);
    }
  }, [bankTransactionId, fetchAttachments]);

  // ── File input change ──────────────────────────────────────────────────────
  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) void handleUpload(file);
    e.target.value = '';
  };

  // ── Drag-and-drop ──────────────────────────────────────────────────────────
  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    setDragOver(false);
    const file = e.dataTransfer.files?.[0];
    if (file) void handleUpload(file);
  };

  // ── Delete ─────────────────────────────────────────────────────────────────
  const handleDelete = async (id: string, name: string) => {
    setDeletingId(id);
    try {
      const res = await apiFetch(
        `/api/accounting/bank-tx-attachments?id=${encodeURIComponent(id)}`,
        { method: 'DELETE' },
      );
      const json = await res.json() as { success: boolean; message?: string };
      if (!res.ok || !json.success) throw new Error(json.message ?? 'Delete failed');
      notify.success(`${name} removed`);
      setAttachments(prev => prev.filter(a => a.id !== id));
    } catch (err) {
      notify.error(err instanceof Error ? err.message : 'Delete failed');
    } finally {
      setDeletingId(null);
    }
  };

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
      <div
        className="w-full max-w-lg bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl shadow-2xl flex flex-col max-h-[85vh]"
        onClick={e => e.stopPropagation()}
      >
        {/* ── Header ─────────────────────────────────────────────────────── */}
        <div className="flex items-center gap-3 px-5 py-4 border-b border-[var(--ff-border-light)] shrink-0">
          <div className="p-2 rounded-lg bg-blue-500/10">
            <Paperclip className="h-4 w-4 text-blue-400" />
          </div>
          <div className="flex-1 min-w-0">
            <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">Attachments</h2>
            {transactionDescription && (
              <p className="text-xs text-[var(--ff-text-tertiary)] truncate">{transactionDescription}</p>
            )}
          </div>
          <button
            onClick={onClose}
            className="p-1.5 rounded hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-primary)]"
          >
            <X className="h-4 w-4" />
          </button>
        </div>

        {/* ── Upload zone ────────────────────────────────────────────────── */}
        <div className="px-5 pt-4 shrink-0">
          <div
            onDragOver={e => { e.preventDefault(); setDragOver(true); }}
            onDragLeave={() => setDragOver(false)}
            onDrop={handleDrop}
            onClick={() => !uploading && fileInputRef.current?.click()}
            className={`relative flex flex-col items-center justify-center gap-2 rounded-lg border-2 border-dashed py-5 cursor-pointer transition-colors ${
              dragOver
                ? 'border-blue-400 bg-blue-500/10'
                : 'border-[var(--ff-border-light)] hover:border-[var(--ff-text-tertiary)] bg-[var(--ff-bg-primary)]'
            }`}
          >
            {uploading ? (
              <>
                <Loader2 className="h-5 w-5 text-blue-400 animate-spin" />
                <span className="text-xs text-[var(--ff-text-secondary)]">Uploading…</span>
              </>
            ) : (
              <>
                <Upload className="h-5 w-5 text-[var(--ff-text-tertiary)]" />
                <p className="text-xs text-[var(--ff-text-secondary)] text-center">
                  Drag &amp; drop or{' '}
                  <span className="text-blue-400 font-medium">click to browse</span>
                </p>
                <p className="text-[10px] text-[var(--ff-text-tertiary)]">
                  JPG, PNG, PDF — max 2 MB
                </p>
              </>
            )}
            <input
              ref={fileInputRef}
              type="file"
              accept={ACCEPT}
              className="sr-only"
              onChange={handleFileChange}
              disabled={uploading}
            />
          </div>
        </div>

        {/* ── Attachment list ─────────────────────────────────────────────── */}
        <div className="flex-1 overflow-y-auto px-5 py-4 space-y-2">
          {loading ? (
            <div className="flex items-center justify-center py-8 gap-2 text-[var(--ff-text-tertiary)]">
              <Loader2 className="h-4 w-4 animate-spin" />
              <span className="text-xs">Loading…</span>
            </div>
          ) : attachments.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-8 gap-2 text-[var(--ff-text-tertiary)]">
              <AlertCircle className="h-5 w-5" />
              <span className="text-xs">No attachments yet</span>
            </div>
          ) : (
            attachments.map(att => {
              const icon = fileIcon(att.file_name);
              const isDeleting = deletingId === att.id;
              return (
                <div
                  key={att.id}
                  className="flex items-center gap-3 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] px-3 py-2.5"
                >
                  {/* File type icon */}
                  <div className="shrink-0 p-1.5 rounded bg-[var(--ff-bg-secondary)]">
                    {icon === 'image' ? (
                      <FileImage className="h-4 w-4 text-blue-400" />
                    ) : icon === 'pdf' ? (
                      <FileText className="h-4 w-4 text-orange-400" />
                    ) : (
                      <Paperclip className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                    )}
                  </div>

                  {/* Name + meta */}
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-[var(--ff-text-primary)] truncate">
                      {att.file_name}
                    </p>
                    <p className="text-[10px] text-[var(--ff-text-tertiary)]">
                      {formatBytes(att.file_size)}{att.file_size ? ' · ' : ''}{formatDate(att.created_at)}
                    </p>
                  </div>

                  {/* Download link */}
                  <a
                    href={att.file_url}
                    download={att.file_name}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="shrink-0 p-1.5 rounded hover:bg-blue-500/10 text-[var(--ff-text-tertiary)] hover:text-blue-400 transition-colors"
                    title="Download"
                    onClick={e => e.stopPropagation()}
                  >
                    <Upload className="h-3.5 w-3.5 rotate-180" />
                  </a>

                  {/* Delete */}
                  <button
                    disabled={isDeleting}
                    onClick={() => void handleDelete(att.id, att.file_name)}
                    className="shrink-0 p-1.5 rounded hover:bg-red-500/10 text-[var(--ff-text-tertiary)] hover:text-red-400 disabled:opacity-40 transition-colors"
                    title="Remove"
                  >
                    {isDeleting
                      ? <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      : <Trash2 className="h-3.5 w-3.5" />
                    }
                  </button>
                </div>
              );
            })
          )}
        </div>

        {/* ── Footer ─────────────────────────────────────────────────────── */}
        <div className="border-t border-[var(--ff-border-light)] px-5 py-3 flex items-center justify-between shrink-0">
          <span className="text-xs text-[var(--ff-text-tertiary)]">
            {attachments.length} attachment{attachments.length !== 1 ? 's' : ''}
          </span>
          <button
            onClick={onClose}
            className="px-4 py-1.5 rounded text-xs border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
}

