/**
 * POST /api/onboarding/documents
 * Upload statutory documents during onboarding.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { withAuth, type AuthenticatedNextApiRequest } from '@/lib/auth';
import { sql, transaction } from '@/lib/neon';

interface DocumentPayload {
  type: string;
  name: string;
  data: string;
  mimeType: string;
  size: number;
}

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method!, ['POST']);
  }

  const userId = (req as AuthenticatedNextApiRequest).user.id;
  const { companyId, documents } = req.body as {
    companyId?: string;
    documents?: DocumentPayload[];
  };

  if (!companyId) return apiResponse.badRequest(res, 'companyId is required');
  if (!documents || !Array.isArray(documents) || documents.length === 0) {
    return apiResponse.badRequest(res, 'documents array is required');
  }

  // Validate company membership
  const membership = (await sql`
    SELECT role FROM company_users
    WHERE company_id = ${companyId}::UUID AND user_id = ${userId}
  `) as { role: string }[];

  if (membership.length === 0) {
    return apiResponse.forbidden(res, 'You do not have access to this company');
  }

  // Insert each document
  for (const doc of documents) {
    await sql`
      INSERT INTO company_documents (
        company_id, document_type, document_name,
        file_data, mime_type, file_size, uploaded_by
      ) VALUES (
        ${companyId}::UUID, ${doc.type}, ${doc.name},
        ${doc.data}, ${doc.mimeType}, ${doc.size}, ${userId}
      )
    `;
  }

  return apiResponse.created(res, { count: documents.length });
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export default withAuth(withErrorHandler(handler));

export const config = {
  api: { bodyParser: { sizeLimit: '50mb' } },
};

/**
 * EFT File Generation Service — South African Bank Formats
 * Generates payment files for: Standard Bank, FNB, ABSA, Nedbank, Capitec
 * Pure business logic — no database dependencies.
 */

export interface EFTPayment {
  beneficiaryName: string;
  beneficiaryAccountNumber: string;
  beneficiaryBranchCode: string;
  beneficiaryAccountType: 'current' | 'savings' | 'transmission';
  amount: number;
  reference: string;
  beneficiaryBank?: string;
}

export interface EFTBatchHeader {
  companyName: string;
  bankAccountNumber: string;
  branchCode: string;
  accountType: 'current' | 'savings';
  batchReference: string;
  actionDate: string; // YYYY-MM-DD
}

export interface EFTValidationResult {
  valid: boolean;
  errors: string[];
  totalAmount: number;
  paymentCount: number;
}

// ═══════════════════════════════════════════════════════════════════════════
// FORMATTING UTILITIES
// ═══════════════════════════════════════════════════════════════════════════

export function formatEFTAmount(amount: number): string {
  return String(Math.round(amount * 100));
}

export function padRight(str: string, length: number): string {
  return str.substring(0, length).padEnd(length, ' ');
}

export function padLeft(str: string, length: number): string {
  const s = String(str);
  return s.length > length ? s.substring(s.length - length) : s.padStart(length, '0');
}

function formatEFTDate(dateStr: string): string {
  return dateStr.replace(/-/g, '').substring(2); // YYMMDD
}

function accountTypeCode(type: string): string {
  switch (type) {
    case 'current': return '1';
    case 'savings': return '2';
    case 'transmission': return '3';
    default: return '1';
  }
}

// ═══════════════════════════════════════════════════════════════════════════
// VALIDATION
// ═════════════════════���═════════════════════════════════════════════════════

export function validateBankAccount(accountNumber: string, branchCode: string): { valid: boolean; error?: string } {
  if (!accountNumber || accountNumber.trim() === '') return { valid: false, error: 'Account number is required' };
  if (!branchCode || branchCode.trim() === '') return { valid: false, error: 'Branch code is required' };
  if (!/^\d+$/.test(accountNumber)) return { valid: false, error: 'Account number must contain only digits' };
  if (!/^\d{6}$/.test(branchCode)) return { valid: false, error: 'Branch code must be exactly 6 digits' };
  return { valid: true };
}

export function validateEFTBatch(header: EFTBatchHeader, payments: EFTPayment[]): EFTValidationResult {
  const errors: string[] = [];

  if (!payments || payments.length === 0) {
    errors.push('At least one payment is required');
    return { valid: false, errors, totalAmount: 0, paymentCount: 0 };
  }

  let totalAmount = 0;
  for (let i = 0; i < payments.length; i++) {
    const p = payments[i]!;
    if (!p.beneficiaryName || p.beneficiaryName.trim() === '') errors.push(`Payment ${i + 1}: Beneficiary name is required`);
    if (!p.beneficiaryAccountNumber || p.beneficiaryAccountNumber.trim() === '') errors.push(`Payment ${i + 1}: Account number is required`);
    if (!p.amount || p.amount <= 0) errors.push(`Payment ${i + 1}: Amount must be greater than zero`);
    totalAmount += p.amount || 0;
  }

  totalAmount = Math.round(totalAmount * 100) / 100;
  return { valid: errors.length === 0, errors, totalAmount, paymentCount: payments.length };
}

// ═════════════════════════════════════════════════════���═════════════════════
// STANDARD BANK ACB FORMAT
// ══════��═══════════════════════════════════════════════════════��════════════

export function generateStandardBankACB(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  // Header record
  lines.push(
    'H' +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    padRight(header.companyName, 30) +
    date +
    padRight(header.batchReference, 20) +
    padLeft(String(payments.length), 6)
  );

  // Transaction records
  for (const p of payments) {
    lines.push(
      'T' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 20)
    );
  }

  // Trailer record
  lines.push(
    'Z' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 62)
  );

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// FNB EFT FORMAT
// ═══════════════════════════════════════════════════════════���═══════════════

export function generateFNBEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  // Header
  lines.push(
    'EFT' +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    date +
    padRight(header.companyName, 30) +
    padRight(header.batchReference, 12)
  );

  // Transactions
  for (const p of payments) {
    lines.push(
      'STD' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 12)
    );
  }

  // Trailer
  lines.push(
    'END' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 50)
  );

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════════════════════
// ABSA EFT FORMAT
// ════════════════════════��════════════════════════════��═════════════════════

export function generateABSAEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  lines.push(
    '04' + date +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    padRight(header.companyName, 30) +
    padRight(header.batchReference, 12)
  );

  for (const p of payments) {
    lines.push(
      '50' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 12)
    );
  }

  lines.push(
    '92' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 50)
  );

  return lines.join('\n');
}

// ═══════════════════════════════���═══════════════════════════════════════════
// NEDBANK EFT FORMAT
// ══��═══════════════════════════════════════════════════════════════���════════

export function generateNedbankEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  lines.push(
    'HDR' +
    date +
    padLeft(header.branchCode, 6) +
    padLeft(header.bankAccountNumber, 11) +
    padRight(header.companyName, 30) +
    padRight(header.batchReference, 12)
  );

  for (const p of payments) {
    lines.push(
      'TXN' +
      padLeft(p.beneficiaryBranchCode, 6) +
      padLeft(p.beneficiaryAccountNumber, 11) +
      accountTypeCode(p.beneficiaryAccountType) +
      padLeft(formatEFTAmount(p.amount), 11) +
      padRight(p.beneficiaryName, 30) +
      padRight(p.reference, 12)
    );
  }

  lines.push(
    'TRL' +
    padLeft(String(payments.length), 6) +
    padLeft(String(totalCents), 12) +
    padRight('', 50)
  );

  return lines.join('\n');
}

// ═══════════════════════════════════════════════════════════��═══════════════
// CAPITEC EFT FORMAT
// ═══════════════════��════════════════════════════════════���══════════════════

export function generateCapitecEFT(header: EFTBatchHeader, payments: EFTPayment[]): string {
  const lines: string[] = [];
  const date = formatDate(header.actionDate);
  const totalCents = payments.reduce((s, p) => s + Math.round(p.amount * 100), 0);

  lines.push(
    'H,' + date + ',' +
    header.branchCode + ',' +
    header.bankAccountNumber + ',' +
    header.companyName + ',' +
    header.batchReference
  );

  for (const p of payments) {
    lines.push(
      'T,' +
      p.beneficiaryBranchCode + ',' +
      p.beneficiaryAccountNumber + ',' +
      accountTypeCode(p.beneficiaryAccountType) + ',' +
      formatEFTAmount(p.amount) + ',' +
      p.beneficiaryName + ',' +
      p.reference
    );
  }

  lines.push(
    'Z,' + payments.length + ',' + totalCents
  );

  return lines.join('\n');
}

/**
 * POST /api/auth/register
 * Creates a new user account with email + password.
 * Does NOT set an auth cookie — user must log in after registering.
 */

import type { NextApiRequest, NextApiResponse } from 'next';
import { serialize } from 'cookie';
import { withErrorHandler } from '@/lib/api-error-handler';
import { apiResponse } from '@/lib/apiResponse';
import { hashPassword, checkPasswordStrength } from '@/lib/auth';
import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { checkRateLimit } from '@/lib/rateLimit';
import { signToken } from '@/lib/auth/jwt';
import { createSession } from '@/lib/auth/session';
import { AUTH_COOKIE_NAME } from '@/lib/auth/middleware';
import type { AuthRole } from '@/lib/auth/types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') {
    return apiResponse.methodNotAllowed(res, req.method ?? 'unknown', ['POST']);
  }

  // Rate limit: 3 registrations per IP per 15 minutes
  const rawIp = Array.isArray(req.headers['x-forwarded-for'])
    ? req.headers['x-forwarded-for'][0]
    : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
  const ip: string = rawIp ?? 'unknown';
  if (checkRateLimit(ip, { windowMs: 15 * 60 * 1000, maxRequests: 3 })) {
    return res.status(429).json({
      success: false,
      error: { code: 'RATE_LIMITED', message: 'Too many attempts. Please try again later.' },
    });
  }

  const { firstName, lastName, email, password, confirmPassword, inviteToken } = req.body as {
    firstName?: string;
    lastName?: string;
    email?: string;
    password?: string;
    confirmPassword?: string;
    inviteToken?: string;
  };

  // Validate all fields present
  if (!firstName || !lastName || !email || !password || !confirmPassword) {
    return apiResponse.badRequest(res, 'All fields are required');
  }

  // Validate email format
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!emailRegex.test(email)) {
    return apiResponse.badRequest(res, 'Please enter a valid email address');
  }

  // Validate passwords match
  if (password !== confirmPassword) {
    return apiResponse.badRequest(res, 'Passwords do not match');
  }

  // Check password strength
  const strength = checkPasswordStrength(password);
  if (!strength.isValid) {
    return apiResponse.badRequest(res, `Password too weak: ${strength.issues[0] || 'Please choose a stronger password'}`);
  }

  try {
    // Check email uniqueness
    const existing = (await sql`
      SELECT id FROM users WHERE LOWER(email) = LOWER(${email.trim()}) LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      return apiResponse.badRequest(res, 'An account with this email already exists');
    }

    // Hash password
    const hash = await hashPassword(password);

    // Insert user
    const rows = (await sql`
      INSERT INTO users (email, password_hash, first_name, last_name, role, permissions, is_active, onboarding_completed)
      VALUES (${email.toLowerCase().trim()}, ${hash}, ${firstName.trim()}, ${lastName.trim()}, 'viewer', '[]', true, false)
      RETURNING id, email
    `) as Row[];

    const user = rows[0];
    const userId = String(user.id);
    const normalizedEmail = (email as string).toLowerCase().trim();

    // Auto-accept pending invitations: by token (if provided) + by email match
    let invitationsAccepted = 0;

    // 1. Accept the specific invite by token (from invite link flow)
    if (inviteToken && typeof inviteToken === 'string') {
      const tokenInvites = (await sql`
        SELECT id, company_id, role
        FROM company_invitations
        WHERE token = ${inviteToken}
          AND accepted_at IS NULL
          AND expires_at > NOW()
        LIMIT 1
      `) as Row[];

      for (const inv of tokenInvites) {
        await sql`
          INSERT INTO company_users (company_id, user_id, role, is_default)
          VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
          ON CONFLICT (company_id, user_id) DO NOTHING
        `;
        await sql`
          UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
        `;
        invitationsAccepted++;
      }
    }

    // 2. Also accept any other pending invitations matching by email
    const pendingInvitations = (await sql`
      SELECT id, company_id, role
      FROM company_invitations
      WHERE LOWER(email) = LOWER(${normalizedEmail})
        AND accepted_at IS NULL
        AND expires_at > NOW()
    `) as Row[];

    for (const inv of pendingInvitations) {
      await sql`
        INSERT INTO company_users (company_id, user_id, role, is_default)
        VALUES (${inv.company_id as string}::UUID, ${userId}::UUID, ${inv.role as string}, false)
        ON CONFLICT (company_id, user_id) DO NOTHING
      `;
      await sql`
        UPDATE company_invitations SET accepted_at = NOW() WHERE id = ${inv.id as string}::UUID
      `;
      invitationsAccepted++;
    }

    const onboardingCompleted = invitationsAccepted > 0;
    if (onboardingCompleted) {
      await sql`UPDATE users SET onboarding_completed = true WHERE id = ${userId}`;
      log.info('Onboarding skipped via invitation acceptance at registration', { userId, invitationsAccepted }, 'auth/register');
    }

    log.info('User registered', { userId, email: user.email as string, invitationsAccepted }, 'auth/register');

    // Auto-login: create session and set auth cookie
    const authUser = {
      id: userId,
      userId,
      email: normalizedEmail,
      firstName: firstName.trim(),
      lastName: lastName.trim(),
      name: `${firstName.trim()} ${lastName.trim()}`.trim(),
      role: 'viewer' as AuthRole,
      permissions: [] as string[],
      isActive: true,
    };

    const ipAddress = Array.isArray(req.headers['x-forwarded-for'])
      ? req.headers['x-forwarded-for'][0]
      : req.headers['x-forwarded-for'] ?? req.socket.remoteAddress;
    const userAgent = req.headers['user-agent'];

    const tempToken = await signToken(authUser, 'pending');
    const session = await createSession(authUser.id, tempToken, ipAddress, userAgent);
    const finalToken = await signToken(authUser, session.id);

    const crypto = await import('crypto');
    const finalHash = crypto.createHash('sha256').update(finalToken).digest('hex');
    await sql`
      UPDATE user_sessions SET token_hash = ${finalHash} WHERE id = ${Number(session.id)}
    `;

    const isProd = process.env.NODE_ENV === 'production';
    const cookies = [
      serialize(AUTH_COOKIE_NAME, finalToken, {
        httpOnly: true,
        secure: true,
        sameSite: 'lax',
        path: '/',
        maxAge: 8 * 60 * 60,
        ...(isProd ? { domain: '.isaflow.co.za' } : {}),
      }),
    ];
    if (onboardingCompleted) {
      const domainSuffix = isProd ? '; Domain=.isaflow.co.za' : '';
      cookies.push(`ff_onboarding_done=1; Path=/; Max-Age=${30 * 24 * 60 * 60}; SameSite=Lax${isProd ? '; Secure' : ''}${domainSuffix}`);
    }
    res.setHeader('Set-Cookie', cookies);

    return apiResponse.created(res, {
      userId,
      email: normalizedEmail,
      invitationsAccepted,
      autoLoggedIn: true,
    });
  } catch (err) {
    log.error('Registration error', err instanceof Error ? { message: err.message } : { err }, 'auth/register');
    return apiResponse.internalError(res, err);
  }
}

export default withErrorHandler(handler);

