    y += 5;
    doc.text(`YTD PAYE: R ${formatCurrency(Number(slip.ytd_paye))}`, margin, y);
    y += 5;
    doc.text(`YTD UIF: R ${formatCurrency(Number(slip.ytd_uif))}`, margin, y);
    y += 10;

