/**
 * SARS eFiling Integration Service
 * Generates VAT201 and EMP201 form data from accounting records.
 * Manages tax periods and compliance calendar for South African tax obligations.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const SA_VAT_RATE = 0.15;

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface VAT201Data {
  periodStart: string;
  periodEnd: string;
  field1_standardRatedSupplies: number;
  field2_zeroRatedSupplies: number;
  field3_exemptSupplies: number;
  field4_totalImports: number;
  field5_outputVAT: number;
  field6_capitalGoods: number;
  field7_otherGoods: number;
  field8_services: number;
  field9_imports: number;
  field10_totalInputVAT: number;
  field11_vatPayableOrRefundable: number;
  outputInvoices: VAT201Invoice[];
  inputInvoices: VAT201Invoice[];
}

export interface VAT201Invoice {
  id: string;
  invoiceNumber: string;
  counterpartyName: string;
  invoiceDate: string;
  totalExclVat: number;
  vatAmount: number;
  vatType: string;
}

export interface EMP201Data {
  periodStart: string;
  periodEnd: string;
  totalPAYE: number;
  totalUIF_employee: number;
  totalUIF_employer: number;
  totalUIF: number;
  totalSDL: number;
  employeeCount: number;
  totalTaxableRemuneration: number;
  totalDeductions: number;
  payrollRuns: EMP201PayrollRun[];
}

export interface EMP201PayrollRun {
  id: string;
  runDate: string;
  employeeCount: number;
  grossPay: number;
  paye: number;
  uif: number;
  sdl: number;
}

export interface TaxPeriod {
  type: 'VAT' | 'PAYE';
  periodStart: string;
  periodEnd: string;
  dueDate: string;
  label: string;
}

export interface ComplianceEvent {
  id?: string;
  eventType: string;
  dueDate: string;
  description: string;
  status: 'pending' | 'completed' | 'overdue';
  submissionId?: string;
}

export interface SARSSubmission {
  id: string;
  formType: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  formData: Record<string, unknown>;
  submissionReference: string | null;
  submittedAt: string | null;
  submittedBy: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;

/**
 * PRD-060: FibreFlow Accounting Module — Phase 4
 * Bank Reconciliation Service
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { detectBankFormat, parseFNBStatement, parseStandardBankStatement, parseNedbankStatement, parseABSAStatement, parseCapitecStatement } from '../utils/bankCsvParsers';
import { parseOfxStatement } from '../utils/bankOfxParser';
import { parseQifStatement } from '../utils/bankQifParser';
import { runAutoMatch } from '../utils/autoMatch';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import type { BankTransaction, BankReconciliation, AutoMatchResult, BankFormat, BankCsvParseResult } from '../types/bank.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Import ───────────────────────────────────────────────────────────────────

export async function importBankStatement(
  companyId: string,
  csvContent: string,
  bankAccountId: string,
  statementDate: string,
  bankFormat?: BankFormat
): Promise<{ batchId: string; transactionCount: number; errors: Array<{ row: number; error: string }> }> {
  try {
    const format = bankFormat && bankFormat !== 'unknown' ? bankFormat : detectBankFormat(csvContent);
    let parseResult;

    switch (format) {
      case 'fnb':
        parseResult = parseFNBStatement(csvContent);
        break;
      case 'standard_bank':
        parseResult = parseStandardBankStatement(csvContent);
        break;
      case 'nedbank':
        parseResult = parseNedbankStatement(csvContent);
        break;
      case 'absa':
        parseResult = parseABSAStatement(csvContent);
        break;
      case 'capitec':
        parseResult = parseCapitecStatement(csvContent);
        break;
      case 'ofx':
        parseResult = parseOfxStatement(csvContent);
        break;
      case 'qif':
        parseResult = parseQifStatement(csvContent);
        break;
      default:
        throw new Error('Unable to detect bank format. Please specify the bank.');
    }

    if (parseResult.transactions.length === 0) {
      return { batchId: '', transactionCount: 0, errors: parseResult.errors };
    }

    const batchId = crypto.randomUUID();

    await transaction((txSql) =>
      parseResult.transactions.map(tx => txSql`
        INSERT INTO bank_transactions (
          bank_account_id, transaction_date, value_date, amount,
          description, reference, import_batch_id
        ) VALUES (
          ${bankAccountId}::UUID, ${tx.transactionDate}, ${tx.valueDate || null},
          ${tx.amount}, ${tx.description}, ${tx.reference || null}, ${batchId}::UUID
        )
      `)
    );

    log.info('Imported bank statement', {
      batchId, format, count: parseResult.transactions.length,
    }, 'accounting');

/**
 * Consolidated Reporting Service
 *
 * Generates consolidated financial reports across a group of companies.
 * Combines individual company reports, maps them to the group COA,
 * and applies elimination adjustments.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

interface EntityBalance {
  debit: number;
  credit: number;
}

interface ConsolidatedTrialBalanceRow {
  groupAccountId: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  entities: Record<string, EntityBalance>;
  eliminationDebit: number;
  eliminationCredit: number;
  consolidatedDebit: number;
  consolidatedCredit: number;
}

interface ConsolidatedTrialBalanceTotals {
  entities: Record<string, EntityBalance>;
  eliminationDebit: number;
  eliminationCredit: number;
  consolidatedDebit: number;
  consolidatedCredit: number;
}

export interface ConsolidatedTrialBalance {
  groupId: string;
  periodStart: string;
  periodEnd: string;
  groupAccounts: ConsolidatedTrialBalanceRow[];
  totals: ConsolidatedTrialBalanceTotals;
}

interface EntityAmount {
  amount: number;
}

interface ConsolidatedLineItem {
  groupAccountId: string;
  accountCode: string;
  accountName: string;
  entities: Record<string, EntityAmount>;
  eliminationAmount: number;
  consolidatedAmount: number;
}

interface ConsolidatedISTotals {
  entities: Record<string, number>;
  eliminationAmount: number;
  consolidatedAmount: number;
}

export interface ConsolidatedIncomeStatement {
  groupId: string;
  periodStart: string;
  periodEnd: string;
  revenue: ConsolidatedLineItem[];
  costOfSales: ConsolidatedLineItem[];
  operatingExpenses: ConsolidatedLineItem[];
  totalRevenue: ConsolidatedISTotals;
  totalCostOfSales: ConsolidatedISTotals;
  grossProfit: ConsolidatedISTotals;
  totalOperatingExpenses: ConsolidatedISTotals;
  netProfit: ConsolidatedISTotals;

  updatedAt: string;
}

// ---------------------------------------------------------------------------
// VAT201 Generation
// ---------------------------------------------------------------------------

/**
 * Generate a VAT201 return from customer and supplier invoices for the period.
 * Output VAT comes from customer_invoices; input VAT from supplier_invoices.
 * GL account codes 2120 (Output VAT) and 1140 (Input VAT) are cross-referenced.
 */
export async function generateVAT201(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<VAT201Data> {
  log.info('Generating VAT201', { periodStart, periodEnd }, 'sarsService');

  // -- Output VAT: customer invoices in period --
  let customerInvoices: Row[] = [];
  try {
    customerInvoices = (await sql`
      SELECT
        ci.id,
        ci.invoice_number,
        ci.invoice_date,
        ci.subtotal,
        ci.tax_amount,
        ci.total_amount,
        ci.tax_rate,
        COALESCE(c.name, cl.name) AS customer_name
      FROM customer_invoices ci
      LEFT JOIN customers c ON c.id = ci.customer_id
      LEFT JOIN clients cl ON cl.id = ci.client_id
      WHERE ci.company_id = ${companyId}
        AND ci.invoice_date >= ${periodStart}
        AND ci.invoice_date <= ${periodEnd}
        AND ci.status != 'cancelled'
      ORDER BY ci.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query customer_invoices for VAT201', { error: err }, 'sarsService');
  }

  // -- Input VAT: supplier invoices in period --
  let supplierInvoices: Row[] = [];
  try {
    supplierInvoices = (await sql`
      SELECT
        si.id,
        si.invoice_number,
        si.invoice_date,
        si.subtotal,
        si.tax_amount,
        si.total_amount,
        si.tax_rate,
        s.name AS supplier_name
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.company_id = ${companyId}
        AND si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status != 'cancelled'
      ORDER BY si.invoice_date
    `) as Row[];
  } catch (err) {
    log.warn('Could not query supplier_invoices for VAT201', { error: err }, 'sarsService');
  }

  // Categorise customer invoices (output side)
  let field1_standardRated = 0;
  let field2_zeroRated = 0;
  const field3_exempt = 0; // TODO: categorise exempt invoices when vat_type column added

  const outputInvoices: VAT201Invoice[] = customerInvoices.map((inv: Row) => {
    const subtotal = Number(inv.subtotal) || 0;
    const vatAmt = Number(inv.tax_amount) || 0;
    const taxRate = Number(inv.tax_rate) || 0;
    // Determine VAT type from tax_rate: 0% = zero-rated, 15% = standard
    const vatType = taxRate === 0 ? 'zero_rated' : 'standard';

    if (taxRate === 0) {
      field2_zeroRated += subtotal;
    } else {
      field1_standardRated += subtotal;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.customer_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  // Field 5: Output VAT = standard-rated supplies x 15%
  const field5_outputVAT = roundCents(field1_standardRated * SA_VAT_RATE);

  // Categorise supplier invoices (input side)
  const field6_capitalGoods = 0; // TODO: categorise when vat_type column added
  let field7_otherGoods = 0;
  const field8_services = 0; // TODO: categorise when vat_type column added
  const field9_imports = 0; // TODO: categorise when vat_type column added

  const inputInvoices: VAT201Invoice[] = supplierInvoices.map((inv: Row) => {
    const vatAmt = Number(inv.tax_amount) || 0;
    const subtotal = Number(inv.subtotal) || 0;
    const taxRate = Number(inv.tax_rate) || 0;
    const vatType = taxRate === 0 ? 'zero_rated' : 'standard';

    // All standard-rated supplier invoices go to "other goods" (field 7) by default
    if (taxRate > 0) {
      field7_otherGoods += vatAmt;
    }

    return {
      id: String(inv.id),
      invoiceNumber: String(inv.invoice_number || ''),
      counterpartyName: String(inv.supplier_name || 'Unknown'),
      invoiceDate: String(inv.invoice_date || ''),
      totalExclVat: subtotal,
      vatAmount: vatAmt,
      vatType,
    };
  });

  const field10_totalInputVAT = roundCents(
    field6_capitalGoods + field7_otherGoods + field8_services + field9_imports
  );

  const field11_vatPayable = roundCents(field5_outputVAT - field10_totalInputVAT);

  return {
    periodStart,
    periodEnd,
    field1_standardRatedSupplies: roundCents(field1_standardRated),
    field2_zeroRatedSupplies: roundCents(field2_zeroRated),
    field3_exemptSupplies: roundCents(field3_exempt),
    field4_totalImports: roundCents(field9_imports > 0 ? field9_imports / SA_VAT_RATE : 0),
    field5_outputVAT,
    field6_capitalGoods: roundCents(field6_capitalGoods),
    field7_otherGoods: roundCents(field7_otherGoods),
    field8_services: roundCents(field8_services),
    field9_imports: roundCents(field9_imports),
    field10_totalInputVAT,
    field11_vatPayableOrRefundable: field11_vatPayable,
    outputInvoices,
    inputInvoices,
  };
}

// ---------------------------------------------------------------------------
// EMP201 Generation
// ---------------------------------------------------------------------------

/**
 * Generate EMP201 (monthly PAYE/UIF/SDL) data from payroll tables.
 * Handles missing payroll tables gracefully by returning zero-filled data.
 */
export async function generateEMP201(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<EMP201Data> {
  log.info('Generating EMP201', { periodStart, periodEnd }, 'sarsService');

  const emptyResult: EMP201Data = {
    periodStart,
    periodEnd,
    totalPAYE: 0,
    totalUIF_employee: 0,
    totalUIF_employer: 0,
    totalUIF: 0,
    totalSDL: 0,
    employeeCount: 0,
    totalTaxableRemuneration: 0,
    totalDeductions: 0,
    payrollRuns: [],
  };

  // Check if payroll tables exist
  let hasPayrollTables = false;
  try {
    const tables = (await sql`
      SELECT table_name FROM information_schema.tables
      WHERE table_schema = 'public'
        AND table_name IN ('payroll_runs', 'payslips')
    `) as Row[];
    hasPayrollTables = tables.length >= 2;
  } catch (err) {
    log.warn('Could not check payroll tables', { error: err }, 'sarsService');
  }

  if (!hasPayrollTables) {
    log.info('Payroll tables not found, returning empty EMP201', {}, 'sarsService');
    return emptyResult;
  }

/**
 * Accounting Module - Main Page
 * Tabbed interface: Overview, Chart of Accounts, Journal Entries, Fiscal Periods, Reports
 */

import { useState, useEffect, useCallback } from 'react';
