                      <Link href={`/accounting/journal-entries/${entry.id}`} className="text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]">
                        <ChevronRight className="h-4 w-4 inline" />
                      </Link>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

