    };
  } catch (err) {
    log.error('Failed to generate consolidated income statement', { groupId, error: err }, 'accounting');
    throw err;
  }
}

// ── Balance Sheet ─────────────────────────────────────────────────────────────

export async function getConsolidatedBalanceSheet(
