                      >
                        {a.name}
                      </span>
                    )}
                  </td>
                  <td className="py-2 text-[var(--ff-text-secondary)] capitalize">{a.account_type}</td>
                  <td className="py-2 text-[var(--ff-text-tertiary)]">{a.sub_type || '-'}</td>
                  <td className="py-2 text-[var(--ff-text-tertiary)]">{a.level}</td>
