                            Cancel
                          </button>
                        </div>
                      ) : (
                        <div className="flex items-center justify-end gap-1">
                          <button onClick={() => { setEditingMemberId(m.id); setEditMember({ ownership_pct: m.ownership_pct, consolidation_method: m.consolidation_method }); }}
