        <CreateEntityModal
          type={createEntityType}
          transactionDescription={entityTx?.description}
          existingAccounts={glAccounts}
          onClose={onCreateEntityClose}
          onCreated={entity => onCreateEntityDone(entity, createEntityType)}
        />
      )}
    </>
  );
}

