    excludingTxId, createEntityTxId,
    setSmartRunning, setRowSelections, setTransactions, setSelectedIds,
    setRulePrompt, setExcludingTxId, loadTransactions,
  } = deps;

  const callAction = async (body: Record<string, string>) => {
