  setSelectedIds: (fn: (prev: Set<string>) => Set<string>) => void;
  setShowBatchEdit: (v: boolean) => void;
  setRulePrompt: (v: RulePrompt | null) => void;
  setExcludingTxId: (v: string | null) => void;
  loadTransactions: () => void;
}

