    if (createEntityTxId) {
      setRowSelections(prev => ({ ...prev, [createEntityTxId]: { type, entityId: entity.id, label, vatCode: prev[createEntityTxId]?.vatCode || vatCode } }));
      saveSelection(createEntityTxId, type as AllocType, entity.id, vatCode);
    }
  };

  return {
    saveSelection, saveDimensions,
    handleAccept, handleExclude, handleExcludeConfirm,
    handleUnmatch, handleUpdateNotes,
    handleBatchAccept, handleBatchDelete, handleBulkAccept,
    handleApplyRules, handleReverse,
    handleExport, handleDownloadReport, handleCreateEntityDone,
