/**
 * Intercompany Reconciliation
 * View, record, and reconcile intercompany transactions across group companies.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Building2,
  Loader2,
  AlertCircle,
  Check,
  Plus,
  Link2,
  X,
  ArrowLeftRight,
  Calendar,
  Filter,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ── Formatters ── */
const fmt = (n: number, currency = 'ZAR') =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency }).format(n);

/* ── Types ── */
interface CompanyGroup {
  id: string;
  name: string;
  companies: { id: string; name: string }[];
}

interface IntercompanyTx {
  id: string;
  date: string;
  sourceCompanyId: string;
  sourceCompanyName: string;
  targetCompanyId: string;
  targetCompanyName: string;
  type: string;
  amount: number;
  currency: string;
  description: string;
  status: 'matched' | 'partial' | 'unmatched' | 'variance';
  matchedTxId?: string;
  journalEntryId?: string;
}

interface ReconciliationStats {
  totalVolume: number;
  matchedCount: number;
  matchedAmount: number;
  unmatchedCount: number;
  unmatchedAmount: number;
  varianceCount: number;
  varianceAmount: number;
}

type TabKey = 'all' | 'unmatched' | 'matched' | 'variance';

const TX_TYPES = [
  { value: 'sale', label: 'Sale' },
  { value: 'purchase', label: 'Purchase' },
  { value: 'loan', label: 'Loan' },
  { value: 'dividend', label: 'Dividend' },
  { value: 'mgmt_fee', label: 'Management Fee' },
  { value: 'transfer', label: 'Transfer' },
] as const;

const STATUS_STYLES: Record<string, string> = {
  matched: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30',
  partial: 'bg-amber-500/10 text-amber-400 border-amber-500/30',
  unmatched: 'bg-red-500/10 text-red-400 border-red-500/30',
  variance: 'bg-orange-500/10 text-orange-400 border-orange-500/30',
};

/* ── Default date range: current month ── */
function defaultRange() {
  const now = new Date();
  const start = new Date(now.getFullYear(), now.getMonth(), 1);
  const end = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return {
    start: start.toISOString().split('T')[0],
    end: end.toISOString().split('T')[0],
  };
}

export default function IntercompanyReconciliationPage() {
  /* ── State ── */
  const [groups, setGroups] = useState<CompanyGroup[]>([]);
  const [selectedGroupId, setSelectedGroupId] = useState('');
  const range = defaultRange();
  const [periodStart, setPeriodStart] = useState(range.start);
  const [periodEnd, setPeriodEnd] = useState(range.end);

  const [transactions, setTransactions] = useState<IntercompanyTx[]>([]);
  const [stats, setStats] = useState<ReconciliationStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [loadingTx, setLoadingTx] = useState(false);

  const [activeTab, setActiveTab] = useState<TabKey>('all');
  const [showCreate, setShowCreate] = useState(false);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<{ type: 'success' | 'error'; text: string } | null>(null);

  // Matching state
  const [matchSelection, setMatchSelection] = useState<string[]>([]);

  // Create form state
  const [form, setForm] = useState({
    sourceCompanyId: '',
    targetCompanyId: '',
    type: 'sale',
    amount: '',
    currency: 'ZAR',
    date: new Date().toISOString().slice(0, 10),
    description: '',
    journalEntryId: '',
  });

  /* ── Helpers ── */
  const activeGroup = groups.find((g) => g.id === selectedGroupId);
  const companies = activeGroup?.companies || [];

  /* ── Load groups ── */
  useEffect(() => {
    (async () => {
      setLoading(true);
      const res = await apiFetch('/api/accounting/company-groups');
      if (res.ok) {
        const json = await res.json();
        const list: CompanyGroup[] = json.data?.items ?? json.data ?? [];
        setGroups(list);
        if (list.length > 0 && !selectedGroupId && list[0]) {
          setSelectedGroupId(list[0].id);
        }
      }
      setLoading(false);
    })();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  /* ── Load transactions + stats ── */
  const loadData = useCallback(async () => {
    if (!selectedGroupId) return;
    setLoadingTx(true);
    setMsg(null);

    const params = new URLSearchParams({
      group_id: selectedGroupId,
      ...(periodStart ? { period_start: periodStart } : {}),
      ...(periodEnd ? { period_end: periodEnd } : {}),
    });
    if (activeTab !== 'all') params.set('status', activeTab);

    const [txRes, reconRes] = await Promise.all([
      apiFetch(`/api/accounting/intercompany-transactions?${params}`),
      apiFetch(
        `/api/accounting/intercompany-transactions?group_id=${selectedGroupId}&action=reconciliation&period_start=${periodStart}&period_end=${periodEnd}`
      ),
    ]);

    if (txRes.ok) {
      const json = await txRes.json();
      setTransactions(json.data?.items || json.data || []);
    }
    if (reconRes.ok) {
      const json = await reconRes.json();
      setStats(json.data || null);
    }
    setLoadingTx(false);
  }, [selectedGroupId, periodStart, periodEnd, activeTab]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ── Create transaction ── */
  const handleCreate = async () => {
    if (!form.sourceCompanyId || !form.targetCompanyId || !form.amount) return;
    setSaving(true);
    const res = await apiFetch('/api/accounting/intercompany-transactions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        groupId: selectedGroupId,
        sourceCompanyId: form.sourceCompanyId,
        targetCompanyId: form.targetCompanyId,
        transactionType: form.type,
        amount: parseFloat(form.amount),
        currency: form.currency,
        transactionDate: form.date,
        description: form.description,
        sourceJournalEntryId: form.journalEntryId || undefined,
      }),
    });
    if (res.ok) {
      setMsg({ type: 'success', text: 'Transaction recorded' });
      setShowCreate(false);
      setForm({
        sourceCompanyId: '',
        targetCompanyId: '',
        type: 'sale',
        amount: '',
        currency: 'ZAR',
        date: new Date().toISOString().slice(0, 10),
        description: '',
        journalEntryId: '',
      });
      await loadData();
    } else {
      const err = await res.json().catch(() => null);
      setMsg({ type: 'error', text: err?.message || 'Failed to create transaction' });
    }
    setSaving(false);
  };

  /* ── Match two transactions ── */
  const toggleMatchSelect = (id: string) => {
    setMatchSelection((prev) => {
      if (prev.includes(id)) return prev.filter((x) => x !== id);
      if (prev.length >= 2) return [prev[1]!, id];
      return [...prev, id];
    });
  };

  const handleMatch = async () => {
    if (matchSelection.length !== 2) return;
    setSaving(true);
    const res = await apiFetch('/api/accounting/intercompany-transactions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        action: 'match',
        sourceId: matchSelection[0],
        targetId: matchSelection[1],
      }),
    });
    if (res.ok) {
      setMsg({ type: 'success', text: 'Transactions matched' });
      setMatchSelection([]);
      await loadData();
    } else {
      const err = await res.json().catch(() => null);
      setMsg({ type: 'error', text: err?.message || 'Match failed' });
    }
    setSaving(false);
  };

  /* ── Filtered transactions (client-side fallback) ── */
  const filtered = activeTab === 'all'
    ? transactions
    : transactions.filter((t) => t.status === activeTab);

  /* ── Tab config ── */
  const tabs: { key: TabKey; label: string }[] = [
    { key: 'all', label: 'All' },
    { key: 'unmatched', label: 'Unmatched' },
    { key: 'matched', label: 'Matched' },
    { key: 'variance', label: 'Variance' },
  ];

  /* ── Render ── */
  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between flex-wrap gap-4">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-purple-500/10">
                <Building2 className="h-6 w-6 text-purple-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Intercompany Reconciliation
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  View, record, and reconcile intercompany transactions
                </p>
              </div>
            </div>

            <div className="flex items-center gap-3 flex-wrap">
              {/* Group Selector */}
              <div className="flex items-center gap-2">
                <Filter className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                <select
                  value={selectedGroupId}
                  onChange={(e) => setSelectedGroupId(e.target.value)}
                  className="px-3 py-1.5 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
                >
                  {groups.map((g) => (
                    <option key={g.id} value={g.id}>
                      {g.name}
                    </option>
                  ))}
                </select>
              </div>

              {/* Date Range */}
              <div className="flex items-center gap-2">
                <Calendar className="h-4 w-4 text-[var(--ff-text-tertiary)]" />
                <input
                  type="date"
                  value={periodStart}
                  onChange={(e) => setPeriodStart(e.target.value)}
                  className="px-2 py-1.5 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
                />
                <span className="text-[var(--ff-text-tertiary)] text-sm">to</span>
                <input
                  type="date"
                  value={periodEnd}
                  onChange={(e) => setPeriodEnd(e.target.value)}
                  className="px-2 py-1.5 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
                />
              </div>

              <button
                onClick={() => setShowCreate(true)}
                className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-sm font-medium transition-colors"
              >
                <Plus className="h-4 w-4" /> Record Transaction
              </button>
            </div>
          </div>
        </div>

        <div className="p-6 space-y-4">
          {/* Message banner */}
          {msg && (
            <div
              className={`flex items-center gap-2 p-3 rounded-lg text-sm ${
                msg.type === 'success'
                  ? 'bg-teal-500/10 text-teal-400'
                  : 'bg-red-500/10 text-red-400'
              }`}
            >
              {msg.type === 'success' ? (
                <Check className="h-4 w-4" />
              ) : (
                <AlertCircle className="h-4 w-4" />
              )}
              {msg.text}
              <button onClick={() => setMsg(null)} className="ml-auto">
                <X className="h-4 w-4" />
              </button>
            </div>
          )}

          {/* Stats Cards */}
          {stats && (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
              <StatCard
                label="Total Intercompany Volume"
                value={fmt(stats.totalVolume)}
                sub={`${stats.matchedCount + stats.unmatchedCount + stats.varianceCount} transaction(s)`}
                color="text-purple-400"
              />
              <StatCard
                label="Matched"
                value={fmt(stats.matchedAmount)}
                sub={`${stats.matchedCount} transaction(s)`}
                color="text-emerald-400"
              />
              <StatCard
                label="Unmatched"
                value={fmt(stats.unmatchedAmount)}
                sub={`${stats.unmatchedCount} transaction(s)`}
                color="text-red-400"
              />
              <StatCard
                label="Variance"
                value={fmt(stats.varianceAmount)}
                sub={`${stats.varianceCount} transaction(s)`}
                color="text-orange-400"
              />
            </div>
          )}

          {/* Tabs */}
          <div className="flex items-center gap-1 border-b border-[var(--ff-border-light)]">
            {tabs.map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                  activeTab === tab.key
                    ? 'border-purple-500 text-purple-400'
                    : 'border-transparent text-[var(--ff-text-tertiary)] hover:text-[var(--ff-text-secondary)]'
                }`}
              >
                {tab.label}
              </button>
            ))}

            {/* Match button */}
            {matchSelection.length === 2 && (
              <button
                onClick={handleMatch}
                disabled={saving}
                className="ml-auto flex items-center gap-2 px-4 py-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 text-sm font-medium transition-colors"
              >
                {saving ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Link2 className="h-4 w-4" />
                )}
                Match Selected ({matchSelection.length})
              </button>
            )}
            {matchSelection.length > 0 && matchSelection.length < 2 && (
              <span className="ml-auto text-xs text-[var(--ff-text-tertiary)] py-2">
                Select 1 more transaction to match
              </span>
            )}
          </div>

          {/* Transaction Table */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
            {loading || loadingTx ? (
              <div className="p-12 text-center">
                <Loader2 className="h-6 w-6 animate-spin text-[var(--ff-text-tertiary)] mx-auto" />
              </div>
            ) : filtered.length === 0 ? (
              <div className="p-12 text-center text-[var(--ff-text-tertiary)]">
                <ArrowLeftRight className="h-8 w-8 mx-auto mb-2 opacity-50" />
                <p>No intercompany transactions found</p>
              </div>
            ) : (
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-[var(--ff-border-light)] text-[var(--ff-text-tertiary)] text-xs uppercase">
                      <th className="px-4 py-3 text-left w-8" />
                      <th className="px-4 py-3 text-left">Date</th>
                      <th className="px-4 py-3 text-left">Source Company</th>
                      <th className="px-4 py-3 text-left">Target Company</th>
                      <th className="px-4 py-3 text-left">Type</th>
                      <th className="px-4 py-3 text-right">Amount</th>
                      <th className="px-4 py-3 text-center">Status</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-[var(--ff-border-light)]">
                    {filtered.map((tx) => {
                      const isSelected = matchSelection.includes(tx.id);
                      const canSelect = tx.status === 'unmatched' || tx.status === 'partial';
                      return (
                        <tr
                          key={tx.id}
                          onClick={() => canSelect && toggleMatchSelect(tx.id)}
                          className={`hover:bg-[var(--ff-bg-tertiary)] transition-colors ${
                            canSelect ? 'cursor-pointer' : ''
                          } ${isSelected ? 'bg-purple-500/5' : ''}`}
                        >
                          <td className="px-4 py-3">
                            {canSelect && (
                              <input
                                type="checkbox"
                                checked={isSelected}
                                onChange={() => toggleMatchSelect(tx.id)}
                                className="rounded border-[var(--ff-border-light)]"
                              />
                            )}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-primary)] whitespace-nowrap">
                            {tx.date?.split('T')[0]}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                            {tx.sourceCompanyName}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                            {tx.targetCompanyName}
                          </td>
                          <td className="px-4 py-3 text-[var(--ff-text-secondary)] capitalize">
                            {tx.type.replace('_', ' ')}
                          </td>
                          <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                            {fmt(tx.amount, tx.currency)}
                          </td>
                          <td className="px-4 py-3 text-center">
                            <span
                              className={`inline-block px-2 py-0.5 text-xs font-medium rounded-full border ${
                                STATUS_STYLES[tx.status] || STATUS_STYLES.unmatched
                              }`}
                            >
                              {tx.status}
                            </span>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            )}
          </div>
        </div>

        {/* ── Create Transaction Modal ── */}
        {showCreate && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60">
            <div className="bg-[var(--ff-bg-secondary)] border border-[var(--ff-border-light)] rounded-xl w-full max-w-lg mx-4 shadow-2xl">
              <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                  Record Intercompany Transaction
                </h2>
                <button
                  onClick={() => setShowCreate(false)}
                  className="p-1 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div className="px-6 py-4 space-y-4">
                {/* Source / Target */}
                <div className="grid grid-cols-2 gap-4">
                  <FieldSelect
                    label="Source Company"
                    value={form.sourceCompanyId}
                    onChange={(v) => setForm((f) => ({ ...f, sourceCompanyId: v }))}
                    options={companies.map((c) => ({ value: c.id, label: c.name }))}
                    placeholder="Select..."
                  />
                  <FieldSelect
                    label="Target Company"
                    value={form.targetCompanyId}
                    onChange={(v) => setForm((f) => ({ ...f, targetCompanyId: v }))}
                    options={companies.filter((c) => c.id !== form.sourceCompanyId).map((c) => ({ value: c.id, label: c.name }))}
                    placeholder="Select..."
                  />
                </div>

                {/* Type + Currency */}
                <div className="grid grid-cols-2 gap-4">
                  <FieldSelect
                    label="Transaction Type"
                    value={form.type}
                    onChange={(v) => setForm((f) => ({ ...f, type: v }))}
                    options={TX_TYPES.map((t) => ({ value: t.value, label: t.label }))}
                  />
                  <FieldInput
                    label="Currency"
                    value={form.currency}
                    onChange={(v) => setForm((f) => ({ ...f, currency: v }))}
                  />
                </div>

                {/* Amount + Date */}
                <div className="grid grid-cols-2 gap-4">
                  <FieldInput
                    label="Amount"
                    type="number"
                    value={form.amount}
                    onChange={(v) => setForm((f) => ({ ...f, amount: v }))}
                    placeholder="0.00"
                  />
                  <FieldInput
                    label="Date"
                    type="date"
                    value={form.date}
                    onChange={(v) => setForm((f) => ({ ...f, date: v }))}
                  />
                </div>

                {/* Description */}
                <FieldInput
                  label="Description"
                  value={form.description}
                  onChange={(v) => setForm((f) => ({ ...f, description: v }))}
                  placeholder="e.g. Management fee Q1 2026"
                />

                {/* Journal Entry Link (optional) */}
                <FieldInput
                  label="Journal Entry ID (optional)"
                  value={form.journalEntryId}
                  onChange={(v) => setForm((f) => ({ ...f, journalEntryId: v }))}
                  placeholder="Leave blank if not linked"
                />
              </div>

              <div className="flex items-center justify-end gap-3 px-6 py-4 border-t border-[var(--ff-border-light)]">
                <button
                  onClick={() => setShowCreate(false)}
                  className="px-4 py-2 text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] transition-colors"
                >
                  Cancel
                </button>
                <button
                  onClick={handleCreate}
                  disabled={saving || !form.sourceCompanyId || !form.targetCompanyId || !form.amount}
                  className="flex items-center gap-2 px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 text-sm font-medium disabled:opacity-40 transition-colors"
                >
                  {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
                  Record
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/* ── Reusable sub-components ── */

function StatCard({
  label,
  value,
  sub,
  color,
}: {
  label: string;
  value: string;
  sub: string;
  color: string;
}) {
  return (
    <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
      <p className="text-xs text-[var(--ff-text-tertiary)] uppercase">{label}</p>
      <p className={`text-xl font-bold font-mono ${color}`}>{value}</p>
      <p className="text-xs text-[var(--ff-text-tertiary)]">{sub}</p>
    </div>
  );
}

function FieldInput({
  label,
  value,
  onChange,
  type = 'text',
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  type?: string;
  placeholder?: string;
}) {
  return (
    <label className="block">
      <span className="text-xs text-[var(--ff-text-tertiary)] uppercase">{label}</span>
      <input
        type={type}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder={placeholder}
        className="mt-1 w-full px-3 py-2 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)] placeholder:text-[var(--ff-text-tertiary)]"
      />
    </label>
  );
}

function FieldSelect({
  label,
  value,
  onChange,
  options,
  placeholder,
}: {
  label: string;
  value: string;
  onChange: (v: string) => void;
  options: { value: string; label: string }[];
  placeholder?: string;
}) {
  return (
    <label className="block">
      <span className="text-xs text-[var(--ff-text-tertiary)] uppercase">{label}</span>
      <select
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="mt-1 w-full px-3 py-2 text-sm bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] rounded-lg text-[var(--ff-text-primary)]"
      >
        {placeholder && <option value="">{placeholder}</option>}
        {options.map((o) => (
          <option key={o.value} value={o.value}>
            {o.label}
          </option>
        ))}
      </select>
    </label>
  );
}

/**
 * Elimination Adjustments Page
 * Manage intercompany elimination entries for consolidated reporting.
 */

import React, { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import {
  Building2,
  Loader2,
  AlertCircle,
  Plus,
  Zap,
  Send,
  RotateCcw,
  X,
  Trash2,
} from 'lucide-react';
import { apiFetch } from '@/lib/apiFetch';

/* ------------------------------------------------------------------ */
/*  Types                                                              */
/* ------------------------------------------------------------------ */

interface EntityGroup {
  id: string;
  name: string;
}

type EliminationType =
  | 'interco_revenue'
  | 'interco_balance'
  | 'unrealised_profit'
  | 'nci'
  | 'currency_translation'
  | 'goodwill';

type EliminationStatus = 'draft' | 'posted' | 'reversed';

interface EliminationAdjustment {
  id: string;
  number: string;
  type: EliminationType;
  description: string;
  period: string;
  status: EliminationStatus;
  amount: number;
  lines?: EliminationLine[];
}

interface EliminationLine {
  id?: string;
  groupAccountCode: string;
  groupAccountName?: string;
  debit: number;
  credit: number;
}

interface EliminationsResponse {
  items: EliminationAdjustment[];
  total: number;
}

/* ------------------------------------------------------------------ */
/*  Helpers                                                            */
/* ------------------------------------------------------------------ */

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const today = new Date();
const defaultPeriodStart = `${today.getFullYear()}-01-01`;
const defaultPeriodEnd = today.toISOString().substring(0, 10);

const selectClass =
  'px-3 py-2 rounded-lg bg-[var(--ff-bg-tertiary)] border border-[var(--ff-border-light)] text-[var(--ff-text-primary)] text-sm';
const inputClass = selectClass;

const ELIMINATION_TYPE_LABELS: Record<EliminationType, string> = {
  interco_revenue: 'Intercompany Revenue',
  interco_balance: 'Intercompany Balance',
  unrealised_profit: 'Unrealised Profit',
  nci: 'Non-Controlling Interest',
  currency_translation: 'Currency Translation',
  goodwill: 'Goodwill',
};

const STATUS_STYLES: Record<EliminationStatus, string> = {
  draft: 'bg-gray-500/10 text-gray-400',
  posted: 'bg-teal-500/10 text-teal-400',
  reversed: 'bg-amber-500/10 text-amber-400',
};

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

export default function EliminationsPage() {
  const [groups, setGroups] = useState<EntityGroup[]>([]);
  const [selectedGroupId, setSelectedGroupId] = useState('');
  const [periodStart, setPeriodStart] = useState(defaultPeriodStart);
  const [periodEnd, setPeriodEnd] = useState(defaultPeriodEnd);

  const [data, setData] = useState<EliminationsResponse | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [actionLoading, setActionLoading] = useState<string | null>(null);

  // Create modal state
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [formType, setFormType] = useState<EliminationType>('interco_revenue');
  const [formDescription, setFormDescription] = useState('');
  const [formPeriod, setFormPeriod] = useState(defaultPeriodEnd);
  const [formLines, setFormLines] = useState<EliminationLine[]>([
    { groupAccountCode: '', debit: 0, credit: 0 },
    { groupAccountCode: '', debit: 0, credit: 0 },
  ]);
  const [formError, setFormError] = useState('');
  const [formSaving, setFormSaving] = useState(false);

  /* ---------- Load available groups ---------- */
  useEffect(() => {
    apiFetch('/api/accounting/company-groups')
      .then(r => r.json())
      .then(json => {
        const items: EntityGroup[] = json.data?.items || json.data?.groups || json.data || [];
        setGroups(items);
        if (items.length > 0 && !selectedGroupId && items[0]) {
          setSelectedGroupId(items[0].id);
        }
      })
      .catch(() => {
        // Non-critical — group list load failure
      });
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /* ---------- Load eliminations ---------- */
  const loadData = useCallback(async () => {
    if (!selectedGroupId) return;
    setLoading(true);
    setError('');
    try {
      const params = new URLSearchParams({
        group_id: selectedGroupId,
        action: 'eliminations',
        period_start: periodStart,
        period_end: periodEnd,
      });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`);
      if (!res.ok) throw new Error('Failed to load elimination adjustments');
      const json = await res.json();
      const payload: EliminationsResponse = json.data || json;
      setData(payload);
    } catch {
      setError('Failed to load elimination adjustments');
      setData(null);
    } finally {
      setLoading(false);
    }
  }, [selectedGroupId, periodStart, periodEnd]);

  useEffect(() => {
    loadData();
  }, [loadData]);

  /* ---------- Actions ---------- */
  async function handleAutoGenerate() {
    if (!selectedGroupId) return;
    setActionLoading('auto-generate');
    try {
      const params = new URLSearchParams({ group_id: selectedGroupId });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'auto-eliminate',
          period_start: periodStart,
          period_end: periodEnd,
        }),
      });
      if (!res.ok) {
        const json = await res.json();
        throw new Error(json.message || 'Auto-generation failed');
      }
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Auto-generation failed');
    } finally {
      setActionLoading(null);
    }
  }

  async function handlePost(adjustmentId: string) {
    if (!selectedGroupId) return;
    setActionLoading(adjustmentId);
    try {
      const params = new URLSearchParams({ group_id: selectedGroupId });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'post-elimination',
          elimination_id: adjustmentId,
        }),
      });
      if (!res.ok) {
        const json = await res.json();
        throw new Error(json.message || 'Failed to post elimination');
      }
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to post elimination');
    } finally {
      setActionLoading(null);
    }
  }

  async function handleReverse(adjustmentId: string) {
    if (!selectedGroupId) return;
    setActionLoading(adjustmentId);
    try {
      const params = new URLSearchParams({ group_id: selectedGroupId });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'reverse-elimination',
          elimination_id: adjustmentId,
        }),
      });
      if (!res.ok) {
        const json = await res.json();
        throw new Error(json.message || 'Failed to reverse elimination');
      }
      await loadData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to reverse elimination');
    } finally {
      setActionLoading(null);
    }
  }

  /* ---------- Create Modal ---------- */
  function resetForm() {
    setFormType('interco_revenue');
    setFormDescription('');
    setFormPeriod(defaultPeriodEnd);
    setFormLines([
      { groupAccountCode: '', debit: 0, credit: 0 },
      { groupAccountCode: '', debit: 0, credit: 0 },
    ]);
    setFormError('');
  }

  function addLine() {
    setFormLines(prev => [...prev, { groupAccountCode: '', debit: 0, credit: 0 }]);
  }

  function removeLine(idx: number) {
    setFormLines(prev => prev.filter((_, i) => i !== idx));
  }

  function updateLine(idx: number, field: keyof EliminationLine, value: string | number) {
    setFormLines(prev =>
      prev.map((line, i) => (i === idx ? { ...line, [field]: value } : line)),
    );
  }

  async function handleCreateSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!selectedGroupId) return;

    const totalDebit = formLines.reduce((s, l) => s + Number(l.debit || 0), 0);
    const totalCredit = formLines.reduce((s, l) => s + Number(l.credit || 0), 0);
    if (Math.abs(totalDebit - totalCredit) > 0.01) {
      setFormError(`Debits (${fmt(totalDebit)}) must equal credits (${fmt(totalCredit)})`);
      return;
    }
    if (formLines.some(l => !l.groupAccountCode)) {
      setFormError('All lines must have a group account code');
      return;
    }

    setFormSaving(true);
    setFormError('');
    try {
      const params = new URLSearchParams({ group_id: selectedGroupId });
      const res = await apiFetch(`/api/accounting/consolidated-reports?${params}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'create-elimination',
          type: formType,
          description: formDescription,
          period: formPeriod,
          lines: formLines.map(l => ({
            group_account_code: l.groupAccountCode,
            debit: Number(l.debit || 0),
            credit: Number(l.credit || 0),
          })),
        }),
      });
      if (!res.ok) {
        const json = await res.json();
        throw new Error(json.message || 'Failed to create elimination');
      }
      setShowCreateModal(false);
      resetForm();
      await loadData();
    } catch (err) {
      setFormError(err instanceof Error ? err.message : 'Failed to create elimination');
    } finally {
      setFormSaving(false);
    }
  }

  const items = data?.items || [];

  /* ---------------------------------------------------------------- */
  /*  Render                                                           */
  /* ---------------------------------------------------------------- */
  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between flex-wrap gap-3">
            <div className="flex items-center gap-3">
              <div className="p-2 rounded-lg bg-teal-500/10">
                <Building2 className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">
                  Elimination Adjustments
                </h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  Intercompany eliminations for consolidated reporting
                </p>
              </div>
            </div>
            <div className="flex items-center gap-3 flex-wrap">
              <select
                value={selectedGroupId}
                onChange={e => setSelectedGroupId(e.target.value)}
                className={selectClass}
              >
                {groups.length === 0 && <option value="">No groups</option>}
                {groups.map(g => (
                  <option key={g.id} value={g.id}>{g.name}</option>
                ))}
              </select>
              <input
                type="date"
                value={periodStart}
                onChange={e => setPeriodStart(e.target.value)}
                className={inputClass}
              />
              <input
                type="date"
                value={periodEnd}
                onChange={e => setPeriodEnd(e.target.value)}
                className={inputClass}
              />
              <button
                onClick={handleAutoGenerate}
                disabled={!selectedGroupId || actionLoading === 'auto-generate'}
                className="inline-flex items-center gap-2 px-4 py-2 bg-amber-600 text-white rounded-lg hover:bg-amber-700 text-sm font-medium disabled:opacity-50"
              >
                {actionLoading === 'auto-generate' ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <Zap className="h-4 w-4" />
                )}
                Auto-Generate
              </button>
              <button
                onClick={() => { resetForm(); setShowCreateModal(true); }}
                className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium"
              >
                <Plus className="h-4 w-4" /> Manual Elimination
              </button>
            </div>
          </div>
        </div>

        <div className="p-6">
          {/* Error banner */}
          {error && (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm mb-6">
              <AlertCircle className="h-4 w-4 shrink-0" /> {error}
            </div>
          )}

          {/* States: loading / empty / list */}
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <Loader2 className="h-8 w-8 animate-spin text-teal-500" />
            </div>
          ) : items.length === 0 ? (
            <div className="text-center py-12">
              <Building2 className="h-12 w-12 text-[var(--ff-text-tertiary)] mx-auto mb-3" />
              <p className="text-[var(--ff-text-secondary)]">
                No elimination adjustments found
              </p>
              <p className="text-sm text-[var(--ff-text-tertiary)] mt-1">
                Use &ldquo;Auto-Generate&rdquo; to detect intercompany transactions or create manually
              </p>
            </div>
          ) : (
            <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] overflow-hidden">
              <table className="w-full text-sm">
                <thead>
                  <tr className="border-b border-[var(--ff-border-light)] text-left text-[var(--ff-text-secondary)]">
                    <th className="px-4 py-3">Number</th>
                    <th className="px-4 py-3">Type</th>
                    <th className="px-4 py-3">Description</th>
                    <th className="px-4 py-3">Period</th>
                    <th className="px-4 py-3">Status</th>
                    <th className="px-4 py-3 text-right">Amount</th>
                    <th className="px-4 py-3 text-right">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {items.map(adj => (
                    <tr
                      key={adj.id}
                      className="border-b border-[var(--ff-border-light)] hover:bg-[var(--ff-bg-primary)]/50"
                    >
                      <td className="px-4 py-3 font-mono text-[var(--ff-text-tertiary)]">
                        {adj.number}
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-primary)]">
                        {ELIMINATION_TYPE_LABELS[adj.type] || adj.type}
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-secondary)] max-w-xs truncate">
                        {adj.description}
                      </td>
                      <td className="px-4 py-3 text-[var(--ff-text-tertiary)] font-mono text-xs">
                        {adj.period}
                      </td>
                      <td className="px-4 py-3">
                        <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${STATUS_STYLES[adj.status]}`}>
                          {adj.status}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-right font-mono text-[var(--ff-text-primary)]">
                        {fmt(adj.amount)}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <div className="flex items-center justify-end gap-1">
                          {adj.status === 'draft' && (
                            <button
                              onClick={() => handlePost(adj.id)}
                              disabled={actionLoading === adj.id}
                              title="Post elimination"
                              className="inline-flex items-center gap-1 px-2.5 py-1.5 bg-teal-600 text-white rounded-md hover:bg-teal-700 text-xs font-medium disabled:opacity-50"
                            >
                              {actionLoading === adj.id ? (
                                <Loader2 className="h-3 w-3 animate-spin" />
                              ) : (
                                <Send className="h-3 w-3" />
                              )}
                              Post
                            </button>
                          )}
                          {adj.status === 'posted' && (
                            <button
                              onClick={() => handleReverse(adj.id)}
                              disabled={actionLoading === adj.id}
                              title="Reverse elimination"
                              className="inline-flex items-center gap-1 px-2.5 py-1.5 bg-amber-600 text-white rounded-md hover:bg-amber-700 text-xs font-medium disabled:opacity-50"
                            >
                              {actionLoading === adj.id ? (
                                <Loader2 className="h-3 w-3 animate-spin" />
                              ) : (
                                <RotateCcw className="h-3 w-3" />
                              )}
                              Reverse
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* ---------- Create Elimination Modal ---------- */}
        {showCreateModal && (
          <div className="fixed inset-0 bg-black/60 flex items-center justify-center z-50 p-4">
            <div className="bg-[var(--ff-surface-primary)] rounded-xl border border-[var(--ff-border-light)] w-full max-w-2xl max-h-[90vh] overflow-y-auto">
              <div className="flex items-center justify-between px-6 py-4 border-b border-[var(--ff-border-light)]">
                <h2 className="text-lg font-bold text-[var(--ff-text-primary)]">
                  Create Manual Elimination
                </h2>
                <button
                  onClick={() => setShowCreateModal(false)}
                  className="p-1 rounded hover:bg-[var(--ff-bg-tertiary)] text-[var(--ff-text-tertiary)]"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>

              <form onSubmit={handleCreateSubmit} className="p-6 space-y-4">
                {formError && (
                  <div className="flex items-center gap-2 p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">
                    <AlertCircle className="h-4 w-4 shrink-0" /> {formError}
                  </div>
                )}

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Type</label>
                    <select
                      value={formType}
                      onChange={e => setFormType(e.target.value as EliminationType)}
                      className={selectClass + ' w-full'}
                    >
                      {(Object.keys(ELIMINATION_TYPE_LABELS) as EliminationType[]).map(t => (
                        <option key={t} value={t}>{ELIMINATION_TYPE_LABELS[t]}</option>
                      ))}
                    </select>
                  </div>
                  <div>
                    <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Period</label>
                    <input
                      type="date"
                      value={formPeriod}
                      onChange={e => setFormPeriod(e.target.value)}
                      className={inputClass + ' w-full'}
                    />
                  </div>
                </div>

                <div>
                  <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Description</label>
                  <input
                    type="text"
                    value={formDescription}
                    onChange={e => setFormDescription(e.target.value)}
                    placeholder="Describe the elimination adjustment..."
                    className={inputClass + ' w-full'}
                    required
                  />
                </div>

                {/* Lines */}
                <div>
                  <div className="flex items-center justify-between mb-2">
                    <label className="text-xs text-[var(--ff-text-tertiary)]">Journal Lines</label>
                    <button
                      type="button"
                      onClick={addLine}
                      className="inline-flex items-center gap-1 text-xs text-teal-400 hover:text-teal-300"
                    >
                      <Plus className="h-3 w-3" /> Add Line
                    </button>
                  </div>
                  <div className="space-y-2">
                    <div className="grid grid-cols-[1fr_100px_100px_32px] gap-2 text-xs text-[var(--ff-text-tertiary)]">
                      <span>Group Account Code</span>
                      <span className="text-right">Debit</span>
                      <span className="text-right">Credit</span>
                      <span />
                    </div>
                    {formLines.map((line, idx) => (
                      <div key={idx} className="grid grid-cols-[1fr_100px_100px_32px] gap-2">
                        <input
                          type="text"
                          value={line.groupAccountCode}
                          onChange={e => updateLine(idx, 'groupAccountCode', e.target.value)}
                          placeholder="e.g. 4000"
                          className={inputClass + ' w-full'}
                          required
                        />
                        <input
                          type="number"
                          step="0.01"
                          min="0"
                          value={line.debit || ''}
                          onChange={e => updateLine(idx, 'debit', parseFloat(e.target.value) || 0)}
                          placeholder="0.00"
                          className={inputClass + ' w-full text-right'}
                        />
                        <input
                          type="number"
                          step="0.01"
                          min="0"
                          value={line.credit || ''}
                          onChange={e => updateLine(idx, 'credit', parseFloat(e.target.value) || 0)}
                          placeholder="0.00"
                          className={inputClass + ' w-full text-right'}
                        />
                        <button
                          type="button"
                          onClick={() => removeLine(idx)}
                          disabled={formLines.length <= 2}
                          className="p-1.5 rounded hover:bg-red-500/10 text-[var(--ff-text-tertiary)] hover:text-red-400 disabled:opacity-30"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>
                    ))}
                  </div>
                  <div className="grid grid-cols-[1fr_100px_100px_32px] gap-2 mt-2 pt-2 border-t border-[var(--ff-border-light)] text-xs font-medium text-[var(--ff-text-primary)]">
                    <span>Totals</span>
                    <span className="text-right font-mono">
                      {fmt(formLines.reduce((s, l) => s + Number(l.debit || 0), 0))}
                    </span>
                    <span className="text-right font-mono">
                      {fmt(formLines.reduce((s, l) => s + Number(l.credit || 0), 0))}
                    </span>
                    <span />
                  </div>
                </div>

                <div className="flex justify-end gap-3 pt-4 border-t border-[var(--ff-border-light)]">
                  <button
                    type="button"
                    onClick={() => setShowCreateModal(false)}
                    className="px-4 py-2 rounded-lg border border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:bg-[var(--ff-bg-tertiary)] text-sm"
                  >
                    Cancel
                  </button>
                  <button
                    type="submit"
                    disabled={formSaving}
                    className="inline-flex items-center gap-2 px-4 py-2 bg-teal-600 text-white rounded-lg hover:bg-teal-700 text-sm font-medium disabled:opacity-50"
                  >
                    {formSaving ? (
                      <Loader2 className="h-4 w-4 animate-spin" />
                    ) : (
                      <Plus className="h-4 w-4" />
                    )}
                    Create Elimination
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}
      </div>
    </AppLayout>
  );
}

/**
 * Payroll Service
 * Handles employee management, payroll runs, payslip generation,
 * and GL journal posting for SA payroll.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import {
  calculateMonthlyPAYE,
  calculateUIF,
  calculateSDL,
  calculateAgeFromIdNumber,
} from './taxTables';
import type {
  EmployeeWithPay,
  PayStructure,
  PayrollRun,
  PayrollRunWithPayslips,
  Payslip,
  CreateEmployeeInput,
  UpdateEmployeeInput,
  CustomDeduction,
} from './types';
import {
  createJournalEntry,
  postJournalEntry,
} from '@/modules/accounting/services/journalEntryService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = Record<string, any>;

// ── Employee Functions ──────────────────────────────────────────────────────

export async function listEmployees(
  companyId: string,
  search?: string,
  statusFilter?: string
): Promise<EmployeeWithPay[]> {
  try {
    const searchTerm = search ? `%${search}%` : null;
    let rows: Row[];

    if (searchTerm && statusFilter) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.company_id = ${companyId}::UUID
          AND e.status = ${statusFilter}
          AND (
            e.first_name ILIKE ${searchTerm}
            OR e.last_name ILIKE ${searchTerm}
            OR e.employee_number ILIKE ${searchTerm}
            OR e.department ILIKE ${searchTerm}
          )
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else if (searchTerm) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.company_id = ${companyId}::UUID
          AND (
            e.first_name ILIKE ${searchTerm}
            OR e.last_name ILIKE ${searchTerm}
            OR e.employee_number ILIKE ${searchTerm}
            OR e.department ILIKE ${searchTerm}
          )
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else if (statusFilter) {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.company_id = ${companyId}::UUID
          AND e.status = ${statusFilter}
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT e.*,
          ps.id AS ps_id, ps.basic_salary, ps.travel_allowance,
          ps.housing_allowance, ps.cell_allowance, ps.other_allowances,
          ps.medical_aid_contribution, ps.retirement_fund_contribution_pct,
          ps.custom_deductions, ps.effective_from, ps.effective_to
        FROM employees e
        LEFT JOIN LATERAL (
          SELECT * FROM pay_structures p
          WHERE p.employee_id = e.id
            AND p.effective_from <= CURRENT_DATE
            AND (p.effective_to IS NULL OR p.effective_to >= CURRENT_DATE)
          ORDER BY p.effective_from DESC
          LIMIT 1
        ) ps ON TRUE
        WHERE e.company_id = ${companyId}::UUID
        ORDER BY e.employee_number ASC
        LIMIT 200
      `) as Row[];
    }

    return rows.map(mapEmployeeWithPay);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (message.includes('does not exist')) return [];
    log.error('listEmployees failed', { error: message }, 'payroll');
    throw err;
  }
}

