    subject: `You've been invited to join ${options.companyName} on ISAFlow`,
    html: inviteEmailHtml(inviteData),
  });
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 5
 * Financial Reporting Service
 *
 * Income Statement, Balance Sheet, VAT Return, Project Profitability
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccount } from './systemAccountResolver';
import type {
  IncomeStatementReport,
  BalanceSheetReport,
  VATReturnReport,
  ProjectProfitabilityReport,
} from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface ReportLineItem {
  accountCode: string;
  accountName: string;
  amount: number;
}

interface BSLineItem {
  accountCode: string;
  accountName: string;
  balance: number;
}

// ── Income Statement (P&L) ───────────────────────────────────────────────────

interface ISOptions {
  projectId?: string;
  costCentreId?: string;
}

/** Fetch P&L line items for a single period. Reused for comparative calls. */
async function fetchIncomeStatementRows(
  companyId: string,
  periodStart: string,
  periodEnd: string,
  opts: ISOptions
) {
  const projId = opts.projectId ?? null;
  const ccId = opts.costCentreId ?? null;

  const rows = (await sql`
    SELECT ga.account_code, ga.account_name, ga.account_type, ga.account_subtype,
      COALESCE(SUM(jl.debit), 0) AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.company_id = ${companyId}::UUID
      AND je.entry_date >= ${periodStart}
      AND je.entry_date <= ${periodEnd}
      AND ga.account_type IN ('revenue', 'expense')
      AND (${projId}::TEXT IS NULL OR jl.project_id = ${projId}::UUID)
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
    GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.account_subtype
    ORDER BY ga.account_code
  `) as Row[];

  const revenue: ReportLineItem[] = [];
  const costOfSales: ReportLineItem[] = [];
  const operatingExpenses: ReportLineItem[] = [];

  for (const r of rows) {
    const type = String(r.account_type);
    const subtype = r.account_subtype ? String(r.account_subtype) : '';
    const debit = Number(r.total_debit);
    const credit = Number(r.total_credit);

    if (type === 'revenue') {
      const amount = credit - debit;
      if (Math.abs(amount) > 0.001) {
        revenue.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
      }
    } else if (type === 'expense') {
      const amount = debit - credit;
      if (Math.abs(amount) > 0.001) {
        const item = { accountCode: String(r.account_code), accountName: String(r.account_name), amount };
        if (subtype === 'cost_of_sales') costOfSales.push(item);
        else operatingExpenses.push(item);
      }
    }
  }

  const totalRevenue = revenue.reduce((s, i) => s + i.amount, 0);
  const totalCostOfSales = costOfSales.reduce((s, i) => s + i.amount, 0);
  const grossProfit = totalRevenue - totalCostOfSales;
  const totalOperatingExpenses = operatingExpenses.reduce((s, i) => s + i.amount, 0);
  const netProfit = grossProfit - totalOperatingExpenses;

  return { revenue, costOfSales, operatingExpenses, totalRevenue, totalCostOfSales, grossProfit, totalOperatingExpenses, netProfit };
}

export async function getIncomeStatement(companyId: string,
  periodStart: string,
  periodEnd: string,
  opts: ISOptions = {},
  comparePeriod?: { start: string; end: string }
): Promise<IncomeStatementReport> {
  try {
    const [current, prior] = await Promise.all([
      fetchIncomeStatementRows(companyId, periodStart, periodEnd, opts),
      comparePeriod
        ? fetchIncomeStatementRows(companyId, comparePeriod.start, comparePeriod.end, opts)
        : Promise.resolve(null),
    ]);

    const report: IncomeStatementReport = {
      periodStart,
      periodEnd,
      projectId: opts.projectId,
      costCentreId: opts.costCentreId,
      revenue: current.revenue,
      costOfSales: current.costOfSales,
      operatingExpenses: current.operatingExpenses,
      totalRevenue: current.totalRevenue,
      totalCostOfSales: current.totalCostOfSales,
      grossProfit: current.grossProfit,
      totalOperatingExpenses: current.totalOperatingExpenses,
      netProfit: current.netProfit,
    };

    if (comparePeriod && prior) {
      report.comparativePeriod = comparePeriod;
      report.priorTotalRevenue = prior.totalRevenue;
      report.priorTotalCostOfSales = prior.totalCostOfSales;
      report.priorGrossProfit = prior.grossProfit;
      report.priorTotalOperatingExpenses = prior.totalOperatingExpenses;
      report.priorNetProfit = prior.netProfit;

      const mergeLineItems = (curr: ReportLineItem[], prev: ReportLineItem[]) => {
        const priorMap = new Map(prev.map(p => [p.accountCode, p.amount]));
        return curr.map(c => {
          const pa = priorMap.get(c.accountCode) ?? 0;
          const variance = c.amount - pa;
          return { ...c, priorAmount: pa, variance, variancePct: pa !== 0 ? (variance / Math.abs(pa)) * 100 : 0 };
        });
      };
      report.revenue = mergeLineItems(current.revenue, prior.revenue);
      report.costOfSales = mergeLineItems(current.costOfSales, prior.costOfSales);
      report.operatingExpenses = mergeLineItems(current.operatingExpenses, prior.operatingExpenses);
    }

    return report;
  } catch (err) {
    log.error('Failed to generate income statement', { error: err }, 'accounting');
    throw err;
  }
}

// ── Balance Sheet ────────────────────────────────────────────────────────────

/** Fetch balance sheet data for a single date. Reused for comparative calls. */
async function fetchBalanceSheetData(companyId: string, asAtDate: string, costCentreId?: string) {
  const ccId = costCentreId ?? null;

  const rows = (await sql`
    SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
      COALESCE(SUM(jl.debit), 0) AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.company_id = ${companyId}::UUID
      AND je.entry_date <= ${asAtDate}
      AND ga.account_type IN ('asset', 'liability', 'equity')
      AND ga.level >= 3
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
    GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance
    ORDER BY ga.account_code
  `) as Row[];

  const assets: BSLineItem[] = [];
  const liabilities: BSLineItem[] = [];
  const equity: BSLineItem[] = [];

  for (const r of rows) {
    const type = String(r.account_type);
    const normalBal = String(r.normal_balance);
    const debit = Number(r.total_debit);
    const credit = Number(r.total_credit);
    const balance = normalBal === 'debit' ? debit - credit : credit - debit;
    if (Math.abs(balance) < 0.01) continue;

    const item: BSLineItem = { accountCode: String(r.account_code), accountName: String(r.account_name), balance };
    if (type === 'asset') assets.push(item);
    else if (type === 'liability') liabilities.push(item);
    else if (type === 'equity') equity.push(item);
  }

  const retainedEarnings = await calculateRetainedEarnings(companyId, asAtDate, costCentreId);
  if (Math.abs(retainedEarnings) > 0.01) {
    const reAccount = await getSystemAccount('retained_earnings');
    const existing = equity.find(e => e.accountCode === reAccount.accountCode);
    if (existing) existing.balance += retainedEarnings;
    else equity.push({ accountCode: reAccount.accountCode, accountName: 'Retained Earnings (Current)', balance: retainedEarnings });
  }

  return { assets, liabilities, equity };
}

export async function getBalanceSheet(companyId: string,
  asAtDate: string,
  costCentreId?: string,
  compareDate?: string
): Promise<BalanceSheetReport> {
  try {
    const [current, prior] = await Promise.all([
      fetchBalanceSheetData(companyId, asAtDate, costCentreId),
      compareDate
        ? fetchBalanceSheetData(companyId, compareDate, costCentreId)
        : Promise.resolve(null),
    ]);

    const report: BalanceSheetReport = {
      asAtDate,
      costCentreId,
      assets: current.assets,
      liabilities: current.liabilities,
      equity: current.equity,
      totalAssets: current.assets.reduce((s, a) => s + a.balance, 0),
      totalLiabilities: current.liabilities.reduce((s, l) => s + l.balance, 0),
      totalEquity: current.equity.reduce((s, e) => s + e.balance, 0),
    };

    if (compareDate && prior) {
      report.compareDate = compareDate;
      report.priorTotalAssets = prior.assets.reduce((s, a) => s + a.balance, 0);
      report.priorTotalLiabilities = prior.liabilities.reduce((s, l) => s + l.balance, 0);
      report.priorTotalEquity = prior.equity.reduce((s, e) => s + e.balance, 0);

      const mergeBSLines = (curr: BSLineItem[], prev: BSLineItem[]) => {
        const priorMap = new Map(prev.map(p => [p.accountCode, p.balance]));
        return curr.map(c => {
          const pb = priorMap.get(c.accountCode) ?? 0;
          const variance = c.balance - pb;
          return { ...c, priorBalance: pb, variance, variancePct: pb !== 0 ? (variance / Math.abs(pb)) * 100 : 0 };
        });
      };
      report.assets = mergeBSLines(current.assets, prior.assets);
      report.liabilities = mergeBSLines(current.liabilities, prior.liabilities);
      report.equity = mergeBSLines(current.equity, prior.equity);
    }

    return report;
  } catch (err) {
    log.error('Failed to generate balance sheet', { error: err }, 'accounting');
    throw err;
  }
}

async function calculateRetainedEarnings(companyId: string, asAtDate: string, costCentreId?: string): Promise<number> {
  const ccId = costCentreId ?? null;
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
      COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.company_id = ${companyId}::UUID
      AND je.entry_date <= ${asAtDate}
      AND ga.account_type IN ('revenue', 'expense')
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
  `) as Row[];

  return Number(rows[0]!.revenue) - Number(rows[0]!.expenses);
}

// ── VAT201 Return (SA SARS) ─────────────────────────────────────────────────

interface VAT201BoxDef {
  box: string;
  label: string;
  accountType: 'liability' | 'asset';
  vatTypes: string[];
}

const OUTPUT_BOXES: VAT201BoxDef[] = [
  { box: '1',   label: 'Standard rated supplies',           accountType: 'liability', vatTypes: ['standard'] },
  { box: '1A',  label: 'Capital goods/services supplied',   accountType: 'liability', vatTypes: ['capital_goods'] },
  { box: '2',   label: 'Zero-rated supplies (domestic)',    accountType: 'liability', vatTypes: ['zero_rated'] },
  { box: '2A',  label: 'Zero-rated exports',                accountType: 'liability', vatTypes: ['export'] },
  { box: '3',   label: 'Exempt supplies',                   accountType: 'liability', vatTypes: ['exempt'] },
  { box: '12',  label: 'Imported services / other output',  accountType: 'liability', vatTypes: ['reverse_charge', 'imported'] },
];

const INPUT_BOXES: VAT201BoxDef[] = [
  { box: '14',      label: 'Capital goods/services purchased', accountType: 'asset', vatTypes: ['capital_goods'] },
  { box: '15',      label: 'Other goods/services purchased',   accountType: 'asset', vatTypes: ['standard'] },
  { box: '14A/15A', label: 'Goods imported',                   accountType: 'asset', vatTypes: ['imported'] },
  { box: '16',      label: 'Change in use',                    accountType: 'asset', vatTypes: ['reverse_charge'] },
  { box: '17',      label: 'Bad debts',                        accountType: 'asset', vatTypes: ['bad_debt'] },
  { box: '18',      label: 'Other adjustments',                accountType: 'asset', vatTypes: ['exempt', 'no_vat'] },
];

/** Line-level transaction shape used in drill-down arrays. */
interface VATDrillDown {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  description: string;
  sourceDocument?: string;
  amount: number;
}

/** Populated VAT201 box with transactions list. */
interface PopulatedBox {
  box: string;
  label: string;
  amount: number;
  transactions: VATDrillDown[];
}

export async function getVATReturn(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<VATReturnReport> {
  try {
    const vatLines = (await sql`
      SELECT
        jl.id              AS line_id,
        jl.gl_account_id,
        jl.debit,
        jl.credit,
        jl.vat_type,
        jl.description     AS line_description,
        je.id              AS journal_entry_id,
        je.entry_number,
        je.entry_date,
        je.description     AS entry_description,
        je.source_document_id,
        ga.account_code,
        ga.account_name,
        ga.account_type,
        ga.account_subtype
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga        ON ga.id  = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND (
          ga.account_subtype IN ('vat_input', 'vat_output', 'tax')
        )
      ORDER BY je.entry_date, je.entry_number
    `) as Row[];

    /** Build a drill-down transaction object from a raw journal line. */
    const toDrillDown = (l: Row, signFn: (debit: number, credit: number) => number): VATDrillDown => ({
      journalEntryId: String(l.journal_entry_id),
      entryNumber:    String(l.entry_number),
      entryDate:      String(l.entry_date),
      description:    l.entry_description
        ? String(l.entry_description)
        : l.line_description
          ? String(l.line_description)
          : '',
      sourceDocument: l.source_document_id ? String(l.source_document_id) : undefined,
      amount: signFn(Number(l.debit), Number(l.credit)),
    });

    // ── Output Boxes ────────────────────────────────────────────────────────
    const outputBoxes: PopulatedBox[] = OUTPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isOutput =
          String(l.account_type) === 'liability' ||
          String(l.account_subtype) === 'vat_output';
        const matchesType =
          l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isOutput && matchesType;
      });

      // Output VAT: credit increases the liability; net = credit - debit.
      const transactions = matching.map((l: Row) =>
        toDrillDown(l, (d, c) => c - d)
      );
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    // Unclassified output lines (vat_type IS NULL) default to Box 1 — standard.
    const unclassifiedOutput = vatLines.filter((l: Row) => {
      const isOutput =
        String(l.account_type) === 'liability' ||
        String(l.account_subtype) === 'vat_output';
      return isOutput && l.vat_type == null;
    });
    if (unclassifiedOutput.length > 0) {
      const box1 = outputBoxes.find((b) => b.box === '1');
      if (box1) {
        const extra = unclassifiedOutput.map((l: Row) =>
          toDrillDown(l, (d, c) => c - d)
        );
        box1.amount += extra.reduce((s, t) => s + t.amount, 0);
        box1.transactions.push(...extra);
      }
    }

    // ── Input Boxes ──────────────────────────────────────────────────────────
    const inputBoxes: PopulatedBox[] = INPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isInput =
          String(l.account_type) === 'asset' ||
          String(l.account_subtype) === 'vat_input';
        const matchesType =
          l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isInput && matchesType;
      });

      // Input VAT: debit increases the asset; net = debit - credit.
      const transactions = matching.map((l: Row) =>
        toDrillDown(l, (d, c) => d - c)
      );
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    // Unclassified input lines (vat_type IS NULL) default to Box 15 — standard purchases.
    const unclassifiedInput = vatLines.filter((l: Row) => {
      const isInput =
        String(l.account_type) === 'asset' ||
        String(l.account_subtype) === 'vat_input';
      return isInput && l.vat_type == null;
    });
    if (unclassifiedInput.length > 0) {
      const box15 = inputBoxes.find((b) => b.box === '15');
      if (box15) {
        const extra = unclassifiedInput.map((l: Row) =>
          toDrillDown(l, (d, c) => d - c)
        );
        box15.amount += extra.reduce((s, t) => s + t.amount, 0);
        box15.transactions.push(...extra);
      }
    }

    // ── Totals ───────────────────────────────────────────────────────────────
    const totalOutputTax = outputBoxes.reduce((s, b) => s + b.amount, 0);
    const totalInputTax  = inputBoxes.reduce((s, b) => s + b.amount, 0);
    const netVAT         = totalOutputTax - totalInputTax;

    // Legacy compatibility fields — summarise non-zero boxes as account-like lines.
    const outputDetails = outputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));
    const inputDetails = inputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));

    return {
      periodStart,
      periodEnd,
      outputBoxes,
      totalOutputTax,
      inputBoxes,
      totalInputTax,
      netVAT,
      outputVAT: totalOutputTax,
      inputVAT:  totalInputTax,
      outputDetails,
      inputDetails,
    };
  } catch (err) {
    log.error('Failed to generate VAT return', { error: err }, 'accounting');
    throw err;
  }
}

// ── Project Profitability ────────────────────────────────────────────────────

export async function getProjectProfitability(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<ProjectProfitabilityReport[]> {
  try {
    const projectRows = (await sql`
      SELECT DISTINCT jl.project_id, p.project_name
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      LEFT JOIN projects p ON p.id = jl.project_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND jl.project_id IS NOT NULL
      ORDER BY p.project_name
    `) as Row[];

    const reports: ProjectProfitabilityReport[] = [];

    for (const proj of projectRows) {
      const projectId = String(proj.project_id);
      const projectName = proj.project_name ? String(proj.project_name) : 'Unknown Project';

      const rows = (await sql`
        SELECT ga.account_code, ga.account_name, ga.account_type,
          COALESCE(SUM(jl.debit), 0) AS total_debit,
          COALESCE(SUM(jl.credit), 0) AS total_credit
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${periodStart}
          AND je.entry_date <= ${periodEnd}
          AND jl.project_id = ${projectId}::UUID
          AND ga.account_type IN ('revenue', 'expense')
        GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
        ORDER BY ga.account_code
      `) as Row[];

      const revenueLines: ReportLineItem[] = [];
      const costLines: ReportLineItem[] = [];

      for (const r of rows) {
        const type = String(r.account_type);
        const debit = Number(r.total_debit);
        const credit = Number(r.total_credit);

        if (type === 'revenue') {
          const amount = credit - debit;
          if (Math.abs(amount) > 0.001) {
            revenueLines.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
          }
        } else if (type === 'expense') {
          const amount = debit - credit;
          if (Math.abs(amount) > 0.001) {
            costLines.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
          }
        }
      }

      const revenue = revenueLines.reduce((s, r) => s + r.amount, 0);
      const costs = costLines.reduce((s, c) => s + c.amount, 0);
      const profit = revenue - costs;
      const margin = revenue > 0 ? (profit / revenue) * 100 : 0;

      reports.push({
        projectId,
        projectName,
        periodStart,
        periodEnd,
        revenue,
        costs,
        profit,
        margin: Math.round(margin * 100) / 100,
        revenueLines,
        costLines,
      });
    }

    // Sort by profit DESC
    reports.sort((a, b) => b.profit - a.profit);
    return reports;
  } catch (err) {
    log.error('Failed to generate project profitability', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * Approval Workflow Service
 * Configurable approval rules for financial documents.
 * Checks if documents require approval before processing.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type DocumentType = 'customer_invoice' | 'supplier_invoice' | 'payment' | 'journal_entry' | 'credit_note';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected' | 'cancelled';

export interface ApprovalRule {
  id: string;
  name: string;
  documentType: DocumentType;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
  priority: number;
  createdAt: string;
}

export interface ApprovalRequest {
  id: string;
  ruleId: string;
  ruleName?: string;
  documentType: DocumentType;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: ApprovalStatus;
  requestedBy: string;
  requestedByName?: string;
  requestedAt: string;
  decidedBy: string | null;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

export interface ApprovalCheckResult {
  requiresApproval: boolean;
  matchedRule: ApprovalRule | null;
  existingRequest: ApprovalRequest | null;
}

// ── Rule CRUD ────────────────────────────────────────────────────────────────

export async function listRules(companyId?: string): Promise<ApprovalRule[]> {
  if (!companyId) return [];
  const rows = (await sql`
    SELECT * FROM approval_rules WHERE company_id = ${companyId} ORDER BY priority ASC, name ASC
  `) as Row[];
  return rows.map(mapRule);
}

export async function createRule(companyId: string, input: {
  name: string;
  documentType: DocumentType;
  conditionField?: string;
  conditionOperator?: string;
  conditionValue?: number;
  approverRole?: string;
}): Promise<ApprovalRule> {
  const rows = (await sql`
    INSERT INTO approval_rules (company_id, name, document_type, condition_field, condition_operator, condition_value, approver_role)
    VALUES (
      ${companyId}, ${input.name}, ${input.documentType},
      ${input.conditionField || 'total'}, ${input.conditionOperator || 'greater_than'},
      ${input.conditionValue || 0}, ${input.approverRole || 'admin'}
    ) RETURNING *
  `) as Row[];
  log.info('Created approval rule', { id: rows[0].id, name: input.name }, 'accounting');
  return mapRule(rows[0]);
}

export async function updateRule(companyId: string, id: string, input: Partial<{
  name: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
}>): Promise<ApprovalRule> {
  const rows = (await sql`
    UPDATE approval_rules SET
      name = COALESCE(${input.name ?? null}, name),
      condition_field = COALESCE(${input.conditionField ?? null}, condition_field),
      condition_operator = COALESCE(${input.conditionOperator ?? null}, condition_operator),
      condition_value = COALESCE(${input.conditionValue ?? null}, condition_value),
      approver_role = COALESCE(${input.approverRole ?? null}, approver_role),
      is_active = COALESCE(${input.isActive ?? null}, is_active),
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRule(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM approval_rules WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

// ── Approval Check ───────────────────────────────────────────────────────────

/** Check if a document requires approval based on active rules */
export async function checkApproval(
  companyId: string,
  documentType: DocumentType,
  documentId: string,
  amount: number
): Promise<ApprovalCheckResult> {
  // Check for existing pending request
  const existing = (await sql`
    SELECT ar.*, rl.name AS rule_name
    FROM approval_requests ar
    LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
    WHERE ar.company_id = ${companyId}
      AND ar.document_type = ${documentType}
      AND ar.document_id = ${documentId}::UUID
      AND ar.status = 'pending'
    LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    return {
      requiresApproval: true,
      matchedRule: null,
      existingRequest: mapRequest(existing[0]),
    };
  }

  // Find matching active rules
  const rules = (await sql`
    SELECT * FROM approval_rules
    WHERE company_id = ${companyId}
      AND document_type = ${documentType}
      AND is_active = true
    ORDER BY priority ASC
  `) as Row[];

  for (const rule of rules) {
    const r = mapRule(rule);
    let matches = false;

    switch (r.conditionOperator) {
      case 'any':
        matches = true;
        break;
      case 'greater_than':
        matches = amount > r.conditionValue;
        break;
      case 'greater_equal':
        matches = amount >= r.conditionValue;
        break;
    }

    if (matches) {
      return {
        requiresApproval: true,
        matchedRule: r,
        existingRequest: null,
      };
    }
  }

  return { requiresApproval: false, matchedRule: null, existingRequest: null };
}

// ── Approval Requests ────────────────────────────────────────────────────────

/** Create an approval request for a document */
export async function requestApproval(companyId: string, input: {
  ruleId: string;
  documentType: DocumentType;
  documentId: string;
  documentReference?: string;
  amount?: number;
  requestedBy: string;
}): Promise<ApprovalRequest> {
  const rows = (await sql`
    INSERT INTO approval_requests (company_id, rule_id, document_type, document_id, document_reference, amount, requested_by)
    VALUES (
      ${companyId}, ${input.ruleId}::UUID, ${input.documentType}, ${input.documentId}::UUID,
      ${input.documentReference || null}, ${input.amount || null}, ${input.requestedBy}::UUID
    ) RETURNING *
  `) as Row[];
  log.info('Approval requested', {
    id: rows[0].id,
    documentType: input.documentType,
    documentId: input.documentId,
  }, 'accounting');
  return mapRequest(rows[0]);
}

/** List approval requests with optional status filter */
export async function listRequests(companyId: string, status?: ApprovalStatus): Promise<ApprovalRequest[]> {
  const rows = status
    ? (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by::TEXT
        LEFT JOIN users u2 ON u2.id = ar.decided_by::TEXT
        WHERE ar.company_id = ${companyId} AND ar.status = ${status}
        ORDER BY ar.created_at DESC
      `) as Row[]
    : (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by::TEXT
        LEFT JOIN users u2 ON u2.id = ar.decided_by::TEXT
        WHERE ar.company_id = ${companyId}
        ORDER BY ar.created_at DESC
      `) as Row[];
  return rows.map(mapRequest);
}

/** Approve or reject a request */
export async function decideRequest(companyId: string, 
  requestId: string,
  decision: 'approved' | 'rejected',
  decidedBy: string,
  notes?: string
): Promise<ApprovalRequest> {
  const rows = (await sql`
    UPDATE approval_requests SET
      status = ${decision},
      decided_by = ${decidedBy}::UUID,
      decided_at = NOW(),
      decision_notes = ${notes || null}
    WHERE id = ${requestId}::UUID AND company_id = ${companyId} AND status = 'pending'
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Request ${requestId} not found or already decided`);
  log.info('Approval decided', { id: requestId, decision }, 'accounting');
  return mapRequest(rows[0]);
}

/** Get pending approval count for dashboard badge */
export async function getPendingCount(companyId?: string): Promise<number> {
  if (!companyId) return 0;
  const rows = (await sql`
    SELECT COUNT(*) AS count FROM approval_requests WHERE company_id = ${companyId} AND status = 'pending'
  `) as Row[];
  return Number(rows[0]?.count ?? 0);
}

// ── Mappers ──────────────────────────────────────────────────────────────────

function mapRule(r: Row): ApprovalRule {
  return {
    id: r.id,
    name: r.name,
    documentType: r.document_type,
    conditionField: r.condition_field,
    conditionOperator: r.condition_operator,
    conditionValue: Number(r.condition_value),
    approverRole: r.approver_role,
    isActive: r.is_active,
    priority: r.priority,
    createdAt: r.created_at,
  };
}

function mapRequest(r: Row): ApprovalRequest {
  return {
    id: r.id,
    ruleId: r.rule_id,
    ruleName: r.rule_name || undefined,
    documentType: r.document_type,
    documentId: r.document_id,
    documentReference: r.document_reference,
    amount: r.amount ? Number(r.amount) : null,
    status: r.status,
    requestedBy: r.requested_by,
    requestedByName: r.requested_by_name || undefined,
    requestedAt: r.requested_at,
    decidedBy: r.decided_by,
    decidedByName: r.decided_by_name || undefined,
    decidedAt: r.decided_at,
    decisionNotes: r.decision_notes,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * AR Aging Report Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { calculateAgingBuckets } from '../utils/aging';
import type { AgingBucket, AgingInvoice } from '../types/ap.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getARAging(companyId: string, asAtDate?: string): Promise<AgingBucket[]> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const rows = (await sql`
      SELECT ci.id, COALESCE(ci.client_id, ci.customer_id) AS entity_id, c.name AS entity_name,
        ci.due_date, ci.total_amount, ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS balance
      FROM customer_invoices ci
      JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
      WHERE ci.company_id = ${companyId}
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
        AND ci.due_date IS NOT NULL
      ORDER BY ci.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    // Include unallocated credit notes as negative balances
    const cnRows = (await sql`
      SELECT cn.id, cn.client_id AS entity_id, c.name AS entity_name,
        cn.credit_date AS due_date, cn.total_amount, 0 AS amount_paid,
        -cn.total_amount AS balance
      FROM credit_notes cn
      JOIN customers c ON c.id = cn.client_id
      WHERE cn.company_id = ${companyId}
        AND cn.type = 'customer' AND cn.status = 'approved'
        AND cn.customer_invoice_id IS NULL
    `) as Row[];

    for (const r of cnRows) {
      invoices.push({
        id: String(r.id),
        entityId: String(r.entity_id),
        entityName: String(r.entity_name),
        dueDate: String(r.due_date),
        totalAmount: Number(r.total_amount),
        amountPaid: Number(r.amount_paid),
        balance: Number(r.balance),
      });
    }

    return calculateAgingBuckets(invoices, asAt);
  } catch (err) {
    log.error('Failed to get AR aging', { error: err }, 'accounting');
    throw err;
  }
}

export async function getARAgingDetail(companyId: string, 
  clientId: string,
  asAtDate?: string
): Promise<{ client: { id: string; name: string }; invoices: AgingInvoice[]; buckets: AgingBucket | null }> {
  try {
    const asAt = asAtDate ? new Date(asAtDate) : new Date();

    const clientRows = (await sql`SELECT id, name AS name FROM customers WHERE id = ${clientId}::UUID AND company_id = ${companyId}`) as Row[];
    if (clientRows.length === 0) throw new Error(`Client ${clientId} not found`);

    const rows = (await sql`
      SELECT ci.id, COALESCE(ci.client_id, ci.customer_id) AS entity_id, c.name AS entity_name,
        ci.due_date, ci.invoice_number, ci.total_amount, ci.amount_paid,
        (ci.total_amount - ci.amount_paid) AS balance
      FROM customer_invoices ci
      JOIN customers c ON c.id = COALESCE(ci.client_id, ci.customer_id)
      WHERE ci.company_id = ${companyId}
        AND COALESCE(ci.client_id, ci.customer_id) = ${clientId}::UUID
        AND ci.status IN ('approved', 'sent', 'partially_paid', 'overdue')
        AND (ci.total_amount - ci.amount_paid) > 0
        AND ci.due_date IS NOT NULL
      ORDER BY ci.due_date
    `) as Row[];

    const invoices: AgingInvoice[] = rows.map((r: Row) => ({
      id: String(r.id),
      entityId: String(r.entity_id),
      entityName: String(r.entity_name),
      dueDate: String(r.due_date),
      totalAmount: Number(r.total_amount),
      amountPaid: Number(r.amount_paid),
      balance: Number(r.balance),
    }));

    const buckets = calculateAgingBuckets(invoices, asAt);
    return {
      client: { id: String(clientRows[0]!.id), name: String(clientRows[0]!.name) },
      invoices,
      buckets: buckets.length > 0 ? buckets[0]! : null,
    };
  } catch (err) {
    log.error('Failed to get AR aging detail', { clientId, error: err }, 'accounting');
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getFiscalPeriods(companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods WHERE company_id = ${companyId}
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(companyId: string, id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE company_id = ${companyId} AND fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (company_id, period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${companyId}, ${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(companyId, id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

    const openPrior = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND fiscal_year = ${period.fiscalYear}
        AND period_number < ${period.periodNumber}
        AND status = 'open'
    `) as Row[];
    if (Number(openPrior[0].cnt) > 0) {
      throw new Error('Cannot close period while prior periods are still open');
    }

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'closed', closed_by = ${userId}::UUID, closed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to close period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(companyId, id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(companyId, id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): FiscalPeriod {
  return {
    id: String(row.id),
    periodName: String(row.period_name),
    periodNumber: Number(row.period_number),
    fiscalYear: Number(row.fiscal_year),
    startDate: String(row.start_date),
    endDate: String(row.end_date),
    status: String(row.status) as FiscalPeriodStatus,
    closedBy: row.closed_by ? String(row.closed_by) : undefined,
    closedAt: row.closed_at ? String(row.closed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Cross-Module GL Integration Hooks
 * - Asset depreciation → DR Depreciation Expense, CR Accumulated Depreciation
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccountId } from './systemAccountResolver';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Asset Depreciation → GL ────────────────────────────────────────────────

export async function postAssetDepreciationToGL(
  companyId: string,
  assetId: string,
  depreciationAmount: number,
  userId: string
): Promise<string | null> {
  try {
    if (depreciationAmount <= 0) return null;

    const asset = (await sql`
      SELECT id, asset_number, name FROM assets WHERE id = ${assetId}
    `) as Row[];

    if (!asset[0]) {
      log.warn('Asset not found for depreciation GL', { assetId }, 'accounting');
      return null;
    }

    const depExpenseId = await getSystemAccountId('depreciation_expense');
    const accumDepId = await getSystemAccountId('accumulated_depreciation');

    const entry = (await sql`
      INSERT INTO gl_journal_entries (
        company_id, entry_number, entry_date, description, source, status, created_by
      ) VALUES (
        ${companyId}, ${`DEP-${asset[0].asset_number}-${new Date().toISOString().slice(0, 7)}`}, CURRENT_DATE,
        ${`Depreciation: ${asset[0].name} (${asset[0].asset_number})`},
        'auto_depreciation', 'posted', ${userId}
      ) RETURNING id
    `) as Row[];

    const entryId = String(entry[0].id);

    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${depExpenseId}::UUID, ${depreciationAmount}, 0,
        ${`Depreciation: ${asset[0].asset_number}`})
    `;
    await sql`
      INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
      VALUES (${entryId}::UUID, ${accumDepId}::UUID, 0, ${depreciationAmount},
        ${`Depreciation: ${asset[0].asset_number}`})
    `;

    await sql`
      UPDATE assets SET
        accumulated_depreciation = COALESCE(accumulated_depreciation, 0) + ${depreciationAmount},
        current_book_value = COALESCE(purchase_price, 0) - (COALESCE(accumulated_depreciation, 0) + ${depreciationAmount}),
        updated_at = NOW()
      WHERE id = ${assetId}
    `;

    log.info('Asset depreciation GL posted', { assetId, entryId, depreciationAmount }, 'accounting');
    return entryId;
  } catch (err) {
    log.error('Failed to post asset depreciation to GL', { assetId, error: err }, 'accounting');
    return null;
  }
}

/**
 * GL Import Service — WS-6.3 Excel Import Wizard
 * Validates and imports journal entries from spreadsheet uploads.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { VatType } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface ImportRow {
  date: string;          // YYYY-MM-DD
  accountCode: string;   // Must exist in gl_accounts for this company
  description: string;
  reference?: string;
  debit: number;
  credit: number;
  vatCode?: string;
  costCentre?: string;
}

export interface ValidationResult {
  row: number;
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface ValidationSummary {
  validations: ValidationResult[];
  validCount: number;
  errorCount: number;
  warningCount: number;
  totalDebit: number;
  totalCredit: number;
  isBalanced: boolean;
}

export interface ImportResult {
  entriesCreated: number;
  linesCreated: number;
  totalValue: number;
}

const VALID_VAT_CODES: VatType[] = [
  'standard', 'zero_rated', 'exempt', 'capital_goods',
  'export', 'imported', 'reverse_charge', 'bad_debt', 'no_vat',
];

function parseDate(dateStr: string): Date | null {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return d;
}

export async function validateImportRows(
  companyId: string,
  rows: ImportRow[],
): Promise<ValidationSummary> {
  try {
    // Load chart of accounts for this company
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load open fiscal periods
    const periodRows = (await sql`
      SELECT start_date, end_date
      FROM fiscal_periods
      WHERE company_id = ${companyId}::UUID
        AND status = 'open'
      ORDER BY start_date
    `) as Row[];

    // Load cost centres
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccSet = new Set<string>(ccRows.map((r: Row) => String(r.code).toLowerCase()));

    const validations: ValidationResult[] = [];
    let totalDebit = 0;
    let totalCredit = 0;
    let validCount = 0;
    let errorCount = 0;
    let warningCount = 0;

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i]!;
      const errors: string[] = [];
      const warnings: string[] = [];
      const rowNum = i + 2; // 1-indexed + header row

      // Description required
      if (!row.description || row.description.trim() === '') {
        errors.push('Description is required');
      }

      // Date validation
      const parsedDate = parseDate(row.date);
      if (!parsedDate) {
        errors.push(`Invalid date: "${row.date}" — expected YYYY-MM-DD`);
      } else {
        // Check if date falls within an open fiscal period
        const inOpenPeriod = periodRows.some((p: Row) => {
          const start = new Date(p.start_date);
          const end = new Date(p.end_date);
          return parsedDate >= start && parsedDate <= end;
        });
        if (!inOpenPeriod) {
          warnings.push(`Date ${row.date} does not fall within an open fiscal period`);
        }
      }

      // Account code validation
      if (!row.accountCode || row.accountCode.trim() === '') {
        errors.push('Account code is required');
      } else if (!accountMap.has(String(row.accountCode).trim())) {
        errors.push(`Account code "${row.accountCode}" not found in chart of accounts`);
      }

      // Debit / credit validation
      const debit = Number(row.debit) || 0;
      const credit = Number(row.credit) || 0;

      if (debit < 0) errors.push('Debit cannot be negative');
      if (credit < 0) errors.push('Credit cannot be negative');

      if (debit > 0 && credit > 0) {
        errors.push('Debit and credit cannot both be greater than zero on the same line');
      }
      if (debit === 0 && credit === 0) {
        errors.push('At least one of debit or credit must be greater than zero');
      }

      // VAT code validation (optional)
      if (row.vatCode && row.vatCode.trim() !== '') {
        const code = row.vatCode.trim() as VatType;
        if (!VALID_VAT_CODES.includes(code)) {
          errors.push(
            `Invalid VAT code "${row.vatCode}". Valid codes: ${VALID_VAT_CODES.join(', ')}`,
          );
        }
      }

      // Cost centre validation (optional)
      if (row.costCentre && row.costCentre.trim() !== '') {
        if (!ccSet.has(row.costCentre.trim().toLowerCase())) {
          warnings.push(`Cost centre "${row.costCentre}" not found — will be ignored`);
        }
      }

      const valid = errors.length === 0;
      if (valid) {
        validCount++;
        totalDebit += debit;
        totalCredit += credit;
      } else {
        errorCount++;
      }
      if (warnings.length > 0) warningCount++;

      validations.push({ row: rowNum, valid, errors, warnings });
    }

    // For balanced check, only consider valid rows
    const diff = Math.abs(totalDebit - totalCredit);
    const isBalanced = diff < 0.005; // tolerance for floating point

    return {
      validations,
      validCount,
      errorCount,
      warningCount,
      totalDebit,
      totalCredit,
      isBalanced,
    };
  } catch (err) {
    log.error('Failed to validate import rows', { error: err }, 'gl-import');
    throw err;
  }
}

export async function importJournalEntries(
  companyId: string,
  rows: ImportRow[],
  userId: string,
  postImmediately: boolean,
): Promise<ImportResult> {
  try {
    // Load account code → id mapping
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load cost centre code → id mapping
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccMap = new Map<string, string>(
      ccRows.map((r: Row) => [String(r.code).toLowerCase(), String(r.id)]),
    );

    // Group rows into journal entries: same date + same reference = one entry
    const grouped = new Map<string, ImportRow[]>();
    for (const row of rows) {
      const key = `${row.date}||${row.reference || ''}`;
      const group = grouped.get(key) ?? [];
      group.push(row);
      grouped.set(key, group);
    }

    let entriesCreated = 0;
    let linesCreated = 0;
    let totalValue = 0;
    const status = postImmediately ? 'posted' : 'draft';

    for (const [, groupRows] of grouped) {
      const firstRow = groupRows[0]!;

      // Find fiscal period for entry date
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE company_id = ${companyId}::UUID
          AND start_date <= ${firstRow.date}::DATE
          AND end_date >= ${firstRow.date}::DATE
        LIMIT 1
      `) as Row[];
      const fiscalPeriodId = periodRows.length > 0 ? String(periodRows[0].id) : null;

      const description = firstRow.reference
        ? `${firstRow.reference}: ${firstRow.description}`
        : firstRow.description;

      const postedBy = postImmediately ? userId : null;

      const entryInsert = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, fiscal_period_id, description,
          source, created_by, status,
          posted_by, posted_at
        ) VALUES (
          ${companyId}::UUID,
          ${firstRow.date}::DATE,
          ${fiscalPeriodId}::UUID,
          ${description},
          'import',
          ${userId}::UUID,
          ${status},
          ${postedBy}::UUID,
          ${postImmediately ? sql`NOW()` : sql`NULL`}
        )
        RETURNING id
      `) as Row[];

      const entryId = String(entryInsert[0].id);
      entriesCreated++;

      for (const row of groupRows) {
        const accountId = accountMap.get(String(row.accountCode).trim());
        if (!accountId) continue; // already validated upstream

        const ccId = row.costCentre
          ? (ccMap.get(row.costCentre.trim().toLowerCase()) ?? null)
          : null;

        const vatType = (row.vatCode?.trim() as VatType) || null;

        await sql`
          INSERT INTO gl_journal_lines (
            journal_entry_id, gl_account_id, debit, credit,
            description, vat_type, cost_center_id
          ) VALUES (
            ${entryId}::UUID,
            ${accountId}::UUID,
            ${Number(row.debit) || 0},
            ${Number(row.credit) || 0},
            ${row.description},
            ${vatType},
            ${ccId}::UUID
          )
        `;

        linesCreated++;
        totalValue += Number(row.debit) || 0;
      }
    }

    log.info('Imported journal entries', {
      companyId, entriesCreated, linesCreated, totalValue, postImmediately,
    }, 'gl-import');

    return { entriesCreated, linesCreated, totalValue };
  } catch (err) {
    log.error('Failed to import journal entries', { error: err }, 'gl-import');
    throw err;
  }
}

