export async function getRules(companyId: string): Promise<BankCategorisationRule[]> {
  const rows = (await sql`
    SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name,
           s.company_name AS supplier_name, c.name AS client_name
    FROM bank_categorisation_rules r
    LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
    LEFT JOIN suppliers s ON s.id = r.supplier_id
    LEFT JOIN customers c ON c.id = r.client_id
    WHERE r.company_id = ${companyId}::UUID
    ORDER BY r.priority ASC, r.rule_name ASC
  `) as Row[];
  return rows.map(mapRuleRow);
}

export async function createRule(companyId: string, input: RuleCreateInput, userId: string): Promise<BankCategorisationRule> {
  const vatCode = input.vatCode || 'none';
  const rows = (await sql`
    INSERT INTO bank_categorisation_rules (
      company_id, rule_name, match_field, match_type, match_pattern,
      gl_account_id, supplier_id, client_id, description_template,
      priority, auto_create_entry, vat_code, created_by
    ) VALUES (
      ${companyId}::UUID, ${input.ruleName}, ${input.matchField}, ${input.matchType}, ${input.matchPattern},
      ${input.glAccountId || null}::UUID, ${input.supplierId || null}::UUID,
      ${input.clientId || null}::UUID,
      ${input.descriptionTemplate || null},
      ${input.priority || 100}, ${input.autoCreateEntry !== false}, ${vatCode}, ${userId}
    ) RETURNING *
  `) as Row[];
  log.info('Created bank rule', { id: rows[0].id, ruleName: input.ruleName }, 'accounting');
  return mapRuleRow(rows[0]);
}

export async function updateRule(companyId: string, id: string, input: Partial<RuleCreateInput>): Promise<BankCategorisationRule> {
  const rows = (await sql`
    UPDATE bank_categorisation_rules SET
      rule_name = COALESCE(${input.ruleName || null}, rule_name),
      match_field = COALESCE(${input.matchField || null}, match_field),
      match_type = COALESCE(${input.matchType || null}, match_type),
      match_pattern = COALESCE(${input.matchPattern || null}, match_pattern),
      gl_account_id = COALESCE(${input.glAccountId || null}::UUID, gl_account_id),
      supplier_id = COALESCE(${input.supplierId || null}::UUID, supplier_id),
      client_id = COALESCE(${input.clientId || null}::UUID, client_id),
      description_template = COALESCE(${input.descriptionTemplate || null}, description_template),
      priority = COALESCE(${input.priority || null}, priority),
      auto_create_entry = COALESCE(${input.autoCreateEntry ?? null}, auto_create_entry),
      vat_code = COALESCE(${input.vatCode || null}, vat_code)
    WHERE id = ${id}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRuleRow(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM bank_categorisation_rules WHERE id = ${id}::UUID`;
}

export async function deleteRules(companyId: string, ids: string[]): Promise<number> {
  if (ids.length === 0) return 0;
  const rows = await sql`
    DELETE FROM bank_categorisation_rules
    WHERE id = ANY(${ids}::UUID[])
    RETURNING id
  ` as { id: string }[];
  return rows.length;
}

export async function toggleRule(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE bank_categorisation_rules SET is_active = ${isActive} WHERE id = ${id}::UUID`;
}

// ── Apply Rules ─────────────────────────────────────────────────────────────

/** Lookup a GL account UUID by account code */
async function glAccountByCode(code: string): Promise<string> {
  const rows = (await sql`
    SELECT id FROM gl_accounts WHERE account_code = ${code} AND is_active = TRUE LIMIT 1
  `) as Row[];
  if (rows.length === 0) throw new Error(`GL account ${code} not found`);
  return String(rows[0].id);
}

/** Convert rule match type to SQL ILIKE pattern */
function toSqlPattern(matchType: string, matchPattern: string): string {
  switch (matchType) {
    case 'contains': return `%${matchPattern}%`;
    case 'starts_with': return `${matchPattern}%`;
    case 'ends_with': return `%${matchPattern}`;
    case 'exact': return matchPattern;
    default: return `%${matchPattern}%`;
  }
}

export async function applyRules(companyId: string, 
  bankAccountId: string,
  userId: string
): Promise<RuleApplyResult> {
  try {
    // Get active rules ordered by priority
    const rules = (await sql`
      SELECT * FROM bank_categorisation_rules
      WHERE is_active = true
      ORDER BY priority ASC
    `) as Row[];

    if (rules.length === 0) return { applied: 0, skipped: 0, entries: [] };

    let totalApplied = 0;
    const entries: RuleApplyResult['entries'] = [];

    const autoCreateRules = rules.filter((r: Row) => Boolean(r.auto_create_entry));
    const hasSuggestionRules = rules.some((r: Row) => !r.auto_create_entry);

    if (hasSuggestionRules) {
      // Single-query approach: JOIN all suggestion-mode rules against all unmatched
      // transactions in one CTE, assign the highest-priority matching rule per tx.
      // ILIKE patterns are generated inline using CASE on match_type column —
      // one network round-trip to Neon regardless of rule count.
      const updated = (await sql`
        WITH matched AS (
          SELECT
            bt.id                                              AS tx_id,
            r.gl_account_id,
            r.supplier_id,
            r.client_id,
            r.rule_name,
            r.vat_code,
            ROW_NUMBER() OVER (PARTITION BY bt.id ORDER BY r.priority ASC) AS rn
          FROM bank_transactions bt
          JOIN bank_categorisation_rules r ON (
            r.is_active = true
            AND r.auto_create_entry = false
            AND (
              (r.match_field IN ('description', 'both')
                AND bt.description ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
              OR
              (r.match_field IN ('reference', 'both')
                AND bt.reference ILIKE
                  CASE r.match_type
                    WHEN 'contains'    THEN '%' || r.match_pattern || '%'
                    WHEN 'starts_with' THEN        r.match_pattern || '%'
                    WHEN 'ends_with'   THEN '%' || r.match_pattern
                    ELSE                           r.match_pattern
                  END)
            )
          )
          WHERE bt.bank_account_id = ${bankAccountId}::UUID
            AND bt.status IN ('imported', 'allocated')
            AND bt.suggested_gl_account_id IS NULL
            AND bt.suggested_supplier_id IS NULL
            AND bt.suggested_client_id IS NULL
            AND bt.suggested_category IS NULL
        ),
        top_match AS (SELECT * FROM matched WHERE rn = 1)
        UPDATE bank_transactions bt
        SET
          suggested_gl_account_id = tm.gl_account_id,
          suggested_supplier_id   = tm.supplier_id,
          suggested_client_id     = tm.client_id,
          suggested_category      = tm.rule_name,
          suggested_vat_code      = COALESCE(tm.vat_code, 'none')
        FROM top_match tm
        WHERE bt.id = tm.tx_id
        RETURNING bt.id, tm.rule_name
      `) as Row[];

      for (const row of updated) {
        entries.push({ bankTxId: String(row.id), ruleName: String(row.rule_name), suggestion: true });
      }
      totalApplied += updated.length;

      // Backfill vat_code for already-suggested transactions (suggested before the vat_code column existed)
      await sql`
        UPDATE bank_transactions bt
        SET suggested_vat_code = r.vat_code
        FROM (
          SELECT DISTINCT ON (rule_name) rule_name, vat_code
          FROM bank_categorisation_rules
          WHERE is_active = true AND vat_code != 'none'
          ORDER BY rule_name, priority ASC
        ) r
        WHERE bt.bank_account_id = ${bankAccountId}::UUID
          AND bt.status IN ('imported', 'allocated')
          AND bt.suggested_category = r.rule_name
          AND bt.suggested_vat_code = 'none'
      `;
    }

    // Auto-create JE mode — sequential (each transaction needs its own JE)
    for (const rule of autoCreateRules) {
      const pattern = toSqlPattern(String(rule.match_type), String(rule.match_pattern));
      const field = String(rule.match_field);
      const ruleName = String(rule.rule_name);

      let matchingTxs: Row[];
      if (field === 'description') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND description ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Row[];
      } else if (field === 'reference') {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND reference ILIKE ${pattern}
          ORDER BY transaction_date
        `) as Row[];
      } else {
        matchingTxs = (await sql`
          SELECT id, amount, transaction_date, description, reference
          FROM bank_transactions
          WHERE bank_account_id = ${bankAccountId}::UUID
            AND status IN ('imported', 'allocated')
            AND matched_journal_line_id IS NULL
            AND (description ILIKE ${pattern} OR reference ILIKE ${pattern})
          ORDER BY transaction_date
        `) as Row[];
      }

      for (const tx of matchingTxs) {
        const totalAmount = Math.abs(Number(tx.amount));
        const isDeposit = Number(tx.amount) > 0;
        const entryDesc = rule.description_template
          ? String(rule.description_template).replace('{description}', String(tx.description || '')).replace('{amount}', totalAmount.toFixed(2))
          : `Bank: ${tx.description || 'Categorised by rule'}`;

        // VAT splitting — mirrors allocateTransaction logic
        const vatCode = String(rule.vat_code || 'none');
        const hasVat = vatCode === 'standard';
        const netAmount = hasVat ? Math.round((totalAmount * 100 / 115) * 100) / 100 : totalAmount;
        const vatAmount = hasVat ? Math.round((totalAmount - netAmount) * 100) / 100 : 0;
        const vatAccountKey = isDeposit ? 'vat_output' as const : 'vat_input' as const;
        const mapVatType = vatCode === 'standard' ? 'standard' as const
          : vatCode === 'zero_rated' ? 'zero_rated' as const
          : vatCode === 'exempt' ? 'exempt' as const
          : undefined;

        let lines: JournalLineInput[];
        if (isDeposit) {
          lines = [
            { glAccountId: bankAccountId, debit: totalAmount, credit: 0, description: entryDesc },
            { glAccountId: String(rule.gl_account_id), debit: 0, credit: netAmount, description: entryDesc, vatType: mapVatType },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: 0, credit: vatAmount, description: `VAT @ 15%`, vatType: 'standard' });
          }
        } else {
          lines = [
            { glAccountId: String(rule.gl_account_id), debit: netAmount, credit: 0, description: entryDesc, vatType: mapVatType },
            { glAccountId: bankAccountId, debit: 0, credit: totalAmount, description: entryDesc },
          ];
          if (hasVat) {
            const vatAcctId = await getSystemAccountId(vatAccountKey);
            lines.splice(1, 0, { glAccountId: vatAcctId, debit: vatAmount, credit: 0, description: `VAT @ 15%`, vatType: 'standard' });
          }
        }

        const je = await createJournalEntry(companyId, {
          entryDate: tx.transaction_date instanceof Date
            ? tx.transaction_date.toISOString().split('T')[0]
            : String(tx.transaction_date).split('T')[0],
          description: entryDesc,
          source: 'auto_bank_recon',
          lines,
        }, userId);
        await postJournalEntry('', je.id, userId);

        const bankLineRows = (await sql`
          SELECT id FROM gl_journal_lines
          WHERE journal_entry_id = ${je.id}::UUID AND gl_account_id = ${bankAccountId}::UUID
          LIMIT 1
        `) as Row[];

        if (bankLineRows[0]) {
          await sql`
            UPDATE bank_transactions
            SET status = 'allocated', matched_journal_line_id = ${bankLineRows[0].id}::UUID,
                allocation_type = 'account',
                allocated_entity_name = ${ruleName},
                updated_at = NOW()
            WHERE id = ${tx.id}::UUID
          `;
        }

        entries.push({ bankTxId: String(tx.id), ruleName, journalEntryId: je.id });
        totalApplied++;
      }
    }

    // Count remaining unmatched for the skipped total
    const remaining = (await sql`
      SELECT COUNT(*) AS cnt FROM bank_transactions
      WHERE bank_account_id = ${bankAccountId}::UUID
        AND status IN ('imported', 'allocated')
        AND suggested_gl_account_id IS NULL
        AND matched_journal_line_id IS NULL
    `) as Row[];
    const skipped = Number(remaining[0].cnt);

    log.info('Applied bank rules', { bankAccountId, applied: totalApplied, skipped }, 'accounting');
    return { applied: totalApplied, skipped, entries };
  } catch (err) {
    log.error('Failed to apply bank rules', { error: err }, 'accounting');
    throw err;
  }
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function mapRuleRow(row: Row): BankCategorisationRule {
  return {
    id: String(row.id),
    ruleName: String(row.rule_name),
    matchField: String(row.match_field) as BankCategorisationRule['matchField'],
    matchType: String(row.match_type) as BankCategorisationRule['matchType'],
    matchPattern: String(row.match_pattern ?? row.match_value ?? ''),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    clientId: row.client_id ? String(row.client_id) : undefined,
    descriptionTemplate: row.description_template ? String(row.description_template) : undefined,
    priority: Number(row.priority),
    isActive: Boolean(row.is_active),
    autoCreateEntry: Boolean(row.auto_create_entry),
    vatCode: (row.vat_code || 'none') as BankCategorisationRule['vatCode'],
    createdBy: row.created_by ? String(row.created_by) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
    glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Journal Entry Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateJournalEntry } from '../utils/doubleEntry';
import type {
  JournalEntry,
  JournalLine,
  JournalEntryCreateInput,
  JournalLineInput,
  GLEntryStatus,
  GLEntrySource,
  TrialBalanceRow,
  VatType,
} from '../types/gl.types';

const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Resolve a userId to a valid UUID — handles non-UUID IDs like 'admin-001' */
async function resolveUserUuid(userId: string): Promise<string> {
  if (UUID_PATTERN.test(userId)) return userId;
  const rows = (await sql`SELECT id FROM users WHERE id::TEXT ~ '^[0-9a-f]{8}-' LIMIT 1`) as { id: string }[];
  return rows.length > 0 ? String(rows[0]!.id) : '00000000-0000-0000-0000-000000000000';
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface JournalEntryFilters {
  status?: GLEntryStatus;
  source?: GLEntrySource;
  fiscalPeriodId?: string;
  limit?: number;
  offset?: number;
}

export async function getJournalEntries(companyId: string, filters?: JournalEntryFilters): Promise<{
  entries: JournalEntry[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;

    let rows: Row[];
    let countRows: Row[];

    // Exclude auto-generated entries (auto_grn, auto_supplier_payment, etc.)
    // so only manual journals appear in the UI. Auto entries still feed into
    // trial balance and financial reports via getTrialBalance().
    if (filters?.status && filters?.fiscalPeriodId) {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.status = ${filters.status}
          AND je.fiscal_period_id = ${filters.fiscalPeriodId}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries
        WHERE company_id = ${companyId} AND status = ${filters.status} AND fiscal_period_id = ${filters.fiscalPeriodId}
          AND source NOT LIKE 'auto_%'
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.status = ${filters.status}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries
        WHERE company_id = ${companyId} AND status = ${filters.status} AND source NOT LIKE 'auto_%'
      `) as Row[];
    } else if (filters?.fiscalPeriodId) {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.fiscal_period_id = ${filters.fiscalPeriodId}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries
        WHERE company_id = ${companyId} AND fiscal_period_id = ${filters.fiscalPeriodId} AND source NOT LIKE 'auto_%'
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT je.*, fp.period_name AS fiscal_period_name
        FROM gl_journal_entries je
        LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
        WHERE je.company_id = ${companyId}
          AND je.source NOT LIKE 'auto_%'
        ORDER BY je.entry_date DESC, je.created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM gl_journal_entries WHERE company_id = ${companyId} AND source NOT LIKE 'auto_%'
      `) as Row[];
    }

    return {
      entries: rows.map(mapEntryRow),
      total: Number(countRows[0].cnt),
    };
  } catch (err) {
    log.error('Failed to get journal entries', { error: err }, 'accounting');
    throw err;
  }
}

export async function getJournalEntryById(companyId: string, 
  id: string
): Promise<(JournalEntry & { lines: JournalLine[] }) | null> {
  try {
    const entryRows = (await sql`
      SELECT je.*, fp.period_name AS fiscal_period_name
      FROM gl_journal_entries je
      LEFT JOIN fiscal_periods fp ON fp.id = je.fiscal_period_id
      WHERE je.id = ${id} AND je.company_id = ${companyId}
    `) as Row[];
    if (entryRows.length === 0) return null;

    const lineRows = (await sql`
      SELECT jl.*, a.account_code, a.account_name
      FROM gl_journal_lines jl
      JOIN gl_accounts a ON a.id = jl.gl_account_id
      WHERE jl.journal_entry_id = ${id}
      ORDER BY jl.created_at
    `) as Row[];

    return {
      ...mapEntryRow(entryRows[0]),
      lines: lineRows.map(mapLineRow),
    };
  } catch (err) {
    log.error('Failed to get journal entry', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createJournalEntry(companyId: string, 
  input: JournalEntryCreateInput,
  userId: string
): Promise<JournalEntry> {
  try {
    const validation = validateJournalEntry(input.lines);
    if (!validation.valid) {
      throw new Error(`Invalid journal entry: ${validation.errors.join('; ')}`);
    }

    let fiscalPeriodId = input.fiscalPeriodId;
    if (!fiscalPeriodId) {
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE start_date <= ${input.entryDate}::DATE AND end_date >= ${input.entryDate}::DATE
        LIMIT 1
      `) as Row[];
      if (periodRows.length > 0) {
        fiscalPeriodId = String(periodRows[0].id);
      }
    }

    const safeUserId = await resolveUserUuid(userId);

    // Use HTTP-based sql (not Pool/WebSocket withTransaction) for reliability
    const rows = (await sql`
      INSERT INTO gl_journal_entries (
        company_id, entry_date, fiscal_period_id, description, source,
        source_document_id, created_by
      ) VALUES (
        ${companyId}::UUID, ${input.entryDate}, ${fiscalPeriodId || null},
        ${input.description || null}, ${input.source || 'manual'},
        ${input.sourceDocumentId || null}, ${safeUserId}::UUID
      )
      RETURNING *
    `) as Row[];

    const entryRow = rows[0] as Row;
    const entryId = String(entryRow.id);

    for (const line of input.lines) {
      await sql`
        INSERT INTO gl_journal_lines (
          journal_entry_id, gl_account_id, debit, credit,
          description, project_id, cost_center_id, bu_id, vat_type
        ) VALUES (
          ${entryId}::UUID, ${line.glAccountId}::UUID,
          ${line.debit}, ${line.credit},
          ${line.description || null},
          ${line.projectId || null},
          ${line.costCenterId || null},
          ${line.buId || null},
          ${line.vatType || null}
        )
      `;
    }

    log.info('Created journal entry', {
      entryId: String(entryRow.id),
      entryNumber: String(entryRow.entry_number),
      lineCount: input.lines.length,
    }, 'accounting');

    return mapEntryRow(entryRow);
  } catch (err) {
    log.error('Failed to create journal entry', { error: err }, 'accounting');
    throw err;
  }
}

export async function postJournalEntry(companyId: string, id: string, userId: string): Promise<JournalEntry> {
  try {
    const entry = await getJournalEntryById(companyId, id);
    if (!entry) throw new Error(`Journal entry ${id} not found`);
    if (entry.status !== 'draft') throw new Error(`Cannot post entry with status: ${entry.status}`);

    if (entry.fiscalPeriodId) {
      const period = (await sql`
        SELECT status FROM fiscal_periods WHERE id = ${entry.fiscalPeriodId}
      `) as Row[];
      if (period.length > 0 && String(period[0].status) !== 'open') {
        throw new Error(`Cannot post to ${period[0].status} fiscal period`);
      }
    }

    if (entry.lines) {
      const validation = validateJournalEntry(entry.lines.map(l => ({
        glAccountId: l.glAccountId,
        debit: l.debit,
        credit: l.credit,
      })));
      if (!validation.valid) {
        throw new Error(`Entry not balanced: ${validation.errors.join('; ')}`);
      }
    }

    const safePostUserId = await resolveUserUuid(userId);
    const rows = (await sql`
      UPDATE gl_journal_entries
      SET status = 'posted', posted_by = ${safePostUserId}::UUID, posted_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];

    log.info('Posted journal entry', { id, entryNumber: String(rows[0].entry_number) }, 'accounting');
    return mapEntryRow(rows[0]);
  } catch (err) {
    log.error('Failed to post journal entry', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reverseJournalEntry(companyId: string, id: string, userId: string): Promise<JournalEntry> {
  try {
    const entry = await getJournalEntryById(companyId, id);
    if (!entry) throw new Error(`Journal entry ${id} not found`);
    if (entry.status !== 'posted') throw new Error('Can only reverse posted entries');
    if (!entry.lines || entry.lines.length === 0) throw new Error('Entry has no lines');

    const reversalLines: JournalLineInput[] = entry.lines.map(l => ({
      glAccountId: l.glAccountId,
      debit: l.credit,
      credit: l.debit,
      description: `Reversal: ${l.description || ''}`,
      projectId: l.projectId,
      costCenterId: l.costCenterId,
    }));

    const reversalEntry = await createJournalEntry(companyId, {
      entryDate: new Date().toISOString().split('T')[0]!,
      description: `Reversal of ${entry.entryNumber}`,
      source: entry.source,
      fiscalPeriodId: entry.fiscalPeriodId,
      lines: reversalLines,
    }, userId);

    await postJournalEntry(companyId, reversalEntry.id, userId);

    await sql`
      UPDATE gl_journal_entries
      SET status = 'reversed', reversed_by = ${userId}::UUID, reversed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
    `;

    await sql`
      UPDATE gl_journal_entries
      SET reversal_of_id = ${id}::UUID
      WHERE id = ${reversalEntry.id} AND company_id = ${companyId}
    `;

    log.info('Reversed journal entry', {
      originalId: id,
      reversalId: reversalEntry.id,
    }, 'accounting');

    return reversalEntry;
  } catch (err) {
    log.error('Failed to reverse journal entry', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getTrialBalance(companyId: string, fiscalPeriodId: string, costCentreId?: string): Promise<TrialBalanceRow[]> {
  try {
    if (!costCentreId) {
      // Use direct query with company_id filter instead of the SQL function
      const rows = (await sql`
        SELECT a.account_code, a.account_name, a.account_type, a.normal_balance,
          COALESCE(b.debit_total, 0) AS debit_balance,
          COALESCE(b.credit_total, 0) AS credit_balance
        FROM gl_accounts a
        LEFT JOIN gl_account_balances b ON b.gl_account_id = a.id AND b.fiscal_period_id = ${fiscalPeriodId}::UUID
        WHERE a.is_active = true
          AND a.company_id = ${companyId}::UUID
          AND (COALESCE(b.debit_total, 0) != 0 OR COALESCE(b.credit_total, 0) != 0)
        ORDER BY a.account_code
      `) as Row[];
      return rows.map(r => ({
        accountCode: String(r.account_code),
        accountName: String(r.account_name),
        accountType: String(r.account_type),
        normalBalance: String(r.normal_balance) as 'debit' | 'credit',
        debitBalance: Number(r.debit_balance),
        creditBalance: Number(r.credit_balance),
      }));
    }

    // Direct query with cost centre filter
    const rows = (await sql`
      SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
        COALESCE(SUM(jl.debit), 0) AS total_debit,
        COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.fiscal_period_id = ${fiscalPeriodId}::UUID
        AND jl.cost_center_id = ${costCentreId}::UUID
      GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance
      HAVING COALESCE(SUM(jl.debit), 0) != 0 OR COALESCE(SUM(jl.credit), 0) != 0
      ORDER BY ga.account_code
    `) as Row[];

    return rows.map(r => {
      const net = Number(r.total_debit) - Number(r.total_credit);
      return {
        accountCode: String(r.account_code),
        accountName: String(r.account_name),
        accountType: String(r.account_type),
        normalBalance: String(r.normal_balance) as 'debit' | 'credit',
        debitBalance: net > 0 ? net : 0,
        creditBalance: net < 0 ? Math.abs(net) : 0,
      };
    });
  } catch (err) {
    log.error('Failed to get trial balance', { fiscalPeriodId, error: err }, 'accounting');
    throw err;
  }
}

function mapEntryRow(row: Row): JournalEntry {
  return {
    id: String(row.id),
    entryNumber: row.entry_number ? String(row.entry_number) : '',
    entryDate: String(row.entry_date),
    fiscalPeriodId: row.fiscal_period_id ? String(row.fiscal_period_id) : undefined,
    description: row.description ? String(row.description) : undefined,
    source: String(row.source) as GLEntrySource,
    sourceDocumentId: row.source_document_id ? String(row.source_document_id) : undefined,
    status: String(row.status) as GLEntryStatus,
    postedBy: row.posted_by ? String(row.posted_by) : undefined,
    postedAt: row.posted_at ? String(row.posted_at) : undefined,
    reversedBy: row.reversed_by ? String(row.reversed_by) : undefined,
    reversedAt: row.reversed_at ? String(row.reversed_at) : undefined,
    reversalOfId: row.reversal_of_id ? String(row.reversal_of_id) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

function mapLineRow(row: Row): JournalLine {
  return {
    id: String(row.id),
    journalEntryId: String(row.journal_entry_id),
    glAccountId: String(row.gl_account_id),
    debit: Number(row.debit),
    credit: Number(row.credit),
    description: row.description ? String(row.description) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    costCenterId: row.cost_center_id ? String(row.cost_center_id) : undefined,
    vatType: row.vat_type ? String(row.vat_type) as VatType : undefined,
    createdAt: String(row.created_at),
    accountCode: row.account_code ? String(row.account_code) : undefined,
    accountName: row.account_name ? String(row.account_name) : undefined,
  };
}

/**
 * KPI Dashboard Service
 * Real-time financial KPIs from the general ledger, invoices, and bank accounts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ───────────────────────────────────────────────────────────────────

export interface DashboardKPIs {
  revenue: { total: number; priorTotal: number; changePercent: number };
  expenses: { total: number; priorTotal: number };
  grossProfit: { amount: number; margin: number };
  netProfit: { amount: number; margin: number };
  cash: { total: number; priorTotal: number; change: number };
  receivables: { total: number; overdue: number; avgDebtorDays: number };
  payables: { total: number; overdue: number; avgCreditorDays: number };
  activity: { invoicesIssued: number; paymentsReceived: number; journalsPosted: number };
}

export interface ChartPoint {
  month: string;
  revenue: number;
  expenses: number;
}

export interface CashFlowPoint {
  month: string;
  inflows: number;
  outflows: number;
}

export interface AgingBreakdownBucket {
  name: string;
  value: number;
}

export interface TopCustomer {
  name: string;
  revenue: number;
  invoiceCount: number;
}

export interface TopExpenseCategory {
  accountName: string;
  total: number;
  percentOfExpenses: number;
}

// ── Dashboard KPIs ──────────────────────────────────────────────────────────

export async function getDashboardKPIs(companyId: string,
  fromDate: string,
  toDate: string
): Promise<DashboardKPIs> {
  try {
    // Calculate prior period (same duration before fromDate)
    const from = new Date(fromDate);
    const to = new Date(toDate);
    const durationMs = to.getTime() - from.getTime();
    const priorFrom = new Date(from.getTime() - durationMs);
    const priorFromStr = priorFrom.toISOString().slice(0, 10);
    const priorToStr = new Date(from.getTime() - 86400000).toISOString().slice(0, 10);

    const [
      revenueRows,
      priorRevenueRows,
      expenseRows,
      priorExpenseRows,
      cashRows,
      priorCashRows,
      arRows,
      arOverdueRows,
      arDebtorDaysRows,
      apRows,
      apOverdueRows,
      apCreditorDaysRows,
      invoicesIssuedRows,
      paymentsReceivedRows,
      journalsPostedRows,
    ] = await Promise.all([
      // Current period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current cash position (sum of all bank account balances from transactions)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
      `,
      // Prior period cash (transactions up to prior period end)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
          AND bt.transaction_date <= ${priorToStr}
      `,
      // AR total outstanding
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
      `,
      // AR overdue
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
          AND due_date < CURRENT_DATE
      `,
      // Average debtor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_at, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM customer_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // AP total outstanding
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
      `,
      // AP overdue
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
          AND due_date < CURRENT_DATE
      `,
      // Average creditor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_at, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM supplier_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // Invoices issued this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate} AND invoice_date <= ${toDate}
          AND status NOT IN ('cancelled', 'draft')
      `,
      // Payments received this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND paid_at >= ${fromDate} AND paid_at <= ${toDate}
      `,
      // Journal entries posted this period
      sql`
        SELECT COUNT(*) AS count
        FROM gl_journal_entries
        WHERE company_id = ${companyId}::UUID
          AND status = 'posted'
          AND entry_date >= ${fromDate} AND entry_date <= ${toDate}
      `,
    ]);

    const totalRevenue = Number((revenueRows as Row[])[0]?.total || 0);
    const priorRevenue = Number((priorRevenueRows as Row[])[0]?.total || 0);
    const totalExpenses = Number((expenseRows as Row[])[0]?.total || 0);
    const priorExpenses = Number((priorExpenseRows as Row[])[0]?.total || 0);
    const cashTotal = Number((cashRows as Row[])[0]?.total || 0);
    const priorCash = Number((priorCashRows as Row[])[0]?.total || 0);

    const grossProfit = totalRevenue - totalExpenses;
    const grossMargin = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
    const revenueChange = priorRevenue > 0
      ? ((totalRevenue - priorRevenue) / priorRevenue) * 100
      : totalRevenue > 0 ? 100 : 0;

    return {
      revenue: { total: totalRevenue, priorTotal: priorRevenue, changePercent: revenueChange },
      expenses: { total: totalExpenses, priorTotal: priorExpenses },
      grossProfit: { amount: grossProfit, margin: grossMargin },
      netProfit: { amount: grossProfit, margin: grossMargin },
      cash: { total: cashTotal, priorTotal: priorCash, change: cashTotal - priorCash },
      receivables: {
        total: Number((arRows as Row[])[0]?.total || 0),
        overdue: Number((arOverdueRows as Row[])[0]?.total || 0),
        avgDebtorDays: Math.round(Number((arDebtorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      payables: {
        total: Number((apRows as Row[])[0]?.total || 0),
        overdue: Number((apOverdueRows as Row[])[0]?.total || 0),
        avgCreditorDays: Math.round(Number((apCreditorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      activity: {
        invoicesIssued: Number((invoicesIssuedRows as Row[])[0]?.count || 0),
        paymentsReceived: Number((paymentsReceivedRows as Row[])[0]?.count || 0),
        journalsPosted: Number((journalsPostedRows as Row[])[0]?.count || 0),
      },
    };
  } catch (err) {
    log.error('Failed to get dashboard KPIs', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Revenue Chart ───────────────────────────────────────────────────────────

export async function getRevenueChart(companyId: string, months: number): Promise<ChartPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
        COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
      FROM months m
      LEFT JOIN gl_journal_entries je
        ON je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= m.month_start
        AND je.entry_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_journal_lines jl ON jl.journal_entry_id = je.id
      LEFT JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        AND ga.account_type IN ('revenue', 'expense')
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(r.month_start).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      revenue: Math.abs(Number(r.revenue || 0)),
      expenses: Math.abs(Number(r.expenses || 0)),
    }));
  } catch (err) {
    log.error('Failed to get revenue chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Cash Flow Chart ─────────────────────────────────────────────────────────

export async function getCashFlowChart(companyId: string, months: number): Promise<CashFlowPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END), 0) AS inflows,
        COALESCE(SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END), 0) AS outflows
      FROM months m
      LEFT JOIN bank_transactions bt
        ON bt.company_id = ${companyId}::UUID
        AND bt.transaction_date >= m.month_start
        AND bt.transaction_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        AND ga.account_subtype = 'bank' AND ga.is_active = true
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(r.month_start).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      inflows: Number(r.inflows || 0),
      outflows: Number(r.outflows || 0),
    }));
  } catch (err) {
    log.error('Failed to get cash flow chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Aging Breakdown ─────────────────────────────────────────────────────────

export async function getAgingBreakdown(companyId: string, type: 'ar' | 'ap'): Promise<AgingBreakdownBucket[]> {
  try {
    let rows: Row[];

    if (type === 'ar') {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
        GROUP BY bucket
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
        GROUP BY bucket
      `) as Row[];
    }

    // Ensure all buckets exist in correct order
    const bucketOrder = ['Current', '30 Days', '60 Days', '90+ Days'];
    const bucketMap = new Map<string, number>();
    for (const b of bucketOrder) bucketMap.set(b, 0);
    for (const r of rows) {
      bucketMap.set(String(r.bucket), Number(r.total || 0));
    }

    return bucketOrder.map(name => ({ name, value: bucketMap.get(name) || 0 }));
  } catch (err) {
    log.error('Failed to get aging breakdown', { error: err, type }, 'kpi-service');
    throw err;
  }
}

// ── Top Customers ───────────────────────────────────────────────────────────

export async function getTopCustomers(companyId: string, limit: number): Promise<TopCustomer[]> {
  try {
    const rows = (await sql`
      SELECT c.name AS name,
        COALESCE(SUM(ci.total_amount), 0) AS revenue,
        COUNT(ci.id) AS invoice_count
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.customer_id
      WHERE ci.status NOT IN ('cancelled', 'draft')
        AND ci.company_id = ${companyId}::UUID
      GROUP BY c.id, c.name
      ORDER BY revenue DESC
      LIMIT ${limit}
    `) as Row[];

    return rows.map((r: Row) => ({
      name: String(r.name),
      revenue: Number(r.revenue || 0),
      invoiceCount: Number(r.invoice_count || 0),
    }));
  } catch (err) {
    log.error('Failed to get top customers', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Top Expense Categories ──────────────────────────────────────────────────

export async function getTopExpenseCategories(companyId: string, limit: number): Promise<TopExpenseCategory[]> {
  try {
    const rows = (await sql`
      SELECT ga.account_name,
        COALESCE(SUM(jl.debit - jl.credit), 0) AS total
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE ga.account_type = 'expense' AND je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
      GROUP BY ga.id, ga.account_name
      HAVING SUM(jl.debit - jl.credit) > 0
      ORDER BY total DESC
      LIMIT ${limit}
    `) as Row[];

    const totalExpenses = rows.reduce((s: number, r: Row) => s + Number(r.total || 0), 0);

    return rows.map((r: Row) => {
      const total = Number(r.total || 0);
      return {
        accountName: String(r.account_name),
        total,
        percentOfExpenses: totalExpenses > 0 ? (total / totalExpenses) * 100 : 0,
      };
    });
  } catch (err) {
    log.error('Failed to get top expense categories', { error: err }, 'kpi-service');
    throw err;
  }
}

/**
 * Cash Flow Forecasting Service
 * Projects future cash position based on historical patterns,
 * recurring invoices, known payables, and seasonal trends.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export interface CashFlowForecastPoint {
  date: string;          // YYYY-MM-DD
  label: string;         // "Apr 2026", "Week 14", etc.
  projectedInflow: number;
  projectedOutflow: number;
  projectedNet: number;
  projectedBalance: number;
  confidence: number;    // 0-1
}

export interface CashFlowAlert {
  type: 'warning' | 'danger';
  message: string;
  date: string;
  projectedBalance: number;
}

export interface CashFlowForecastResult {
  currentBalance: number;
  forecastPoints: CashFlowForecastPoint[];
  alerts: CashFlowAlert[];
  assumptions: string[];
  generatedAt: string;
}

export interface HistoricalCashFlow {
  month: string;
  inflow: number;
  outflow: number;
  net: number;
}

// ── Historical Analysis ──────────────────────────────────────────────────────

/** Get current total cash balance across all bank accounts */
async function getCurrentCashBalance(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(
      CASE WHEN ga.account_subtype IN ('bank', 'cash')
        THEN COALESCE(
          (SELECT SUM(jl.debit) - SUM(jl.credit)
           FROM gl_journal_lines jl
           JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
           WHERE jl.gl_account_id = ga.id
             AND je.status = 'posted'
             AND je.company_id = ${companyId}),
          0)
        ELSE 0
      END
    ), 0) AS total_cash
    FROM gl_accounts ga
    WHERE ga.company_id = ${companyId}
      AND ga.account_type = 'asset'
      AND ga.account_subtype IN ('bank', 'cash')
      AND ga.is_active = true
  `) as Row[];
  return Number(rows[0]?.total_cash ?? 0);
}

/** Get monthly cash inflows and outflows for the last N months */
async function getHistoricalCashFlows(companyId: string, months: number): Promise<HistoricalCashFlow[]> {
  // Compute the start date in JS to avoid interval arithmetic in tagged templates
  const startDate = new Date();
  startDate.setMonth(startDate.getMonth() - months);
  const startStr = startDate.toISOString().split('T')[0]!;

  const rows = (await sql`
    WITH monthly AS (
      SELECT
        date_trunc('month', je.entry_date) AS month,
        COALESCE(SUM(CASE WHEN jl.debit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.debit ELSE 0 END), 0) AS inflow,
        COALESCE(SUM(CASE WHEN jl.credit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.credit ELSE 0 END), 0) AS outflow
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.company_id = ${companyId}
        AND je.status = 'posted'
        AND ga.account_type = 'asset'
        AND ga.account_subtype IN ('bank', 'cash')
        AND je.entry_date >= ${startStr}::DATE
      GROUP BY date_trunc('month', je.entry_date)
    )
    SELECT
      to_char(month, 'YYYY-MM') AS month,
      inflow,
      outflow,
      (inflow - outflow) AS net
    FROM monthly
    ORDER BY month ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    month: r.month,
    inflow: Number(r.inflow),
    outflow: Number(r.outflow),
    net: Number(r.net),
  }));
}

/** Get known future receivables (unpaid customer invoices) */
async function getExpectedReceivables(companyId: string): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM customer_invoices
    WHERE company_id = ${companyId}
      AND status IN ('sent', 'overdue', 'approved')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get known future payables (unpaid supplier invoices) */
async function getExpectedPayables(companyId: string): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM supplier_invoices
    WHERE company_id = ${companyId}
      AND status IN ('approved', 'received', 'overdue')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get recurring invoice amounts for projection */
async function getRecurringRevenue(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(total_amount), 0) AS monthly_recurring
    FROM recurring_invoices
    WHERE company_id = ${companyId}
      AND status = 'active'
      AND frequency = 'monthly'
  `) as Row[];
  return Number(rows[0]?.monthly_recurring ?? 0);
}

// ── Forecasting Engine ───────────────────────────────────────────────────────

/**
 * Generate a cash flow forecast for the next N months.
 * Uses a blend of:
 * 1. Known receivables and payables (high confidence)
 * 2. Recurring invoices (medium-high confidence)
 * 3. Historical average patterns (medium confidence)
 * 4. Seasonal adjustment from same month prior year (lower confidence)
 */
export async function generateForecast(companyId: string, 
  forecastMonths = 6,
  alertThreshold = 0
): Promise<CashFlowForecastResult> {
  const [currentBalance, historical, receivables, payables, recurringRevenue] = await Promise.all([
    getCurrentCashBalance(companyId),
    getHistoricalCashFlows(companyId, 12),
    getExpectedReceivables(companyId),
    getExpectedPayables(companyId),
    getRecurringRevenue(companyId),
  ]);

  // Calculate historical averages
  const avgInflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.inflow, 0) / historical.length
    : 0;
  const avgOutflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.outflow, 0) / historical.length
    : 0;

  // Build month-by-month forecast
  const forecastPoints: CashFlowForecastPoint[] = [];
  const alerts: CashFlowAlert[] = [];
  let runningBalance = currentBalance;
  const now = new Date();

  for (let i = 1; i <= forecastMonths; i++) {
    const forecastDate = new Date(now.getFullYear(), now.getMonth() + i, 1);
    const monthStr = forecastDate.toISOString().slice(0, 7); // YYYY-MM
    const monthLabel = forecastDate.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });

    // Known receivables due this month
    const knownInflows = receivables
      .filter(r => String(r.dueDate).startsWith(monthStr))
      .reduce((sum, r) => sum + r.amount, 0);

    // Known payables due this month
    const knownOutflows = payables
      .filter(p => String(p.dueDate).startsWith(monthStr))
      .reduce((sum, p) => sum + p.amount, 0);

    // Projected inflow: known receivables + recurring revenue + historical average for unknowns
    const knownInflowWeight = knownInflows > 0 ? 0.7 : 0;
    const historicalInflowWeight = 1 - knownInflowWeight;
    const projectedInflow = knownInflows + recurringRevenue + (avgInflow * historicalInflowWeight * 0.5);

    // Projected outflow: known payables + historical average for unknowns
    const knownOutflowWeight = knownOutflows > 0 ? 0.7 : 0;
    const historicalOutflowWeight = 1 - knownOutflowWeight;
    const projectedOutflow = knownOutflows + (avgOutflow * historicalOutflowWeight * 0.5);

    const projectedNet = projectedInflow - projectedOutflow;
    runningBalance += projectedNet;

    // Confidence decreases as we project further out
    const baseConfidence = 0.9;
    const decayFactor = 0.1;
    const knownDataBoost = (knownInflows + knownOutflows > 0) ? 0.1 : 0;
    const confidence = Math.max(0.3, baseConfidence - (i * decayFactor) + knownDataBoost);

    forecastPoints.push({
      date: forecastDate.toISOString().slice(0, 10),
      label: monthLabel,
      projectedInflow: Math.round(projectedInflow * 100) / 100,
      projectedOutflow: Math.round(projectedOutflow * 100) / 100,
      projectedNet: Math.round(projectedNet * 100) / 100,
      projectedBalance: Math.round(runningBalance * 100) / 100,
      confidence: Math.round(confidence * 100) / 100,
    });

    // Generate alerts
    if (runningBalance < alertThreshold) {
      alerts.push({
        type: runningBalance < 0 ? 'danger' : 'warning',
        message: runningBalance < 0
          ? `Projected negative cash balance of R ${Math.abs(runningBalance).toLocaleString('en-ZA', { minimumFractionDigits: 2 })} in ${monthLabel}`
          : `Cash balance projected to drop below threshold in ${monthLabel}`,
        date: forecastDate.toISOString().slice(0, 10),
        projectedBalance: Math.round(runningBalance * 100) / 100,
      });
    }
  }

  // Build assumptions list
  const assumptions: string[] = [];
  if (historical.length > 0) {
    assumptions.push(`Based on ${historical.length} months of historical data`);
  } else {
    assumptions.push('Limited historical data — forecast accuracy may be low');
  }
  if (recurringRevenue > 0) {
    assumptions.push(`Includes R ${recurringRevenue.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} monthly recurring revenue`);
  }
  if (receivables.length > 0) {
    const totalAR = receivables.reduce((s, r) => s + r.amount, 0);
    assumptions.push(`${receivables.length} outstanding invoices totalling R ${totalAR.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  if (payables.length > 0) {
    const totalAP = payables.reduce((s, p) => s + p.amount, 0);
    assumptions.push(`${payables.length} outstanding payables totalling R ${totalAP.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  assumptions.push('Confidence decreases for months further in the future');

  log.info('Cash flow forecast generated', {
    months: forecastMonths,
    currentBalance,
    pointCount: forecastPoints.length,
    alertCount: alerts.length,
  }, 'accounting');

  return {
    currentBalance: Math.round(currentBalance * 100) / 100,
    forecastPoints,
    alerts,
    assumptions,
    generatedAt: new Date().toISOString(),
  };
}

/** Get historical cash flow data for chart display */
export async function getHistoricalForChart(companyId: string, months = 6): Promise<HistoricalCashFlow[]> {
  return getHistoricalCashFlows(companyId, months);
}

