/**
 * Migration AP Service — Supplier Invoice Import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import { updateSession, type ImportResult, type MigrationError } from './migrationService';
import { matchContact } from './migrationImportService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface APInvoiceRow {
  invoiceNumber: string;
  supplierName: string;
  invoiceDate: string;
  dueDate: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  amountPaid: number;
  reference?: string;
}

// ── AP Invoice Import ────────────────────────────────────────────────────────

export async function importAPInvoices(
  companyId: string,
  sessionId: string,
  invoices: APInvoiceRow[],
  userId: string,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const apAccountId      = await getSystemAccountId('payable');
  const expenseAccountId = await getSystemAccountId('default_expense');
  const vatInputId       = await getSystemAccountId('vat_input');

  const supRows = (await sql`
    SELECT id, COALESCE(company_name, name) AS name FROM suppliers
    WHERE company_id = ${companyId}::UUID
  `) as Row[];

  for (let i = 0; i < invoices.length; i++) {
    const inv = invoices[i]!;
    try {
      const supplierId = matchContact(inv.supplierName, supRows);
      if (!supplierId) {
        errors.push({ step: 'ap_invoices', row: i, field: 'supplierName', message: `Supplier not found: ${inv.supplierName}` });
        skipped++;
        continue;
      }

      const balance = inv.totalAmount - (inv.amountPaid ?? 0);
      const status  = balance <= 0 ? 'paid' : inv.amountPaid > 0 ? 'partially_paid' : 'approved';

      const invRows = (await sql`
        INSERT INTO supplier_invoices (
          company_id, supplier_id, invoice_number, invoice_date, due_date,
          subtotal, tax_amount, total_amount, amount_paid, balance_due,
          status, reference, created_by
        ) VALUES (
          ${companyId}::UUID, ${supplierId}::UUID, ${inv.invoiceNumber},
          ${inv.invoiceDate}::DATE, ${inv.dueDate}::DATE,
          ${inv.subtotal}, ${inv.taxAmount}, ${inv.totalAmount},
          ${inv.amountPaid ?? 0}, ${balance}, ${status},
          ${inv.reference ?? null}, ${userId}::UUID
        )
        ON CONFLICT DO NOTHING
        RETURNING id
      `) as Row[];

      if (invRows.length === 0) { skipped++; continue; }
      const invoiceId = String(invRows[0].id);

      // Post GL: DR Expense + VAT Input, CR Payable
      const journalLines = [
        { glAccountId: expenseAccountId, debit: inv.subtotal,   credit: 0,              description: `Expense — ${inv.invoiceNumber}` },
        { glAccountId: apAccountId,      debit: 0,              credit: inv.totalAmount, description: `AP — ${inv.invoiceNumber}` },
      ];
      if (inv.taxAmount > 0) {
        // DR VAT Input (claimable input tax), AP credit already equals totalAmount
        journalLines.push({ glAccountId: vatInputId, debit: inv.taxAmount, credit: 0, description: `VAT Input — ${inv.invoiceNumber}` });
      }

      const entry = await createJournalEntry(companyId, {
        entryDate: inv.invoiceDate,
        description: `Migrated AP invoice ${inv.invoiceNumber}`,
        source: 'auto_migration',
        sourceDocumentId: invoiceId,
        lines: journalLines,
      }, userId);
      await postJournalEntry(companyId, entry.id, userId);
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'ap_invoices', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { apInvoicesImported: imported, stepsCompleted: { ap_invoices: true }, errors });
  log.info('AP invoices imported', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

/**
 * Migration COA Service — Chart of Accounts import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { clearSystemAccountCache } from './systemAccountResolver';
import { updateSession } from './migrationService';
import type { ImportResult, MigrationError } from './migrationService';
import type { GLAccountType } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface AccountImportRow {
  accountCode: string;
  accountName: string;
  accountType: GLAccountType;
  accountSubtype?: string;
  parentCode?: string;
  normalBalance: 'debit' | 'credit';
  description?: string;
}

export interface SystemAccountMap {
  bank: string;
  receivable: string;
  payable: string;
  vat_input: string;
  vat_output: string;
  retained_earnings: string;
  default_revenue: string;
  default_expense: string;
  admin_expense: string;
}

// ── Public API ───────────────────────────────────────────────────────────────

export async function importChartOfAccounts(
  companyId: string,
  sessionId: string,
  accounts: AccountImportRow[],
  systemAccountMap: SystemAccountMap,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  // Sort: accounts without parents first, then those with parents (preserves hierarchy)
  const sorted = [...accounts.filter(a => !a.parentCode), ...accounts.filter(a => a.parentCode)];

  for (let i = 0; i < sorted.length; i++) {
    const acct = sorted[i]!;
    try {
      let parentAccountId: string | null = null;
      if (acct.parentCode) {
        const parentRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE account_code = ${acct.parentCode} AND company_id = ${companyId}::UUID
        `) as Row[];
        if (parentRows.length === 0) {
          errors.push({ step: 'coa', row: i, field: 'parentCode', message: `Parent code ${acct.parentCode} not found` });
          skipped++;
          continue;
        }
        parentAccountId = String(parentRows[0].id);
      }

      const subtypeEntry = Object.entries(systemAccountMap).find(([, code]) => code === acct.accountCode);
      const accountSubtype = subtypeEntry ? subtypeEntry[0] : (acct.accountSubtype ?? null);
      const isSystem = subtypeEntry != null;

      await sql`
        INSERT INTO gl_accounts (
          company_id, account_code, account_name, account_type, account_subtype,
          normal_balance, parent_account_id, description, is_system_account,
          level, display_order
        ) VALUES (
          ${companyId}::UUID,
          ${acct.accountCode},
          ${acct.accountName},
          ${acct.accountType},
          ${accountSubtype},
          ${acct.normalBalance},
          ${parentAccountId}::UUID,
          ${acct.description ?? null},
          ${isSystem},
          ${parentAccountId ? 2 : 1},
          0
        )
        ON CONFLICT (company_id, account_code) DO UPDATE SET
          account_name      = EXCLUDED.account_name,
          account_type      = EXCLUDED.account_type,
          account_subtype   = COALESCE(EXCLUDED.account_subtype, gl_accounts.account_subtype),
          normal_balance    = EXCLUDED.normal_balance,
          description       = COALESCE(EXCLUDED.description, gl_accounts.description),
          is_system_account = EXCLUDED.is_system_account OR gl_accounts.is_system_account
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'coa', row: i, field: 'accountCode', message: msg });
      skipped++;
    }
  }

  // Enforce system account subtype + flag for explicitly mapped accounts
  for (const [subtype, accountCode] of Object.entries(systemAccountMap)) {
    await sql`
      UPDATE gl_accounts
      SET account_subtype = ${subtype}, is_system_account = true
      WHERE company_id = ${companyId}::UUID AND account_code = ${accountCode}
    `;
  }

  clearSystemAccountCache();

  await updateSession(sessionId, companyId, {
    coaRecordsImported: imported,
    stepsCompleted: { coa: true },
    errors,
  });

  log.info('COA import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

/**
 * Cost Centre (Analysis Code) Service
 * Phase 5: Custom reporting dimensions for GL entries
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export type CcType = 'cc1' | 'cc2';

export interface CostCentre {
  id: string;
  code: string;
  name: string;
  description?: string;
  department?: string;
  ccType: CcType;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface CostCentreInput {
  code: string;
  name: string;
  description?: string;
  department?: string;
  ccType?: CcType;
}

export async function getCostCentres(companyId: string, activeOnly = false, ccType?: CcType): Promise<CostCentre[]> {
  let rows: Row[];
  if (ccType && activeOnly) {
    rows = (await sql`SELECT * FROM cost_centres WHERE company_id = ${companyId} AND cc_type = ${ccType} AND is_active = true ORDER BY code`) as Row[];
  } else if (ccType) {
    rows = (await sql`SELECT * FROM cost_centres WHERE company_id = ${companyId} AND cc_type = ${ccType} ORDER BY code`) as Row[];
  } else if (activeOnly) {
    rows = (await sql`SELECT * FROM cost_centres WHERE company_id = ${companyId} AND is_active = true ORDER BY code`) as Row[];
  } else {
    rows = (await sql`SELECT * FROM cost_centres WHERE company_id = ${companyId} ORDER BY code`) as Row[];
  }
  return rows.map(mapRow);
}

export async function getCostCentre(id: string): Promise<CostCentre | null> {
  const rows = (await sql`SELECT * FROM cost_centres WHERE id = ${id}::UUID`) as Row[];
  return rows[0] ? mapRow(rows[0]) : null;
}

export async function createCostCentre(companyId: string, input: CostCentreInput, _userId: string): Promise<CostCentre> {
  const rows = (await sql`
    INSERT INTO cost_centres (company_id, code, name, description, department, cc_type)
    VALUES (${companyId}, ${input.code}, ${input.name}, ${input.description || null}, ${input.department || null}, ${input.ccType || 'cc1'})
    RETURNING *
  `) as Row[];
  log.info('Created cost centre', { id: rows[0].id, code: input.code }, 'accounting');
  return mapRow(rows[0]);
}

export async function updateCostCentre(companyId: string, id: string, input: Partial<CostCentreInput>): Promise<CostCentre> {
  const rows = (await sql`
    UPDATE cost_centres SET
      code = COALESCE(${input.code || null}, code),
      name = COALESCE(${input.name || null}, name),
      description = COALESCE(${input.description || null}, description),
      department = COALESCE(${input.department || null}, department)
    WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Cost centre ${id} not found`);
  return mapRow(rows[0]);
}

export async function toggleCostCentre(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE cost_centres SET is_active = ${isActive} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

export async function deleteCostCentre(companyId: string, id: string): Promise<void> {
  // Check for usage in journal lines
  const usage = (await sql`
    SELECT COUNT(*) as cnt FROM gl_journal_lines WHERE cost_center_id = ${id}::UUID OR cc1_id = ${id}::UUID OR cc2_id = ${id}::UUID
  `) as Row[];
  if (Number(usage[0]?.cnt) > 0) {
    throw new Error('Cannot delete cost centre that is used in journal entries. Deactivate instead.');
  }
  await sql`DELETE FROM cost_centres WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

function mapRow(row: Row): CostCentre {
  return {
    id: String(row.id),
    code: String(row.code),
    name: String(row.name),
    description: row.description ? String(row.description) : undefined,
    department: row.department ? String(row.department) : undefined,
    ccType: (row.cc_type || 'cc1') as CcType,
    isActive: Boolean(row.is_active),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Migration Contact Service — Customers + Suppliers import
 * PRD: Customer Migration Wizard — Phase 1
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { updateSession } from './migrationService';
import type { ImportResult, MigrationError } from './migrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface CustomerImportRow {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  registrationNumber?: string;
  billingAddress?: string;
  contactPerson?: string;
  paymentTerms?: number;
  creditLimit?: number;
  notes?: string;
}

export interface SupplierImportRow {
  name: string;
  email?: string;
  phone?: string;
  vatNumber?: string;
  registrationNumber?: string;
  billingAddress?: string;
  contactPerson?: string;
  paymentTerms?: number;
  bankName?: string;
  bankAccountNumber?: string;
  bankBranchCode?: string;
  bankAccountType?: string;
  notes?: string;
}

export type DuplicateStrategy = 'skip' | 'overwrite' | 'merge';

// ── Customers ────────────────────────────────────────────────────────────────

export async function importCustomers(
  companyId: string,
  sessionId: string,
  customers: CustomerImportRow[],
  duplicateStrategy: DuplicateStrategy = 'skip',
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const existingRows = (await sql`
    SELECT id, name FROM customers WHERE company_id = ${companyId}::UUID
  `) as Row[];
  const existing = existingRows.map(r => ({ id: String(r.id), name: String(r.name) }));

  for (let i = 0; i < customers.length; i++) {
    const cust = customers[i]!;
    if (!cust.name?.trim()) {
      errors.push({ step: 'customers', row: i, field: 'name', message: 'Name is required' });
      skipped++;
      continue;
    }

    try {
      const duplicate = findDuplicate(cust.name, existing);

      if (duplicate && duplicateStrategy === 'skip') { skipped++; continue; }

      if (duplicate && duplicateStrategy === 'overwrite') {
        await sql`
          UPDATE customers SET
            email           = COALESCE(${cust.email ?? null}, email),
            phone           = COALESCE(${cust.phone ?? null}, phone),
            vat_number      = COALESCE(${cust.vatNumber ?? null}, vat_number),
            billing_address = COALESCE(${cust.billingAddress ?? null}, billing_address),
            contact_person  = COALESCE(${cust.contactPerson ?? null}, contact_person),
            payment_terms   = COALESCE(${cust.paymentTerms ?? null}, payment_terms),
            credit_limit    = COALESCE(${cust.creditLimit ?? null}, credit_limit)
          WHERE id = ${duplicate.id}::UUID AND company_id = ${companyId}::UUID
        `;
        imported++;
        continue;
      }

      await sql`
        INSERT INTO customers (
          company_id, name, email, phone, vat_number, registration_number,
          billing_address, contact_person, payment_terms, credit_limit, notes
        ) VALUES (
          ${companyId}::UUID, ${cust.name}, ${cust.email ?? null}, ${cust.phone ?? null},
          ${cust.vatNumber ?? null}, ${cust.registrationNumber ?? null},
          ${cust.billingAddress ?? null}, ${cust.contactPerson ?? null},
          ${cust.paymentTerms ?? 30}, ${cust.creditLimit ?? null}, ${cust.notes ?? null}
        )
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'customers', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { customersImported: imported, stepsCompleted: { customers: true } });
  log.info('Customer import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Suppliers ────────────────────────────────────────────────────────────────

export async function importSuppliers(
