          ${sup.bankBranchCode ?? null}, ${sup.bankAccountType ?? null}, ${sup.notes ?? null}
        )
      `;
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'suppliers', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { suppliersImported: imported, stepsCompleted: { suppliers: true } });
  log.info('Supplier import complete', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Duplicate detection ──────────────────────────────────────────────────────

function findDuplicate(
  name: string,
  existing: Array<{ id: string; name: string }>,
): { id: string; name: string } | null {
  const normalized = name.toLowerCase().trim();
  const exact = existing.find(e => e.name.toLowerCase().trim() === normalized);
  if (exact) return exact;

  for (const e of existing) {
    if (diceCoefficient(normalized, e.name.toLowerCase().trim()) >= 0.8) return e;
  }
  return null;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const ba = new Set<string>(), bb = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) ba.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bb.add(b.substring(i, i + 2));
  let n = 0;
  for (const g of ba) { if (bb.has(g)) n++; }
  return (2 * n) / (ba.size + bb.size);
}

/**
 * Migration Execute Service — import parsed Xero/QuickBooks/Pastel data into ISAFlow
 * Uses existing migrationCoaService and migrationContactService patterns.
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { ParsedAccount, ParsedEntity, MigrationSource } from './migrationParserService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface ExecuteMigrationResult {
  accountsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: number;
  errors: string[];
}

export interface VerifyEntry {
  accountCode: string;
  sourceName: string;
  sourceBalance: number;
  isaflowBalance: number;
  difference: number;
  matched: boolean;
}

// ── Execute ──────────────────────────────────────────────────────────────────

export async function executeMigration(
  companyId: string,
  userId: string,
  source: MigrationSource,
  accounts: ParsedAccount[],
  customers: ParsedEntity[],
  suppliers: ParsedEntity[],
): Promise<ExecuteMigrationResult> {
  const errors: string[] = [];
  let accountsImported = 0;
  let customersImported = 0;
  let suppliersImported = 0;
  let openingBalancesSet = 0;

  log.info('Starting migration execution', { companyId, source, accountCount: accounts.length }, 'migration');

  // 1. Import GL accounts
  const validAccounts = accounts.filter(acct => {
    if (!acct.sourceCode && !acct.sourceName) return false;
    if (!acct.mappedType) {
      errors.push(`Account "${acct.sourceCode} ${acct.sourceName}": unmapped type "${acct.sourceType}" — skipped`);
      return false;
    }
    return true;
  });

  if (validAccounts.length > 0) {
    try {
      await transaction((txSql) =>
        validAccounts.map(acct => txSql`
          INSERT INTO gl_accounts (
            company_id, account_code, account_name, account_type, account_subtype,
            normal_balance, description, level, display_order, imported_from
          ) VALUES (
            ${companyId}::UUID,
            ${acct.sourceCode || acct.sourceName.substring(0, 20)},
            ${acct.sourceName},
            ${acct.mappedType},
            ${acct.mappedSubtype ?? null},
            ${acct.mappedNormalBalance ?? 'debit'},
            ${'Imported from ' + source},
            3,
            0,
            ${source}
          )
          ON CONFLICT (company_id, account_code) DO UPDATE SET
            account_name  = EXCLUDED.account_name,
            account_type  = EXCLUDED.account_type,
            imported_from = EXCLUDED.imported_from
        `)
      );
      accountsImported = validAccounts.length;
    } catch (err) {
      errors.push(`Accounts batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 2. Set opening balances via journal entry
  const balanceAccounts = accounts.filter(a => a.openingBalance !== 0 && a.sourceCode && a.mappedType);
  if (balanceAccounts.length > 0) {
    try {
      const jeRows = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, reference, description, status, created_by
        ) VALUES (
          ${companyId}::UUID,
          CURRENT_DATE,
          ${'OB-' + source.toUpperCase()},
          ${'Opening balances imported from ' + source},
          'posted',
          ${userId}::UUID
        ) RETURNING id
      `) as Row[];

      const jeId = String(jeRows[0].id);

      for (const acct of balanceAccounts) {
        const glRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE company_id = ${companyId}::UUID AND account_code = ${acct.sourceCode}
          LIMIT 1
        `) as Row[];

        if (glRows.length === 0) continue;
        const glId = String(glRows[0].id);
        const isDebitNormal = acct.mappedNormalBalance === 'debit';
        const debit  = isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;
        const credit = !isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;

        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
          VALUES (${jeId}::UUID, ${glId}::UUID, ${debit}, ${credit}, ${'Opening balance — ' + source})
        `;
        openingBalancesSet++;
      }
    } catch (err) {
      errors.push(`Opening balances: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 3. Import customers
  const validCustomers = customers.filter(c => c.name?.trim());
  if (validCustomers.length > 0) {
    try {
      await transaction((txSql) =>
        validCustomers.map(cust => txSql`
          INSERT INTO customers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${cust.name},
            ${cust.email ?? null},
            ${cust.phone ?? null},
            ${cust.vatNumber ?? null},
            ${cust.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      customersImported = validCustomers.length;
    } catch (err) {
      errors.push(`Customers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 4. Import suppliers
  const validSuppliers = suppliers.filter(s => s.name?.trim());
  if (validSuppliers.length > 0) {
    try {
      await transaction((txSql) =>
        validSuppliers.map(sup => txSql`
          INSERT INTO suppliers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${sup.name},
            ${sup.email ?? null},
            ${sup.phone ?? null},
            ${sup.vatNumber ?? null},
            ${sup.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      suppliersImported = validSuppliers.length;
    } catch (err) {
      errors.push(`Suppliers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  log.info('Migration execution complete', {
    companyId, source, accountsImported, customersImported, suppliersImported,
  }, 'migration');

  return { accountsImported, customersImported, suppliersImported, openingBalancesSet, errors };
}

// ── Verify balances ───────────────────────────────────────────────────────────

export async function verifyBalances(
  companyId: string,
  sourceAccounts: ParsedAccount[],
): Promise<VerifyEntry[]> {
  const results: VerifyEntry[] = [];

  for (const acct of sourceAccounts) {
    if (!acct.sourceCode) continue;

    try {
      const glRows = (await sql`
        SELECT ga.account_name,
          COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS net_debit,
          ga.normal_balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
        WHERE ga.company_id = ${companyId}::UUID AND ga.account_code = ${acct.sourceCode}
        GROUP BY ga.id, ga.account_name, ga.normal_balance
        LIMIT 1
      `) as Row[];

      const isaflowBalance = glRows.length > 0
        ? (String(glRows[0].normal_balance) === 'debit'
          ? Number(glRows[0].net_debit)
          : -Number(glRows[0].net_debit))
        : 0;

      const difference = acct.openingBalance - isaflowBalance;

      results.push({
        accountCode:    acct.sourceCode,
        sourceName:     acct.sourceName,
        sourceBalance:  acct.openingBalance,
        isaflowBalance,
        difference,
        matched:        Math.abs(difference) < 0.01,
      });
    } catch (err) {
      log.warn('Balance verification failed for account', { code: acct.sourceCode, error: err }, 'migration');
    }
  }

  return results;
}

// ── Rollback ─────────────────────────────────────────────────────────────────

export async function rollbackMigration(
  companyId: string,
  source: MigrationSource,
): Promise<{ deleted: number }> {
  let deleted = 0;

  try {
    // Remove GL accounts imported from this source
    const acctRows = (await sql`
      DELETE FROM gl_accounts
      WHERE company_id = ${companyId}::UUID AND imported_from = ${source}
      RETURNING id
    `) as Row[];
    deleted += acctRows.length;

    log.info('Rollback complete', { companyId, source, deleted }, 'migration');
  } catch (err) {
    log.error('Rollback failed', { companyId, source, error: err }, 'migration');
    throw err;
  }

  return { deleted };
}

/**
 * Migration Import Service — Opening Balances + AR Invoices
 * PRD: Customer Migration Wizard — Phase 1
 *
 * AP invoice import is in migrationApService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccountId } from './systemAccountResolver';
import { updateSession, type ImportResult, type MigrationError } from './migrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface OpeningBalanceRow {
  accountCode: string;
  debit: number;
  credit: number;
}

export interface ARInvoiceRow {
  invoiceNumber: string;
  customerName: string;
  invoiceDate: string;
  dueDate: string;
  subtotal: number;
  taxAmount: number;
  totalAmount: number;
  amountPaid: number;
  reference?: string;
}

// ── Opening Balances ─────────────────────────────────────────────────────────

export async function importOpeningBalances(
  companyId: string,
  sessionId: string,
  effectiveDate: string,
  balances: OpeningBalanceRow[],
  userId: string,
): Promise<{ journalEntryId: string; errors: MigrationError[] }> {
  const errors: MigrationError[] = [];

  const totalDebit  = balances.reduce((s, b) => s + (b.debit ?? 0), 0);
  const totalCredit = balances.reduce((s, b) => s + (b.credit ?? 0), 0);

  if (Math.abs(totalDebit - totalCredit) > 0.01) {
    throw new Error(
      `Trial balance is not balanced: debits ${totalDebit.toFixed(2)} ≠ credits ${totalCredit.toFixed(2)}`
    );
  }

  const lines = [];
  for (let i = 0; i < balances.length; i++) {
    const bal = balances[i]!;
    if (bal.debit === 0 && bal.credit === 0) continue;

    const acctRows = (await sql`
      SELECT id FROM gl_accounts
      WHERE account_code = ${bal.accountCode} AND company_id = ${companyId}::UUID
    `) as Row[];

    if (acctRows.length === 0) {
      errors.push({ step: 'opening_balances', row: i, field: 'accountCode', message: `Account ${bal.accountCode} not found` });
      continue;
    }

    lines.push({
      glAccountId: String(acctRows[0].id),
      debit: bal.debit ?? 0,
      credit: bal.credit ?? 0,
      description: `Opening balance — ${bal.accountCode}`,
    });
  }

  if (lines.length === 0) {
    throw new Error('No valid balance rows to import');
  }

  const entry = await createJournalEntry(companyId, {
    entryDate: effectiveDate,
    description: 'Opening balances — migration import',
    source: 'auto_migration',
    lines,
  }, userId);

  await postJournalEntry(companyId, entry.id, userId);

  await updateSession(sessionId, companyId, {
    openingBalancesSet: true,
    stepsCompleted: { opening_balances: true },
    errors,
  });

  log.info('Opening balances imported', { companyId, journalEntryId: entry.id, lines: lines.length }, 'migration');
  return { journalEntryId: entry.id, errors };
}

// ── AR Invoice Import ────────────────────────────────────────────────────────

export async function importARInvoices(
  companyId: string,
  sessionId: string,
  invoices: ARInvoiceRow[],
  userId: string,
): Promise<ImportResult> {
  const errors: MigrationError[] = [];
  let imported = 0;
  let skipped = 0;

  const arAccountId      = await getSystemAccountId('receivable');
  const revenueAccountId = await getSystemAccountId('default_revenue');
  const vatOutputId      = await getSystemAccountId('vat_output');

  const custRows = (await sql`
    SELECT id, name FROM customers WHERE company_id = ${companyId}::UUID
  `) as Row[];

  for (let i = 0; i < invoices.length; i++) {
    const inv = invoices[i]!;
    try {
      const customerId = matchContact(inv.customerName, custRows);
      if (!customerId) {
        errors.push({ step: 'ar_invoices', row: i, field: 'customerName', message: `Customer not found: ${inv.customerName}` });
        skipped++;
        continue;
      }

      const balance = inv.totalAmount - (inv.amountPaid ?? 0);
      const status  = balance <= 0 ? 'paid' : inv.amountPaid > 0 ? 'partially_paid' : 'approved';

      const invRows = (await sql`
        INSERT INTO customer_invoices (
          company_id, customer_id, client_id, invoice_number, invoice_date, due_date,
          subtotal, tax_amount, total_amount, amount_paid, balance_due,
          status, reference, created_by
        ) VALUES (
          ${companyId}::UUID, ${customerId}::UUID, ${customerId}::UUID, ${inv.invoiceNumber},
          ${inv.invoiceDate}::DATE, ${inv.dueDate}::DATE,
          ${inv.subtotal}, ${inv.taxAmount}, ${inv.totalAmount},
          ${inv.amountPaid ?? 0}, ${balance}, ${status},
          ${inv.reference ?? null}, ${userId}::UUID
        )
        ON CONFLICT DO NOTHING
        RETURNING id
      `) as Row[];

      if (invRows.length === 0) { skipped++; continue; }
      const invoiceId = String(invRows[0].id);

      const journalLines = [
        { glAccountId: arAccountId,      debit: inv.totalAmount, credit: 0,             description: `AR — ${inv.invoiceNumber}` },
        { glAccountId: revenueAccountId, debit: 0,               credit: inv.subtotal,  description: `Revenue — ${inv.invoiceNumber}` },
      ];
      if (inv.taxAmount > 0) {
        journalLines.push({ glAccountId: vatOutputId, debit: 0, credit: inv.taxAmount, description: `VAT — ${inv.invoiceNumber}` });
      }

      const entry = await createJournalEntry(companyId, {
        entryDate: inv.invoiceDate,
        description: `Migrated AR invoice ${inv.invoiceNumber}`,
        source: 'auto_migration',
        sourceDocumentId: invoiceId,
        lines: journalLines,
      }, userId);
      await postJournalEntry(companyId, entry.id, userId);
      imported++;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      errors.push({ step: 'ar_invoices', row: i, message: msg });
      skipped++;
    }
  }

  await updateSession(sessionId, companyId, { arInvoicesImported: imported, stepsCompleted: { ar_invoices: true }, errors });
  log.info('AR invoices imported', { companyId, imported, skipped }, 'migration');
  return { imported, skipped, errors };
}

// ── Helpers ──────────────────────────────────────────────────────────────────

export function matchContact(name: string, candidates: Row[]): string | null {
  const normalized = name.toLowerCase().trim();
  const exact = candidates.find(c => String(c.name).toLowerCase().trim() === normalized);
  if (exact) return String(exact.id);
  let best: { id: string; score: number } | null = null;
  for (const c of candidates) {
    const score = diceCoefficient(normalized, String(c.name).toLowerCase().trim());
    if (score >= 0.7 && (!best || score > best.score)) best = { id: String(c.id), score };
  }
  return best?.id ?? null;
}

function diceCoefficient(a: string, b: string): number {
  if (a === b) return 1;
  if (a.length < 2 || b.length < 2) return 0;
  const ba = new Set<string>(), bb = new Set<string>();
  for (let i = 0; i < a.length - 1; i++) ba.add(a.substring(i, i + 2));
  for (let i = 0; i < b.length - 1; i++) bb.add(b.substring(i, i + 2));
  let n = 0;
  for (const g of ba) { if (bb.has(g)) n++; }
  return (2 * n) / (ba.size + bb.size);
}

/**
 * Migration Service — Session management
 * PRD: Customer Migration Wizard — Phase 1
 *
 * CRUD for migration_sessions. See also:
 *   migrationCoaService.ts  — Chart of accounts import
 *   migrationContactService.ts — Customers + suppliers import
 *   migrationImportService.ts  — Opening balances + AR/AP invoices
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Shared types (re-exported for consumers) ─────────────────────────────────

export type MigrationStatus = 'in_progress' | 'completed' | 'abandoned';

export interface MigrationSession {
  id: string;
  companyId: string;
  sourceSystem: string | null;
  status: MigrationStatus;
  stepsCompleted: Record<string, boolean>;
  coaRecordsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: boolean;
  arInvoicesImported: number;
  apInvoicesImported: number;
  errors: MigrationError[];
  startedBy: string;
  startedAt: string;
  completedAt: string | null;
  notes: string | null;
}

export interface MigrationError {
  step: string;
  row?: number;
  field?: string;
  message: string;
}

export interface ImportResult {
  imported: number;
  skipped: number;
  errors: MigrationError[];
}

// ── Row mapper ───────────────────────────────────────────────────────────────

export function mapSessionRow(r: Row): MigrationSession {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    sourceSystem: r.source_system ?? null,
    status: r.status as MigrationStatus,
    stepsCompleted: (r.steps_completed as Record<string, boolean>) ?? {},
    coaRecordsImported: Number(r.coa_records_imported ?? 0),
    customersImported: Number(r.customers_imported ?? 0),
    suppliersImported: Number(r.suppliers_imported ?? 0),
    openingBalancesSet: Boolean(r.opening_balances_set),
    arInvoicesImported: Number(r.ar_invoices_imported ?? 0),
    apInvoicesImported: Number(r.ap_invoices_imported ?? 0),
    errors: (r.errors as MigrationError[]) ?? [],
    startedBy: String(r.started_by),
    startedAt: r.started_at instanceof Date ? r.started_at.toISOString() : String(r.started_at),
    completedAt: r.completed_at
      ? (r.completed_at instanceof Date ? r.completed_at.toISOString() : String(r.completed_at))
      : null,
    notes: r.notes ?? null,
  };
}

// ── Public API ───────────────────────────────────────────────────────────────

export async function createSession(
  companyId: string,
  sourceSystem: string,
  userId: string,
): Promise<MigrationSession> {
  const rows = (await sql`
    INSERT INTO migration_sessions (company_id, source_system, started_by)
    VALUES (${companyId}::UUID, ${sourceSystem}, ${userId}::UUID)
    RETURNING *
  `) as Row[];
  log.info('Migration session created', { companyId, sourceSystem }, 'migration');
  return mapSessionRow(rows[0]);
}

export async function getSession(
  sessionId: string,
  companyId: string,
): Promise<MigrationSession | null> {
  const rows = (await sql`
    SELECT * FROM migration_sessions
    WHERE id = ${sessionId}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];
  return rows.length > 0 ? mapSessionRow(rows[0]) : null;
}

export async function listSessions(companyId: string): Promise<MigrationSession[]> {
  const rows = (await sql`
    SELECT * FROM migration_sessions
    WHERE company_id = ${companyId}::UUID
    ORDER BY started_at DESC
  `) as Row[];
  return rows.map(mapSessionRow);
}

export async function updateSession(
  sessionId: string,
  companyId: string,
  updates: Partial<Pick<MigrationSession,
    | 'sourceSystem' | 'status' | 'stepsCompleted'
    | 'coaRecordsImported' | 'customersImported' | 'suppliersImported'
    | 'openingBalancesSet' | 'arInvoicesImported' | 'apInvoicesImported'
    | 'errors' | 'notes' | 'completedAt'
  >>,
): Promise<MigrationSession> {
  const rows = (await sql`
    UPDATE migration_sessions SET
      source_system        = COALESCE(${updates.sourceSystem ?? null}, source_system),
      status               = COALESCE(${updates.status ?? null}, status),
      steps_completed      = COALESCE(${updates.stepsCompleted ? JSON.stringify(updates.stepsCompleted) : null}::JSONB, steps_completed),
      coa_records_imported = COALESCE(${updates.coaRecordsImported ?? null}, coa_records_imported),
      customers_imported   = COALESCE(${updates.customersImported ?? null}, customers_imported),
      suppliers_imported   = COALESCE(${updates.suppliersImported ?? null}, suppliers_imported),
      opening_balances_set = COALESCE(${updates.openingBalancesSet ?? null}, opening_balances_set),
      ar_invoices_imported = COALESCE(${updates.arInvoicesImported ?? null}, ar_invoices_imported),
      ap_invoices_imported = COALESCE(${updates.apInvoicesImported ?? null}, ap_invoices_imported),
      errors               = COALESCE(${updates.errors ? JSON.stringify(updates.errors) : null}::JSONB, errors),
      notes                = COALESCE(${updates.notes ?? null}, notes),
      completed_at         = COALESCE(${updates.completedAt ?? null}::TIMESTAMPTZ, completed_at)
    WHERE id = ${sessionId}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `) as Row[];
  return mapSessionRow(rows[0]);
}

export async function completeSession(
  sessionId: string,
  companyId: string,
): Promise<MigrationSession> {
  const rows = (await sql`
    UPDATE migration_sessions
    SET status = 'completed', completed_at = NOW()
    WHERE id = ${sessionId}::UUID AND company_id = ${companyId}::UUID
    RETURNING *
  `) as Row[];
  log.info('Migration session completed', { sessionId, companyId }, 'migration');
  return mapSessionRow(rows[0]);
}

/**
 * Migration Validation Service
 * PRD: Customer Migration Wizard — Phase 1
 *
 * Pre/post migration validation checks used in Step 8: Validation & Go-Live.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { validateSystemAccounts } from './systemAccountResolver';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export type ValidationStatus = 'pass' | 'fail' | 'warn';

export interface ValidationResult {
  check: string;
  status: ValidationStatus;
  message: string;
  detail?: string;
}

// ── Public API ───────────────────────────────────────────────────────────────

/**
 * Run all post-migration validation checks.
 * Returns a list of results — caller decides pass/fail threshold.
 */
export async function validateMigration(
  companyId: string,
  sessionId: string,
): Promise<ValidationResult[]> {
  const results: ValidationResult[] = [];

  const [tb, arCheck, apCheck, sysAccounts, orphanAR, orphanAP] = await Promise.all([
    checkTrialBalance(companyId),
    checkARvsGL(companyId),
    checkAPvsGL(companyId),
    checkSystemAccounts(),
    checkOrphanARInvoices(companyId),
    checkOrphanAPInvoices(companyId),
  ]);

  results.push(tb, arCheck, apCheck, sysAccounts, orphanAR, orphanAP);

  log.info('Migration validation complete', {
    companyId,
    sessionId,
    passed: results.filter(r => r.status === 'pass').length,
    failed: results.filter(r => r.status === 'fail').length,
  }, 'migration');

  return results;
}

// ── Checks ───────────────────────────────────────────────────────────────────

async function checkTrialBalance(companyId: string): Promise<ValidationResult> {
  const rows = (await sql`
    SELECT
      COALESCE(SUM(jl.debit), 0)  AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    WHERE je.company_id = ${companyId}::UUID
      AND je.status = 'posted'
  `) as Row[];

  const totalDebit  = Number(rows[0]?.total_debit ?? 0);
  const totalCredit = Number(rows[0]?.total_credit ?? 0);
  const diff = Math.abs(totalDebit - totalCredit);

  if (diff <= 0.01) {
    return { check: 'Trial Balance', status: 'pass', message: 'Debits equal credits', detail: `Total: R${totalDebit.toFixed(2)}` };
  }

  return {
    check: 'Trial Balance',
    status: 'fail',
    message: 'Trial balance is not balanced',
    detail: `Debits: R${totalDebit.toFixed(2)}, Credits: R${totalCredit.toFixed(2)}, Diff: R${diff.toFixed(2)}`,
  };
}

async function checkARvsGL(companyId: string): Promise<ValidationResult> {
  // Sum of open customer invoice balances
  const invRows = (await sql`
    SELECT COALESCE(SUM(balance_due), 0) AS total
    FROM customer_invoices
    WHERE company_id = ${companyId}::UUID
      AND status IN ('approved', 'partially_paid', 'overdue')
  `) as Row[];

  // GL balance on receivable account
  const glRows = (await sql`
    SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS balance
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId}::UUID
      AND je.status = 'posted'
      AND ga.account_subtype = 'receivable'
      AND ga.company_id = ${companyId}::UUID
  `) as Row[];

  const invoiceTotal = Number(invRows[0]?.total ?? 0);
  const glBalance    = Number(glRows[0]?.balance ?? 0);
  const diff = Math.abs(invoiceTotal - glBalance);

  if (diff <= 0.01) {
    return { check: 'AR vs GL', status: 'pass', message: 'AR invoices match GL receivable balance', detail: `R${invoiceTotal.toFixed(2)}` };
  }

  return {
    check: 'AR vs GL',
    status: diff > 100 ? 'fail' : 'warn',
    message: 'AR invoice total does not exactly match GL receivable',
    detail: `Invoices: R${invoiceTotal.toFixed(2)}, GL: R${glBalance.toFixed(2)}, Diff: R${diff.toFixed(2)}`,
  };
}

async function checkAPvsGL(companyId: string): Promise<ValidationResult> {
  const invRows = (await sql`
    SELECT COALESCE(SUM(balance_due), 0) AS total
    FROM supplier_invoices
    WHERE company_id = ${companyId}::UUID
      AND status IN ('approved', 'partially_paid', 'overdue')
  `) as Row[];

  const glRows = (await sql`
    SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS balance
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.company_id = ${companyId}::UUID
      AND je.status = 'posted'
      AND ga.account_subtype = 'payable'
      AND ga.company_id = ${companyId}::UUID
  `) as Row[];

  const invoiceTotal = Number(invRows[0]?.total ?? 0);
  const glBalance    = Number(glRows[0]?.balance ?? 0);
  const diff = Math.abs(invoiceTotal - glBalance);

  if (diff <= 0.01) {
    return { check: 'AP vs GL', status: 'pass', message: 'AP invoices match GL payable balance', detail: `R${invoiceTotal.toFixed(2)}` };
  }

  return {
    check: 'AP vs GL',
    status: diff > 100 ? 'fail' : 'warn',
    message: 'AP invoice total does not exactly match GL payable',
    detail: `Invoices: R${invoiceTotal.toFixed(2)}, GL: R${glBalance.toFixed(2)}, Diff: R${diff.toFixed(2)}`,
  };
}

async function checkSystemAccounts(): Promise<ValidationResult> {
  const missing = await validateSystemAccounts();
  if (missing.length === 0) {
    return { check: 'System Accounts', status: 'pass', message: 'All system accounts are mapped and active' };
  }
  return {
    check: 'System Accounts',
    status: 'fail',
    message: `${missing.length} system account(s) not mapped`,
    detail: `Missing: ${missing.join(', ')}`,
  };
}

async function checkOrphanARInvoices(companyId: string): Promise<ValidationResult> {
  const rows = (await sql`
    SELECT COUNT(*) AS cnt
    FROM customer_invoices ci
    WHERE ci.company_id = ${companyId}::UUID
      AND COALESCE(ci.client_id, ci.customer_id) IS NULL
  `) as Row[];

  const cnt = Number(rows[0]?.cnt ?? 0);
  if (cnt === 0) {
    return { check: 'Orphan AR Invoices', status: 'pass', message: 'All customer invoices have a linked customer' };
  }
  return {
    check: 'Orphan AR Invoices',
    status: 'fail',
    message: `${cnt} customer invoice(s) have no linked customer`,
    detail: 'These invoices will not appear in AR aging reports',
  };
}

async function checkOrphanAPInvoices(companyId: string): Promise<ValidationResult> {
  const rows = (await sql`
    SELECT COUNT(*) AS cnt
    FROM supplier_invoices si
    WHERE si.company_id = ${companyId}::UUID
      AND si.supplier_id IS NULL
  `) as Row[];

  const cnt = Number(rows[0]?.cnt ?? 0);
  if (cnt === 0) {
    return { check: 'Orphan AP Invoices', status: 'pass', message: 'All supplier invoices have a linked supplier' };
  }
  return {
    check: 'Orphan AP Invoices',
    status: 'fail',
    message: `${cnt} supplier invoice(s) have no linked supplier`,
    detail: 'These invoices will not appear in AP aging reports',
  };
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 3
 * Credit Note Service (Customer & Supplier)
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry, reverseJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import type { CreditNote, CreditNoteCreateInput, CreditNoteStatus } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface CreditNoteFilters {
  type?: 'customer' | 'supplier';
  status?: CreditNoteStatus;
  limit?: number;
  offset?: number;
}

export async function getCreditNotes(companyId: string, filters?: CreditNoteFilters): Promise<{
  creditNotes: CreditNote[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    if (filters?.type) {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId} AND cn.type = ${filters.type}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId} AND type = ${filters.type}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
          COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
        FROM credit_notes cn
        LEFT JOIN customers c ON c.id = cn.client_id
        LEFT JOIN suppliers s ON s.id = cn.supplier_id
        LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
        LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
        WHERE cn.company_id = ${companyId}
        ORDER BY cn.credit_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`SELECT COUNT(*) AS cnt FROM credit_notes WHERE company_id = ${companyId}`) as Row[];
    }

    return { creditNotes: rows.map(mapRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get credit notes', { error: err }, 'accounting');
    throw err;
  }
}

export async function getCreditNoteById(companyId: string, id: string): Promise<CreditNote | null> {
  const rows = (await sql`
    SELECT cn.*, c.name AS client_name, COALESCE(s.company_name, s.name) AS supplier_name,
      COALESCE(ci.invoice_number, si.invoice_number) AS invoice_number
    FROM credit_notes cn
    LEFT JOIN customers c ON c.id = cn.client_id
    LEFT JOIN suppliers s ON s.id = cn.supplier_id
    LEFT JOIN customer_invoices ci ON ci.id = cn.customer_invoice_id
    LEFT JOIN supplier_invoices si ON si.id = cn.supplier_invoice_id
    WHERE cn.id = ${id}::UUID AND cn.company_id = ${companyId}
  `) as Row[];
  return rows.length > 0 ? mapRow(rows[0]) : null;
}

export async function createCreditNote(companyId: string, 
  input: CreditNoteCreateInput,
  userId: string
): Promise<CreditNote> {
  try {
    const taxRate = input.taxRate ?? 15;
    const taxAmount = Math.round(input.subtotal * taxRate / 100 * 100) / 100;
    const totalAmount = input.subtotal + taxAmount;

    const rows = (await sql`
      INSERT INTO credit_notes (
        type, client_id, customer_invoice_id, supplier_id, supplier_invoice_id,
        credit_date, reason, subtotal, tax_rate, tax_amount, total_amount,
        project_id, created_by
      ) VALUES (
        ${input.type}, ${input.clientId || null}, ${input.customerInvoiceId || null},
        ${input.supplierId ? Number(input.supplierId) : null},
        ${input.supplierInvoiceId || null},
        ${input.creditDate}, ${input.reason || null},
        ${input.subtotal}, ${taxRate}, ${taxAmount}, ${totalAmount},
        ${input.projectId || null}, ${userId}::UUID
      ) RETURNING *
    `) as Row[];

    log.info('Created credit note', { id: String(rows[0]!.id), type: input.type }, 'accounting');
    return mapRow(rows[0]!);
  } catch (err) {
    log.error('Failed to create credit note', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveCreditNote(companyId: string, id: string, userId: string): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'draft') throw new Error(`Cannot approve credit note with status: ${cn.status}`);

    let lines: JournalLineInput[];

    if (String(cn.type) === 'customer') {
      // Customer CN: DR Revenue, CR Accounts Receivable
      const revenueAccount = await getSystemAccount('default_revenue');
      const arAccount = await getSystemAccount('receivable');
      const vatAccount = await getSystemAccount('vat_output');

      lines = [
        { glAccountId: revenueAccount.id, debit: Number(cn.subtotal), credit: 0,
          description: `Credit note ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: Number(cn.tax_amount), credit: 0,
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: arAccount.id, debit: 0, credit: Number(cn.total_amount),
        description: `AR credit: ${cn.credit_note_number}` });
    } else {
      // Supplier CN: DR Accounts Payable, CR Expense
      const apAccount = await getSystemAccount('payable');
      const expenseAccount = await getSystemAccount('default_expense');
      const vatAccount = await getSystemAccount('vat_input');

      lines = [
        { glAccountId: apAccount.id, debit: Number(cn.total_amount), credit: 0,
          description: `AP credit: ${cn.credit_note_number}` },
      ];
      if (Number(cn.tax_amount) > 0 && vatAccount) {
        lines.push({ glAccountId: vatAccount.id, debit: 0, credit: Number(cn.tax_amount),
          description: `VAT reversal: ${cn.credit_note_number}` });
      }
      lines.push({ glAccountId: expenseAccount.id, debit: 0, credit: Number(cn.subtotal),
        description: `Expense credit: ${cn.credit_note_number}` });
    }

    const je = await createJournalEntry('', {
      entryDate: String(cn.credit_date),
      description: `Credit note ${cn.credit_note_number}`,
      source: 'auto_credit_note',
      sourceDocumentId: id,
      lines,
    }, userId);
    await postJournalEntry('', je.id, userId);

    // Update invoice balance and credit note status atomically
    const updated = await withTransaction(async (tx) => {
      if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
        await tx`
          UPDATE customer_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.customer_invoice_id}::UUID
        `;
      } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
        await tx`
          UPDATE supplier_invoices SET amount_paid = amount_paid + ${Number(cn.total_amount)}
          WHERE id = ${cn.supplier_invoice_id}::UUID
        `;
      }

      const rows = (await tx`
        UPDATE credit_notes SET status = 'approved', approved_by = ${userId}::UUID,
          approved_at = NOW(), gl_journal_entry_id = ${je.id}::UUID
        WHERE id = ${id} RETURNING *
      `) as Row[];

      return rows[0] as Row;
    });

    log.info('Approved credit note', { id, journalEntryId: je.id }, 'accounting');
    return mapRow(updated);
  } catch (err) {
    log.error('Failed to approve credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelCreditNote(companyId: string, 
  id: string,
  userId: string,
  reason?: string
): Promise<CreditNote> {
  try {
    const cnRows = (await sql`SELECT * FROM credit_notes WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
    if (cnRows.length === 0) throw new Error(`Credit note ${id} not found`);
    const cn = cnRows[0]!;
    if (String(cn.status) !== 'approved') {
      throw new Error(`Cannot cancel credit note with status: ${cn.status}`);
    }

    // Reverse GL journal entry
    if (cn.gl_journal_entry_id) {
      await reverseJournalEntry('', String(cn.gl_journal_entry_id), userId);
    }

    // Reverse invoice balance adjustments
    if (String(cn.type) === 'customer' && cn.customer_invoice_id) {
      await sql`
        UPDATE customer_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
        WHERE id = ${cn.customer_invoice_id}::UUID
      `;
      await sql`
        UPDATE customer_invoices SET status = CASE
          WHEN amount_paid <= 0.01 THEN 'approved'
          WHEN amount_paid < total_amount THEN 'partially_paid'
          ELSE status
        END
        WHERE id = ${cn.customer_invoice_id}::UUID
      `;
    } else if (String(cn.type) === 'supplier' && cn.supplier_invoice_id) {
      await sql`
        UPDATE supplier_invoices
        SET amount_paid = GREATEST(0, amount_paid - ${Number(cn.total_amount)})
        WHERE id = ${cn.supplier_invoice_id}::UUID
      `;
    }

    const updated = (await sql`
      UPDATE credit_notes
      SET status = 'cancelled', cancelled_by = ${userId}::UUID,
          cancelled_at = NOW(), cancel_reason = ${reason || null}
      WHERE id = ${id} RETURNING *
    `) as Row[];

    log.info('Cancelled credit note', { id, reason }, 'accounting');
    return mapRow(updated[0]!);
  } catch (err) {
    log.error('Failed to cancel credit note', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): CreditNote {
  return {
    id: String(row.id),
    creditNoteNumber: row.credit_note_number ? String(row.credit_note_number) : '',
    type: String(row.type) as CreditNote['type'],
    clientId: row.client_id ? String(row.client_id) : undefined,
    customerInvoiceId: row.customer_invoice_id ? String(row.customer_invoice_id) : undefined,
    supplierId: row.supplier_id ? String(row.supplier_id) : undefined,
    supplierInvoiceId: row.supplier_invoice_id ? String(row.supplier_invoice_id) : undefined,
    creditDate: String(row.credit_date),
    reason: row.reason ? String(row.reason) : undefined,
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    status: String(row.status) as CreditNoteStatus,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    invoiceNumber: row.invoice_number ? String(row.invoice_number) : undefined,
  };
}

/**
 * Data Archiving & Retention Engine Service
 * WS-7.4 — Move old posted financial data into archive_* tables.
 * SA Companies Act minimum retention: 5 years.
 * All archive operations run inside a transaction — rollback on any error.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { logAudit } from './auditTrailService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface StorageStats {
  tableName: string;
  rowCount: number;
  oldestDate: string | null;
  newestDate: string | null;
}

export interface ArchivePreview {
  journalEntries: number;
  journalLines: number;
  bankTransactions: number;
  customerInvoices: number;
  supplierInvoices: number;
  totalRecords: number;
}

export interface ArchiveValidation {
  valid: boolean;
  errors: string[];
}

export interface ArchiveResult {
  runId: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
  supplierInvoicesArchived: number;
}

export interface ArchiveRun {
  id: string;
  cutoffDate: string;
  status: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
  supplierInvoicesArchived: number;
  startedAt: string | null;
  completedAt: string | null;
  errorMessage: string | null;
  createdAt: string;
}

export interface ArchivedEntry {
  id: string;
  entryNumber: string | null;
  entryDate: string;
  description: string | null;
  status: string | null;
  source: string | null;
  createdAt: string;
}

const COMPONENT = 'data-archiving';
const MIN_RETENTION_YEARS = 5;

function toISODate(val: Date | string | null): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? null;
  return String(val).split('T')[0] ?? null;
}

function toStr(val: Date | string | null | undefined): string {
  if (!val) return '';
  if (val instanceof Date) return val.toISOString();
  return String(val);
}

