// ── Run Tracking (exported for sageImportService) ───────────────────────────

export async function startRun(runType: string, userId: string): Promise<string> {
  const rows = (await sql`
    INSERT INTO gl_migration_runs (run_type, status, started_by)
    VALUES (${runType}, 'running', ${userId})
    RETURNING id
  `) as Row[];
  return String(rows[0].id);
}

export async function completeRun(
  runId: string, total: number, succeeded: number, failed: number, skipped: number
): Promise<MigrationRun> {
  const status = failed === 0 ? 'completed' : 'partial';
  const rows = (await sql`
    UPDATE gl_migration_runs
    SET status = ${status}, total_records = ${total}, processed = ${succeeded + failed + skipped},
        succeeded = ${succeeded}, failed = ${failed}, skipped = ${skipped}, completed_at = NOW()
    WHERE id = ${runId}::UUID RETURNING *
  `) as Row[];
  const r = rows[0];
  return {
    id: String(r.id), runType: String(r.run_type), status: String(r.status),
    totalRecords: Number(r.total_records), processed: Number(r.processed),
    succeeded: Number(r.succeeded), failed: Number(r.failed), skipped: Number(r.skipped),
    startedAt: String(r.started_at), completedAt: r.completed_at ? String(r.completed_at) : null,
  };
}

export async function failRun(runId: string, err: unknown): Promise<void> {
  const msg = err instanceof Error ? err.message : 'Unknown error';
  await sql`
    UPDATE gl_migration_runs SET status = 'failed', error_message = ${msg}, completed_at = NOW()
    WHERE id = ${runId}::UUID
  `;
}

// ── Migration Status ────────────────────────────────────────────────────────

export async function getMigrationStatus(companyId: string): Promise<MigrationStatus> {
  try {
    const accountStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE gl_account_id IS NOT NULL) AS mapped,
        COUNT(*) FILTER (WHERE gl_account_id IS NULL) AS unmapped,
        COUNT(*) FILTER (WHERE mapping_status = 'auto') AS auto_mapped
      FROM sage_accounts
    `) as Row[];

    const ledgerStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
        COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed,
        MIN(transaction_date) AS earliest, MAX(transaction_date) AS latest
      FROM sage_ledger_transactions
    `) as Row[];

    const invoiceStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
        COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed
      FROM sage_supplier_invoices
    `) as Row[];

    let customerInvoiceStats: Row[] = [{ total: 0, imported: 0, pending: 0, failed: 0 }];
    try {
      customerInvoiceStats = (await sql`
        SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
          COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
          COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed
        FROM sage_customer_invoices
      `) as Row[];
    } catch {
      // Table may not exist yet if migration 212 hasn't run
    }

    const runs = (await sql`
      SELECT id, run_type, status, total_records, processed, succeeded, failed, skipped,
        started_at, completed_at
      FROM gl_migration_runs ORDER BY started_at DESC LIMIT 10
    `) as Row[];

    return {
      accounts: {
        sageTotal: Number(accountStats[0]?.total || 0), mapped: Number(accountStats[0]?.mapped || 0),
        unmapped: Number(accountStats[0]?.unmapped || 0), autoMapped: Number(accountStats[0]?.auto_mapped || 0),
      },
      ledger: {
        sageTotal: Number(ledgerStats[0]?.total || 0), imported: Number(ledgerStats[0]?.imported || 0),
        pending: Number(ledgerStats[0]?.pending || 0), failed: Number(ledgerStats[0]?.failed || 0),
        dateRange: { earliest: ledgerStats[0]?.earliest || null, latest: ledgerStats[0]?.latest || null },
      },
      invoices: {
        sageTotal: Number(invoiceStats[0]?.total || 0), imported: Number(invoiceStats[0]?.imported || 0),
        pending: Number(invoiceStats[0]?.pending || 0), failed: Number(invoiceStats[0]?.failed || 0),
      },
      customerInvoices: {
        sageTotal: Number(customerInvoiceStats[0]?.total || 0),
        imported: Number(customerInvoiceStats[0]?.imported || 0),
        pending: Number(customerInvoiceStats[0]?.pending || 0),
        failed: Number(customerInvoiceStats[0]?.failed || 0),
      },
      lastRuns: runs.map((r: Row) => ({
        id: String(r.id), runType: String(r.run_type), status: String(r.status),
        totalRecords: Number(r.total_records), processed: Number(r.processed),
        succeeded: Number(r.succeeded), failed: Number(r.failed), skipped: Number(r.skipped),
        startedAt: String(r.started_at), completedAt: r.completed_at ? String(r.completed_at) : null,
      })),
    };
  } catch (err) {
    log.error('Failed to get migration status', { error: err }, 'accounting');
    throw err;
  }
}

// ── Account Mapping ─────────────────────────────────────────────────────────

export async function getAccountMappings(companyId: string): Promise<AccountMapping[]> {
  const rows = (await sql`
    SELECT sa.sage_account_id, sa.name, sa.account_type, sa.balance,
      sa.gl_account_id, sa.mapping_status, sa.mapping_notes,
      ga.account_code, ga.account_name
    FROM sage_accounts sa LEFT JOIN gl_accounts ga ON ga.id = sa.gl_account_id
    ORDER BY sa.name
  `) as Row[];

  return rows.map((r: Row) => ({
    sageAccountId: String(r.sage_account_id), sageName: String(r.name),
    sageType: r.account_type != null ? Number(r.account_type) : null,
    sageBalance: Number(r.balance || 0),
    glAccountId: r.gl_account_id ? String(r.gl_account_id) : null,
    glAccountCode: r.account_code ? String(r.account_code) : null,
    glAccountName: r.account_name ? String(r.account_name) : null,
    mappingStatus: String(r.mapping_status || 'unmapped'),
    mappingNotes: r.mapping_notes ? String(r.mapping_notes) : null,
  }));
}

function nameSimilarity(a: string, b: string): number {
  const tokensA = new Set(a.split(/[\s\-_&/]+/).filter(Boolean));
  const tokensB = new Set(b.split(/[\s\-_&/]+/).filter(Boolean));
  if (tokensA.size === 0 || tokensB.size === 0) return 0;
  let overlap = 0;
  for (const t of tokensA) {
    if (tokensB.has(t)) overlap++;
    else { for (const tb of tokensB) { if (tb.includes(t) || t.includes(tb)) { overlap += 0.5; break; } } }
  }
  return overlap / Math.max(tokensA.size, tokensB.size);
}

export async function autoMapAccounts(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('account_mapping', userId);
  try {
    const sageAccounts = (await sql`
      SELECT id, sage_account_id, name, account_type, balance FROM sage_accounts WHERE gl_account_id IS NULL ORDER BY name
    `) as Row[];
    const glAccounts = (await sql`
      SELECT id, account_code, account_name, account_type FROM gl_accounts WHERE level >= 3 AND is_active = true ORDER BY account_code
    `) as Row[];

    let succeeded = 0; let skipped = 0;
    const typeMap: Record<number, string> = { 1: 'revenue', 2: 'expense', 5: 'asset', 6: 'liability', 7: 'equity' };

    for (const sage of sageAccounts) {
      const sageName = String(sage.name).toLowerCase().trim();
      const sageType = sage.account_type != null ? typeMap[Number(sage.account_type)] : null;
      let bestMatch: Row | null = null; let bestScore = 0;

      for (const gl of glAccounts) {
        if (sageType && String(gl.account_type) !== sageType) continue;
        const score = nameSimilarity(sageName, String(gl.account_name).toLowerCase().trim());
        if (score > bestScore && score >= 0.6) { bestScore = score; bestMatch = gl; }
      }

      if (bestMatch) {
        await sql`
          UPDATE sage_accounts SET gl_account_id = ${bestMatch.id}::UUID, mapping_status = 'auto',
            mapping_notes = ${`Auto-mapped (${(bestScore * 100).toFixed(0)}% match) to ${bestMatch.account_code}`}
          WHERE id = ${sage.id}
        `;
        succeeded++;
      } else { skipped++; }
    }
    return await completeRun(runId, sageAccounts.length, succeeded, 0, skipped);
  } catch (err) { await failRun(runId, err); throw err; }
}

export async function mapAccount(companyId: string, sageAccountId: string, glAccountId: string | null, notes?: string): Promise<void> {
  if (glAccountId) {
    await sql`UPDATE sage_accounts SET gl_account_id = ${glAccountId}::UUID, mapping_status = 'manual',
      mapping_notes = ${notes || 'Manually mapped'} WHERE sage_account_id = ${sageAccountId}`;
  } else {
    await sql`UPDATE sage_accounts SET gl_account_id = NULL, mapping_status = 'unmapped',
      mapping_notes = ${notes || null} WHERE sage_account_id = ${sageAccountId}`;
  }
}

// ── Comparison ──────────────────────────────────────────────────────────────

export async function generateComparison(companyId: string, userId: string): Promise<ComparisonReport> {
  try {
    const sageBalances = (await sql`
      SELECT sa.sage_account_id, sa.name, sa.balance, ga.account_code, ga.account_name, ga.id AS gl_id
      FROM sage_accounts sa JOIN gl_accounts ga ON ga.id = sa.gl_account_id ORDER BY ga.account_code
    `) as Row[];

    const glBalances = (await sql`
      SELECT ga.id, ga.account_code, ga.account_name, ga.normal_balance,
        COALESCE(SUM(jl.debit), 0) AS total_debit, COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
      WHERE ga.level >= 3 GROUP BY ga.id, ga.account_code, ga.account_name, ga.normal_balance ORDER BY ga.account_code
    `) as Row[];

    const glMap = new Map<string, number>();
    let glTotalDebit = 0; let glTotalCredit = 0;
    for (const gl of glBalances) {
      const d = Number(gl.total_debit), c = Number(gl.total_credit);
      glMap.set(String(gl.id), String(gl.normal_balance) === 'debit' ? d - c : c - d);
      glTotalDebit += d; glTotalCredit += c;
    }

    const differences: ComparisonReport['differences'] = [];
    let sageTotalDebit = 0; let sageTotalCredit = 0;
    for (const sage of sageBalances) {
      const sb = Number(sage.balance || 0), gb = glMap.get(String(sage.gl_id)) || 0;
      if (sb > 0) sageTotalDebit += sb; else sageTotalCredit += Math.abs(sb);
      if (Math.abs(sb - gb) > 0.01) {
        differences.push({ accountCode: String(sage.account_code), accountName: String(sage.account_name), sageBalance: sb, glBalance: gb, difference: sb - gb });
      }
    }

    const report: ComparisonReport = {
      comparisonDate: new Date().toISOString().slice(0, 10),
      sageTotals: { totalDebit: sageTotalDebit, totalCredit: sageTotalCredit, accountCount: sageBalances.length },
      glTotals: { totalDebit: glTotalDebit, totalCredit: glTotalCredit, accountCount: glBalances.length },
      differences, isBalanced: differences.length === 0,
    };

    await sql`
      INSERT INTO gl_migration_comparisons (comparison_date, sage_totals, gl_totals, differences, is_balanced, created_by)
      VALUES (${report.comparisonDate}, ${JSON.stringify(report.sageTotals)}, ${JSON.stringify(report.glTotals)},
        ${JSON.stringify(report.differences)}, ${report.isBalanced}, ${userId})
    `;
    return report;
  } catch (err) { log.error('Failed to generate comparison', { error: err }, 'accounting'); throw err; }
}

// ── Reset ───────────────────────────────────────────────────────────────────

export async function resetMigration(companyId: string, 
  runType: 'accounts' | 'ledger' | 'invoices' | 'customer_invoices'
): Promise<void> {
  if (runType === 'accounts') {
    await sql`UPDATE sage_accounts SET gl_account_id = NULL, mapping_status = 'unmapped', mapping_notes = NULL`;
  } else if (runType === 'ledger') {
    await sql`UPDATE sage_ledger_transactions SET migration_status = 'pending', gl_journal_entry_id = NULL`;
  } else if (runType === 'invoices') {
    await sql`UPDATE sage_supplier_invoices SET migration_status = 'pending', gl_supplier_invoice_id = NULL`;
  } else if (runType === 'customer_invoices') {
    await sql`UPDATE sage_customer_invoices SET migration_status = 'pending', gl_customer_invoice_id = NULL`;
  }
}

/**
 * Smart Categorization Service
 * AI-powered bank transaction categorization using rules, patterns, and historical learning
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW';

export interface CategorizationInput {
  description: string;
  amount: number;
  reference?: string;
}

export interface CategorizationResult {
  glAccountId?: string;
  glAccountCode?: string;
  glAccountName?: string;
  category?: string;
  vatCode?: string;
  confidence: number;
  confidenceLevel: ConfidenceLevel;
  matchSource: 'rule' | 'pattern' | 'historical';
  matchDetail?: string;
}

export interface BulkCategorizationResult {
  categorized: number;
  skipped: number;
  results: Array<{
    transactionId: string;
    result: CategorizationResult | null;
  }>;
}

// ── Confidence helpers ───────────────────────────────────────────────────────

function toConfidenceLevel(score: number): ConfidenceLevel {
  if (score >= 0.85) return 'HIGH';
  if (score >= 0.60) return 'MEDIUM';
  return 'LOW';
}

// ── Core: Categorize a single transaction ────────────────────────────────────

export async function categorizeBankTransaction(companyId: string, 
  tx: CategorizationInput
): Promise<CategorizationResult | null> {
  const description = (tx.description || '').toUpperCase().trim();
  const reference = (tx.reference || '').toUpperCase().trim();

  if (!description && !reference) return null;

  // 1. Check existing bank_categorisation_rules (highest priority)
  const ruleMatch = await matchAgainstRules(description, reference);
  if (ruleMatch) return ruleMatch;

  // 2. Check categorization_patterns table (system + learned patterns)
  const patternMatch = await matchAgainstPatterns(description, reference);
  if (patternMatch) return patternMatch;

  // 3. Learn from historical allocations (similar past transactions)
  const historicalMatch = await matchFromHistory(description, tx.amount);
  if (historicalMatch) return historicalMatch;

  return null;
}

// ── Strategy 1: Match against bank_categorisation_rules ──────────────────────

async function matchAgainstRules(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const rules = (await sql`
      SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
      WHERE r.is_active = true
      ORDER BY r.priority ASC
    `) as Row[];

    for (const rule of rules) {
      const pattern = String(rule.match_pattern).toUpperCase();
      const matchType = String(rule.match_type);
      const matchField = String(rule.match_field);

      const targets: string[] = [];
      if (matchField === 'description' || matchField === 'both') targets.push(description);
      if (matchField === 'reference' || matchField === 'both') targets.push(reference);

      const matched = targets.some(target => {
        switch (matchType) {
          case 'contains': return target.includes(pattern);
          case 'starts_with': return target.startsWith(pattern);
          case 'ends_with': return target.endsWith(pattern);
          case 'exact': return target === pattern;
          default: return target.includes(pattern);
        }
      });

      if (matched) {
        return {
          glAccountId: rule.gl_account_id ? String(rule.gl_account_id) : undefined,
          glAccountCode: rule.gl_account_code ? String(rule.gl_account_code) : undefined,
          glAccountName: rule.gl_account_name ? String(rule.gl_account_name) : undefined,
          category: String(rule.rule_name),
          vatCode: String(rule.vat_code || 'none'),
          confidence: 0.95,
          confidenceLevel: 'HIGH',
          matchSource: 'rule',
          matchDetail: `Rule: ${rule.rule_name} (${matchType} "${rule.match_pattern}")`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: rule matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 2: Match against categorization_patterns ────────────────────────

async function matchAgainstPatterns(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const patterns = (await sql`
      SELECT cp.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM categorization_patterns cp
      LEFT JOIN gl_accounts ga ON ga.id = cp.gl_account_id
      ORDER BY cp.confidence DESC, cp.usage_count DESC
    `) as Row[];

    const combined = `${description} ${reference}`;

    for (const p of patterns) {
      const pat = String(p.pattern).toUpperCase();
      const matchType = String(p.match_type);

      let matched = false;
      switch (matchType) {
        case 'contains':
          matched = combined.includes(pat);
          break;
        case 'starts_with':
          matched = description.startsWith(pat) || reference.startsWith(pat);
          break;
        case 'regex':
          try {
            const re = new RegExp(p.pattern, 'i');
            matched = re.test(description) || re.test(reference);
          } catch {
            // WORKING: invalid regex patterns are safely skipped
            matched = false;
          }
          break;
        default:
          matched = combined.includes(pat);
      }

      if (matched) {
        const confidence = Number(p.confidence) || 0.80;

        // Update usage stats (fire-and-forget)
        sql`
          UPDATE categorization_patterns
          SET usage_count = usage_count + 1, last_used_at = NOW()
          WHERE id = ${p.id}::UUID
        `.catch(() => {});

        return {
          glAccountId: p.gl_account_id ? String(p.gl_account_id) : undefined,
          glAccountCode: p.gl_account_code ? String(p.gl_account_code) : undefined,
          glAccountName: p.gl_account_name ? String(p.gl_account_name) : undefined,
          category: p.category ? String(p.category) : undefined,
          vatCode: String(p.vat_code || 'standard'),
          confidence,
          confidenceLevel: toConfidenceLevel(confidence),
          matchSource: 'pattern',
          matchDetail: `Pattern: "${p.pattern}" (${p.source})`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: pattern matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 3: Learn from historical allocations ────────────────────────────

async function matchFromHistory(
  description: string,
  _amount: number
): Promise<CategorizationResult | null> {
  if (!description || description.length < 3) return null;

  try {
    // Extract significant words (3+ chars, skip common banking noise)
    const noiseWords = new Set([
      'THE', 'AND', 'FOR', 'FROM', 'WITH', 'PAYMENT', 'TRANSFER',
      'DEBIT', 'CREDIT', 'ORDER', 'REF', 'POS', 'PURCHASE', 'CARD',
    ]);
    const words = description
      .split(/[\s/\\,.-]+/)
      .filter(w => w.length >= 3 && !noiseWords.has(w) && !/^\d+$/.test(w));

    if (words.length === 0) return null;

    // Build search: look for allocated transactions with similar descriptions
    // Use the first 2-3 significant words for matching
    const searchWords = words.slice(0, 3);
    const likePattern = `%${searchWords.join('%')}%`;

    const historicalRows = (await sql`
      SELECT
        bt.suggested_gl_account_id,
        bt.suggested_category,
        bt.suggested_vat_code,
        bt.allocation_type,
        ga.account_code AS gl_account_code,
        ga.account_name AS gl_account_name,
        COUNT(*) AS match_count
      FROM bank_transactions bt
      LEFT JOIN gl_accounts ga ON ga.id = bt.suggested_gl_account_id
      WHERE bt.status IN ('matched', 'reconciled')
        AND bt.matched_journal_line_id IS NOT NULL
        AND bt.suggested_gl_account_id IS NOT NULL
        AND UPPER(bt.description) ILIKE ${likePattern}
      GROUP BY bt.suggested_gl_account_id, bt.suggested_category,
               bt.suggested_vat_code, bt.allocation_type,
               ga.account_code, ga.account_name
      ORDER BY match_count DESC
      LIMIT 1
    `) as Row[];

    if (historicalRows.length > 0) {
      const row = historicalRows[0];
      const matchCount = Number(row.match_count);
      // Scale confidence based on how many historical matches we found
      const baseConfidence = matchCount >= 5 ? 0.70 : matchCount >= 2 ? 0.55 : 0.40;

      return {
        glAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
        glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
        glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
        category: row.suggested_category ? String(row.suggested_category) : undefined,
        vatCode: String(row.suggested_vat_code || 'none'),
        confidence: baseConfidence,
        confidenceLevel: toConfidenceLevel(baseConfidence),
        matchSource: 'historical',
        matchDetail: `Historical: ${matchCount} similar transaction(s)`,
      };
    }
  } catch (err) {
    log.error('Smart categorization: historical matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Learn from user allocation ───────────────────────────────────────────────

export async function learnFromAllocation(companyId: string, 
  txId: string,
  glAccountId: string,
  category: string,
  vatCode?: string
): Promise<void> {
  try {
    // Get the transaction description
    const txRows = (await sql`
      SELECT description FROM bank_transactions WHERE id = ${txId}::UUID
    `) as Row[];

    if (txRows.length === 0) return;

    const description = String(txRows[0].description || '').trim();
    if (description.length < 3) return;

    // Extract a clean pattern from the description
    // Remove trailing numbers, dates, and references to get the merchant/payee name
    const pattern = extractLearningPattern(description);
    if (!pattern || pattern.length < 3) return;

    // Check if we already have this pattern
    const existing = (await sql`
      SELECT id, usage_count FROM categorization_patterns
      WHERE UPPER(pattern) = ${pattern.toUpperCase()}
        AND source = 'learned'
      LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      // Update existing pattern — increase confidence with use
      const newCount = Number(existing[0].usage_count) + 1;
      const newConfidence = Math.min(0.95, 0.60 + newCount * 0.05);
      await sql`
        UPDATE categorization_patterns
        SET gl_account_id = ${glAccountId}::UUID,
            category = ${category},
            vat_code = ${vatCode || 'standard'},
            usage_count = ${newCount},
            confidence = ${newConfidence},
            last_used_at = NOW()
        WHERE id = ${existing[0].id}::UUID
      `;
    } else {
      // Create new learned pattern
      await sql`
        INSERT INTO categorization_patterns (pattern, match_type, gl_account_id, category, vat_code, confidence, usage_count, last_used_at, source)
        VALUES (${pattern}, 'contains', ${glAccountId}::UUID, ${category}, ${vatCode || 'standard'}, 0.65, 1, NOW(), 'learned')
      `;
    }

    log.info('Learned categorization pattern', { pattern, category, glAccountId }, 'accounting');
  } catch (err) {
    log.error('Failed to learn from allocation', { txId, error: err }, 'accounting');
    // Non-critical: don't throw — learning failures should not break allocation flow
  }
}

/**
 * Extract a clean pattern from a bank transaction description.
 * Strips trailing reference numbers, dates, card numbers, etc.
 */
function extractLearningPattern(description: string): string {
  let clean = description.toUpperCase();

  // Remove common suffixes: card numbers, dates, reference numbers
  clean = clean.replace(/\b\d{4}\*+\d{4}\b/g, '');      // Card number masks
  clean = clean.replace(/\b\d{2}\/\d{2}\/\d{2,4}\b/g, ''); // Dates
  clean = clean.replace(/\b\d{6,}\b/g, '');               // Long number sequences
  clean = clean.replace(/\bREF\s*:?\s*\S+/gi, '');        // REF: xxx
  clean = clean.replace(/\bPOS\b/g, '');                   // POS prefix
  clean = clean.replace(/\bPURCHASE\b/g, '');              // PURCHASE label

  // Trim and collapse whitespace
  clean = clean.replace(/\s+/g, ' ').trim();

  // Take the first meaningful part (usually merchant name)
  const parts = clean.split(/\s{2,}/);
  return parts[0]?.trim() || clean;
}

// ── Bulk categorize ──────────────────────────────────────────────────────────

export async function bulkCategorize(companyId: string, 
  transactionIds: string[]
): Promise<BulkCategorizationResult> {
  if (transactionIds.length === 0) {
    return { categorized: 0, skipped: 0, results: [] };
  }

  // Fetch all requested transactions
  const txRows = (await sql`
    SELECT id, description, amount, reference
    FROM bank_transactions
    WHERE id = ANY(${transactionIds}::UUID[])
      AND status IN ('imported', 'allocated')
  `) as Row[];

  let categorized = 0;
  let skipped = 0;
  const results: BulkCategorizationResult['results'] = [];

  for (const tx of txRows) {
    const txId = String(tx.id);
    const input: CategorizationInput = {
      description: String(tx.description || ''),
      amount: Number(tx.amount),
      reference: tx.reference ? String(tx.reference) : undefined,
    };

    const result = await categorizeBankTransaction('', input);

    if (result) {
      // Write suggestion back to the transaction
      await sql`
        UPDATE bank_transactions SET
          suggested_gl_account_id = COALESCE(${result.glAccountId || null}::UUID, suggested_gl_account_id),
          suggested_category = COALESCE(${result.category || null}, suggested_category),
          suggested_vat_code = COALESCE(${result.vatCode || null}, suggested_vat_code),
          suggested_confidence = ${result.confidence}
        WHERE id = ${txId}::UUID
          AND suggested_gl_account_id IS NULL
      `;
      categorized++;
      results.push({ transactionId: txId, result });
    } else {
      skipped++;
      results.push({ transactionId: txId, result: null });
    }
  }

  log.info('Bulk smart categorization complete', { categorized, skipped, total: txRows.length }, 'accounting');

  return { categorized, skipped, results };
}

// ── Categorize all uncategorized transactions for a bank account ──────────────

export async function smartCategorizeForAccount(companyId: string, 
  bankAccountId: string
): Promise<BulkCategorizationResult> {
  // Get all uncategorized transactions for this bank account
  const txRows = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND status IN ('imported', 'allocated')
      AND suggested_gl_account_id IS NULL
      AND suggested_category IS NULL
    ORDER BY transaction_date DESC
    LIMIT 500
  `) as Row[];

  const ids = txRows.map((r: Row) => String(r.id));
  return bulkCategorize('', ids);
}

