/**
 * Phase 3: Transaction-Level Reporting Service
 * Customer, Supplier, Banking, Account, and Audit Trail reports
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccount } from './systemAccountResolver';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface TransactionRow {
  date: string;
  entryNumber: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
  source: string;
}

// ── Customer Report ─────────────────────────────────────────────────────────

export interface CustomerReportRow {
  clientId: string;
  clientName: string;
  invoiceCount: number;
  totalInvoiced: number;
  totalPaid: number;
  balance: number;
}

export async function getCustomerReport(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<CustomerReportRow[]> {
  try {
    const rows = (await sql`
      SELECT
        c.id AS client_id,
        c.name AS client_name,
        COUNT(DISTINCT ci.id) AS invoice_count,
        COALESCE(SUM(ci.total_amount), 0) AS total_invoiced,
        COALESCE(SUM(ci.amount_paid), 0) AS total_paid
      FROM customers c
      LEFT JOIN customer_invoices ci ON ci.client_id = c.id
        AND ci.invoice_date >= ${periodStart}
        AND ci.invoice_date <= ${periodEnd}
        AND ci.status NOT IN ('draft', 'cancelled')
      GROUP BY c.id, c.name
      HAVING COUNT(ci.id) > 0
      ORDER BY COALESCE(SUM(ci.total_amount), 0) DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceCount: Number(r.invoice_count),
      totalInvoiced: Number(r.total_invoiced),
      totalPaid: Number(r.total_paid),
      balance: Number(r.total_invoiced) - Number(r.total_paid),
    }));
  } catch (err) {
    log.error('Failed to generate customer report', { error: err }, 'accounting');
    throw err;
  }
}

// ── Supplier Report ─────────────────────────────────────────────────────────

export interface SupplierReportRow {
  supplierId: string;
  supplierName: string;
  invoiceCount: number;
  totalInvoiced: number;
  totalPaid: number;
  balance: number;
}

export async function getSupplierReport(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<SupplierReportRow[]> {
  try {
    const rows = (await sql`
      SELECT
        s.id AS supplier_id,
        COALESCE(s.company_name, s.name) AS supplier_name,
        COUNT(DISTINCT si.id) AS invoice_count,
        COALESCE(SUM(si.total_amount), 0) AS total_invoiced,
        COALESCE(SUM(si.amount_paid), 0) AS total_paid
      FROM suppliers s
      LEFT JOIN supplier_invoices si ON si.supplier_id = s.id
        AND si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status NOT IN ('draft', 'cancelled')
      GROUP BY s.id, s.company_name, s.name
      HAVING COUNT(si.id) > 0
      ORDER BY COALESCE(SUM(si.total_amount), 0) DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      supplierId: String(r.supplier_id),
      supplierName: String(r.supplier_name),
      invoiceCount: Number(r.invoice_count),
      totalInvoiced: Number(r.total_invoiced),
      totalPaid: Number(r.total_paid),
      balance: Number(r.total_invoiced) - Number(r.total_paid),
    }));
  } catch (err) {
    log.error('Failed to generate supplier report', { error: err }, 'accounting');
    throw err;
  }
}

// ── Bank Transactions ───────────────────────────────────────────────────────

export interface BankTransactionRow {
  date: string;
  entryNumber: string;
  description: string;
  deposit: number;
  withdrawal: number;
  runningBalance: number;
}

export interface BankTransactionsReport {
  accountCode: string;
  accountName: string;
  periodStart: string;
  periodEnd: string;
  openingBalance: number;
  closingBalance: number;
  transactions: BankTransactionRow[];
}

export async function getBankTransactions(companyId: string, 
  periodStart: string,
  periodEnd: string,
  accountCode?: string
): Promise<BankTransactionsReport> {
  try {
    const bankCode = accountCode || (await getSystemAccount('bank')).accountCode;

    // Opening balance (all posted entries before period start)
    const obRows = (await sql`
      SELECT
        COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS balance
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date < ${periodStart}
        AND ga.account_code = ${bankCode}
    `) as Row[];
    const openingBalance = Number(obRows[0]?.balance || 0);

    // Transactions in period
    const txnRows = (await sql`
      SELECT
        je.entry_date, je.entry_number, je.description, je.source,
        jl.debit, jl.credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND ga.account_code = ${bankCode}
      ORDER BY je.entry_date, je.created_at
    `) as Row[];

    // Get account name
    const acctRows = (await sql`
      SELECT account_name FROM gl_accounts WHERE account_code = ${bankCode} LIMIT 1
    `) as Row[];

    let running = openingBalance;
    const transactions: BankTransactionRow[] = txnRows.map((r: Row) => {
      const dep = Number(r.debit || 0);
      const wd = Number(r.credit || 0);
      running += dep - wd;
      return {
        date: String(r.entry_date).split('T')[0] ?? '',
        entryNumber: String(r.entry_number),
        description: String(r.description || ''),
        deposit: dep,
        withdrawal: wd,
        runningBalance: running,
      };
    });

    return {
      accountCode: bankCode,
      accountName: String(acctRows[0]?.account_name || 'Bank'),
      periodStart,
      periodEnd,
      openingBalance,
      closingBalance: running,
      transactions,
    };
  } catch (err) {
    log.error('Failed to generate bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Account Transactions ────────────────────────────────────────────────────

export interface AccountTransactionsReport {
  accountCode: string;
  accountName: string;
  accountType: string;
  periodStart: string;
  periodEnd: string;
  openingBalance: number;
  closingBalance: number;
  transactions: TransactionRow[];
}

export async function getAccountTransactions(
  companyId: string,
  accountCode: string,
  periodStart: string,
  periodEnd: string
): Promise<AccountTransactionsReport> {
  try {
    const acctRows = (await sql`
      SELECT account_name, account_type, normal_balance
      FROM gl_accounts WHERE account_code = ${accountCode} LIMIT 1
    `) as Row[];
    if (!acctRows[0]) throw new Error(`Account ${accountCode} not found`);

    const normalBal = String(acctRows[0].normal_balance);

    // Opening balance
    const obRows = (await sql`
      SELECT
        COALESCE(SUM(jl.debit), 0) AS total_debit,
        COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date < ${periodStart}
        AND ga.account_code = ${accountCode}
    `) as Row[];

    const obDebit = Number(obRows[0]?.total_debit || 0);
    const obCredit = Number(obRows[0]?.total_credit || 0);
    const openingBalance = normalBal === 'debit' ? obDebit - obCredit : obCredit - obDebit;

    // Transactions
    const txnRows = (await sql`
      SELECT
        je.entry_date, je.entry_number, je.description, je.source,
        jl.debit, jl.credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND ga.account_code = ${accountCode}
      ORDER BY je.entry_date, je.created_at
    `) as Row[];

    let running = openingBalance;
    const transactions: TransactionRow[] = txnRows.map((r: Row) => {
      const d = Number(r.debit || 0);
      const c = Number(r.credit || 0);
      running += normalBal === 'debit' ? d - c : c - d;
      const rawDate = r.entry_date instanceof Date
        ? r.entry_date.toISOString().split('T')[0]
        : String(r.entry_date || '').split('T')[0];
      return {
        date: rawDate,
        entryNumber: String(r.entry_number),
        description: String(r.description || ''),
        debit: d,
        credit: c,
        balance: running,
        source: String(r.source || 'manual'),
      };
    });

    return {
      accountCode,
      accountName: String(acctRows[0].account_name),
      accountType: String(acctRows[0].account_type),
      periodStart,
      periodEnd,
      openingBalance,
      closingBalance: running,
      transactions,
    };
  } catch (err) {
    log.error('Failed to generate account transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Audit Trail ─────────────────────────────────────────────────────────────

export interface AuditTrailRow {
  entryDate: string;
  entryNumber: string;
  description: string;
  source: string;
  status: string;
  totalDebit: number;
  totalCredit: number;
  createdBy: string;
  createdAt: string;
  postedAt: string | null;
}

export async function getAuditTrail(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<AuditTrailRow[]> {
  try {
    const rows = (await sql`
      SELECT
        je.entry_date, je.entry_number, je.description, je.source, je.status,
        COALESCE(SUM(jl.debit), 0) AS total_debit,
        COALESCE(SUM(jl.credit), 0) AS total_credit,
        COALESCE(CONCAT_WS(' ', u.first_name, u.last_name), je.created_by::TEXT) AS created_by_name,
        je.created_at, je.posted_at
      FROM gl_journal_entries je
      LEFT JOIN gl_journal_lines jl ON jl.journal_entry_id = je.id
      LEFT JOIN users u ON u.id::TEXT = je.created_by::TEXT
      WHERE je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
      GROUP BY je.id, je.entry_date, je.entry_number, je.description,
        je.source, je.status, u.first_name, u.last_name, je.created_by, je.created_at, je.posted_at
      ORDER BY je.created_at DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      entryDate: r.entry_date instanceof Date
        ? r.entry_date.toISOString().split('T')[0]!
        : String(r.entry_date || '').split('T')[0]!,
      entryNumber: String(r.entry_number),
      description: String(r.description || ''),
      source: String(r.source || 'manual'),
      status: String(r.status),
      totalDebit: Number(r.total_debit || 0),
      totalCredit: Number(r.total_credit || 0),
      createdBy: String(r.created_by_name || '—'),
      createdAt: String(r.created_at),
      postedAt: r.posted_at ? String(r.posted_at) : null,
    }));
  } catch (err) {
    log.error('Failed to generate audit trail', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * VAT Adjustment Service
 * Phase 1 Sage Alignment: Manual VAT corrections with GL posting
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type { VATAdjustment, VATAdjustmentCreateInput } from '../types/gl.types';
import type { JournalLineInput } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export async function getVATAdjustments(companyId: string, filters?: {
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: VATAdjustment[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.status) {
    rows = (await sql`
      SELECT * FROM vat_adjustments
      WHERE company_id = ${companyId} AND status = ${filters.status}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM vat_adjustments
      WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT * FROM vat_adjustments WHERE company_id = ${companyId}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM vat_adjustments WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createVATAdjustment(companyId: string, 
  input: VATAdjustmentCreateInput,
  userId: string
): Promise<VATAdjustment> {
  const rows = (await sql`
    INSERT INTO vat_adjustments (
      company_id, adjustment_date, vat_period, adjustment_type, amount, reason, created_by
    ) VALUES (
      ${companyId}, ${input.adjustmentDate}, ${input.vatPeriod || null},
      ${input.adjustmentType}, ${input.amount}, ${input.reason}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created VAT adjustment', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function approveVATAdjustment(companyId: string, 
  id: string,
  userId: string
): Promise<VATAdjustment> {
  const vaRows = (await sql`SELECT * FROM vat_adjustments WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!vaRows[0]) throw new Error('VAT adjustment not found');
  if (vaRows[0].status !== 'draft') throw new Error('VAT adjustment is not in draft status');

  const va = vaRows[0];
  const amount = Number(va.amount);
  const isInput = va.adjustment_type === 'input';

  // GL: Input → DR VAT Input, CR Expense
  //     Output → DR Expense, CR VAT Output
  const vatAccount = isInput
    ? await getSystemAccount('vat_input')
    : await getSystemAccount('vat_output');
  const expenseAccount = await getSystemAccount('admin_expense');

  const lines: JournalLineInput[] = isInput
    ? [
        { glAccountId: vatAccount.id, debit: amount, credit: 0,
          description: `VAT input adjustment ${va.adjustment_number}` },
        { glAccountId: expenseAccount.id, debit: 0, credit: amount,
          description: `VAT input adjustment ${va.adjustment_number}` },
      ]
    : [
        { glAccountId: expenseAccount.id, debit: amount, credit: 0,
          description: `VAT output adjustment ${va.adjustment_number}` },
        { glAccountId: vatAccount.id, debit: 0, credit: amount,
          description: `VAT output adjustment ${va.adjustment_number}` },
      ];

  const je = await createJournalEntry('', {
    entryDate: String(va.adjustment_date),
    description: `VAT adjustment ${va.adjustment_number}`,
    source: 'auto_vat_adjustment',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry('', je.id, userId);

  const updated = (await sql`
    UPDATE vat_adjustments
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved VAT adjustment', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelVATAdjustment(companyId: string, id: string): Promise<void> {
  await sql`UPDATE vat_adjustments SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
}

function mapRow(row: Row): VATAdjustment {
  return {
    id: String(row.id),
    adjustmentNumber: row.adjustment_number ? String(row.adjustment_number) : '',
    adjustmentDate: String(row.adjustment_date),
    vatPeriod: row.vat_period ? String(row.vat_period) : undefined,
    adjustmentType: String(row.adjustment_type) as VATAdjustment['adjustmentType'],
    amount: Number(row.amount),
    reason: String(row.reason),
    status: String(row.status) as VATAdjustment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Webhook Service — WS-8.1
 * Fire-and-forget HMAC-signed webhook delivery with delivery logging.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { WEBHOOK_EVENTS } from '@/modules/accounting/constants/webhookEvents';

export { WEBHOOK_EVENTS };
export type { WebhookEvent } from '@/modules/accounting/constants/webhookEvents';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface Webhook {
  id: string;
  companyId: string;
  name: string;
  url: string;
  secret: string | null;
  events: string[];
  isActive: boolean;
  lastTriggeredAt: string | null;
  failureCount: number;
  createdAt: string;
}

export interface WebhookInput {
  name: string;
  url: string;
  secret?: string | null;
  events: string[];
  isActive?: boolean;
}

export interface Delivery {
  id: string;
  webhookId: string;
  event: string;
  payload: Record<string, unknown>;
  responseStatus: number | null;
  responseBody: string | null;
  deliveredAt: string;
  success: boolean;
}

function mapWebhook(row: Row): Webhook {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    name: String(row.name),
    url: String(row.url),
    secret: row.secret ? String(row.secret) : null,
    events: Array.isArray(row.events) ? row.events : [],
    isActive: Boolean(row.is_active),
    lastTriggeredAt: row.last_triggered_at ? String(row.last_triggered_at) : null,
    failureCount: Number(row.failure_count),
    createdAt: String(row.created_at),
  };
}

function mapDelivery(row: Row): Delivery {
  return {
    id: String(row.id),
    webhookId: String(row.webhook_id),
    event: String(row.event),
    payload: typeof row.payload === 'object' ? row.payload : JSON.parse(row.payload || '{}'),
    responseStatus: row.response_status != null ? Number(row.response_status) : null,
    responseBody: row.response_body ? String(row.response_body) : null,
    deliveredAt: String(row.delivered_at),
    success: Boolean(row.success),
  };
}

function signPayload(secret: string, body: string): string {
  return crypto.createHmac('sha256', secret).update(body).digest('hex');
}

/** Fire webhook for an event — non-blocking, never throws to caller. */
export async function fireWebhook(
  companyId: string,
  event: string,
  payload: Record<string, unknown>,
): Promise<void> {
  // Intentionally fire-and-forget — wrap everything in try/catch
  void (async () => {
    try {
      const rows = (await sql`
        SELECT * FROM webhook_endpoints
        WHERE company_id = ${companyId}
          AND is_active = true
          AND ${event} = ANY(events)
      `) as Row[];

      for (const row of rows) {
        const endpoint = mapWebhook(row);
        const body = JSON.stringify(payload);
        const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

        let responseStatus: number | null = null;
        let responseBody: string | null = null;
        let success = false;

        try {
          const controller = new AbortController();
          const timeout = setTimeout(() => controller.abort(), 5000);
          const resp = await fetch(endpoint.url, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'X-Webhook-Event': event,
              ...(signature ? { 'X-Webhook-Signature': signature } : {}),
            },
            body,
            signal: controller.signal,
          });
          clearTimeout(timeout);
          responseStatus = resp.status;
          responseBody = await resp.text().catch(() => null);
          success = resp.ok;
        } catch (fetchErr) {
          log.warn('Webhook delivery failed', { endpointId: endpoint.id, error: fetchErr }, 'webhook');
        }

        // Record delivery
        await sql`
          INSERT INTO webhook_deliveries (webhook_id, event, payload, response_status, response_body, success)
          VALUES (${endpoint.id}::UUID, ${event}, ${JSON.stringify(payload)}::JSONB,
                  ${responseStatus}, ${responseBody}, ${success})
        `;

        if (success) {
          await sql`
            UPDATE webhook_endpoints
            SET last_triggered_at = NOW(), failure_count = 0
            WHERE id = ${endpoint.id}::UUID
          `;
        } else {
          await sql`
            UPDATE webhook_endpoints
            SET failure_count = failure_count + 1,
                is_active = CASE WHEN failure_count + 1 >= 10 THEN false ELSE is_active END
            WHERE id = ${endpoint.id}::UUID
          `;
        }
      }
    } catch (err) {
      log.error('fireWebhook error', { companyId, event, error: err }, 'webhook');
    }
  })();
}

export async function getWebhooks(companyId: string): Promise<Webhook[]> {
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE company_id = ${companyId} ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapWebhook);
}

export async function createWebhook(companyId: string, input: WebhookInput): Promise<Webhook> {
  const rows = (await sql`
    INSERT INTO webhook_endpoints (company_id, name, url, secret, events, is_active)
    VALUES (${companyId}, ${input.name}, ${input.url}, ${input.secret ?? null},
            ${JSON.stringify(input.events)}::TEXT[], ${input.isActive ?? true})
    RETURNING *
  `) as Row[];
  log.info('Webhook created', { id: rows[0]?.id }, 'webhook');
  return mapWebhook(rows[0]!);
}

export async function updateWebhook(
  companyId: string,
  id: string,
  updates: Partial<WebhookInput>,
): Promise<Webhook> {
  // Build individual field updates to avoid array casting complexity
  if (updates.name !== undefined) {
    await sql`UPDATE webhook_endpoints SET name = ${updates.name} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.url !== undefined) {
    await sql`UPDATE webhook_endpoints SET url = ${updates.url} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.secret !== undefined) {
    await sql`UPDATE webhook_endpoints SET secret = ${updates.secret ?? null} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.events !== undefined) {
    await sql`UPDATE webhook_endpoints SET events = ${updates.events}::TEXT[] WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  if (updates.isActive !== undefined) {
    await sql`UPDATE webhook_endpoints SET is_active = ${updates.isActive} WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  }
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!rows[0]) throw new Error('Webhook not found');
  log.info('Webhook updated', { id }, 'webhook');
  return mapWebhook(rows[0]!);
}

export async function deleteWebhook(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}`;
  log.info('Webhook deleted', { id }, 'webhook');
}

export async function getDeliveries(
  companyId: string,
  webhookId: string,
  limit = 50,
): Promise<Delivery[]> {
  // Verify ownership
  const rows = (await sql`
    SELECT wd.* FROM webhook_deliveries wd
    JOIN webhook_endpoints we ON we.id = wd.webhook_id
    WHERE wd.webhook_id = ${webhookId}::UUID AND we.company_id = ${companyId}
    ORDER BY wd.delivered_at DESC
    LIMIT ${limit}
  `) as Row[];
  return rows.map(mapDelivery);
}

export async function testWebhook(
  companyId: string,
  id: string,
): Promise<{ success: boolean; status: number; body: string }> {
  const rows = (await sql`
    SELECT * FROM webhook_endpoints WHERE id = ${id}::UUID AND company_id = ${companyId}
  `) as Row[];
  if (!rows[0]) throw new Error('Webhook not found');
  const endpoint = mapWebhook(rows[0]!);

  const payload = { test: true, event: 'webhook.test', timestamp: new Date().toISOString() };
  const body = JSON.stringify(payload);
  const signature = endpoint.secret ? signPayload(endpoint.secret, body) : '';

  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 5000);
    const resp = await fetch(endpoint.url, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Webhook-Event': 'webhook.test',
        ...(signature ? { 'X-Webhook-Signature': signature } : {}),
      },
      body,
      signal: controller.signal,
    });
    clearTimeout(timeout);
    const respBody = await resp.text().catch(() => '');
    log.info('Webhook test sent', { id, status: resp.status }, 'webhook');
    return { success: resp.ok, status: resp.status, body: respBody };
  } catch (err) {
    log.warn('Webhook test failed', { id, error: err }, 'webhook');
    return { success: false, status: 0, body: err instanceof Error ? err.message : 'Request failed' };
  }
}

