/**
 * Admin Analytics Service
 * Platform health, usage analytics, and settings for ISAFlow Admin Platform.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { PlatformHealth, UsageAnalytics, PlatformSettings } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toISOString(value: unknown): string | null {
  if (!value) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

export async function getPlatformHealth(): Promise<PlatformHealth> {
  const [activeUsers, apiCalls, dbSize, topCompanies] = await Promise.all([
    getActiveUserCounts(),
    getApiCallCount(),
    getDbSizeMb(),
    getTopCompaniesBySize(),
  ]);

  const health: PlatformHealth = {
    active_users_24h: activeUsers.h24,
    active_users_7d: activeUsers.d7,
    active_users_30d: activeUsers.d30,
    total_api_calls_24h: apiCalls.total,
    error_count_24h: apiCalls.errors,
    error_rate_percent: apiCalls.total > 0
      ? Math.round((apiCalls.errors / apiCalls.total) * 10000) / 100
      : 0,
    db_size_mb: dbSize,
    top_companies_by_size: topCompanies,
  };

  log.info('Platform health fetched', {
    active_users_24h: health.active_users_24h,
    db_size_mb: health.db_size_mb,
  }, 'analyticsService');

  return health;
}

async function getActiveUserCounts(): Promise<{ h24: number; d7: number; d30: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '24 hours') AS h24,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')   AS d7,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days')  AS d30
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    h24: parseInt(row.h24 as string, 10) || 0,
    d7: parseInt(row.d7 as string, 10) || 0,
    d30: parseInt(row.d30 as string, 10) || 0,
  };
}

async function getApiCallCount(): Promise<{ total: number; errors: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE action ILIKE 'error%') AS errors
    FROM admin_audit_log
    WHERE created_at >= NOW() - INTERVAL '24 hours'
  `;
  const row = rows[0] as Row;
  return {
    total: parseInt(row.total as string, 10) || 0,
    errors: parseInt(row.errors as string, 10) || 0,
  };
}

async function getDbSizeMb(): Promise<number> {
  const rows = await sql`
    SELECT ROUND(pg_database_size(current_database()) / 1048576.0, 2) AS size_mb
  `;
  const val = (rows[0] as Row).size_mb;
  return parseFloat(val as string) || 0;
}

async function getTopCompaniesBySize(): Promise<PlatformHealth['top_companies_by_size']> {
  // Proxy company "size" by counting rows in major tables grouped by company_id
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name AS company_name,
      (
        COALESCE((SELECT COUNT(*) FROM gl_journal_entries je WHERE je.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM customer_invoices ci WHERE COALESCE(ci.client_id, ci.customer_id) IS NOT NULL AND ci.company_id = c.id), 0)
        + COALESCE((SELECT COUNT(*) FROM bank_transactions bt WHERE bt.company_id = c.id), 0)
      )::float / 1000.0 AS size_mb
    FROM companies c
    WHERE c.status IS DISTINCT FROM 'deleted'
    ORDER BY size_mb DESC
    LIMIT 10
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    size_mb: parseFloat(row.size_mb as string) || 0,
  }));
}

export async function getUsageAnalytics(): Promise<UsageAnalytics> {
  const [engagement, featureAdoption, revenueByPlan, churnSignals] = await Promise.all([
    getEngagementCounts(),
    getFeatureAdoption(),
    getRevenueByPlan(),
    getChurnSignals(),
  ]);

  const stickiness = engagement.mau > 0
    ? Math.round((engagement.dau / engagement.mau) * 10000) / 100
    : 0;

  const analytics: UsageAnalytics = {
    dau: engagement.dau,
    wau: engagement.wau,
    mau: engagement.mau,
    stickiness_percent: stickiness,
    // top_pages requires a page_views tracking table — not yet implemented
    top_pages: [],
    feature_adoption: featureAdoption,
    revenue_by_plan: revenueByPlan,
    churn_signals: churnSignals,
  };

  log.info('Usage analytics fetched', {
    dau: analytics.dau,
    mau: analytics.mau,
    churn_signals: analytics.churn_signals.length,
  }, 'analyticsService');

  return analytics;
}

async function getEngagementCounts(): Promise<{ dau: number; wau: number; mau: number }> {
  const rows = await sql`
    SELECT
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '1 day')   AS dau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '7 days')  AS wau,
      COUNT(*) FILTER (WHERE last_login >= NOW() - INTERVAL '30 days') AS mau
    FROM users
    WHERE is_active = true
  `;
  const row = rows[0] as Row;
  return {
    dau: parseInt(row.dau as string, 10) || 0,
    wau: parseInt(row.wau as string, 10) || 0,
    mau: parseInt(row.mau as string, 10) || 0,
  };
}

async function getFeatureAdoption(): Promise<UsageAnalytics['feature_adoption']> {
  const totalRow = await sql`SELECT COUNT(*) AS total FROM companies WHERE status IS DISTINCT FROM 'deleted'`;
  const total = parseInt((totalRow[0] as Row).total as string, 10) || 1;

  const rows = await sql`
    SELECT
      ff.name AS feature,
      COUNT(DISTINCT cfo.company_id) AS user_count
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo ON cfo.feature_id = ff.id AND cfo.enabled = true
    GROUP BY ff.id, ff.name
    ORDER BY user_count DESC
  `;

  return (rows as Row[]).map((row) => ({
    feature: row.feature as string,
    user_count: parseInt(row.user_count as string, 10) || 0,
    adoption_percent: Math.round(((parseInt(row.user_count as string, 10) || 0) / total) * 10000) / 100,
  }));
}

async function getRevenueByPlan(): Promise<UsageAnalytics['revenue_by_plan']> {
  const rows = await sql`
    SELECT
      p.name AS plan_name,
      COUNT(s.id) AS company_count,
      COALESCE(SUM(
        CASE
          WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
          ELSE 0
        END
      ), 0) AS mrr_cents
    FROM plans p
    LEFT JOIN subscriptions s ON s.plan_id = p.id AND s.status IN ('active', 'trial')
    GROUP BY p.id, p.name
    ORDER BY mrr_cents DESC
  `;
  return (rows as Row[]).map((row) => ({
    plan_name: row.plan_name as string,
    mrr_cents: parseInt(row.mrr_cents as string, 10) || 0,
    company_count: parseInt(row.company_count as string, 10) || 0,
  }));
}

async function getChurnSignals(): Promise<UsageAnalytics['churn_signals']> {
  const rows = await sql`
    SELECT
      c.id::text AS company_id,
      c.name     AS company_name,
      EXTRACT(DAY FROM NOW() - MAX(u.last_login))::int AS days_inactive,
      MAX(u.last_login) AS last_login
    FROM companies c
    INNER JOIN company_users cu ON cu.company_id = c.id
    INNER JOIN users u ON u.id = cu.user_id AND u.is_active = true
    WHERE c.status IS DISTINCT FROM 'deleted'
    GROUP BY c.id, c.name
    HAVING MAX(u.last_login) < NOW() - INTERVAL '14 days'
        OR MAX(u.last_login) IS NULL
    ORDER BY days_inactive DESC NULLS LAST
    LIMIT 20
  `;
  return (rows as Row[]).map((row) => ({
    company_id: row.company_id as string,
    company_name: row.company_name as string,
    days_inactive: parseInt(row.days_inactive as string, 10) || 0,
    last_login: toISOString(row.last_login),
  }));
}

export async function getPlatformSettings(): Promise<PlatformSettings> {
  // MVP: sensible defaults — persistence table not yet implemented
  return {
    maintenance_mode: false,
    registration_enabled: true,
    default_trial_days: 14,
    max_companies_per_user: 5,
    smtp_configured: !!(process.env.SMTP_HOST ?? process.env.RESEND_API_KEY),
  };
}

export async function updatePlatformSettings(data: Partial<PlatformSettings>): Promise<void> {
  // MVP: no persistence table yet — log the intent only
  log.info('Platform settings update requested (no persistence yet)', {
    changes: data,
  }, 'analyticsService');
}

// ── Public API ────────────────────────────────────────────────────────────────

export async function detectDuplicates(
  companyId: string,
  entityType: 'customer' | 'supplier' | 'item',
): Promise<DuplicatePair[]> {
  log.info('Detecting duplicates', { companyId, entityType }, 'duplicate-detection');

  if (entityType === 'customer') return detectCustomerDuplicates(companyId);
  if (entityType === 'supplier') return detectSupplierDuplicates(companyId);
  return detectItemDuplicates(companyId);
}

// ── Customer detection ────────────────────────────────────────────────────────

async function detectCustomerDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, name, email, vat_number, phone, registration_number, contact_person, billing_address
    FROM customers
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY name
  `) as Row[];

  const entities: DuplicateEntity[] = rows.map((r: Row) => ({
    id: r.id,
    name: r.name,
    email: r.email,
    vatNumber: r.vat_number,
    phone: r.phone,
    registrationNumber: r.registration_number,
    contactPerson: r.contact_person,
    billingAddress: r.billing_address,
  }));

  const pairs = findDuplicatePairs(entities, 'customer', 0.85);
  log.info('Customer duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Supplier detection ────────────────────────────────────────────────────────

async function detectSupplierDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, name, email, vat_number, phone, registration_number, contact_person, address
    FROM suppliers
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY name
  `) as Row[];

  const entities: DuplicateEntity[] = rows.map((r: Row) => ({
    id: r.id,
    name: r.name,
    email: r.email,
    vatNumber: r.vat_number,
    phone: r.phone,
    registrationNumber: r.registration_number,
    contactPerson: r.contact_person,
    address: r.address,
  }));

  const pairs = findDuplicatePairs(entities, 'supplier', 0.85);
  log.info('Supplier duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Item detection ────────────────────────────────────────────────────────────

async function detectItemDuplicates(companyId: string): Promise<DuplicatePair[]> {
  const rows = (await sql`
    SELECT id, code, description, item_type, unit, cost_price, selling_price_excl
    FROM items
    WHERE company_id = ${companyId}::UUID
      AND deleted_at IS NULL
      AND is_active = true
    ORDER BY code
  `) as Row[];

  const pairs: DuplicatePair[] = [];
  const seen = new Set<string>();

  for (let i = 0; i < rows.length; i++) {
    for (let j = i + 1; j < rows.length; j++) {
      const a = rows[i] as Row;
      const b = rows[j] as Row;
      const pairKey = [a.id as string, b.id as string].sort().join(':');
      if (seen.has(pairKey)) continue;

      const reasons: string[] = [];
      let confidence = 0;

      if (a.code && b.code && (a.code as string).toLowerCase() === (b.code as string).toLowerCase()) {
        reasons.push(`Same item code: ${a.code as string}`);
        confidence = 100;
      } else {
        const nameResult = fuzzyMatch(a.description as string, [b.description as string], 0.90);
        if (nameResult) {
          const pct = Math.round(nameResult.score * 100);
          reasons.push(`Name ${pct}% match`);
          confidence = Math.max(confidence, pct);
        }
      }

      if (reasons.length > 0) {
        seen.add(pairKey);
        pairs.push({
          entityType: 'item',
          primary: { id: a.id as string, name: a.description as string, itemCode: a.code, itemType: a.item_type, unit: a.unit, costPrice: a.cost_price },
          duplicate: { id: b.id as string, name: b.description as string, itemCode: b.code, itemType: b.item_type, unit: b.unit, costPrice: b.cost_price },
          confidence,
          matchReasons: reasons,
        });
      }
    }
  }

  log.info('Item duplicate scan complete', { count: pairs.length, companyId }, 'duplicate-detection');
  return pairs;
}

// ── Generic pair-finding ──────────────────────────────────────────────────────

function findDuplicatePairs(
  entities: DuplicateEntity[],
  entityType: 'customer' | 'supplier',
  nameThreshold: number,
): DuplicatePair[] {
  const pairs: DuplicatePair[] = [];
  const seen = new Set<string>();

  // For >500 entities, bucket by first 3 chars to reduce O(n²) comparisons
  const useBucketing = entities.length > 500;
  const compareGroups: DuplicateEntity[][] = useBucketing
    ? buildBuckets(entities)
    : [entities];

  for (const group of compareGroups) {
    for (let i = 0; i < group.length; i++) {
      for (let j = i + 1; j < group.length; j++) {
        const a = group[i]!;
        const b = group[j]!;
        const pairKey = [a.id, b.id].sort().join(':');
        if (seen.has(pairKey)) continue;

        const { reasons, confidence } = scorePair(a, b, nameThreshold);
        if (reasons.length > 0) {
          seen.add(pairKey);
          pairs.push({ entityType, primary: a, duplicate: b, confidence: Math.min(confidence, 100), matchReasons: reasons });
        }
      }
    }
  }

  pairs.sort((a, b) => b.confidence - a.confidence);
  return pairs;
}

function buildBuckets(entities: DuplicateEntity[]): DuplicateEntity[][] {
  const map = new Map<string, DuplicateEntity[]>();
  for (const e of entities) {
    const key = e.name.toLowerCase().slice(0, 3);
    if (!map.has(key)) map.set(key, []);
    map.get(key)!.push(e);
  }
  return Array.from(map.values());
}

function scorePair(a: DuplicateEntity, b: DuplicateEntity, nameThreshold: number): { reasons: string[]; confidence: number } {
  const reasons: string[] = [];
  let confidence = 0;

  if (a.vatNumber && b.vatNumber && a.vatNumber === b.vatNumber) {
    reasons.push(`Same VAT number: ${a.vatNumber}`);
    confidence = Math.max(confidence, 95);
  }

  if (a.email && b.email && a.email.toLowerCase() === b.email.toLowerCase()) {
    reasons.push(`Same email: ${a.email}`);
    confidence = Math.max(confidence, 90);
  }

  const nameResult = fuzzyMatch(a.name, [b.name], nameThreshold);
  if (nameResult) {
    const pct = Math.round(nameResult.score * 100);
    reasons.push(`Name ${pct}% match`);
    confidence = Math.max(confidence, pct);
  }

  return { reasons, confidence };
}

/**
 * Announcement Service
 * CRUD for system_announcements table — admin-managed platform messages.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { Announcement, PaginatedResult } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(v: unknown): string | null {
  if (v == null) return null;
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

function rowToAnnouncement(r: Row): Announcement {
  return {
    id: r.id as string,
    title: r.title as string,
    message: r.message as string,
    type: r.type as string,
    target: r.target as string,
    target_ids: (r.target_ids ?? []) as string[],
    starts_at: toIso(r.starts_at) as string,
    ends_at: toIso(r.ends_at),
    is_dismissible: r.is_dismissible as boolean,
    created_by: r.created_by as string,
    created_at: toIso(r.created_at) as string,
  };
}

interface ListFilters {
  active_only?: boolean;
  page?: number;
  limit?: number;
}

export async function listAnnouncements(
  filters: ListFilters = {}
): Promise<PaginatedResult<Announcement>> {
  const page  = Math.max(1, filters.page  ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;

  try {
    const rows = await sql`
      SELECT *
      FROM system_announcements
      WHERE (
        ${filters.active_only
          ? sql`starts_at <= NOW() AND (ends_at IS NULL OR ends_at >= NOW())`
          : sql`TRUE`}
      )
      ORDER BY created_at DESC
      LIMIT ${limit} OFFSET ${offset}
    `;

    const [countRow] = await sql`
      SELECT COUNT(*)::int AS total
      FROM system_announcements
      WHERE (
        ${filters.active_only
          ? sql`starts_at <= NOW() AND (ends_at IS NULL OR ends_at >= NOW())`
          : sql`TRUE`}
      )
    `;

    const total = countRow?.total ?? 0;

    return {
      items: rows.map(rowToAnnouncement),
      total,
      page,
      limit,
      total_pages: Math.ceil(total / limit),
    };
  } catch (err) {
    log.error('listAnnouncements failed', { error: err }, 'announcementService');
    throw err;
  }
}

export async function getAnnouncement(id: string): Promise<Announcement | null> {
  try {
    const [row] = await sql`
      SELECT * FROM system_announcements WHERE id = ${id}
    `;
    if (!row) return null;
    return rowToAnnouncement(row);
  } catch (err) {
    log.error('getAnnouncement failed', { id, error: err }, 'announcementService');
    throw err;
  }
}

export interface CreateAnnouncementData {
  title: string;
  message: string;
  type?: string;
  target?: string;
  target_ids?: string[];
  starts_at: string;
  ends_at?: string;
  is_dismissible?: boolean;
  created_by: string;
}

export async function createAnnouncement(data: CreateAnnouncementData): Promise<string> {
  const type         = data.type         ?? 'info';
  const target       = data.target       ?? 'all';
  const target_ids   = data.target_ids   ?? [];
  const is_dismissible = data.is_dismissible ?? true;

  try {
    const rows = await sql`
      INSERT INTO system_announcements (
        title, message, type, target, target_ids,
        starts_at, ends_at, is_dismissible, created_by, created_at
      ) VALUES (
        ${data.title},
        ${data.message},
        ${type},
        ${target},
        ${target_ids},
        ${data.starts_at}::timestamptz,
        ${data.ends_at ?? null}::timestamptz,
        ${is_dismissible},
        ${data.created_by},
        NOW()
      )
      RETURNING id
    `;
    if (!rows[0]) throw new Error('Insert returned no row');
    return rows[0].id as string;
  } catch (err) {
    log.error('createAnnouncement failed', { error: err }, 'announcementService');
    throw err;
  }
}

export async function updateAnnouncement(
  id: string,
  data: Partial<Omit<Announcement, 'id' | 'created_at' | 'created_by'>>
): Promise<void> {
  try {
    const startsAt = data.starts_at ?? null;
    const endsAt   = data.ends_at   ?? null;

    await sql`
      UPDATE system_announcements SET
        title          = COALESCE(${data.title          ?? null}, title),
        message        = COALESCE(${data.message        ?? null}, message),
        type           = COALESCE(${data.type           ?? null}, type),
        target         = COALESCE(${data.target         ?? null}, target),
        target_ids     = COALESCE(${data.target_ids     ?? null}, target_ids),
        starts_at      = CASE WHEN ${startsAt}::text IS NOT NULL
                              THEN ${startsAt}::timestamptz
                              ELSE starts_at END,
        ends_at        = CASE WHEN ${endsAt}::text IS NOT NULL
                              THEN ${endsAt}::timestamptz
                              ELSE ends_at END,
        is_dismissible = COALESCE(${data.is_dismissible ?? null}, is_dismissible)
      WHERE id = ${id}
    `;
  } catch (err) {
    log.error('updateAnnouncement failed', { id, error: err }, 'announcementService');
    throw err;
  }
}

export async function deleteAnnouncement(id: string): Promise<void> {
  try {
    await sql`DELETE FROM system_announcements WHERE id = ${id}`;
  } catch (err) {
    log.error('deleteAnnouncement failed', { id, error: err }, 'announcementService');
    throw err;
  }
}

/**
 * Billing Service — Overview & Subscriptions
 * Aggregate KPIs and subscription lifecycle for the ISAFlow Admin Platform.
 * Invoice operations are in invoiceService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  BillingOverview,
  SubscriptionListItem,
  PaginatedResult,
} from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

// ---------------------------------------------------------------------------
// Overview
// ---------------------------------------------------------------------------

export async function getBillingOverview(): Promise<BillingOverview> {
  const [[subRow], [churnRow], [revRow]] = await Promise.all([
    sql`
      SELECT COUNT(*) AS total,
        COUNT(*) FILTER (WHERE s.status = 'active')   AS active,
        COUNT(*) FILTER (WHERE s.status = 'past_due') AS past_due,
        COUNT(*) FILTER (WHERE s.status = 'trial')    AS trial,
        COALESCE(SUM(CASE
          WHEN s.status != 'active' THEN 0
          WHEN s.billing_cycle = 'monthly' THEN ROUND(p.monthly_price_cents::numeric * (100 - COALESCE(s.discount_percent, 0)::numeric) / 100.0)
          WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents::numeric / 12.0 * (100 - COALESCE(s.discount_percent, 0)::numeric) / 100.0)
          ELSE 0 END), 0) AS mrr_cents
      FROM subscriptions s INNER JOIN plans p ON p.id = s.plan_id
    `,
    sql`
      SELECT
        COUNT(*) FILTER (WHERE status = 'cancelled'
          AND cancelled_at >= NOW() - INTERVAL '30 days')::float AS cancelled_30d,
        GREATEST(COUNT(*) FILTER (WHERE status IN ('active','trial','past_due')
          OR (status = 'cancelled' AND cancelled_at >= NOW() - INTERVAL '30 days')), 1)::float AS base
      FROM subscriptions
    `,
    sql`
      SELECT
        COALESCE(SUM(total_cents) FILTER (WHERE status = 'paid'), 0)              AS total_revenue_cents,
        COALESCE(SUM(total_cents) FILTER (WHERE status IN ('sent','overdue')), 0)  AS outstanding_cents
      FROM admin_invoices
    `,
  ]);

  const s = subRow as Row;
  const c = churnRow as Row;
  const rv = revRow as Row;
  const mrr = parseInt(s.mrr_cents as string, 10);
  const active = parseInt(s.active as string, 10);
  const churnRate = Math.round(((c.cancelled_30d as number) / (c.base as number)) * 10000) / 100;

  const overview: BillingOverview = {
    mrr_cents: mrr,
    arr_cents: mrr * 12,
    total_subscriptions: parseInt(s.total as string, 10),
    active_subscriptions: active,
    past_due_count: parseInt(s.past_due as string, 10),
    trial_count: parseInt(s.trial as string, 10),
    churn_rate_percent: churnRate,
    arpu_cents: active > 0 ? Math.round(mrr / active) : 0,
    total_revenue_cents: parseInt(rv.total_revenue_cents as string, 10),
    outstanding_cents: parseInt(rv.outstanding_cents as string, 10),
  };

  log.info('getBillingOverview', { mrr_cents: mrr, active }, 'BillingService');
  return overview;
}

// ---------------------------------------------------------------------------
// Subscriptions
// ---------------------------------------------------------------------------

const ALLOWED_SUB_SORT: Record<string, string> = {
  created_at: 's.created_at',
  status: 's.status',
  company_name: 'c.name',
  plan_name: 'p.name',
};

function rowToSubscription(r: Row): SubscriptionListItem {
  return {
    id: r.id as string,
    company_id: r.company_id as string,
    company_name: r.company_name as string,
    plan_id: r.plan_id as string,
    plan_name: r.plan_name as string,
    plan_code: r.plan_code as string,
    status: r.status as string,
    billing_cycle: r.billing_cycle as string,
    current_period_start: toIso(r.current_period_start),
    current_period_end: toIso(r.current_period_end),
    cancel_at_period_end: r.cancel_at_period_end as boolean,
    discount_percent: r.discount_percent as number,
    monthly_amount_cents: parseInt(r.monthly_amount_cents as string, 10),
    created_at: toIso(r.created_at) ?? '',
  };
}

export async function listSubscriptions(filters: {
  status?: string;
  plan_id?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<SubscriptionListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SUB_SORT[filters.sort_by ?? ''] ?? 's.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
  `;

  const rows = await sql`
    SELECT s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle, s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
           WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
           ELSE 0 END AS monthly_amount_cents, s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE (${filters.status ?? null}::text IS NULL OR s.status = ${filters.status ?? null})
      AND (${filters.plan_id ?? null}::uuid IS NULL OR s.plan_id = ${filters.plan_id ?? null}::uuid)
      AND (${search}::text IS NULL OR c.name ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listSubscriptions: ${rows.length} rows (page ${page})`, {}, 'BillingService');

  return {
    items: (rows as Row[]).map(rowToSubscription),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function getSubscription(
  subscriptionId: string
): Promise<SubscriptionListItem | null> {
  const rows = await sql`
    SELECT s.id, s.company_id, c.name AS company_name,
      s.plan_id, p.name AS plan_name, p.code AS plan_code,
      s.status, s.billing_cycle, s.current_period_start, s.current_period_end,
      COALESCE(s.cancel_at_period_end, false) AS cancel_at_period_end,
      COALESCE(s.discount_percent, 0)          AS discount_percent,
      CASE WHEN s.billing_cycle = 'monthly' THEN p.monthly_price_cents
           WHEN s.billing_cycle = 'annual'  THEN ROUND(p.annual_price_cents / 12.0)
           ELSE 0 END AS monthly_amount_cents, s.created_at
    FROM subscriptions s
    INNER JOIN companies c ON c.id = s.company_id
    INNER JOIN plans p ON p.id = s.plan_id
    WHERE s.id = ${subscriptionId}
    LIMIT 1
  `;
  if (rows.length === 0) return null;
  return rowToSubscription(rows[0] as Row);
}

export async function createSubscription(data: {
  company_id: string;
  plan_id: string;
  billing_cycle: string;
  discount_percent?: number;
  notes?: string;
}): Promise<string> {
  const { company_id, plan_id, billing_cycle, discount_percent = 0, notes = null } = data;
  const periodDays = billing_cycle === 'annual' ? 365 : 30;

  const rows = await sql`
    INSERT INTO subscriptions (
      company_id, plan_id, status, billing_cycle,
      current_period_start, current_period_end,
      cancel_at_period_end, discount_percent, notes,
      created_at, updated_at
    ) VALUES (
      ${company_id}::uuid, ${plan_id}::uuid,
      'active', ${billing_cycle},
      NOW(), NOW() + INTERVAL '1 day' * ${periodDays},
      false, ${discount_percent}, ${notes},
      NOW(), NOW()
    )
    RETURNING id
  `;

  const id = (rows[0] as Row).id as string;
  log.info('createSubscription', { id, company_id, plan_id, billing_cycle }, 'BillingService');
  return id;
}

export async function updateSubscription(
  subscriptionId: string,
  data: {
    plan_id?: string;
    billing_cycle?: string;
    discount_percent?: number;
    status?: string;
    notes?: string;
  }
): Promise<void> {
  const { plan_id, billing_cycle, discount_percent, status, notes } = data;

  await sql`
    UPDATE subscriptions SET
      plan_id          = COALESCE(${plan_id ?? null}::uuid, plan_id),
      billing_cycle    = COALESCE(${billing_cycle ?? null}, billing_cycle),
      discount_percent = COALESCE(${discount_percent ?? null}, discount_percent),
      status           = COALESCE(${status ?? null}, status),
      notes            = COALESCE(${notes ?? null}, notes),
      updated_at       = NOW()
    WHERE id = ${subscriptionId}
  `;

  log.info('updateSubscription', { subscriptionId }, 'BillingService');
}

export async function cancelSubscription(
  subscriptionId: string,
  atPeriodEnd: boolean
): Promise<void> {
  if (atPeriodEnd) {
    await sql`
      UPDATE subscriptions
      SET cancel_at_period_end = true,
          updated_at           = NOW()
      WHERE id = ${subscriptionId}
    `;
  } else {
    await sql`
      UPDATE subscriptions
      SET status       = 'cancelled',
          cancelled_at = NOW(),
          updated_at   = NOW()
      WHERE id = ${subscriptionId}
    `;
  }
  log.info('cancelSubscription', { subscriptionId, atPeriodEnd }, 'BillingService');
}

