export async function executeRecurring(
  companyId: string,
  templateId: string,
  userId: string,
): Promise<{ entityType: string; entityId: string; posted: boolean }> {
  const rows = (await sql`
    SELECT * FROM recurring_transaction_templates
    WHERE id = ${templateId}::UUID AND company_id = ${companyId} AND is_active = true
  `) as Row[];
  if (!rows[0]) throw new Error('Template not found or inactive');
  const template = mapRow(rows[0]!);

  let entityId: string;
  let posted = false;

  if (template.entityType === 'journal_entry') {
    const { createJournalEntry, postJournalEntry } =
      await import('./journalEntryService');
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const data = template.templateData as any;
    const je = await createJournalEntry(companyId, {
      entryDate: new Date().toISOString().split('T')[0]!,
      description: data.description || template.name,
      source: 'auto_recurring',
      lines: data.lines || [],
    }, userId);
    entityId = je.id;
    if (template.autoPost) {
      await postJournalEntry(companyId, je.id, userId);
      posted = true;
    }
  } else if (template.entityType === 'customer_invoice') {
    // Customer invoice: insert with template_data fields
    const data = template.templateData as Record<string, unknown>;
    const ciRows = (await sql`
      INSERT INTO customer_invoices (company_id, client_id, invoice_date, due_date,
        reference, notes, currency, lines, subtotal, vat_amount, total_amount, status)
      VALUES (
        ${companyId},
        ${String(data.clientId || '')},
        CURRENT_DATE,
        CURRENT_DATE::DATE + INTERVAL '30 days',
        ${String(data.reference || 'AUTO-REC')},
        ${String(data.notes || template.name)},
        ${String(data.currency || 'ZAR')},
        ${JSON.stringify(data.lines || [])}::JSONB,
        ${Number(data.subtotal || 0)},
        ${Number(data.vatAmount || 0)},
        ${Number(data.totalAmount || 0)},
        'draft'
      ) RETURNING id
    `) as Row[];
    entityId = String(ciRows[0]?.id);
    if (template.autoPost) {
      await sql`UPDATE customer_invoices SET status = 'posted' WHERE id = ${entityId}::UUID`;
      posted = true;
    }
  } else {
    // Supplier invoice
    const data = template.templateData as Record<string, unknown>;
    const siRows = (await sql`
      INSERT INTO supplier_invoices (company_id, supplier_id, invoice_date, due_date,
        reference, description, currency, lines, subtotal, vat_amount, total_amount, status)
      VALUES (
        ${companyId},
        ${String(data.supplierId || '')},
        CURRENT_DATE,
        CURRENT_DATE::DATE + INTERVAL '30 days',
        ${String(data.reference || 'AUTO-REC')},
        ${String(data.description || template.name)},
        ${String(data.currency || 'ZAR')},
        ${JSON.stringify(data.lines || [])}::JSONB,
        ${Number(data.subtotal || 0)},
        ${Number(data.vatAmount || 0)},
        ${Number(data.totalAmount || 0)},
        'draft'
      ) RETURNING id
    `) as Row[];
    entityId = String(siRows[0]?.id);
    if (template.autoPost) {
      await sql`UPDATE supplier_invoices SET status = 'posted' WHERE id = ${entityId}::UUID`;
      posted = true;
    }
  }

  // Advance schedule
  const now = new Date();
  const nextDate = calculateNextRunDate(now, template.frequency).toISOString().split('T')[0]!;
  await sql`
    UPDATE recurring_transaction_templates
    SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE
    WHERE id = ${templateId}::UUID AND company_id = ${companyId}
  `;

  log.info('Recurring template executed', { templateId, entityId, entityType: template.entityType }, 'recurring');
  return { entityType: template.entityType, entityId, posted };
}

export async function getUpcomingRecurring(
  companyId: string,
  days = 7,
): Promise<UpcomingItem[]> {
  const rows = (await sql`
    SELECT id, name, entity_type, next_run_date, frequency
    FROM recurring_transaction_templates
    WHERE company_id = ${companyId}
      AND is_active = true
      AND next_run_date <= CURRENT_DATE + ${days} * INTERVAL '1 day'
    ORDER BY next_run_date ASC
  `) as Row[];
  return rows.map(r => ({
    id: String(r.id),
    name: String(r.name),
    entityType: String(r.entity_type),
    nextRunDate: String(r.next_run_date),
    frequency: String(r.frequency),
  }));
}

/**
 * Sage Customer Invoice Importer
 * Moves sage_customer_invoices → customer_invoices + customer_invoice_items
 * Matches Sage's approach: invoices are standalone AR documents,
 * no separate GL journal entries are created per invoice.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

/**
 * Import sage_customer_invoices into customer_invoices with line items
 */
export async function importCustomerInvoices(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('customer_invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_customer_id, client_id,
        invoice_number, invoice_date, due_date,
        subtotal, tax_amount, total_amount, outstanding_amount,
        status, raw_data
      FROM sage_customer_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        const clientId = inv.client_id;
        if (!clientId) {
          await sql`
            UPDATE sage_customer_invoices SET migration_status = 'failed'
            WHERE id = ${inv.id}
          `;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;
        const isPaid = inv.status === 'paid'
          || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data
        const rawData = parseRawData(inv.raw_data);
        const reference = rawData?.Reference || inv.invoice_number || null;

        const newInv = (await sql`
          INSERT INTO customer_invoices (
            company_id, invoice_number, client_id, customer_id, invoice_date, due_date,
            billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${companyId}::UUID,
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${clientId}::UUID, ${clientId}::UUID,
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)},
            ${totalAmount},
            ${isPaid ? totalAmount : 0},
            ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id},
            ${reference},
            ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = rawData?.Lines;
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);

            await sql`
              INSERT INTO customer_invoice_items (
                invoice_id, description, unit_price, quantity,
                tax_amount, line_total, income_type
              ) VALUES (
                ${newInvoiceId}::UUID,
                ${line.Description || 'Line item'},
                ${price}, ${qty}, ${lineTax}, ${lineTotal}, 'other'
              )
            `;
          }
        }

        await sql`
          UPDATE sage_customer_invoices
          SET migration_status = 'imported',
              gl_customer_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import customer invoice',
          { invoiceId: inv.id, error: err }, 'accounting');
        await sql`
          UPDATE sage_customer_invoices SET migration_status = 'failed'
          WHERE id = ${inv.id}
        `;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown): any {
  if (!rawData) return null;
  if (typeof rawData === 'string') {
    try { return JSON.parse(rawData); } catch { return null; }
  }
  return rawData;
}

/**
 * Accounting Adjustment Service
 * Phase 1 Sage Alignment: Customer & supplier balance adjustments
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount } from './systemAccountResolver';
import type { AccountingAdjustment, AdjustmentCreateInput } from '../types/ar.types';
import type { JournalLineInput } from '../types/gl.types';

export async function getAdjustments(companyId: string, filters?: {
  entityType?: string;
  status?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: AccountingAdjustment[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Record<string, unknown>[];
  let countRows: Record<string, unknown>[];

  if (filters?.entityType) {
    rows = (await sql`
      SELECT * FROM accounting_adjustments
      WHERE company_id = ${companyId} AND entity_type = ${filters.entityType}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Record<string, unknown>[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM accounting_adjustments
      WHERE company_id = ${companyId} AND entity_type = ${filters.entityType}
    `) as Record<string, unknown>[];
  } else {
    rows = (await sql`
      SELECT * FROM accounting_adjustments WHERE company_id = ${companyId}
      ORDER BY created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Record<string, unknown>[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM accounting_adjustments WHERE company_id = ${companyId}`) as Record<string, unknown>[];
  }

  // Resolve entity names
  const items: AccountingAdjustment[] = [];
  for (const row of rows) {
    const mapped = mapRow(row);
    if (row.entity_type === 'customer') {
      const c = (await sql`SELECT name FROM customers WHERE id = ${row.entity_id}::UUID`) as Record<string, unknown>[];
      mapped.entityName = c[0]?.name ? String(c[0].name) : 'Unknown';
    } else {
      const s = (await sql`SELECT name FROM suppliers WHERE id = ${row.entity_id}::UUID`) as Record<string, unknown>[];
      mapped.entityName = s[0]?.name ? String(s[0].name) : 'Unknown';
    }
    items.push(mapped);
  }

  return { items, total: Number(countRows[0]?.cnt || 0) };
}

export async function createAdjustment(companyId: string, 
  input: AdjustmentCreateInput,
  userId: string
): Promise<AccountingAdjustment> {
  const rows = (await sql`
    INSERT INTO accounting_adjustments (
      company_id, entity_type, entity_id, adjustment_type, amount, reason,
      adjustment_date, created_by
    ) VALUES (
      ${companyId}, ${input.entityType}, ${input.entityId}::UUID, ${input.adjustmentType},
      ${input.amount}, ${input.reason},
      ${input.adjustmentDate || new Date().toISOString().split('T')[0]},
      ${userId}::UUID
    ) RETURNING *
  `) as Record<string, unknown>[];

  log.info('Created adjustment', { id: rows[0]?.id, type: input.entityType }, 'accounting');
  return mapRow(rows[0]!);
}

export async function approveAdjustment(companyId: string, id: string, userId: string): Promise<AccountingAdjustment> {
  const adjRows = (await sql`SELECT * FROM accounting_adjustments WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!adjRows[0]) throw new Error('Adjustment not found');
  if (adjRows[0].status !== 'draft') throw new Error('Adjustment is not in draft status');

  const adj = adjRows[0];
  const amount = Number(adj.amount);
  const isCustomer = adj.entity_type === 'customer';
  const isDebit = adj.adjustment_type === 'debit';

  // GL accounts
  const balanceAccount = isCustomer
    ? await getSystemAccount('receivable')
    : await getSystemAccount('payable');
  const offsetAccount = isDebit
    ? await getSystemAccount('other_income')
    : await getSystemAccount('admin_expense');

  const lines: JournalLineInput[] = isDebit
    ? [
        { glAccountId: balanceAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: offsetAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ]
    : [
        { glAccountId: offsetAccount.id, debit: amount, credit: 0,
          description: `Adjustment ${adj.adjustment_number}` },
        { glAccountId: balanceAccount.id, debit: 0, credit: amount,
          description: `Adjustment ${adj.adjustment_number}` },
      ];

  const je = await createJournalEntry('', {
    entryDate: String(adj.adjustment_date),
    description: `${isCustomer ? 'Customer' : 'Supplier'} adjustment ${adj.adjustment_number}`,
    source: 'auto_adjustment',
    sourceDocumentId: id,
    lines,
  }, userId);
  await postJournalEntry('', je.id, userId);

  const updated = (await sql`
    UPDATE accounting_adjustments
    SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
        gl_journal_entry_id = ${je.id}::UUID
    WHERE id = ${id} AND company_id = ${companyId} RETURNING *
  `) as Row[];

  log.info('Approved adjustment', { id, journalEntryId: je.id }, 'accounting');
  return mapRow(updated[0]!);
}

export async function cancelAdjustment(companyId: string, id: string): Promise<void> {
  await sql`UPDATE accounting_adjustments SET status = 'cancelled' WHERE id = ${id} AND company_id = ${companyId} AND status = 'draft'`;
}

function mapRow(row: Row): AccountingAdjustment {
  return {
    id: String(row.id),
    adjustmentNumber: row.adjustment_number ? String(row.adjustment_number) : '',
    entityType: String(row.entity_type) as AccountingAdjustment['entityType'],
    entityId: String(row.entity_id),
    adjustmentType: String(row.adjustment_type) as AccountingAdjustment['adjustmentType'],
    amount: Number(row.amount),
    reason: String(row.reason),
    adjustmentDate: String(row.adjustment_date),
    status: String(row.status) as AccountingAdjustment['status'],
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Sage Customer Invoice Importer
 * Moves sage_customer_invoices → customer_invoices + customer_invoice_items
 * Matches Sage's approach: invoices are standalone AR documents,
 * no separate GL journal entries are created per invoice.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { MigrationRun } from './sageMigrationService';
import { startRun, completeRun, failRun } from './sageMigrationService';

type Row = Record<string, unknown>;

/**
 * Import sage_customer_invoices into customer_invoices with line items
 */
export async function importCustomerInvoices(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('customer_invoice_import', userId);

  try {
    const sageInvoices = (await sql`
      SELECT id, sage_invoice_id, sage_customer_id, client_id,
        invoice_number, invoice_date, due_date,
        subtotal, tax_amount, total_amount, outstanding_amount,
        status, raw_data
      FROM sage_customer_invoices
      WHERE migration_status = 'pending'
      ORDER BY invoice_date
    `) as Row[];

    let succeeded = 0;
    let failed = 0;
    let skipped = 0;

    for (const inv of sageInvoices) {
      try {
        const totalAmount = Number(inv.total_amount || 0);
        if (totalAmount === 0) { skipped++; continue; }

        const clientId = inv.client_id;
        if (!clientId) {
          await sql`
            UPDATE sage_customer_invoices SET migration_status = 'failed'
            WHERE id = ${inv.id}
          `;
          failed++;
          continue;
        }

        const subtotal = Number(inv.subtotal || 0) || totalAmount / 1.15;
        const taxAmount = Number(inv.tax_amount || 0) || totalAmount - subtotal;
        const taxRate = subtotal > 0
          ? Math.round((taxAmount / subtotal) * 100 * 100) / 100
          : 15;
        const isPaid = inv.status === 'paid'
          || Number(inv.outstanding_amount || 0) === 0;

        // Extract reference from raw_data
        const rawData = parseRawData(inv.raw_data);
        const reference = rawData?.Reference || inv.invoice_number || null;

        const newInv = (await sql`
          INSERT INTO customer_invoices (
            company_id, invoice_number, client_id, customer_id, invoice_date, due_date,
            billing_period_start, billing_period_end,
            subtotal, tax_rate, tax_amount, total_amount,
            amount_paid, status, sage_invoice_id, reference, created_by
          ) VALUES (
            ${companyId}::UUID,
            ${inv.invoice_number || `SAGE-${inv.sage_invoice_id}`},
            ${clientId}::UUID, ${clientId}::UUID,
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${inv.invoice_date}, ${inv.due_date || inv.invoice_date},
            ${subtotal.toFixed(2)}, ${taxRate}, ${taxAmount.toFixed(2)},
            ${totalAmount},
            ${isPaid ? totalAmount : 0},
            ${isPaid ? 'paid' : 'approved'},
            ${inv.sage_invoice_id},
            ${reference},
            ${userId}
          ) RETURNING id
        `) as Row[];

        const newInvoiceId = String(newInv[0].id);

        // Insert line items from raw_data
        const lines = rawData?.Lines;
        if (lines && Array.isArray(lines) && lines.length > 0) {
          for (const line of lines) {
            const qty = Number(line.Quantity || 1);
            const price = Number(line.UnitPriceExclusive || 0);
            const lineTax = Number(line.Tax || 0);
            const lineTotal = Number(line.Exclusive || line.Total || price * qty);

            await sql`
              INSERT INTO customer_invoice_items (
                invoice_id, description, unit_price, quantity,
                tax_amount, line_total, income_type
              ) VALUES (
                ${newInvoiceId}::UUID,
                ${line.Description || 'Line item'},
                ${price}, ${qty}, ${lineTax}, ${lineTotal}, 'other'
              )
            `;
          }
        }

        await sql`
          UPDATE sage_customer_invoices
          SET migration_status = 'imported',
              gl_customer_invoice_id = ${newInvoiceId}::UUID
          WHERE id = ${inv.id}
        `;

        succeeded++;
      } catch (err) {
        log.error('Failed to import customer invoice',
          { invoiceId: inv.id, error: err }, 'accounting');
        await sql`
          UPDATE sage_customer_invoices SET migration_status = 'failed'
          WHERE id = ${inv.id}
        `;
        failed++;
      }
    }

    return await completeRun(runId, sageInvoices.length, succeeded, failed, skipped);
  } catch (err) {
    await failRun(runId, err);
    throw err;
  }
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function parseRawData(rawData: unknown): any {
  if (!rawData) return null;
  if (typeof rawData === 'string') {
    try { return JSON.parse(rawData); } catch { return null; }
  }
  return rawData;
}

/**
 * Group Company Service
 * Manages company groups, memberships, group COA, COA mappings,
 * and intercompany transactions for consolidated reporting.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

// ── Types ────────────────────────────────────────────────────────────────────

export interface CompanyGroup {
  id: string;
  name: string;
  holdingCompanyId: string | null;
  defaultCurrency: string;
  financialYearStart: number;
  isActive: boolean;
  createdBy: string | null;
  createdAt: string;
  updatedAt: string;
  memberCount?: number;
}

export interface GroupMember {
  id: string;
  groupId: string;
  companyId: string;
  companyName?: string;
  ownershipPct: number;
  consolidationMethod: string;
  isHolding: boolean;
  joinedDate: string;
  leftDate: string | null;
  createdAt: string;
}

export interface GroupAccount {
  id: string;
  groupId: string;
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string | null;
  parentAccountId: string | null;
  normalBalance: string;
  level: number;
  displayOrder: number;
  isActive: boolean;
  createdAt: string;
}

export interface CoaMapping {
  id: string;
  groupId: string;
  groupAccountId: string;
  groupAccountCode?: string;
  groupAccountName?: string;
  companyId: string;
  companyAccountId: string;
  companyAccountCode?: string;
  companyAccountName?: string;
  createdAt: string;
}

export interface IntercompanyTransaction {
  id: string;
  groupId: string;
  sourceCompanyId: string;
  sourceCompanyName?: string;
  targetCompanyId: string;
  targetCompanyName?: string;
  sourceJournalEntryId: string | null;
  targetJournalEntryId: string | null;
  transactionType: string;
  amount: number;
  currency: string;
  description: string | null;
  transactionDate: string;
  matchStatus: string;
  varianceAmount: number;
  matchedAt: string | null;
  matchedBy: string | null;
  createdAt: string;
}

export interface IntercompanyReconciliation {
  totalTransactions: number;
  matched: number;
  unmatched: number;
  partial: number;
  variance: number;
  totalAmount: number;
  matchedAmount: number;
  unmatchedAmount: number;
  varianceTotal: number;
  transactions: IntercompanyTransaction[];
}

export interface IntercompanyFilters {
  dateFrom?: string;
  dateTo?: string;
  matchStatus?: string;
  sourceCompanyId?: string;
  targetCompanyId?: string;
  transactionType?: string;
}

// ── Group CRUD ───────────────────────────────────────────────────────────────

export async function listGroups(): Promise<CompanyGroup[]> {
  const rows = (await sql`
    SELECT cg.*,
           COUNT(cgm.id) FILTER (WHERE cgm.left_date IS NULL) AS member_count
    FROM company_groups cg
    LEFT JOIN company_group_members cgm ON cgm.group_id = cg.id
    WHERE cg.is_active = true
    GROUP BY cg.id
    ORDER BY cg.name
  `) as Row[];
  return rows.map((r: Row) => ({ ...mapGroup(r), memberCount: Number(r.member_count) }));
}

export async function getGroup(groupId: string): Promise<CompanyGroup | null> {
  const rows = (await sql`
    SELECT cg.*,
           COUNT(cgm.id) FILTER (WHERE cgm.left_date IS NULL) AS member_count
    FROM company_groups cg
    LEFT JOIN company_group_members cgm ON cgm.group_id = cg.id
    WHERE cg.id = ${groupId}::UUID
    GROUP BY cg.id
  `) as Row[];
  if (!rows[0]) return null;
  return { ...mapGroup(rows[0]), memberCount: Number(rows[0].member_count) };
}

export async function createGroup(input: {
  name: string;
  holdingCompanyId?: string;
  defaultCurrency?: string;
  financialYearStart?: number;
}, userId: string): Promise<CompanyGroup> {
  const rows = (await sql`
    INSERT INTO company_groups (name, holding_company_id, default_currency, financial_year_start, created_by)
    VALUES (
      ${input.name},
      ${input.holdingCompanyId || null},
      ${input.defaultCurrency || 'ZAR'},
      ${input.financialYearStart || 3},
      ${userId}::UUID
    )
    RETURNING *
  `) as Row[];

  const group = mapGroup(rows[0]);

  // Auto-add holding company as member if specified
  if (input.holdingCompanyId) {
    await sql`
      INSERT INTO company_group_members (group_id, company_id, ownership_pct, consolidation_method, is_holding)
      VALUES (${group.id}::UUID, ${input.holdingCompanyId}::UUID, 100.00, 'full', true)
    `;
  }

  log.info('Company group created', { id: group.id, name: input.name }, 'accounting');
  return group;
}

export async function updateGroup(groupId: string, input: Partial<{
  name: string;
  holdingCompanyId: string;
  defaultCurrency: string;
  financialYearStart: number;
}>): Promise<CompanyGroup> {
  const rows = (await sql`
    UPDATE company_groups SET
      name = COALESCE(${input.name ?? null}, name),
      holding_company_id = COALESCE(${input.holdingCompanyId ?? null}, holding_company_id),
      default_currency = COALESCE(${input.defaultCurrency ?? null}, default_currency),
      financial_year_start = COALESCE(${input.financialYearStart ?? null}, financial_year_start),
      updated_at = NOW()
    WHERE id = ${groupId}::UUID
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Company group ${groupId} not found`);
  return mapGroup(rows[0]);
}

export async function deleteGroup(groupId: string): Promise<void> {
  await sql`
    UPDATE company_groups SET is_active = false, updated_at = NOW()
    WHERE id = ${groupId}::UUID
  `;
  log.info('Company group soft-deleted', { groupId }, 'accounting');
}

// ── Group Members ────────────────────────────────────────────────────────────

export async function addMember(groupId: string, companyId: string, opts?: {
  ownershipPct?: number;
  consolidationMethod?: string;
}): Promise<GroupMember> {
  const rows = (await sql`
    INSERT INTO company_group_members (group_id, company_id, ownership_pct, consolidation_method)
    VALUES (
      ${groupId}::UUID,
      ${companyId}::UUID,
      ${opts?.ownershipPct ?? 100},
      ${opts?.consolidationMethod ?? 'full'}
    )
    RETURNING *
  `) as Row[];
  log.info('Group member added', { groupId, companyId }, 'accounting');
  return mapMember(rows[0]);
}

export async function updateMember(memberId: string, opts: {
  ownershipPct?: number;
  consolidationMethod?: string;
}): Promise<GroupMember> {
  const rows = (await sql`
    UPDATE company_group_members SET
      ownership_pct = COALESCE(${opts.ownershipPct ?? null}, ownership_pct),
      consolidation_method = COALESCE(${opts.consolidationMethod ?? null}, consolidation_method)
    WHERE id = ${memberId}::UUID
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Group member ${memberId} not found`);
  return mapMember(rows[0]);
}

export async function removeMember(memberId: string): Promise<void> {
  await sql`
    UPDATE company_group_members SET left_date = CURRENT_DATE
    WHERE id = ${memberId}::UUID
  `;
  log.info('Group member removed', { memberId }, 'accounting');
}

export async function getGroupMembers(groupId: string): Promise<GroupMember[]> {
  const rows = (await sql`
    SELECT cgm.*, c.name AS company_name
    FROM company_group_members cgm
    JOIN companies c ON c.id = cgm.company_id
    WHERE cgm.group_id = ${groupId}::UUID AND cgm.left_date IS NULL
    ORDER BY cgm.is_holding DESC, c.name ASC
  `) as Row[];
  return rows.map((r: Row) => ({ ...mapMember(r), companyName: r.company_name }));
}

// ── Group Chart of Accounts ──────────────────────────────────────────────────

export async function getGroupAccounts(groupId: string): Promise<GroupAccount[]> {
  const rows = (await sql`
    SELECT * FROM group_accounts
    WHERE group_id = ${groupId}::UUID AND is_active = true
    ORDER BY display_order, account_code
  `) as Row[];
  return rows.map(mapGroupAccount);
}

export async function createGroupAccount(groupId: string, input: {
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype?: string;
  parentAccountId?: string;
  normalBalance?: string;
  level?: number;
  displayOrder?: number;
}): Promise<GroupAccount> {
  const rows = (await sql`
    INSERT INTO group_accounts (
      group_id, account_code, account_name, account_type, account_subtype,
      parent_account_id, normal_balance, level, display_order
    )
    VALUES (
      ${groupId}::UUID,
      ${input.accountCode},
      ${input.accountName},
      ${input.accountType},
      ${input.accountSubtype || null},
      ${input.parentAccountId || null},
      ${input.normalBalance || 'debit'},
      ${input.level ?? 1},
      ${input.displayOrder ?? 0}
    )
    RETURNING *
  `) as Row[];
  log.info('Group account created', { groupId, code: input.accountCode }, 'accounting');
  return mapGroupAccount(rows[0]);
}

export async function updateGroupAccount(accountId: string, input: Partial<{
  accountCode: string;
  accountName: string;
  accountType: string;
  accountSubtype: string;
  parentAccountId: string;
  normalBalance: string;
  level: number;
  displayOrder: number;
}>): Promise<GroupAccount> {
  const rows = (await sql`
    UPDATE group_accounts SET
      account_code = COALESCE(${input.accountCode ?? null}, account_code),
      account_name = COALESCE(${input.accountName ?? null}, account_name),
      account_type = COALESCE(${input.accountType ?? null}, account_type),
      account_subtype = COALESCE(${input.accountSubtype ?? null}, account_subtype),
      parent_account_id = COALESCE(${input.parentAccountId ?? null}, parent_account_id),
      normal_balance = COALESCE(${input.normalBalance ?? null}, normal_balance),
      level = COALESCE(${input.level ?? null}, level),
      display_order = COALESCE(${input.displayOrder ?? null}, display_order)
    WHERE id = ${accountId}::UUID
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Group account ${accountId} not found`);
  return mapGroupAccount(rows[0]);
}

export async function deleteGroupAccount(accountId: string): Promise<void> {
  await sql`
    UPDATE group_accounts SET is_active = false
    WHERE id = ${accountId}::UUID
  `;
}

export async function autoGenerateGroupCOA(groupId: string, sourceCompanyId: string): Promise<number> {
  const rows = (await sql`
    INSERT INTO group_accounts (group_id, account_code, account_name, account_type, account_subtype, normal_balance, level, display_order)
    SELECT
      ${groupId}::UUID,
      a.account_code,
      a.account_name,
      a.account_type,
      a.account_subtype,
      a.normal_balance,
      COALESCE(a.level, 1),
      COALESCE(a.display_order, 0)
    FROM gl_accounts a
    WHERE a.company_id = ${sourceCompanyId}::UUID AND a.is_active = true
    ON CONFLICT (group_id, account_code) DO NOTHING
    RETURNING id
  `) as Row[];
  log.info('Group COA auto-generated', { groupId, sourceCompanyId, count: rows.length }, 'accounting');
  return rows.length;
}

// ── COA Mappings ─────────────────────────────────────────────────────────────

export async function getCoaMappings(groupId: string, companyId?: string): Promise<CoaMapping[]> {
  const rows = companyId
    ? (await sql`
        SELECT m.*,
               ga.account_code AS group_account_code, ga.account_name AS group_account_name,
               ca.account_code AS company_account_code, ca.account_name AS company_account_name
        FROM group_coa_mappings m
        JOIN group_accounts ga ON ga.id = m.group_account_id
        JOIN gl_accounts ca ON ca.id = m.company_account_id
        WHERE m.group_id = ${groupId}::UUID AND m.company_id = ${companyId}::UUID
        ORDER BY ga.account_code
      `) as Row[]
    : (await sql`
        SELECT m.*,
               ga.account_code AS group_account_code, ga.account_name AS group_account_name,
               ca.account_code AS company_account_code, ca.account_name AS company_account_name
        FROM group_coa_mappings m
        JOIN group_accounts ga ON ga.id = m.group_account_id
        JOIN gl_accounts ca ON ca.id = m.company_account_id
        WHERE m.group_id = ${groupId}::UUID
        ORDER BY m.company_id, ga.account_code
      `) as Row[];
  return rows.map(mapCoaMapping);
}

export async function setCoaMapping(
  groupId: string,
  companyId: string,
  companyAccountId: string,
  groupAccountId: string,
): Promise<CoaMapping> {
  const rows = (await sql`
    INSERT INTO group_coa_mappings (group_id, company_id, company_account_id, group_account_id)
    VALUES (${groupId}::UUID, ${companyId}::UUID, ${companyAccountId}::UUID, ${groupAccountId}::UUID)
    ON CONFLICT (group_id, company_id, company_account_id)
    DO UPDATE SET group_account_id = ${groupAccountId}::UUID
    RETURNING *
  `) as Row[];
  return mapCoaMapping(rows[0]);
}

export async function removeCoaMapping(mappingId: string): Promise<void> {
  await sql`DELETE FROM group_coa_mappings WHERE id = ${mappingId}::UUID`;
}

export async function autoMapAccounts(groupId: string, companyId: string): Promise<number> {
  const rows = (await sql`
    INSERT INTO group_coa_mappings (group_id, company_id, company_account_id, group_account_id)
    SELECT
      ${groupId}::UUID,
      ${companyId}::UUID,
      ca.id,
      ga.id
    FROM gl_accounts ca
    JOIN group_accounts ga ON ga.group_id = ${groupId}::UUID AND ga.account_code = ca.account_code AND ga.is_active = true
    WHERE ca.company_id = ${companyId}::UUID AND ca.is_active = true
    ON CONFLICT (group_id, company_id, company_account_id) DO NOTHING
    RETURNING id
  `) as Row[];
  log.info('Auto-mapped accounts', { groupId, companyId, mapped: rows.length }, 'accounting');
  return rows.length;
}

export async function getUnmappedAccounts(groupId: string, companyId: string): Promise<{
  id: string;
  accountCode: string;
  accountName: string;
  accountType: string;
}[]> {
  const rows = (await sql`
    SELECT ca.id, ca.account_code, ca.account_name, ca.account_type
    FROM gl_accounts ca
    WHERE ca.company_id = ${companyId}::UUID
      AND ca.is_active = true
      AND NOT EXISTS (
        SELECT 1 FROM group_coa_mappings m
        WHERE m.group_id = ${groupId}::UUID
          AND m.company_id = ${companyId}::UUID
          AND m.company_account_id = ca.id
      )
    ORDER BY ca.account_code
  `) as Row[];
  return rows.map((r: Row) => ({
    id: r.id,
    accountCode: r.account_code,
    accountName: r.account_name,
    accountType: r.account_type,
  }));
}

// ── Intercompany Transactions ────────────────────────────────────────────────

export async function listIntercompanyTransactions(
  groupId: string,
  filters?: IntercompanyFilters,
): Promise<IntercompanyTransaction[]> {
  const rows = (await sql`
    SELECT it.*,
           sc.name AS source_company_name,
           tc.name AS target_company_name
    FROM intercompany_transactions it
    JOIN companies sc ON sc.id = it.source_company_id
    JOIN companies tc ON tc.id = it.target_company_id
    WHERE it.group_id = ${groupId}::UUID
      AND (${filters?.dateFrom || null}::DATE IS NULL OR it.transaction_date >= ${filters?.dateFrom || null}::DATE)
      AND (${filters?.dateTo || null}::DATE IS NULL OR it.transaction_date <= ${filters?.dateTo || null}::DATE)
      AND (${filters?.matchStatus || null}::TEXT IS NULL OR it.match_status = ${filters?.matchStatus || null})
      AND (${filters?.sourceCompanyId || null}::UUID IS NULL OR it.source_company_id = ${filters?.sourceCompanyId || null}::UUID)
      AND (${filters?.targetCompanyId || null}::UUID IS NULL OR it.target_company_id = ${filters?.targetCompanyId || null}::UUID)
      AND (${filters?.transactionType || null}::TEXT IS NULL OR it.transaction_type = ${filters?.transactionType || null})
    ORDER BY it.transaction_date DESC, it.created_at DESC
  `) as Row[];
  return rows.map(mapIntercompanyTx);
}

export async function createIntercompanyTransaction(input: {
  groupId: string;
  sourceCompanyId: string;
  targetCompanyId: string;
  sourceJournalEntryId?: string;
  targetJournalEntryId?: string;
  transactionType: string;
  amount: number;
  currency?: string;
  description?: string;
  transactionDate: string;
}): Promise<IntercompanyTransaction> {
  const rows = (await sql`
    INSERT INTO intercompany_transactions (
      group_id, source_company_id, target_company_id,
      source_journal_entry_id, target_journal_entry_id,
      transaction_type, amount, currency, description, transaction_date
    )
    VALUES (
      ${input.groupId}::UUID,
      ${input.sourceCompanyId}::UUID,
      ${input.targetCompanyId}::UUID,
      ${input.sourceJournalEntryId || null},
      ${input.targetJournalEntryId || null},
      ${input.transactionType},
      ${input.amount},
      ${input.currency || 'ZAR'},
      ${input.description || null},
      ${input.transactionDate}::DATE
    )
    RETURNING *
  `) as Row[];
  log.info('Intercompany transaction created', {
    id: rows[0].id,
    groupId: input.groupId,
    type: input.transactionType,
    amount: input.amount,
  }, 'accounting');
  return mapIntercompanyTx(rows[0]);
}

export async function matchIntercompanyTransactions(
  sourceId: string,
  targetId: string,
): Promise<void> {
  // Fetch both sides
  const sources = (await sql`SELECT * FROM intercompany_transactions WHERE id = ${sourceId}::UUID`) as Row[];
  const targets = (await sql`SELECT * FROM intercompany_transactions WHERE id = ${targetId}::UUID`) as Row[];

  if (!sources[0] || !targets[0]) {
    throw new Error('One or both intercompany transactions not found');
  }

  const source = sources[0];
  const target = targets[0];
  const variance = Math.abs(Number(source.amount) - Number(target.amount));
  const status = variance === 0 ? 'matched' : 'variance';

  await sql`
    UPDATE intercompany_transactions SET
      match_status = ${status},
      variance_amount = ${variance},
      matched_at = NOW()
    WHERE id IN (${sourceId}::UUID, ${targetId}::UUID)
  `;

  log.info('Intercompany transactions matched', { sourceId, targetId, status, variance }, 'accounting');
}

export async function getIntercompanyReconciliation(
  groupId: string,
  periodStart: string,
  periodEnd: string,
): Promise<IntercompanyReconciliation> {
  const rows = (await sql`
    SELECT it.*,
           sc.name AS source_company_name,
           tc.name AS target_company_name
    FROM intercompany_transactions it
    JOIN companies sc ON sc.id = it.source_company_id
    JOIN companies tc ON tc.id = it.target_company_id
    WHERE it.group_id = ${groupId}::UUID
      AND it.transaction_date >= ${periodStart}::DATE
      AND it.transaction_date <= ${periodEnd}::DATE
    ORDER BY it.transaction_date DESC
  `) as Row[];

  const transactions = rows.map(mapIntercompanyTx);
  const matched = transactions.filter(t => t.matchStatus === 'matched');
  const unmatched = transactions.filter(t => t.matchStatus === 'unmatched');
  const partial = transactions.filter(t => t.matchStatus === 'partial');
  const withVariance = transactions.filter(t => t.matchStatus === 'variance');

  return {
    totalTransactions: transactions.length,
    matched: matched.length,
    unmatched: unmatched.length,
    partial: partial.length,
    variance: withVariance.length,
    totalAmount: transactions.reduce((sum, t) => sum + t.amount, 0),
    matchedAmount: matched.reduce((sum, t) => sum + t.amount, 0),
    unmatchedAmount: unmatched.reduce((sum, t) => sum + t.amount, 0),
    varianceTotal: withVariance.reduce((sum, t) => sum + t.varianceAmount, 0),
    transactions,
  };
}

// ── Mappers ──────────────────────────────────────────────────────────────────

function mapGroup(r: Row): CompanyGroup {
  return {
    id: r.id,
    name: r.name,
    holdingCompanyId: r.holding_company_id,
    defaultCurrency: r.default_currency,
    financialYearStart: r.financial_year_start,
    isActive: r.is_active,
    createdBy: r.created_by,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function mapMember(r: Row): GroupMember {
  return {
    id: r.id,
    groupId: r.group_id,
    companyId: r.company_id,
    ownershipPct: Number(r.ownership_pct),
    consolidationMethod: r.consolidation_method,
    isHolding: r.is_holding,
    joinedDate: r.joined_date,
    leftDate: r.left_date,
    createdAt: r.created_at,
  };
}

function mapGroupAccount(r: Row): GroupAccount {
  return {
    id: r.id,
    groupId: r.group_id,
    accountCode: r.account_code,
    accountName: r.account_name,
    accountType: r.account_type,
    accountSubtype: r.account_subtype,
