/**
 * Smart Categorization Service
 * AI-powered bank transaction categorization using rules, patterns, and historical learning
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type ConfidenceLevel = 'HIGH' | 'MEDIUM' | 'LOW';

export interface CategorizationInput {
  description: string;
  amount: number;
  reference?: string;
}

export interface CategorizationResult {
  glAccountId?: string;
  glAccountCode?: string;
  glAccountName?: string;
  category?: string;
  vatCode?: string;
  confidence: number;
  confidenceLevel: ConfidenceLevel;
  matchSource: 'rule' | 'pattern' | 'historical';
  matchDetail?: string;
}

export interface BulkCategorizationResult {
  categorized: number;
  skipped: number;
  results: Array<{
    transactionId: string;
    result: CategorizationResult | null;
  }>;
}

// ── Confidence helpers ───────────────────────────────────────────────────────

function toConfidenceLevel(score: number): ConfidenceLevel {
  if (score >= 0.85) return 'HIGH';
  if (score >= 0.60) return 'MEDIUM';
  return 'LOW';
}

// ── Core: Categorize a single transaction ────────────────────────────────────

export async function categorizeBankTransaction(companyId: string, 
  tx: CategorizationInput
): Promise<CategorizationResult | null> {
  const description = (tx.description || '').toUpperCase().trim();
  const reference = (tx.reference || '').toUpperCase().trim();

  if (!description && !reference) return null;

  // 1. Check existing bank_categorisation_rules (highest priority)
  const ruleMatch = await matchAgainstRules(description, reference);
  if (ruleMatch) return ruleMatch;

  // 2. Check categorization_patterns table (system + learned patterns)
  const patternMatch = await matchAgainstPatterns(description, reference);
  if (patternMatch) return patternMatch;

  // 3. Learn from historical allocations (similar past transactions)
  const historicalMatch = await matchFromHistory(description, tx.amount);
  if (historicalMatch) return historicalMatch;

  return null;
}

// ── Strategy 1: Match against bank_categorisation_rules ──────────────────────

async function matchAgainstRules(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const rules = (await sql`
      SELECT r.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM bank_categorisation_rules r
      LEFT JOIN gl_accounts ga ON ga.id = r.gl_account_id
      WHERE r.is_active = true
      ORDER BY r.priority ASC
    `) as Row[];

    for (const rule of rules) {
      const pattern = String(rule.match_pattern).toUpperCase();
      const matchType = String(rule.match_type);
      const matchField = String(rule.match_field);

      const targets: string[] = [];
      if (matchField === 'description' || matchField === 'both') targets.push(description);
      if (matchField === 'reference' || matchField === 'both') targets.push(reference);

      const matched = targets.some(target => {
        switch (matchType) {
          case 'contains': return target.includes(pattern);
          case 'starts_with': return target.startsWith(pattern);
          case 'ends_with': return target.endsWith(pattern);
          case 'exact': return target === pattern;
          default: return target.includes(pattern);
        }
      });

      if (matched) {
        return {
          glAccountId: rule.gl_account_id ? String(rule.gl_account_id) : undefined,
          glAccountCode: rule.gl_account_code ? String(rule.gl_account_code) : undefined,
          glAccountName: rule.gl_account_name ? String(rule.gl_account_name) : undefined,
          category: String(rule.rule_name),
          vatCode: String(rule.vat_code || 'none'),
          confidence: 0.95,
          confidenceLevel: 'HIGH',
          matchSource: 'rule',
          matchDetail: `Rule: ${rule.rule_name} (${matchType} "${rule.match_pattern}")`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: rule matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 2: Match against categorization_patterns ────────────────────────

async function matchAgainstPatterns(
  description: string,
  reference: string
): Promise<CategorizationResult | null> {
  try {
    const patterns = (await sql`
      SELECT cp.*, ga.account_code AS gl_account_code, ga.account_name AS gl_account_name
      FROM categorization_patterns cp
      LEFT JOIN gl_accounts ga ON ga.id = cp.gl_account_id
      ORDER BY cp.confidence DESC, cp.usage_count DESC
    `) as Row[];

    const combined = `${description} ${reference}`;

    for (const p of patterns) {
      const pat = String(p.pattern).toUpperCase();
      const matchType = String(p.match_type);

      let matched = false;
      switch (matchType) {
        case 'contains':
          matched = combined.includes(pat);
          break;
        case 'starts_with':
          matched = description.startsWith(pat) || reference.startsWith(pat);
          break;
        case 'regex':
          try {
            const re = new RegExp(p.pattern, 'i');
            matched = re.test(description) || re.test(reference);
          } catch {
            // WORKING: invalid regex patterns are safely skipped
            matched = false;
          }
          break;
        default:
          matched = combined.includes(pat);
      }

      if (matched) {
        const confidence = Number(p.confidence) || 0.80;

        // Update usage stats (fire-and-forget)
        sql`
          UPDATE categorization_patterns
          SET usage_count = usage_count + 1, last_used_at = NOW()
          WHERE id = ${p.id}::UUID
        `.catch(() => {});

        return {
          glAccountId: p.gl_account_id ? String(p.gl_account_id) : undefined,
          glAccountCode: p.gl_account_code ? String(p.gl_account_code) : undefined,
          glAccountName: p.gl_account_name ? String(p.gl_account_name) : undefined,
          category: p.category ? String(p.category) : undefined,
          vatCode: String(p.vat_code || 'standard'),
          confidence,
          confidenceLevel: toConfidenceLevel(confidence),
          matchSource: 'pattern',
          matchDetail: `Pattern: "${p.pattern}" (${p.source})`,
        };
      }
    }
  } catch (err) {
    log.error('Smart categorization: pattern matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Strategy 3: Learn from historical allocations ────────────────────────────

async function matchFromHistory(
  description: string,
  _amount: number
): Promise<CategorizationResult | null> {
  if (!description || description.length < 3) return null;

  try {
    // Extract significant words (3+ chars, skip common banking noise)
    const noiseWords = new Set([
      'THE', 'AND', 'FOR', 'FROM', 'WITH', 'PAYMENT', 'TRANSFER',
      'DEBIT', 'CREDIT', 'ORDER', 'REF', 'POS', 'PURCHASE', 'CARD',
    ]);
    const words = description
      .split(/[\s/\\,.-]+/)
      .filter(w => w.length >= 3 && !noiseWords.has(w) && !/^\d+$/.test(w));

    if (words.length === 0) return null;

    // Build search: look for allocated transactions with similar descriptions
    // Use the first 2-3 significant words for matching
    const searchWords = words.slice(0, 3);
    const likePattern = `%${searchWords.join('%')}%`;

    const historicalRows = (await sql`
      SELECT
        bt.suggested_gl_account_id,
        bt.suggested_category,
        bt.suggested_vat_code,
        bt.allocation_type,
        ga.account_code AS gl_account_code,
        ga.account_name AS gl_account_name,
        COUNT(*) AS match_count
      FROM bank_transactions bt
      LEFT JOIN gl_accounts ga ON ga.id = bt.suggested_gl_account_id
      WHERE bt.status IN ('matched', 'reconciled')
        AND bt.matched_journal_line_id IS NOT NULL
        AND bt.suggested_gl_account_id IS NOT NULL
        AND UPPER(bt.description) ILIKE ${likePattern}
      GROUP BY bt.suggested_gl_account_id, bt.suggested_category,
               bt.suggested_vat_code, bt.allocation_type,
               ga.account_code, ga.account_name
      ORDER BY match_count DESC
      LIMIT 1
    `) as Row[];

    if (historicalRows.length > 0) {
      const row = historicalRows[0];
      const matchCount = Number(row.match_count);
      // Scale confidence based on how many historical matches we found
      const baseConfidence = matchCount >= 5 ? 0.70 : matchCount >= 2 ? 0.55 : 0.40;

      return {
        glAccountId: row.suggested_gl_account_id ? String(row.suggested_gl_account_id) : undefined,
        glAccountCode: row.gl_account_code ? String(row.gl_account_code) : undefined,
        glAccountName: row.gl_account_name ? String(row.gl_account_name) : undefined,
        category: row.suggested_category ? String(row.suggested_category) : undefined,
        vatCode: String(row.suggested_vat_code || 'none'),
        confidence: baseConfidence,
        confidenceLevel: toConfidenceLevel(baseConfidence),
        matchSource: 'historical',
        matchDetail: `Historical: ${matchCount} similar transaction(s)`,
      };
    }
  } catch (err) {
    log.error('Smart categorization: historical matching failed', { error: err }, 'accounting');
  }

  return null;
}

// ── Learn from user allocation ───────────────────────────────────────────────

export async function learnFromAllocation(companyId: string, 
  txId: string,
  glAccountId: string,
  category: string,
  vatCode?: string
): Promise<void> {
  try {
    // Get the transaction description
    const txRows = (await sql`
      SELECT description FROM bank_transactions WHERE id = ${txId}::UUID
    `) as Row[];

    if (txRows.length === 0) return;

    const description = String(txRows[0].description || '').trim();
    if (description.length < 3) return;

    // Extract a clean pattern from the description
    // Remove trailing numbers, dates, and references to get the merchant/payee name
    const pattern = extractLearningPattern(description);
    if (!pattern || pattern.length < 3) return;

    // Check if we already have this pattern
    const existing = (await sql`
      SELECT id, usage_count FROM categorization_patterns
      WHERE UPPER(pattern) = ${pattern.toUpperCase()}
        AND source = 'learned'
      LIMIT 1
    `) as Row[];

    if (existing.length > 0) {
      // Update existing pattern — increase confidence with use
      const newCount = Number(existing[0].usage_count) + 1;
      const newConfidence = Math.min(0.95, 0.60 + newCount * 0.05);
      await sql`
        UPDATE categorization_patterns
        SET gl_account_id = ${glAccountId}::UUID,
            category = ${category},
            vat_code = ${vatCode || 'standard'},
            usage_count = ${newCount},
            confidence = ${newConfidence},
            last_used_at = NOW()
        WHERE id = ${existing[0].id}::UUID
      `;
    } else {
      // Create new learned pattern
      await sql`
        INSERT INTO categorization_patterns (pattern, match_type, gl_account_id, category, vat_code, confidence, usage_count, last_used_at, source)
        VALUES (${pattern}, 'contains', ${glAccountId}::UUID, ${category}, ${vatCode || 'standard'}, 0.65, 1, NOW(), 'learned')
      `;
    }

    log.info('Learned categorization pattern', { pattern, category, glAccountId }, 'accounting');
  } catch (err) {
    log.error('Failed to learn from allocation', { txId, error: err }, 'accounting');
    // Non-critical: don't throw — learning failures should not break allocation flow
  }
}

/**
 * Extract a clean pattern from a bank transaction description.
 * Strips trailing reference numbers, dates, card numbers, etc.
 */
function extractLearningPattern(description: string): string {
  let clean = description.toUpperCase();

  // Remove common suffixes: card numbers, dates, reference numbers
  clean = clean.replace(/\b\d{4}\*+\d{4}\b/g, '');      // Card number masks
  clean = clean.replace(/\b\d{2}\/\d{2}\/\d{2,4}\b/g, ''); // Dates
  clean = clean.replace(/\b\d{6,}\b/g, '');               // Long number sequences
  clean = clean.replace(/\bREF\s*:?\s*\S+/gi, '');        // REF: xxx
  clean = clean.replace(/\bPOS\b/g, '');                   // POS prefix
  clean = clean.replace(/\bPURCHASE\b/g, '');              // PURCHASE label

  // Trim and collapse whitespace
  clean = clean.replace(/\s+/g, ' ').trim();

  // Take the first meaningful part (usually merchant name)
  const parts = clean.split(/\s{2,}/);
  return parts[0]?.trim() || clean;
}

// ── Bulk categorize ──────────────────────────────────────────────────────────

export async function bulkCategorize(companyId: string, 
  transactionIds: string[]
): Promise<BulkCategorizationResult> {
  if (transactionIds.length === 0) {
    return { categorized: 0, skipped: 0, results: [] };
  }

  // Fetch all requested transactions
  const txRows = (await sql`
    SELECT id, description, amount, reference
    FROM bank_transactions
    WHERE id = ANY(${transactionIds}::UUID[])
      AND status IN ('imported', 'allocated')
  `) as Row[];

  let categorized = 0;
  let skipped = 0;
  const results: BulkCategorizationResult['results'] = [];

  for (const tx of txRows) {
    const txId = String(tx.id);
    const input: CategorizationInput = {
      description: String(tx.description || ''),
      amount: Number(tx.amount),
      reference: tx.reference ? String(tx.reference) : undefined,
    };

    const result = await categorizeBankTransaction('', input);

    if (result) {
      // Write suggestion back to the transaction
      await sql`
        UPDATE bank_transactions SET
          suggested_gl_account_id = COALESCE(${result.glAccountId || null}::UUID, suggested_gl_account_id),
          suggested_category = COALESCE(${result.category || null}, suggested_category),
          suggested_vat_code = COALESCE(${result.vatCode || null}, suggested_vat_code),
          suggested_confidence = ${result.confidence}
        WHERE id = ${txId}::UUID
          AND suggested_gl_account_id IS NULL
      `;
      categorized++;
      results.push({ transactionId: txId, result });
    } else {
      skipped++;
      results.push({ transactionId: txId, result: null });
    }
  }

  log.info('Bulk smart categorization complete', { categorized, skipped, total: txRows.length }, 'accounting');

  return { categorized, skipped, results };
}

// ── Categorize all uncategorized transactions for a bank account ──────────────

export async function smartCategorizeForAccount(companyId: string, 
  bankAccountId: string
): Promise<BulkCategorizationResult> {
  // Get all uncategorized transactions for this bank account
  const txRows = (await sql`
    SELECT id FROM bank_transactions
    WHERE bank_account_id = ${bankAccountId}::UUID
      AND status IN ('imported', 'allocated')
      AND suggested_gl_account_id IS NULL
      AND suggested_category IS NULL
    ORDER BY transaction_date DESC
    LIMIT 500
  `) as Row[];

  const ids = txRows.map((r: Row) => String(r.id));
  return bulkCategorize('', ids);
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 2
 * Supplier Invoice Service
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import { createJournalEntry, postJournalEntry } from './journalEntryService';
import { getSystemAccount, getSystemAccountId } from './systemAccountResolver';
import { validateThreeWayMatch } from '../utils/threeWayMatch';
import type {
  SupplierInvoice,
  SupplierInvoiceItem,
  SupplierInvoiceCreateInput,
  SupplierInvoiceStatus,
  InvoiceMatchStatus,
} from '../types/ap.types';
import type { JournalLineInput, VatType } from '../types/gl.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

interface InvoiceFilters {
  status?: SupplierInvoiceStatus;
  supplierId?: number;
  matchStatus?: InvoiceMatchStatus;
  limit?: number;
  offset?: number;
}

export async function getSupplierInvoices(companyId: string, filters?: InvoiceFilters): Promise<{
  invoices: SupplierInvoice[];
  total: number;
}> {
  try {
    const limit = filters?.limit || 50;
    const offset = filters?.offset || 0;
    let rows: Row[];
    let countRows: Row[];

    // NOTE: purchase_orders table is not available in standalone accounting app.
    // po_number is returned as NULL; purchase_order_id column is kept for data integrity.
    if (filters?.status && filters?.supplierId) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.deleted_at IS NULL
          AND si.status = ${filters.status} AND si.supplier_id = ${filters.supplierId}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE deleted_at IS NULL
          AND status = ${filters.status} AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else if (filters?.status) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.deleted_at IS NULL
          AND si.status = ${filters.status}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE deleted_at IS NULL AND status = ${filters.status}
      `) as Row[];
    } else if (filters?.supplierId) {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.deleted_at IS NULL
          AND si.supplier_id = ${filters.supplierId}
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices
        WHERE deleted_at IS NULL AND supplier_id = ${filters.supplierId}
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
        FROM supplier_invoices si
        LEFT JOIN suppliers s ON s.id = si.supplier_id
        WHERE si.deleted_at IS NULL
        ORDER BY si.invoice_date DESC LIMIT ${limit} OFFSET ${offset}
      `) as Row[];
      countRows = (await sql`
        SELECT COUNT(*) AS cnt FROM supplier_invoices WHERE deleted_at IS NULL
      `) as Row[];
    }

    return { invoices: rows.map(mapInvoiceRow), total: Number(countRows[0]!.cnt) };
  } catch (err) {
    log.error('Failed to get supplier invoices', { error: err }, 'accounting');
    throw err;
  }
}

export async function getSupplierInvoiceById(companyId: string, 
  id: string
): Promise<(SupplierInvoice & { items: SupplierInvoiceItem[] }) | null> {
  try {
    const rows = (await sql`
      SELECT si.*, s.name AS supplier_name, NULL::text AS po_number
      FROM supplier_invoices si
      LEFT JOIN suppliers s ON s.id = si.supplier_id
      WHERE si.id = ${id}
    `) as Row[];
    if (rows.length === 0) return null;

    const itemRows = (await sql`
      SELECT sii.*, a.account_code, a.account_name
      FROM supplier_invoice_items sii
      LEFT JOIN gl_accounts a ON a.id = sii.gl_account_id
      WHERE sii.supplier_invoice_id = ${id}
      ORDER BY sii.created_at
    `) as Row[];

    return { ...mapInvoiceRow(rows[0]!), items: itemRows.map(mapItemRow) };
  } catch (err) {
    log.error('Failed to get supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function createSupplierInvoice(companyId: string, 
  input: SupplierInvoiceCreateInput,
  userId: string
): Promise<SupplierInvoice> {
  try {
    const invoiceTaxRate = input.taxRate ?? 15;
    let subtotal = 0;
    let totalTax = 0;

    const computedItems = input.items.map(item => {
      const lineTotal = Math.round(item.quantity * item.unitPrice * 100) / 100;
      const itemTaxRate = item.taxRate ?? invoiceTaxRate;
      const itemTax = Math.round(lineTotal * itemTaxRate / 100 * 100) / 100;
      subtotal += lineTotal;
      totalTax += itemTax;
      return { ...item, lineTotal, taxAmount: itemTax, taxRate: itemTaxRate };
    });

    subtotal = Math.round(subtotal * 100) / 100;
    totalTax = Math.round(totalTax * 100) / 100;
    const totalAmount = subtotal + totalTax;

    const dueDate = input.dueDate || calculateDueDate(input.invoiceDate, input.paymentTerms);

    const invoiceRow = await withTransaction(async (tx) => {
      const rows = (await tx`
        INSERT INTO supplier_invoices (
          invoice_number, supplier_id, purchase_order_id, grn_id,
          invoice_date, due_date, subtotal, tax_rate, tax_amount,
          total_amount, payment_terms, reference, project_id,
          cost_center_id, notes, created_by
        ) VALUES (
          ${input.invoiceNumber}, ${input.supplierId},
          ${input.purchaseOrderId || null}, ${input.grnId || null},
          ${input.invoiceDate}, ${dueDate || null},
          ${subtotal}, ${invoiceTaxRate}, ${totalTax}, ${totalAmount},
          ${input.paymentTerms || null}, ${input.reference || null},
          ${input.projectId || null}, ${input.costCenterId || null},
          ${input.notes || null}, ${userId}::UUID
        ) RETURNING *
      `) as Row[];

      const invoiceId = String(rows[0]!.id);

      for (const item of computedItems) {
        await tx`
          INSERT INTO supplier_invoice_items (
            supplier_invoice_id, po_item_id, description, quantity,
            unit_price, tax_rate, tax_amount, line_total,
            gl_account_id, project_id, cost_center_id, vat_classification
          ) VALUES (
            ${invoiceId}::UUID, ${item.poItemId || null}, ${item.description},
            ${item.quantity}, ${item.unitPrice}, ${item.taxRate},
            ${item.taxAmount}, ${item.lineTotal},
            ${item.glAccountId || null}, ${item.projectId || null},
            ${item.costCenterId || null},
            ${item.vatClassification || (item.taxRate > 0 ? 'standard' : 'zero_rated')}
          )
        `;
      }

      return rows[0] as Row;
    });

    log.info('Created supplier invoice', { invoiceId: String(invoiceRow.id), invoiceNumber: input.invoiceNumber }, 'accounting');
    return mapInvoiceRow(invoiceRow);
  } catch (err) {
    log.error('Failed to create supplier invoice', { error: err }, 'accounting');
    throw err;
  }
}

export async function approveSupplierInvoice(companyId: string, 
  id: string,
  userId: string
): Promise<SupplierInvoice> {
  try {
    const invoice = await getSupplierInvoiceById('', id);
    if (!invoice) throw new Error(`Supplier invoice ${id} not found`);
    if (invoice.status !== 'draft' && invoice.status !== 'pending_approval') {
      throw new Error(`Cannot approve invoice with status: ${invoice.status}`);
    }

    // Auto-post GL entry: DR Expense + DR VAT Input, CR Accounts Payable
    const apAccount = await getSystemAccount('payable');
    const vatAccount = await getSystemAccount('vat_input');

    const defaultExpenseAccount = await getSystemAccount('default_expense');
    const lines: JournalLineInput[] = [];

    for (const item of invoice.items) {
      const glAccountId = item.glAccountId || defaultExpenseAccount.id;
      if (!glAccountId) throw new Error('No GL account for invoice item and no default expense account');
      lines.push({
        glAccountId,
        debit: item.lineTotal,
        credit: 0,
        description: item.description,
        projectId: item.projectId || invoice.projectId,
        costCenterId: item.costCenterId || invoice.costCenterId,
      });
    }

    if (invoice.taxAmount > 0) {
      lines.push({
        glAccountId: vatAccount.id,
        debit: invoice.taxAmount,
        credit: 0,
        description: `VAT on ${invoice.invoiceNumber}`,
        vatType: 'standard',
      });
    }

    lines.push({
      glAccountId: apAccount.id,
      debit: 0,
      credit: invoice.totalAmount,
      description: `AP: ${invoice.invoiceNumber}`,
    });

    const journalEntry = await createJournalEntry('', {
      entryDate: invoice.invoiceDate,
      description: `Supplier invoice ${invoice.invoiceNumber}`,
      source: 'auto_supplier_invoice',
      sourceDocumentId: id,
      lines,
    }, userId);

    await postJournalEntry('', journalEntry.id, userId);

    const updated = (await sql`
      UPDATE supplier_invoices
      SET status = 'approved', approved_by = ${userId}::UUID, approved_at = NOW(),
          gl_journal_entry_id = ${journalEntry.id}::UUID
      WHERE id = ${id}
      RETURNING *
    `) as Row[];

    log.info('Approved supplier invoice', { id, journalEntryId: journalEntry.id }, 'accounting');
    return mapInvoiceRow(updated[0]!);
  } catch (err) {
    log.error('Failed to approve supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function cancelSupplierInvoice(companyId: string, id: string): Promise<SupplierInvoice> {
  try {
    const invoice = await getSupplierInvoiceById('', id);
    if (!invoice) throw new Error(`Supplier invoice ${id} not found`);
    if (invoice.status === 'paid' || invoice.status === 'partially_paid') {
      throw new Error('Cannot cancel invoice with payments');
    }
    const rows = (await sql`
      UPDATE supplier_invoices SET status = 'cancelled' WHERE id = ${id} RETURNING *
    `) as Row[];
    return mapInvoiceRow(rows[0]!);
  } catch (err) {
    log.error('Failed to cancel supplier invoice', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function performThreeWayMatch(companyId: string, invoiceId: string) {
  try {
    const invoice = await getSupplierInvoiceById('', invoiceId);
    if (!invoice) throw new Error(`Invoice ${invoiceId} not found`);
    if (!invoice.purchaseOrderId) throw new Error('Invoice has no linked PO');

    const poItems = (await sql`
      SELECT * FROM po_items WHERE purchase_order_id = ${invoice.purchaseOrderId}
    `) as Row[];

    const grnItems = invoice.grnId
      ? ((await sql`
          SELECT * FROM grn_items WHERE grn_id = ${invoice.grnId}
        `) as Row[])
      : [];

    const results = invoice.items.map(item => {
      const poItem = item.poItemId ? poItems.find((p: Row) => String(p.id) === item.poItemId) : null;
      const grnItem = poItem ? grnItems.find((g: Row) => String(g.po_item_id) === String(poItem.id)) : null;

      return {
        itemDescription: item.description,
        match: validateThreeWayMatch({
          poQuantity: poItem ? Number(poItem.quantity_ordered) : 0,
          poUnitPrice: poItem ? Number(poItem.unit_price) : 0,
          grnQuantityReceived: grnItem ? Number(grnItem.quantity_received) : 0,
          invoiceQuantity: item.quantity,
          invoiceUnitPrice: item.unitPrice,
        }),
      };
    });

    const overallStatus = results.every(r => r.match.status === 'fully_matched')
      ? 'fully_matched'
      : results.some(r => r.match.status === 'po_matched') ? 'po_matched'
      : results.some(r => r.match.status === 'grn_matched') ? 'grn_matched'
      : 'unmatched';

    await sql`
      UPDATE supplier_invoices SET match_status = ${overallStatus} WHERE id = ${invoiceId}
    `;

    return { invoiceId, matchStatus: overallStatus, itemResults: results };
  } catch (err) {
    log.error('Failed to perform 3-way match', { invoiceId, error: err }, 'accounting');
    throw err;
  }
}

function calculateDueDate(invoiceDate: string, paymentTerms?: string): string | null {
  if (!paymentTerms) return null;
  const match = paymentTerms.match(/net(\d+)/i);
  if (!match) return null;
  const date = new Date(invoiceDate);
  date.setDate(date.getDate() + Number(match[1]));
  return date.toISOString().split('T')[0]!;
}

function mapInvoiceRow(row: Row): SupplierInvoice {
  return {
    id: String(row.id),
    invoiceNumber: String(row.invoice_number),
    supplierId: String(row.supplier_id),
    purchaseOrderId: row.purchase_order_id ? String(row.purchase_order_id) : undefined,
    grnId: row.grn_id ? String(row.grn_id) : undefined,
    invoiceDate: String(row.invoice_date),
    dueDate: row.due_date ? String(row.due_date) : undefined,
    receivedDate: row.received_date ? String(row.received_date) : undefined,
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    amountPaid: Number(row.amount_paid),
    balance: Number(row.balance),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    currency: String(row.currency),
    reference: row.reference ? String(row.reference) : undefined,
    status: String(row.status) as SupplierInvoice['status'],
    matchStatus: String(row.match_status) as SupplierInvoice['matchStatus'],
    projectId: row.project_id ? String(row.project_id) : undefined,
    costCenterId: row.cost_center_id ? String(row.cost_center_id) : undefined,
    glJournalEntryId: row.gl_journal_entry_id ? String(row.gl_journal_entry_id) : undefined,
    sageInvoiceId: row.sage_invoice_id ? String(row.sage_invoice_id) : undefined,
    notes: row.notes ? String(row.notes) : undefined,
    createdBy: String(row.created_by),
    approvedBy: row.approved_by ? String(row.approved_by) : undefined,
    approvedAt: row.approved_at ? String(row.approved_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    supplierName: row.supplier_name ? String(row.supplier_name) : undefined,
    poNumber: row.po_number ? String(row.po_number) : undefined,
  };
}

function mapItemRow(row: Row): SupplierInvoiceItem {
  return {
    id: String(row.id),
    supplierInvoiceId: String(row.supplier_invoice_id),
    poItemId: row.po_item_id ? String(row.po_item_id) : undefined,
    description: String(row.description),
    quantity: Number(row.quantity),
    unitPrice: Number(row.unit_price),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    lineTotal: Number(row.line_total),
    glAccountId: row.gl_account_id ? String(row.gl_account_id) : undefined,
    projectId: row.project_id ? String(row.project_id) : undefined,
    costCenterId: row.cost_center_id ? String(row.cost_center_id) : undefined,
    vatClassification: row.vat_classification ? String(row.vat_classification) as VatType : undefined,
    createdAt: String(row.created_at),
  };
}

