/**
 * Approval Workflow Service
 * Configurable approval rules for financial documents.
 * Checks if documents require approval before processing.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

// ── Types ────────────────────────────────────────────────────────────────────

export type DocumentType = 'customer_invoice' | 'supplier_invoice' | 'payment' | 'journal_entry' | 'credit_note';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected' | 'cancelled';

export interface ApprovalRule {
  id: string;
  name: string;
  documentType: DocumentType;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
  priority: number;
  createdAt: string;
}

export interface ApprovalRequest {
  id: string;
  ruleId: string;
  ruleName?: string;
  documentType: DocumentType;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: ApprovalStatus;
  requestedBy: string;
  requestedByName?: string;
  requestedAt: string;
  decidedBy: string | null;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

export interface ApprovalCheckResult {
  requiresApproval: boolean;
  matchedRule: ApprovalRule | null;
  existingRequest: ApprovalRequest | null;
}

// ── Rule CRUD ────────────────────────────────────────────────────────────────

export async function listRules(companyId?: string): Promise<ApprovalRule[]> {
  if (!companyId) return [];
  const rows = (await sql`
    SELECT * FROM approval_rules WHERE company_id = ${companyId} ORDER BY priority ASC, name ASC
  `) as Row[];
  return rows.map(mapRule);
}

export async function createRule(companyId: string, input: {
  name: string;
  documentType: DocumentType;
  conditionField?: string;
  conditionOperator?: string;
  conditionValue?: number;
  approverRole?: string;
}): Promise<ApprovalRule> {
  const rows = (await sql`
    INSERT INTO approval_rules (company_id, name, document_type, condition_field, condition_operator, condition_value, approver_role)
    VALUES (
      ${companyId}, ${input.name}, ${input.documentType},
      ${input.conditionField || 'total'}, ${input.conditionOperator || 'greater_than'},
      ${input.conditionValue || 0}, ${input.approverRole || 'admin'}
    ) RETURNING *
  `) as Row[];
  log.info('Created approval rule', { id: rows[0].id, name: input.name }, 'accounting');
  return mapRule(rows[0]);
}

export async function updateRule(companyId: string, id: string, input: Partial<{
  name: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
}>): Promise<ApprovalRule> {
  const rows = (await sql`
    UPDATE approval_rules SET
      name = COALESCE(${input.name ?? null}, name),
      condition_field = COALESCE(${input.conditionField ?? null}, condition_field),
      condition_operator = COALESCE(${input.conditionOperator ?? null}, condition_operator),
      condition_value = COALESCE(${input.conditionValue ?? null}, condition_value),
      approver_role = COALESCE(${input.approverRole ?? null}, approver_role),
      is_active = COALESCE(${input.isActive ?? null}, is_active),
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Rule ${id} not found`);
  return mapRule(rows[0]);
}

export async function deleteRule(companyId: string, id: string): Promise<void> {
  await sql`DELETE FROM approval_rules WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

// ── Approval Check ───────────────────────────────────────────────────────────

/** Check if a document requires approval based on active rules */
export async function checkApproval(
  companyId: string,
  documentType: DocumentType,
  documentId: string,
  amount: number
): Promise<ApprovalCheckResult> {
  // Check for existing pending request
  const existing = (await sql`
    SELECT ar.*, rl.name AS rule_name
    FROM approval_requests ar
    LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
    WHERE ar.company_id = ${companyId}
      AND ar.document_type = ${documentType}
      AND ar.document_id = ${documentId}::UUID
      AND ar.status = 'pending'
    LIMIT 1
  `) as Row[];

  if (existing.length > 0) {
    return {
      requiresApproval: true,
      matchedRule: null,
      existingRequest: mapRequest(existing[0]),
    };
  }

  // Find matching active rules
  const rules = (await sql`
    SELECT * FROM approval_rules
    WHERE company_id = ${companyId}
      AND document_type = ${documentType}
      AND is_active = true
    ORDER BY priority ASC
  `) as Row[];

  for (const rule of rules) {
    const r = mapRule(rule);
    let matches = false;

    switch (r.conditionOperator) {
      case 'any':
        matches = true;
        break;
      case 'greater_than':
        matches = amount > r.conditionValue;
        break;
      case 'greater_equal':
        matches = amount >= r.conditionValue;
        break;
    }

    if (matches) {
      return {
        requiresApproval: true,
        matchedRule: r,
        existingRequest: null,
      };
    }
  }

  return { requiresApproval: false, matchedRule: null, existingRequest: null };
}

// ── Approval Requests ────────────────────────────────────────────────────────

/** Create an approval request for a document */
export async function requestApproval(companyId: string, input: {
  ruleId: string;
  documentType: DocumentType;
  documentId: string;
  documentReference?: string;
  amount?: number;
  requestedBy: string;
}): Promise<ApprovalRequest> {
  const rows = (await sql`
    INSERT INTO approval_requests (company_id, rule_id, document_type, document_id, document_reference, amount, requested_by)
    VALUES (
      ${companyId}, ${input.ruleId}::UUID, ${input.documentType}, ${input.documentId}::UUID,
      ${input.documentReference || null}, ${input.amount || null}, ${input.requestedBy}::UUID
    ) RETURNING *
  `) as Row[];
  log.info('Approval requested', {
    id: rows[0].id,
    documentType: input.documentType,
    documentId: input.documentId,
  }, 'accounting');
  return mapRequest(rows[0]);
}

/** List approval requests with optional status filter */
export async function listRequests(companyId: string, status?: ApprovalStatus): Promise<ApprovalRequest[]> {
  const rows = status
    ? (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by::TEXT
        LEFT JOIN users u2 ON u2.id = ar.decided_by::TEXT
        WHERE ar.company_id = ${companyId} AND ar.status = ${status}
        ORDER BY ar.created_at DESC
      `) as Row[]
    : (await sql`
        SELECT ar.*, rl.name AS rule_name,
               u1.first_name || ' ' || u1.last_name AS requested_by_name,
               u2.first_name || ' ' || u2.last_name AS decided_by_name
        FROM approval_requests ar
        LEFT JOIN approval_rules rl ON rl.id = ar.rule_id
        LEFT JOIN users u1 ON u1.id = ar.requested_by::TEXT
        LEFT JOIN users u2 ON u2.id = ar.decided_by::TEXT
        WHERE ar.company_id = ${companyId}
        ORDER BY ar.created_at DESC
      `) as Row[];
  return rows.map(mapRequest);
}

/** Approve or reject a request */
export async function decideRequest(companyId: string, 
  requestId: string,
  decision: 'approved' | 'rejected',
  decidedBy: string,
  notes?: string
): Promise<ApprovalRequest> {
  const rows = (await sql`
    UPDATE approval_requests SET
      status = ${decision},
      decided_by = ${decidedBy}::UUID,
      decided_at = NOW(),
      decision_notes = ${notes || null}
    WHERE id = ${requestId}::UUID AND company_id = ${companyId} AND status = 'pending'
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error(`Request ${requestId} not found or already decided`);
  log.info('Approval decided', { id: requestId, decision }, 'accounting');
  return mapRequest(rows[0]);
}

/** Get pending approval count for dashboard badge */
export async function getPendingCount(companyId?: string): Promise<number> {
  if (!companyId) return 0;
  const rows = (await sql`
    SELECT COUNT(*) AS count FROM approval_requests WHERE company_id = ${companyId} AND status = 'pending'
  `) as Row[];
  return Number(rows[0]?.count ?? 0);
}

// ── Mappers ──────────────────────────────────────────────────────────────────

function mapRule(r: Row): ApprovalRule {
  return {
    id: r.id,
    name: r.name,
    documentType: r.document_type,
    conditionField: r.condition_field,
    conditionOperator: r.condition_operator,
    conditionValue: Number(r.condition_value),
    approverRole: r.approver_role,
    isActive: r.is_active,
    priority: r.priority,
    createdAt: r.created_at,
  };
}

function mapRequest(r: Row): ApprovalRequest {
  return {
    id: r.id,
    ruleId: r.rule_id,
    ruleName: r.rule_name || undefined,
    documentType: r.document_type,
    documentId: r.document_id,
    documentReference: r.document_reference,
    amount: r.amount ? Number(r.amount) : null,
    status: r.status,
    requestedBy: r.requested_by,
    requestedByName: r.requested_by_name || undefined,
    requestedAt: r.requested_at,
    decidedBy: r.decided_by,
    decidedByName: r.decided_by_name || undefined,
    decidedAt: r.decided_at,
    decisionNotes: r.decision_notes,
  };
}

/**
 * Data Export Service
 * Exports all major accounting data for a company as structured JSON.
 * Future enhancement: ZIP/CSV generation.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface CompanyExportResult {
  filename: string;
  data: Record<string, unknown[]>;
}

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(v: unknown): string | null {
  if (v == null) return null;
  if (v instanceof Date) return v.toISOString();
  return v as string;
}

function normalizeRows(rows: Row[]): Record<string, unknown>[] {
  return rows.map((r) => {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(r)) {
      out[k] = v instanceof Date ? toIso(v) : v;
    }
    return out;
  });
}

export async function exportCompanyData(
  companyId: string
): Promise<CompanyExportResult> {
  try {
    const [companyRows, accountRows, customerRows, supplierRows, invoiceRows, journalRows, bankRows] =
      await Promise.all([
        sql`SELECT * FROM companies WHERE id = ${companyId}`,

        sql`SELECT * FROM gl_accounts
            WHERE company_id = ${companyId}
            ORDER BY code`,

        sql`SELECT * FROM customers
            WHERE company_id = ${companyId}
            ORDER BY name`,

        sql`SELECT * FROM suppliers
            WHERE company_id = ${companyId}
            ORDER BY name`,

        sql`SELECT * FROM invoices
            WHERE company_id = ${companyId}
            ORDER BY invoice_date DESC`,

        sql`SELECT * FROM gl_journal_entries
            WHERE company_id = ${companyId}
            ORDER BY entry_date DESC`,

        sql`SELECT * FROM bank_transactions
            WHERE company_id = ${companyId}
            ORDER BY transaction_date DESC`,
      ]);

    const companyName =
      (companyRows[0]?.name as string | undefined) ?? companyId;

    const dateStr = new Date().toISOString().split('T')[0];
    const safeName = companyName.replace(/[^a-zA-Z0-9-_]/g, '-').toLowerCase();
    const filename = `export-${safeName}-${dateStr}.json`;

    return {
      filename,
      data: {
        company:         normalizeRows(companyRows),
        accounts:        normalizeRows(accountRows),
        customers:       normalizeRows(customerRows),
        suppliers:       normalizeRows(supplierRows),
        invoices:        normalizeRows(invoiceRows),
        journal_entries: normalizeRows(journalRows),
        bank_transactions: normalizeRows(bankRows),
      },
    };
  } catch (err) {
    log.error('exportCompanyData failed', { companyId, error: err }, 'dataExportService');
    throw err;
  }
}

/**
 * Feature Flag Service
 * Resolves effective features per company based on global flags, plan features,
 * and company-level overrides. Used by both the admin platform and feature gating middleware.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  FeatureFlag,
  CompanyEffectiveFeature,
} from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string {
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

export async function listFeatureFlags(): Promise<FeatureFlag[]> {
  const rows = await sql`
    SELECT id, code, name, description, is_global, created_at
    FROM feature_flags
    ORDER BY code ASC
  `;

  log.info(`listFeatureFlags: ${rows.length} flags`, {}, 'FeatureFlagService');

  return (rows as Row[]).map((r) => ({
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    is_global: r.is_global as boolean,
    created_at: toIso(r.created_at),
  }));
}

export async function getFeatureFlag(id: string): Promise<FeatureFlag | null> {
  const rows = await sql`
    SELECT id, code, name, description, is_global, created_at
    FROM feature_flags
    WHERE id = ${id}
    LIMIT 1
  `;

  if (rows.length === 0) return null;
  const r = rows[0] as Row;

  return {
    id: r.id as string,
    code: r.code as string,
    name: r.name as string,
    description: r.description as string | null,
    is_global: r.is_global as boolean,
    created_at: toIso(r.created_at),
  };
}

export async function updateFeatureFlag(
  id: string,
  data: { name?: string; description?: string; is_global?: boolean }
): Promise<void> {
  await sql`
    UPDATE feature_flags
    SET
      name        = COALESCE(${data.name ?? null}, name),
      description = COALESCE(${data.description ?? null}, description),
      is_global   = COALESCE(${data.is_global ?? null}, is_global)
    WHERE id = ${id}
  `;

  log.info('updateFeatureFlag', { id, data }, 'FeatureFlagService');
}

export async function getCompanyEffectiveFeatures(
  companyId: string
): Promise<CompanyEffectiveFeature[]> {
  // Fetch all flags, plan memberships and overrides in parallel
  const [flagRows, planRows, overrideRows] = await Promise.all([
    sql`
      SELECT id, code, name, is_global
      FROM feature_flags
      ORDER BY code ASC
    `,
    sql`
      SELECT pf.feature_id
      FROM plan_features pf
      JOIN companies c ON c.plan_id = pf.plan_id
      WHERE c.id = ${companyId}
    `,
    sql`
      SELECT feature_id, enabled
      FROM company_feature_overrides
      WHERE company_id = ${companyId}
    `,
  ]);

  const planFeatureIds = new Set(
    (planRows as Row[]).map((r) => r.feature_id as string)
  );

  const overrideMap = new Map<string, boolean>(
    (overrideRows as Row[]).map((r) => [r.feature_id as string, r.enabled as boolean])
  );

  return (flagRows as Row[]).map((r) => {
    const id = r.id as string;
    const isGlobal = r.is_global as boolean;
    const inPlan = planFeatureIds.has(id);
    const override = overrideMap.get(id);

    let enabled: boolean;
    let source: 'global' | 'plan' | 'override';

    if (override !== undefined) {
      // Override always wins
      enabled = override;
      source = 'override';
    } else if (isGlobal) {
      enabled = true;
      source = 'global';
    } else if (inPlan) {
      enabled = true;
      source = 'plan';
    } else {
      enabled = false;
      source = 'plan';
    }

    return {
      code: r.code as string,
      name: r.name as string,
      enabled,
      source,
    };
  });
}

export async function setCompanyFeatureOverride(
  companyId: string,
  featureId: string,
  enabled: boolean,
  reason: string,
  setBy: string
): Promise<void> {
  await sql`
    INSERT INTO company_feature_overrides
      (company_id, feature_id, enabled, reason, set_by, created_at)
    VALUES
      (${companyId}, ${featureId}, ${enabled}, ${reason}, ${setBy}, NOW())
    ON CONFLICT (company_id, feature_id)
    DO UPDATE SET
      enabled    = EXCLUDED.enabled,
      reason     = EXCLUDED.reason,
      set_by     = EXCLUDED.set_by,
      created_at = NOW()
  `;

  log.info('setCompanyFeatureOverride', { companyId, featureId, enabled }, 'FeatureFlagService');
}

export async function removeCompanyFeatureOverride(
  companyId: string,
  featureId: string
): Promise<void> {
  await sql`
    DELETE FROM company_feature_overrides
    WHERE company_id = ${companyId}
      AND feature_id = ${featureId}
  `;

  log.info('removeCompanyFeatureOverride', { companyId, featureId }, 'FeatureFlagService');
}

export async function hasFeature(
  companyId: string,
  featureCode: string
): Promise<boolean> {
  const rows = await sql`
    SELECT
      ff.is_global,
      EXISTS (
        SELECT 1
        FROM plan_features pf
        JOIN companies c ON c.plan_id = pf.plan_id
        WHERE c.id = ${companyId}
          AND pf.feature_id = ff.id
      ) AS in_plan,
      cfo.enabled AS override_enabled
    FROM feature_flags ff
    LEFT JOIN company_feature_overrides cfo
      ON cfo.feature_id = ff.id
      AND cfo.company_id = ${companyId}
    WHERE ff.code = ${featureCode}
    LIMIT 1
  `;

  if (rows.length === 0) return false;

  const r = rows[0] as Row;
  const overrideEnabled = r.override_enabled as boolean | null;

  // Override takes precedence
  if (overrideEnabled !== null) return overrideEnabled;
  // Then global flag
  if (r.is_global as boolean) return true;
  // Then plan membership
  return r.in_plan as boolean;
}

/**
 * Invoice Service
 * Admin invoice lifecycle for the ISAFlow Admin Platform.
 * Subscription operations are in billingService.ts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { InvoiceListItem, PaginatedResult } from '../types/admin.types';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

function toIso(value: unknown): string | null {
  if (value == null) return null;
  if (value instanceof Date) return value.toISOString();
  return value as string;
}

const ALLOWED_SORT: Record<string, string> = {
  created_at: 'i.created_at',
  due_date: 'i.due_date',
  status: 'i.status',
  total_cents: 'i.total_cents',
  company_name: 'c.name',
  invoice_number: 'i.invoice_number',
};

export async function listInvoices(filters: {
  company_id?: string;
  status?: string;
  from_date?: string;
  to_date?: string;
  search?: string;
  page?: number;
  limit?: number;
  sort_by?: string;
  sort_dir?: 'asc' | 'desc';
}): Promise<PaginatedResult<InvoiceListItem>> {
  const page = Math.max(1, filters.page ?? 1);
  const limit = Math.min(100, Math.max(1, filters.limit ?? 25));
  const offset = (page - 1) * limit;
  const sortCol = ALLOWED_SORT[filters.sort_by ?? ''] ?? 'i.created_at';
  const sortDir = filters.sort_dir === 'asc' ? sql`ASC` : sql`DESC`;
  const search = filters.search ? `%${filters.search}%` : null;

  const [countRow] = await sql`
    SELECT COUNT(*) AS total
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
  `;

  const rows = await sql`
    SELECT
      i.id, i.company_id, c.name AS company_name,
      i.invoice_number, i.status,
      i.subtotal_cents, i.tax_cents, i.total_cents, i.currency,
      i.due_date, i.paid_at, i.payment_method,
      i.created_at
    FROM admin_invoices i
    INNER JOIN companies c ON c.id = i.company_id
    WHERE (${filters.company_id ?? null}::uuid IS NULL
           OR i.company_id = ${filters.company_id ?? null}::uuid)
      AND (${filters.status ?? null}::text IS NULL
           OR i.status = ${filters.status ?? null})
      AND (${filters.from_date ?? null}::date IS NULL
           OR i.created_at::date >= ${filters.from_date ?? null}::date)
      AND (${filters.to_date ?? null}::date IS NULL
           OR i.created_at::date <= ${filters.to_date ?? null}::date)
      AND (${search}::text IS NULL
           OR c.name ILIKE ${search}
           OR i.invoice_number ILIKE ${search})
    ORDER BY ${sql.unsafe(sortCol)} ${sortDir}
    LIMIT ${limit} OFFSET ${offset}
  `;

  const total = parseInt((countRow as Row).total as string, 10);
  log.info(`listInvoices: ${rows.length} rows (page ${page})`, {}, 'InvoiceService');

  return {
    items: (rows as Row[]).map((r: Row) => ({
      id: r.id as string,
      company_id: r.company_id as string,
      company_name: r.company_name as string,
      invoice_number: r.invoice_number as string,
      status: r.status as string,
      subtotal_cents: r.subtotal_cents as number,
      tax_cents: r.tax_cents as number,
      total_cents: r.total_cents as number,
      currency: r.currency as string,
      due_date: toIso(r.due_date),
      paid_at: toIso(r.paid_at),
      payment_method: r.payment_method as string | null,
      created_at: toIso(r.created_at) ?? '',
    })),
    total,
    page,
    limit,
    total_pages: Math.ceil(total / limit),
  };
}

export async function createInvoice(data: {
  company_id: string;
  subscription_id?: string;
  subtotal_cents: number;
  tax_cents: number;
  total_cents: number;
  due_date?: string;
  line_items?: unknown[];
  notes?: string;
}): Promise<string> {
  const {
    company_id,
    subscription_id = null,
    subtotal_cents,
    tax_cents,
    total_cents,
    due_date = null,
    line_items = [],
    notes = null,
  } = data;

  // Sequential invoice number: INV-YYYYMM-XXXX
  const yyyymm = new Date().toISOString().slice(0, 7).replace('-', '');
  const prefix = `INV-${yyyymm}-`;

  const seqRows = (await sql`
    SELECT COALESCE(MAX(
      CAST(SUBSTRING(invoice_number FROM ${prefix.length + 1}) AS integer)
    ), 0) AS max_seq
    FROM admin_invoices
    WHERE invoice_number LIKE ${prefix + '%'}
  `) as Row[];
  const seq = parseInt((seqRows[0] as Row).max_seq as string, 10) + 1;
  const invoice_number = `${prefix}${String(seq).padStart(4, '0')}`;

  const rows = (await sql`
    INSERT INTO admin_invoices (
      company_id, subscription_id, invoice_number, status,
      subtotal_cents, tax_cents, total_cents, currency,
      due_date, line_items, notes, created_at
    ) VALUES (
      ${company_id}::uuid,
      ${subscription_id}::uuid,
      ${invoice_number}, 'draft',
      ${subtotal_cents}, ${tax_cents}, ${total_cents}, 'ZAR',
      ${due_date}::date,
      ${JSON.stringify(line_items)}::jsonb,
      ${notes},
      NOW()
    )
    RETURNING id
  `) as Row[];

  log.info('createInvoice', { id: (rows[0] as Row).id, invoice_number, company_id }, 'InvoiceService');
  return (rows[0] as Row).id as string;
}

export async function markInvoicePaid(
  invoiceId: string,
  paymentMethod: string
): Promise<boolean> {
  const rows = await sql`
    UPDATE admin_invoices
    SET status         = 'paid',
        paid_at        = NOW(),
        payment_method = ${paymentMethod}
    WHERE id = ${invoiceId}
      AND status IN ('sent', 'overdue')
    RETURNING id
  `;
  const updated = rows.length > 0;
  log.info('markInvoicePaid', { invoiceId, paymentMethod, updated }, 'InvoiceService');
  return updated;
}

export async function sendInvoice(invoiceId: string): Promise<void> {
  await sql`
    UPDATE admin_invoices
    SET status = 'sent'
    WHERE id   = ${invoiceId}
      AND status = 'draft'
  `;
  log.info('sendInvoice', { invoiceId }, 'InvoiceService');
}

/**
 * Approval Workflow Service
 * Configurable approval rules for financial documents.
 * Checks if documents require approval before processing.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// ── Types ────────────────────────────────────────────────────────────────────

export type DocumentType = 'customer_invoice' | 'supplier_invoice' | 'payment' | 'journal_entry' | 'credit_note';
export type ApprovalStatus = 'pending' | 'approved' | 'rejected' | 'cancelled';

export interface ApprovalRule {
  id: string;
  name: string;
  documentType: DocumentType;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
  priority: number;
  createdAt: string;
}

export interface ApprovalRequest {
  id: string;
  ruleId: string;
  ruleName?: string;
  documentType: DocumentType;
  documentId: string;
  documentReference: string | null;
  amount: number | null;
  status: ApprovalStatus;
  requestedBy: string;
  requestedByName?: string;
  requestedAt: string;
  decidedBy: string | null;
  decidedByName?: string;
  decidedAt: string | null;
  decisionNotes: string | null;
}

export interface ApprovalCheckResult {
  requiresApproval: boolean;
  matchedRule: ApprovalRule | null;
  existingRequest: ApprovalRequest | null;
}

// ── Rule CRUD ────────────────────────────────────────────────────────────────

export async function listRules(companyId?: string): Promise<ApprovalRule[]> {
  if (!companyId) return [];
  const rows = (await sql`
    SELECT * FROM approval_rules WHERE company_id = ${companyId} ORDER BY priority ASC, name ASC
  `) as Row[];
  return rows.map(mapRule);
}

export async function createRule(companyId: string, input: {
  name: string;
  documentType: DocumentType;
  conditionField?: string;
  conditionOperator?: string;
  conditionValue?: number;
  approverRole?: string;
}): Promise<ApprovalRule> {
  const rows = (await sql`
    INSERT INTO approval_rules (company_id, name, document_type, condition_field, condition_operator, condition_value, approver_role)
    VALUES (
      ${companyId}, ${input.name}, ${input.documentType},
      ${input.conditionField || 'total'}, ${input.conditionOperator || 'greater_than'},
      ${input.conditionValue || 0}, ${input.approverRole || 'admin'}
    ) RETURNING *
  `) as Row[];
  log.info('Created approval rule', { id: rows[0].id, name: input.name }, 'accounting');
  return mapRule(rows[0]);
}

export async function updateRule(companyId: string, id: string, input: Partial<{
  name: string;
  conditionField: string;
  conditionOperator: string;
  conditionValue: number;
  approverRole: string;
  isActive: boolean;
