    )
    VALUES (
      ${groupId}::UUID,
      ${input.accountCode},
      ${input.accountName},
      ${input.accountType},
      ${input.accountSubtype || null},
      ${input.parentAccountId || null},
      ${input.normalBalance || 'debit'},
      ${input.level ?? 1},
      ${input.displayOrder ?? 0}
    )
    RETURNING *
  `) as Row[];
