/**
 * Audit Trail Service
 * Field-level change history for all accounting entities.
 * logAudit is fire-and-forget — never throws.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export type AuditAction =
  | 'create'
  | 'update'
  | 'delete'
  | 'post'
  | 'reverse'
  | 'approve'
  | 'reject'
  | 'login'
  | 'export';

export interface AuditFieldChange {
  field: string;
  old: string | null;
  new: string | null;
  label: string;
}

export interface AuditChanges {
  fields: AuditFieldChange[];
  metadata?: Record<string, string>;
}

export interface AuditLogItem {
  id: string;
  companyId: string;
  userId: string;
  userEmail: string | null;
  action: AuditAction;
  entityType: string;
  entityId: string;
  entityRef: string | null;
  changes: AuditChanges | null;
  ipAddress: string | null;
  userAgent: string | null;
  sessionId: string | null;
  createdAt: string;
}

export interface LogAuditParams {
  companyId: string;
  userId: string;
  userEmail?: string;
  action: AuditAction;
  entityType: string;
  entityId: string;
  entityRef?: string;
  changes?: AuditChanges;
  ip?: string;
  userAgent?: string;
  sessionId?: string;
}

export interface AuditLogFilters {
  entityType?: string;
  entityId?: string;
  userId?: string;
  action?: string;
  dateFrom?: string;
  dateTo?: string;
  search?: string;
  limit?: number;
  offset?: number;
}

/**
 * Fire-and-forget audit log writer. Never throws — errors are swallowed
 * so audit failures never break the calling transaction.
 */
export async function logAudit(params: LogAuditParams): Promise<void> {
  try {
    const changesJson = params.changes ? JSON.stringify(params.changes) : null;
    await sql`
      INSERT INTO audit_log (
        company_id, user_id, user_email, action,
        entity_type, entity_id, entity_ref,
        changes, ip_address, user_agent, session_id
      ) VALUES (
        ${params.companyId}::UUID,
        ${params.userId},
        ${params.userEmail ?? null},
        ${params.action},
        ${params.entityType},
        ${params.entityId}::UUID,
        ${params.entityRef ?? null},
        ${changesJson}::JSONB,
        ${params.ip ?? null},
        ${params.userAgent ?? null},
        ${params.sessionId ? params.sessionId + '::UUID' : null}
      )
    `;
  } catch (err) {
    // Never surface audit errors to callers
    log.warn('Audit log write failed', { error: err, params }, 'audit-trail');
  }
}

export async function getAuditLog(
  companyId: string,
  filters: AuditLogFilters,
): Promise<{ items: AuditLogItem[]; total: number }> {
  try {
    const limit = filters.limit ?? 50;
    const offset = filters.offset ?? 0;

    // Build conditional clauses using separate queries per filter combination
    // to avoid dynamic SQL string concatenation
    const entityType = filters.entityType ?? null;
    const entityId = filters.entityId ?? null;
    const userId = filters.userId ?? null;
    const action = filters.action ?? null;
    const dateFrom = filters.dateFrom ?? null;
    const dateTo = filters.dateTo ?? null;
    const search = filters.search ? `%${filters.search}%` : null;

    const [rows, countRows] = await Promise.all([
      sql`
        SELECT *
        FROM audit_log
        WHERE company_id = ${companyId}::UUID
          AND (${entityType}::VARCHAR IS NULL OR entity_type = ${entityType})
          AND (${entityId}::UUID IS NULL OR entity_id = ${entityId}::UUID)
          AND (${userId}::VARCHAR IS NULL OR user_id = ${userId})
          AND (${action}::VARCHAR IS NULL OR action = ${action})
          AND (${dateFrom}::TIMESTAMPTZ IS NULL OR created_at >= ${dateFrom}::TIMESTAMPTZ)
          AND (${dateTo}::TIMESTAMPTZ IS NULL OR created_at <= ${dateTo}::TIMESTAMPTZ)
          AND (
            ${search}::VARCHAR IS NULL
            OR user_email ILIKE ${search}
            OR entity_ref ILIKE ${search}
            OR entity_type ILIKE ${search}
          )
        ORDER BY created_at DESC
        LIMIT ${limit} OFFSET ${offset}
      ` as Promise<Record<string, unknown>[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM audit_log
        WHERE company_id = ${companyId}::UUID
          AND (${entityType}::VARCHAR IS NULL OR entity_type = ${entityType})
          AND (${entityId}::UUID IS NULL OR entity_id = ${entityId}::UUID)
          AND (${userId}::VARCHAR IS NULL OR user_id = ${userId})
          AND (${action}::VARCHAR IS NULL OR action = ${action})
          AND (${dateFrom}::TIMESTAMPTZ IS NULL OR created_at >= ${dateFrom}::TIMESTAMPTZ)
          AND (${dateTo}::TIMESTAMPTZ IS NULL OR created_at <= ${dateTo}::TIMESTAMPTZ)
          AND (
            ${search}::VARCHAR IS NULL
            OR user_email ILIKE ${search}
            OR entity_ref ILIKE ${search}
            OR entity_type ILIKE ${search}
          )
      ` as Promise<Record<string, unknown>[]>,
    ]);

    return {
      items: rows.map(mapAuditRow),
      total: Number(countRows[0].cnt),
    };
  } catch (err) {
    log.error('Failed to get audit log', { companyId, filters, error: err }, 'audit-trail');
    throw err;
  }
}

export async function getEntityHistory(
  companyId: string,
  entityType: string,
  entityId: string,
): Promise<AuditLogItem[]> {
  try {
    const rows = (await sql`
      SELECT *
      FROM audit_log
      WHERE company_id = ${companyId}::UUID
        AND entity_type = ${entityType}
        AND entity_id = ${entityId}::UUID
      ORDER BY created_at DESC
      LIMIT 500
    `) as Record<string, unknown>[];
    return rows.map(mapAuditRow);
  } catch (err) {
    log.error('Failed to get entity history', { companyId, entityType, entityId, error: err }, 'audit-trail');
    throw err;
  }
}

/**
 * Diffs two objects and returns an array of field changes.
 * Only includes fields that actually changed.
 */
export function diffObjects(
  oldObj: Record<string, unknown>,
  newObj: Record<string, unknown>,
  fieldLabels: Record<string, string>,
): AuditFieldChange[] {
  const allKeys = new Set([...Object.keys(oldObj), ...Object.keys(newObj)]);
  const changes: AuditFieldChange[] = [];

  for (const key of allKeys) {
    const oldVal = oldObj[key];
    const newVal = newObj[key];
    const oldStr = oldVal == null ? null : String(oldVal);
    const newStr = newVal == null ? null : String(newVal);
    if (oldStr !== newStr) {
      changes.push({
        field: key,
        old: oldStr,
        new: newStr,
        label: fieldLabels[key] ?? key,
      });
    }
  }

  return changes;
}

function mapAuditRow(row: Row): AuditLogItem {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    userId: String(row.user_id),
    userEmail: row.user_email ? String(row.user_email) : null,
    action: String(row.action) as AuditAction,
    entityType: String(row.entity_type),
    entityId: String(row.entity_id),
    entityRef: row.entity_ref ? String(row.entity_ref) : null,
    changes: row.changes ?? null,
    ipAddress: row.ip_address ? String(row.ip_address) : null,
    userAgent: row.user_agent ? String(row.user_agent) : null,
    sessionId: row.session_id ? String(row.session_id) : null,
    createdAt: row.created_at instanceof Date
      ? row.created_at.toISOString()
      : String(row.created_at),
  };
}

/**
 * Payment Gateway Service — PayFast integration
 * Handles payment form generation, ITN validation, and transaction tracking.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';

type Row = Record<string, unknown>;

// ── Config ──────────────────────────────────────────────────────────────────

const PAYFAST_SANDBOX_URL = 'https://sandbox.payfast.co.za/eng/process';
const PAYFAST_LIVE_URL = 'https://www.payfast.co.za/eng/process';

// PayFast valid IP ranges (production)
const PAYFAST_IP_RANGES = [
  '197.97.145.144/28',
  '41.74.179.192/27',
  '196.12.62.128/27',
];

// Sandbox allows any IP, but we still check in production
const PAYFAST_SANDBOX_IPS = ['127.0.0.1', '::1'];

function getConfig() {
  return {
    merchantId: process.env.PAYFAST_MERCHANT_ID || '',
    merchantKey: process.env.PAYFAST_MERCHANT_KEY || '',
    passphrase: process.env.PAYFAST_PASSPHRASE || '',
    isSandbox: process.env.PAYFAST_SANDBOX === 'true',
  };
}

function getPayFastUrl(): string {
  return getConfig().isSandbox ? PAYFAST_SANDBOX_URL : PAYFAST_LIVE_URL;
}

// ── Signature Generation ────────────────────────────────────────────────────

function generateSignature(data: Record<string, string>, passphrase: string): string {
  // Sort keys alphabetically, exclude blank values and 'signature' key
  const sortedKeys = Object.keys(data)
    .filter(k => k !== 'signature' && data[k] !== '' && data[k] !== undefined && data[k] !== null)
    .sort();

  const queryString = sortedKeys
    .map(k => `${k}=${encodeURIComponent(data[k]!).replace(/%20/g, '+')}`)
    .join('&');

  const toHash = passphrase ? `${queryString}&passphrase=${encodeURIComponent(passphrase).replace(/%20/g, '+')}` : queryString;

  return crypto.createHash('md5').update(toHash).digest('hex');
}

// ── IP Validation ───────────────────────────────────────────────────────────

function ipInCidr(ip: string, cidr: string): boolean {
  const [range, bitsStr] = cidr.split('/');
  if (!range || !bitsStr) return false;
  const bits = parseInt(bitsStr, 10);

  const ipParts = ip.split('.').map(Number);
  const rangeParts = range.split('.').map(Number);

  const ipNum = ((ipParts[0]! << 24) | (ipParts[1]! << 16) | (ipParts[2]! << 8) | ipParts[3]!) >>> 0;
  const rangeNum = ((rangeParts[0]! << 24) | (rangeParts[1]! << 16) | (rangeParts[2]! << 8) | rangeParts[3]!) >>> 0;
  const mask = (~0 << (32 - bits)) >>> 0;

  return (ipNum & mask) === (rangeNum & mask);
}

function isPayFastIp(ip: string): boolean {
  const config = getConfig();
  if (config.isSandbox) return true; // Sandbox mode: accept any IP

  // Strip IPv6 prefix
  const cleanIp = ip.startsWith('::ffff:') ? ip.slice(7) : ip;

  for (const cidr of PAYFAST_IP_RANGES) {
    if (ipInCidr(cleanIp, cidr)) return true;
  }
  return PAYFAST_SANDBOX_IPS.includes(cleanIp);
}

// ── Public Functions ────────────────────────────────────────────────────────

export interface PayFastFormData {
  paymentUrl: string;
  fields: Record<string, string>;
  transactionId: string;
}

/**
 * Generate PayFast payment form data for an invoice.
 */
export async function generatePayFastForm(
  companyId: string,
  invoiceId: string,
  returnUrl: string,
  cancelUrl: string,
  notifyUrl: string,
): Promise<PayFastFormData> {
  const config = getConfig();
  if (!config.merchantId || !config.merchantKey) {
    throw new Error('PayFast merchant credentials not configured');
  }

  // Look up invoice details
  const invoices = (await sql`
    SELECT ci.id, ci.invoice_number, ci.total_amount, ci.amount_paid,
           ci.client_name, ci.status,
           c.email AS client_email
    FROM customer_invoices ci
    LEFT JOIN customers c ON c.id = ci.client_id
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
  `) as Row[];

  if (!invoices[0]) throw new Error('Invoice not found');

  const inv = invoices[0];
  const balance = Number(inv.total_amount) - Number(inv.amount_paid || 0);
  if (balance <= 0) throw new Error('Invoice is already fully paid');

  const clientEmail = inv.client_email ? String(inv.client_email) : '';
  const clientName = inv.client_name ? String(inv.client_name) : '';

  // Create payment transaction record
  const txRows = (await sql`
    INSERT INTO payment_transactions (company_id, invoice_id, gateway, amount, currency, customer_email, customer_name, status)
    VALUES (${companyId}::UUID, ${invoiceId}::UUID, 'payfast', ${balance}, 'ZAR', ${clientEmail}, ${clientName}, 'pending')
    RETURNING id
  `) as Row[];

  if (!txRows[0]) throw new Error('Failed to create payment transaction');
  const transactionId = String(txRows[0].id);

  // Build PayFast form fields
  const fields: Record<string, string> = {
    merchant_id: config.merchantId,
    merchant_key: config.merchantKey,
    return_url: returnUrl,
    cancel_url: cancelUrl,
    notify_url: notifyUrl,
    m_payment_id: transactionId,
    amount: balance.toFixed(2),
    item_name: `Invoice ${String(inv.invoice_number || '')}`.slice(0, 100),
    item_description: `Payment for invoice ${String(inv.invoice_number || '')}`.slice(0, 255),
  };

  // Add customer email if available
  if (clientEmail) {
    fields.email_address = clientEmail;
  }

  // Add customer name if available
  if (clientName) {
    const nameParts = clientName.split(' ');
    fields.name_first = (nameParts[0] || '').slice(0, 100);
    fields.name_last = (nameParts.slice(1).join(' ') || '').slice(0, 100);
  }

  // Generate signature
  fields.signature = generateSignature(fields, config.passphrase);

  log.info('PayFast form generated', { transactionId, invoiceId, amount: balance }, 'PaymentGateway');

  return {
    paymentUrl: getPayFastUrl(),
    fields,
    transactionId,
  };
}

/**
 * Handle PayFast ITN (Instant Transaction Notification).
 * Validates the notification and updates payment status.
 */
export async function handleITN(
  body: Record<string, string>,
  sourceIp: string,
): Promise<{ valid: boolean; transactionId: string | null }> {
  const config = getConfig();

  // 1. Verify source IP
  if (!isPayFastIp(sourceIp)) {
    log.error('ITN rejected: invalid source IP', { sourceIp }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 2. Verify signature
  const receivedSignature = body.signature;
  if (!receivedSignature) {
    log.error('ITN rejected: no signature', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const dataForSig = { ...body };
  delete dataForSig.signature;
  const expectedSignature = generateSignature(dataForSig, config.passphrase);

  if (receivedSignature !== expectedSignature) {
    log.error('ITN rejected: signature mismatch', { received: receivedSignature, expected: expectedSignature }, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  const transactionId = body.m_payment_id || null;
  if (!transactionId) {
    log.error('ITN rejected: no m_payment_id', {}, 'PaymentGateway');
    return { valid: false, transactionId: null };
  }

  // 3. Look up the transaction
  const txRows = (await sql`
    SELECT id, company_id, invoice_id, amount, status
    FROM payment_transactions WHERE id = ${transactionId}::UUID
  `) as Row[];

  if (!txRows[0]) {
    log.error('ITN rejected: transaction not found', { transactionId }, 'PaymentGateway');
    return { valid: false, transactionId };
  }

  const tx = txRows[0];

  // 4. Verify amount matches
  const itnAmount = parseFloat(body.amount_gross || '0');
  const expectedAmount = Number(tx.amount);
  if (Math.abs(itnAmount - expectedAmount) > 0.01) {
    log.error('ITN rejected: amount mismatch', { expected: expectedAmount, received: itnAmount }, 'PaymentGateway');
    await sql`
      UPDATE payment_transactions SET status = 'failed', error_message = 'Amount mismatch', updated_at = NOW()
      WHERE id = ${transactionId}::UUID
    `;
    return { valid: false, transactionId };
  }

  // 5. Map PayFast status to our status
  const pfStatus = (body.payment_status || '').toUpperCase();
  let newStatus: string;
  switch (pfStatus) {
    case 'COMPLETE':
      newStatus = 'completed';
      break;
    case 'FAILED':
      newStatus = 'failed';
      break;
    case 'PENDING':
      newStatus = 'processing';
      break;
    case 'CANCELLED':
      newStatus = 'cancelled';
      break;
    default:
      newStatus = 'processing';
  }

  // 6. Update transaction
  await sql`
    UPDATE payment_transactions
    SET status = ${newStatus},
        gateway_ref = ${body.pf_payment_id || ''},
        payment_method = ${body.payment_method || ''},
        paid_at = ${newStatus === 'completed' ? new Date().toISOString() : null},
        metadata = ${JSON.stringify(body)}::JSONB,
        updated_at = NOW()
    WHERE id = ${transactionId}::UUID
  `;

  // 7. If completed, update the invoice
  if (newStatus === 'completed' && tx.invoice_id) {
    await sql`
      UPDATE customer_invoices
      SET amount_paid = COALESCE(amount_paid, 0) + ${itnAmount},
          status = CASE
            WHEN COALESCE(amount_paid, 0) + ${itnAmount} >= total_amount THEN 'paid'
            ELSE 'partially_paid'
          END,
          updated_at = NOW()
      WHERE id = ${tx.invoice_id}::UUID AND company_id = ${tx.company_id}::UUID
    `;

    log.info('Invoice payment recorded via PayFast', {
      transactionId, invoiceId: tx.invoice_id, amount: itnAmount, status: 'completed',
    }, 'PaymentGateway');
  }

  log.info('ITN processed', { transactionId, pfStatus, newStatus }, 'PaymentGateway');
  return { valid: true, transactionId };
}

/**
 * Get payment transaction details.
 */
export async function getPaymentStatus(companyId: string, transactionId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE id = ${transactionId}::UUID AND company_id = ${companyId}::UUID
  `) as Row[];

  if (!rows[0]) return null;
  return mapTransaction(rows[0]);
}

/**
 * List all payment attempts for an invoice.
 */
export async function getInvoicePayments(companyId: string, invoiceId: string) {
  const rows = (await sql`
    SELECT * FROM payment_transactions
    WHERE invoice_id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
    ORDER BY created_at DESC
  `) as Row[];

  return rows.map(mapTransaction);
}

/**
 * Enable online payment for an invoice and generate a payment URL.
 */
export async function enableOnlinePayment(companyId: string, invoiceId: string): Promise<string> {
  const appUrl = process.env.NEXT_PUBLIC_APP_URL || 'http://localhost:3101';

  // Create a portal payment link token for public access
  const linkRows = (await sql`
    INSERT INTO portal_payment_links (invoice_id, client_id, amount)
    SELECT ci.id, ci.client_id, ci.total_amount - COALESCE(ci.amount_paid, 0)
    FROM customer_invoices ci
    WHERE ci.id = ${invoiceId}::UUID AND ci.company_id = ${companyId}::UUID
    RETURNING token
  `) as Row[];

  if (!linkRows[0]) throw new Error('Invoice not found or no balance due');

  const token = linkRows[0].token as string;
  const paymentUrl = `${appUrl}/portal/pay/${token}`;

  // Store the payment URL and enable online payments on the invoice
  await sql`
    UPDATE customer_invoices
    SET online_payment_enabled = true, payment_url = ${paymentUrl}, updated_at = NOW()
    WHERE id = ${invoiceId}::UUID AND company_id = ${companyId}::UUID
  `;

  log.info('Online payment enabled', { invoiceId, paymentUrl }, 'PaymentGateway');
  return paymentUrl;
}

// ── Mapper ──────────────────────────────────────────────────────────────────

interface PaymentTransaction {
  id: string;
  companyId: string;
  invoiceId: string | null;
  gateway: string;
  gatewayRef: string | null;
  amount: number;
  currency: string;
  status: string;
  customerEmail: string | null;
  customerName: string | null;
  paymentMethod: string | null;
  metadata: Record<string, unknown>;
  errorMessage: string | null;
  paidAt: string | null;
  createdAt: string;
  updatedAt: string;
}

function mapTransaction(r: Row): PaymentTransaction {
  return {
    id: String(r.id),
    companyId: String(r.company_id),
    invoiceId: r.invoice_id ? String(r.invoice_id) : null,
    gateway: String(r.gateway),
    gatewayRef: r.gateway_ref ? String(r.gateway_ref) : null,
    amount: Number(r.amount),
    currency: String(r.currency),
    status: String(r.status),
    customerEmail: r.customer_email ? String(r.customer_email) : null,
    customerName: r.customer_name ? String(r.customer_name) : null,
    paymentMethod: r.payment_method ? String(r.payment_method) : null,
    metadata: (r.metadata && typeof r.metadata === 'object' ? r.metadata : {}) as Record<string, unknown>,
    errorMessage: r.error_message ? String(r.error_message) : null,
    paidAt: r.paid_at ? String(r.paid_at) : null,
    createdAt: String(r.created_at),
    updatedAt: String(r.updated_at),
  };
}

/**
 * PRD-060: FibreFlow Accounting Module
 * Fiscal Period Service
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { FiscalPeriod, FiscalPeriodStatus } from '../types/gl.types';

type Row = Record<string, unknown>;

export async function getFiscalPeriods(companyId: string, fiscalYear?: number): Promise<FiscalPeriod[]> {
  try {
    let rows: Row[];
    if (fiscalYear) {
      rows = (await sql`
        SELECT * FROM fiscal_periods
        WHERE company_id = ${companyId} AND fiscal_year = ${fiscalYear}
        ORDER BY period_number
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT * FROM fiscal_periods WHERE company_id = ${companyId}
        ORDER BY fiscal_year DESC, period_number
      `) as Row[];
    }
    return rows.map(mapRow);
  } catch (err) {
    log.error('Failed to get fiscal periods', { fiscalYear, error: err }, 'accounting');
    throw err;
  }
}

export async function getFiscalPeriodById(companyId: string, id: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`SELECT * FROM fiscal_periods WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get fiscal period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function getCurrentFiscalPeriod(companyId: string): Promise<FiscalPeriod | null> {
  try {
    const rows = (await sql`
      SELECT * FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND start_date <= CURRENT_DATE AND end_date >= CURRENT_DATE
      LIMIT 1
    `) as Row[];
    return rows.length > 0 ? mapRow(rows[0]) : null;
  } catch (err) {
    log.error('Failed to get current fiscal period', { error: err }, 'accounting');
    throw err;
  }
}

export async function createFiscalYear(companyId: string, year: number): Promise<FiscalPeriod[]> {
  try {
    const existing = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods WHERE company_id = ${companyId} AND fiscal_year = ${year}
    `) as Row[];
    if (Number(existing[0].cnt) > 0) {
      throw new Error(`Fiscal year ${year} already exists`);
    }

    const months = [
      'January', 'February', 'March', 'April', 'May', 'June',
      'July', 'August', 'September', 'October', 'November', 'December',
    ];

    const periods: FiscalPeriod[] = [];
    for (let i = 0; i < 12; i++) {
      const periodNum = i + 1;
      const startDate = `${year}-${String(periodNum).padStart(2, '0')}-01`;
      const lastDay = new Date(year, periodNum, 0).getDate();
      const endDate = `${year}-${String(periodNum).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

      const rows = (await sql`
        INSERT INTO fiscal_periods (company_id, period_name, period_number, fiscal_year, start_date, end_date)
        VALUES (${companyId}, ${months[i]! + ' ' + year}, ${periodNum}, ${year}, ${startDate}, ${endDate})
        RETURNING *
      `) as Row[];
      periods.push(mapRow(rows[0]));
    }

    return periods;
  } catch (err) {
    log.error('Failed to create fiscal year', { year, error: err }, 'accounting');
    throw err;
  }
}

export async function closePeriod(companyId: string, id: string, userId: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(companyId, id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot close a locked period');
    if (period.status === 'closed') throw new Error('Period is already closed');

    const openPrior = (await sql`
      SELECT COUNT(*) AS cnt FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND fiscal_year = ${period.fiscalYear}
        AND period_number < ${period.periodNumber}
        AND status = 'open'
    `) as Row[];
    if (Number(openPrior[0].cnt) > 0) {
      throw new Error('Cannot close period while prior periods are still open');
    }

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'closed', closed_by = ${userId}::UUID, closed_at = NOW()
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to close period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function lockPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(companyId, id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status !== 'closed') throw new Error('Period must be closed before locking');

    const rows = (await sql`
      UPDATE fiscal_periods SET status = 'locked' WHERE id = ${id} AND company_id = ${companyId} RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to lock period', { id, error: err }, 'accounting');
    throw err;
  }
}

export async function reopenPeriod(companyId: string, id: string): Promise<FiscalPeriod> {
  try {
    const period = await getFiscalPeriodById(companyId, id);
    if (!period) throw new Error(`Fiscal period ${id} not found`);
    if (period.status === 'locked') throw new Error('Cannot reopen a locked period');
    if (period.status === 'open') throw new Error('Period is already open');

    const rows = (await sql`
      UPDATE fiscal_periods
      SET status = 'open', closed_by = NULL, closed_at = NULL
      WHERE id = ${id} AND company_id = ${companyId}
      RETURNING *
    `) as Row[];
    return mapRow(rows[0]);
  } catch (err) {
    log.error('Failed to reopen period', { id, error: err }, 'accounting');
    throw err;
  }
}

function mapRow(row: Row): FiscalPeriod {
  return {
    id: String(row.id),
    periodName: String(row.period_name),
    periodNumber: Number(row.period_number),
    fiscalYear: Number(row.fiscal_year),
    startDate: String(row.start_date),
    endDate: String(row.end_date),
    status: String(row.status) as FiscalPeriodStatus,
    closedBy: row.closed_by ? String(row.closed_by) : undefined,
    closedAt: row.closed_at ? String(row.closed_at) : undefined,
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

