/**
 * Bank Feed Service — re-export facade for backward compatibility.
 *
 * Domain logic lives in:
 *   bankFeedConnectionService.ts — OAuth, token management, connection CRUD, GraphQL
 *   bankFeedSyncService.ts       — transaction fetching, sync orchestration, history
 *
 * Environment variables required:
 *   STITCH_CLIENT_ID     — Stitch application client ID
 *   STITCH_CLIENT_SECRET — Stitch application secret
 *   STITCH_REDIRECT_URI  — OAuth callback URL
 */

// Types
export type {
  BankFeedConnection,
  StitchTransaction,
  StitchAccount,
  SyncResult,
} from './bankFeedConnectionService';

// Connection management
export {
  isConfigured,
  getAuthorizationUrl,

  clientId: string;
  email: string;
  password: string;
  name: string;
}): Promise<PortalUser> {
  const hash = await bcrypt.hash(input.password, 12);
  const rows = (await sql`
    INSERT INTO portal_access (client_id, email, password_hash, name)
    VALUES (${input.clientId}::UUID, ${input.email}, ${hash}, ${input.name})
    RETURNING *
  `) as Row[];
  log.info('Portal user created', { email: input.email }, 'portal');
  return mapPortalUser(rows[0]);
}

