/**
 * Bank Feed Sync Service — transaction fetching, sync orchestration, and history.
 *
 * Handles: token refresh, pagination via Stitch GraphQL, deduplication, sync logging.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { SyncResult, StitchTransaction } from './bankFeedConnectionService';
import {
  refreshAccessToken,
  graphqlQuery,
  encryptToken,
  decryptToken,
} from './bankFeedConnectionService';

// ── Stitch transaction fetching ───────────────────────────────────────────────

/**
 * Fetch transactions for a specific account from Stitch.
 * Supports cursor-based pagination for incremental sync.
 */
export async function fetchStitchTransactions(
  accessToken: string,
  accountId: string,
  afterCursor?: string,
  limit = 100,
): Promise<{
  transactions: StitchTransaction[];
  endCursor: string | null;
  hasNextPage: boolean;
}> {
  const query = `
    query GetTransactions($accountId: ID!, $first: Int!, $after: String) {
      node(id: $accountId) {
        ... on BankAccount {
          transactions(first: $first, after: $after) {
            pageInfo { hasNextPage endCursor }
            nodes { id amount runningBalance description reference date }
          }
        }
      }
    }
  `;

  const data = await graphqlQuery(accessToken, query, {
    accountId,
    first: limit,
    after: afterCursor || null,
  });

  const txConnection = data?.node?.transactions;
  const nodes = txConnection?.nodes ?? [];
  const pageInfo = txConnection?.pageInfo ?? {};

  return {
    transactions: nodes.map((t: Record<string, unknown>) => ({
      id: t.id as string,
      amount: Number(t.amount),
      runningBalance: t.runningBalance != null ? Number(t.runningBalance) : null,
      description: (t.description as string) || '',
      reference: (t.reference as string) || null,
      date: t.date as string,
    })),
    endCursor: (pageInfo.endCursor as string) || null,
    hasNextPage: !!pageInfo.hasNextPage,
  };
}

// ── Sync orchestration ────────────────────────────────────────────────────────

/**
 * Sync transactions for a connection.
 * Handles token refresh, pagination, and deduplication.
 */
export async function syncTransactions(connectionId: string): Promise<SyncResult> {
  const conn = (await sql`
    SELECT * FROM bank_feed_connections WHERE id = ${connectionId}::UUID AND is_active = true
  `) as Record<string, unknown>[];
  if (!conn[0]) throw new Error('Connection not found or inactive');

  const connection = conn[0];
  let accessToken = decryptToken(connection.access_token as string);
  const refreshToken = decryptToken(connection.refresh_token as string);

  // Refresh token if expired
  if (new Date(connection.token_expires_at) <= new Date()) {
    log.info('Refreshing expired token', { connectionId }, 'bank-feeds');
    const refreshed = await refreshAccessToken(refreshToken);
    accessToken = refreshed.accessToken;
    const newExpiry = new Date(Date.now() + refreshed.expiresIn * 1000).toISOString();
    await sql`
      UPDATE bank_feed_connections SET
        access_token = ${encryptToken(refreshed.accessToken)},
        refresh_token = ${encryptToken(refreshed.refreshToken)},
        token_expires_at = ${newExpiry}::TIMESTAMPTZ,
        updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
  }

  // Create sync log entry
  const logRows = (await sql`
    INSERT INTO bank_feed_sync_log (connection_id, sync_type)
    VALUES (${connectionId}::UUID, ${connection.last_sync_cursor ? 'incremental' : 'full'})
    RETURNING id
  `) as Row[];
  const syncLogId = logRows[0].id;

  await sql`
    UPDATE bank_feed_connections SET sync_status = 'syncing', updated_at = NOW()
    WHERE id = ${connectionId}::UUID
  `;

  let totalFetched = 0;
  let totalImported = 0;
  let totalSkipped = 0;
  let cursor: string | undefined = connection.last_sync_cursor || undefined;

  try {
    let hasMore = true;
    while (hasMore) {
      const result = await fetchStitchTransactions(
        accessToken,
        connection.external_account_id,
        cursor,
        100,
      );
      totalFetched += result.transactions.length;

      for (const tx of result.transactions) {
        const existing = (await sql`
          SELECT id FROM bank_transactions
          WHERE bank_account_id = ${connection.bank_account_id}::UUID
            AND bank_reference = ${tx.id}
          LIMIT 1
        `) as Row[];

        if (existing.length > 0) {
          totalSkipped++;
          continue;
        }

        await sql`
          INSERT INTO bank_transactions (
            bank_account_id, transaction_date, amount, description,
            reference, bank_reference, status, import_batch_id
          ) VALUES (
            ${connection.bank_account_id}::UUID, ${tx.date}::DATE, ${tx.amount},
            ${tx.description}, ${tx.reference || null}, ${tx.id},
            'imported', NULL
          )
        `;
        totalImported++;
      }

      cursor = result.endCursor || undefined;
      hasMore = result.hasNextPage;
    }

    await sql`
      UPDATE bank_feed_connections SET
        last_sync_at = NOW(),
        last_sync_cursor = ${cursor || null},
        sync_status = 'synced',
        sync_error = NULL,
        updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;

    await sql`
      UPDATE bank_feed_sync_log SET
        transactions_fetched = ${totalFetched},
        transactions_imported = ${totalImported},
        transactions_skipped = ${totalSkipped},
        completed_at = NOW(),
        status = 'completed'
      WHERE id = ${syncLogId}::UUID
    `;

    log.info('Bank feed sync completed', {
      connectionId, fetched: totalFetched, imported: totalImported, skipped: totalSkipped,
    }, 'bank-feeds');
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Sync failed';
    await sql`
      UPDATE bank_feed_connections SET sync_status = 'error', sync_error = ${errorMessage}, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
    await sql`
      UPDATE bank_feed_sync_log SET status = 'failed', error = ${errorMessage}, completed_at = NOW()
      WHERE id = ${syncLogId}::UUID
    `;
    log.error('Bank feed sync failed', { connectionId, error: errorMessage }, 'bank-feeds');
    throw error;
  }

  return { fetched: totalFetched, imported: totalImported, skipped: totalSkipped };
}

// ── Sync history ──────────────────────────────────────────────────────────────

/**
 * Get sync history for a connection.
 */
export async function getSyncHistory(
  connectionId: string,
  limit = 20,
): Promise<Array<{
  id: string;
  syncType: string;
  fetched: number;
  imported: number;
  skipped: number;
  startedAt: string;
  completedAt: string | null;
  status: string;
  error: string | null;
}>> {
  const rows = (await sql`
    SELECT * FROM bank_feed_sync_log
    WHERE connection_id = ${connectionId}::UUID
    ORDER BY started_at DESC
    LIMIT ${limit}
  `) as Row[];

  return rows.map((r: Row) => ({
    id: r.id,
    syncType: r.sync_type,
    fetched: r.transactions_fetched,
    imported: r.transactions_imported,
    skipped: r.transactions_skipped,
    startedAt: r.started_at,
    completedAt: r.completed_at,
    status: r.status,
    error: r.error,
  }));
}

/**
 * GL Import Service — WS-6.3 Excel Import Wizard
 * Validates and imports journal entries from spreadsheet uploads.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { VatType } from '../types/gl.types';

type Row = Record<string, unknown>;

export interface ImportRow {
  date: string;          // YYYY-MM-DD
  accountCode: string;   // Must exist in gl_accounts for this company
  description: string;
  reference?: string;
  debit: number;
  credit: number;
  vatCode?: string;
  costCentre?: string;
}

export interface ValidationResult {
  row: number;
  valid: boolean;
  errors: string[];
  warnings: string[];
}

export interface ValidationSummary {
  validations: ValidationResult[];
  validCount: number;
  errorCount: number;
  warningCount: number;
  totalDebit: number;
  totalCredit: number;
  isBalanced: boolean;
}

export interface ImportResult {
  entriesCreated: number;
  linesCreated: number;
  totalValue: number;
}

const VALID_VAT_CODES: VatType[] = [
  'standard', 'zero_rated', 'exempt', 'capital_goods',
  'export', 'imported', 'reverse_charge', 'bad_debt', 'no_vat',
];

function parseDate(dateStr: string): Date | null {
  if (!dateStr) return null;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return null;
  return d;
}

export async function validateImportRows(
  companyId: string,
  rows: ImportRow[],
): Promise<ValidationSummary> {
  try {
    // Load chart of accounts for this company
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load open fiscal periods
    const periodRows = (await sql`
      SELECT start_date, end_date
      FROM fiscal_periods
      WHERE company_id = ${companyId}::UUID
        AND status = 'open'
      ORDER BY start_date
    `) as Row[];

    // Load cost centres
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccSet = new Set<string>(ccRows.map((r: Row) => String(r.code).toLowerCase()));

    const validations: ValidationResult[] = [];
    let totalDebit = 0;
    let totalCredit = 0;
    let validCount = 0;
    let errorCount = 0;
    let warningCount = 0;

    for (let i = 0; i < rows.length; i++) {
      const row = rows[i]!;
      const errors: string[] = [];
      const warnings: string[] = [];
      const rowNum = i + 2; // 1-indexed + header row

      // Description required
      if (!row.description || row.description.trim() === '') {
        errors.push('Description is required');
      }

      // Date validation
      const parsedDate = parseDate(row.date);
      if (!parsedDate) {
        errors.push(`Invalid date: "${row.date}" — expected YYYY-MM-DD`);
      } else {
        // Check if date falls within an open fiscal period
        const inOpenPeriod = periodRows.some((p: Row) => {
          const start = new Date(String(p.start_date));
          const end = new Date(String(p.end_date));
          return parsedDate >= start && parsedDate <= end;
        });
        if (!inOpenPeriod) {
          warnings.push(`Date ${row.date} does not fall within an open fiscal period`);
        }
      }

      // Account code validation
      if (!row.accountCode || row.accountCode.trim() === '') {
        errors.push('Account code is required');
      } else if (!accountMap.has(String(row.accountCode).trim())) {
        errors.push(`Account code "${row.accountCode}" not found in chart of accounts`);
      }

      // Debit / credit validation
      const debit = Number(row.debit) || 0;
      const credit = Number(row.credit) || 0;

      if (debit < 0) errors.push('Debit cannot be negative');
      if (credit < 0) errors.push('Credit cannot be negative');

      if (debit > 0 && credit > 0) {
        errors.push('Debit and credit cannot both be greater than zero on the same line');
      }
      if (debit === 0 && credit === 0) {
        errors.push('At least one of debit or credit must be greater than zero');
      }

      // VAT code validation (optional)
      if (row.vatCode && row.vatCode.trim() !== '') {
        const code = row.vatCode.trim() as VatType;
        if (!VALID_VAT_CODES.includes(code)) {
          errors.push(
            `Invalid VAT code "${row.vatCode}". Valid codes: ${VALID_VAT_CODES.join(', ')}`,
          );
        }
      }

      // Cost centre validation (optional)
      if (row.costCentre && row.costCentre.trim() !== '') {
        if (!ccSet.has(row.costCentre.trim().toLowerCase())) {
          warnings.push(`Cost centre "${row.costCentre}" not found — will be ignored`);
        }
      }

      const valid = errors.length === 0;
      if (valid) {
        validCount++;
        totalDebit += debit;
        totalCredit += credit;
      } else {
        errorCount++;
      }
      if (warnings.length > 0) warningCount++;

      validations.push({ row: rowNum, valid, errors, warnings });
    }

    // For balanced check, only consider valid rows
    const diff = Math.abs(totalDebit - totalCredit);
    const isBalanced = diff < 0.005; // tolerance for floating point

    return {
      validations,
      validCount,
      errorCount,
      warningCount,
      totalDebit,
      totalCredit,
      isBalanced,
    };
  } catch (err) {
    log.error('Failed to validate import rows', { error: err }, 'gl-import');
    throw err;
  }
}

export async function importJournalEntries(
  companyId: string,
  rows: ImportRow[],
  userId: string,
  postImmediately: boolean,
): Promise<ImportResult> {
  try {
    // Load account code → id mapping
    const accountRows = (await sql`
      SELECT account_code, id
      FROM gl_accounts
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const accountMap = new Map<string, string>(
      accountRows.map((r: Row) => [String(r.account_code), String(r.id)]),
    );

    // Load cost centre code → id mapping
    const ccRows = (await sql`
      SELECT code, id
      FROM cost_centres
      WHERE company_id = ${companyId}::UUID
        AND is_active = true
    `) as Row[];
    const ccMap = new Map<string, string>(
      ccRows.map((r: Row) => [String(r.code).toLowerCase(), String(r.id)]),
    );

    // Group rows into journal entries: same date + same reference = one entry
    const grouped = new Map<string, ImportRow[]>();
    for (const row of rows) {
      const key = `${row.date}||${row.reference || ''}`;
      const group = grouped.get(key) ?? [];
      group.push(row);
      grouped.set(key, group);
    }

    let entriesCreated = 0;
    let linesCreated = 0;
    let totalValue = 0;
    const status = postImmediately ? 'posted' : 'draft';

    for (const [, groupRows] of grouped) {
      const firstRow = groupRows[0]!;

      // Find fiscal period for entry date
      const periodRows = (await sql`
        SELECT id FROM fiscal_periods
        WHERE company_id = ${companyId}::UUID
          AND start_date <= ${firstRow.date}::DATE
          AND end_date >= ${firstRow.date}::DATE
        LIMIT 1
      `) as Row[];
      const fiscalPeriodId = periodRows.length > 0 ? String(periodRows[0].id) : null;

      const description = firstRow.reference
        ? `${firstRow.reference}: ${firstRow.description}`
        : firstRow.description;

      const postedBy = postImmediately ? userId : null;

      const entryInsert = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, fiscal_period_id, description,
          source, created_by, status,
          posted_by, posted_at
        ) VALUES (
          ${companyId}::UUID,
          ${firstRow.date}::DATE,
          ${fiscalPeriodId}::UUID,
          ${description},
          'import',
          ${userId}::UUID,
          ${status},
          ${postedBy}::UUID,
          ${postImmediately ? sql`NOW()` : sql`NULL`}
        )
        RETURNING id
      `) as Row[];

      const entryId = String(entryInsert[0].id);
      entriesCreated++;

      for (const row of groupRows) {
        const accountId = accountMap.get(String(row.accountCode).trim());
        if (!accountId) continue; // already validated upstream

        const ccId = row.costCentre
          ? (ccMap.get(row.costCentre.trim().toLowerCase()) ?? null)
          : null;

        const vatType = (row.vatCode?.trim() as VatType) || null;

        await sql`
          INSERT INTO gl_journal_lines (
            journal_entry_id, gl_account_id, debit, credit,
            description, vat_type, cost_center_id
          ) VALUES (
            ${entryId}::UUID,
            ${accountId}::UUID,
            ${Number(row.debit) || 0},
            ${Number(row.credit) || 0},
            ${row.description},
            ${vatType},
            ${ccId}::UUID
          )
        `;

        linesCreated++;
        totalValue += Number(row.debit) || 0;
      }
    }

    log.info('Imported journal entries', {
      companyId, entriesCreated, linesCreated, totalValue, postImmediately,
    }, 'gl-import');

    return { entriesCreated, linesCreated, totalValue };
  } catch (err) {
    log.error('Failed to import journal entries', { error: err }, 'gl-import');
    throw err;
  }
}

/**
 * Recurring Invoice Service
 * Phase 1 Sage Alignment: Auto-generate customer invoices on schedule
 */

import { sql, withTransaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type {
  RecurringInvoice,
  RecurringInvoiceCreateInput,
} from '../types/ar.types';

type Row = Record<string, unknown>;

export async function getRecurringInvoices(companyId: string, filters?: {
  status?: string;
  clientId?: string;
  limit?: number;
  offset?: number;
}): Promise<{ items: RecurringInvoice[]; total: number }> {
  const limit = filters?.limit || 50;
  const offset = filters?.offset || 0;
  let rows: Row[];
  let countRows: Row[];

  if (filters?.clientId) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.client_id = ${filters.clientId}::UUID
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices
      WHERE company_id = ${companyId} AND client_id = ${filters.clientId}::UUID
    `) as Row[];
  } else if (filters?.status) {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId} AND ri.status = ${filters.status}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`
      SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId} AND status = ${filters.status}
    `) as Row[];
  } else {
    rows = (await sql`
      SELECT ri.*, c.name AS client_name
      FROM recurring_invoices ri LEFT JOIN customers c ON c.id = ri.client_id
      WHERE ri.company_id = ${companyId}
      ORDER BY ri.created_at DESC LIMIT ${limit} OFFSET ${offset}
    `) as Row[];
    countRows = (await sql`SELECT COUNT(*) AS cnt FROM recurring_invoices WHERE company_id = ${companyId}`) as Row[];
  }

  return { items: rows.map(mapRow), total: Number(countRows[0]?.cnt || 0) };
}

export async function createRecurringInvoice(companyId: string, 
  input: RecurringInvoiceCreateInput,
  userId: string
): Promise<RecurringInvoice> {
  const taxRate = input.taxRate ?? 15;
  const subtotal = input.lineItems.reduce(
    (s, li) => s + li.quantity * li.unitPrice, 0
  );
  const taxAmount = Math.round(subtotal * (taxRate / 100) * 100) / 100;
  const totalAmount = subtotal + taxAmount;

  const rows = (await sql`
    INSERT INTO recurring_invoices (
      company_id, template_name, client_id, project_id, frequency, next_run_date,
      end_date, description, line_items, subtotal, tax_rate, tax_amount,
      total_amount, payment_terms, created_by
    ) VALUES (
      ${companyId}, ${input.templateName}, ${input.clientId}::UUID,
      ${input.projectId || null}, ${input.frequency}, ${input.nextRunDate},
      ${input.endDate || null}, ${input.description || null},
      ${JSON.stringify(input.lineItems)}::JSONB, ${subtotal}, ${taxRate},
      ${taxAmount}, ${totalAmount}, ${input.paymentTerms || '30 days'}, ${userId}::UUID
    ) RETURNING *
  `) as Row[];

  log.info('Created recurring invoice', { id: rows[0]?.id }, 'accounting');
  return mapRow(rows[0]!);
}

export async function updateRecurringStatus(companyId: string, 
  id: string,
  status: 'paused' | 'active' | 'cancelled'
): Promise<void> {
  await sql`UPDATE recurring_invoices SET status = ${status} WHERE id = ${id} AND company_id = ${companyId}`;
  log.info('Updated recurring invoice status', { id, status }, 'accounting');
}

export async function generateInvoiceFromRecurring(companyId: string, 
  id: string,
  userId: string
): Promise<string> {
  const rows = (await sql`SELECT * FROM recurring_invoices WHERE id = ${id} AND company_id = ${companyId}`) as Row[];
  if (!rows[0]) throw new Error('Recurring invoice not found');
  const ri = rows[0];
  if (ri.status !== 'active') throw new Error('Recurring invoice is not active');

  const nextDate = advanceDate(String(ri.next_run_date), String(ri.frequency));
  const endDate = ri.end_date ? String(ri.end_date) : null;
  const newStatus = endDate && nextDate > endDate ? 'completed' : 'active';

  const invoiceId = await withTransaction(async (tx) => {
    const inv = (await tx`
      INSERT INTO customer_invoices (
        client_id, project_id, invoice_date, due_date, subtotal,
        tax_amount, total_amount, status, description, created_by
      ) VALUES (
        ${ri.client_id}::UUID, ${ri.project_id || null},
        CURRENT_DATE, CURRENT_DATE + INTERVAL '30 days',
        ${Number(ri.subtotal)}, ${Number(ri.tax_amount)}, ${Number(ri.total_amount)},
        'approved', ${ri.description || ri.template_name}, ${userId}::UUID
      ) RETURNING id
    `) as Row[];

    await tx`
      UPDATE recurring_invoices
      SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE,
          run_count = run_count + 1, status = ${newStatus}
      WHERE id = ${id}
    `;

    return String(inv[0]!.id);
  });

  log.info('Generated invoice from recurring', { recurringId: id, invoiceId }, 'accounting');
  return invoiceId;
}

function advanceDate(dateStr: string, frequency: string): string {
  const d = new Date(dateStr);
  switch (frequency) {
    case 'weekly': d.setDate(d.getDate() + 7); break;
    case 'monthly': d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually': d.setFullYear(d.getFullYear() + 1); break;
  }
  return d.toISOString().split('T')[0]!;
}

function mapRow(row: Row): RecurringInvoice {
  return {
    id: String(row.id),
    templateName: String(row.template_name),
    clientId: String(row.client_id),
    projectId: row.project_id ? String(row.project_id) : undefined,
    frequency: String(row.frequency) as RecurringInvoice['frequency'],
    nextRunDate: String(row.next_run_date),
    endDate: row.end_date ? String(row.end_date) : undefined,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : undefined,
    runCount: Number(row.run_count),
    status: String(row.status) as RecurringInvoice['status'],
    description: row.description ? String(row.description) : undefined,
    lineItems: Array.isArray(row.line_items) ? row.line_items : JSON.parse(row.line_items || '[]'),
    subtotal: Number(row.subtotal),
    taxRate: Number(row.tax_rate),
    taxAmount: Number(row.tax_amount),
    totalAmount: Number(row.total_amount),
    paymentTerms: row.payment_terms ? String(row.payment_terms) : undefined,
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
    clientName: row.client_name ? String(row.client_name) : undefined,
  };
}

/**
 * Bank Feed Sync Service — transaction fetching, sync orchestration, and history.
 *
 * Handles: token refresh, pagination via Stitch GraphQL, deduplication, sync logging.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { SyncResult, StitchTransaction } from './bankFeedConnectionService';
import {
  refreshAccessToken,
  graphqlQuery,
  encryptToken,
  decryptToken,
} from './bankFeedConnectionService';

// ── Stitch transaction fetching ───────────────────────────────────────────────

/**
 * Fetch transactions for a specific account from Stitch.
 * Supports cursor-based pagination for incremental sync.
 */
export async function fetchStitchTransactions(
  accessToken: string,
  accountId: string,
  afterCursor?: string,
  limit = 100,
): Promise<{
  transactions: StitchTransaction[];
  endCursor: string | null;
  hasNextPage: boolean;
}> {
  const query = `
    query GetTransactions($accountId: ID!, $first: Int!, $after: String) {
      node(id: $accountId) {
        ... on BankAccount {
          transactions(first: $first, after: $after) {
            pageInfo { hasNextPage endCursor }
            nodes { id amount runningBalance description reference date }
          }
        }
      }
    }
  `;

  const data = await graphqlQuery(accessToken, query, {
    accountId,
    first: limit,
    after: afterCursor || null,
  });

  const txConnection = data?.node?.transactions;
  const nodes = txConnection?.nodes ?? [];
  const pageInfo = txConnection?.pageInfo ?? {};

  return {
    transactions: nodes.map((t: Record<string, unknown>) => ({
      id: t.id as string,
      amount: Number(t.amount),
      runningBalance: t.runningBalance != null ? Number(t.runningBalance) : null,
      description: (t.description as string) || '',
      reference: (t.reference as string) || null,
      date: t.date as string,
    })),
    endCursor: (pageInfo.endCursor as string) || null,
    hasNextPage: !!pageInfo.hasNextPage,
  };
}

// ── Sync orchestration ────────────────────────────────────────────────────────

/**
 * Sync transactions for a connection.
 * Handles token refresh, pagination, and deduplication.
 */
export async function syncTransactions(connectionId: string): Promise<SyncResult> {
  const conn = (await sql`
    SELECT * FROM bank_feed_connections WHERE id = ${connectionId}::UUID AND is_active = true
  `) as Record<string, unknown>[];
  if (!conn[0]) throw new Error('Connection not found or inactive');

  const connection = conn[0];
  let accessToken = decryptToken(connection.access_token as string);
  const refreshToken = decryptToken(connection.refresh_token as string);

  // Refresh token if expired
  if (new Date(connection.token_expires_at) <= new Date()) {
    log.info('Refreshing expired token', { connectionId }, 'bank-feeds');
    const refreshed = await refreshAccessToken(refreshToken);
    accessToken = refreshed.accessToken;
    const newExpiry = new Date(Date.now() + refreshed.expiresIn * 1000).toISOString();
    await sql`
      UPDATE bank_feed_connections SET
        access_token = ${encryptToken(refreshed.accessToken)},
        refresh_token = ${encryptToken(refreshed.refreshToken)},
        token_expires_at = ${newExpiry}::TIMESTAMPTZ,
        updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
  }

  // Create sync log entry
  const logRows = (await sql`
    INSERT INTO bank_feed_sync_log (connection_id, sync_type)
    VALUES (${connectionId}::UUID, ${connection.last_sync_cursor ? 'incremental' : 'full'})
    RETURNING id
  `) as Record<string, unknown>[];
  const syncLogId = logRows[0].id;

  await sql`
    UPDATE bank_feed_connections SET sync_status = 'syncing', updated_at = NOW()
    WHERE id = ${connectionId}::UUID
  `;

  let totalFetched = 0;
  let totalImported = 0;
  let totalSkipped = 0;
  let cursor: string | undefined = connection.last_sync_cursor || undefined;

  try {
    let hasMore = true;
    while (hasMore) {
      const result = await fetchStitchTransactions(
        accessToken,
        connection.external_account_id,
        cursor,
        100,
      );
      totalFetched += result.transactions.length;

      for (const tx of result.transactions) {
        const existing = (await sql`
          SELECT id FROM bank_transactions
          WHERE bank_account_id = ${connection.bank_account_id}::UUID
            AND bank_reference = ${tx.id}
          LIMIT 1
        `) as Row[];

        if (existing.length > 0) {
          totalSkipped++;
          continue;
        }

        await sql`
          INSERT INTO bank_transactions (
            bank_account_id, transaction_date, amount, description,
            reference, bank_reference, status, import_batch_id
          ) VALUES (
            ${connection.bank_account_id}::UUID, ${tx.date}::DATE, ${tx.amount},
            ${tx.description}, ${tx.reference || null}, ${tx.id},
            'imported', NULL
          )
        `;
        totalImported++;
      }

      cursor = result.endCursor || undefined;
      hasMore = result.hasNextPage;
    }

    await sql`
      UPDATE bank_feed_connections SET
        last_sync_at = NOW(),
        last_sync_cursor = ${cursor || null},
        sync_status = 'synced',
        sync_error = NULL,
        updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;

    await sql`
      UPDATE bank_feed_sync_log SET
        transactions_fetched = ${totalFetched},
        transactions_imported = ${totalImported},
        transactions_skipped = ${totalSkipped},
        completed_at = NOW(),
        status = 'completed'
      WHERE id = ${syncLogId}::UUID
    `;

    log.info('Bank feed sync completed', {
      connectionId, fetched: totalFetched, imported: totalImported, skipped: totalSkipped,
    }, 'bank-feeds');
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Sync failed';
    await sql`
      UPDATE bank_feed_connections SET sync_status = 'error', sync_error = ${errorMessage}, updated_at = NOW()
      WHERE id = ${connectionId}::UUID
    `;
    await sql`
      UPDATE bank_feed_sync_log SET status = 'failed', error = ${errorMessage}, completed_at = NOW()
      WHERE id = ${syncLogId}::UUID
    `;
    log.error('Bank feed sync failed', { connectionId, error: errorMessage }, 'bank-feeds');
    throw error;
  }

  return { fetched: totalFetched, imported: totalImported, skipped: totalSkipped };
}

// ── Sync history ──────────────────────────────────────────────────────────────

/**
 * Get sync history for a connection.
 */
export async function getSyncHistory(
  connectionId: string,
  limit = 20,
): Promise<Array<{
  id: string;
  syncType: string;
  fetched: number;
  imported: number;
