/**
 * Recurring Transaction Service — WS-8.4
 * CRUD + execute for recurring journal/invoice templates.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

export interface RecurringTemplate {
  id: string;
  companyId: string;
  name: string;
  entityType: 'journal_entry' | 'customer_invoice' | 'supplier_invoice';
  templateData: Record<string, unknown>;
  frequency: 'daily' | 'weekly' | 'monthly' | 'quarterly' | 'annually';
  nextRunDate: string | null;
  lastRunDate: string | null;
  isActive: boolean;
  autoPost: boolean;
  createdBy: string;
  createdAt: string;
}

export interface TemplateInput {
  name: string;
  entityType: 'journal_entry' | 'customer_invoice' | 'supplier_invoice';
  templateData: Record<string, unknown>;
  frequency: 'daily' | 'weekly' | 'monthly' | 'quarterly' | 'annually';
  nextRunDate?: string | null;
  isActive?: boolean;
  autoPost?: boolean;
}

export interface UpcomingItem {
  id: string;
  name: string;
  entityType: string;
  nextRunDate: string;
  frequency: string;
}

function mapRow(row: Row): RecurringTemplate {
  return {
    id: String(row.id),
    companyId: String(row.company_id),
    name: String(row.name),
    entityType: String(row.entity_type) as RecurringTemplate['entityType'],
    templateData: (typeof row.template_data === 'object' && row.template_data !== null ? row.template_data : JSON.parse(typeof row.template_data === 'string' ? row.template_data : '{}')) as Record<string, unknown>,
    frequency: String(row.frequency) as RecurringTemplate['frequency'],
    nextRunDate: row.next_run_date ? String(row.next_run_date) : null,
    lastRunDate: row.last_run_date ? String(row.last_run_date) : null,
    isActive: Boolean(row.is_active),
    autoPost: Boolean(row.auto_post),
    createdBy: String(row.created_by),
    createdAt: String(row.created_at),
  };
}

export function calculateNextRunDate(currentDate: Date, frequency: string): Date {
  const d = new Date(currentDate);
  switch (frequency) {
    case 'daily':     d.setDate(d.getDate() + 1); break;
    case 'weekly':    d.setDate(d.getDate() + 7); break;
    case 'monthly':   d.setMonth(d.getMonth() + 1); break;
    case 'quarterly': d.setMonth(d.getMonth() + 3); break;
    case 'annually':  d.setFullYear(d.getFullYear() + 1); break;
  }
  return d;
}

export async function getRecurringTemplates(companyId: string): Promise<RecurringTemplate[]> {
  const rows = (await sql`
    SELECT * FROM recurring_transaction_templates
    WHERE company_id = ${companyId}
    ORDER BY created_at DESC
  `) as Row[];
  return rows.map(mapRow);
}

export async function createRecurringTemplate(
  companyId: string,
  userId: string,
  input: TemplateInput,
): Promise<RecurringTemplate> {
  const rows = (await sql`
    INSERT INTO recurring_transaction_templates
      (company_id, name, entity_type, template_data, frequency, next_run_date, is_active, auto_post, created_by)
    VALUES (
      ${companyId}, ${input.name}, ${input.entityType},
      ${JSON.stringify(input.templateData)}::JSONB,
      ${input.frequency}, ${input.nextRunDate ?? null},
      ${input.isActive ?? true}, ${input.autoPost ?? false}, ${userId}
    )
    RETURNING *
  `) as Row[];
  log.info('Recurring template created', { id: rows[0]?.id }, 'recurring');
  return mapRow(rows[0]!);
}

export async function updateRecurringTemplate(
  companyId: string,
  id: string,
  updates: Partial<TemplateInput>,
): Promise<RecurringTemplate> {
  const rows = (await sql`
    UPDATE recurring_transaction_templates SET
      name          = COALESCE(${updates.name ?? null}, name),
      frequency     = COALESCE(${updates.frequency ?? null}, frequency),
      next_run_date = COALESCE(${updates.nextRunDate ?? null}::DATE, next_run_date),
      is_active     = COALESCE(${updates.isActive ?? null}, is_active),
      auto_post     = COALESCE(${updates.autoPost ?? null}, auto_post),
      template_data = COALESCE(${updates.templateData ? JSON.stringify(updates.templateData) : null}::JSONB, template_data)
    WHERE id = ${id}::UUID AND company_id = ${companyId}
    RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error('Template not found');
  log.info('Recurring template updated', { id }, 'recurring');
  return mapRow(rows[0]!);
}

export async function deleteRecurringTemplate(companyId: string, id: string): Promise<void> {
  await sql`
    DELETE FROM recurring_transaction_templates WHERE id = ${id}::UUID AND company_id = ${companyId}
  `;
  log.info('Recurring template deleted', { id }, 'recurring');
}

export async function executeRecurring(
  companyId: string,
  templateId: string,
  userId: string,
): Promise<{ entityType: string; entityId: string; posted: boolean }> {
  const rows = (await sql`
    SELECT * FROM recurring_transaction_templates
    WHERE id = ${templateId}::UUID AND company_id = ${companyId} AND is_active = true
  `) as Row[];
  if (!rows[0]) throw new Error('Template not found or inactive');
  const template = mapRow(rows[0]!);

  let entityId: string;
  let posted = false;

  if (template.entityType === 'journal_entry') {
    const { createJournalEntry, postJournalEntry } =
      await import('./journalEntryService');
    const data = template.templateData as Record<string, unknown>;
    const je = await createJournalEntry(companyId, {
      entryDate: new Date().toISOString().split('T')[0]!,
      description: data.description || template.name,
      source: 'auto_recurring',
      lines: data.lines || [],
    }, userId);
    entityId = je.id;
    if (template.autoPost) {
      await postJournalEntry(companyId, je.id, userId);
      posted = true;
    }
  } else if (template.entityType === 'customer_invoice') {
    // Customer invoice: insert with template_data fields
    const data = template.templateData as Record<string, unknown>;
    const ciRows = (await sql`
      INSERT INTO customer_invoices (company_id, client_id, invoice_date, due_date,
        reference, notes, currency, lines, subtotal, vat_amount, total_amount, status)
      VALUES (
        ${companyId},
        ${String(data.clientId || '')},
        CURRENT_DATE,
        CURRENT_DATE::DATE + INTERVAL '30 days',
        ${String(data.reference || 'AUTO-REC')},
        ${String(data.notes || template.name)},
        ${String(data.currency || 'ZAR')},
        ${JSON.stringify(data.lines || [])}::JSONB,
        ${Number(data.subtotal || 0)},
        ${Number(data.vatAmount || 0)},
        ${Number(data.totalAmount || 0)},
        'draft'
      ) RETURNING id
    `) as Row[];
    entityId = String(ciRows[0]?.id);
    if (template.autoPost) {
      await sql`UPDATE customer_invoices SET status = 'posted' WHERE id = ${entityId}::UUID`;
      posted = true;
    }
  } else {
    // Supplier invoice
    const data = template.templateData as Record<string, unknown>;
    const siRows = (await sql`
      INSERT INTO supplier_invoices (company_id, supplier_id, invoice_date, due_date,
        reference, description, currency, lines, subtotal, vat_amount, total_amount, status)
      VALUES (
        ${companyId},
        ${String(data.supplierId || '')},
        CURRENT_DATE,
        CURRENT_DATE::DATE + INTERVAL '30 days',
        ${String(data.reference || 'AUTO-REC')},
        ${String(data.description || template.name)},
        ${String(data.currency || 'ZAR')},
        ${JSON.stringify(data.lines || [])}::JSONB,
        ${Number(data.subtotal || 0)},
        ${Number(data.vatAmount || 0)},
        ${Number(data.totalAmount || 0)},
        'draft'
      ) RETURNING id
    `) as Row[];
    entityId = String(siRows[0]?.id);
    if (template.autoPost) {
      await sql`UPDATE supplier_invoices SET status = 'posted' WHERE id = ${entityId}::UUID`;
      posted = true;
    }
  }

  // Advance schedule
  const now = new Date();
  const nextDate = calculateNextRunDate(now, template.frequency).toISOString().split('T')[0]!;
  await sql`
    UPDATE recurring_transaction_templates
    SET last_run_date = CURRENT_DATE, next_run_date = ${nextDate}::DATE
    WHERE id = ${templateId}::UUID AND company_id = ${companyId}
  `;

  log.info('Recurring template executed', { templateId, entityId, entityType: template.entityType }, 'recurring');
  return { entityType: template.entityType, entityId, posted };
}

export async function getUpcomingRecurring(
  companyId: string,
  days = 7,
): Promise<UpcomingItem[]> {
  const rows = (await sql`
    SELECT id, name, entity_type, next_run_date, frequency
    FROM recurring_transaction_templates
    WHERE company_id = ${companyId}
      AND is_active = true
      AND next_run_date <= CURRENT_DATE + ${days} * INTERVAL '1 day'
    ORDER BY next_run_date ASC
  `) as Row[];
  return rows.map(r => ({
    id: String(r.id),
    name: String(r.name),
    entityType: String(r.entity_type),
    nextRunDate: String(r.next_run_date),
    frequency: String(r.frequency),
  }));
}

/**
 * Bank Feed Connection Service — Stitch.money OAuth, token management, and connection CRUD.
 *
 * Environment variables required:
 *   STITCH_CLIENT_ID     — Stitch application client ID
 *   STITCH_CLIENT_SECRET — Stitch application secret
 *   STITCH_REDIRECT_URI  — OAuth callback URL
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { encryptToken, decryptToken } from '@/lib/encryption';

// ── Config ───────────────────────────────────────────────────────────────────

const STITCH_AUTH_URL = 'https://secure.stitch.money/connect/authorize';
export const STITCH_TOKEN_URL = 'https://secure.stitch.money/connect/token';
export const STITCH_GRAPHQL_URL = 'https://api.stitch.money/graphql';

function getConfig() {
  return {
    clientId: process.env.STITCH_CLIENT_ID,
    clientSecret: process.env.STITCH_CLIENT_SECRET,
    redirectUri: process.env.STITCH_REDIRECT_URI,
  };
}

export function isConfigured(): boolean {
  const { clientId, clientSecret, redirectUri } = getConfig();
  return !!(clientId && clientSecret && redirectUri);
}

// ── Types ────────────────────────────────────────────────────────────────────

export interface BankFeedConnection {
  id: string;
  bankAccountId: string;
  bankAccountName?: string;
  provider: string;
  externalAccountId: string | null;
  bankName: string | null;
  accountNumberMasked: string | null;
  branchCode: string | null;
  accountType: string | null;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
  isActive: boolean;
  createdAt: string;
}

export interface StitchTransaction {
  id: string;
  amount: number;
  runningBalance: number | null;
  description: string;
  reference: string | null;
  date: string;
}

export interface StitchAccount {
  id: string;
  name: string;
  bankId: string;
  accountType: string;
  accountNumber: string;
  branchCode: string;
  currency: string;
  currentBalance: number | null;
  availableBalance: number | null;
}

export interface SyncResult {
  fetched: number;
  imported: number;
  skipped: number;
}

// ── PKCE Helpers ─────────────────────────────────────────────────────────────

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString('base64url');
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash('sha256').update(verifier).digest('base64url');
}

// ── OAuth Flow ───────────────────────────────────────────────────────────────

/**
 * Generate the Stitch authorization URL for linking a bank account.
 * Returns { url, state, codeVerifier } — store state + codeVerifier in session.
 */
export function getAuthorizationUrl(): {
  url: string;
  state: string;
  nonce: string;
  codeVerifier: string;
} {
  const { clientId, redirectUri } = getConfig();
  if (!clientId || !redirectUri) {
    throw new Error('Stitch integration not configured. Set STITCH_CLIENT_ID and STITCH_REDIRECT_URI.');
  }

  const state = crypto.randomBytes(16).toString('hex');
  const nonce = crypto.randomBytes(16).toString('hex');
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  const params = new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    scope: 'openid accounts transactions balances offline_access',
    redirect_uri: redirectUri,
    state,
    nonce,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
  });

  return { url: `${STITCH_AUTH_URL}?${params.toString()}`, state, nonce, codeVerifier };
}

/**
 * Exchange authorization code for access + refresh tokens.
 */
export async function exchangeCode(
  code: string,
  codeVerifier: string,
): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const { clientId, clientSecret, redirectUri } = getConfig();
  if (!clientId || !clientSecret || !redirectUri) {
    throw new Error('Stitch integration not configured');
  }

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: clientId,
      client_secret: clientSecret,
      code,
      redirect_uri: redirectUri,
      code_verifier: codeVerifier,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token exchange failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token exchange failed: ${res.status}`);
  }

  const data = await res.json();
  return { accessToken: data.access_token, refreshToken: data.refresh_token, expiresIn: data.expires_in };
}

/**
 * Refresh an expired access token.
 */
export async function refreshAccessToken(refreshToken: string): Promise<{
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}> {
  const { clientId, clientSecret } = getConfig();
  if (!clientId || !clientSecret) throw new Error('Stitch integration not configured');

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token refresh failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token refresh failed: ${res.status}`);
  }

  const data = await res.json();
  return {
    accessToken: data.access_token,
    refreshToken: data.refresh_token || refreshToken,
    expiresIn: data.expires_in,
  };
}

// ── GraphQL ──────────────────────────────────────────────────────────────────

export async function graphqlQuery(
  accessToken: string,
  query: string,
  variables?: Record<string, unknown>,
) {
  const res = await fetch(STITCH_GRAPHQL_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({ query, variables }),
  });
  if (!res.ok) {
    const error = await res.text();
    throw new Error(`GraphQL request failed: ${res.status} — ${error}`);
  }
  const json = await res.json();
  if (json.errors?.length) throw new Error(`GraphQL errors: ${JSON.stringify(json.errors)}`);
  return json.data;
}

/**
 * Fetch linked bank accounts from Stitch.
 */
export async function fetchStitchAccounts(accessToken: string): Promise<StitchAccount[]> {
  const query = `query { user { bankAccounts { id name bankId accountType accountNumber branchCode currency currentBalance availableBalance } } }`;
  const data = await graphqlQuery(accessToken, query);
  return (data?.user?.bankAccounts ?? []).map((a: Record<string, unknown>) => ({
    id: a.id as string,
    name: a.name as string,
    bankId: a.bankId as string,
    accountType: a.accountType as string,
    accountNumber: a.accountNumber as string,
    branchCode: a.branchCode as string,
    currency: (a.currency as string) || 'ZAR',
    currentBalance: a.currentBalance != null ? Number(a.currentBalance) : null,
    availableBalance: a.availableBalance != null ? Number(a.availableBalance) : null,
  }));
}

// ── Connection CRUD ──────────────────────────────────────────────────────────

export async function listConnections(): Promise<BankFeedConnection[]> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    ORDER BY bfc.created_at DESC
  `) as Record<string, unknown>[];
  return rows.map(mapConnection);
}

export async function getConnection(id: string): Promise<BankFeedConnection | null> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${id}::UUID
  `) as Record<string, unknown>[];
  return rows[0] ? mapConnection(rows[0]) : null;
}

export async function createConnection(input: {
  bankAccountId: string;
  externalAccountId: string;
  bankName?: string;
  accountNumberMasked?: string;
  branchCode?: string;
  accountType?: string;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  createdBy: string;
