    `) as Row[];

    log.info('Payroll run completed', { runId, journalEntryId: journalEntry.id }, 'payroll');
    return mapPayrollRun(updatedRows[0]!);
  } catch (err) {
    log.error('completePayrollRun failed', { runId, error: err }, 'payroll');
    throw err;
  }
}

