    `) as Row[];

    log.info('Payroll run reversed', { runId }, 'payroll');
    return mapPayrollRun(updatedRows[0]!);
  } catch (err) {
    log.error('reversePayrollRun failed', { runId, error: err }, 'payroll');
    throw err;
  }
}

