  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    ORDER BY bfc.created_at DESC
  `) as Record<string, unknown>[];
  return rows.map(mapConnection);
}

export async function getConnection(id: string): Promise<BankFeedConnection | null> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${id}::UUID
  `) as Record<string, unknown>[];
  return rows[0] ? mapConnection(rows[0]) : null;
}

export async function createConnection(input: {
  bankAccountId: string;
  externalAccountId: string;
  bankName?: string;
  accountNumberMasked?: string;
  branchCode?: string;
  accountType?: string;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  createdBy: string;
}): Promise<BankFeedConnection> {
  const expiresAt = new Date(Date.now() + input.expiresIn * 1000).toISOString();
  const rows = (await sql`
    INSERT INTO bank_feed_connections (
      bank_account_id, provider, external_account_id, bank_name,
      account_number_masked, branch_code, account_type,
      access_token, refresh_token, token_expires_at, sync_status, created_by
    ) VALUES (
      ${input.bankAccountId}::UUID, 'stitch', ${input.externalAccountId},
      ${input.bankName || null}, ${input.accountNumberMasked || null},
      ${input.branchCode || null}, ${input.accountType || null},
      ${encryptToken(input.accessToken)}, ${encryptToken(input.refreshToken)}, ${expiresAt}::TIMESTAMPTZ,
      'pending', ${input.createdBy}::UUID
    ) RETURNING *
  `) as Record<string, unknown>[];
  log.info('Bank feed connection created', { id: rows[0].id, bankName: input.bankName }, 'bank-feeds');
  return mapConnection(rows[0]);
}

export async function disconnectConnection(id: string): Promise<void> {
  await sql`UPDATE bank_feed_connections SET is_active = false, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Bank feed disconnected', { id }, 'bank-feeds');
}

// ── Mapper ────────────────────────────────────────────────────────────────────

export function mapConnection(r: Record<string, unknown>): BankFeedConnection {
  return {
    id: r.id,
    bankAccountId: r.bank_account_id,
    bankAccountName: r.bank_account_name || undefined,
    provider: r.provider,
    externalAccountId: r.external_account_id,
    bankName: r.bank_name,
    accountNumberMasked: r.account_number_masked,
    branchCode: r.branch_code,
    accountType: r.account_type,
    lastSyncAt: r.last_sync_at,
    syncStatus: r.sync_status,
    syncError: r.sync_error,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

/**
 * Business Unit Service
 * CRUD operations for the business_units table
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

export interface BusinessUnit {
  id: string;
  code: string;
  name: string;
  description?: string;
  isActive: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface BusinessUnitInput {
  code: string;
  name: string;
  description?: string;
}

export async function getBusinessUnits(companyId: string, activeOnly = false): Promise<BusinessUnit[]> {
  const rows = activeOnly
    ? ((await sql`SELECT * FROM business_units WHERE company_id = ${companyId} AND is_active = true ORDER BY code`) as Row[])
    : ((await sql`SELECT * FROM business_units WHERE company_id = ${companyId} ORDER BY code`) as Row[]);
  return rows.map(mapRow);
}

export async function createBusinessUnit(companyId: string, input: BusinessUnitInput, _userId: string): Promise<BusinessUnit> {
  const rows = (await sql`
    INSERT INTO business_units (company_id, code, name, description)
    VALUES (${companyId}, ${input.code}, ${input.name}, ${input.description || null})
    RETURNING *
  `) as Record<string, unknown>[];
  log.info('Created business unit', { id: rows[0].id, code: input.code }, 'accounting');
  return mapRow(rows[0]);
}

export async function updateBusinessUnit(companyId: string, id: string, input: Partial<BusinessUnitInput>): Promise<BusinessUnit> {
  const rows = (await sql`
    UPDATE business_units SET
      code = COALESCE(${input.code || null}, code),
      name = COALESCE(${input.name || null}, name),
      description = COALESCE(${input.description || null}, description),
      updated_at = NOW()
    WHERE id = ${id}::UUID AND company_id = ${companyId} RETURNING *
  `) as Record<string, unknown>[];
  if (!rows[0]) throw new Error(`Business unit ${id} not found`);
  return mapRow(rows[0]);
}

export async function toggleBusinessUnit(companyId: string, id: string, isActive: boolean): Promise<void> {
  await sql`UPDATE business_units SET is_active = ${isActive}, updated_at = NOW() WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

export async function deleteBusinessUnit(companyId: string, id: string): Promise<void> {
  const usage = (await sql`
    SELECT COUNT(*) as cnt FROM gl_journal_lines WHERE bu_id = ${id}::UUID
  `) as Record<string, unknown>[];
  if (Number(usage[0]?.cnt) > 0) {
    throw new Error('Cannot delete business unit used in journal entries. Deactivate instead.');
  }
  const btUsage = (await sql`
    SELECT COUNT(*) as cnt FROM bank_transactions WHERE bu_id = ${id}::UUID
  `) as Record<string, unknown>[];
  if (Number(btUsage[0]?.cnt) > 0) {
    throw new Error('Cannot delete business unit used in bank transactions. Deactivate instead.');
  }
  await sql`DELETE FROM business_units WHERE id = ${id}::UUID AND company_id = ${companyId}`;
}

function mapRow(row: Row): BusinessUnit {
  return {
    id: String(row.id),
    code: String(row.code),
    name: String(row.name),
    description: row.description ? String(row.description) : undefined,
    isActive: Boolean(row.is_active),
    createdAt: String(row.created_at),
    updatedAt: String(row.updated_at),
  };
}

/**
 * Migration Execute Service — import parsed Xero/QuickBooks/Pastel data into ISAFlow
 * Uses existing migrationCoaService and migrationContactService patterns.
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { ParsedAccount, ParsedEntity, MigrationSource } from './migrationParserService';

type Row = Record<string, unknown>;

export interface ExecuteMigrationResult {
  accountsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: number;
  errors: string[];
}

export interface VerifyEntry {
  accountCode: string;
  sourceName: string;
  sourceBalance: number;
  isaflowBalance: number;
  difference: number;
  matched: boolean;
}

// ── Execute ──────────────────────────────────────────────────────────────────

export async function executeMigration(
  companyId: string,
  userId: string,
  source: MigrationSource,
  accounts: ParsedAccount[],
  customers: ParsedEntity[],
  suppliers: ParsedEntity[],
): Promise<ExecuteMigrationResult> {
  const errors: string[] = [];
  let accountsImported = 0;
  let customersImported = 0;
  let suppliersImported = 0;
  let openingBalancesSet = 0;

  log.info('Starting migration execution', { companyId, source, accountCount: accounts.length }, 'migration');

  // 1. Import GL accounts
  const validAccounts = accounts.filter(acct => {
    if (!acct.sourceCode && !acct.sourceName) return false;
    if (!acct.mappedType) {
      errors.push(`Account "${acct.sourceCode} ${acct.sourceName}": unmapped type "${acct.sourceType}" — skipped`);
      return false;
    }
    return true;
  });

  if (validAccounts.length > 0) {
    try {
      await transaction((txSql) =>
        validAccounts.map(acct => txSql`
          INSERT INTO gl_accounts (
            company_id, account_code, account_name, account_type, account_subtype,
            normal_balance, description, level, display_order, imported_from
          ) VALUES (
            ${companyId}::UUID,
            ${acct.sourceCode || acct.sourceName.substring(0, 20)},
            ${acct.sourceName},
            ${acct.mappedType},
            ${acct.mappedSubtype ?? null},
            ${acct.mappedNormalBalance ?? 'debit'},
            ${'Imported from ' + source},
            3,
            0,
            ${source}
          )
          ON CONFLICT (company_id, account_code) DO UPDATE SET
            account_name  = EXCLUDED.account_name,
            account_type  = EXCLUDED.account_type,
            imported_from = EXCLUDED.imported_from
        `)
      );
      accountsImported = validAccounts.length;
    } catch (err) {
      errors.push(`Accounts batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 2. Set opening balances via journal entry
  const balanceAccounts = accounts.filter(a => a.openingBalance !== 0 && a.sourceCode && a.mappedType);
  if (balanceAccounts.length > 0) {
    try {
      const jeRows = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, reference, description, status, created_by
        ) VALUES (
          ${companyId}::UUID,
          CURRENT_DATE,
          ${'OB-' + source.toUpperCase()},
          ${'Opening balances imported from ' + source},
          'posted',
          ${userId}::UUID
        ) RETURNING id
      `) as Row[];

      const jeId = String(jeRows[0].id);

      for (const acct of balanceAccounts) {
        const glRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE company_id = ${companyId}::UUID AND account_code = ${acct.sourceCode}
          LIMIT 1
        `) as Row[];

        if (glRows.length === 0) continue;
        const glId = String(glRows[0].id);
        const isDebitNormal = acct.mappedNormalBalance === 'debit';
        const debit  = isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;
        const credit = !isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;

        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
          VALUES (${jeId}::UUID, ${glId}::UUID, ${debit}, ${credit}, ${'Opening balance — ' + source})
        `;
        openingBalancesSet++;
      }
    } catch (err) {
      errors.push(`Opening balances: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 3. Import customers
  const validCustomers = customers.filter(c => c.name?.trim());
  if (validCustomers.length > 0) {
    try {
      await transaction((txSql) =>
        validCustomers.map(cust => txSql`
          INSERT INTO customers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${cust.name},
            ${cust.email ?? null},
            ${cust.phone ?? null},
            ${cust.vatNumber ?? null},
            ${cust.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      customersImported = validCustomers.length;
    } catch (err) {
      errors.push(`Customers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 4. Import suppliers
  const validSuppliers = suppliers.filter(s => s.name?.trim());
  if (validSuppliers.length > 0) {
    try {
      await transaction((txSql) =>
        validSuppliers.map(sup => txSql`
          INSERT INTO suppliers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${sup.name},
            ${sup.email ?? null},
            ${sup.phone ?? null},
            ${sup.vatNumber ?? null},
            ${sup.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      suppliersImported = validSuppliers.length;
    } catch (err) {
      errors.push(`Suppliers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  log.info('Migration execution complete', {
    companyId, source, accountsImported, customersImported, suppliersImported,
  }, 'migration');

  return { accountsImported, customersImported, suppliersImported, openingBalancesSet, errors };
}

// ── Verify balances ───────────────────────────────────────────────────────────

export async function verifyBalances(
  companyId: string,
  sourceAccounts: ParsedAccount[],
): Promise<VerifyEntry[]> {
  const results: VerifyEntry[] = [];

  for (const acct of sourceAccounts) {
    if (!acct.sourceCode) continue;

    try {
      const glRows = (await sql`
        SELECT ga.account_name,
          COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS net_debit,
          ga.normal_balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
        WHERE ga.company_id = ${companyId}::UUID AND ga.account_code = ${acct.sourceCode}
        GROUP BY ga.id, ga.account_name, ga.normal_balance
        LIMIT 1
      `) as Row[];

      const isaflowBalance = glRows.length > 0
        ? (String(glRows[0].normal_balance) === 'debit'
          ? Number(glRows[0].net_debit)
          : -Number(glRows[0].net_debit))
        : 0;

      const difference = acct.openingBalance - isaflowBalance;

      results.push({
        accountCode:    acct.sourceCode,
        sourceName:     acct.sourceName,
        sourceBalance:  acct.openingBalance,
        isaflowBalance,
        difference,
        matched:        Math.abs(difference) < 0.01,
      });
    } catch (err) {
      log.warn('Balance verification failed for account', { code: acct.sourceCode, error: err }, 'migration');
    }
  }

  return results;
}

// ── Rollback ─────────────────────────────────────────────────────────────────

export async function rollbackMigration(
  companyId: string,
  source: MigrationSource,
): Promise<{ deleted: number }> {
  let deleted = 0;

  try {
    // Remove GL accounts imported from this source
    const acctRows = (await sql`
      DELETE FROM gl_accounts
      WHERE company_id = ${companyId}::UUID AND imported_from = ${source}
      RETURNING id
    `) as Row[];
    deleted += acctRows.length;

    log.info('Rollback complete', { companyId, source, deleted }, 'migration');
  } catch (err) {
    log.error('Rollback failed', { companyId, source, error: err }, 'migration');
    throw err;
  }

  return { deleted };
}

/** Bank Feed Connection Service — Stitch.money OAuth, token management, and connection CRUD. */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { encryptToken, decryptToken } from '@/lib/encryption';

const STITCH_AUTH_URL = 'https://secure.stitch.money/connect/authorize';
export const STITCH_TOKEN_URL = 'https://secure.stitch.money/connect/token';
export const STITCH_GRAPHQL_URL = 'https://api.stitch.money/graphql';

function getConfig() {
  return {
    clientId: process.env.STITCH_CLIENT_ID,
    clientSecret: process.env.STITCH_CLIENT_SECRET,
    redirectUri: process.env.STITCH_REDIRECT_URI,
  };
}

export function isConfigured(): boolean {
  const { clientId, clientSecret, redirectUri } = getConfig();
  return !!(clientId && clientSecret && redirectUri);
}

// Types

export interface BankFeedConnection {
  id: string;
  bankAccountId: string;
  bankAccountName?: string;
  provider: string;
  externalAccountId: string | null;
  bankName: string | null;
  accountNumberMasked: string | null;
  branchCode: string | null;
  accountType: string | null;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
  isActive: boolean;
  createdAt: string;
}

export interface StitchTransaction {
  id: string;
  amount: number;
  runningBalance: number | null;
  description: string;
  reference: string | null;
  date: string;
}

export interface StitchAccount {
  id: string;
  name: string;
  bankId: string;
  accountType: string;
  accountNumber: string;
  branchCode: string;
  currency: string;
  currentBalance: number | null;
  availableBalance: number | null;
}

export interface SyncResult {
  fetched: number;
  imported: number;
  skipped: number;
}

// PKCE helpers

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString('base64url');
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash('sha256').update(verifier).digest('base64url');
}

// OAuth Flow

/** Generate Stitch authorization URL. Store state + codeVerifier in session. */
export function getAuthorizationUrl(): {
  url: string;
  state: string;
  nonce: string;
  codeVerifier: string;
} {
  const { clientId, redirectUri } = getConfig();
  if (!clientId || !redirectUri) {
    throw new Error('Stitch integration not configured. Set STITCH_CLIENT_ID and STITCH_REDIRECT_URI.');
  }

  const state = crypto.randomBytes(16).toString('hex');
  const nonce = crypto.randomBytes(16).toString('hex');
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  const params = new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    scope: 'openid accounts transactions balances offline_access',
    redirect_uri: redirectUri,
    state,
    nonce,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
  });

  return { url: `${STITCH_AUTH_URL}?${params.toString()}`, state, nonce, codeVerifier };
}

/** Exchange authorization code for access + refresh tokens. */
export async function exchangeCode(
  code: string,
  codeVerifier: string,
): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const { clientId, clientSecret, redirectUri } = getConfig();
  if (!clientId || !clientSecret || !redirectUri) {
    throw new Error('Stitch integration not configured');
  }

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: clientId,
      client_secret: clientSecret,
      code,
      redirect_uri: redirectUri,
      code_verifier: codeVerifier,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token exchange failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token exchange failed: ${res.status}`);
  }

  const data = await res.json();
  return { accessToken: data.access_token, refreshToken: data.refresh_token, expiresIn: data.expires_in };
}

/** Refresh an expired access token. */
export async function refreshAccessToken(refreshToken: string): Promise<{
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}> {
  const { clientId, clientSecret } = getConfig();
  if (!clientId || !clientSecret) throw new Error('Stitch integration not configured');

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token refresh failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token refresh failed: ${res.status}`);
  }

  const data = await res.json();
  return {
    accessToken: data.access_token,
    refreshToken: data.refresh_token || refreshToken,
    expiresIn: data.expires_in,
  };
}

// GraphQL

export async function graphqlQuery(
  accessToken: string,
  query: string,
  variables?: Record<string, unknown>,
) {
  const res = await fetch(STITCH_GRAPHQL_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({ query, variables }),
  });
  if (!res.ok) {
    const error = await res.text();
    throw new Error(`GraphQL request failed: ${res.status} — ${error}`);
  }
  const json = await res.json();
  if (json.errors?.length) throw new Error(`GraphQL errors: ${JSON.stringify(json.errors)}`);
  return json.data;
}

/**
 * Fetch linked bank accounts from Stitch.
 */
export async function fetchStitchAccounts(accessToken: string): Promise<StitchAccount[]> {
  const query = `query { user { bankAccounts { id name bankId accountType accountNumber branchCode currency currentBalance availableBalance } } }`;
  const data = await graphqlQuery(accessToken, query);
  return (data?.user?.bankAccounts ?? []).map((a: Record<string, unknown>) => ({
    id: a.id as string,
    name: a.name as string,
    bankId: a.bankId as string,
    accountType: a.accountType as string,
    accountNumber: a.accountNumber as string,
    branchCode: a.branchCode as string,
    currency: (a.currency as string) || 'ZAR',
    currentBalance: a.currentBalance != null ? Number(a.currentBalance) : null,
    availableBalance: a.availableBalance != null ? Number(a.availableBalance) : null,
  }));
}

// ── Connection CRUD ──────────────────────────────────────────────────────────

export async function listConnections(): Promise<BankFeedConnection[]> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    ORDER BY bfc.created_at DESC
  `) as Record<string, unknown>[];
  return rows.map(mapConnection);
}

export async function getConnection(id: string): Promise<BankFeedConnection | null> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${id}::UUID
  `) as Record<string, unknown>[];
  return rows[0] ? mapConnection(rows[0]) : null;
}

export async function createConnection(input: {
  bankAccountId: string;
  externalAccountId: string;
  bankName?: string;
  accountNumberMasked?: string;
  branchCode?: string;
  accountType?: string;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  createdBy: string;
}): Promise<BankFeedConnection> {
  const expiresAt = new Date(Date.now() + input.expiresIn * 1000).toISOString();
  const rows = (await sql`
    INSERT INTO bank_feed_connections (
      bank_account_id, provider, external_account_id, bank_name,
      account_number_masked, branch_code, account_type,
      access_token, refresh_token, token_expires_at, sync_status, created_by
    ) VALUES (
      ${input.bankAccountId}::UUID, 'stitch', ${input.externalAccountId},
      ${input.bankName || null}, ${input.accountNumberMasked || null},
      ${input.branchCode || null}, ${input.accountType || null},
      ${encryptToken(input.accessToken)}, ${encryptToken(input.refreshToken)}, ${expiresAt}::TIMESTAMPTZ,
      'pending', ${input.createdBy}::UUID
    ) RETURNING *
  `) as Record<string, unknown>[];
  log.info('Bank feed connection created', { id: rows[0].id, bankName: input.bankName }, 'bank-feeds');
  return mapConnection(rows[0]);
}

export async function disconnectConnection(id: string): Promise<void> {
  await sql`UPDATE bank_feed_connections SET is_active = false, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Bank feed disconnected', { id }, 'bank-feeds');
}

// ── Mapper ────────────────────────────────────────────────────────────────────

export function mapConnection(r: Record<string, unknown>): BankFeedConnection {
  return {
    id: r.id,
    bankAccountId: r.bank_account_id,
    bankAccountName: r.bank_account_name || undefined,
    provider: r.provider,
    externalAccountId: r.external_account_id,
    bankName: r.bank_name,
    accountNumberMasked: r.account_number_masked,
    branchCode: r.branch_code,
    accountType: r.account_type,
    lastSyncAt: r.last_sync_at,
    syncStatus: r.sync_status,
    syncError: r.sync_error,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

/**
 * Migration Execute Service — import parsed Xero/QuickBooks/Pastel data into ISAFlow
 * Uses existing migrationCoaService and migrationContactService patterns.
 */

import { sql, transaction } from '@/lib/neon';
import { log } from '@/lib/logger';
import type { ParsedAccount, ParsedEntity, MigrationSource } from './migrationParserService';

type Row = Record<string, unknown>;

export interface ExecuteMigrationResult {
  accountsImported: number;
  customersImported: number;
  suppliersImported: number;
  openingBalancesSet: number;
  errors: string[];
}

export interface VerifyEntry {
  accountCode: string;
  sourceName: string;
  sourceBalance: number;
  isaflowBalance: number;
  difference: number;
  matched: boolean;
}

// ── Execute ──────────────────────────────────────────────────────────────────

export async function executeMigration(
  companyId: string,
  userId: string,
  source: MigrationSource,
  accounts: ParsedAccount[],
  customers: ParsedEntity[],
  suppliers: ParsedEntity[],
): Promise<ExecuteMigrationResult> {
  const errors: string[] = [];
  let accountsImported = 0;
  let customersImported = 0;
  let suppliersImported = 0;
  let openingBalancesSet = 0;

  log.info('Starting migration execution', { companyId, source, accountCount: accounts.length }, 'migration');

  // 1. Import GL accounts
  const validAccounts = accounts.filter(acct => {
    if (!acct.sourceCode && !acct.sourceName) return false;
    if (!acct.mappedType) {
      errors.push(`Account "${acct.sourceCode} ${acct.sourceName}": unmapped type "${acct.sourceType}" — skipped`);
      return false;
    }
    return true;
  });

  if (validAccounts.length > 0) {
    try {
      await transaction((txSql) =>
        validAccounts.map(acct => txSql`
          INSERT INTO gl_accounts (
            company_id, account_code, account_name, account_type, account_subtype,
            normal_balance, description, level, display_order, imported_from
          ) VALUES (
            ${companyId}::UUID,
            ${acct.sourceCode || acct.sourceName.substring(0, 20)},
            ${acct.sourceName},
            ${acct.mappedType},
            ${acct.mappedSubtype ?? null},
            ${acct.mappedNormalBalance ?? 'debit'},
            ${'Imported from ' + source},
            3,
            0,
            ${source}
          )
          ON CONFLICT (company_id, account_code) DO UPDATE SET
            account_name  = EXCLUDED.account_name,
            account_type  = EXCLUDED.account_type,
            imported_from = EXCLUDED.imported_from
        `)
      );
      accountsImported = validAccounts.length;
    } catch (err) {
      errors.push(`Accounts batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 2. Set opening balances via journal entry
  const balanceAccounts = accounts.filter(a => a.openingBalance !== 0 && a.sourceCode && a.mappedType);
  if (balanceAccounts.length > 0) {
    try {
      const jeRows = (await sql`
        INSERT INTO gl_journal_entries (
          company_id, entry_date, reference, description, status, created_by
        ) VALUES (
          ${companyId}::UUID,
          CURRENT_DATE,
          ${'OB-' + source.toUpperCase()},
          ${'Opening balances imported from ' + source},
          'posted',
          ${userId}::UUID
        ) RETURNING id
      `) as Row[];

      const jeId = String(jeRows[0]!.id);

      for (const acct of balanceAccounts) {
        const glRows = (await sql`
          SELECT id FROM gl_accounts
          WHERE company_id = ${companyId}::UUID AND account_code = ${acct.sourceCode}
          LIMIT 1
        `) as Row[];

        if (glRows.length === 0) continue;
        const glId = String(glRows[0].id);
        const isDebitNormal = acct.mappedNormalBalance === 'debit';
        const debit  = isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;
        const credit = !isDebitNormal && acct.openingBalance > 0 ? acct.openingBalance : 0;

        await sql`
          INSERT INTO gl_journal_lines (journal_entry_id, gl_account_id, debit, credit, description)
          VALUES (${jeId}::UUID, ${glId}::UUID, ${debit}, ${credit}, ${'Opening balance — ' + source})
        `;
        openingBalancesSet++;
      }
    } catch (err) {
      errors.push(`Opening balances: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 3. Import customers
  const validCustomers = customers.filter(c => c.name?.trim());
  if (validCustomers.length > 0) {
    try {
      await transaction((txSql) =>
        validCustomers.map(cust => txSql`
          INSERT INTO customers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${cust.name},
            ${cust.email ?? null},
            ${cust.phone ?? null},
            ${cust.vatNumber ?? null},
            ${cust.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      customersImported = validCustomers.length;
    } catch (err) {
      errors.push(`Customers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  // 4. Import suppliers
  const validSuppliers = suppliers.filter(s => s.name?.trim());
  if (validSuppliers.length > 0) {
    try {
      await transaction((txSql) =>
        validSuppliers.map(sup => txSql`
          INSERT INTO suppliers (company_id, name, email, phone, vat_number, billing_address)
          VALUES (
            ${companyId}::UUID,
            ${sup.name},
            ${sup.email ?? null},
            ${sup.phone ?? null},
            ${sup.vatNumber ?? null},
            ${sup.address ?? null}
          )
          ON CONFLICT DO NOTHING
        `)
      );
      suppliersImported = validSuppliers.length;
    } catch (err) {
      errors.push(`Suppliers batch: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  log.info('Migration execution complete', {
    companyId, source, accountsImported, customersImported, suppliersImported,
  }, 'migration');

  return { accountsImported, customersImported, suppliersImported, openingBalancesSet, errors };
}

// ── Verify balances ───────────────────────────────────────────────────────────

export async function verifyBalances(
  companyId: string,
  sourceAccounts: ParsedAccount[],
): Promise<VerifyEntry[]> {
  const results: VerifyEntry[] = [];

  for (const acct of sourceAccounts) {
    if (!acct.sourceCode) continue;

    try {
      const glRows = (await sql`
        SELECT ga.account_name,
          COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS net_debit,
          ga.normal_balance
        FROM gl_accounts ga
        LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
        LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
        WHERE ga.company_id = ${companyId}::UUID AND ga.account_code = ${acct.sourceCode}
        GROUP BY ga.id, ga.account_name, ga.normal_balance
        LIMIT 1
      `) as Row[];

      const isaflowBalance = glRows.length > 0
        ? (String(glRows[0].normal_balance) === 'debit'
          ? Number(glRows[0].net_debit)
          : -Number(glRows[0].net_debit))
        : 0;

      const difference = acct.openingBalance - isaflowBalance;

      results.push({
        accountCode:    acct.sourceCode,
        sourceName:     acct.sourceName,
        sourceBalance:  acct.openingBalance,
        isaflowBalance,
        difference,
        matched:        Math.abs(difference) < 0.01,
      });
    } catch (err) {
      log.warn('Balance verification failed for account', { code: acct.sourceCode, error: err }, 'migration');
    }
  }

  return results;
}

// ── Rollback ─────────────────────────────────────────────────────────────────

export async function rollbackMigration(
  companyId: string,
  source: MigrationSource,
): Promise<{ deleted: number }> {
  let deleted = 0;

  try {
    // Remove GL accounts imported from this source
    const acctRows = (await sql`
      DELETE FROM gl_accounts
      WHERE company_id = ${companyId}::UUID AND imported_from = ${source}
      RETURNING id
    `) as Row[];
    deleted += acctRows.length;

    log.info('Rollback complete', { companyId, source, deleted }, 'migration');
  } catch (err) {
    log.error('Rollback failed', { companyId, source, error: err }, 'migration');
    throw err;
  }

  return { deleted };
}

/**
 * Cash Flow Forecasting Service
 * Projects future cash position based on historical patterns,
 * recurring invoices, known payables, and seasonal trends.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// ── Types ────────────────────────────────────────────────────────────────────

export interface CashFlowForecastPoint {
  date: string;          // YYYY-MM-DD
  label: string;         // "Apr 2026", "Week 14", etc.
  projectedInflow: number;
  projectedOutflow: number;
  projectedNet: number;
  projectedBalance: number;
  confidence: number;    // 0-1
}

export interface CashFlowAlert {
  type: 'warning' | 'danger';
  message: string;
  date: string;
  projectedBalance: number;
}

export interface CashFlowForecastResult {
  currentBalance: number;
  forecastPoints: CashFlowForecastPoint[];
  alerts: CashFlowAlert[];
  assumptions: string[];
  generatedAt: string;
}

export interface HistoricalCashFlow {
  month: string;
  inflow: number;
  outflow: number;
  net: number;
}

// ── Historical Analysis ──────────────────────────────────────────────────────

/** Get current total cash balance across all bank accounts */
async function getCurrentCashBalance(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(
      CASE WHEN ga.account_subtype IN ('bank', 'cash')
        THEN COALESCE(
          (SELECT SUM(jl.debit) - SUM(jl.credit)
           FROM gl_journal_lines jl
           JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
           WHERE jl.gl_account_id = ga.id
             AND je.status = 'posted'
             AND je.company_id = ${companyId}),
          0)
        ELSE 0
      END
    ), 0) AS total_cash
    FROM gl_accounts ga
    WHERE ga.company_id = ${companyId}
      AND ga.account_type = 'asset'
      AND ga.account_subtype IN ('bank', 'cash')
      AND ga.is_active = true
  `) as Row[];
  return Number(rows[0]?.total_cash ?? 0);
}

/** Get monthly cash inflows and outflows for the last N months */
async function getHistoricalCashFlows(companyId: string, months: number): Promise<HistoricalCashFlow[]> {
  // Compute the start date in JS to avoid interval arithmetic in tagged templates
  const startDate = new Date();
  startDate.setMonth(startDate.getMonth() - months);
  const startStr = startDate.toISOString().split('T')[0]!;

  const rows = (await sql`
    WITH monthly AS (
      SELECT
        date_trunc('month', je.entry_date) AS month,
        COALESCE(SUM(CASE WHEN jl.debit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.debit ELSE 0 END), 0) AS inflow,
        COALESCE(SUM(CASE WHEN jl.credit > 0 AND ga.account_subtype IN ('bank', 'cash') THEN jl.credit ELSE 0 END), 0) AS outflow
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.company_id = ${companyId}
        AND je.status = 'posted'
        AND ga.account_type = 'asset'
        AND ga.account_subtype IN ('bank', 'cash')
        AND je.entry_date >= ${startStr}::DATE
      GROUP BY date_trunc('month', je.entry_date)
    )
    SELECT
      to_char(month, 'YYYY-MM') AS month,
      inflow,
      outflow,
      (inflow - outflow) AS net
    FROM monthly
    ORDER BY month ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    month: r.month,
    inflow: Number(r.inflow),
    outflow: Number(r.outflow),
    net: Number(r.net),
  }));
}

/** Get known future receivables (unpaid customer invoices) */
async function getExpectedReceivables(companyId: string): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM customer_invoices
    WHERE company_id = ${companyId}
      AND status IN ('sent', 'overdue', 'approved')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get known future payables (unpaid supplier invoices) */
async function getExpectedPayables(companyId: string): Promise<Array<{ dueDate: string; amount: number }>> {
  const rows = (await sql`
    SELECT due_date, SUM(total_amount - COALESCE(amount_paid, 0)) AS amount_due
    FROM supplier_invoices
    WHERE company_id = ${companyId}
      AND status IN ('approved', 'received', 'overdue')
      AND due_date >= CURRENT_DATE
      AND (total_amount - COALESCE(amount_paid, 0)) > 0
    GROUP BY due_date
    ORDER BY due_date ASC
  `) as Row[];

  return rows.map((r: Row) => ({
    dueDate: r.due_date,
    amount: Number(r.amount_due),
  }));
}

/** Get recurring invoice amounts for projection */
async function getRecurringRevenue(companyId: string): Promise<number> {
  const rows = (await sql`
    SELECT COALESCE(SUM(total_amount), 0) AS monthly_recurring
    FROM recurring_invoices
    WHERE company_id = ${companyId}
      AND status = 'active'
      AND frequency = 'monthly'
  `) as Row[];
  return Number(rows[0]?.monthly_recurring ?? 0);
}

// ── Forecasting Engine ───────────────────────────────────────────────────────

/**
 * Generate a cash flow forecast for the next N months.
 * Uses a blend of:
 * 1. Known receivables and payables (high confidence)
 * 2. Recurring invoices (medium-high confidence)
 * 3. Historical average patterns (medium confidence)
 * 4. Seasonal adjustment from same month prior year (lower confidence)
 */
export async function generateForecast(companyId: string, 
  forecastMonths = 6,
  alertThreshold = 0
): Promise<CashFlowForecastResult> {
  const [currentBalance, historical, receivables, payables, recurringRevenue] = await Promise.all([
    getCurrentCashBalance(companyId),
    getHistoricalCashFlows(companyId, 12),
    getExpectedReceivables(companyId),
    getExpectedPayables(companyId),
    getRecurringRevenue(companyId),
  ]);

  // Calculate historical averages
  const avgInflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.inflow, 0) / historical.length
    : 0;
  const avgOutflow = historical.length > 0
    ? historical.reduce((sum, h) => sum + h.outflow, 0) / historical.length
    : 0;

  // Build month-by-month forecast
  const forecastPoints: CashFlowForecastPoint[] = [];
  const alerts: CashFlowAlert[] = [];
  let runningBalance = currentBalance;
  const now = new Date();

  for (let i = 1; i <= forecastMonths; i++) {
    const forecastDate = new Date(now.getFullYear(), now.getMonth() + i, 1);
    const monthStr = forecastDate.toISOString().slice(0, 7); // YYYY-MM
    const monthLabel = forecastDate.toLocaleDateString('en-ZA', { month: 'short', year: 'numeric' });

    // Known receivables due this month
    const knownInflows = receivables
      .filter(r => String(r.dueDate).startsWith(monthStr))
      .reduce((sum, r) => sum + r.amount, 0);

    // Known payables due this month
    const knownOutflows = payables
      .filter(p => String(p.dueDate).startsWith(monthStr))
      .reduce((sum, p) => sum + p.amount, 0);

    // Projected inflow: known receivables + recurring revenue + historical average for unknowns
    const knownInflowWeight = knownInflows > 0 ? 0.7 : 0;
    const historicalInflowWeight = 1 - knownInflowWeight;
    const projectedInflow = knownInflows + recurringRevenue + (avgInflow * historicalInflowWeight * 0.5);

    // Projected outflow: known payables + historical average for unknowns
    const knownOutflowWeight = knownOutflows > 0 ? 0.7 : 0;
    const historicalOutflowWeight = 1 - knownOutflowWeight;
    const projectedOutflow = knownOutflows + (avgOutflow * historicalOutflowWeight * 0.5);

    const projectedNet = projectedInflow - projectedOutflow;
    runningBalance += projectedNet;

    // Confidence decreases as we project further out
    const baseConfidence = 0.9;
    const decayFactor = 0.1;
    const knownDataBoost = (knownInflows + knownOutflows > 0) ? 0.1 : 0;
    const confidence = Math.max(0.3, baseConfidence - (i * decayFactor) + knownDataBoost);

    forecastPoints.push({
      date: forecastDate.toISOString().slice(0, 10),
      label: monthLabel,
      projectedInflow: Math.round(projectedInflow * 100) / 100,
      projectedOutflow: Math.round(projectedOutflow * 100) / 100,
      projectedNet: Math.round(projectedNet * 100) / 100,
      projectedBalance: Math.round(runningBalance * 100) / 100,
      confidence: Math.round(confidence * 100) / 100,
    });

    // Generate alerts
    if (runningBalance < alertThreshold) {
      alerts.push({
        type: runningBalance < 0 ? 'danger' : 'warning',
        message: runningBalance < 0
          ? `Projected negative cash balance of R ${Math.abs(runningBalance).toLocaleString('en-ZA', { minimumFractionDigits: 2 })} in ${monthLabel}`
          : `Cash balance projected to drop below threshold in ${monthLabel}`,
        date: forecastDate.toISOString().slice(0, 10),
        projectedBalance: Math.round(runningBalance * 100) / 100,
      });
    }
  }

  // Build assumptions list
  const assumptions: string[] = [];
  if (historical.length > 0) {
    assumptions.push(`Based on ${historical.length} months of historical data`);
  } else {
    assumptions.push('Limited historical data — forecast accuracy may be low');
  }
  if (recurringRevenue > 0) {
    assumptions.push(`Includes R ${recurringRevenue.toLocaleString('en-ZA', { minimumFractionDigits: 2 })} monthly recurring revenue`);
  }
  if (receivables.length > 0) {
    const totalAR = receivables.reduce((s, r) => s + r.amount, 0);
    assumptions.push(`${receivables.length} outstanding invoices totalling R ${totalAR.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  if (payables.length > 0) {
    const totalAP = payables.reduce((s, p) => s + p.amount, 0);
    assumptions.push(`${payables.length} outstanding payables totalling R ${totalAP.toLocaleString('en-ZA', { minimumFractionDigits: 2 })}`);
  }
  assumptions.push('Confidence decreases for months further in the future');

  log.info('Cash flow forecast generated', {
    months: forecastMonths,
    currentBalance,
    pointCount: forecastPoints.length,
    alertCount: alerts.length,
  }, 'accounting');

  return {
    currentBalance: Math.round(currentBalance * 100) / 100,
    forecastPoints,
    alerts,
    assumptions,
    generatedAt: new Date().toISOString(),
  };
}

/** Get historical cash flow data for chart display */
export async function getHistoricalForChart(companyId: string, months = 6): Promise<HistoricalCashFlow[]> {
  return getHistoricalCashFlows(companyId, months);
}

/** Bank Feed Connection Service — Stitch.money OAuth, token management, and connection CRUD. */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { encryptToken, decryptToken } from '@/lib/encryption';

const STITCH_AUTH_URL = 'https://secure.stitch.money/connect/authorize';
export const STITCH_TOKEN_URL = 'https://secure.stitch.money/connect/token';
export const STITCH_GRAPHQL_URL = 'https://api.stitch.money/graphql';

function getConfig() {
  return {
    clientId: process.env.STITCH_CLIENT_ID,
    clientSecret: process.env.STITCH_CLIENT_SECRET,
    redirectUri: process.env.STITCH_REDIRECT_URI,
  };
}

export function isConfigured(): boolean {
  const { clientId, clientSecret, redirectUri } = getConfig();
  return !!(clientId && clientSecret && redirectUri);
}

// Types

export interface BankFeedConnection {
  id: string;
  bankAccountId: string;
  bankAccountName?: string;
  provider: string;
  externalAccountId: string | null;
  bankName: string | null;
  accountNumberMasked: string | null;
  branchCode: string | null;
  accountType: string | null;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
  isActive: boolean;
  createdAt: string;
}

export interface StitchTransaction {
  id: string;
  amount: number;
  runningBalance: number | null;
  description: string;
  reference: string | null;
  date: string;
}

export interface StitchAccount {
  id: string;
  name: string;
  bankId: string;
  accountType: string;
  accountNumber: string;
  branchCode: string;
  currency: string;
  currentBalance: number | null;
  availableBalance: number | null;
}

export interface SyncResult {
  fetched: number;
  imported: number;
  skipped: number;
}

// PKCE helpers

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString('base64url');
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash('sha256').update(verifier).digest('base64url');
}

// OAuth Flow

/** Generate Stitch authorization URL. Store state + codeVerifier in session. */
export function getAuthorizationUrl(): {
  url: string;
  state: string;
  nonce: string;
  codeVerifier: string;
} {
  const { clientId, redirectUri } = getConfig();
  if (!clientId || !redirectUri) {
    throw new Error('Stitch integration not configured. Set STITCH_CLIENT_ID and STITCH_REDIRECT_URI.');
  }

  const state = crypto.randomBytes(16).toString('hex');
  const nonce = crypto.randomBytes(16).toString('hex');
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  const params = new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    scope: 'openid accounts transactions balances offline_access',
    redirect_uri: redirectUri,
    state,
    nonce,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
  });

  return { url: `${STITCH_AUTH_URL}?${params.toString()}`, state, nonce, codeVerifier };
}

/** Exchange authorization code for access + refresh tokens. */
export async function exchangeCode(
  code: string,
  codeVerifier: string,
): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const { clientId, clientSecret, redirectUri } = getConfig();
  if (!clientId || !clientSecret || !redirectUri) {
    throw new Error('Stitch integration not configured');
  }

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: clientId,
      client_secret: clientSecret,
      code,
      redirect_uri: redirectUri,
      code_verifier: codeVerifier,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token exchange failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token exchange failed: ${res.status}`);
  }

  const data = await res.json();
  return { accessToken: data.access_token, refreshToken: data.refresh_token, expiresIn: data.expires_in };
}

/** Refresh an expired access token. */
export async function refreshAccessToken(refreshToken: string): Promise<{
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}> {
  const { clientId, clientSecret } = getConfig();
  if (!clientId || !clientSecret) throw new Error('Stitch integration not configured');

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token refresh failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token refresh failed: ${res.status}`);
  }

  const data = await res.json();
  return {
    accessToken: data.access_token,
    refreshToken: data.refresh_token || refreshToken,
    expiresIn: data.expires_in,
  };
}

// GraphQL

export async function graphqlQuery(
  accessToken: string,
  query: string,
  variables?: Record<string, unknown>,
) {
  const res = await fetch(STITCH_GRAPHQL_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({ query, variables }),
  });
  if (!res.ok) {
    const error = await res.text();
    throw new Error(`GraphQL request failed: ${res.status} — ${error}`);
  }
  const json = await res.json();
  if (json.errors?.length) throw new Error(`GraphQL errors: ${JSON.stringify(json.errors)}`);
  return json.data;
}

/** Fetch linked bank accounts from Stitch. */
export async function fetchStitchAccounts(accessToken: string): Promise<StitchAccount[]> {
  const query = `query { user { bankAccounts { id name bankId accountType accountNumber branchCode currency currentBalance availableBalance } } }`;
  const data = await graphqlQuery(accessToken, query);
  return (data?.user?.bankAccounts ?? []).map((a: Record<string, unknown>) => ({
    id: a.id as string,
    name: a.name as string,
    bankId: a.bankId as string,
    accountType: a.accountType as string,
    accountNumber: a.accountNumber as string,
    branchCode: a.branchCode as string,
    currency: (a.currency as string) || 'ZAR',
    currentBalance: a.currentBalance != null ? Number(a.currentBalance) : null,
    availableBalance: a.availableBalance != null ? Number(a.availableBalance) : null,
  }));
}

// ── Connection CRUD ──────────────────────────────────────────────────────────

export async function listConnections(): Promise<BankFeedConnection[]> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    ORDER BY bfc.created_at DESC
  `) as Record<string, unknown>[];
  return rows.map(mapConnection);
}

export async function getConnection(id: string): Promise<BankFeedConnection | null> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${id}::UUID
  `) as Record<string, unknown>[];
  return rows[0] ? mapConnection(rows[0]) : null;
}

export async function createConnection(input: {
  bankAccountId: string;
  externalAccountId: string;
  bankName?: string;
  accountNumberMasked?: string;
  branchCode?: string;
  accountType?: string;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  createdBy: string;
}): Promise<BankFeedConnection> {
  const expiresAt = new Date(Date.now() + input.expiresIn * 1000).toISOString();
  const rows = (await sql`
    INSERT INTO bank_feed_connections (
      bank_account_id, provider, external_account_id, bank_name,
      account_number_masked, branch_code, account_type,
      access_token, refresh_token, token_expires_at, sync_status, created_by
    ) VALUES (
      ${input.bankAccountId}::UUID, 'stitch', ${input.externalAccountId},
      ${input.bankName || null}, ${input.accountNumberMasked || null},
      ${input.branchCode || null}, ${input.accountType || null},
      ${encryptToken(input.accessToken)}, ${encryptToken(input.refreshToken)}, ${expiresAt}::TIMESTAMPTZ,
      'pending', ${input.createdBy}::UUID
    ) RETURNING *
  `) as Record<string, unknown>[];
  log.info('Bank feed connection created', { id: rows[0].id, bankName: input.bankName }, 'bank-feeds');
  return mapConnection(rows[0]);
}

export async function disconnectConnection(id: string): Promise<void> {
  await sql`UPDATE bank_feed_connections SET is_active = false, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Bank feed disconnected', { id }, 'bank-feeds');
}

// ── Mapper ────────────────────────────────────────────────────────────────────

export function mapConnection(r: Record<string, unknown>): BankFeedConnection {
  return {
    id: r.id,
    bankAccountId: r.bank_account_id,
    bankAccountName: r.bank_account_name || undefined,
    provider: r.provider,
    externalAccountId: r.external_account_id,
    bankName: r.bank_name,
    accountNumberMasked: r.account_number_masked,
    branchCode: r.branch_code,
    accountType: r.account_type,
    lastSyncAt: r.last_sync_at,
    syncStatus: r.sync_status,
    syncError: r.sync_error,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

/**
 * PRD-060 Phase 6: Sage Migration Service
 * Status, account mapping, comparison, reset + re-exports importers
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

// Re-export importers so API routes import from one place
export { importLedgerTransactions, importSupplierInvoices } from './sageImportService';
export { importCustomerInvoices } from './sageCustomerImportService';

type Row = Record<string, unknown>;

// ── Types ───────────────────────────────────────────────────────────────────

export interface MigrationStatus {
  accounts: { sageTotal: number; mapped: number; unmapped: number; autoMapped: number };
  ledger: { sageTotal: number; imported: number; pending: number; failed: number; dateRange: { earliest: string | null; latest: string | null } };
  invoices: { sageTotal: number; imported: number; pending: number; failed: number };
  customerInvoices: { sageTotal: number; imported: number; pending: number; failed: number };
  lastRuns: MigrationRun[];
}

export interface MigrationRun {
  id: string; runType: string; status: string; totalRecords: number;
  processed: number; succeeded: number; failed: number; skipped: number;
  startedAt: string; completedAt: string | null;
}

export interface AccountMapping {
  sageAccountId: string; sageName: string; sageType: number | null; sageBalance: number;
  glAccountId: string | null; glAccountCode: string | null; glAccountName: string | null;
  mappingStatus: string; mappingNotes: string | null;
}

export interface ComparisonReport {
  comparisonDate: string;
  sageTotals: { totalDebit: number; totalCredit: number; accountCount: number };
  glTotals: { totalDebit: number; totalCredit: number; accountCount: number };
  differences: Array<{ accountCode: string; accountName: string; sageBalance: number; glBalance: number; difference: number }>;
  isBalanced: boolean;
}

// ── Run Tracking (exported for sageImportService) ───────────────────────────

export async function startRun(runType: string, userId: string): Promise<string> {
  const rows = (await sql`
    INSERT INTO gl_migration_runs (run_type, status, started_by)
    VALUES (${runType}, 'running', ${userId})
    RETURNING id
  `) as Row[];
  if (!rows[0]) throw new Error('Failed to create migration run');
  return String(rows[0].id);
}

export async function completeRun(
  runId: string, total: number, succeeded: number, failed: number, skipped: number
): Promise<MigrationRun> {
  const status = failed === 0 ? 'completed' : 'partial';
  const rows = (await sql`
    UPDATE gl_migration_runs
    SET status = ${status}, total_records = ${total}, processed = ${succeeded + failed + skipped},
        succeeded = ${succeeded}, failed = ${failed}, skipped = ${skipped}, completed_at = NOW()
    WHERE id = ${runId}::UUID RETURNING *
  `) as Row[];
  if (!rows[0]) throw new Error('Migration run not found');
  const r = rows[0];
  return {
    id: String(r.id), runType: String(r.run_type), status: String(r.status),
    totalRecords: Number(r.total_records), processed: Number(r.processed),
    succeeded: Number(r.succeeded), failed: Number(r.failed), skipped: Number(r.skipped),
    startedAt: String(r.started_at), completedAt: r.completed_at ? String(r.completed_at) : null,
  };
}

export async function failRun(runId: string, err: unknown): Promise<void> {
  const msg = err instanceof Error ? err.message : 'Unknown error';
  await sql`
    UPDATE gl_migration_runs SET status = 'failed', error_message = ${msg}, completed_at = NOW()
    WHERE id = ${runId}::UUID
  `;
}

// ── Migration Status ────────────────────────────────────────────────────────

export async function getMigrationStatus(companyId: string): Promise<MigrationStatus> {
  try {
    const accountStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE gl_account_id IS NOT NULL) AS mapped,
        COUNT(*) FILTER (WHERE gl_account_id IS NULL) AS unmapped,
        COUNT(*) FILTER (WHERE mapping_status = 'auto') AS auto_mapped
      FROM sage_accounts
    `) as Row[];

    const ledgerStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
        COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed,
        MIN(transaction_date) AS earliest, MAX(transaction_date) AS latest
      FROM sage_ledger_transactions
    `) as Row[];

    const invoiceStats = (await sql`
      SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
        COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
        COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed
      FROM sage_supplier_invoices
    `) as Row[];

    let customerInvoiceStats: Row[] = [{ total: 0, imported: 0, pending: 0, failed: 0 }];
    try {
      customerInvoiceStats = (await sql`
        SELECT COUNT(*) AS total, COUNT(*) FILTER (WHERE migration_status = 'imported') AS imported,
          COUNT(*) FILTER (WHERE migration_status = 'pending') AS pending,
          COUNT(*) FILTER (WHERE migration_status = 'failed') AS failed
        FROM sage_customer_invoices
      `) as Row[];
    } catch {
      // Table may not exist yet if migration 212 hasn't run
    }

    const runs = (await sql`
      SELECT id, run_type, status, total_records, processed, succeeded, failed, skipped,
        started_at, completed_at
      FROM gl_migration_runs ORDER BY started_at DESC LIMIT 10
    `) as Row[];

    return {
      accounts: {
        sageTotal: Number(accountStats[0]?.total || 0), mapped: Number(accountStats[0]?.mapped || 0),
        unmapped: Number(accountStats[0]?.unmapped || 0), autoMapped: Number(accountStats[0]?.auto_mapped || 0),
      },
      ledger: {
        sageTotal: Number(ledgerStats[0]?.total || 0), imported: Number(ledgerStats[0]?.imported || 0),
        pending: Number(ledgerStats[0]?.pending || 0), failed: Number(ledgerStats[0]?.failed || 0),
        dateRange: { earliest: ledgerStats[0]?.earliest || null, latest: ledgerStats[0]?.latest || null },
      },
      invoices: {
        sageTotal: Number(invoiceStats[0]?.total || 0), imported: Number(invoiceStats[0]?.imported || 0),
        pending: Number(invoiceStats[0]?.pending || 0), failed: Number(invoiceStats[0]?.failed || 0),
      },
      customerInvoices: {
        sageTotal: Number(customerInvoiceStats[0]?.total || 0),
        imported: Number(customerInvoiceStats[0]?.imported || 0),
        pending: Number(customerInvoiceStats[0]?.pending || 0),
        failed: Number(customerInvoiceStats[0]?.failed || 0),
      },
      lastRuns: runs.map((r: Row) => ({
        id: String(r.id), runType: String(r.run_type), status: String(r.status),
        totalRecords: Number(r.total_records), processed: Number(r.processed),
        succeeded: Number(r.succeeded), failed: Number(r.failed), skipped: Number(r.skipped),
        startedAt: String(r.started_at), completedAt: r.completed_at ? String(r.completed_at) : null,
      })),
    };
  } catch (err) {
    log.error('Failed to get migration status', { error: err }, 'accounting');
    throw err;
  }
}

// ── Account Mapping ─────────────────────────────────────────────────────────

export async function getAccountMappings(companyId: string): Promise<AccountMapping[]> {
  const rows = (await sql`
    SELECT sa.sage_account_id, sa.name, sa.account_type, sa.balance,
      sa.gl_account_id, sa.mapping_status, sa.mapping_notes,
      ga.account_code, ga.account_name
    FROM sage_accounts sa LEFT JOIN gl_accounts ga ON ga.id = sa.gl_account_id
    ORDER BY sa.name
  `) as Row[];

  return rows.map((r: Row) => ({
    sageAccountId: String(r.sage_account_id), sageName: String(r.name),
    sageType: r.account_type != null ? Number(r.account_type) : null,
    sageBalance: Number(r.balance || 0),
    glAccountId: r.gl_account_id ? String(r.gl_account_id) : null,
    glAccountCode: r.account_code ? String(r.account_code) : null,
    glAccountName: r.account_name ? String(r.account_name) : null,
    mappingStatus: String(r.mapping_status || 'unmapped'),
    mappingNotes: r.mapping_notes ? String(r.mapping_notes) : null,
  }));
}

function nameSimilarity(a: string, b: string): number {
  const tokensA = new Set(a.split(/[\s\-_&/]+/).filter(Boolean));
  const tokensB = new Set(b.split(/[\s\-_&/]+/).filter(Boolean));
  if (tokensA.size === 0 || tokensB.size === 0) return 0;
  let overlap = 0;
  for (const t of tokensA) {
    if (tokensB.has(t)) overlap++;
    else { for (const tb of tokensB) { if (tb.includes(t) || t.includes(tb)) { overlap += 0.5; break; } } }
  }
  return overlap / Math.max(tokensA.size, tokensB.size);
}

export async function autoMapAccounts(companyId: string, userId: string): Promise<MigrationRun> {
  const runId = await startRun('account_mapping', userId);
  try {
    const sageAccounts = (await sql`
      SELECT id, sage_account_id, name, account_type, balance FROM sage_accounts WHERE gl_account_id IS NULL ORDER BY name
    `) as Row[];
    const glAccounts = (await sql`
      SELECT id, account_code, account_name, account_type FROM gl_accounts WHERE level >= 3 AND is_active = true ORDER BY account_code
    `) as Row[];

    let succeeded = 0; let skipped = 0;
    const typeMap: Record<number, string> = { 1: 'revenue', 2: 'expense', 5: 'asset', 6: 'liability', 7: 'equity' };

    for (const sage of sageAccounts) {
      const sageName = String(sage.name).toLowerCase().trim();
      const sageType = sage.account_type != null ? typeMap[Number(sage.account_type)] : null;
      let bestMatch: Row | null = null; let bestScore = 0;

      for (const gl of glAccounts) {
        if (sageType && String(gl.account_type) !== sageType) continue;
        const score = nameSimilarity(sageName, String(gl.account_name).toLowerCase().trim());
        if (score > bestScore && score >= 0.6) { bestScore = score; bestMatch = gl; }
      }

      if (bestMatch) {
        await sql`
          UPDATE sage_accounts SET gl_account_id = ${bestMatch.id}::UUID, mapping_status = 'auto',
            mapping_notes = ${`Auto-mapped (${(bestScore * 100).toFixed(0)}% match) to ${bestMatch.account_code}`}
          WHERE id = ${sage.id}
        `;
        succeeded++;
      } else { skipped++; }
    }
    return await completeRun(runId, sageAccounts.length, succeeded, 0, skipped);
  } catch (err) { await failRun(runId, err); throw err; }
}

export async function mapAccount(companyId: string, sageAccountId: string, glAccountId: string | null, notes?: string): Promise<void> {
  if (glAccountId) {
    await sql`UPDATE sage_accounts SET gl_account_id = ${glAccountId}::UUID, mapping_status = 'manual',
      mapping_notes = ${notes || 'Manually mapped'} WHERE sage_account_id = ${sageAccountId}`;
  } else {
    await sql`UPDATE sage_accounts SET gl_account_id = NULL, mapping_status = 'unmapped',
      mapping_notes = ${notes || null} WHERE sage_account_id = ${sageAccountId}`;
  }
}

// ── Comparison ──────────────────────────────────────────────────────────────

export async function generateComparison(companyId: string, userId: string): Promise<ComparisonReport> {
  try {
    const sageBalances = (await sql`
      SELECT sa.sage_account_id, sa.name, sa.balance, ga.account_code, ga.account_name, ga.id AS gl_id
      FROM sage_accounts sa JOIN gl_accounts ga ON ga.id = sa.gl_account_id ORDER BY ga.account_code
    `) as Row[];

    const glBalances = (await sql`
      SELECT ga.id, ga.account_code, ga.account_name, ga.normal_balance,
        COALESCE(SUM(jl.debit), 0) AS total_debit, COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_accounts ga
      LEFT JOIN gl_journal_lines jl ON jl.gl_account_id = ga.id
      LEFT JOIN gl_journal_entries je ON je.id = jl.journal_entry_id AND je.status = 'posted'
      WHERE ga.level >= 3 GROUP BY ga.id, ga.account_code, ga.account_name, ga.normal_balance ORDER BY ga.account_code
    `) as Row[];

    const glMap = new Map<string, number>();
    let glTotalDebit = 0; let glTotalCredit = 0;
    for (const gl of glBalances) {
      const d = Number(gl.total_debit), c = Number(gl.total_credit);
      glMap.set(String(gl.id), String(gl.normal_balance) === 'debit' ? d - c : c - d);
      glTotalDebit += d; glTotalCredit += c;
    }

    const differences: ComparisonReport['differences'] = [];
    let sageTotalDebit = 0; let sageTotalCredit = 0;
    for (const sage of sageBalances) {
      const sb = Number(sage.balance || 0), gb = glMap.get(String(sage.gl_id)) || 0;
      if (sb > 0) sageTotalDebit += sb; else sageTotalCredit += Math.abs(sb);
      if (Math.abs(sb - gb) > 0.01) {
        differences.push({ accountCode: String(sage.account_code), accountName: String(sage.account_name), sageBalance: sb, glBalance: gb, difference: sb - gb });
      }
    }

    const report: ComparisonReport = {
      comparisonDate: new Date().toISOString().slice(0, 10),
      sageTotals: { totalDebit: sageTotalDebit, totalCredit: sageTotalCredit, accountCount: sageBalances.length },
      glTotals: { totalDebit: glTotalDebit, totalCredit: glTotalCredit, accountCount: glBalances.length },
      differences, isBalanced: differences.length === 0,
    };

    await sql`
      INSERT INTO gl_migration_comparisons (comparison_date, sage_totals, gl_totals, differences, is_balanced, created_by)
      VALUES (${report.comparisonDate}, ${JSON.stringify(report.sageTotals)}, ${JSON.stringify(report.glTotals)},
        ${JSON.stringify(report.differences)}, ${report.isBalanced}, ${userId})
    `;
    return report;
  } catch (err) { log.error('Failed to generate comparison', { error: err }, 'accounting'); throw err; }
}

