/**
 * Phase 3: Transaction-Level Reporting Service
 * Customer, Supplier, Banking, Account, and Audit Trail reports
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccount } from './systemAccountResolver';

type Row = Record<string, unknown>;

interface TransactionRow {
  date: string;
  entryNumber: string;
  description: string;
  debit: number;
  credit: number;
  balance: number;
  source: string;
}

// ── Customer Report ─────────────────────────────────────────────────────────

export interface CustomerReportRow {
  clientId: string;
  clientName: string;
  invoiceCount: number;
  totalInvoiced: number;
  totalPaid: number;
  balance: number;
}

export async function getCustomerReport(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<CustomerReportRow[]> {
  try {
    const rows = (await sql`
      SELECT
        c.id AS client_id,
        c.name AS client_name,
        COUNT(DISTINCT ci.id) AS invoice_count,
        COALESCE(SUM(ci.total_amount), 0) AS total_invoiced,
        COALESCE(SUM(ci.amount_paid), 0) AS total_paid
      FROM customers c
      LEFT JOIN customer_invoices ci ON ci.client_id = c.id
        AND ci.invoice_date >= ${periodStart}
        AND ci.invoice_date <= ${periodEnd}
        AND ci.status NOT IN ('draft', 'cancelled')
      GROUP BY c.id, c.name
      HAVING COUNT(ci.id) > 0
      ORDER BY COALESCE(SUM(ci.total_amount), 0) DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      clientId: String(r.client_id),
      clientName: String(r.client_name),
      invoiceCount: Number(r.invoice_count),
      totalInvoiced: Number(r.total_invoiced),
      totalPaid: Number(r.total_paid),
      balance: Number(r.total_invoiced) - Number(r.total_paid),
    }));
  } catch (err) {
    log.error('Failed to generate customer report', { error: err }, 'accounting');
    throw err;
  }
}

// ── Supplier Report ─────────────────────────────────────────────────────────

export interface SupplierReportRow {
  supplierId: string;
  supplierName: string;
  invoiceCount: number;
  totalInvoiced: number;
  totalPaid: number;
  balance: number;
}

export async function getSupplierReport(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<SupplierReportRow[]> {
  try {
    const rows = (await sql`
      SELECT
        s.id AS supplier_id,
        COALESCE(s.company_name, s.name) AS supplier_name,
        COUNT(DISTINCT si.id) AS invoice_count,
        COALESCE(SUM(si.total_amount), 0) AS total_invoiced,
        COALESCE(SUM(si.amount_paid), 0) AS total_paid
      FROM suppliers s
      LEFT JOIN supplier_invoices si ON si.supplier_id = s.id
        AND si.invoice_date >= ${periodStart}
        AND si.invoice_date <= ${periodEnd}
        AND si.status NOT IN ('draft', 'cancelled')
      GROUP BY s.id, s.company_name, s.name
      HAVING COUNT(si.id) > 0
      ORDER BY COALESCE(SUM(si.total_amount), 0) DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      supplierId: String(r.supplier_id),
      supplierName: String(r.supplier_name),
      invoiceCount: Number(r.invoice_count),
      totalInvoiced: Number(r.total_invoiced),
      totalPaid: Number(r.total_paid),
      balance: Number(r.total_invoiced) - Number(r.total_paid),
    }));
  } catch (err) {
    log.error('Failed to generate supplier report', { error: err }, 'accounting');
    throw err;
  }
}

// ── Bank Transactions ───────────────────────────────────────────────────────

export interface BankTransactionRow {
  date: string;
  entryNumber: string;
  description: string;
  deposit: number;
  withdrawal: number;
  runningBalance: number;
}

export interface BankTransactionsReport {
  accountCode: string;
  accountName: string;
  periodStart: string;
  periodEnd: string;
  openingBalance: number;
  closingBalance: number;
  transactions: BankTransactionRow[];
}

export async function getBankTransactions(companyId: string, 
  periodStart: string,
  periodEnd: string,
  accountCode?: string
): Promise<BankTransactionsReport> {
  try {
    const bankCode = accountCode || (await getSystemAccount('bank')).accountCode;

    // Opening balance (all posted entries before period start)
    const obRows = (await sql`
      SELECT
        COALESCE(SUM(jl.debit), 0) - COALESCE(SUM(jl.credit), 0) AS balance
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date < ${periodStart}
        AND ga.account_code = ${bankCode}
    `) as Row[];
    const openingBalance = Number(obRows[0]?.balance || 0);

    // Transactions in period
    const txnRows = (await sql`
      SELECT
        je.entry_date, je.entry_number, je.description, je.source,
        jl.debit, jl.credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND ga.account_code = ${bankCode}
      ORDER BY je.entry_date, je.created_at
    `) as Row[];

    // Get account name
    const acctRows = (await sql`
      SELECT account_name FROM gl_accounts WHERE account_code = ${bankCode} LIMIT 1
    `) as Row[];

    let running = openingBalance;
    const transactions: BankTransactionRow[] = txnRows.map((r: Row) => {
      const dep = Number(r.debit || 0);
      const wd = Number(r.credit || 0);
      running += dep - wd;
      return {
        date: String(r.entry_date).split('T')[0] ?? '',
        entryNumber: String(r.entry_number),
        description: String(r.description || ''),
        deposit: dep,
        withdrawal: wd,
        runningBalance: running,
      };
    });

    return {
      accountCode: bankCode,
      accountName: String(acctRows[0]?.account_name || 'Bank'),
      periodStart,
      periodEnd,
      openingBalance,
      closingBalance: running,
      transactions,
    };
  } catch (err) {
    log.error('Failed to generate bank transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Account Transactions ────────────────────────────────────────────────────

export interface AccountTransactionsReport {
  accountCode: string;
  accountName: string;
  accountType: string;
  periodStart: string;
  periodEnd: string;
  openingBalance: number;
  closingBalance: number;
  transactions: TransactionRow[];
}

export async function getAccountTransactions(
  companyId: string,
  accountCode: string,
  periodStart: string,
  periodEnd: string
): Promise<AccountTransactionsReport> {
  try {
    const acctRows = (await sql`
      SELECT account_name, account_type, normal_balance
      FROM gl_accounts WHERE account_code = ${accountCode} LIMIT 1
    `) as Row[];
    if (!acctRows[0]) throw new Error(`Account ${accountCode} not found`);

    const normalBal = String(acctRows[0].normal_balance);

    // Opening balance
    const obRows = (await sql`
      SELECT
        COALESCE(SUM(jl.debit), 0) AS total_debit,
        COALESCE(SUM(jl.credit), 0) AS total_credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date < ${periodStart}
        AND ga.account_code = ${accountCode}
    `) as Row[];

    const obDebit = Number(obRows[0]?.total_debit || 0);
    const obCredit = Number(obRows[0]?.total_credit || 0);
    const openingBalance = normalBal === 'debit' ? obDebit - obCredit : obCredit - obDebit;

    // Transactions
    const txnRows = (await sql`
      SELECT
        je.entry_date, je.entry_number, je.description, je.source,
        jl.debit, jl.credit
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND ga.account_code = ${accountCode}
      ORDER BY je.entry_date, je.created_at
    `) as Row[];

    let running = openingBalance;
    const transactions: TransactionRow[] = txnRows.map((r: Row) => {
      const d = Number(r.debit || 0);
      const c = Number(r.credit || 0);
      running += normalBal === 'debit' ? d - c : c - d;
      const rawDate = r.entry_date instanceof Date
        ? r.entry_date.toISOString().split('T')[0]
        : String(r.entry_date || '').split('T')[0];
      return {
        date: rawDate,
        entryNumber: String(r.entry_number),
        description: String(r.description || ''),
        debit: d,
        credit: c,
        balance: running,
        source: String(r.source || 'manual'),
      };
    });

    return {
      accountCode,
      accountName: String(acctRows[0].account_name),
      accountType: String(acctRows[0].account_type),
      periodStart,
      periodEnd,
      openingBalance,
      closingBalance: running,
      transactions,
    };
  } catch (err) {
    log.error('Failed to generate account transactions', { error: err }, 'accounting');
    throw err;
  }
}

// ── Audit Trail ─────────────────────────────────────────────────────────────

export interface AuditTrailRow {
  entryDate: string;
  entryNumber: string;
  description: string;
  source: string;
  status: string;
  totalDebit: number;
  totalCredit: number;
  createdBy: string;
  createdAt: string;
  postedAt: string | null;
}

export async function getAuditTrail(companyId: string, 
  periodStart: string,
  periodEnd: string
): Promise<AuditTrailRow[]> {
  try {
    const rows = (await sql`
      SELECT
        je.entry_date, je.entry_number, je.description, je.source, je.status,
        COALESCE(SUM(jl.debit), 0) AS total_debit,
        COALESCE(SUM(jl.credit), 0) AS total_credit,
        COALESCE(CONCAT_WS(' ', u.first_name, u.last_name), je.created_by::TEXT) AS created_by_name,
        je.created_at, je.posted_at
      FROM gl_journal_entries je
      LEFT JOIN gl_journal_lines jl ON jl.journal_entry_id = je.id
      LEFT JOIN users u ON u.id::TEXT = je.created_by::TEXT
      WHERE je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
      GROUP BY je.id, je.entry_date, je.entry_number, je.description,
        je.source, je.status, u.first_name, u.last_name, je.created_by, je.created_at, je.posted_at
      ORDER BY je.created_at DESC
    `) as Row[];

    return rows.map((r: Row) => ({
      entryDate: r.entry_date instanceof Date
        ? r.entry_date.toISOString().split('T')[0]!
        : String(r.entry_date || '').split('T')[0]!,
      entryNumber: String(r.entry_number),
      description: String(r.description || ''),
      source: String(r.source || 'manual'),
      status: String(r.status),
      totalDebit: Number(r.total_debit || 0),
      totalCredit: Number(r.total_credit || 0),
      createdBy: String(r.created_by_name || '—'),
      createdAt: String(r.created_at),
      postedAt: r.posted_at ? String(r.posted_at) : null,
    }));
  } catch (err) {
    log.error('Failed to generate audit trail', { error: err }, 'accounting');
    throw err;
  }
}

/** Bank Feed Connection Service — Stitch.money OAuth, token management, and connection CRUD. */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import crypto from 'crypto';
import { encryptToken, decryptToken } from '@/lib/encryption';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

const STITCH_AUTH_URL = 'https://secure.stitch.money/connect/authorize';
export const STITCH_TOKEN_URL = 'https://secure.stitch.money/connect/token';
export const STITCH_GRAPHQL_URL = 'https://api.stitch.money/graphql';

function getConfig() {
  return {
    clientId: process.env.STITCH_CLIENT_ID,
    clientSecret: process.env.STITCH_CLIENT_SECRET,
    redirectUri: process.env.STITCH_REDIRECT_URI,
  };
}

export function isConfigured(): boolean {
  const { clientId, clientSecret, redirectUri } = getConfig();
  return !!(clientId && clientSecret && redirectUri);
}

// Types

export interface BankFeedConnection {
  id: string;
  bankAccountId: string;
  bankAccountName?: string;
  provider: string;
  externalAccountId: string | null;
  bankName: string | null;
  accountNumberMasked: string | null;
  branchCode: string | null;
  accountType: string | null;
  lastSyncAt: string | null;
  syncStatus: string;
  syncError: string | null;
  isActive: boolean;
  createdAt: string;
}

export interface StitchTransaction {
  id: string;
  amount: number;
  runningBalance: number | null;
  description: string;
  reference: string | null;
  date: string;
}

export interface StitchAccount {
  id: string;
  name: string;
  bankId: string;
  accountType: string;
  accountNumber: string;
  branchCode: string;
  currency: string;
  currentBalance: number | null;
  availableBalance: number | null;
}

export interface SyncResult {
  fetched: number;
  imported: number;
  skipped: number;
}

// PKCE helpers

function generateCodeVerifier(): string {
  return crypto.randomBytes(32).toString('base64url');
}

function generateCodeChallenge(verifier: string): string {
  return crypto.createHash('sha256').update(verifier).digest('base64url');
}

// OAuth Flow

/** Generate Stitch authorization URL. Store state + codeVerifier in session. */
export function getAuthorizationUrl(): {
  url: string;
  state: string;
  nonce: string;
  codeVerifier: string;
} {
  const { clientId, redirectUri } = getConfig();
  if (!clientId || !redirectUri) {
    throw new Error('Stitch integration not configured. Set STITCH_CLIENT_ID and STITCH_REDIRECT_URI.');
  }

  const state = crypto.randomBytes(16).toString('hex');
  const nonce = crypto.randomBytes(16).toString('hex');
  const codeVerifier = generateCodeVerifier();
  const codeChallenge = generateCodeChallenge(codeVerifier);

  const params = new URLSearchParams({
    client_id: clientId,
    response_type: 'code',
    scope: 'openid accounts transactions balances offline_access',
    redirect_uri: redirectUri,
    state,
    nonce,
    code_challenge: codeChallenge,
    code_challenge_method: 'S256',
  });

  return { url: `${STITCH_AUTH_URL}?${params.toString()}`, state, nonce, codeVerifier };
}

/** Exchange authorization code for access + refresh tokens. */
export async function exchangeCode(
  code: string,
  codeVerifier: string,
): Promise<{ accessToken: string; refreshToken: string; expiresIn: number }> {
  const { clientId, clientSecret, redirectUri } = getConfig();
  if (!clientId || !clientSecret || !redirectUri) {
    throw new Error('Stitch integration not configured');
  }

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      client_id: clientId,
      client_secret: clientSecret,
      code,
      redirect_uri: redirectUri,
      code_verifier: codeVerifier,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token exchange failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token exchange failed: ${res.status}`);
  }

  const data = await res.json();
  return { accessToken: data.access_token, refreshToken: data.refresh_token, expiresIn: data.expires_in };
}

/** Refresh an expired access token. */
export async function refreshAccessToken(refreshToken: string): Promise<{
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
}> {
  const { clientId, clientSecret } = getConfig();
  if (!clientId || !clientSecret) throw new Error('Stitch integration not configured');

  const res = await fetch(STITCH_TOKEN_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'refresh_token',
      client_id: clientId,
      client_secret: clientSecret,
      refresh_token: refreshToken,
    }),
  });

  if (!res.ok) {
    const error = await res.text();
    log.error('Stitch token refresh failed', { status: res.status, error }, 'bank-feeds');
    throw new Error(`Token refresh failed: ${res.status}`);
  }

  const data = await res.json();
  return {
    accessToken: data.access_token,
    refreshToken: data.refresh_token || refreshToken,
    expiresIn: data.expires_in,
  };
}

// GraphQL

export async function graphqlQuery(
  accessToken: string,
  query: string,
  variables?: Record<string, unknown>,
) {
  const res = await fetch(STITCH_GRAPHQL_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${accessToken}` },
    body: JSON.stringify({ query, variables }),
  });
  if (!res.ok) {
    const error = await res.text();
    throw new Error(`GraphQL request failed: ${res.status} — ${error}`);
  }
  const json = await res.json();
  if (json.errors?.length) throw new Error(`GraphQL errors: ${JSON.stringify(json.errors)}`);
  return json.data;
}

/** Fetch linked bank accounts from Stitch. */
export async function fetchStitchAccounts(accessToken: string): Promise<StitchAccount[]> {
  const query = `query { user { bankAccounts { id name bankId accountType accountNumber branchCode currency currentBalance availableBalance } } }`;
  const data = await graphqlQuery(accessToken, query);
  return (data?.user?.bankAccounts ?? []).map((a: Record<string, unknown>) => ({
    id: a.id as string,
    name: a.name as string,
    bankId: a.bankId as string,
    accountType: a.accountType as string,
    accountNumber: a.accountNumber as string,
    branchCode: a.branchCode as string,
    currency: (a.currency as string) || 'ZAR',
    currentBalance: a.currentBalance != null ? Number(a.currentBalance) : null,
    availableBalance: a.availableBalance != null ? Number(a.availableBalance) : null,
  }));
}

// Connection CRUD

export async function listConnections(): Promise<BankFeedConnection[]> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    ORDER BY bfc.created_at DESC
  `) as Row[];
  return rows.map(mapConnection);
}

export async function getConnection(id: string): Promise<BankFeedConnection | null> {
  const rows = (await sql`
    SELECT bfc.*, ba.account_name AS bank_account_name
    FROM bank_feed_connections bfc
    LEFT JOIN bank_accounts ba ON ba.id = bfc.bank_account_id
    WHERE bfc.id = ${id}::UUID
  `) as Row[];
  return rows[0] ? mapConnection(rows[0]) : null;
}

export async function createConnection(input: {
  bankAccountId: string;
  externalAccountId: string;
  bankName?: string;
  accountNumberMasked?: string;
  branchCode?: string;
  accountType?: string;
  accessToken: string;
  refreshToken: string;
  expiresIn: number;
  createdBy: string;
}): Promise<BankFeedConnection> {
  const expiresAt = new Date(Date.now() + input.expiresIn * 1000).toISOString();
  const rows = (await sql`
    INSERT INTO bank_feed_connections (
      bank_account_id, provider, external_account_id, bank_name,
      account_number_masked, branch_code, account_type,
      access_token, refresh_token, token_expires_at, sync_status, created_by
    ) VALUES (
      ${input.bankAccountId}::UUID, 'stitch', ${input.externalAccountId},
      ${input.bankName || null}, ${input.accountNumberMasked || null},
      ${input.branchCode || null}, ${input.accountType || null},
      ${encryptToken(input.accessToken)}, ${encryptToken(input.refreshToken)}, ${expiresAt}::TIMESTAMPTZ,
      'pending', ${input.createdBy}::UUID
    ) RETURNING *
  `) as Row[];
  log.info('Bank feed connection created', { id: rows[0].id, bankName: input.bankName }, 'bank-feeds');
  return mapConnection(rows[0]);
}

export async function disconnectConnection(id: string): Promise<void> {
  await sql`UPDATE bank_feed_connections SET is_active = false, updated_at = NOW() WHERE id = ${id}::UUID`;
  log.info('Bank feed disconnected', { id }, 'bank-feeds');
}

// Mapper

export function mapConnection(r: Record<string, unknown>): BankFeedConnection {
  return {
    id: r.id,
    bankAccountId: r.bank_account_id,
    bankAccountName: r.bank_account_name || undefined,
    provider: r.provider,
    externalAccountId: r.external_account_id,
    bankName: r.bank_name,
    accountNumberMasked: r.account_number_masked,
    branchCode: r.branch_code,
    accountType: r.account_type,
    lastSyncAt: r.last_sync_at,
    syncStatus: r.sync_status,
    syncError: r.sync_error,
    isActive: r.is_active,
    createdAt: r.created_at,
  };
}

