    entryDate: todayStr(),
    hours: '',
    rate: '',
    billable: true,
    customerId: '',
    notes: '',
  });

  // Load customers once
  useEffect(() => {
    apiFetch('/api/accounting/customers').then(r => r.json()).then(res => {
      const d = res.data || res;
      const list = Array.isArray(d) ? d : d.items || [];
      setCustomers(list.map((c: Record<string, unknown>) => ({
        id: String(c.id),
        companyName: String(c.companyName || c.company_name || ''),
      })));
    }).catch(() => { /* ignore */ });
  }, []);

  const loadEntries = useCallback(async () => {
    setLoading(true);
    setError('');
    const params = new URLSearchParams();
    if (tab === 'my-time') params.set('userId', 'me');
    if (filterStatus) params.set('status', filterStatus);
    if (filterProject) params.set('projectName', filterProject);
    if (filterCustomer) params.set('customerId', filterCustomer);
    if (filterBillable) params.set('billable', filterBillable);
    if (filterDateFrom) params.set('dateFrom', filterDateFrom);
    if (filterDateTo) params.set('dateTo', filterDateTo);
    params.set('limit', '100');

    try {
      const res = await apiFetch(`/api/accounting/time-entries?${params}`);
      const json = await res.json();
      const d = json.data || json;
      setEntries(d.entries || []);
      setTotal(d.total || 0);
    } catch {
      setError('Failed to load time entries');
    }
    setLoading(false);
  }, [tab, filterStatus, filterProject, filterCustomer, filterBillable, filterDateFrom, filterDateTo]);

  const loadSummary = useCallback(async () => {
    setLoading(true);
    const params = new URLSearchParams();
    if (filterDateFrom) params.set('dateFrom', filterDateFrom);
    if (filterDateTo) params.set('dateTo', filterDateTo);
    try {
      const res = await apiFetch(`/api/accounting/time-summary?${params}`);
      const json = await res.json();
      setSummary(json.data || null);
    } catch {
      setError('Failed to load summary');
    }
    setLoading(false);
  }, [filterDateFrom, filterDateTo]);

  useEffect(() => {
    if (tab === 'summary') {
      loadSummary();
    } else {
      loadEntries();
    }
  }, [tab, loadEntries, loadSummary]);

  const resetForm = () => {
    setForm({ projectName: '', taskDescription: '', entryDate: todayStr(), hours: '', rate: '', billable: true, customerId: '', notes: '' });
    setEditId(null);
  };

  const handleSubmitForm = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(''); setBusy('save');
    try {
      const body: Record<string, unknown> = {
        projectName: form.projectName || undefined,
        taskDescription: form.taskDescription,
        entryDate: form.entryDate,
        hours: Number(form.hours),
        rate: form.rate ? Number(form.rate) : undefined,
        billable: form.billable,
        customerId: form.customerId || undefined,
        notes: form.notes || undefined,
      };

      let res;
      if (editId) {
        res = await apiFetch('/api/accounting/time-entries', {
          method: 'PUT',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ id: editId, ...body }),
        });
      } else {
        res = await apiFetch('/api/accounting/time-entries', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        });
      }

      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setSuccess(editId ? 'Entry updated' : 'Entry created');
      setShowForm(false);
      resetForm();
      await loadEntries();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Save failed');
    } finally { setBusy(''); }
  };

  const handleDelete = async (id: string) => {
    if (!confirm('Delete this time entry?')) return;
    setBusy(id);
    try {
      const res = await apiFetch(`/api/accounting/time-entries?id=${id}`, { method: 'DELETE' });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      setSuccess('Entry deleted');
      await loadEntries();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Delete failed');
    } finally { setBusy(''); }
  };

  const handleEdit = (entry: TimeEntry) => {
    setForm({
      projectName: entry.projectName || '',
      taskDescription: entry.taskDescription,
      entryDate: entry.entryDate.split('T')[0],
      hours: String(entry.hours),
      rate: entry.rate != null ? String(entry.rate) : '',
      billable: entry.billable,
      customerId: entry.customerId || '',
      notes: entry.notes || '',
    });
    setEditId(entry.id);
    setShowForm(true);
  };

  const handleBulkAction = async (action: 'submit' | 'approve') => {
    const ids = Array.from(selected);
    if (!ids.length) return;
    setBusy(action); setError('');
    try {
      const res = await apiFetch('/api/accounting/time-entries-action', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action, ids }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.message || 'Failed');
      const count = json.data?.count || 0;
      setSuccess(`${action === 'submit' ? 'Submitted' : 'Approved'} ${count} entries`);
      setSelected(new Set());
      await loadEntries();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Action failed');
    } finally { setBusy(''); }
  };

  const toggleSelect = (id: string) => {
    setSelected(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id); else next.add(id);
      return next;
    });
  };

  const toggleSelectAll = () => {
    if (selected.size === entries.length) {
      setSelected(new Set());
    } else {
      setSelected(new Set(entries.map(e => e.id)));
    }
  };

  // Clear messages after a delay
  useEffect(() => {
    if (success) { const t = setTimeout(() => setSuccess(''), 3000); return () => clearTimeout(t); }
  }, [success]);

  const TABS: { id: TabId; label: string }[] = [
    { id: 'my-time', label: 'My Time' },
    { id: 'all-entries', label: 'All Entries' },
    { id: 'summary', label: 'Summary' },
  ];

  return (
    <AppLayout>
      <div className="p-6 max-w-7xl mx-auto space-y-6">
        {/* Header */}
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <Clock className="w-7 h-7 text-blue-600 dark:text-blue-400" />
            <h1 className="text-2xl font-bold text-gray-900 dark:text-white">Time Tracking</h1>
          </div>
          <button
            onClick={() => { resetForm(); setShowForm(true); }}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Plus className="w-4 h-4" /> New Entry
          </button>
        </div>

        {/* Alerts */}
        {error && (
          <div className="bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300 p-3 rounded-lg flex items-center justify-between">
            {error}
            <button onClick={() => setError('')}><X className="w-4 h-4" /></button>
          </div>
        )}
        {success && (
          <div className="bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300 p-3 rounded-lg">
            {success}
          </div>
        )}

        {/* Tabs */}
        <div className="flex gap-1 border-b border-gray-200 dark:border-gray-700">
          {TABS.map(t => (
            <button
              key={t.id}
              onClick={() => { setTab(t.id); setSelected(new Set()); }}
              className={`px-4 py-2 text-sm font-medium border-b-2 transition-colors ${
                tab === t.id
                  ? 'border-blue-600 text-blue-600 dark:border-blue-400 dark:text-blue-400'
                  : 'border-transparent text-gray-500 hover:text-gray-700 dark:text-gray-400'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* Filters */}
        {tab !== 'summary' && (
          <div>
            <button
              onClick={() => setShowFilters(!showFilters)}
              className="flex items-center gap-2 text-sm text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white"
            >
              <Filter className="w-4 h-4" />
              Filters
              {showFilters ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
            </button>
            {showFilters && (
              <div className="mt-3 grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
                <select value={filterStatus} onChange={e => setFilterStatus(e.target.value)}
                  className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white">
                  <option value="">All Statuses</option>
                  <option value="draft">Draft</option>
                  <option value="submitted">Submitted</option>
                  <option value="approved">Approved</option>
                  <option value="invoiced">Invoiced</option>
                </select>
                <input value={filterProject} onChange={e => setFilterProject(e.target.value)}
                  placeholder="Project name..." className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white" />
                <select value={filterCustomer} onChange={e => setFilterCustomer(e.target.value)}
                  className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white">
                  <option value="">All Customers</option>
                  {customers.map(c => <option key={c.id} value={c.id}>{c.companyName}</option>)}
                </select>
                <select value={filterBillable} onChange={e => setFilterBillable(e.target.value)}
                  className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white">
                  <option value="">All</option>
                  <option value="true">Billable</option>
                  <option value="false">Non-Billable</option>
                </select>
                <input type="date" value={filterDateFrom} onChange={e => setFilterDateFrom(e.target.value)}
                  className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white" />
                <input type="date" value={filterDateTo} onChange={e => setFilterDateTo(e.target.value)}
                  className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white" />
              </div>
            )}
          </div>
        )}

        {/* Summary tab filters (date range only) */}
        {tab === 'summary' && (
          <div className="flex gap-3 items-center">
            <Filter className="w-4 h-4 text-gray-500" />
            <input type="date" value={filterDateFrom} onChange={e => setFilterDateFrom(e.target.value)}
              className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white" />
            <span className="text-gray-500">to</span>
            <input type="date" value={filterDateTo} onChange={e => setFilterDateTo(e.target.value)}
              className="border rounded-lg px-3 py-2 text-sm dark:bg-gray-800 dark:border-gray-600 dark:text-white" />
          </div>
        )}

        {/* Bulk Actions */}
        {tab !== 'summary' && selected.size > 0 && (
          <div className="flex items-center gap-3 p-3 bg-blue-50 dark:bg-blue-900/20 rounded-lg">
            <span className="text-sm font-medium text-blue-700 dark:text-blue-300">
              {selected.size} selected
            </span>
            <button
              onClick={() => handleBulkAction('submit')}
              disabled={busy === 'submit'}
              className="flex items-center gap-1 px-3 py-1.5 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
            >
              {busy === 'submit' ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
              Submit
            </button>
            <button
              onClick={() => handleBulkAction('approve')}
              disabled={busy === 'approve'}
              className="flex items-center gap-1 px-3 py-1.5 text-sm bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50"
            >
              {busy === 'approve' ? <Loader2 className="w-4 h-4 animate-spin" /> : <CheckCircle className="w-4 h-4" />}
              Approve
            </button>
          </div>
        )}

        {/* Entry Form Modal */}
        {showForm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-xl w-full max-w-lg mx-4 p-6">
              <div className="flex justify-between items-center mb-4">
                <h2 className="text-lg font-semibold text-gray-900 dark:text-white">
                  {editId ? 'Edit Time Entry' : 'New Time Entry'}
                </h2>
                <button onClick={() => { setShowForm(false); resetForm(); }}>
                  <X className="w-5 h-5 text-gray-500 hover:text-gray-700 dark:hover:text-gray-300" />
                </button>
              </div>
              <form onSubmit={handleSubmitForm} className="space-y-4">
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Date</label>
                    <input type="date" required value={form.entryDate}
                      onChange={e => setForm({ ...form, entryDate: e.target.value })}
                      className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Project</label>
                    <input value={form.projectName}
                      onChange={e => setForm({ ...form, projectName: e.target.value })}
                      placeholder="Project name"
                      className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Task Description *</label>
                  <input required value={form.taskDescription}
                    onChange={e => setForm({ ...form, taskDescription: e.target.value })}
                    placeholder="What did you work on?"
                    className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Hours *</label>
                    <input type="number" step="0.25" min="0.25" required value={form.hours}
                      onChange={e => setForm({ ...form, hours: e.target.value })}
                      placeholder="0.00"
                      className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Rate (ZAR/hr)</label>
                    <input type="number" step="0.01" min="0" value={form.rate}
                      onChange={e => setForm({ ...form, rate: e.target.value })}
                      placeholder="0.00"
                      className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Customer</label>
                  <select value={form.customerId}
                    onChange={e => setForm({ ...form, customerId: e.target.value })}
                    className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white">
                    <option value="">-- No Customer --</option>
                    {customers.map(c => <option key={c.id} value={c.id}>{c.companyName}</option>)}
                  </select>
                </div>
                <div className="flex items-center gap-2">
                  <input type="checkbox" id="billable" checked={form.billable}
                    onChange={e => setForm({ ...form, billable: e.target.checked })}
                    className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                  <label htmlFor="billable" className="text-sm text-gray-700 dark:text-gray-300">Billable</label>
                </div>
                <div>
                  <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">Notes</label>
                  <textarea value={form.notes} rows={2}
                    onChange={e => setForm({ ...form, notes: e.target.value })}
                    placeholder="Additional notes..."
                    className="w-full border rounded-lg px-3 py-2 text-sm dark:bg-gray-700 dark:border-gray-600 dark:text-white" />
                </div>
                <div className="flex justify-end gap-3">
                  <button type="button" onClick={() => { setShowForm(false); resetForm(); }}
                    className="px-4 py-2 text-sm border rounded-lg text-gray-700 dark:text-gray-300 dark:border-gray-600 hover:bg-gray-50 dark:hover:bg-gray-700">
                    Cancel
                  </button>
                  <button type="submit" disabled={busy === 'save'}
                    className="px-4 py-2 text-sm bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2">
                    {busy === 'save' && <Loader2 className="w-4 h-4 animate-spin" />}
                    {editId ? 'Update' : 'Save'}
                  </button>
                </div>
              </form>
            </div>
          </div>
        )}

        {/* Content */}
        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
          </div>
        ) : tab === 'summary' ? (
          /* Summary Tab */
          <div className="space-y-6">
            {summary && (
              <>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                  <SummaryCard label="Total Hours" value={fmtHours(summary.totalHours)} icon={<Clock className="w-5 h-5" />} color="blue" />
                  <SummaryCard label="Billable Hours" value={fmtHours(summary.billableHours)} icon={<CheckCircle className="w-5 h-5" />} color="green" />
                  <SummaryCard label="Non-Billable" value={fmtHours(summary.nonBillableHours)} icon={<Clock className="w-5 h-5" />} color="gray" />
                  <SummaryCard label="Total Value" value={fmt(summary.totalValue)} icon={<BarChart3 className="w-5 h-5" />} color="purple" />
                </div>

                <div className="grid md:grid-cols-2 gap-6">
                  {/* By Project */}
                  <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4">
                    <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">By Project</h3>
                    {summary.byProject.length === 0 ? (
                      <p className="text-sm text-gray-500">No data</p>
                    ) : (
                      <table className="w-full text-sm">
                        <thead>
                          <tr className="text-left text-gray-500 dark:text-gray-400 border-b dark:border-gray-700">
                            <th className="pb-2">Project</th>
                            <th className="pb-2 text-right">Hours</th>
                            <th className="pb-2 text-right">Value</th>
                          </tr>
                        </thead>
                        <tbody>
                          {summary.byProject.map(p => (
                            <tr key={p.projectName} className="border-b dark:border-gray-700/50">
                              <td className="py-2 text-gray-900 dark:text-white">{p.projectName}</td>
                              <td className="py-2 text-right text-gray-600 dark:text-gray-400">{fmtHours(p.hours)}</td>
                              <td className="py-2 text-right text-gray-600 dark:text-gray-400">{fmt(p.value)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>

                  {/* By Customer */}
                  <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4">
                    <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-3">By Customer</h3>
                    {summary.byCustomer.length === 0 ? (
                      <p className="text-sm text-gray-500">No data</p>
                    ) : (
                      <table className="w-full text-sm">
                        <thead>
                          <tr className="text-left text-gray-500 dark:text-gray-400 border-b dark:border-gray-700">
                            <th className="pb-2">Customer</th>
                            <th className="pb-2 text-right">Hours</th>
                            <th className="pb-2 text-right">Value</th>
                          </tr>
                        </thead>
                        <tbody>
                          {summary.byCustomer.map(c => (
                            <tr key={c.customerId} className="border-b dark:border-gray-700/50">
                              <td className="py-2 text-gray-900 dark:text-white">{c.customerName}</td>
                              <td className="py-2 text-right text-gray-600 dark:text-gray-400">{fmtHours(c.hours)}</td>
                              <td className="py-2 text-right text-gray-600 dark:text-gray-400">{fmt(c.value)}</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    )}
                  </div>
                </div>
              </>
            )}
          </div>
        ) : (
          /* Entries Table */
          <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-900/50 border-b dark:border-gray-700">
                    <th className="px-4 py-3 w-10">
                      <input type="checkbox" checked={entries.length > 0 && selected.size === entries.length}
                        onChange={toggleSelectAll}
                        className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                    </th>
                    <th className="px-4 py-3">Date</th>
                    <th className="px-4 py-3">Project</th>
                    <th className="px-4 py-3">Task</th>
                    <th className="px-4 py-3">Customer</th>
                    <th className="px-4 py-3 text-right">Hours</th>
                    <th className="px-4 py-3 text-right">Rate</th>
                    <th className="px-4 py-3 text-right">Amount</th>
                    <th className="px-4 py-3 text-center">Billable</th>
                    <th className="px-4 py-3 text-center">Status</th>
                    <th className="px-4 py-3 w-20"></th>
                  </tr>
                </thead>
                <tbody>
                  {entries.length === 0 ? (
                    <tr>
                      <td colSpan={11} className="px-4 py-12 text-center text-gray-500 dark:text-gray-400">
                        No time entries found. Click &quot;New Entry&quot; to get started.
                      </td>
                    </tr>
                  ) : entries.map(entry => (
                    <tr key={entry.id} className="border-b dark:border-gray-700/50 hover:bg-gray-50 dark:hover:bg-gray-700/30">
                      <td className="px-4 py-3">
                        <input type="checkbox" checked={selected.has(entry.id)}
                          onChange={() => toggleSelect(entry.id)}
                          className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                      </td>
                      <td className="px-4 py-3 text-gray-900 dark:text-white whitespace-nowrap">
                        {new Date(entry.entryDate).toLocaleDateString('en-ZA')}
                      </td>
                      <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{entry.projectName || '-'}</td>
                      <td className="px-4 py-3 text-gray-900 dark:text-white max-w-xs truncate">{entry.taskDescription}</td>
                      <td className="px-4 py-3 text-gray-700 dark:text-gray-300">{entry.customerName || '-'}</td>
                      <td className="px-4 py-3 text-right text-gray-900 dark:text-white font-mono">{fmtHours(entry.hours)}</td>
                      <td className="px-4 py-3 text-right text-gray-600 dark:text-gray-400 font-mono">
                        {entry.rate != null ? fmt(entry.rate) : '-'}
                      </td>
                      <td className="px-4 py-3 text-right text-gray-900 dark:text-white font-mono font-medium">
                        {entry.amount != null ? fmt(entry.amount) : '-'}
                      </td>
                      <td className="px-4 py-3 text-center">
                        {entry.billable ? (
                          <span className="inline-block px-2 py-0.5 text-xs rounded-full bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-300">Yes</span>
                        ) : (
                          <span className="inline-block px-2 py-0.5 text-xs rounded-full bg-gray-100 text-gray-500 dark:bg-gray-700 dark:text-gray-400">No</span>
                        )}
                      </td>
                      <td className="px-4 py-3 text-center">
                        <span className={`inline-block px-2 py-0.5 text-xs rounded-full font-medium capitalize ${STATUS_COLORS[entry.status] || ''}`}>
                          {entry.status}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        {entry.status === 'draft' && (
                          <div className="flex items-center gap-1">
                            <button onClick={() => handleEdit(entry)}
                              className="p-1 text-gray-400 hover:text-blue-600 dark:hover:text-blue-400" title="Edit">
                              <Clock className="w-4 h-4" />
                            </button>
                            <button onClick={() => handleDelete(entry.id)}
                              disabled={busy === entry.id}
                              className="p-1 text-gray-400 hover:text-red-600 dark:hover:text-red-400" title="Delete">
                              {busy === entry.id ? <Loader2 className="w-4 h-4 animate-spin" /> : <Trash2 className="w-4 h-4" />}
                            </button>
                          </div>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
            {total > entries.length && (
              <div className="px-4 py-3 text-sm text-gray-500 dark:text-gray-400 border-t dark:border-gray-700">
                Showing {entries.length} of {total} entries
              </div>
            )}
          </div>
        )}
      </div>
    </AppLayout>
  );
}

function SummaryCard({ label, value, icon, color }: { label: string; value: string; icon: React.ReactNode; color: string }) {
  const colors: Record<string, string> = {
    blue: 'bg-blue-50 text-blue-600 dark:bg-blue-900/30 dark:text-blue-400',
    green: 'bg-green-50 text-green-600 dark:bg-green-900/30 dark:text-green-400',
    gray: 'bg-gray-50 text-gray-600 dark:bg-gray-800 dark:text-gray-400',
    purple: 'bg-purple-50 text-purple-600 dark:bg-purple-900/30 dark:text-purple-400',
  };
  return (
    <div className="bg-white dark:bg-gray-800 rounded-xl border border-gray-200 dark:border-gray-700 p-4">
      <div className="flex items-center gap-2 mb-2">
        <div className={`p-2 rounded-lg ${colors[color]}`}>{icon}</div>
        <span className="text-sm text-gray-500 dark:text-gray-400">{label}</span>
      </div>
      <div className="text-xl font-bold text-gray-900 dark:text-white">{value}</div>
    </div>
  );
}

/**
 * Data Archiving & Retention Engine
 * WS-7.4 — Archive old financial data for DB performance.
 * SA Companies Act minimum retention: 5 years.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import { useCompany } from '@/contexts/CompanyContext';
import { apiFetch } from '@/lib/apiFetch';
import { log } from '@/lib/logger';
import {
  Archive, Database, Clock, CheckCircle2, XCircle,
  AlertTriangle, Loader2, Eye, ChevronRight,
} from 'lucide-react';
import type {
  StorageStats, ArchivePreview, ArchiveValidation, ArchiveRun, ArchivedEntry,
} from '@/modules/accounting/services/dataArchivingService';

type ViewMode = 'dashboard' | 'archived-data';

const COMPONENT = 'data-archiving-page';
const ARCHIVE_LIMIT = 50;
const TABLE_LABELS: Record<string, string> = {
  gl_journal_entries: 'GL Journal Entries',
  gl_journal_lines: 'GL Journal Lines',
  bank_transactions: 'Bank Transactions',
  customer_invoices: 'Customer Invoices',
  supplier_invoices: 'Supplier Invoices',
};

// ---------------------------------------------------------------------------
// Sub-components
// ---------------------------------------------------------------------------

function StatusBadge({ status }: { status: string }) {
  const map: Record<string, string> = {
    completed: 'bg-green-100 text-green-800 border-green-300',
    running: 'bg-blue-100 text-blue-800 border-blue-300',
    pending: 'bg-yellow-100 text-yellow-800 border-yellow-300',
    failed: 'bg-red-100 text-red-800 border-red-300',
    posted: 'bg-green-100 text-green-800 border-green-300',
  };
  const cls = map[status] ?? 'bg-gray-100 text-gray-800 border-gray-300';
  return (
    <span className={`inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold ${cls}`}>
      {status.charAt(0).toUpperCase() + status.slice(1)}
    </span>
  );
}

function Section({ title, icon, children }: {
  title: string;
  icon: React.ReactNode;
  children: React.ReactNode;
}) {
  return (
    <div className="rounded-xl border border-[var(--ff-border)] bg-[var(--ff-bg-secondary)] overflow-hidden">
      <div className="flex items-center gap-2 px-6 py-4 border-b border-[var(--ff-border)] bg-[var(--ff-bg-primary)]">
        <span className="text-[var(--ff-text-muted)]">{icon}</span>
        <h2 className="text-sm font-semibold text-[var(--ff-text-primary)]">{title}</h2>
      </div>
      <div className="p-6">{children}</div>
    </div>
  );
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

async function fetchJson<T>(url: string, options?: RequestInit): Promise<T> {
  const res = await apiFetch(url, options);
  const json = await res.json() as { data: T };
  return json.data;
}

// ---------------------------------------------------------------------------
// Page
// ---------------------------------------------------------------------------

export default function DataArchivingPage() {
  const { activeCompany } = useCompany();
  const [view, setView] = useState<ViewMode>('dashboard');

  // Storage stats
  const [stats, setStats] = useState<StorageStats[]>([]);
  const [statsLoading, setStatsLoading] = useState(true);

  // Archive wizard
  const [cutoffDate, setCutoffDate] = useState('');
  const [validation, setValidation] = useState<ArchiveValidation | null>(null);
  const [validating, setValidating] = useState(false);
  const [preview, setPreview] = useState<ArchivePreview | null>(null);
  const [previewing, setPreviewing] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [archiving, setArchiving] = useState(false);
  const [archiveError, setArchiveError] = useState<string | null>(null);
  const [archiveSuccess, setArchiveSuccess] = useState(false);

  // Archive history
  const [runs, setRuns] = useState<ArchiveRun[]>([]);
  const [runsLoading, setRunsLoading] = useState(true);

  // Archived data viewer
  const [archivedItems, setArchivedItems] = useState<ArchivedEntry[]>([]);
  const [archivedTotal, setArchivedTotal] = useState(0);
  const [archivedLoading, setArchivedLoading] = useState(false);
  const [archiveDateFrom, setArchiveDateFrom] = useState('');
  const [archiveDateTo, setArchiveDateTo] = useState('');
  const [archivePage, setArchivePage] = useState(0);

  // Maximum cutoff date: today minus 5 years
  const maxCutoff = (() => {
    const d = new Date();
    d.setFullYear(d.getFullYear() - 5);
    return d.toISOString().split('T')[0] ?? '';
  })();

  const loadStats = useCallback(async () => {
    if (!activeCompany) return;
    setStatsLoading(true);
    try {
      const data = await fetchJson<{ stats: StorageStats[] }>('/api/accounting/data-archiving');
      setStats(data.stats);
    } catch (err) {
      log.error('Failed to load storage stats', { error: err }, COMPONENT);
    } finally {
      setStatsLoading(false);
    }
  }, [activeCompany]);

  const loadRuns = useCallback(async () => {
    if (!activeCompany) return;
    setRunsLoading(true);
    try {
      const data = await fetchJson<{ runs: ArchiveRun[] }>('/api/accounting/archive-runs');
      setRuns(data.runs);
    } catch (err) {
      log.error('Failed to load archive runs', { error: err }, COMPONENT);
    } finally {
      setRunsLoading(false);
    }
  }, [activeCompany]);

  const loadArchivedData = useCallback(async () => {
    if (!activeCompany) return;
    setArchivedLoading(true);
    try {
      const params = new URLSearchParams({
        limit: String(ARCHIVE_LIMIT),
        offset: String(archivePage * ARCHIVE_LIMIT),
      });
      if (archiveDateFrom) params.set('date_from', archiveDateFrom);
      if (archiveDateTo) params.set('date_to', archiveDateTo);
      const data = await fetchJson<{ items: ArchivedEntry[]; total: number }>(
        `/api/accounting/archived-data?${params.toString()}`
      );
      setArchivedItems(data.items);
      setArchivedTotal(data.total);
    } catch (err) {
      log.error('Failed to load archived data', { error: err }, COMPONENT);
    } finally {
      setArchivedLoading(false);
    }
  }, [activeCompany, archivePage, archiveDateFrom, archiveDateTo]);

  useEffect(() => { void loadStats(); void loadRuns(); }, [loadStats, loadRuns]);
  useEffect(() => {
    if (view === 'archived-data') void loadArchivedData();
  }, [view, loadArchivedData]);

  const handleValidate = async () => {
    if (!cutoffDate) return;
    setValidating(true);
    setValidation(null);
    setPreview(null);
    try {
      const data = await fetchJson<{ validation: ArchiveValidation }>(
        `/api/accounting/data-archiving?action=validate&cutoff=${cutoffDate}`
      );
      setValidation(data.validation);
    } catch (err) {
      log.error('Validation request failed', { error: err }, COMPONENT);
    } finally {
      setValidating(false);
    }
  };

  const handlePreview = async () => {
    if (!cutoffDate) return;
    setPreviewing(true);
    setPreview(null);
    try {
      const data = await fetchJson<{ preview: ArchivePreview }>(
        `/api/accounting/data-archiving?action=preview&cutoff=${cutoffDate}`
      );
      setPreview(data.preview);
    } catch (err) {
      log.error('Preview request failed', { error: err }, COMPONENT);
    } finally {
      setPreviewing(false);
    }
  };

  const handleArchive = async () => {
    setShowConfirm(false);
    setArchiving(true);
    setArchiveError(null);
    setArchiveSuccess(false);
    try {
      await apiFetch('/api/accounting/data-archiving', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ cutoffDate }),
      });
      setArchiveSuccess(true);
      setCutoffDate('');
      setValidation(null);
      setPreview(null);
      await loadStats();
      await loadRuns();
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'Archive failed. All changes have been rolled back.';
      setArchiveError(msg);
      log.error('Archive execution failed', { error: err }, COMPONENT);
    } finally {
      setArchiving(false);
    }
  };

  const totalRows = stats.reduce((sum, s) => sum + s.rowCount, 0);

  // ── Render ────────────────────────────────────────────────────────────────

  return (
    <AppLayout>
      <div className="max-w-5xl mx-auto px-4 py-8 space-y-6">

        {/* Page header */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
          <div>
            <h1 className="text-2xl font-bold text-[var(--ff-text-primary)] flex items-center gap-2">
              <Archive className="h-6 w-6 text-teal-600" />
              Data Archiving
            </h1>
            <p className="text-sm text-[var(--ff-text-muted)] mt-1">
              Move old financial records to archive tables to maintain database performance.
              SA Companies Act requires minimum 5-year retention.
            </p>
          </div>
          <div className="flex gap-2">
            <button
              onClick={() => setView('dashboard')}
              className={`text-sm px-4 py-2 rounded-lg border transition-colors ${
                view === 'dashboard'
                  ? 'bg-teal-600 text-white border-teal-600'
                  : 'border-[var(--ff-border)] text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-secondary)]'
              }`}
            >
              Dashboard
            </button>
            <button
              onClick={() => setView('archived-data')}
              className={`flex items-center gap-1.5 text-sm px-4 py-2 rounded-lg border transition-colors ${
                view === 'archived-data'
                  ? 'bg-teal-600 text-white border-teal-600'
                  : 'border-[var(--ff-border)] text-[var(--ff-text-primary)] hover:bg-[var(--ff-bg-secondary)]'
              }`}
            >
              <Eye className="h-4 w-4" />
              View Archived Data
            </button>
          </div>
        </div>

        {/* ── Dashboard View ── */}
        {view === 'dashboard' && (
          <>
            {/* Storage Stats */}
            <Section title="Storage Dashboard" icon={<Database className="h-4 w-4" />}>
              {statsLoading ? (
                <div className="flex items-center gap-2 text-[var(--ff-text-muted)]">
                  <Loader2 className="h-4 w-4 animate-spin" /> Loading statistics...
                </div>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border)]">
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Table</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Row Count</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Oldest Record</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Newest Record</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border)]">
                      {stats.map((s) => (
                        <tr key={s.tableName}>
                          <td className="py-2.5 font-medium text-[var(--ff-text-primary)]">
                            {TABLE_LABELS[s.tableName] ?? s.tableName}
                          </td>
                          <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">
                            {s.rowCount.toLocaleString()}
                          </td>
                          <td className="py-2.5 text-right text-[var(--ff-text-muted)]">
                            {s.oldestDate ?? '—'}
                          </td>
                          <td className="py-2.5 text-right text-[var(--ff-text-muted)]">
                            {s.newestDate ?? '—'}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="border-t-2 border-[var(--ff-border)]">
                        <td className="pt-3 font-bold text-[var(--ff-text-primary)]">Total</td>
                        <td className="pt-3 text-right font-bold text-[var(--ff-text-primary)]">
                          {totalRows.toLocaleString()}
                        </td>
                        <td colSpan={2} />
                      </tr>
                    </tfoot>
                  </table>
                </div>
              )}
            </Section>

            {/* Archive Wizard */}
            <Section title="Archive Wizard" icon={<Archive className="h-4 w-4" />}>
              <div className="space-y-6">
                {/* Date picker */}
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-primary)] mb-1.5">
                    Cutoff Date
                  </label>
                  <p className="text-xs text-[var(--ff-text-muted)] mb-2">
                    Records before this date (that are fully finalised) will be moved to archive tables.
                    Maximum allowed cutoff: <strong>{maxCutoff}</strong> (5-year minimum retention).
                  </p>
                  <input
                    type="date"
                    value={cutoffDate}
                    max={maxCutoff}
                    onChange={(e) => {
                      setCutoffDate(e.target.value);
                      setValidation(null);
                      setPreview(null);
                      setArchiveError(null);
                      setArchiveSuccess(false);
                    }}
                    className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] px-3 py-2 text-sm w-48 focus:outline-none focus:ring-2 focus:ring-teal-500"
                  />
                </div>

                {/* Buttons */}
                <div className="flex flex-wrap gap-3">
                  <button
                    onClick={() => void handleValidate()}
                    disabled={!cutoffDate || validating}
                    className="flex items-center gap-2 text-sm px-4 py-2 rounded-lg border border-[var(--ff-border)] hover:bg-[var(--ff-bg-secondary)] text-[var(--ff-text-primary)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  >
                    {validating ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />}
                    Validate
                  </button>
                  <button
                    onClick={() => void handlePreview()}
                    disabled={!cutoffDate || previewing}
                    className="flex items-center gap-2 text-sm px-4 py-2 rounded-lg border border-[var(--ff-border)] hover:bg-[var(--ff-bg-secondary)] text-[var(--ff-text-primary)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  >
                    {previewing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Eye className="h-4 w-4" />}
                    Preview
                  </button>
                  <button
                    onClick={() => setShowConfirm(true)}
                    disabled={!validation?.valid || archiving}
                    className="flex items-center gap-2 text-sm px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
                  >
                    {archiving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Archive className="h-4 w-4" />}
                    Archive Now
                  </button>
                </div>

                {/* Validation result */}
                {validation && (
                  <div className={`rounded-lg border p-4 ${
                    validation.valid
                      ? 'border-green-300 bg-green-50'
                      : 'border-red-300 bg-red-50'
                  }`}>
                    <div className="flex items-center gap-2 mb-2">
                      {validation.valid
                        ? <CheckCircle2 className="h-5 w-5 text-green-600" />
                        : <XCircle className="h-5 w-5 text-red-600" />}
                      <span className={`text-sm font-semibold ${validation.valid ? 'text-green-800' : 'text-red-800'}`}>
                        {validation.valid ? 'Validation Passed' : 'Validation Failed'}
                      </span>
                    </div>
                    {validation.errors.length > 0 && (
                      <ul className="list-disc list-inside space-y-1">
                        {validation.errors.map((e, i) => (
                          <li key={i} className="text-sm text-red-700">{e}</li>
                        ))}
                      </ul>
                    )}
                  </div>
                )}

                {/* Preview result */}
                {preview && (
                  <div className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] p-4">
                    <p className="text-sm font-semibold text-[var(--ff-text-primary)] mb-3">
                      Records that would be archived before {cutoffDate}:
                    </p>
                    <dl className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                      {[
                        { label: 'Journal Entries', value: preview.journalEntries },
                        { label: 'Journal Lines', value: preview.journalLines },
                        { label: 'Bank Transactions', value: preview.bankTransactions },
                        { label: 'Customer Invoices', value: preview.customerInvoices },
                        { label: 'Supplier Invoices', value: preview.supplierInvoices },
                      ].map((item) => (
                        <div key={item.label} className="rounded-lg bg-[var(--ff-bg-secondary)] p-3">
                          <dt className="text-xs text-[var(--ff-text-muted)]">{item.label}</dt>
                          <dd className="text-lg font-bold text-[var(--ff-text-primary)]">
                            {item.value.toLocaleString()}
                          </dd>
                        </div>
                      ))}
                      <div className="rounded-lg bg-teal-50 border border-teal-200 p-3">
                        <dt className="text-xs text-teal-700 font-medium">Total Records</dt>
                        <dd className="text-lg font-bold text-teal-800">
                          {preview.totalRecords.toLocaleString()}
                        </dd>
                      </div>
                    </dl>
                  </div>
                )}

                {/* Success / error banners */}
                {archiveSuccess && (
                  <div className="flex items-center gap-2 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-800">
                    <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                    Archive completed successfully. Data has been moved to archive tables.
                  </div>
                )}
                {archiveError && (
                  <div className="flex items-center gap-2 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-800">
                    <XCircle className="h-5 w-5 text-red-600 flex-shrink-0" />
                    {archiveError}
                  </div>
                )}
              </div>
            </Section>

            {/* Archive History */}
            <Section title="Archive History" icon={<Clock className="h-4 w-4" />}>
              {runsLoading ? (
                <div className="flex items-center gap-2 text-[var(--ff-text-muted)]">
                  <Loader2 className="h-4 w-4 animate-spin" /> Loading history...
                </div>
              ) : runs.length === 0 ? (
                <p className="text-sm text-[var(--ff-text-muted)]">No archive runs yet.</p>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border)]">
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Date Run</th>
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Cutoff</th>
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Status</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Entries</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Transactions</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Invoices</th>
                        <th className="pb-2 text-right font-semibold text-[var(--ff-text-muted)]">Duration</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border)]">
                      {runs.map((run) => {
                        const duration = run.startedAt && run.completedAt
                          ? Math.round(
                              (new Date(run.completedAt).getTime() - new Date(run.startedAt).getTime()) / 1000
                            )
                          : null;
                        return (
                          <tr key={run.id}>
                            <td className="py-2.5 text-[var(--ff-text-secondary)]">
                              {new Date(run.createdAt).toLocaleDateString('en-ZA')}
                            </td>
                            <td className="py-2.5 text-[var(--ff-text-primary)] font-medium">
                              {run.cutoffDate}
                            </td>
                            <td className="py-2.5"><StatusBadge status={run.status} /></td>
                            <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">
                              {run.entriesArchived.toLocaleString()}
                            </td>
                            <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">
                              {run.transactionsArchived.toLocaleString()}
                            </td>
                            <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">
                              {(run.invoicesArchived + run.supplierInvoicesArchived).toLocaleString()}
                            </td>
                            <td className="py-2.5 text-right text-[var(--ff-text-muted)]">
                              {duration !== null ? `${duration}s` : '—'}
                            </td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </Section>
          </>
        )}

        {/* ── Archived Data View ── */}
        {view === 'archived-data' && (
          <Section title="Archived Journal Entries (Read-Only)" icon={<Eye className="h-4 w-4" />}>
            {/* Filters */}
            <div className="flex flex-wrap gap-3 mb-6">
              <div>
                <label className="block text-xs text-[var(--ff-text-muted)] mb-1">Date From</label>
                <input
                  type="date"
                  value={archiveDateFrom}
                  onChange={(e) => { setArchiveDateFrom(e.target.value); setArchivePage(0); }}
                  className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-muted)] mb-1">Date To</label>
                <input
                  type="date"
                  value={archiveDateTo}
                  onChange={(e) => { setArchiveDateTo(e.target.value); setArchivePage(0); }}
                  className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500"
                />
              </div>
              <div className="flex items-end">
                <button
                  onClick={() => void loadArchivedData()}
                  disabled={archivedLoading}
                  className="flex items-center gap-1.5 text-sm px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white disabled:opacity-50 transition-colors"
                >
                  {archivedLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : <ChevronRight className="h-4 w-4" />}
                  Search
                </button>
              </div>
            </div>

            {archivedLoading ? (
              <div className="flex items-center gap-2 text-[var(--ff-text-muted)]">
                <Loader2 className="h-4 w-4 animate-spin" /> Loading archived data...
              </div>
            ) : archivedItems.length === 0 ? (
              <div className="flex items-center gap-2 text-[var(--ff-text-muted)]">
                <AlertTriangle className="h-4 w-4" />
                No archived journal entries found for the selected date range.
              </div>
            ) : (
              <>
                <p className="text-xs text-[var(--ff-text-muted)] mb-3">
                  Showing {archivePage * ARCHIVE_LIMIT + 1}–{Math.min((archivePage + 1) * ARCHIVE_LIMIT, archivedTotal)} of {archivedTotal.toLocaleString()} archived entries
                </p>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border)]">
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Entry #</th>
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Date</th>
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Description</th>
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Source</th>
                        <th className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">Status</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border)]">
                      {archivedItems.map((item) => (
                        <tr key={item.id}>
                          <td className="py-2.5 font-mono text-xs text-[var(--ff-text-secondary)]">
                            {item.entryNumber ?? '—'}
                          </td>
                          <td className="py-2.5 text-[var(--ff-text-primary)]">{item.entryDate}</td>
                          <td className="py-2.5 text-[var(--ff-text-secondary)] max-w-xs truncate">
                            {item.description ?? '—'}
                          </td>
                          <td className="py-2.5 text-[var(--ff-text-muted)] capitalize">{item.source ?? '—'}</td>
                          <td className="py-2.5">
                            <StatusBadge status={item.status ?? 'unknown'} />
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>

                {/* Pagination */}
                {archivedTotal > ARCHIVE_LIMIT && (
                  <div className="flex items-center justify-between mt-4 pt-4 border-t border-[var(--ff-border)]">
                    <button
                      onClick={() => setArchivePage((p) => Math.max(0, p - 1))}
                      disabled={archivePage === 0}
                      className="text-sm px-3 py-1.5 rounded-lg border border-[var(--ff-border)] disabled:opacity-40 hover:bg-[var(--ff-bg-secondary)] transition-colors"
                    >
                      Previous
                    </button>
                    <span className="text-sm text-[var(--ff-text-muted)]">
                      Page {archivePage + 1} of {Math.ceil(archivedTotal / ARCHIVE_LIMIT)}
                    </span>
                    <button
                      onClick={() => setArchivePage((p) => p + 1)}
                      disabled={(archivePage + 1) * ARCHIVE_LIMIT >= archivedTotal}
                      className="text-sm px-3 py-1.5 rounded-lg border border-[var(--ff-border)] disabled:opacity-40 hover:bg-[var(--ff-bg-secondary)] transition-colors"
                    >
                      Next
                    </button>
                  </div>
                )}
              </>
            )}
          </Section>
        )}
      </div>

      {/* Confirm Dialog */}
      {showConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-[var(--ff-bg-primary)] rounded-xl border border-[var(--ff-border)] p-6 max-w-md w-full space-y-4 shadow-xl">
            <div className="flex items-start gap-3">
              <AlertTriangle className="h-6 w-6 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <h3 className="text-base font-semibold text-[var(--ff-text-primary)]">
                  Confirm Archive Operation
                </h3>
                <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
                  This will permanently move all eligible records before{' '}
                  <strong>{cutoffDate}</strong> to the archive tables and delete them from
                  active tables. This operation cannot be undone from the UI.
                </p>
                {preview && (
                  <p className="text-sm text-[var(--ff-text-muted)] mt-2">
                    <strong>{preview.totalRecords.toLocaleString()}</strong> total records will be archived.
                  </p>
                )}
              </div>
            </div>
            <div className="flex gap-3 justify-end pt-2">
              <button
                onClick={() => setShowConfirm(false)}
                className="text-sm px-4 py-2 rounded-lg border border-[var(--ff-border)] hover:bg-[var(--ff-bg-secondary)] text-[var(--ff-text-primary)] transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={() => void handleArchive()}
                className="text-sm px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white transition-colors"
              >
                Yes, Archive Now
              </button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

/**
 * VAT201 Form Page
 * Period selector, auto-populated VAT201 fields with invoice breakdown,
 * save draft and mark submitted actions, CSV export.
 */

import { useState, useEffect, useCallback } from 'react';
import { AppLayout } from '@/components/layout/AppLayout';
import Link from 'next/link';
import {
  FileText, Loader2, Save, Send, Download,
  ChevronLeft, ChevronDown, ChevronRight, Calendar,
} from 'lucide-react';
import { formatDate } from '@/utils/formatters';
import { apiFetch } from '@/lib/apiFetch';

interface VAT201Invoice {
  id: string;
  invoiceNumber: string;
  counterpartyName: string;
  invoiceDate: string;
  totalExclVat: number;
  vatAmount: number;
  vatType: string;
}

interface VAT201Data {
  periodStart: string;
  periodEnd: string;
  field1_standardRatedSupplies: number;
  field2_zeroRatedSupplies: number;
  field3_exemptSupplies: number;
  field4_totalImports: number;
  field5_outputVAT: number;
  field6_capitalGoods: number;
  field7_otherGoods: number;
  field8_services: number;
  field9_imports: number;
  field10_totalInputVAT: number;
  field11_vatPayableOrRefundable: number;
  outputInvoices: VAT201Invoice[];
  inputInvoices: VAT201Invoice[];
}

const fmt = (n: number) =>
  new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR' }).format(n);

const MONTH_NAMES = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

interface VATQuickPeriod {
  label: string;
  from: string;
  to: string;
}

function pad2(n: number) { return String(n).padStart(2, '0'); }

function buildVatPeriods(year: number, alignment: 'odd' | 'even'): VATQuickPeriod[] {
  const startMonths = alignment === 'even' ? [2, 4, 6, 8, 10, 12] : [1, 3, 5, 7, 9, 11];
  return startMonths.map(sm => {
    const endMonth = sm + 1;
    const endYear = endMonth > 12 ? year + 1 : year;
    const em = endMonth > 12 ? 1 : endMonth;
    const lastDay = new Date(endYear, em, 0).getDate();
    return {
      label: `${MONTH_NAMES[sm - 1]}–${MONTH_NAMES[em - 1]} ${endYear !== year ? year + '/' + endYear : year}`,
      from: `${year}-${pad2(sm)}-01`,
      to: `${endYear}-${pad2(em)}-${pad2(lastDay)}`,
    };
  });
}

function getDefaultPeriod(alignment: 'odd' | 'even' = 'odd'): { from: string; to: string } {
  const now = new Date();
  const year = now.getFullYear();
  const periods = buildVatPeriods(year, alignment);
  const today = now.toISOString().split('T')[0]!;
  const current = periods.find(p => p.from <= today && p.to >= today);
  return current || periods[0]!;
}

export default function VAT201Page() {
  const [alignment, setAlignment] = useState<'odd' | 'even'>('odd');
  const [vatPeriod, setVatPeriod] = useState<'monthly' | 'bi-monthly'>('bi-monthly');
  const [quickPeriods, setQuickPeriods] = useState<VATQuickPeriod[]>([]);
  const defaults = getDefaultPeriod(alignment);
  const [from, setFrom] = useState(defaults.from);
  const [to, setTo] = useState(defaults.to);
  const [data, setData] = useState<VAT201Data | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [viewMode, setViewMode] = useState<'summary' | 'detail'>('summary');
  const [sarsRef, setSarsRef] = useState('');
  const [savedId, setSavedId] = useState('');
  const [showSubmitModal, setShowSubmitModal] = useState(false);

  // Load company alignment setting
  useEffect(() => {
    (async () => {
      const res = await apiFetch('/api/accounting/companies', { credentials: 'include' });
      const json = await res.json();
      if (res.ok && json.data) {
        const c = Array.isArray(json.data) ? json.data[0] : json.data;
        const a = c?.vatPeriodAlignment || c?.vat_period_alignment || 'odd';
        const vp = c?.vatPeriod || c?.vat_period || 'bi-monthly';
        setAlignment(a);
        setVatPeriod(vp);
        const year = new Date().getFullYear();
        if (vp === 'monthly') {
          const months: VATQuickPeriod[] = [];
          for (let m = 1; m <= 12; m++) {
            const lastDay = new Date(year, m, 0).getDate();
            months.push({
              label: `${MONTH_NAMES[m - 1]} ${year}`,
              from: `${year}-${pad2(m)}-01`,
              to: `${year}-${pad2(m)}-${pad2(lastDay)}`,
            });
          }
          setQuickPeriods(months);
        } else {
          setQuickPeriods(buildVatPeriods(year, a));
        }
        const def = getDefaultPeriod(a);
        setFrom(def.from);
        setTo(def.to);
      }
    })();
  }, []);

  const generate = useCallback(async () => {
    if (!from || !to) return;
    setLoading(true);
    setError('');
    setSuccess('');
    setData(null);
    setSavedId('');
    try {
      const res = await apiFetch(
        `/api/accounting/sars/sars-vat201?from=${from}&to=${to}`,
        { credentials: 'include' }
      );
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || json.message || 'Failed');
      setData(json.data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate VAT201');
    } finally {
      setLoading(false);
    }
  }, [from, to]);

  const saveDraft = async () => {
    if (!data) return;
    setSaving(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/sars/sars-vat201', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ periodStart: from, periodEnd: to }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || json.message || 'Failed');
      setSavedId(json.data?.id || '');
      setSuccess('VAT201 draft saved successfully');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save draft');
    } finally {
      setSaving(false);
    }
  };

  const markSubmitted = async () => {
    if (!savedId || !sarsRef.trim()) return;
    setSubmitting(true);
    setError('');
    try {
      const res = await apiFetch('/api/accounting/sars/sars-submissions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        credentials: 'include',
        body: JSON.stringify({ id: savedId, action: 'mark_submitted', reference: sarsRef.trim() }),
      });
      const json = await res.json();
      if (!res.ok) throw new Error(json.error?.message || json.message || 'Failed');
      setSuccess('VAT201 marked as submitted to SARS');
      setShowSubmitModal(false);
      setSarsRef('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to mark as submitted');
    } finally {
      setSubmitting(false);
    }
  };

  const exportCSV = () => {
    if (!data) return;
    const rows = [
      ['Field', 'Description', 'Amount (ZAR)'],
      ['1', 'Standard-rated supplies (15%)', data.field1_standardRatedSupplies.toFixed(2)],
      ['2', 'Zero-rated supplies', data.field2_zeroRatedSupplies.toFixed(2)],
      ['3', 'Exempt supplies', data.field3_exemptSupplies.toFixed(2)],
      ['4', 'Total imports', data.field4_totalImports.toFixed(2)],
      ['5', 'Output VAT (Field 1 x 15%)', data.field5_outputVAT.toFixed(2)],
      ['6', 'Input VAT — Capital goods', data.field6_capitalGoods.toFixed(2)],
      ['7', 'Input VAT — Other goods', data.field7_otherGoods.toFixed(2)],
      ['8', 'Input VAT — Services', data.field8_services.toFixed(2)],
      ['9', 'Input VAT — Imports', data.field9_imports.toFixed(2)],
      ['10', 'Total input VAT', data.field10_totalInputVAT.toFixed(2)],
      ['11', 'VAT payable / (refundable)', data.field11_vatPayableOrRefundable.toFixed(2)],
      [],
      ['Period', `${data.periodStart} to ${data.periodEnd}`],
    ];
    const csv = rows.map((r) => r.join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `VAT201_${from}_${to}.csv`;
    a.click();
    URL.revokeObjectURL(url);
  };

  return (
    <AppLayout>
      <div className="min-h-screen bg-[var(--ff-bg-primary)]">
        {/* Header */}
        <div className="border-b border-[var(--ff-border-light)] bg-[var(--ff-bg-secondary)] px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <Link
                href="/accounting/sars"
                className="p-2 rounded-lg hover:bg-[var(--ff-bg-primary)] text-[var(--ff-text-secondary)]"
              >
                <ChevronLeft className="h-5 w-5" />
              </Link>
              <div className="p-2 rounded-lg bg-teal-500/10">
                <FileText className="h-6 w-6 text-teal-500" />
              </div>
              <div>
                <h1 className="text-2xl font-bold text-[var(--ff-text-primary)]">VAT201 Return</h1>
                <p className="text-sm text-[var(--ff-text-secondary)]">
                  SARS Value-Added Tax Declaration
                </p>
              </div>
            </div>
            {data && (
              <div className="flex items-center gap-2">
                <button
                  onClick={exportCSV}
                  className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg border border-[var(--ff-border-light)] text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)] hover:border-teal-500/30"
                >
                  <Download className="h-4 w-4" /> Export CSV
                </button>
              </div>
            )}
          </div>
        </div>

        <div className="p-6 space-y-6">
          {error && <div className="p-3 rounded-lg bg-red-500/10 text-red-400 text-sm">{error}</div>}
          {success && <div className="p-3 rounded-lg bg-teal-500/10 text-teal-400 text-sm">{success}</div>}

          {/* Period Selector */}
          <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-4">
            <div className="flex items-center justify-between mb-3">
              <h2 className="text-sm font-medium text-[var(--ff-text-secondary)] flex items-center gap-2">
                <Calendar className="h-4 w-4" /> VAT Period
              </h2>
              <span className="text-xs text-[var(--ff-text-tertiary)]">
                {vatPeriod === 'monthly' ? 'Monthly' : alignment === 'even' ? 'Bi-Monthly (Category B)' : 'Bi-Monthly (Category A)'}
              </span>
            </div>

            {/* Quick Period Buttons */}
            {quickPeriods.length > 0 && (
              <div className="flex flex-wrap gap-2 mb-4">
                {quickPeriods.map(p => (
                  <button
                    key={p.from}
                    onClick={() => { setFrom(p.from); setTo(p.to); }}
                    className={`px-3 py-1.5 rounded-lg text-xs font-medium border transition-colors ${
                      from === p.from && to === p.to
                        ? 'bg-teal-600 text-white border-teal-600'
                        : 'border-[var(--ff-border-light)] text-[var(--ff-text-secondary)] hover:border-teal-500/50 hover:text-[var(--ff-text-primary)]'
                    }`}
                  >
                    {p.label}
                  </button>
                ))}
              </div>
            )}

            <div className="flex flex-wrap items-end gap-4">
              <div>
                <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Period Start</label>
                <input
                  type="date"
                  value={from}
                  onChange={(e) => setFrom(e.target.value)}
                  className="px-3 py-2 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] text-sm"
                />
              </div>
              <div>
                <label className="block text-xs text-[var(--ff-text-tertiary)] mb-1">Period End</label>
                <input
                  type="date"
                  value={to}
                  onChange={(e) => setTo(e.target.value)}
                  className="px-3 py-2 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] text-sm"
                />
              </div>
              <button
                onClick={generate}
                disabled={loading}
                className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-teal-600 text-white text-sm font-medium hover:bg-teal-700 disabled:opacity-50"
              >
                {loading ? <Loader2 className="h-4 w-4 animate-spin" /> : <FileText className="h-4 w-4" />}
                Generate
              </button>
            </div>
          </div>

          {/* VAT201 Form */}
          {data && (
            <>
              {/* View Toggle */}
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-1 bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-1">
                  <button
                    onClick={() => setViewMode('summary')}
                    className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${
                      viewMode === 'summary'
                        ? 'bg-teal-600 text-white'
                        : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                    }`}
                  >
                    Summary
                  </button>
                  <button
                    onClick={() => setViewMode('detail')}
                    className={`px-4 py-1.5 rounded-md text-sm font-medium transition-colors ${
                      viewMode === 'detail'
                        ? 'bg-teal-600 text-white'
                        : 'text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]'
                    }`}
                  >
                    Detail
                  </button>
                </div>
                <span className="text-xs text-[var(--ff-text-tertiary)]">
                  {viewMode === 'summary' ? 'SARS VAT201 box totals' : `${data.outputInvoices.length + data.inputInvoices.length} transactions`}
                </span>
              </div>

              {viewMode === 'summary' ? (
                /* ── SUMMARY VIEW ── */
                <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)]">
                  <div className="px-4 py-3 border-b border-[var(--ff-border-light)]">
                    <h2 className="text-lg font-semibold text-[var(--ff-text-primary)]">
                      VAT201 — {formatDate(data.periodStart)} to {formatDate(data.periodEnd)}
                    </h2>
                  </div>

                  <div className="divide-y divide-[var(--ff-border-light)]">
                    <div className="px-4 py-2 bg-teal-500/5">
                      <p className="text-xs font-semibold text-teal-500 uppercase tracking-wider">Output VAT (Sales)</p>
                    </div>
                    <FormRow field="1" label="Standard-rated supplies (15%)" amount={data.field1_standardRatedSupplies} />
                    <FormRow field="2" label="Zero-rated supplies" amount={data.field2_zeroRatedSupplies} />
                    <FormRow field="3" label="Exempt supplies" amount={data.field3_exemptSupplies} />
                    <FormRow field="4" label="Total imports" amount={data.field4_totalImports} />
                    <FormRow field="5" label="Output VAT (Field 1 x 15%)" amount={data.field5_outputVAT} highlight />

                    <div className="px-4 py-2 bg-blue-500/5">
                      <p className="text-xs font-semibold text-blue-500 uppercase tracking-wider">Input VAT (Purchases)</p>
                    </div>
                    <FormRow field="6" label="Capital goods" amount={data.field6_capitalGoods} />
                    <FormRow field="7" label="Other goods" amount={data.field7_otherGoods} />
                    <FormRow field="8" label="Services" amount={data.field8_services} />
                    <FormRow field="9" label="Imports" amount={data.field9_imports} />
                    <FormRow field="10" label="Total input VAT" amount={data.field10_totalInputVAT} highlight />

                    <div className="px-4 py-2 bg-[var(--ff-bg-primary)]">
                      <p className="text-xs font-semibold text-[var(--ff-text-secondary)] uppercase tracking-wider">Result</p>
                    </div>
                    <div className="px-4 py-3 flex items-center justify-between bg-[var(--ff-bg-primary)]/50">
                      <div className="flex items-center gap-3">
                        <span className="text-sm font-mono text-[var(--ff-text-tertiary)] w-8">11</span>
                        <span className="text-sm font-semibold text-[var(--ff-text-primary)]">
                          {data.field11_vatPayableOrRefundable >= 0 ? 'VAT Payable to SARS' : 'VAT Refundable from SARS'}
                        </span>
                      </div>
                      <span className={`text-lg font-bold ${
                        data.field11_vatPayableOrRefundable >= 0 ? 'text-red-400' : 'text-emerald-400'
                      }`}>
                        {fmt(Math.abs(data.field11_vatPayableOrRefundable))}
                      </span>
                    </div>
                  </div>
                </div>
              ) : (
                /* ── DETAIL VIEW ── */
                <div className="space-y-4">
                  {/* Output Transactions */}
                  <TransactionTable
                    title="Section A — Output Tax (Sales)"
                    sectionColor="teal"
                    invoices={data.outputInvoices}
                    totalLabel="Total Output Tax (Box 13)"
                    totalVat={data.field5_outputVAT}
                  />

                  {/* Input Transactions */}
                  <TransactionTable
                    title="Section B — Input Tax (Purchases)"
                    sectionColor="blue"
                    invoices={data.inputInvoices}
                    totalLabel="Total Input Tax (Box 19)"
                    totalVat={data.field10_totalInputVAT}
                  />

                  {/* Net Result Banner */}
                  <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] px-4 py-3 flex items-center justify-between">
                    <span className="text-sm font-semibold text-[var(--ff-text-primary)]">
                      Net VAT — Box 20 ({data.field11_vatPayableOrRefundable >= 0 ? 'Payable to SARS' : 'Refundable from SARS'})
                    </span>
                    <span className={`text-lg font-bold ${
                      data.field11_vatPayableOrRefundable >= 0 ? 'text-red-400' : 'text-emerald-400'
                    }`}>
                      {fmt(Math.abs(data.field11_vatPayableOrRefundable))}
                    </span>
                  </div>
                </div>
              )}

              {/* Actions */}
              <div className="flex items-center gap-3">
                <button
                  onClick={saveDraft}
                  disabled={saving}
                  className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-teal-600 text-white text-sm font-medium hover:bg-teal-700 disabled:opacity-50"
                >
                  {saving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                  Save Draft
                </button>
                {savedId && (
                  <button
                    onClick={() => setShowSubmitModal(true)}
                    className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-emerald-600 text-white text-sm font-medium hover:bg-emerald-700"
                  >
                    <Send className="h-4 w-4" /> Mark as Submitted
                  </button>
                )}
              </div>
            </>
          )}

          {/* Submit Modal */}
          {showSubmitModal && (
            <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
              <div className="bg-[var(--ff-bg-secondary)] rounded-lg border border-[var(--ff-border-light)] p-6 w-full max-w-md mx-4">
                <h3 className="text-lg font-semibold text-[var(--ff-text-primary)] mb-4">
                  Mark as Submitted to SARS
                </h3>
                <p className="text-sm text-[var(--ff-text-secondary)] mb-4">
                  Enter the SARS eFiling reference number after submitting the return on the SARS eFiling portal.
                </p>
                <input
                  type="text"
                  value={sarsRef}
                  onChange={(e) => setSarsRef(e.target.value)}
                  placeholder="SARS reference number"
                  className="w-full px-3 py-2 rounded-lg border border-[var(--ff-border-light)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] text-sm mb-4"
                />
                <div className="flex items-center gap-3 justify-end">
                  <button
                    onClick={() => setShowSubmitModal(false)}
                    className="px-4 py-2 rounded-lg text-sm text-[var(--ff-text-secondary)] hover:text-[var(--ff-text-primary)]"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={markSubmitted}
                    disabled={submitting || !sarsRef.trim()}
                    className="inline-flex items-center gap-1.5 px-4 py-2 rounded-lg bg-emerald-600 text-white text-sm font-medium hover:bg-emerald-700 disabled:opacity-50"
                  >
                    {submitting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Send className="h-4 w-4" />}
                    Confirm
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </AppLayout>
  );
}

