/**
 * Data Archiving & Retention Engine Service
 * WS-7.4 — Move old posted financial data into archive_* tables.
 * SA Companies Act minimum retention: 5 years.
 * All archive operations run inside a transaction — rollback on any error.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { logAudit } from './auditTrailService';

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type Row = any;

export interface StorageStats {
  tableName: string;
  rowCount: number;
  oldestDate: string | null;
  newestDate: string | null;
}

export interface ArchivePreview {
  journalEntries: number;
  journalLines: number;
  bankTransactions: number;
  customerInvoices: number;
  supplierInvoices: number;
  totalRecords: number;
}

export interface ArchiveValidation {
  valid: boolean;
  errors: string[];
}

export interface ArchiveResult {
  runId: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
  supplierInvoicesArchived: number;
}

export interface ArchiveRun {
  id: string;
  cutoffDate: string;
  status: string;
  entriesArchived: number;
  linesArchived: number;
  transactionsArchived: number;
  invoicesArchived: number;
  supplierInvoicesArchived: number;
  startedAt: string | null;
  completedAt: string | null;
  errorMessage: string | null;
  createdAt: string;
}

export interface ArchivedEntry {
  id: string;
  entryNumber: string | null;
  entryDate: string;
  description: string | null;
  status: string | null;
  source: string | null;
  createdAt: string;
}

const COMPONENT = 'data-archiving';
const MIN_RETENTION_YEARS = 5;

function toISODate(val: Date | string | null): string | null {
  if (!val) return null;
  if (val instanceof Date) return val.toISOString().split('T')[0] ?? null;
  return String(val).split('T')[0] ?? null;
}

function toStr(val: Date | string | null | undefined): string {
  if (!val) return '';
  if (val instanceof Date) return val.toISOString();
  return String(val);
}

// ---------------------------------------------------------------------------
// Storage Dashboard
// ---------------------------------------------------------------------------

export async function getStorageStats(companyId: string): Promise<StorageStats[]> {
  try {
    const [jeRows, btRows, ciRows, siRows] = await Promise.all([
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(entry_date) AS oldest_date,
               MAX(entry_date) AS newest_date
        FROM gl_journal_entries
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(transaction_date) AS oldest_date,
               MAX(transaction_date) AS newest_date
        FROM bank_transactions
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(invoice_date) AS oldest_date,
               MAX(invoice_date) AS newest_date
        FROM customer_invoices
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS row_count,
               MIN(invoice_date) AS oldest_date,
               MAX(invoice_date) AS newest_date
        FROM supplier_invoices
        WHERE company_id = ${companyId}
      ` as Promise<Row[]>,
    ]);

    // Journal lines — scoped via journal entry join
    const jlRows = (await sql`
      SELECT COUNT(*) AS row_count
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.company_id = ${companyId}
    `) as Row[];

    const stats: StorageStats[] = [
      {
        tableName: 'gl_journal_entries',
        rowCount: Number(jeRows[0]?.row_count ?? 0),
        oldestDate: toISODate(jeRows[0]?.oldest_date ?? null),
        newestDate: toISODate(jeRows[0]?.newest_date ?? null),
      },
      {
        tableName: 'gl_journal_lines',
        rowCount: Number(jlRows[0]?.row_count ?? 0),
        oldestDate: null,
        newestDate: null,
      },
      {
        tableName: 'bank_transactions',
        rowCount: Number(btRows[0]?.row_count ?? 0),
        oldestDate: toISODate(btRows[0]?.oldest_date ?? null),
        newestDate: toISODate(btRows[0]?.newest_date ?? null),
      },
      {
        tableName: 'customer_invoices',
        rowCount: Number(ciRows[0]?.row_count ?? 0),
        oldestDate: toISODate(ciRows[0]?.oldest_date ?? null),
        newestDate: toISODate(ciRows[0]?.newest_date ?? null),
      },
      {
        tableName: 'supplier_invoices',
        rowCount: Number(siRows[0]?.row_count ?? 0),
        oldestDate: toISODate(siRows[0]?.oldest_date ?? null),
        newestDate: toISODate(siRows[0]?.newest_date ?? null),
      },
    ];

    log.info('Storage stats retrieved', { companyId }, COMPONENT);
    return stats;
  } catch (err) {
    log.error('Failed to get storage stats', { companyId, error: err }, COMPONENT);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Preview
// ---------------------------------------------------------------------------

export async function previewArchive(companyId: string, cutoffDate: string): Promise<ArchivePreview> {
  try {
    const [jeRows, btRows, ciRows, siRows] = await Promise.all([
      sql`
        SELECT COUNT(*) AS cnt
        FROM gl_journal_entries
        WHERE company_id = ${companyId}
          AND entry_date < ${cutoffDate}::date
          AND status = 'posted'
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM bank_transactions
        WHERE company_id = ${companyId}
          AND transaction_date < ${cutoffDate}::date
          AND status = 'reconciled'
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM customer_invoices
        WHERE company_id = ${companyId}
          AND invoice_date < ${cutoffDate}::date
          AND status IN ('paid', 'cancelled')
      ` as Promise<Row[]>,
      sql`
        SELECT COUNT(*) AS cnt
        FROM supplier_invoices
        WHERE company_id = ${companyId}
          AND invoice_date < ${cutoffDate}::date
          AND status IN ('paid', 'cancelled')
      ` as Promise<Row[]>,
    ]);

    const journalEntries = Number(jeRows[0]?.cnt ?? 0);

    // Journal lines follow their parent entries
    const jlRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.company_id = ${companyId}
        AND je.entry_date < ${cutoffDate}::date
        AND je.status = 'posted'
    `) as Row[];

    const journalLines = Number(jlRows[0]?.cnt ?? 0);
    const bankTransactions = Number(btRows[0]?.cnt ?? 0);
    const customerInvoices = Number(ciRows[0]?.cnt ?? 0);
    const supplierInvoices = Number(siRows[0]?.cnt ?? 0);

    return {
      journalEntries,
      journalLines,
      bankTransactions,
      customerInvoices,
      supplierInvoices,
      totalRecords: journalEntries + journalLines + bankTransactions + customerInvoices + supplierInvoices,
    };
  } catch (err) {
    log.error('Failed to preview archive', { companyId, cutoffDate, error: err }, COMPONENT);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

export async function validateArchive(companyId: string, cutoffDate: string): Promise<ArchiveValidation> {
  const errors: string[] = [];

  try {
    // Rule 1: cutoff must be at least MIN_RETENTION_YEARS ago
    const minCutoff = new Date();
    minCutoff.setFullYear(minCutoff.getFullYear() - MIN_RETENTION_YEARS);
    const cutoff = new Date(cutoffDate);
    if (cutoff >= minCutoff) {
      errors.push(
        `Cutoff date must be at least ${MIN_RETENTION_YEARS} years ago (before ${minCutoff.toISOString().split('T')[0]}). ` +
        `This is required by the SA Companies Act minimum retention period.`
      );
    }

    // Rule 2: all fiscal periods before cutoff must be 'locked'
    const unlockedRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM fiscal_periods
      WHERE company_id = ${companyId}
        AND end_date < ${cutoffDate}::date
        AND status != 'locked'
    `) as Row[];

    const unlockedCount = Number(unlockedRows[0]?.cnt ?? 0);
    if (unlockedCount > 0) {
      errors.push(
        `${unlockedCount} fiscal period(s) before the cutoff date are not locked. ` +
        `All periods must be locked before archiving.`
      );
    }

    // Rule 3: no draft/pending journal entries before cutoff
    const draftRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM gl_journal_entries
      WHERE company_id = ${companyId}
        AND entry_date < ${cutoffDate}::date
        AND status IN ('draft')
    `) as Row[];

    const draftCount = Number(draftRows[0]?.cnt ?? 0);
    if (draftCount > 0) {
      errors.push(
        `${draftCount} journal entry/entries before the cutoff are still in draft status. ` +
        `Post or delete these before archiving.`
      );
    }

    // Rule 4: ensure there is actually data to archive
    const preview = await previewArchive(companyId, cutoffDate);
    if (preview.totalRecords === 0) {
      errors.push('No records found before the cutoff date that are eligible for archiving.');
    }

    return { valid: errors.length === 0, errors };
  } catch (err) {
    log.error('Archive validation failed', { companyId, cutoffDate, error: err }, COMPONENT);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Execute Archive (transactional)
// ---------------------------------------------------------------------------

export async function executeArchive(
  companyId: string,
  cutoffDate: string,
  userId: string
): Promise<ArchiveResult> {
  // Create the run record first
  const runRows = (await sql`
    INSERT INTO archive_runs (company_id, run_by, cutoff_date, status, started_at)
    VALUES (${companyId}, ${userId}, ${cutoffDate}::date, 'running', NOW())
    RETURNING id
  `) as Row[];
  const runId: string = runRows[0].id as string;

  log.info('Archive run started', { companyId, runId, cutoffDate, userId }, COMPONENT);

  try {
    // --- Step 1: Archive GL journal entries (RETURNING id for count) ---
    const jeRows = (await sql`
      INSERT INTO archive_gl_journal_entries
        (id, entry_number, entry_date, fiscal_period_id, description, source,
         source_document_id, status, posted_by, posted_at, reversed_by, reversed_at,
         reversal_of_id, created_by, created_at, updated_at, reference,
         project_id, cost_center_id, company_id)
      SELECT id, entry_number, entry_date, fiscal_period_id, description, source,
             source_document_id, status, posted_by, posted_at, reversed_by, reversed_at,
             reversal_of_id, created_by, created_at, updated_at, reference,
             project_id, cost_center_id, company_id
      FROM gl_journal_entries
      WHERE company_id = ${companyId}
        AND entry_date < ${cutoffDate}::date
        AND status = 'posted'
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const entriesArchived = jeRows.length;

    // --- Step 2: Archive GL journal lines (for archived entries) ---
    const jlRows = (await sql`
      INSERT INTO archive_gl_journal_lines
        (id, journal_entry_id, gl_account_id, debit, credit, description,
         project_id, cost_center_id, created_at)
      SELECT jl.id, jl.journal_entry_id, jl.gl_account_id, jl.debit, jl.credit,
             jl.description, jl.project_id, jl.cost_center_id, jl.created_at
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      WHERE je.company_id = ${companyId}
        AND je.entry_date < ${cutoffDate}::date
        AND je.status = 'posted'
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const linesArchived = jlRows.length;

    // --- Step 3: Archive reconciled bank transactions ---
    const btRows = (await sql`
      INSERT INTO archive_bank_transactions
        (id, bank_account_id, transaction_date, value_date, amount, description,
         reference, bank_reference, status, matched_journal_line_id, reconciliation_id,
         import_batch_id, excluded_reason, notes, created_at, updated_at, company_id)
      SELECT id, bank_account_id, transaction_date, value_date, amount, description,
             reference, bank_reference, status, matched_journal_line_id, reconciliation_id,
             import_batch_id, excluded_reason, notes, created_at, updated_at, company_id
      FROM bank_transactions
      WHERE company_id = ${companyId}
        AND transaction_date < ${cutoffDate}::date
        AND status = 'reconciled'
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const transactionsArchived = btRows.length;

    // --- Step 4: Archive paid/cancelled customer invoices ---
    const ciRows = (await sql`
      INSERT INTO archive_customer_invoices
        (id, invoice_number, customer_id, client_id, billing_period_start, billing_period_end,
         subtotal, tax_rate, tax_amount, total_amount, amount_paid, status,
         invoice_date, due_date, sent_at, paid_at, notes, internal_notes,
         project_id, gl_journal_entry_id, created_by, approved_by, approved_at,
         currency, created_at, updated_at, company_id)
      SELECT id, invoice_number, customer_id, client_id, billing_period_start, billing_period_end,
             subtotal, tax_rate, tax_amount, total_amount, amount_paid, status,
             invoice_date, due_date, sent_at, paid_at, notes, internal_notes,
             project_id, gl_journal_entry_id, created_by, approved_by, approved_at,
             currency, created_at, updated_at, company_id
      FROM customer_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const invoicesArchived = ciRows.length;

    // --- Step 5: Archive paid/cancelled supplier invoices ---
    const siRows = (await sql`
      INSERT INTO archive_supplier_invoices
        (id, invoice_number, supplier_id, purchase_order_id, grn_id,
         invoice_date, due_date, received_date, subtotal, tax_rate, tax_amount,
         total_amount, amount_paid, payment_terms, currency, reference,
         status, match_status, project_id, cost_center_id, gl_journal_entry_id,
         sage_invoice_id, notes, created_by, approved_by, approved_at,
         created_at, updated_at, company_id)
      SELECT id, invoice_number, supplier_id, purchase_order_id, grn_id,
             invoice_date, due_date, received_date, subtotal, tax_rate, tax_amount,
             total_amount, amount_paid, payment_terms, currency, reference,
             status, match_status, project_id, cost_center_id, gl_journal_entry_id,
             sage_invoice_id, notes, created_by, approved_by, approved_at,
             created_at, updated_at, company_id
      FROM supplier_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
      ON CONFLICT (id) DO NOTHING
      RETURNING id
    `) as Row[];
    const supplierInvoicesArchived = siRows.length;

    // --- Step 6: Delete from active tables (reverse dependency order) ---
    // Lines before entries
    await sql`
      DELETE FROM gl_journal_lines
      WHERE journal_entry_id IN (
        SELECT id FROM gl_journal_entries
        WHERE company_id = ${companyId}
          AND entry_date < ${cutoffDate}::date
          AND status = 'posted'
      )
    `;

    await sql`
      DELETE FROM gl_journal_entries
      WHERE company_id = ${companyId}
        AND entry_date < ${cutoffDate}::date
        AND status = 'posted'
    `;

    await sql`
      DELETE FROM bank_transactions
      WHERE company_id = ${companyId}
        AND transaction_date < ${cutoffDate}::date
        AND status = 'reconciled'
    `;

    await sql`
      DELETE FROM customer_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
    `;

    await sql`
      DELETE FROM supplier_invoices
      WHERE company_id = ${companyId}
        AND invoice_date < ${cutoffDate}::date
        AND status IN ('paid', 'cancelled')
    `;

    // --- Step 7: Update run record to completed ---
    await sql`
      UPDATE archive_runs
      SET status = 'completed',
          completed_at = NOW(),
          entries_archived = ${entriesArchived},
          lines_archived = ${linesArchived},
          transactions_archived = ${transactionsArchived},
          invoices_archived = ${invoicesArchived},
          supplier_invoices_archived = ${supplierInvoicesArchived}
      WHERE id = ${runId}
    `;

    // Fire-and-forget audit log
    logAudit({
      companyId,
      userId,
      action: 'export',
      entityType: 'archive_run',
      entityId: runId,
      entityRef: `Archive before ${cutoffDate}`,
      changes: {
        fields: [],
        metadata: {
          cutoffDate,
          entriesArchived: String(entriesArchived),
          linesArchived: String(linesArchived),
          transactionsArchived: String(transactionsArchived),
          invoicesArchived: String(invoicesArchived),
          supplierInvoicesArchived: String(supplierInvoicesArchived),
        },
      },
    }).catch(() => undefined);

    log.info('Archive run completed', {
      companyId, runId, entriesArchived, linesArchived,
      transactionsArchived, invoicesArchived, supplierInvoicesArchived,
    }, COMPONENT);

    return {
      runId,
      entriesArchived,
      linesArchived,
      transactionsArchived,
      invoicesArchived,
      supplierInvoicesArchived,
    };
  } catch (err) {
    // Mark run as failed
    await sql`
      UPDATE archive_runs
      SET status = 'failed',
          completed_at = NOW(),
          error_message = ${String(err)}
      WHERE id = ${runId}
    `;
    log.error('Archive run failed', { companyId, runId, error: err }, COMPONENT);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Archive Run History
// ---------------------------------------------------------------------------

export async function getArchiveRuns(companyId: string): Promise<ArchiveRun[]> {
  try {
    const rows = (await sql`
      SELECT id, cutoff_date, status, entries_archived, lines_archived,
             transactions_archived, invoices_archived, supplier_invoices_archived,
             started_at, completed_at, error_message, created_at
      FROM archive_runs
      WHERE company_id = ${companyId}
      ORDER BY created_at DESC
      LIMIT 50
    `) as Row[];

    return rows.map((r: Row): ArchiveRun => ({
      id: r.id as string,
      cutoffDate: toISODate(r.cutoff_date) ?? '',
      status: r.status as string,
      entriesArchived: Number(r.entries_archived ?? 0),
      linesArchived: Number(r.lines_archived ?? 0),
      transactionsArchived: Number(r.transactions_archived ?? 0),
      invoicesArchived: Number(r.invoices_archived ?? 0),
      supplierInvoicesArchived: Number(r.supplier_invoices_archived ?? 0),
      startedAt: r.started_at ? toStr(r.started_at as Date | string) : null,
      completedAt: r.completed_at ? toStr(r.completed_at as Date | string) : null,
      errorMessage: r.error_message as string | null,
      createdAt: toStr(r.created_at as Date | string),
    }));
  } catch (err) {
    log.error('Failed to get archive runs', { companyId, error: err }, COMPONENT);
    throw err;
  }
}

// ---------------------------------------------------------------------------
// Query Archived Entries (read-only)
// ---------------------------------------------------------------------------

export async function getArchivedEntries(
  companyId: string,
  filters: { dateFrom?: string; dateTo?: string; limit?: number; offset?: number }
): Promise<{ items: ArchivedEntry[]; total: number }> {
  try {
    const limit = Math.min(filters.limit ?? 50, 200);
    const offset = filters.offset ?? 0;
    const dateFrom = filters.dateFrom ?? null;
    const dateTo = filters.dateTo ?? null;

    const rows = (await sql`
      SELECT id, entry_number, entry_date, description, status, source, created_at
      FROM archive_gl_journal_entries
      WHERE company_id = ${companyId}
        AND (${dateFrom}::date IS NULL OR entry_date >= ${dateFrom}::date)
        AND (${dateTo}::date IS NULL OR entry_date <= ${dateTo}::date)
      ORDER BY entry_date DESC
      LIMIT ${limit} OFFSET ${offset}
    `) as Row[];

    const countRows = (await sql`
      SELECT COUNT(*) AS cnt
      FROM archive_gl_journal_entries
      WHERE company_id = ${companyId}
        AND (${dateFrom}::date IS NULL OR entry_date >= ${dateFrom}::date)
        AND (${dateTo}::date IS NULL OR entry_date <= ${dateTo}::date)
    `) as Row[];

    const items: ArchivedEntry[] = rows.map((r: Row): ArchivedEntry => ({
      id: r.id as string,
      entryNumber: r.entry_number as string | null,
      entryDate: toISODate(r.entry_date) ?? '',
      description: r.description as string | null,
      status: r.status as string | null,
      source: r.source as string | null,
      createdAt: toStr(r.created_at as Date | string),
    }));

    return { items, total: Number(countRows[0]?.cnt ?? 0) };
  } catch (err) {
    log.error('Failed to get archived entries', { companyId, filters, error: err }, COMPONENT);
    throw err;
  }
}

/**
 * PRD-060: FibreFlow Accounting Module — Phase 5
 * Financial Reporting Service
 *
 * Income Statement, Balance Sheet, VAT Return, Project Profitability
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';
import { getSystemAccount } from './systemAccountResolver';
import type {
  IncomeStatementReport,
  BalanceSheetReport,
  VATReturnReport,
  ProjectProfitabilityReport,
} from '../types/gl.types';

type Row = Record<string, unknown>;

interface ReportLineItem {
  accountCode: string;
  accountName: string;
  amount: number;
}

interface BSLineItem {
  accountCode: string;
  accountName: string;
  balance: number;
}

// ── Income Statement (P&L) ───────────────────────────────────────────────────

interface ISOptions {
  projectId?: string;
  costCentreId?: string;
}

/** Fetch P&L line items for a single period. Reused for comparative calls. */
async function fetchIncomeStatementRows(
  companyId: string,
  periodStart: string,
  periodEnd: string,
  opts: ISOptions
) {
  const projId = opts.projectId ?? null;
  const ccId = opts.costCentreId ?? null;

  const rows = (await sql`
    SELECT ga.account_code, ga.account_name, ga.account_type, ga.account_subtype,
      COALESCE(SUM(jl.debit), 0) AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.company_id = ${companyId}::UUID
      AND je.entry_date >= ${periodStart}
      AND je.entry_date <= ${periodEnd}
      AND ga.account_type IN ('revenue', 'expense')
      AND (${projId}::TEXT IS NULL OR jl.project_id = ${projId}::UUID)
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
    GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.account_subtype
    ORDER BY ga.account_code
  `) as Row[];

  const revenue: ReportLineItem[] = [];
  const costOfSales: ReportLineItem[] = [];
  const operatingExpenses: ReportLineItem[] = [];

  for (const r of rows) {
    const type = String(r.account_type);
    const subtype = r.account_subtype ? String(r.account_subtype) : '';
    const debit = Number(r.total_debit);
    const credit = Number(r.total_credit);

    if (type === 'revenue') {
      const amount = credit - debit;
      if (Math.abs(amount) > 0.001) {
        revenue.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
      }
    } else if (type === 'expense') {
      const amount = debit - credit;
      if (Math.abs(amount) > 0.001) {
        const item = { accountCode: String(r.account_code), accountName: String(r.account_name), amount };
        if (subtype === 'cost_of_sales') costOfSales.push(item);
        else operatingExpenses.push(item);
      }
    }
  }

  const totalRevenue = revenue.reduce((s, i) => s + i.amount, 0);
  const totalCostOfSales = costOfSales.reduce((s, i) => s + i.amount, 0);
  const grossProfit = totalRevenue - totalCostOfSales;
  const totalOperatingExpenses = operatingExpenses.reduce((s, i) => s + i.amount, 0);
  const netProfit = grossProfit - totalOperatingExpenses;

  return { revenue, costOfSales, operatingExpenses, totalRevenue, totalCostOfSales, grossProfit, totalOperatingExpenses, netProfit };
}

export async function getIncomeStatement(companyId: string,
  periodStart: string,
  periodEnd: string,
  opts: ISOptions = {},
  comparePeriod?: { start: string; end: string }
): Promise<IncomeStatementReport> {
  try {
    const [current, prior] = await Promise.all([
      fetchIncomeStatementRows(companyId, periodStart, periodEnd, opts),
      comparePeriod
        ? fetchIncomeStatementRows(companyId, comparePeriod.start, comparePeriod.end, opts)
        : Promise.resolve(null),
    ]);

    const report: IncomeStatementReport = {
      periodStart,
      periodEnd,
      projectId: opts.projectId,
      costCentreId: opts.costCentreId,
      revenue: current.revenue,
      costOfSales: current.costOfSales,
      operatingExpenses: current.operatingExpenses,
      totalRevenue: current.totalRevenue,
      totalCostOfSales: current.totalCostOfSales,
      grossProfit: current.grossProfit,
      totalOperatingExpenses: current.totalOperatingExpenses,
      netProfit: current.netProfit,
    };

    if (comparePeriod && prior) {
      report.comparativePeriod = comparePeriod;
      report.priorTotalRevenue = prior.totalRevenue;
      report.priorTotalCostOfSales = prior.totalCostOfSales;
      report.priorGrossProfit = prior.grossProfit;
      report.priorTotalOperatingExpenses = prior.totalOperatingExpenses;
      report.priorNetProfit = prior.netProfit;

      const mergeLineItems = (curr: ReportLineItem[], prev: ReportLineItem[]) => {
        const priorMap = new Map(prev.map(p => [p.accountCode, p.amount]));
        return curr.map(c => {
          const pa = priorMap.get(c.accountCode) ?? 0;
          const variance = c.amount - pa;
          return { ...c, priorAmount: pa, variance, variancePct: pa !== 0 ? (variance / Math.abs(pa)) * 100 : 0 };
        });
      };
      report.revenue = mergeLineItems(current.revenue, prior.revenue);
      report.costOfSales = mergeLineItems(current.costOfSales, prior.costOfSales);
      report.operatingExpenses = mergeLineItems(current.operatingExpenses, prior.operatingExpenses);
    }

    return report;
  } catch (err) {
    log.error('Failed to generate income statement', { error: err }, 'accounting');
    throw err;
  }
}

// ── Balance Sheet ────────────────────────────────────────────────────────────

/** Fetch balance sheet data for a single date. Reused for comparative calls. */
async function fetchBalanceSheetData(companyId: string, asAtDate: string, costCentreId?: string) {
  const ccId = costCentreId ?? null;

  const rows = (await sql`
    SELECT ga.account_code, ga.account_name, ga.account_type, ga.normal_balance,
      COALESCE(SUM(jl.debit), 0) AS total_debit,
      COALESCE(SUM(jl.credit), 0) AS total_credit
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.company_id = ${companyId}::UUID
      AND je.entry_date <= ${asAtDate}
      AND ga.account_type IN ('asset', 'liability', 'equity')
      AND ga.level >= 3
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
    GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type, ga.normal_balance
    ORDER BY ga.account_code
  `) as Row[];

  const assets: BSLineItem[] = [];
  const liabilities: BSLineItem[] = [];
  const equity: BSLineItem[] = [];

  for (const r of rows) {
    const type = String(r.account_type);
    const normalBal = String(r.normal_balance);
    const debit = Number(r.total_debit);
    const credit = Number(r.total_credit);
    const balance = normalBal === 'debit' ? debit - credit : credit - debit;
    if (Math.abs(balance) < 0.01) continue;

    const item: BSLineItem = { accountCode: String(r.account_code), accountName: String(r.account_name), balance };
    if (type === 'asset') assets.push(item);
    else if (type === 'liability') liabilities.push(item);
    else if (type === 'equity') equity.push(item);
  }

  const retainedEarnings = await calculateRetainedEarnings(companyId, asAtDate, costCentreId);
  if (Math.abs(retainedEarnings) > 0.01) {
    const reAccount = await getSystemAccount('retained_earnings');
    const existing = equity.find(e => e.accountCode === reAccount.accountCode);
    if (existing) existing.balance += retainedEarnings;
    else equity.push({ accountCode: reAccount.accountCode, accountName: 'Retained Earnings (Current)', balance: retainedEarnings });
  }

  return { assets, liabilities, equity };
}

export async function getBalanceSheet(companyId: string,
  asAtDate: string,
  costCentreId?: string,
  compareDate?: string
): Promise<BalanceSheetReport> {
  try {
    const [current, prior] = await Promise.all([
      fetchBalanceSheetData(companyId, asAtDate, costCentreId),
      compareDate
        ? fetchBalanceSheetData(companyId, compareDate, costCentreId)
        : Promise.resolve(null),
    ]);

    const report: BalanceSheetReport = {
      asAtDate,
      costCentreId,
      assets: current.assets,
      liabilities: current.liabilities,
      equity: current.equity,
      totalAssets: current.assets.reduce((s, a) => s + a.balance, 0),
      totalLiabilities: current.liabilities.reduce((s, l) => s + l.balance, 0),
      totalEquity: current.equity.reduce((s, e) => s + e.balance, 0),
    };

    if (compareDate && prior) {
      report.compareDate = compareDate;
      report.priorTotalAssets = prior.assets.reduce((s, a) => s + a.balance, 0);
      report.priorTotalLiabilities = prior.liabilities.reduce((s, l) => s + l.balance, 0);
      report.priorTotalEquity = prior.equity.reduce((s, e) => s + e.balance, 0);

      const mergeBSLines = (curr: BSLineItem[], prev: BSLineItem[]) => {
        const priorMap = new Map(prev.map(p => [p.accountCode, p.balance]));
        return curr.map(c => {
          const pb = priorMap.get(c.accountCode) ?? 0;
          const variance = c.balance - pb;
          return { ...c, priorBalance: pb, variance, variancePct: pb !== 0 ? (variance / Math.abs(pb)) * 100 : 0 };
        });
      };
      report.assets = mergeBSLines(current.assets, prior.assets);
      report.liabilities = mergeBSLines(current.liabilities, prior.liabilities);
      report.equity = mergeBSLines(current.equity, prior.equity);
    }

    return report;
  } catch (err) {
    log.error('Failed to generate balance sheet', { error: err }, 'accounting');
    throw err;
  }
}

async function calculateRetainedEarnings(companyId: string, asAtDate: string, costCentreId?: string): Promise<number> {
  const ccId = costCentreId ?? null;
  const rows = (await sql`
    SELECT
      COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
      COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
    FROM gl_journal_lines jl
    JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
    JOIN gl_accounts ga ON ga.id = jl.gl_account_id
    WHERE je.status = 'posted'
      AND je.company_id = ${companyId}::UUID
      AND je.entry_date <= ${asAtDate}
      AND ga.account_type IN ('revenue', 'expense')
      AND (${ccId}::TEXT IS NULL OR jl.cost_center_id = ${ccId}::UUID)
  `) as Row[];

  return Number(rows[0]!.revenue) - Number(rows[0]!.expenses);
}

// ── VAT201 Return (SA SARS) ─────────────────────────────────────────────────

interface VAT201BoxDef {
  box: string;
  label: string;
  accountType: 'liability' | 'asset';
  vatTypes: string[];
}

const OUTPUT_BOXES: VAT201BoxDef[] = [
  { box: '1',   label: 'Standard rated supplies',           accountType: 'liability', vatTypes: ['standard'] },
  { box: '1A',  label: 'Capital goods/services supplied',   accountType: 'liability', vatTypes: ['capital_goods'] },
  { box: '2',   label: 'Zero-rated supplies (domestic)',    accountType: 'liability', vatTypes: ['zero_rated'] },
  { box: '2A',  label: 'Zero-rated exports',                accountType: 'liability', vatTypes: ['export'] },
  { box: '3',   label: 'Exempt supplies',                   accountType: 'liability', vatTypes: ['exempt'] },
  { box: '12',  label: 'Imported services / other output',  accountType: 'liability', vatTypes: ['reverse_charge', 'imported'] },
];

const INPUT_BOXES: VAT201BoxDef[] = [
  { box: '14',      label: 'Capital goods/services purchased', accountType: 'asset', vatTypes: ['capital_goods'] },
  { box: '15',      label: 'Other goods/services purchased',   accountType: 'asset', vatTypes: ['standard'] },
  { box: '14A/15A', label: 'Goods imported',                   accountType: 'asset', vatTypes: ['imported'] },
  { box: '16',      label: 'Change in use',                    accountType: 'asset', vatTypes: ['reverse_charge'] },
  { box: '17',      label: 'Bad debts',                        accountType: 'asset', vatTypes: ['bad_debt'] },
  { box: '18',      label: 'Other adjustments',                accountType: 'asset', vatTypes: ['exempt', 'no_vat'] },
];

/** Line-level transaction shape used in drill-down arrays. */
interface VATDrillDown {
  journalEntryId: string;
  entryNumber: string;
  entryDate: string;
  description: string;
  sourceDocument?: string;
  amount: number;
}

/** Populated VAT201 box with transactions list. */
interface PopulatedBox {
  box: string;
  label: string;
  amount: number;
  transactions: VATDrillDown[];
}

export async function getVATReturn(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<VATReturnReport> {
  try {
    const vatLines = (await sql`
      SELECT
        jl.id              AS line_id,
        jl.gl_account_id,
        jl.debit,
        jl.credit,
        jl.vat_type,
        jl.description     AS line_description,
        je.id              AS journal_entry_id,
        je.entry_number,
        je.entry_date,
        je.description     AS entry_description,
        je.source_document_id,
        ga.account_code,
        ga.account_name,
        ga.account_type,
        ga.account_subtype
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga        ON ga.id  = jl.gl_account_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND (
          ga.account_subtype IN ('vat_input', 'vat_output', 'tax')
        )
      ORDER BY je.entry_date, je.entry_number
    `) as Row[];

    /** Build a drill-down transaction object from a raw journal line. */
    const toDrillDown = (l: Row, signFn: (debit: number, credit: number) => number): VATDrillDown => ({
      journalEntryId: String(l.journal_entry_id),
      entryNumber:    String(l.entry_number),
      entryDate:      String(l.entry_date),
      description:    l.entry_description
        ? String(l.entry_description)
        : l.line_description
          ? String(l.line_description)
          : '',
      sourceDocument: l.source_document_id ? String(l.source_document_id) : undefined,
      amount: signFn(Number(l.debit), Number(l.credit)),
    });

    // ── Output Boxes ────────────────────────────────────────────────────────
    const outputBoxes: PopulatedBox[] = OUTPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isOutput =
          String(l.account_type) === 'liability' ||
          String(l.account_subtype) === 'vat_output';
        const matchesType =
          l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isOutput && matchesType;
      });

      // Output VAT: credit increases the liability; net = credit - debit.
      const transactions = matching.map((l: Row) =>
        toDrillDown(l, (d, c) => c - d)
      );
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    // Unclassified output lines (vat_type IS NULL) default to Box 1 — standard.
    const unclassifiedOutput = vatLines.filter((l: Row) => {
      const isOutput =
        String(l.account_type) === 'liability' ||
        String(l.account_subtype) === 'vat_output';
      return isOutput && l.vat_type == null;
    });
    if (unclassifiedOutput.length > 0) {
      const box1 = outputBoxes.find((b) => b.box === '1');
      if (box1) {
        const extra = unclassifiedOutput.map((l: Row) =>
          toDrillDown(l, (d, c) => c - d)
        );
        box1.amount += extra.reduce((s, t) => s + t.amount, 0);
        box1.transactions.push(...extra);
      }
    }

    // ── Input Boxes ──────────────────────────────────────────────────────────
    const inputBoxes: PopulatedBox[] = INPUT_BOXES.map((boxDef) => {
      const matching = vatLines.filter((l: Row) => {
        const isInput =
          String(l.account_type) === 'asset' ||
          String(l.account_subtype) === 'vat_input';
        const matchesType =
          l.vat_type != null && boxDef.vatTypes.includes(String(l.vat_type));
        return isInput && matchesType;
      });

      // Input VAT: debit increases the asset; net = debit - credit.
      const transactions = matching.map((l: Row) =>
        toDrillDown(l, (d, c) => d - c)
      );
      const amount = transactions.reduce((s, t) => s + t.amount, 0);
      return { box: boxDef.box, label: boxDef.label, amount, transactions };
    });

    // Unclassified input lines (vat_type IS NULL) default to Box 15 — standard purchases.
    const unclassifiedInput = vatLines.filter((l: Row) => {
      const isInput =
        String(l.account_type) === 'asset' ||
        String(l.account_subtype) === 'vat_input';
      return isInput && l.vat_type == null;
    });
    if (unclassifiedInput.length > 0) {
      const box15 = inputBoxes.find((b) => b.box === '15');
      if (box15) {
        const extra = unclassifiedInput.map((l: Row) =>
          toDrillDown(l, (d, c) => d - c)
        );
        box15.amount += extra.reduce((s, t) => s + t.amount, 0);
        box15.transactions.push(...extra);
      }
    }

    // ── Totals ───────────────────────────────────────────────────────────────
    const totalOutputTax = outputBoxes.reduce((s, b) => s + b.amount, 0);
    const totalInputTax  = inputBoxes.reduce((s, b) => s + b.amount, 0);
    const netVAT         = totalOutputTax - totalInputTax;

    // Legacy compatibility fields — summarise non-zero boxes as account-like lines.
    const outputDetails = outputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));
    const inputDetails = inputBoxes
      .filter((b) => Math.abs(b.amount) > 0.001)
      .map((b) => ({ accountCode: b.box, accountName: b.label, amount: b.amount }));

    return {
      periodStart,
      periodEnd,
      outputBoxes,
      totalOutputTax,
      inputBoxes,
      totalInputTax,
      netVAT,
      outputVAT: totalOutputTax,
      inputVAT:  totalInputTax,
      outputDetails,
      inputDetails,
    };
  } catch (err) {
    log.error('Failed to generate VAT return', { error: err }, 'accounting');
    throw err;
  }
}

// ── Project Profitability ────────────────────────────────────────────────────

export async function getProjectProfitability(companyId: string,
  periodStart: string,
  periodEnd: string
): Promise<ProjectProfitabilityReport[]> {
  try {
    const projectRows = (await sql`
      SELECT DISTINCT jl.project_id, p.project_name
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      LEFT JOIN projects p ON p.id = jl.project_id
      WHERE je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= ${periodStart}
        AND je.entry_date <= ${periodEnd}
        AND jl.project_id IS NOT NULL
      ORDER BY p.project_name
    `) as Row[];

    const reports: ProjectProfitabilityReport[] = [];

    for (const proj of projectRows) {
      const projectId = String(proj.project_id);
      const projectName = proj.project_name ? String(proj.project_name) : 'Unknown Project';

      const rows = (await sql`
        SELECT ga.account_code, ga.account_name, ga.account_type,
          COALESCE(SUM(jl.debit), 0) AS total_debit,
          COALESCE(SUM(jl.credit), 0) AS total_credit
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${periodStart}
          AND je.entry_date <= ${periodEnd}
          AND jl.project_id = ${projectId}::UUID
          AND ga.account_type IN ('revenue', 'expense')
        GROUP BY ga.id, ga.account_code, ga.account_name, ga.account_type
        ORDER BY ga.account_code
      `) as Row[];

      const revenueLines: ReportLineItem[] = [];
      const costLines: ReportLineItem[] = [];

      for (const r of rows) {
        const type = String(r.account_type);
        const debit = Number(r.total_debit);
        const credit = Number(r.total_credit);

        if (type === 'revenue') {
          const amount = credit - debit;
          if (Math.abs(amount) > 0.001) {
            revenueLines.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
          }
        } else if (type === 'expense') {
          const amount = debit - credit;
          if (Math.abs(amount) > 0.001) {
            costLines.push({ accountCode: String(r.account_code), accountName: String(r.account_name), amount });
          }
        }
      }

      const revenue = revenueLines.reduce((s, r) => s + r.amount, 0);
      const costs = costLines.reduce((s, c) => s + c.amount, 0);
      const profit = revenue - costs;
      const margin = revenue > 0 ? (profit / revenue) * 100 : 0;

      reports.push({
        projectId,
        projectName,
        periodStart,
        periodEnd,
        revenue,
        costs,
        profit,
        margin: Math.round(margin * 100) / 100,
        revenueLines,
        costLines,
      });
    }

    // Sort by profit DESC
    reports.sort((a, b) => b.profit - a.profit);
    return reports;
  } catch (err) {
    log.error('Failed to generate project profitability', { error: err }, 'accounting');
    throw err;
  }
}

/**
 * OCR Service — Document data extraction with VLM + regex fallback
 *
 * Primary:  Qwen3 VLM on vLLM (handles images AND text-based PDFs)
 * Fallback: Pattern-based regex extraction for PDFs with text layers
 *
 * Optimised for South African invoices and receipts.
 */

import { log } from '@/lib/logger';
import type { ExtractedDocument, ExtractedLineItem } from '@/modules/accounting/types/documentCapture.types';
import { extractWithVlm, extractPdfWithVlm, isVlmAvailable } from './vlmService';

// ---------------------------------------------------------------------------
// Public API
// ---------------------------------------------------------------------------

/**
 * Extract structured data from a PDF buffer.
 * Tries VLM first (if configured), then falls back to regex-based extraction.
 */
export async function extractFromPdf(buffer: Buffer): Promise<ExtractedDocument> {
  let rawText = '';
  const warnings: string[] = [];

  // Always attempt text extraction — used by VLM as context and as regex fallback
  try {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const pdfParse = require('pdf-parse');
    const data = await pdfParse(buffer);
    rawText = data.text || '';
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('PDF text extraction failed', { error: msg }, 'ocr-service');
    warnings.push(`PDF parsing failed: ${msg}`);
  }

  // --- VLM path ---
  if (isVlmAvailable()) {
    try {
      const vlmResult = await extractPdfWithVlm(buffer, rawText);
      if (vlmResult) {
        vlmResult.warnings.push(...warnings);
        return vlmResult;
      }
      warnings.push('VLM extraction returned no result — falling back to regex.');
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      log.warn('VLM extraction failed, falling back to regex', { error: msg }, 'ocr-service');
      warnings.push(`VLM extraction failed: ${msg}`);
    }
  }

  // --- Regex fallback ---
  if (!rawText.trim()) {
    warnings.push('No text found in PDF — the document may be image-based. Manual entry recommended.');
    return emptyResult(rawText, warnings);
  }

  return extractFromText(rawText, warnings);
}

/**
 * Extract structured data from an image buffer (JPEG/PNG).
 * Requires VLM — no regex fallback for images.
 */
export async function extractFromImage(
  imageBuffer: Buffer,
  mimeType: string,
): Promise<ExtractedDocument> {
  const warnings: string[] = [];

  if (!isVlmAvailable()) {
    warnings.push('VLM not configured — cannot extract from images. Set VLLM_BASE_URL in environment.');
    return emptyResult('', warnings);
  }

  try {
    const base64 = imageBuffer.toString('base64');
    const vlmResult = await extractWithVlm(base64, mimeType);
    if (vlmResult) return vlmResult;
    warnings.push('VLM returned no result for image.');
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    log.error('VLM image extraction failed', { error: msg }, 'ocr-service');
    warnings.push(`VLM image extraction failed: ${msg}`);
  }

  return emptyResult('', warnings);
}

/**
 * Extract structured data from raw text (e.g. pasted or OCR output).
 * Uses VLM if available (sends text as prompt), otherwise regex.
 */
export async function extractFromText(
  rawText: string,
  existingWarnings: string[] = [],
): Promise<ExtractedDocument> {
  const warnings = [...existingWarnings];
  const lines = rawText.split(/\n/).map(l => l.trim()).filter(Boolean);

  if (lines.length === 0) {
    warnings.push('Empty text provided');
    return emptyResult(rawText, warnings);
  }

  // --- Regex extraction ---
  const documentType = detectDocumentType(rawText);
  const vendorName = extractVendorName(lines);
  const vendorVatNumber = extractVatRegistration(rawText);
  const date = extractDate(rawText);
  const referenceNumber = extractReferenceNumber(rawText);
  const amounts = extractAmounts(rawText);
  const lineItems = extractLineItems(lines);

  const confidence = computeConfidence({
    vendorName,
    date,
    referenceNumber,
    totalAmount: amounts.totalAmount,
    vatAmount: amounts.vatAmount,
    lineItems,
  });

  if (confidence < 0.3) {
    warnings.push('Low extraction confidence — please review all fields carefully.');
  }

  return {
    documentType,
    vendorName,
    vendorVatNumber,
    vendorAddress: null,
    vendorBankDetails: null,
    customerName: null,
    customerVatNumber: null,
    date,
    dueDate: null,
    paymentTerms: null,
    referenceNumber,
    purchaseOrderRef: null,
    currency: 'ZAR',
    subtotal: amounts.subtotal,
    vatAmount: amounts.vatAmount,
    vatRate: amounts.vatAmount && amounts.subtotal ? Math.round((amounts.vatAmount / amounts.subtotal) * 100) : null,
    totalAmount: amounts.totalAmount,
    lineItems: lineItems.map(li => ({
      ...li,
      vatAmount: null,
      vatClassification: null,
      glAccountSuggestion: null,
    })),
    rawText,
    confidence,
    warnings,
    extractionMethod: 'regex',
  };
}

// ---------------------------------------------------------------------------
// Document type detection
// ---------------------------------------------------------------------------

function detectDocumentType(text: string): ExtractedDocument['documentType'] {
  const upper = text.toUpperCase();

  if (/CREDIT\s*NOTE/i.test(upper)) return 'credit_note';
  if (/PURCHASE\s*ORDER/i.test(upper)) return 'purchase_order';
  if (/DELIVERY\s*NOTE/i.test(upper)) return 'delivery_note';
  if (/TAX\s*INVOICE/i.test(upper)) return 'invoice';
  if (/INVOICE/i.test(upper)) return 'invoice';
  if (/STATEMENT/i.test(upper)) return 'statement';
  if (/RECEIPT/i.test(upper) || /PROOF\s*OF\s*PAYMENT/i.test(upper)) return 'receipt';

  return 'unknown';
}

// ---------------------------------------------------------------------------
// Vendor name extraction
// ---------------------------------------------------------------------------

function extractVendorName(lines: string[]): string | null {
  const skipPatterns = [
    /^(TAX\s*)?INVOICE$/i,
    /^CREDIT\s*NOTE$/i,
    /^STATEMENT$/i,
    /^RECEIPT$/i,
    /^(page|date|ref|invoice|tel|fax|email|vat|tax|reg)/i,
    /^\d{1,2}[/-]\d{1,2}[/-]\d{2,4}$/,
    /^P\.?O\.?\s*BOX/i,
    /^\d+\s+(street|road|avenue|drive|lane|crescent)/i,
  ];

  for (let i = 0; i < Math.min(lines.length, 8); i++) {
    const line = lines[i];
    if (!line || line.length < 3 || line.length > 80) continue;
    if (skipPatterns.some(p => p.test(line))) continue;
    if (/^\d+$/.test(line)) continue;
    if (/\b\d{4}\b.*\b(South Africa|SA|RSA)\b/i.test(line)) continue;

    return line;
  }

  const fromMatch = lines.join('\n').match(/(?:From|Supplier|Vendor|Company)\s*[:-]\s*(.+)/i);
  if (fromMatch && fromMatch[1]) return fromMatch[1].trim();

  return null;
}

// ---------------------------------------------------------------------------
// VAT registration number
// ---------------------------------------------------------------------------

function extractVatRegistration(text: string): string | null {
  const patterns = [
    /VAT\s*(?:Reg(?:istration)?\.?\s*)?(?:No\.?|Number|#)\s*[:-]?\s*(\d{10})/i,
    /VAT\s*[:-]?\s*(\d{10})/i,
    /(?:Reg(?:istration)?\.?\s*)?(?:No\.?|Number)\s*[:-]?\s*(\d{10})/i,
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1]) return match[1];
  }

  return null;
}

// ---------------------------------------------------------------------------
// Date extraction
// ---------------------------------------------------------------------------

function extractDate(text: string): string | null {
  const months: Record<string, string> = {
    jan: '01', january: '01',
    feb: '02', february: '02',
    mar: '03', march: '03',
    apr: '04', april: '04',
    may: '05',
    jun: '06', june: '06',
    jul: '07', july: '07',
    aug: '08', august: '08',
    sep: '09', september: '09',
    oct: '10', october: '10',
    nov: '11', november: '11',
    dec: '12', december: '12',
  };

  const labelledPatterns = [
    /(?:Invoice|Document|Tax Invoice|Statement)\s*Date\s*[:-]?\s*(.+)/i,
    /Date\s*[:-]\s*(.+)/i,
    /Dated?\s*[:-]\s*(.+)/i,
  ];

  for (const pattern of labelledPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      const parsed = parseDateString(match[1].trim(), months);
      if (parsed) return parsed;
    }
  }

  const slashDate = text.match(/\b(\d{1,2})[/-](\d{1,2})[/-](\d{4})\b/);
  if (slashDate) {
    const [, d, m, y] = slashDate;
    const day = d!.padStart(2, '0');
    const month = m!.padStart(2, '0');
    if (parseInt(month) >= 1 && parseInt(month) <= 12) {
      return `${y}-${month}-${day}`;
    }
  }

  const isoDate = text.match(/\b(\d{4})-(\d{2})-(\d{2})\b/);
  if (isoDate) {
    return `${isoDate[1]}-${isoDate[2]}-${isoDate[3]}`;
  }

  const longDate = text.match(/\b(\d{1,2})\s+(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{4})\b/i);
  if (longDate) {
    const day = longDate[1]!.padStart(2, '0');
    const monthNum = months[longDate[2]!.toLowerCase()];
    if (monthNum) return `${longDate[3]}-${monthNum}-${day}`;
  }

  return null;
}

function parseDateString(str: string, months: Record<string, string>): string | null {
  const slashMatch = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{4})/);
  if (slashMatch) {
    const day = slashMatch[1]!.padStart(2, '0');
    const month = slashMatch[2]!.padStart(2, '0');
    if (parseInt(month) >= 1 && parseInt(month) <= 12) {
      return `${slashMatch[3]}-${month}-${day}`;
    }
  }

  const isoMatch = str.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (isoMatch) return `${isoMatch[1]}-${isoMatch[2]}-${isoMatch[3]}`;

  const longMatch = str.match(/^(\d{1,2})\s+(\w+)\s+(\d{4})/);
  if (longMatch) {
    const monthKey = longMatch[2]!.toLowerCase();
    const monthNum = months[monthKey];
    if (monthNum) {
      const day = longMatch[1]!.padStart(2, '0');
      return `${longMatch[3]}-${monthNum}-${day}`;
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Reference / invoice number extraction
// ---------------------------------------------------------------------------

function extractReferenceNumber(text: string): string | null {
  const patterns = [
    /Invoice\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /Ref(?:erence)?\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /(?:INV|REF|CN|CR)\s*[-#]?\s*(\d{3,})/i,
    /Document\s*(?:No\.?|Number)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /Order\s*(?:No\.?|Number)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
    /Receipt\s*(?:No\.?|Number|#)\s*[:-]?\s*([A-Za-z0-9/-]+)/i,
  ];

  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match && match[1] && match[1].length >= 3) {
      return match[1].trim();
    }
  }

  return null;
}

// ---------------------------------------------------------------------------
// Amount extraction (Total, VAT, Subtotal)
// ---------------------------------------------------------------------------

interface ExtractedAmounts {
  subtotal: number | null;
  vatAmount: number | null;
  totalAmount: number | null;
}

function extractAmounts(text: string): ExtractedAmounts {
  const result: ExtractedAmounts = {
    subtotal: null,
    vatAmount: null,
    totalAmount: null,
  };

  const totalPatterns = [
    /(?:Grand\s*)?Total\s*(?:Due|Amount|Payable)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /(?:Amount|Balance)\s*(?:Due|Owing|Payable)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Total\s*(?:Incl(?:uding)?\.?\s*(?:VAT|Tax))?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of totalPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.totalAmount = parseAmount(match[1]);
      break;
    }
  }

  const vatPatterns = [
    /VAT\s*(?:@\s*\d+%?)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Tax\s*(?:Amount)?\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /VAT\s*\(\s*15\s*%\s*\)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of vatPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.vatAmount = parseAmount(match[1]);
      break;
    }
  }

  const subtotalPatterns = [
    /Sub\s*[-\s]?Total\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Total\s*(?:Excl(?:uding)?\.?\s*(?:VAT|Tax))\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
    /Nett?\s*(?:Amount|Total)\s*[:-]?\s*(?:ZAR|R)?\s*(\d[\d\s,]*\d(?:\.\d{2})?|\d+(?:\.\d{2})?)/i,
  ];

  for (const pattern of subtotalPatterns) {
    const match = text.match(pattern);
    if (match && match[1]) {
      result.subtotal = parseAmount(match[1]);
      break;
    }
  }

  if (result.totalAmount !== null && result.vatAmount !== null && result.subtotal === null) {
    result.subtotal = Math.round((result.totalAmount - result.vatAmount) * 100) / 100;
  }

  if (result.subtotal !== null && result.vatAmount !== null && result.totalAmount === null) {
    result.totalAmount = Math.round((result.subtotal + result.vatAmount) * 100) / 100;
  }

  return result;
}

function parseAmount(str: string): number {
  const cleaned = str.replace(/[\s,]/g, '');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : Math.round(num * 100) / 100;
}

// ---------------------------------------------------------------------------
// Line item extraction
// ---------------------------------------------------------------------------

interface RegexLineItem {
  description: string;
  quantity: number | null;
  unitPrice: number | null;
  total: number | null;
}

function extractLineItems(lines: string[]): RegexLineItem[] {
  const items: RegexLineItem[] = [];

  const lineItemPattern = /^(.+?)\s+(\d+(?:\.\d+)?)\s+(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)\s+(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)$/;
  const simpleLinePattern = /^(.{3,}?)\s{2,}(?:R?\s*)?(\d[\d,]*(?:\.\d{2})?)$/;

  let itemsStarted = false;
  const headerPattern = /(?:description|item|product|service)\s.*(?:qty|quantity|amount|price|total)/i;

  for (const line of lines) {
    if (headerPattern.test(line)) {
      itemsStarted = true;
      continue;
    }

    if (!itemsStarted && items.length === 0) {
      const match = lineItemPattern.exec(line);
      if (match) itemsStarted = true;
    }

    if (!itemsStarted) continue;

    if (/^(Sub\s*[-\s]?Total|Total|VAT|Tax|Amount\s*Due|Balance\s*Due|Grand\s*Total)/i.test(line)) {
      break;
    }

    const fullMatch = lineItemPattern.exec(line);
    if (fullMatch) {
      items.push({
        description: fullMatch[1]!.trim(),
        quantity: parseFloat(fullMatch[2]!),
        unitPrice: parseAmount(fullMatch[3]!),
        total: parseAmount(fullMatch[4]!),
      });
      continue;
    }

    const simpleMatch = simpleLinePattern.exec(line);
    if (simpleMatch) {
      items.push({
        description: simpleMatch[1]!.trim(),
        quantity: null,
        unitPrice: null,
        total: parseAmount(simpleMatch[2]!),
      });
    }
  }

  return items;
}

// ---------------------------------------------------------------------------
// Confidence scoring
// ---------------------------------------------------------------------------

function computeConfidence(fields: {
  vendorName: string | null;
  date: string | null;
  referenceNumber: string | null;
  totalAmount: number | null;
  vatAmount: number | null;
  lineItems: RegexLineItem[];
}): number {
  let score = 0;
  const weights = {
    vendorName: 0.2,
    date: 0.2,
    referenceNumber: 0.15,
    totalAmount: 0.25,
    vatAmount: 0.1,
    lineItems: 0.1,
  };

  if (fields.vendorName) score += weights.vendorName;
  if (fields.date) score += weights.date;
  if (fields.referenceNumber) score += weights.referenceNumber;
  if (fields.totalAmount !== null && fields.totalAmount > 0) score += weights.totalAmount;
  if (fields.vatAmount !== null && fields.vatAmount > 0) score += weights.vatAmount;
  if (fields.lineItems.length > 0) score += weights.lineItems;

  return Math.round(score * 100) / 100;
}

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function emptyResult(rawText: string, warnings: string[]): ExtractedDocument {
  return {
    documentType: 'unknown',
    vendorName: null,
    vendorVatNumber: null,
    vendorAddress: null,
    vendorBankDetails: null,
    customerName: null,
    customerVatNumber: null,
    date: null,
    dueDate: null,
    paymentTerms: null,
    referenceNumber: null,
    purchaseOrderRef: null,
    currency: null,
    subtotal: null,
    vatAmount: null,
    vatRate: null,
    totalAmount: null,
    lineItems: [],
    rawText,
    confidence: 0,
    warnings,
    extractionMethod: 'regex',
  };
}

/**
 * KPI Dashboard Service
 * Real-time financial KPIs from the general ledger, invoices, and bank accounts.
 */

import { sql } from '@/lib/neon';
import { log } from '@/lib/logger';

type Row = Record<string, unknown>;

// ── Types ───────────────────────────────────────────────────────────────────

export interface DashboardKPIs {
  revenue: { total: number; priorTotal: number; changePercent: number };
  expenses: { total: number; priorTotal: number };
  grossProfit: { amount: number; margin: number };
  netProfit: { amount: number; margin: number };
  cash: { total: number; priorTotal: number; change: number };
  receivables: { total: number; overdue: number; avgDebtorDays: number };
  payables: { total: number; overdue: number; avgCreditorDays: number };
  activity: { invoicesIssued: number; paymentsReceived: number; journalsPosted: number };
}

export interface ChartPoint {
  month: string;
  revenue: number;
  expenses: number;
}

export interface CashFlowPoint {
  month: string;
  inflows: number;
  outflows: number;
}

export interface AgingBreakdownBucket {
  name: string;
  value: number;
}

export interface TopCustomer {
  name: string;
  revenue: number;
  invoiceCount: number;
}

export interface TopExpenseCategory {
  accountName: string;
  total: number;
  percentOfExpenses: number;
}

// ── Dashboard KPIs ──────────────────────────────────────────────────────────

export async function getDashboardKPIs(companyId: string,
  fromDate: string,
  toDate: string
): Promise<DashboardKPIs> {
  try {
    // Calculate prior period (same duration before fromDate)
    const from = new Date(fromDate);
    const to = new Date(toDate);
    const durationMs = to.getTime() - from.getTime();
    const priorFrom = new Date(from.getTime() - durationMs);
    const priorFromStr = priorFrom.toISOString().slice(0, 10);
    const priorToStr = new Date(from.getTime() - 86400000).toISOString().slice(0, 10);

    const [
      revenueRows,
      priorRevenueRows,
      expenseRows,
      priorExpenseRows,
      cashRows,
      priorCashRows,
      arRows,
      arOverdueRows,
      arDebtorDaysRows,
      apRows,
      apOverdueRows,
      apCreditorDaysRows,
      invoicesIssuedRows,
      paymentsReceivedRows,
      journalsPostedRows,
    ] = await Promise.all([
      // Current period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period revenue
      sql`
        SELECT COALESCE(SUM(jl.credit - jl.debit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'revenue' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${fromDate} AND je.entry_date <= ${toDate}
      `,
      // Prior period expenses
      sql`
        SELECT COALESCE(SUM(jl.debit - jl.credit), 0) AS total
        FROM gl_journal_lines jl
        JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
        JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        WHERE ga.account_type = 'expense' AND je.status = 'posted'
          AND je.company_id = ${companyId}::UUID
          AND je.entry_date >= ${priorFromStr} AND je.entry_date <= ${priorToStr}
      `,
      // Current cash position (sum of all bank account balances from transactions)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
      `,
      // Prior period cash (transactions up to prior period end)
      sql`
        SELECT COALESCE(SUM(bt.amount), 0) AS total
        FROM bank_transactions bt
        JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        WHERE ga.account_subtype = 'bank' AND ga.is_active = true
          AND bt.company_id = ${companyId}::UUID
          AND bt.transaction_date <= ${priorToStr}
      `,
      // AR total outstanding
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
      `,
      // AR overdue
      sql`
        SELECT COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
          AND due_date < CURRENT_DATE
      `,
      // Average debtor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_at, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM customer_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // AP total outstanding
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
      `,
      // AP overdue
      sql`
        SELECT COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
          AND due_date < CURRENT_DATE
      `,
      // Average creditor days
      sql`
        SELECT COALESCE(AVG(
          EXTRACT(EPOCH FROM (COALESCE(paid_at, CURRENT_DATE) - invoice_date)) / 86400
        ), 0) AS avg_days
        FROM supplier_invoices
        WHERE status NOT IN ('cancelled', 'draft')
          AND company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate}
      `,
      // Invoices issued this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND invoice_date >= ${fromDate} AND invoice_date <= ${toDate}
          AND status NOT IN ('cancelled', 'draft')
      `,
      // Payments received this period
      sql`
        SELECT COUNT(*) AS count
        FROM customer_invoices
        WHERE company_id = ${companyId}::UUID
          AND paid_at >= ${fromDate} AND paid_at <= ${toDate}
      `,
      // Journal entries posted this period
      sql`
        SELECT COUNT(*) AS count
        FROM gl_journal_entries
        WHERE company_id = ${companyId}::UUID
          AND status = 'posted'
          AND entry_date >= ${fromDate} AND entry_date <= ${toDate}
      `,
    ]);

    const totalRevenue = Number((revenueRows as Row[])[0]?.total || 0);
    const priorRevenue = Number((priorRevenueRows as Row[])[0]?.total || 0);
    const totalExpenses = Number((expenseRows as Row[])[0]?.total || 0);
    const priorExpenses = Number((priorExpenseRows as Row[])[0]?.total || 0);
    const cashTotal = Number((cashRows as Row[])[0]?.total || 0);
    const priorCash = Number((priorCashRows as Row[])[0]?.total || 0);

    const grossProfit = totalRevenue - totalExpenses;
    const grossMargin = totalRevenue > 0 ? (grossProfit / totalRevenue) * 100 : 0;
    const revenueChange = priorRevenue > 0
      ? ((totalRevenue - priorRevenue) / priorRevenue) * 100
      : totalRevenue > 0 ? 100 : 0;

    return {
      revenue: { total: totalRevenue, priorTotal: priorRevenue, changePercent: revenueChange },
      expenses: { total: totalExpenses, priorTotal: priorExpenses },
      grossProfit: { amount: grossProfit, margin: grossMargin },
      netProfit: { amount: grossProfit, margin: grossMargin },
      cash: { total: cashTotal, priorTotal: priorCash, change: cashTotal - priorCash },
      receivables: {
        total: Number((arRows as Row[])[0]?.total || 0),
        overdue: Number((arOverdueRows as Row[])[0]?.total || 0),
        avgDebtorDays: Math.round(Number((arDebtorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      payables: {
        total: Number((apRows as Row[])[0]?.total || 0),
        overdue: Number((apOverdueRows as Row[])[0]?.total || 0),
        avgCreditorDays: Math.round(Number((apCreditorDaysRows as Row[])[0]?.avg_days || 0)),
      },
      activity: {
        invoicesIssued: Number((invoicesIssuedRows as Row[])[0]?.count || 0),
        paymentsReceived: Number((paymentsReceivedRows as Row[])[0]?.count || 0),
        journalsPosted: Number((journalsPostedRows as Row[])[0]?.count || 0),
      },
    };
  } catch (err) {
    log.error('Failed to get dashboard KPIs', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Revenue Chart ───────────────────────────────────────────────────────────

export async function getRevenueChart(companyId: string, months: number): Promise<ChartPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN ga.account_type = 'revenue' THEN jl.credit - jl.debit ELSE 0 END), 0) AS revenue,
        COALESCE(SUM(CASE WHEN ga.account_type = 'expense' THEN jl.debit - jl.credit ELSE 0 END), 0) AS expenses
      FROM months m
      LEFT JOIN gl_journal_entries je
        ON je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
        AND je.entry_date >= m.month_start
        AND je.entry_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_journal_lines jl ON jl.journal_entry_id = je.id
      LEFT JOIN gl_accounts ga ON ga.id = jl.gl_account_id
        AND ga.account_type IN ('revenue', 'expense')
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(String(r.month_start)).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      revenue: Math.abs(Number(r.revenue || 0)),
      expenses: Math.abs(Number(r.expenses || 0)),
    }));
  } catch (err) {
    log.error('Failed to get revenue chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Cash Flow Chart ─────────────────────────────────────────────────────────

export async function getCashFlowChart(companyId: string, months: number): Promise<CashFlowPoint[]> {
  try {
    const rows = (await sql`
      WITH months AS (
        SELECT generate_series(
          date_trunc('month', CURRENT_DATE) - (${months - 1} || ' months')::INTERVAL,
          date_trunc('month', CURRENT_DATE),
          '1 month'::INTERVAL
        )::DATE AS month_start
      )
      SELECT
        m.month_start,
        COALESCE(SUM(CASE WHEN bt.amount > 0 THEN bt.amount ELSE 0 END), 0) AS inflows,
        COALESCE(SUM(CASE WHEN bt.amount < 0 THEN ABS(bt.amount) ELSE 0 END), 0) AS outflows
      FROM months m
      LEFT JOIN bank_transactions bt
        ON bt.company_id = ${companyId}::UUID
        AND bt.transaction_date >= m.month_start
        AND bt.transaction_date < m.month_start + '1 month'::INTERVAL
      LEFT JOIN gl_accounts ga ON ga.id = bt.bank_account_id
        AND ga.account_subtype = 'bank' AND ga.is_active = true
      GROUP BY m.month_start
      ORDER BY m.month_start
    `) as Row[];

    return rows.map((r: Row) => ({
      month: new Date(String(r.month_start)).toLocaleDateString('en-ZA', { month: 'short', year: '2-digit' }),
      inflows: Number(r.inflows || 0),
      outflows: Number(r.outflows || 0),
    }));
  } catch (err) {
    log.error('Failed to get cash flow chart', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Aging Breakdown ─────────────────────────────────────────────────────────

export async function getAgingBreakdown(companyId: string, type: 'ar' | 'ap'): Promise<AgingBreakdownBucket[]> {
  try {
    let rows: Row[];

    if (type === 'ar') {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(total_amount - COALESCE(amount_paid, 0)), 0) AS total
        FROM customer_invoices
        WHERE status IN ('approved', 'sent', 'partially_paid', 'overdue')
          AND company_id = ${companyId}::UUID
          AND (total_amount - COALESCE(amount_paid, 0)) > 0
        GROUP BY bucket
      `) as Row[];
    } else {
      rows = (await sql`
        SELECT
          CASE
            WHEN due_date >= CURRENT_DATE THEN 'Current'
            WHEN CURRENT_DATE - due_date <= 30 THEN '30 Days'
            WHEN CURRENT_DATE - due_date <= 60 THEN '60 Days'
            ELSE '90+ Days'
          END AS bucket,
          COALESCE(SUM(balance), 0) AS total
        FROM supplier_invoices
        WHERE status IN ('approved', 'partially_paid')
          AND company_id = ${companyId}::UUID
          AND balance > 0
        GROUP BY bucket
      `) as Row[];
    }

    // Ensure all buckets exist in correct order
    const bucketOrder = ['Current', '30 Days', '60 Days', '90+ Days'];
    const bucketMap = new Map<string, number>();
    for (const b of bucketOrder) bucketMap.set(b, 0);
    for (const r of rows) {
      bucketMap.set(String(r.bucket), Number(r.total || 0));
    }

    return bucketOrder.map(name => ({ name, value: bucketMap.get(name) || 0 }));
  } catch (err) {
    log.error('Failed to get aging breakdown', { error: err, type }, 'kpi-service');
    throw err;
  }
}

// ── Top Customers ───────────────────────────────────────────────────────────

export async function getTopCustomers(companyId: string, limit: number): Promise<TopCustomer[]> {
  try {
    const rows = (await sql`
      SELECT c.name AS name,
        COALESCE(SUM(ci.total_amount), 0) AS revenue,
        COUNT(ci.id) AS invoice_count
      FROM customer_invoices ci
      JOIN customers c ON c.id = ci.customer_id
      WHERE ci.status NOT IN ('cancelled', 'draft')
        AND ci.company_id = ${companyId}::UUID
      GROUP BY c.id, c.name
      ORDER BY revenue DESC
      LIMIT ${limit}
    `) as Row[];

    return rows.map((r: Row) => ({
      name: String(r.name),
      revenue: Number(r.revenue || 0),
      invoiceCount: Number(r.invoice_count || 0),
    }));
  } catch (err) {
    log.error('Failed to get top customers', { error: err }, 'kpi-service');
    throw err;
  }
}

// ── Top Expense Categories ──────────────────────────────────────────────────

export async function getTopExpenseCategories(companyId: string, limit: number): Promise<TopExpenseCategory[]> {
  try {
    const rows = (await sql`
      SELECT ga.account_name,
        COALESCE(SUM(jl.debit - jl.credit), 0) AS total
      FROM gl_journal_lines jl
      JOIN gl_journal_entries je ON je.id = jl.journal_entry_id
      JOIN gl_accounts ga ON ga.id = jl.gl_account_id
      WHERE ga.account_type = 'expense' AND je.status = 'posted'
        AND je.company_id = ${companyId}::UUID
      GROUP BY ga.id, ga.account_name
      HAVING SUM(jl.debit - jl.credit) > 0
      ORDER BY total DESC
      LIMIT ${limit}
    `) as Row[];

    const totalExpenses = rows.reduce((s: number, r: Row) => s + Number(r.total || 0), 0);

    return rows.map((r: Row) => {
      const total = Number(r.total || 0);
      return {
        accountName: String(r.account_name),
        total,
        percentOfExpenses: totalExpenses > 0 ? (total / totalExpenses) * 100 : 0,
      };
    });
  } catch (err) {
    log.error('Failed to get top expense categories', { error: err }, 'kpi-service');
    throw err;
  }
}

