              Start Free Trial
            </a>
          </div>

          <button onClick={onToggleMobile} className="lg:hidden p-2 text-gray-600">
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {mobileMenuOpen && (
