    expect(result.inputInvoices[0]!.invoiceNumber).toBe('SINV-s-list-1');
    expect(result.inputInvoices[0]!.vatAmount).toBe(3000);
    expect(result.inputInvoices[0]!.vatType).toBe('standard');
