describe('autoMatchTransactions', () => {
  beforeEach(() => vi.clearAllMocks());

  it('returns zeros and empty candidates when no unmatched bank transactions exist', async () => {
    // bank_transactions query — empty
    vi.mocked(sql).mockResolvedValueOnce([] as never);

    const result = await autoMatchTransactions(COMPANY_ID, BANK_ACCOUNT_ID);
    expect(result.matched).toBe(0);
    expect(result.unmatched).toBe(0);
    expect(result.candidates).toHaveLength(0);
  });

  it('returns unmatched count when GL has no matching lines', async () => {
    // bank_transactions — one unmatched tx
    vi.mocked(sql).mockResolvedValueOnce([
      { id: TX_ID, amount: -1500, transaction_date: '2026-03-10', reference: null, description: 'TEST' },
    ] as never);
    // gl_journal_lines — empty (nothing to match against)
    vi.mocked(sql).mockResolvedValueOnce([] as never);

    const result = await autoMatchTransactions(COMPANY_ID, BANK_ACCOUNT_ID);
    expect(result.matched).toBe(0);
    expect(result.unmatched).toBe(1);
  });

  it('auto-matches when bank amount equals GL net (debit - credit)', async () => {
    // bank tx: -1500
    vi.mocked(sql).mockResolvedValueOnce([
      { id: TX_ID, amount: -1500, transaction_date: '2026-03-10', reference: 'REF-001', description: 'SUPPLIER PMT' },
    ] as never);
    // GL line: credit 1500, debit 0 → net -1500
    vi.mocked(sql).mockResolvedValueOnce([
      { id: JL_ID, debit: 0, credit: 1500, description: 'SUPPLIER PMT', entry_date: '2026-03-10', entry_number: 'JE-2026-00001', source_document_id: null },
    ] as never);
    // matchTransaction UPDATE — called for confidence >= 0.9
    vi.mocked(sql).mockResolvedValueOnce([
      makeTxRow({ status: 'matched', matched_journal_line_id: JL_ID }),
    ] as never);

    const result = await autoMatchTransactions(COMPANY_ID, BANK_ACCOUNT_ID);
    expect(result.matched).toBe(1);
    expect(result.unmatched).toBe(0);
  });

  it('leaves low-confidence matches as candidates without updating DB', async () => {
    // bank tx
    vi.mocked(sql).mockResolvedValueOnce([
      { id: TX_ID, amount: -1500, transaction_date: '2026-03-10', reference: null, description: 'VAGUE DESC' },
    ] as never);
    // GL line: same amount but different date and no reference overlap
    vi.mocked(sql).mockResolvedValueOnce([
      { id: JL_ID, debit: 0, credit: 1500, description: 'DIFFERENT TEXT', entry_date: '2026-02-01', entry_number: 'JE-2026-00001', source_document_id: null },
    ] as never);

    const result = await autoMatchTransactions(COMPANY_ID, BANK_ACCOUNT_ID);
    // Low confidence (< 0.9) → no DB update; appears as candidate or unmatched
    expect(result.matched).toBe(0);
    // The transaction either appears as a candidate or unmatched
    const totalAccountedFor = result.candidates.length + result.unmatched;
    expect(totalAccountedFor).toBeGreaterThan(0);
    // matchTransaction SQL should NOT have been called (no high-confidence match)
    // Only the first two sql calls (bank txs + GL lines) should have been made
    expect(vi.mocked(sql).mock.calls.length).toBe(2);
  });

  it('propagates sql errors from bank transaction query', async () => {
    vi.mocked(sql).mockRejectedValueOnce(new Error('connection refused') as never);

    await expect(
      autoMatchTransactions(COMPANY_ID, BANK_ACCOUNT_ID)
    ).rejects.toThrow('connection refused');
  });
});

