      glRow({ accountCode: '4000', accountName: 'Revenue',  accountType: 'revenue', debit: 0,      credit: 50000 }),
      glRow({ accountCode: '6000', accountName: 'Expenses', accountType: 'expense', debit: 80000,  credit: 0    }),
