  it('propagates sql errors to the caller', async () => {
    mockSql.mockRejectedValueOnce(new Error('query timeout'));
    await expect(getVATReturn(COMPANY_ID, PERIOD_START, PERIOD_END)).rejects.toThrow('query timeout');
  });
});

