            from={from} to={to} loading={loading} vatPeriod={vatPeriod} alignment={alignment}
            quickPeriods={quickPeriods}
            onFromChange={setFrom} onToChange={setTo}
            onQuickSelect={(f, t) => { setFrom(f); setTo(t); }}
            onGenerate={generate}
          />

