                    <span className={`text-lg font-bold ${data.field11_vatPayableOrRefundable >= 0 ? 'text-red-400' : 'text-emerald-400'}`}>
                      {fmt(Math.abs(data.field11_vatPayableOrRefundable))}
                    </span>
                  </div>
                </div>
