  label: string;
}

export interface ComplianceEvent {
  id?: string;
  eventType: string;
  dueDate: string;
  description: string;
  status: 'pending' | 'completed' | 'overdue';
  submissionId?: string;
}

export interface SARSSubmission {
  id: string;
