    if (!itemsStarted) continue;
    if (/^(Sub\s*[-\s]?Total|Total|VAT|Tax|Amount\s*Due|Balance\s*Due|Grand\s*Total)/i.test(line)) break;

    const fullMatch = lineItemPattern.exec(line);
