                      {stats.map((s) => (
                        <tr key={s.tableName}>
                          <td className="py-2.5 font-medium text-[var(--ff-text-primary)]">{TABLE_LABELS[s.tableName] ?? s.tableName}</td>
                          <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">{s.rowCount.toLocaleString()}</td>
                          <td className="py-2.5 text-right text-[var(--ff-text-muted)]">{s.oldestDate ?? '—'}</td>
                          <td className="py-2.5 text-right text-[var(--ff-text-muted)]">{s.newestDate ?? '—'}</td>
                        </tr>
                      ))}
                    </tbody>
                    <tfoot>
                      <tr className="border-t-2 border-[var(--ff-border)]">
                        <td className="pt-3 font-bold text-[var(--ff-text-primary)]">Total</td>
                        <td className="pt-3 text-right font-bold text-[var(--ff-text-primary)]">{totalRows.toLocaleString()}</td>
                        <td colSpan={2} />
                      </tr>
                    </tfoot>
                  </table>
                </div>
              )}
            </Section>

            <Section title="Archive Wizard" icon={<Archive className="h-4 w-4" />}>
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-medium text-[var(--ff-text-primary)] mb-1.5">Cutoff Date</label>
                  <p className="text-xs text-[var(--ff-text-muted)] mb-2">
                    Records before this date (fully finalised) will be moved to archive tables.
                    Maximum allowed cutoff: <strong>{maxCutoff}</strong> (5-year minimum retention).
                  </p>
                  <input type="date" value={cutoffDate} max={maxCutoff}
                    onChange={(e) => { setCutoffDate(e.target.value); setValidation(null); setPreview(null); setArchiveError(null); setArchiveSuccess(false); }}
                    className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] px-3 py-2 text-sm w-48 focus:outline-none focus:ring-2 focus:ring-teal-500" />
                </div>
                <div className="flex flex-wrap gap-3">
                  <button onClick={() => void handleValidate()} disabled={!cutoffDate || validating}
                    className="flex items-center gap-2 text-sm px-4 py-2 rounded-lg border border-[var(--ff-border)] hover:bg-[var(--ff-bg-secondary)] text-[var(--ff-text-primary)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                    {validating ? <Loader2 className="h-4 w-4 animate-spin" /> : <CheckCircle2 className="h-4 w-4" />} Validate
                  </button>
                  <button onClick={() => void handlePreview()} disabled={!cutoffDate || previewing}
                    className="flex items-center gap-2 text-sm px-4 py-2 rounded-lg border border-[var(--ff-border)] hover:bg-[var(--ff-bg-secondary)] text-[var(--ff-text-primary)] disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                    {previewing ? <Loader2 className="h-4 w-4 animate-spin" /> : <Eye className="h-4 w-4" />} Preview
                  </button>
                  <button onClick={() => setShowConfirm(true)} disabled={!validation?.valid || archiving}
                    className="flex items-center gap-2 text-sm px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white disabled:opacity-50 disabled:cursor-not-allowed transition-colors">
                    {archiving ? <Loader2 className="h-4 w-4 animate-spin" /> : <Archive className="h-4 w-4" />} Archive Now
                  </button>
                </div>
                {validation && (
                  <div className={`rounded-lg border p-4 ${validation.valid ? 'border-green-300 bg-green-50' : 'border-red-300 bg-red-50'}`}>
                    <div className="flex items-center gap-2 mb-2">
                      {validation.valid ? <CheckCircle2 className="h-5 w-5 text-green-600" /> : <XCircle className="h-5 w-5 text-red-600" />}
                      <span className={`text-sm font-semibold ${validation.valid ? 'text-green-800' : 'text-red-800'}`}>
                        {validation.valid ? 'Validation Passed' : 'Validation Failed'}
                      </span>
                    </div>
                    {validation.errors.length > 0 && (
                      <ul className="list-disc list-inside space-y-1">
                        {validation.errors.map((e, i) => <li key={i} className="text-sm text-red-700">{e}</li>)}
                      </ul>
                    )}
                  </div>
                )}
                {preview && (
                  <div className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] p-4">
                    <p className="text-sm font-semibold text-[var(--ff-text-primary)] mb-3">Records that would be archived before {cutoffDate}:</p>
                    <dl className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                      {[
                        { label: 'Journal Entries', value: preview.journalEntries },
                        { label: 'Journal Lines', value: preview.journalLines },
                        { label: 'Bank Transactions', value: preview.bankTransactions },
                        { label: 'Customer Invoices', value: preview.customerInvoices },
                        { label: 'Supplier Invoices', value: preview.supplierInvoices },
                      ].map((item) => (
                        <div key={item.label} className="rounded-lg bg-[var(--ff-bg-secondary)] p-3">
                          <dt className="text-xs text-[var(--ff-text-muted)]">{item.label}</dt>
                          <dd className="text-lg font-bold text-[var(--ff-text-primary)]">{item.value.toLocaleString()}</dd>
                        </div>
                      ))}
                      <div className="rounded-lg bg-teal-50 border border-teal-200 p-3">
                        <dt className="text-xs text-teal-700 font-medium">Total Records</dt>
                        <dd className="text-lg font-bold text-teal-800">{preview.totalRecords.toLocaleString()}</dd>
                      </div>
                    </dl>
                  </div>
                )}
                {archiveSuccess && (
                  <div className="flex items-center gap-2 rounded-lg border border-green-300 bg-green-50 p-4 text-sm text-green-800">
                    <CheckCircle2 className="h-5 w-5 text-green-600 flex-shrink-0" />
                    Archive completed successfully. Data has been moved to archive tables.
                  </div>
                )}
                {archiveError && (
                  <div className="flex items-center gap-2 rounded-lg border border-red-300 bg-red-50 p-4 text-sm text-red-800">
                    <XCircle className="h-5 w-5 text-red-600 flex-shrink-0" />
                    {archiveError}
                  </div>
                )}
              </div>
            </Section>

            <Section title="Archive History" icon={<Clock className="h-4 w-4" />}>
              {runsLoading ? (
                <div className="flex items-center gap-2 text-[var(--ff-text-muted)]"><Loader2 className="h-4 w-4 animate-spin" /> Loading history...</div>
              ) : runs.length === 0 ? (
                <p className="text-sm text-[var(--ff-text-muted)]">No archive runs yet.</p>
              ) : (
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border)]">
                        {['Date Run', 'Cutoff', 'Status', 'Entries', 'Transactions', 'Invoices', 'Duration'].map((h, i) => (
                          <th key={h} className={`pb-2 ${i < 3 ? 'text-left' : 'text-right'} font-semibold text-[var(--ff-text-muted)]`}>{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border)]">
                      {runs.map((run) => {
                        const duration = run.startedAt && run.completedAt
                          ? Math.round((new Date(run.completedAt).getTime() - new Date(run.startedAt).getTime()) / 1000)
                          : null;
                        return (
                          <tr key={run.id}>
                            <td className="py-2.5 text-[var(--ff-text-secondary)]">{new Date(run.createdAt).toLocaleDateString('en-ZA')}</td>
                            <td className="py-2.5 text-[var(--ff-text-primary)] font-medium">{run.cutoffDate}</td>
                            <td className="py-2.5"><StatusBadge status={run.status} /></td>
                            <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">{run.entriesArchived.toLocaleString()}</td>
                            <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">{run.transactionsArchived.toLocaleString()}</td>
                            <td className="py-2.5 text-right text-[var(--ff-text-secondary)]">{(run.invoicesArchived + run.supplierInvoicesArchived).toLocaleString()}</td>
                            <td className="py-2.5 text-right text-[var(--ff-text-muted)]">{duration !== null ? `${duration}s` : '—'}</td>
                          </tr>
                        );
                      })}
                    </tbody>
                  </table>
                </div>
              )}
            </Section>
          </>
        )}

        {view === 'archived-data' && (
          <Section title="Archived Journal Entries (Read-Only)" icon={<Eye className="h-4 w-4" />}>
            <div className="flex flex-wrap gap-3 mb-6">
              {(['from', 'to'] as const).map((key) => (
                <div key={key}>
                  <label className="block text-xs text-[var(--ff-text-muted)] mb-1">Date {key === 'from' ? 'From' : 'To'}</label>
                  <input type="date"
                    value={key === 'from' ? archiveDateFrom : archiveDateTo}
                    onChange={(e) => { if (key === 'from') setArchiveDateFrom(e.target.value); else setArchiveDateTo(e.target.value); setArchivePage(0); }}
                    className="rounded-lg border border-[var(--ff-border)] bg-[var(--ff-bg-primary)] text-[var(--ff-text-primary)] px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-teal-500" />
                </div>
              ))}
              <div className="flex items-end">
                <button onClick={() => void loadArchivedData()} disabled={archivedLoading}
                  className="flex items-center gap-1.5 text-sm px-4 py-2 rounded-lg bg-teal-600 hover:bg-teal-700 text-white disabled:opacity-50 transition-colors">
                  {archivedLoading ? <Loader2 className="h-4 w-4 animate-spin" /> : null} Search
                </button>
              </div>
            </div>
            {archivedLoading ? (
              <div className="flex items-center gap-2 text-[var(--ff-text-muted)]"><Loader2 className="h-4 w-4 animate-spin" /> Loading archived data...</div>
            ) : archivedItems.length === 0 ? (
              <div className="flex items-center gap-2 text-[var(--ff-text-muted)]"><AlertTriangle className="h-4 w-4" /> No archived journal entries found for the selected date range.</div>
            ) : (
              <>
                <p className="text-xs text-[var(--ff-text-muted)] mb-3">
                  Showing {archivePage * ARCHIVE_LIMIT + 1}–{Math.min((archivePage + 1) * ARCHIVE_LIMIT, archivedTotal)} of {archivedTotal.toLocaleString()} archived entries
                </p>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-[var(--ff-border)]">
                        {['Entry #', 'Date', 'Description', 'Source', 'Status'].map(h => (
                          <th key={h} className="pb-2 text-left font-semibold text-[var(--ff-text-muted)]">{h}</th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-[var(--ff-border)]">
                      {archivedItems.map((item) => (
                        <tr key={item.id}>
                          <td className="py-2.5 font-mono text-xs text-[var(--ff-text-secondary)]">{item.entryNumber ?? '—'}</td>
                          <td className="py-2.5 text-[var(--ff-text-primary)]">{item.entryDate}</td>
                          <td className="py-2.5 text-[var(--ff-text-secondary)] max-w-xs truncate">{item.description ?? '—'}</td>
                          <td className="py-2.5 text-[var(--ff-text-muted)] capitalize">{item.source ?? '—'}</td>
                          <td className="py-2.5"><StatusBadge status={item.status ?? 'unknown'} /></td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
                {archivedTotal > ARCHIVE_LIMIT && (
                  <div className="flex items-center justify-between mt-4 pt-4 border-t border-[var(--ff-border)]">
                    <button onClick={() => setArchivePage((p) => Math.max(0, p - 1))} disabled={archivePage === 0}
                      className="text-sm px-3 py-1.5 rounded-lg border border-[var(--ff-border)] disabled:opacity-40 hover:bg-[var(--ff-bg-secondary)] transition-colors">Previous</button>
                    <span className="text-sm text-[var(--ff-text-muted)]">Page {archivePage + 1} of {Math.ceil(archivedTotal / ARCHIVE_LIMIT)}</span>
                    <button onClick={() => setArchivePage((p) => p + 1)} disabled={(archivePage + 1) * ARCHIVE_LIMIT >= archivedTotal}
                      className="text-sm px-3 py-1.5 rounded-lg border border-[var(--ff-border)] disabled:opacity-40 hover:bg-[var(--ff-bg-secondary)] transition-colors">Next</button>
                  </div>
                )}
              </>
            )}
          </Section>
        )}
      </div>

      {showConfirm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
          <div className="bg-[var(--ff-bg-primary)] rounded-xl border border-[var(--ff-border)] p-6 max-w-md w-full space-y-4 shadow-xl">
            <div className="flex items-start gap-3">
              <AlertTriangle className="h-6 w-6 text-red-500 flex-shrink-0 mt-0.5" />
              <div>
                <h3 className="text-base font-semibold text-[var(--ff-text-primary)]">Confirm Archive Operation</h3>
                <p className="text-sm text-[var(--ff-text-secondary)] mt-1">
                  This will permanently move all eligible records before <strong>{cutoffDate}</strong> to the archive tables. This operation cannot be undone from the UI.
                </p>
                {preview && <p className="text-sm text-[var(--ff-text-muted)] mt-2"><strong>{preview.totalRecords.toLocaleString()}</strong> total records will be archived.</p>}
              </div>
            </div>
            <div className="flex gap-3 justify-end pt-2">
              <button onClick={() => setShowConfirm(false)} className="text-sm px-4 py-2 rounded-lg border border-[var(--ff-border)] hover:bg-[var(--ff-bg-secondary)] text-[var(--ff-text-primary)] transition-colors">Cancel</button>
              <button onClick={() => void handleArchive()} className="text-sm px-4 py-2 rounded-lg bg-red-600 hover:bg-red-700 text-white transition-colors">Yes, Archive Now</button>
            </div>
          </div>
        </div>
      )}
    </AppLayout>
  );
}

